window.Q=window.Q||{};Q["m37_S3"]=[{"i":"S3-1-1-학개론-01","r":"S3","g":1,"c":1,"n":1,"s":"학개론","q":"부동산의 개념에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["경제적 개념의 부동산은 공간, 자연, 위치를 뜻한다.","민법상 부동산은 토지, 건물, 입목, 공장재단을 말한다.","광의의 부동산은 협의의 부동산에 준부동산을 포함한 개념이다.","준부동산은 공시방법이 없어도 부동산에 준하여 취급되는 동산이다.","복합부동산은 토지와 건물이 법률상 하나의 부동산으로 취급되는 상태를 말한다."],"a":[3],"L":"학1-1","o":"변형","x":{"한줄":"협의의 부동산은 토지와 그 정착물이고, 여기에 등기·등록으로 공시되는 준부동산을 더하면 광의의 부동산이 된다.","근거":[{"법령":"민법","조문":"제99조","원문":"①토지 및 그 정착물은 부동산이다.\n②부동산 이외의 물건은 동산이다."},{"이론":"부동산의 복합개념","내용":"법률적(물권) 개념은 협의·광의로, 경제적 개념은 자산·자본·생산요소·소비재·상품으로, 기술적(물리적) 개념은 공간·자연·위치·환경으로 나눈다."}],"선지":[{"번호":1,"판정":"틀림","설명":"공간·자연·위치·환경은 기술적(물리적) 개념이다. 경제적 개념은 자산·자본·생산요소·소비재·상품이다."},{"번호":2,"판정":"틀림","설명":"민법상 부동산은 토지와 그 정착물이다(민법 제99조제1항). 입목·공장재단은 별도 법률에 따라 공시되는 준부동산으로 구분한다."},{"번호":3,"판정":"옳음","설명":"광의의 부동산 = 협의의 부동산(토지+정착물) + 준부동산."},{"번호":4,"판정":"틀림","설명":"준부동산은 등기·등록 같은 공시방법을 갖추어야 부동산에 준하여 취급되는 동산(자동차, 선박, 항공기, 건설기계 등)과 입목·광업재단·공장재단이다."},{"번호":5,"판정":"틀림","설명":"복합부동산은 토지와 건물이 각각 독립된 거래 객체이면서 하나의 결합 상태로 활동 대상이 되는 것이다. 법률상으로는 토지와 건물이 별개의 부동산이다(민법 제99조)."}],"개념":[{"종류":"표","제목":"부동산의 복합개념","머리":["구분","내용","대표 용어"],"행":[["법률적 개념(협의)","토지 + 정착물","민법 제99조"],["법률적 개념(광의)","협의의 부동산 + 준부동산","입목, 공장재단, 광업재단, 등록 동산"],["경제적 개념","자산·자본·생산요소·소비재·상품","투자 대상, 가치 증식"],["기술적(물리적) 개념","공간·자연·위치·환경","토지의 물리적 속성"]]},{"종류":"비교","제목":"준부동산과 복합부동산","왼쪽":{"이름":"준부동산","항목":["부동산이 아니라 동산·재단","공시방법을 갖춤","자동차, 선박, 항공기, 건설기계, 입목, 광업재단, 공장재단"]},"오른쪽":{"이름":"복합부동산","항목":["토지와 건물이 각각 독립된 부동산","하나의 결합 상태로 거래되는 활동 대상","법률상 단일 부동산이 아님"]}}],"함정":"경제적 개념에 공간·위치를 넣은 1번을 고르기 쉽다. 공간·자연·위치는 기술적 개념이다. 5번의 복합부동산을 법률상 한 개의 부동산으로 보는 것도 흔한 오답이다."}},{"i":"S3-1-1-학개론-02","r":"S3","g":1,"c":1,"n":2,"s":"학개론","q":"토지는 사용하는 상황이나 관계에 따라 다양하게 불리는 바, 토지 관련 용어의 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["도시개발사업에 소요된 비용과 공공용지를 제외한 후 도시개발사업 전 토지의 위치ㆍ지목ㆍ면적 등을 고려하여 토지소유자에게 재분배하는 토지를 환지(換地)라 한다.","토지와 도로 등 경계사이의 경사진 부분의 토지를 법지(法地)라 한다.","고압송전선로 아래의 토지를 선하지(線下地)라 한다.","소유권이 인정되지 않는 바다와 육지 사이의 해변 토지를 포락지(浦落地)라 한다.","도시개발사업에 필요한 경비에 충당하기 위해 환지로 정하지 아니한 토지를 체비지(替費地)라 한다."],"a":[4],"L":"학1-2","o":"기출","x":{"한줄":"소유권이 인정되지 않는 바다와 육지 사이의 해변 토지는 빈지이고, 포락지는 지적공부에 등록된 토지가 물에 침식되어 수면 밑으로 잠긴 토지다.","근거":[{"법령":"도시개발법","조문":"제34조제1항","원문":"시행자는 도시개발사업에 필요한 경비에 충당하거나 규약ㆍ정관ㆍ시행규정 또는 실시계획으로 정하는 목적을 위하여 일정한 토지를 환지로 정하지 아니하고 보류지로 정할 수 있으며, 그 중 일부를 체비지로 정하여 도시개발사업에 필요한 경비에 충당할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"환지는 사업 후 토지소유자에게 재분배하는 토지다. 환지 계획은 도시개발법 제28조에 따라 작성한다."},{"번호":2,"판정":"옳음","설명":"법지는 소유는 인정되나 이용 가치가 낮은 경사진 부분이다."},{"번호":3,"판정":"옳음","설명":"선하지는 고압송전선로 아래 토지로 이용에 제한이 따른다."},{"번호":4,"판정":"틀림","설명":"소유권이 인정되지 않는 바다와 육지 사이 해변 토지는 빈지다. 포락지는 물에 침식되어 수면 밑으로 잠긴 지적공부 등록 토지다."},{"번호":5,"판정":"옳음","설명":"체비지는 보류지 중 사업 경비에 충당하려고 정한 토지다(도시개발법 제34조제1항)."}],"개념":[{"종류":"표","제목":"이용 상태·관계에 따른 토지 용어","머리":["용어","뜻"],"행":[["나지","건물 등 정착물이 없고 지상권 등 사법상 권리가 설정되지 않은 토지"],["건부지","건물 등의 부지로 이용 중인 토지"],["공지","건폐율·용적률 제한으로 건축하지 않고 남겨둔 부분의 토지"],["법지","소유는 인정되나 이용 가치가 낮은 경사진 부분의 토지"],["빈지","소유권이 인정되지 않는 바다와 육지 사이의 해변 토지"],["포락지","지적공부에 등록된 토지가 물에 침식되어 수면 밑으로 잠긴 토지"],["선하지","고압송전선로 아래의 토지"]]},{"종류":"표","제목":"단위·전환·사업과 관련된 용어","머리":["용어","뜻"],"행":[["필지","법률적(지적공부상) 토지 등록 단위"],["획지","경제적 단위로 가격수준이 비슷한 일단의 토지"],["후보지","용도적 지역(택지·농지·임지) 간 전환 과정에 있는 토지"],["이행지","한 용도적 지역 안에서 세분된 지역 간 전환 과정에 있는 토지"],["환지","도시개발사업 후 토지소유자에게 재분배하는 토지"],["보류지","환지로 정하지 않고 남겨두는 토지(체비지·공공시설 용지)"],["체비지","보류지 중 사업 경비에 충당하기 위한 토지"]]}],"함정":"빈지와 포락지를 바꿔 외우면 4번을 놓친다. 소유권 부정은 빈지, 침식으로 잠김은 포락지다."}},{"i":"S3-1-1-학개론-03","r":"S3","g":1,"c":1,"n":3,"s":"학개론","q":"토지의 특성에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["부동성으로 인해 외부효과가 발생하지 않는다.","개별성으로 인해 거래사례를 통한 지가 산정이 쉽다.","부증성으로 인해 토지의 물리적 공급은 단기적으로 탄력적이다.","용도의 다양성으로 인해 토지의 경제적 공급은 증가할 수 있다.","영속성으로 인해 부동산 활동에서 토지는 감가상각을 고려하여야 한다."],"a":[4],"L":"학1-3","o":"기출","x":{"한줄":"용도의 다양성 때문에 용도 전환이 가능해 물리적 공급이 고정이어도 특정 용도의 경제적 공급은 늘 수 있다.","근거":[{"이론":"토지의 특성","내용":"자연적 특성은 부동성·영속성·부증성·개별성이고, 인문적 특성은 용도의 다양성·합병분할의 가능성·위치의 가변성이다. 부증성은 물리적 공급을 비탄력으로, 영속성은 감가상각 배제와 가치보존을 낳는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"부동성 때문에 인접 토지에 영향이 미치는 외부효과가 발생한다."},{"번호":2,"판정":"틀림","설명":"개별성 때문에 같은 토지가 없어 거래사례 비교가 어렵고 지가 산정이 쉽지 않다."},{"번호":3,"판정":"틀림","설명":"부증성 때문에 토지의 물리적 공급은 단기적으로 비탄력적(고정)이다."},{"번호":4,"판정":"옳음","설명":"용도의 다양성으로 용도 전환이 가능해 경제적 공급은 증가할 수 있다."},{"번호":5,"판정":"틀림","설명":"영속성 때문에 토지는 소모되지 않아 감가상각을 하지 않는다. 감가상각은 건물에 적용한다."}],"개념":[{"종류":"표","제목":"토지의 특성과 파생현상","머리":["특성","구분","파생현상"],"행":[["부동성","자연적","지역분석, 외부효과, 임장활동, 지방세(재산세)"],["영속성","자연적","감가상각 배제, 가치보존, 장기투자, 재생산 이론"],["부증성","자연적","물리적 공급 비탄력, 지대·지가 발생, 집약적 이용"],["개별성","자연적","부동산 가격의 개별화, 비교 곤란, 일물일가 불성립"],["용도의 다양성","인문적","경제적 공급 가능, 최유효이용"],["합병·분할의 가능성","인문적","토지 이용 규모 조정"],["위치의 가변성","인문적","사회·경제·행정적 위치 변화"]]}],"함정":"부증성은 '물리적' 공급이 고정이라는 뜻이다. 경제적 공급과 구분하지 못하면 3번과 4번에서 갈린다."}},{"i":"S3-1-1-학개론-04","r":"S3","g":1,"c":1,"n":4,"s":"학개론","q":"수요와 공급이 동시에 변화할 경우, 균형가격과 균형량에 관한 설명으로 옳은 것은? (단, 수요곡선은 우하향, 공급곡선은 우상향, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["수요와 공급이 증가하는 경우, 수요의 증가폭이 공급의 증가폭보다 크다면 균형가격은 상승하고 균형량은 감소한다.","수요와 공급이 감소하는 경우, 수요의 감소폭이 공급의 감소폭보다 작다면 균형가격은 상승하고 균형량은 증가한다.","수요와 공급이 감소하는 경우, 수요의 감소폭과 공급의 감소폭이 같다면 균형가격은 불변이고 균형량은 증가한다.","수요는 증가하고 공급이 감소하는 경우, 수요의 증가폭이 공급의 감소폭보다 작다면 균형가격은 상승하고 균형량은 증가한다.","수요는 감소하고 공급이 증가하는 경우, 수요의 감소폭이 공급의 증가폭보다 작다면 균형가격은 하락하고 균형량은 증가한다."],"a":[5],"L":"학2-1","o":"기출","x":{"한줄":"수요 감소폭이 공급 증가폭보다 작으면 공급이 더 크게 늘어 가격은 하락하고, 수요가 줄어도 공급이 더 많이 늘어 균형량은 증가한다.","근거":[{"이론":"수요·공급의 동시 변화","내용":"수요와 공급이 같은 방향으로 변하면 균형량의 변화 방향은 확정되고(증가는 증가, 감소는 감소), 가격은 변화폭 비교로 정해진다. 반대 방향으로 변하면 가격 방향이 확정되고 균형량은 변화폭 비교로 정해진다."}],"선지":[{"번호":1,"판정":"틀림","설명":"둘 다 증가하면 균형량은 반드시 증가한다. 수요 증가폭이 더 크면 가격은 상승하고 균형량은 증가한다."},{"번호":2,"판정":"틀림","설명":"둘 다 감소하면 균형량은 반드시 감소한다. 수요 감소폭이 더 작으면 공급이 더 크게 줄어 가격은 상승하고 균형량은 감소한다."},{"번호":3,"판정":"틀림","설명":"둘 다 감소하면 균형량은 감소한다. 균형량이 증가한다는 부분이 틀리다."},{"번호":4,"판정":"틀림","설명":"수요 증가, 공급 감소이면 가격은 상승한다. 수요 증가폭이 공급 감소폭보다 작으면 균형량은 감소한다."},{"번호":5,"판정":"옳음","설명":"수요 감소, 공급 증가이면 가격은 하락한다. 수요 감소폭이 공급 증가폭보다 작으면 균형량은 증가한다."}],"개념":[{"종류":"표","제목":"수요·공급 동시 변화의 결과","머리":["수요","공급","균형가격","균형량"],"행":[["증가","증가","수요폭이 크면 상승, 공급폭이 크면 하락","증가"],["감소","감소","수요폭이 크면 하락, 공급폭이 크면 상승","감소"],["증가","감소","상승","수요폭이 크면 증가, 공급폭이 크면 감소"],["감소","증가","하락","수요폭이 크면 감소, 공급폭이 크면 증가"]]}],"함정":"같은 방향으로 변할 때는 균형량이, 반대 방향으로 변할 때는 균형가격이 먼저 확정된다. 확정되는 쪽이 아닌 변수만 폭을 비교한다. 1·2·3번은 확정된 균형량을 거꾸로 적었다."}},{"i":"S3-1-1-학개론-05","r":"S3","g":1,"c":1,"n":5,"s":"학개론","q":"해당 부동산시장의 수요곡선을 우측(우상향)으로 이동하게 하는 수요변화의 요인에 해당하는 것은? (단, 수요곡선은 우하향하고, 해당 부동산은 정상재이며, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["대출금리의 상승","보완재 가격의 하락","대체재 수요량의 증가","해당 부동산 가격의 상승","해당 부동산 선호도의 감소"],"a":[2],"L":"학2-1","o":"기출","x":{"한줄":"보완재 가격이 하락하면 보완재 수요가 늘면서 함께 쓰는 해당 부동산의 수요도 늘어 수요곡선이 우측으로 이동한다.","근거":[{"이론":"수요변화의 요인","내용":"해당 재화의 가격 변화는 수요곡선 위의 이동(수요량 변화)이고, 소득·선호·관련재 가격·금리·인구·기대 등의 변화는 수요곡선 자체의 이동(수요 변화)이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"대출금리가 상승하면 구입 부담이 늘어 수요가 감소하고 수요곡선이 좌측으로 이동한다."},{"번호":2,"판정":"옳음","설명":"보완재 가격이 하락하면 보완재 수요가 늘고, 함께 소비하는 해당 부동산의 수요도 증가한다."},{"번호":3,"판정":"틀림","설명":"대체재 수요량의 증가는 대체재 가격 하락 같은 원인에서 나올 수 있고, 이 경우 해당 부동산 수요는 감소한다. 수요 증가 요인으로 확정할 수 없다."},{"번호":4,"판정":"틀림","설명":"해당 부동산 가격의 상승은 수요곡선 위에서 수요량이 줄어드는 이동이다."},{"번호":5,"판정":"틀림","설명":"선호도가 감소하면 수요곡선은 좌측으로 이동한다."}],"개념":[{"종류":"표","제목":"수요곡선을 이동시키는 요인","머리":["요인","수요 증가(우측 이동)","수요 감소(좌측 이동)"],"행":[["소득(정상재)","소득 증가","소득 감소"],["대체재 가격","상승","하락"],["보완재 가격","하락","상승"],["대출금리","하락","상승"],["선호도","증가","감소"],["인구·가구 수","증가","감소"],["가격 상승 기대","있음(투자·투기 수요)","하락 기대"]]},{"종류":"비교","제목":"수요량의 변화와 수요의 변화","왼쪽":{"이름":"수요량의 변화","항목":["해당 재화 가격 변화가 원인","같은 수요곡선 위의 점 이동"]},"오른쪽":{"이름":"수요의 변화","항목":["가격 이외 요인이 원인","수요곡선 자체가 좌·우로 이동"]}}],"함정":"해당 부동산 가격 변화(4번)를 수요 변화로 고르기 쉽다. 자기 가격은 수요량 변화이므로 곡선이 움직이지 않는다."}},{"i":"S3-1-1-학개론-06","r":"S3","g":1,"c":1,"n":6,"s":"학개론","q":"부동산의 수요와 공급이 동시에 변화할 때, 균형가격이 상승하고 균형거래량이 감소하는 경우는? (단, X축은 수량, Y축은 가격, 수요곡선은 우하향, 공급곡선은 우상향, 수요곡선과 공급곡선 기울기의 절댓값은 1이며, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["수요의 증가폭이 공급의 증가폭보다 클 경우","수요의 감소폭이 공급의 감소폭보다 클 경우","수요의 증가폭이 공급의 감소폭보다 작을 경우","수요의 감소폭이 공급의 증가폭보다 작을 경우","수요의 증가폭이 공급의 증가폭보다 작을 경우"],"a":[3],"L":"학2-1","o":"기출","x":{"한줄":"수요 증가와 공급 감소가 겹치면 가격은 반드시 오르고, 수요 증가폭이 공급 감소폭보다 작으면 균형량이 줄어든다.","근거":[{"이론":"수요·공급 동시 변화","내용":"기울기 절댓값이 1이면 수요 이동폭을 d, 공급 이동폭을 s라 할 때 수요 증가·공급 감소에서 가격 변화는 (d+s)/2로 항상 상승하고 수량 변화는 (d−s)/2다."}],"선지":[{"번호":1,"판정":"틀림","설명":"수요와 공급이 모두 증가하면 균형량은 증가한다. 수요 증가폭이 더 클 때 가격은 상승하나 균형량 감소가 아니다."},{"번호":2,"판정":"틀림","설명":"둘 다 감소하면 균형량이 감소한다. 수요 감소폭이 더 크면 가격은 하락한다."},{"번호":3,"판정":"옳음","설명":"수요 증가·공급 감소이면 가격은 상승하고, 수요 증가폭이 공급 감소폭보다 작으면 균형량은 감소한다."},{"번호":4,"판정":"틀림","설명":"수요 감소, 공급 증가이면 가격이 하락한다."},{"번호":5,"판정":"틀림","설명":"둘 다 증가하고 수요 증가폭이 더 작으면 가격은 하락하고 균형량은 증가한다."}],"개념":[{"종류":"계산","제목":"수요 증가·공급 감소의 수치 확인(기울기 절댓값 1)","단계":[{"설명":"처음 수요와 공급을 Qd = 100 − P, Qs = P로 놓는다","식":"100 − P = P","값":"P = 50, Q = 50"},{"설명":"수요 10 증가, 공급 20 감소(수요 증가폭 < 공급 감소폭)","식":"Qd = 110 − P,  Qs = P − 20","값":"새 식"},{"설명":"새 균형을 구한다","식":"110 − P = P − 20","값":"P = 65 (15 상승)"},{"설명":"균형량을 구한다","식":"Q = 65 − 20","값":"Q = 45 (5 감소)"}]},{"종류":"표","제목":"동시 변화 결과 정리","머리":["수요","공급","가격","균형량"],"행":[["증가","감소","상승","수요폭 < 공급폭이면 감소"],["감소","증가","하락","수요폭 < 공급폭이면 증가"],["증가","증가","수요폭 > 공급폭이면 상승","증가"],["감소","감소","수요폭 > 공급폭이면 하락","감소"]]}],"함정":"1번과 5번은 둘 다 증가하는데 균형량 감소를 고른 경우다. 같은 방향 변화에서는 균형량이 폭에 상관없이 확정된다."}},{"i":"S3-1-1-학개론-07","r":"S3","g":1,"c":1,"n":7,"s":"학개론","q":"어느 지역 아파트시장에서 수요의 가격탄력성이 1.6 이다. 아파트가격이 5% 하락할 때 수요량의 변화는? (단, 수요곡선은 우하향, 수요의 가격탄력성은 절댓값이며, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["4% 증가","4% 하락","6% 증가","6% 하락","8% 증가"],"a":[5],"L":"학2-2","o":"기출","x":{"한줄":"탄력성 1.6 × 가격 하락률 5% = 8%이고, 수요곡선이 우하향이므로 가격이 내리면 수요량은 8% 증가한다.","근거":[{"이론":"수요의 가격탄력성","내용":"수요의 가격탄력성 = 수요량 변화율(%) ÷ 가격 변화율(%) (절댓값). 수요법칙에 따라 가격과 수요량은 반대 방향으로 움직인다."}],"선지":[{"번호":1,"판정":"-","설명":"4%는 1.6이 아닌 0.8을 곱해야 나오는 값이다."},{"번호":2,"판정":"-","설명":"수요량 하락은 가격 하락과 같은 방향이라 수요법칙에 어긋난다."},{"번호":3,"판정":"-","설명":"6%는 탄력성 1.2에 해당한다."},{"번호":4,"판정":"-","설명":"수요량 하락은 수요법칙에 어긋난다."},{"번호":5,"판정":"-","설명":"1.6 × 5% = 8%. 가격 하락에 수요량은 증가하므로 8% 증가."}],"개념":[{"종류":"계산","제목":"수요량 변화율 구하기","단계":[{"설명":"정의식에서 수요량 변화율을 정리한다","식":"수요량 변화율 = 탄력성 × 가격 변화율","값":"공식"},{"설명":"대입한다","식":"1.6 × 5%","값":"8%"},{"설명":"방향을 정한다(가격 하락 → 수요량 증가)","식":"가격 ↓, 수요량 ↑","값":"8% 증가"}]},{"종류":"표","제목":"가격탄력성의 값과 해석","머리":["탄력성","명칭","가격 5% 하락 시 수요량"],"행":[["0","완전비탄력","변화 없음"],["0.8","비탄력","4% 증가"],["1","단위탄력","5% 증가"],["1.6","탄력","8% 증가"],["∞","완전탄력","무한히 증가"]]}],"함정":"방향을 놓치면 8% 하락을 고르게 된다. 가격이 내리면 수요량은 늘어난다. 6%는 1.2를 곱한 값, 4%는 0.8을 곱한 값이다."}},{"i":"S3-1-1-학개론-08","r":"S3","g":1,"c":1,"n":8,"s":"학개론","q":"수요의 가격탄력성에 관한 설명으로 옳은 것은? (단, 수요의 가격탄력성은 절댓값이며, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["대체재가 풍부하고 관찰기간이 길수록 수요의 가격탄력성은 커진다.","수요의 가격탄력성이 1보다 크면 가격이 상승할 때 총수입(임대료 수입)은 증가한다.","수요의 가격탄력성이 비탄력적이면 가격을 인하할 때 총수입이 증가한다.","수요곡선이 수직선이면 수요의 가격탄력성은 완전탄력적이다.","수요의 가격탄력성은 가격 변화율을 수요량 변화율로 나눈 값이다."],"a":[1],"L":"학2-2","o":"변형","x":{"한줄":"대체재가 많을수록, 관찰기간이 길수록 소비자가 가격 변화에 맞춰 수요량을 조정할 여지가 커 탄력성이 커진다.","근거":[{"이론":"수요의 가격탄력성 결정요인과 총수입","내용":"대체재의 존재·용도의 다양성·관찰기간·재화 가격이 소득에서 차지하는 비중이 클수록 탄력적이다. 탄력적이면 가격과 총수입이 반대로, 비탄력적이면 같은 방향으로 움직인다."}],"선지":[{"번호":1,"판정":"옳음","설명":"대체재가 많고 관찰기간이 길수록 수요량 조정이 쉬워 탄력성이 커진다."},{"번호":2,"판정":"틀림","설명":"탄력적(ε>1)이면 가격 상승 시 수요량이 더 크게 줄어 총수입이 감소한다."},{"번호":3,"판정":"틀림","설명":"비탄력적(ε<1)이면 가격 인하로 수요량이 조금만 늘어 총수입이 감소한다."},{"번호":4,"판정":"틀림","설명":"수직선 수요곡선은 가격이 변해도 수요량이 불변이므로 완전비탄력(ε=0)이다."},{"번호":5,"판정":"틀림","설명":"탄력성은 수요량 변화율을 가격 변화율로 나눈 값이다."}],"개념":[{"종류":"표","제목":"가격탄력성과 총수입","머리":["탄력성","가격 상승 시","가격 하락 시"],"행":[["탄력적(ε>1)","총수입 감소","총수입 증가"],["단위탄력(ε=1)","총수입 불변","총수입 불변"],["비탄력적(ε<1)","총수입 증가","총수입 감소"],["완전비탄력(ε=0)","총수입 증가(수요량 불변)","총수입 감소(수요량 불변)"]]},{"종류":"표","제목":"탄력성이 커지는 조건","머리":["조건","탄력성"],"행":[["대체재가 많음","커짐"],["용도가 다양함","커짐"],["관찰기간이 김","커짐"],["소득에서 차지하는 비중이 큼(사치재)","커짐"],["필수재","작아짐"]]}],"함정":"탄력성 정의식의 분자·분모를 바꾼 5번, 총수입의 방향을 반대로 외운 2번과 3번이 흔한 오답이다."}},{"i":"S3-1-1-학개론-09","r":"S3","g":1,"c":1,"n":9,"s":"학개론","q":"거미집모형에 관한 설명으로 옳은 것은? (단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["수요의 가격탄력성이 공급의 가격탄력성보다 크면 발산형이다.","가격이 변동하면 수요와 공급은 모두 즉각적으로 반응한다는 가정을 전제하고 있다.","수요곡선의 기울기 절댓값이 공급곡선의 기울기 절댓값보다 작으면 수렴형이다.","수요와 공급의 동시적 관계로 가정하여 균형의 변화를 정태적으로 분석한 모형이다.","공급자는 현재와 미래의 가격을 동시에 고려해 미래의 공급을 결정한다는 가정을 전제하고 있다."],"a":[3],"L":"학2-3","o":"기출","x":{"한줄":"가격을 세로축에 놓을 때 수요곡선이 공급곡선보다 완만하면(수요의 기울기 절댓값이 더 작으면) 가격 변동폭이 시간이 갈수록 줄어 수렴한다.","근거":[{"이론":"거미집모형(에치켈)","내용":"수요는 당기 가격에 즉각 반응하고 공급은 한 기간 시차를 두고 전기 가격에 반응한다. 수요의 가격탄력성이 공급의 가격탄력성보다 크면(|수요 기울기| < |공급 기울기|) 수렴, 작으면 발산, 같으면 순환한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"수요의 가격탄력성이 공급보다 크면 수렴형이다."},{"번호":2,"판정":"틀림","설명":"수요는 당기 가격에 즉각 반응하나 공급은 생산 시차 때문에 전기 가격에 반응한다."},{"번호":3,"판정":"옳음","설명":"수요곡선 기울기 절댓값이 공급곡선 기울기 절댓값보다 작으면(탄력성은 수요가 더 큼) 수렴형이다."},{"번호":4,"판정":"틀림","설명":"시차를 두고 균형이 변해 가는 과정을 보는 동태적 분석 모형이다."},{"번호":5,"판정":"틀림","설명":"공급자는 현재(전기) 가격이 계속될 것으로 보고 공급을 결정하며 미래 가격은 고려하지 않는다."}],"개념":[{"종류":"표","제목":"거미집모형의 형태(가격 Y축 기준)","머리":["구분","탄력성 비교","기울기 절댓값 비교","결과"],"행":[["수렴형","수요 > 공급","수요 < 공급","균형으로 접근"],["발산형","수요 < 공급","수요 > 공급","균형에서 멀어짐"],["순환형","수요 = 공급","수요 = 공급","일정 폭으로 반복"]]},{"종류":"표","제목":"거미집모형의 가정","머리":["항목","내용"],"행":[["수요","당기 가격에 즉각 반응"],["공급","전기 가격에 반응(생산 시차)"],["공급자 예상","현재 가격이 미래에도 계속된다고 가정"],["분석 성격","동태적 분석"],["적용 시장","공급 시차가 긴 농산물·부동산 등"]]}],"함정":"탄력성과 기울기는 크고 작음이 반대다. 탄력성은 수요가 클 때, 기울기는 수요가 작을 때 수렴한다. 이 대응이 1번과 3번의 갈림길이다."}},{"i":"S3-1-1-학개론-10","r":"S3","g":1,"c":1,"n":10,"s":"학개론","q":"부동산시장과 효율적 시장에 관한 설명으로 틀린 것은? (단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["약성 효율적 시장에서는 과거의 가격 정보를 이용한 추세분석으로 초과이윤을 얻을 수 없다.","강성 효율적 시장에서는 비공개 내부정보를 이용하면 초과이윤을 얻을 수 있다.","준강성 효율적 시장에서는 공표된 정보를 분석해도 초과이윤을 얻을 수 없으나 내부정보로는 얻을 수 있다.","할당 효율적 시장은 정보를 얻는 데 드는 비용과 그 정보로 얻는 초과이윤이 같은 시장이다.","부동산의 정보가치는 정보를 알 때의 기대수익과 모를 때의 기대수익의 차이로 나타낼 수 있다."],"a":[2],"L":"학3-1","o":"변형","x":{"한줄":"강성 효율적 시장은 공표·비공표 정보가 모두 가격에 반영되어 있어 내부정보로도 초과이윤을 얻을 수 없다.","근거":[{"이론":"효율적 시장가설(파마)","내용":"약성은 과거 정보, 준강성은 공표된 정보, 강성은 공표·비공표 정보 모두가 가격에 반영된 시장이다. 할당 효율적 시장은 정보비용과 초과이윤이 같아 정보로 순이익을 얻을 수 없는 시장이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"과거 가격 정보는 이미 가격에 반영되어 추세분석(기술적 분석)이 초과이윤을 주지 못한다."},{"번호":2,"판정":"틀림","설명":"강성 효율적 시장은 내부정보까지 반영되어 있어 어떤 정보로도 초과이윤을 얻을 수 없다."},{"번호":3,"판정":"옳음","설명":"준강성은 공표 정보까지만 반영되므로 공표 정보 분석(기본적 분석)으로는 초과이윤이 없고 내부정보로는 가능하다."},{"번호":4,"판정":"옳음","설명":"할당 효율적 시장은 정보비용과 정보로 얻는 초과이윤이 같다."},{"번호":5,"판정":"옳음","설명":"정보의 현재가치는 정보를 알 때와 모를 때의 기대수익(현재가치) 차이다."}],"개념":[{"종류":"표","제목":"효율적 시장의 세 단계","머리":["구분","가격에 반영된 정보","초과이윤 가능한 정보"],"행":[["약성","과거 정보","공표된 정보, 내부정보"],["준강성","과거 + 공표된 정보","내부정보"],["강성","과거 + 공표 + 비공표(내부)정보","없음"]]},{"종류":"표","제목":"부동산시장의 특성과 효율성","머리":["항목","내용"],"행":[["시장 성격","불완전경쟁, 개별성으로 인한 비조직적 시장"],["정보","비대칭성·비공개성이 커 왜곡 가능"],["거래비용","일반 재화보다 많이 듦"],["할당효율","정보비용 = 초과이윤이면 할당 효율적"],["정보의 현재가치","알 때 기대수익 − 모를 때 기대수익"]]}],"함정":"강성에서 내부정보를 쓸 수 있다는 2번을 옳게 읽기 쉽다. 내부정보로 초과이윤이 가능한 단계는 준강성까지다(약성·준강성)."}},{"i":"S3-1-1-학개론-11","r":"S3","g":1,"c":1,"n":11,"s":"학개론","q":"지대이론에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["리카도는 토지의 비옥도(생산성) 차이로 우등지에 차액지대가 생기며, 한계지(최열등지)에는 지대가 발생하지 않는다고 보았다.","마르크스의 절대지대는 토지의 비옥도 차이 때문에 발생한다.","마샬의 준지대는 인간이 만든 고정 설비에서 장기에도 계속 발생하는 영구적 성격의 잉여다.","경제지대는 토지의 공급이 완전탄력적일수록 커진다.","알론소의 입찰지대는 토지의 위치와 무관하게 정해지며 도심에서 멀어질수록 높아진다."],"a":[1],"L":"학3-3","o":"변형","x":{"한줄":"리카도의 차액지대는 비옥도·위치 차이로 우등지가 얻는 초과수익이며 한계지는 지대가 0이다.","근거":[{"이론":"지대이론","내용":"리카도는 곡물 가격이 한계지의 생산비로 정해져 우등지에 차액지대가 생긴다고 보았다. 마르크스의 절대지대는 소유 자체에서, 마샬의 준지대는 단기 고정 설비에서, 경제지대는 요소수입 중 전용수입을 초과한 잉여에서 나온다. 알론소는 도심에 가까울수록 높은 입찰지대를 설명했다."}],"선지":[{"번호":1,"판정":"옳음","설명":"리카도의 차액지대는 비옥도 차이로 생기며 한계지는 지대가 없다."},{"번호":2,"판정":"틀림","설명":"비옥도 차이로 생기는 지대는 차액지대다. 절대지대는 토지의 소유 자체에서 발생하는 최열등지에도 있는 지대다."},{"번호":3,"판정":"틀림","설명":"준지대는 단기에 공급이 고정된 설비 등에서 생기는 일시적 잉여다."},{"번호":4,"판정":"틀림","설명":"경제지대는 공급이 비탄력적일수록 커지고, 공급이 완전비탄력(수직)이면 요소수입 전체가 경제지대다."},{"번호":5,"판정":"틀림","설명":"알론소의 입찰지대는 위치에 따라 정해지며 도심에서 멀어질수록 낮아진다(지대곡선 우하향)."}],"개념":[{"종류":"표","제목":"지대이론 비교","머리":["이론","발생 원인","핵심"],"행":[["리카도 차액지대","비옥도·위치 차이","한계지에는 지대 없음, 곡물가격 → 지대"],["마르크스 절대지대","토지 소유 자체(독점)","최열등지에도 발생, 생산성과 무관"],["마샬 준지대","인공 고정설비의 단기 잉여","일시적, 단기에만 발생"],["경제지대(파레토)","요소수입 − 전용수입","공급이 비탄력적일수록 큼"],["튀넨 위치지대","시장까지의 거리(운송비 절약)","고립국 동심원 토지이용"],["알론소 입찰지대","지불할 용의가 있는 최대 금액","도심에서 멀어지면 낮아짐"]]},{"종류":"비교","제목":"차액지대와 절대지대","왼쪽":{"이름":"차액지대(리카도)","항목":["비옥도·위치의 차이","한계지 지대 0","지대가 곡물가격을 결정하지 않음"]},"오른쪽":{"이름":"절대지대(마르크스)","항목":["토지 소유의 독점","최열등지도 지대 발생","생산성과 무관"]}}],"함정":"차액지대와 절대지대의 발생 원인을 바꾸는 2번이 가장 흔하다. 경제지대는 공급이 비탄력적일수록 커진다는 방향도 헷갈린다."}},{"i":"S3-1-1-학개론-12","r":"S3","g":1,"c":1,"n":12,"s":"학개론","q":"도시공간구조이론 및 입지이론에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["버제스(E. Burgess)의 동심원이론에서 통근자지대는 가장 외곽에 위치한다.","호이트(H. Hoyt)의 선형이론에 따르면, 도시공간구조의 성장과 분화는 점이지대를 향해 직선으로 확대되면서 나타난다.","해리스(C. Harris)와 울만(E. Ullman)의 다핵심이론에는 중심업무지구와 점이지대가 존재하지 않는다.","뢰쉬(A. Lösch)의 최대수요이론은 운송비와 집적이익을 고려한 특정 사업의 팔각형 상권체계 과정을 보여준다.","레일리(W. Reilly)의 소매인력법칙은 특정 점포가 최대이익을 확보하기 위해 어떤 장소에 입지하는가에 대한 8원칙을 제시한다."],"a":[1],"L":"학3-3","o":"기출","x":{"한줄":"버제스 동심원이론은 중심업무지대에서 바깥으로 점이지대, 노동자주거지대, 중산층주거지대, 통근자지대 순이어서 통근자지대가 가장 바깥이다.","근거":[{"이론":"도시공간구조이론","내용":"버제스 동심원(중심업무→점이→노동자주거→중산층주거→통근자), 호이트 선형(교통망 축 따라 부채꼴 확대), 해리스·울만 다핵심(여러 핵이 독자 형성)."}],"선지":[{"번호":1,"판정":"옳음","설명":"동심원이론의 5개 지대 중 통근자지대가 가장 외곽이다."},{"번호":2,"판정":"틀림","설명":"호이트는 도시가 교통망 축을 따라 부채꼴(선형)로 확대된다고 보았다. 점이지대를 향한 확대가 아니다."},{"번호":3,"판정":"틀림","설명":"다핵심이론에도 중심업무지구(CBD)와 점이지대 등이 핵의 하나로 존재한다."},{"번호":4,"판정":"틀림","설명":"뢰쉬의 최대수요이론은 수요 측면에서 시장구역이 육각형으로 형성된다고 보며, 운송비·집적이익 중심의 설명이 아니다."},{"번호":5,"판정":"틀림","설명":"점포 입지의 8원칙은 넬슨의 소매입지이론이다. 레일리는 두 도시의 상권 경계를 설명했다."}],"개념":[{"종류":"표","제목":"도시공간구조 3대 이론","머리":["이론","학자","구조"],"행":[["동심원이론","버제스","중심업무 → 점이 → 노동자주거 → 중산층주거 → 통근자"],["선형(扇形)이론","호이트","교통망 축을 따라 부채꼴로 확대, 고급주거 지역이 한 방향으로 확대"],["다핵심이론","해리스·울만","CBD 외에 여러 핵이 독립적으로 형성"]]},{"종류":"표","제목":"입지이론 구분","머리":["이론","학자","핵심"],"행":[["최소비용","베버","운송비·노동비·집적이익 최소 지점"],["최대수요","뢰쉬","수요 극대화, 육각형 시장구역"],["중심지","크리스탈러","재화의 도달범위·최소요구범위, 육각형 계층"],["소매인력","레일리","두 도시 상권 경계 (인구에 비례, 거리 제곱에 반비례)"],["소매입지 8원칙","넬슨","점포 입지 원칙(고객 흡인력, 접근성 등)"]]}],"함정":"다핵심이론에 CBD가 없다고 보는 3번과, 8원칙을 레일리 것으로 외운 5번이 흔한 오답이다. 8원칙은 넬슨이다."}},{"i":"S3-1-1-학개론-13","r":"S3","g":1,"c":1,"n":13,"s":"학개론","q":"허프(D. Huff)모형에 관한 설명으로 틀린 것은? (단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["소비자가 특정 점포를 이용할 확률을 점포 규모, 거리, 경쟁점포의 영향으로 추정하는 확률모형이다.","점포의 면적이 클수록, 소비자와의 거리가 가까울수록 해당 점포의 이용확률은 높아진다.","경쟁점포의 면적이 커지면 다른 조건이 같을 때 해당 점포의 이용확률은 낮아진다.","교통조건이 개선되면 공간(거리)마찰계수는 커진다.","일상용품점은 전문품점보다 공간(거리)마찰계수가 크다."],"a":[4],"L":"학3-4","o":"변형","x":{"한줄":"교통조건이 좋아지면 거리가 이용에 주는 부담이 줄어 공간마찰계수는 작아진다.","근거":[{"이론":"허프모형","내용":"i 점포 이용확률 = (S_i ÷ D_i^λ) ÷ Σ(S_j ÷ D_j^λ). S는 점포 면적, D는 거리, λ는 공간(거리)마찰계수로 교통조건과 상품 특성에 따라 달라지며 먼저 정해야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"허프모형은 소비자의 점포 이용확률을 구하는 확률모형이다."},{"번호":2,"판정":"옳음","설명":"분자가 S/D^λ이므로 면적이 클수록, 거리가 가까울수록 확률이 커진다."},{"번호":3,"판정":"옳음","설명":"경쟁점포 면적이 커지면 분모가 커져 해당 점포 확률이 낮아진다."},{"번호":4,"판정":"틀림","설명":"교통조건이 좋아지면 거리 저항이 줄어 마찰계수가 작아지고, 교통조건이 나쁘면 커진다."},{"번호":5,"판정":"옳음","설명":"일상용품은 가까운 점포를 이용하므로 거리에 민감해 마찰계수가 크고, 전문품은 먼 거리도 감수해 작다."}],"개념":[{"종류":"계산","제목":"허프모형 이용확률 계산 예","단계":[{"설명":"A: 면적 100, 거리 2 / B: 면적 200, 거리 4 / 마찰계수 λ=2","식":"S ÷ D^λ","값":"A=100÷4=25, B=200÷16=12.5"},{"설명":"합계를 구한다","식":"25 + 12.5","값":"37.5"},{"설명":"A점포 이용확률","식":"25 ÷ 37.5","값":"약 66.7% (2/3)"},{"설명":"B점포 이용확률","식":"12.5 ÷ 37.5","값":"약 33.3% (1/3)"}]},{"종류":"표","제목":"공간(거리)마찰계수","머리":["상황","마찰계수","이유"],"행":[["교통조건 좋음","작음","거리 저항 감소"],["교통조건 나쁨","큼","거리 저항 증가"],["일상용품점","큼","가까운 점포 이용"],["전문품점","작음","먼 거리도 감수"]]}],"함정":"교통조건과 마찰계수의 방향을 반대로 외우면 틀린다. 교통이 좋아지면 거리 부담이 줄어 계수가 작아진다."}},{"i":"S3-1-1-학개론-14","r":"S3","g":1,"c":1,"n":14,"s":"학개론","q":"입지이론에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["레일리(W. Reilly)는 두 도시가 주변 소비자에게 미치는 영향력이 도시의 인구에 비례하고 거리의 제곱에 반비례한다고 보았다.","컨버스(P. Converse)는 레일리의 소매인력법칙을 이용해 두 도시 상권의 경계지점(분기점)을 구하는 식을 제시했다.","베버(A. Weber)의 최소비용이론에서 원료지수가 1보다 크면 공장은 시장 가까이에 입지한다.","크리스탈러(W. Christaller)의 중심지이론에서 재화의 도달범위가 최소요구범위보다 커야 중심지 기능이 성립한다.","뢰쉬(A. Lösch)는 수요 측면에서 이윤이 최대가 되는 입지를 찾았으며 이상적 시장구역이 육각형이라고 보았다."],"a":[3],"L":"학3-4","o":"변형","x":{"한줄":"원료지수가 1보다 크면 제품보다 원료가 무거워 운송비를 줄이려고 원료산지 쪽에 입지하고, 1보다 작으면 시장 쪽에 입지한다.","근거":[{"이론":"베버의 최소비용이론","내용":"원료지수 = 국지원료 중량 ÷ 제품 중량. 원료지수가 1보다 크면 원료지향, 1보다 작으면 시장지향 입지를 보인다."}],"선지":[{"번호":1,"판정":"옳음","설명":"레일리의 소매인력법칙은 인구(크기)에 비례, 거리의 제곱에 반비례한다."},{"번호":2,"판정":"옳음","설명":"컨버스는 레일리 법칙으로 두 도시 상권의 분기점을 구하는 공식을 제시했다."},{"번호":3,"판정":"틀림","설명":"원료지수가 1보다 크면 원료지향 입지다. 시장지향은 1보다 작을 때다."},{"번호":4,"판정":"옳음","설명":"도달범위(재화를 사러 오는 최대거리)가 최소요구범위(최소 수요 확보 범위)보다 커야 성립한다."},{"번호":5,"판정":"옳음","설명":"뢰쉬는 수요 측면에서 이윤극대화 입지를 찾고 시장구역을 육각형으로 보았다."}],"개념":[{"종류":"계산","제목":"베버 원료지수 계산 예","단계":[{"설명":"원료지수 공식","식":"원료지수 = 국지원료 중량 ÷ 제품 중량","값":"공식"},{"설명":"국지원료 30t, 제품 20t이면","식":"30 ÷ 20","값":"1.5 (1 초과)"},{"설명":"입지를 판정한다","식":"원료지수 > 1","값":"원료지향"},{"설명":"국지원료 10t, 제품 20t이면","식":"10 ÷ 20","값":"0.5 → 시장지향"}]},{"종류":"표","제목":"입지이론 정리","머리":["학자","이론","핵심"],"행":[["베버","최소비용","운송비·노동비·집적이익, 원료지수"],["뢰쉬","최대수요","수요 극대화, 육각형"],["크리스탈러","중심지","도달범위 > 최소요구범위, 육각형 계층"],["레일리","소매인력법칙","인구 비례, 거리 제곱에 반비례"],["컨버스","분기점 이론","두 도시 상권의 경계지점"],["허프","확률모형","점포 면적·거리·경쟁점포"]]}],"함정":"원료지수 1을 기준으로 원료지향과 시장지향을 반대로 외우기 쉽다. 원료가 무거우면(지수 > 1) 원료산지 쪽이다."}},{"i":"S3-1-1-학개론-15","r":"S3","g":1,"c":1,"n":15,"s":"학개론","q":"토지비축제도에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["정부가 토지시장에 직접 개입하는 정책수단이다.","지가가 상승하는 시기에는 비축토지를 매입해 토지 공급을 줄이고, 하락하는 시기에는 방출해 가격을 안정시킨다.","장래 공익사업에 쓸 토지를 미리 확보해 두면 사업 시행 단계의 토지보상비 부담을 줄일 수 있다.","지가 하락기에 정부가 토지를 매입해 비축하면 토지시장의 침체를 완화할 수 있다.","비축토지를 장기간 보유하면 관리비용과 재정 부담이 따를 수 있다."],"a":[2],"L":"학4-1","o":"변형","x":{"한줄":"토지비축은 지가가 오르는 시기에 비축토지를 방출해 공급을 늘리고, 지가가 내리는 시기에 매입해 수요를 보충한다.","근거":[{"이론":"토지비축제도(토지은행)","내용":"공공이 토지를 미리 취득·보유하다가 필요한 때 공급하는 직접개입 수단으로, 지가 안정과 공익사업용지의 안정적 확보를 목적으로 한다. 지가 상승기에 방출하고 하락기에 매입한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"토지비축은 정부가 직접 토지를 거래하는 직접개입 수단이다."},{"번호":2,"판정":"틀림","설명":"상승기에는 비축토지를 방출해 공급을 늘리고, 하락기에 매입한다. 방향이 반대로 쓰였다."},{"번호":3,"판정":"옳음","설명":"미리 확보하면 사업 시점의 지가 상승에 따른 보상비 부담을 줄일 수 있다."},{"번호":4,"판정":"옳음","설명":"하락기 매입은 수요를 보충해 시장 침체와 가격 하락을 완화한다."},{"번호":5,"판정":"옳음","설명":"장기 보유에는 관리비용과 자금 조달 등 재정 부담이 따른다."}],"개념":[{"종류":"표","제목":"정부 개입 방식 구분","머리":["구분","수단"],"행":[["직접개입","토지수용, 토지비축(토지은행), 공영개발, 공공투자, 공공임대주택 공급"],["간접개입","금융지원, 보조금, 조세 감면·중과"],["규제","용도지역·지구제, 토지거래허가, 개발권 규제"]]},{"종류":"비교","제목":"지가 국면별 토지비축","왼쪽":{"이름":"지가 상승기","항목":["비축토지 방출","공급을 늘려 가격 안정"]},"오른쪽":{"이름":"지가 하락기","항목":["토지 매입 비축","수요를 보충해 침체 완화"]}}],"함정":"비축은 '많이 사 두는 것'이라고만 외우면 상승기 매입을 옳게 읽는다. 매입 시점은 하락기, 방출 시점은 상승기다."}},{"i":"S3-1-1-학개론-16","r":"S3","g":1,"c":1,"n":16,"s":"학개론","q":"토지정책에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["개발권양도제는 개발사업으로 얻은 불로소득을 일정 비율로 환수하는 제도다.","토지거래허가구역은 5년 이내의 기간을 정하여 지정하며, 허가구역에서 공익사업용 토지의 거래허가 신청이 있으면 선매자를 지정해 협의 매수하게 할 수 있다.","환지방식은 시행자가 구역의 토지를 모두 수용 또는 사용한 뒤 조성한 토지를 분양하는 방식이다.","금융지원과 보조금 지급은 정부가 토지시장에 직접 참여하는 직접개입방식이다.","개발부담금의 부담률은 개발사업의 종류와 관계없이 개발이익의 100분의 50이다."],"a":[2],"L":"학4-1","o":"변형","x":{"한줄":"토지거래허가구역은 5년 이내로 지정하고, 공익사업용 토지 등은 허가신청 때 시장·군수·구청장이 선매자를 지정해 협의 매수하게 할 수 있다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제10조제1항","원문":"국토교통부장관 또는 시ㆍ도지사는 …토지의 투기적인 거래가 성행하거나 지가(地價)가 급격히 상승하는 지역과 그러한 우려가 있는 지역으로서 대통령령으로 정하는 지역에 대해서는 다음 각 호의 구분에 따라 5년 이내의 기간을 정하여 제11조제1항에 따른 토지거래계약에 관한 허가구역…으로 지정할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제15조제1항","원문":"시장ㆍ군수 또는 구청장은 제11조제1항에 따른 토지거래계약에 관한 허가신청이 있는 경우 다음 각 호의 어느 하나에 해당하는 토지에 대하여 국가, 지방자치단체, 한국토지주택공사, 그 밖에 대통령령으로 정하는 공공기관 또는 공공단체가 그 매수를 원하는 경우에는 이들 중에서 해당 토지를 매수할 자[이하 \"선매자(先買者)\"라 한다]를 지정하여 그 토지를 협의 매수하게 할 수 있다.\n  1. 공익사업용 토지\n  2. 제11조제1항에 따른 토지거래계약허가를 받아 취득한 토지를 그 이용목적대로 이용하고 있지 아니한 토지"},{"법령":"도시개발법","조문":"제21조제1항","원문":"도시개발사업은 시행자가 도시개발구역의 토지등을 수용 또는 사용하는 방식이나 환지 방식 또는 이를 혼용하는 방식으로 시행할 수 있다."},{"법령":"개발이익 환수에 관한 법률","조문":"제13조","원문":"1. 제5조제1항제1호부터 제6호까지의 개발사업: 100분의 20\n2. 제5조제1항제7호 및 제8호의 개발사업: 100분의 25. 다만, … 개발제한구역에서 … 납부 의무자가 개발제한구역으로 지정될 당시부터 토지 소유자인 경우에는 100분의 20으로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"개발이익을 환수하는 제도는 개발부담금제다. 개발권양도제는 규제로 개발이 제한된 토지 소유자가 개발권을 팔 수 있게 하는 제도다."},{"번호":2,"판정":"옳음","설명":"허가구역은 5년 이내(부동산 거래신고법 제10조제1항), 선매는 공익사업용 토지 등에 대해 허가신청이 있을 때 가능하다(제15조제1항)."},{"번호":3,"판정":"틀림","설명":"토지를 수용 또는 사용하는 방식과 환지방식은 별개의 시행 방식이다(도시개발법 제21조제1항). 환지방식은 개발 후 토지를 토지소유자에게 재배분한다."},{"번호":4,"판정":"틀림","설명":"금융지원과 보조금 지급은 간접개입방식이다. 토지수용·토지비축·공영개발이 직접개입이다."},{"번호":5,"판정":"틀림","설명":"부담률은 개발사업 종류에 따라 100분의 20 또는 100분의 25다(개발이익 환수에 관한 법률 제13조)."}],"개념":[{"종류":"흐름","제목":"토지거래허가구역 지정·허가·선매 절차","단계":[{"이름":"허가구역 지정","설명":"국토교통부장관 또는 시ㆍ도지사가 도시계획위원회 심의를 거쳐 5년 이내 기간으로 지정"},{"이름":"공고·통지","설명":"지정 사실을 공고하고 시장ㆍ군수ㆍ구청장을 거쳐 등기소에 통지"},{"이름":"효력 발생","설명":"공고한 날부터 5일 후에 효력 발생(제10조제5항)"},{"이름":"허가 신청","설명":"당사자가 공동으로 시장ㆍ군수 또는 구청장에게 허가 신청(제11조제1항)"},{"이름":"선매자 지정","설명":"공익사업용 토지 등은 신청일부터 1개월 이내 선매자 지정(제15조제2항)"},{"이름":"선매협의","설명":"지정 통지를 받은 날부터 1개월 이내 협의 종료, 불성립이면 허가·불허가 통보"}]},{"종류":"표","제목":"토지정책 수단 비교","머리":["제도","내용"],"행":[["개발권양도제","규제 지역 소유자가 개발권을 다른 지역 개발자에게 양도"],["개발부담금","개발이익을 환수(부담률 20% 또는 25%)"],["토지거래허가제","투기 우려 지역 거래를 허가제로 규제, 5년 이내 지정"],["선매제도","허가신청 시 공공이 우선 협의 매수"],["도시개발 환지방식","개발 후 토지소유자에게 토지 재배분"]]}],"함정":"개발권양도제와 개발부담금을 바꿔 읽는 1번이 가장 흔하다. 금융·보조금은 간접개입이다."}},{"i":"S3-1-1-학개론-17","r":"S3","g":1,"c":1,"n":17,"s":"학개론","q":"주택공급제도에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["후분양제도는 건설자금을 사업자가 먼저 조달해야 하므로 금융비용이 분양가격에 반영될 수 있다.","선분양제도는 소비자가 완공된 주택의 품질을 확인한 뒤 계약할 수 있다.","후분양제도는 선분양제도보다 분양권 전매를 통한 가수요가 생기기 쉽다.","선분양제도는 사업자의 초기 자금부담을 가중시킨다.","소비자 측면에서 후분양제도는 선분양제도보다 부실시공에 대처하기 어렵다."],"a":[1],"L":"학4-2","o":"변형","x":{"한줄":"후분양은 주택을 지은 뒤 분양하므로 공사비를 사업자가 먼저 조달하고, 그 금융비용이 분양가격에 반영될 수 있다.","근거":[{"이론":"선분양제도와 후분양제도","내용":"선분양은 착공 전·건설 중에 분양대금을 받아 건설에 쓰고, 후분양은 일정 공정 이후 또는 준공 후에 분양한다. 선분양은 사업자 자금부담이 작고 소비자의 품질 확인이 어렵다. 후분양은 사업자 금융비용이 크고 소비자 품질 확인과 가수요 억제에 유리하다."}],"선지":[{"번호":1,"판정":"옳음","설명":"후분양에서는 건설자금을 사업자가 먼저 조달하므로 금융비용이 분양가격에 반영될 수 있다."},{"번호":2,"판정":"틀림","설명":"선분양은 주택이 지어지기 전에 계약하므로 소비자가 완공된 품질을 확인할 수 없다."},{"번호":3,"판정":"틀림","설명":"분양권 전매 가수요는 선분양에서 생기기 쉽다. 후분양은 분양 시점에 주택이 완공에 가까워 가수요가 줄어든다."},{"번호":4,"판정":"틀림","설명":"선분양은 분양대금을 건설 중에 받아 사업자의 초기 자금부담을 완화한다."},{"번호":5,"판정":"틀림","설명":"후분양은 지어진 주택을 보고 계약하므로 선분양보다 부실시공에 대처하기 쉽다."}],"개념":[{"종류":"비교","제목":"선분양과 후분양","왼쪽":{"이름":"선분양제도","항목":["준공 전 분양대금을 받음","사업자 초기 자금부담 완화","소비자의 품질 확인 곤란","분양권 전매로 가수요 우려"]},"오른쪽":{"이름":"후분양제도","항목":["준공 후(또는 일정 공정 후) 분양","사업자 금융비용 부담이 큼","소비자가 품질 확인 가능","가수요 억제, 분양가에 금융비용 반영 가능"]}},{"종류":"표","제목":"주택공급제도 장단점","머리":["구분","소비자","사업자"],"행":[["선분양","품질 확인 어려움, 입주 지연 위험","자금조달 용이, 판매 위험 작음"],["후분양","품질 확인 가능, 목돈 부담 감소","금융비용 증가, 미분양 위험"]]}],"함정":"자금을 누가 대느냐를 거꾸로 읽기 쉽다. 선분양은 소비자의 분양대금으로, 후분양은 사업자 자금으로 짓는다."}},{"i":"S3-1-1-학개론-18","r":"S3","g":1,"c":1,"n":18,"s":"학개론","q":"부동산 조세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["조세의 중립성은 조세가 시장의 자원배분에 영향을 미치지 않아야 한다는 원칙을 의미한다.","양도소득세를 중과하면 부동산의 보유기간이 늘어나는 현상이 발생할 수 있다.","조세의 사실상 부담이 최종적으로 어떤 사람에게 귀속되는 것을 조세의 귀착이라 한다.","양도소득세는 양도로 인해 발생하는 소득에 대해 부과되는 것으로 타인에게 전가될 수 있다.","재산세와 종합부동산세는 보유세로서 지방세이다."],"a":[5],"L":"학4-3","o":"기출","x":{"한줄":"재산세는 지방세이지만 종합부동산세는 국세다.","근거":[{"법령":"국세기본법","조문":"제2조제1호","원문":"\"국세\"(國稅)란 국가가 부과하는 조세 중 다음 각 목의 것을 말한다.\n  가. 소득세\n  나. 법인세\n  다. 상속세와 증여세\n  라. 종합부동산세"},{"법령":"지방세기본법","조문":"제8조제3항","원문":"구세는 다음 각 호와 같다.\n  1. 등록면허세\n  2. 재산세"}],"선지":[{"번호":1,"판정":"옳음","설명":"조세의 중립성은 조세가 자원배분에 영향을 주지 않아야 한다는 원칙이다."},{"번호":2,"판정":"옳음","설명":"양도소득세를 중과하면 양도를 미루려는 동결효과로 보유기간이 늘어난다."},{"번호":3,"판정":"옳음","설명":"법적 납세자와 실제 부담자가 다를 수 있고 최종 부담이 귀속되는 것이 귀착이다."},{"번호":4,"판정":"옳음","설명":"양도소득세는 양도가격 인상 등으로 매수인에게 전가될 수 있다."},{"번호":5,"판정":"틀림","설명":"재산세는 지방세(지방세기본법 제8조), 종합부동산세는 국세(국세기본법 제2조제1호라목)다."}],"개념":[{"종류":"표","제목":"부동산 관련 조세 분류","머리":["단계","세목","구분","과세 성격"],"행":[["취득","취득세","지방세","거래세"],["취득","상속세·증여세","국세","거래세(무상 취득)"],["보유","재산세","지방세","보유세"],["보유","종합부동산세","국세","보유세"],["처분","양도소득세","국세","거래세(소득세)"],["처분","지방소득세(양도소득분)","지방세","소득에 부가"]]},{"종류":"표","제목":"보유세와 거래세의 효과","머리":["구분","효과"],"행":[["보유세 중과","부동산 보유 비용 증가, 매각 압력, 투기 억제"],["거래세 중과","거래 위축, 동결효과(보유기간 증가)"],["양도소득세 중과","양도 기피, 보유기간 증가"]]}],"함정":"종합부동산세가 지방세라는 오해가 가장 흔하다. 종합부동산세는 국세다."}},{"i":"S3-1-1-학개론-19","r":"S3","g":1,"c":1,"n":19,"s":"학개론","q":"부동산투자의 위험분석에 관한 설명으로 틀린 것은? (단, 위험회피형 투자자라고 가정함)","b":null,"bs":"없음","img":[],"ch":["위험회피형 투자자는 위험이 클수록 더 높은 수익률을 요구한다.","민감도분석은 임대료, 공실률 같은 주요 변수가 변할 때 투자성과가 얼마나 달라지는지 살피는 기법이다.","보수적 예측방법은 수입을 낮게, 비용을 높게 추계해 위험에 대비하는 방법이다.","변동계수(표준편차 ÷ 기대수익률)가 클수록 기대수익 한 단위당 위험이 작다.","위험회피형 투자자는 기대수익률이 같다면 분산이 작은 투자안을 선택한다."],"a":[4],"L":"학5-1","o":"변형","x":{"한줄":"변동계수는 기대수익 한 단위당 위험이므로 값이 클수록 위험이 크다.","근거":[{"이론":"부동산투자의 위험분석","내용":"위험회피형 투자자는 위험 증가만큼 높은 보상(위험할증)을 요구한다. 변동계수 = 표준편차 ÷ 기대수익률로 작을수록 유리하다. 보수적 예측, 민감도분석, 확률분포(평균-분산), 위험조정할인율이 대표 방법이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"위험과 요구수익률은 비례하고 위험회피형은 위험할증을 요구한다."},{"번호":2,"판정":"옳음","설명":"민감도분석은 투입변수의 변화가 결과에 주는 영향을 살핀다."},{"번호":3,"판정":"옳음","설명":"보수적 예측은 수입을 낮게, 비용을 높게 추계해 위험을 감안한다."},{"번호":4,"판정":"틀림","설명":"변동계수가 클수록 기대수익 한 단위당 위험이 크다."},{"번호":5,"판정":"옳음","설명":"기대수익률이 같다면 분산이 작은 투자안이 지배한다(평균-분산 지배원리)."}],"개념":[{"종류":"계산","제목":"변동계수 비교 예","단계":[{"설명":"변동계수 공식","식":"변동계수 = 표준편차 ÷ 기대수익률","값":"공식"},{"설명":"투자안 A: 표준편차 6%, 기대수익률 10%","식":"6 ÷ 10","값":"0.6"},{"설명":"투자안 B: 표준편차 8%, 기대수익률 20%","식":"8 ÷ 20","값":"0.4"},{"설명":"단위 기대수익당 위험이 작은 안을 고른다","식":"0.4 < 0.6","값":"투자안 B 선택"}]},{"종류":"표","제목":"부동산투자 위험분석 방법","머리":["방법","내용"],"행":[["보수적 예측방법","수입은 낮게, 비용은 높게 추계"],["위험조정할인율","위험이 클수록 높은 할인율 적용"],["민감도분석","투입변수 변화에 따른 결과 변화 분석"],["평균-분산 결정법","기대수익률 평균과 분산(위험)으로 선택"],["변동계수","표준편차 ÷ 기대수익률, 작을수록 유리"]]}],"함정":"변동계수의 크기와 위험의 방향을 반대로 읽기 쉽다. 위험조정할인율은 위험할수록 높은 할인율을 적용한다."}},{"i":"S3-1-1-학개론-20","r":"S3","g":1,"c":1,"n":20,"s":"학개론","q":"포트폴리오이론에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["개별자산의 고유한 위험(비체계적 위험)은 분산투자로 줄일 수 있다.","구성자산 간 상관계수가 낮을수록 분산투자 효과가 크다.","위험회피 정도가 큰 투자자일수록 무차별곡선의 기울기가 완만해져 효율적 프런티어에서 위험이 큰 포트폴리오를 선택한다.","포트폴리오의 기대수익률은 구성자산의 기대수익률을 투자비중으로 가중평균한 값이다.","효율적 프런티어 위의 포트폴리오는 다른 어떤 포트폴리오에도 평균-분산 기준으로 지배당하지 않는다."],"a":[3],"L":"학5-1","o":"변형","x":{"한줄":"위험회피 정도가 큰 투자자의 무차별곡선은 기울기가 가파르고, 효율적 프런티어에서 위험이 작은 포트폴리오를 선택한다.","근거":[{"이론":"포트폴리오이론(마코위츠)","내용":"분산투자로 비체계적 위험은 제거되고 체계적 위험은 남는다. 상관계수가 낮을수록 분산효과가 크다. 효율적 프런티어는 같은 위험에서 최대 기대수익률(같은 수익률에서 최소 위험)을 주는 포트폴리오 집합이고, 최적 포트폴리오는 무차별곡선과 프런티어의 접점이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"비체계적 위험은 분산투자로 감소하고 체계적 위험은 줄지 않는다."},{"번호":2,"판정":"옳음","설명":"상관계수가 낮을수록 한 자산의 손실을 다른 자산이 상쇄해 분산효과가 커진다."},{"번호":3,"판정":"틀림","설명":"위험회피 정도가 클수록 무차별곡선은 가파르고 위험이 작은 포트폴리오를 선택한다."},{"번호":4,"판정":"옳음","설명":"포트폴리오 기대수익률은 투자비중에 따른 가중평균이다."},{"번호":5,"판정":"옳음","설명":"효율적 프런티어는 지배당하지 않는 포트폴리오 집합이다."}],"개념":[{"종류":"계산","제목":"포트폴리오 기대수익률 계산 예","단계":[{"설명":"공식","식":"E(Rp) = Σ(투자비중 × 기대수익률)","값":"공식"},{"설명":"자산 A: 비중 60%, 기대수익률 10%","식":"0.6 × 10%","값":"6%"},{"설명":"자산 B: 비중 40%, 기대수익률 5%","식":"0.4 × 5%","값":"2%"},{"설명":"합산한다","식":"6% + 2%","값":"8%"}]},{"종류":"표","제목":"위험의 구분과 분산투자","머리":["구분","다른 이름","분산투자 효과"],"행":[["체계적 위험","시장위험, 분산불가능위험","줄일 수 없음"],["비체계적 위험","개별위험, 분산가능위험","줄일 수 있음"],["상관계수 −1","완전 음의 상관","위험 최대 감소(0까지 가능)"],["상관계수 +1","완전 양의 상관","분산효과 없음"]]}],"함정":"위험회피 정도와 무차별곡선 기울기의 방향을 바꿔 읽기 쉽다. 위험회피가 클수록 기울기는 가파르다."}},{"i":"S3-1-1-학개론-21","r":"S3","g":1,"c":1,"n":21,"s":"학개론","q":"화폐의 시간가치에 관한 설명으로 틀린 것은? (단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["연금의 내가계수는 매기 말 같은 금액을 적립할 때 n기 후에 쌓이는 원리금 합계를 구하는 데 쓴다.","감채기금계수는 연금의 내가계수의 역수이다.","일시불의 현가계수는 일시불의 내가계수의 역수이다.","저당상수에 대출액을 곱하면 원리금균등상환방식의 매기 상환액을 구할 수 있다.","현재 3억원을 연 4% 복리로 5년간 운용했을 때 5년 후의 금액은 연금의 내가계수를 사용하여 구한다."],"a":[5],"L":"학5-2","o":"변형","x":{"한줄":"한 번 맡긴 돈의 n년 후 금액은 일시불의 내가계수 (1+r)ⁿ 으로 구하고, 연금의 내가계수는 매기 같은 금액을 적립할 때 쓴다.","근거":[{"이론":"화폐의 시간가치 6계수","내용":"일시불의 내가계수 (1+r)ⁿ, 일시불의 현가계수 1÷(1+r)ⁿ, 연금의 내가계수 [(1+r)ⁿ−1]÷r, 감채기금계수 r÷[(1+r)ⁿ−1], 연금의 현가계수 [(1+r)ⁿ−1]÷[r(1+r)ⁿ], 저당상수 r(1+r)ⁿ÷[(1+r)ⁿ−1]. 역수 관계는 일시불 내가↔현가, 연금 내가↔감채기금, 연금 현가↔저당상수 세 쌍이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"연금의 내가계수 [(1+r)ⁿ−1]÷r 에 매기 적립액을 곱하면 n기 후 원리금 합계가 나온다."},{"번호":2,"판정":"옳음","설명":"감채기금계수 r÷[(1+r)ⁿ−1] 은 연금의 내가계수 [(1+r)ⁿ−1]÷r 의 역수이다. 목표액에 곱하면 매기 적립액이 나온다."},{"번호":3,"판정":"옳음","설명":"일시불의 현가계수 1÷(1+r)ⁿ 은 일시불의 내가계수 (1+r)ⁿ 의 역수이다."},{"번호":4,"판정":"옳음","설명":"저당상수 r(1+r)ⁿ÷[(1+r)ⁿ−1] 에 대출액을 곱한 값이 원리금균등상환의 매기 원리금이다."},{"번호":5,"판정":"틀림","설명":"3억원을 한 번에 맡겼으므로 일시불의 내가계수 (1+0.04)⁵ 를 쓴다. 연금의 내가계수는 매기 같은 금액을 적립하는 경우에 쓴다."}],"개념":[{"종류":"표","제목":"화폐의 시간가치 6계수","머리":["계수","식","구하는 것","역수 관계"],"행":[["일시불의 내가계수","(1+r)ⁿ","현재 금액의 n기 후 금액","일시불의 현가계수"],["일시불의 현가계수","1÷(1+r)ⁿ","n기 후 금액의 현재가치","일시불의 내가계수"],["연금의 내가계수","[(1+r)ⁿ−1]÷r","매기 적립액의 n기 후 합계","감채기금계수"],["감채기금계수","r÷[(1+r)ⁿ−1]","목표액을 만들 매기 적립액","연금의 내가계수"],["연금의 현가계수","[(1+r)ⁿ−1]÷[r(1+r)ⁿ]","매기 수입의 현재가치 합계","저당상수"],["저당상수","r(1+r)ⁿ÷[(1+r)ⁿ−1]","대출액에 대한 매기 원리금","연금의 현가계수"]]},{"종류":"계산","제목":"3억원의 5년 후 금액 (연 4% 복리)","단계":[{"설명":"일시불의 내가계수","식":"(1+0.04)⁵","값":"1.2167"},{"설명":"대입","식":"3억원 × 1.2167","값":"약 3.65억원"}]}],"함정":"맡긴 돈이 한 번이면 일시불, 매기 같은 금액이면 연금으로 가른다. 역수 관계를 엇갈리게 기억하면 2번이 틀린 문장으로 보인다. 연금의 내가계수의 역수는 감채기금계수이고, 연금의 현가계수의 역수는 저당상수이다."}},{"i":"S3-1-1-학개론-22","r":"S3","g":1,"c":1,"n":22,"s":"학개론","q":"부동산 투자분석의 어림셈법에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["채무불이행률은 영업경비와 부채서비스액의 합을 가능총소득으로 나눈 비율이다.","대부비율이 60%이면 부채비율도 60%이다.","부채감당률이 1보다 작으면 순영업소득이 부채서비스액을 초과한다.","총소득승수는 총투자액을 총소득으로 나눈 값이고, 순소득승수는 총투자액을 순영업소득으로 나눈 값이다.","세전현금수지승수는 지분투자액을 세후현금수지로 나눈 값이다."],"a":[4],"L":"학5-3","o":"변형","x":{"한줄":"총소득승수는 총투자액÷총소득, 순소득승수는 총투자액÷순영업소득이다.","근거":[{"이론":"승수법·비율분석법의 식","내용":"총소득승수=총투자액÷총소득, 순소득승수=총투자액÷순영업소득, 세전현금수지승수=지분투자액÷세전현금수지, 부채감당률=순영업소득÷부채서비스액, 채무불이행률=(영업경비+부채서비스액)÷유효총소득, 부채비율=부채÷지분."}],"선지":[{"번호":1,"판정":"틀림","설명":"채무불이행률(손익분기율)은 (영업경비+부채서비스액)÷유효총소득이다. 분모는 가능총소득이 아니라 유효총소득이다."},{"번호":2,"판정":"틀림","설명":"부채비율은 부채÷지분이다. 대부비율 60%이면 부채 60, 지분 40이므로 부채비율은 150%이다."},{"번호":3,"판정":"틀림","설명":"부채감당률은 순영업소득÷부채서비스액이다. 1보다 작으면 순영업소득이 부채서비스액에 못 미친다."},{"번호":4,"판정":"옳음","설명":"두 승수 모두 총투자액이 분자이고, 분모만 총소득과 순영업소득으로 다르다."},{"번호":5,"판정":"틀림","설명":"세전현금수지승수는 지분투자액÷세전현금수지이다. 세후현금수지로 나누면 세후현금수지승수이다."}],"개념":[{"종류":"표","제목":"어림셈법 지표의 식","머리":["지표","식","읽는 법"],"행":[["대부비율(LTV)","융자액÷부동산가치","클수록 부채 의존도가 크다"],["부채비율","부채÷지분","대부비율 ÷ (1−대부비율)과 같다"],["부채감당률(DCR)","순영업소득÷부채서비스액","1 미만이면 순영업소득으로 원리금을 못 갚는다"],["채무불이행률(손익분기율)","(영업경비+부채서비스액)÷유효총소득","낮을수록 안전하다"],["총자산회전율","총소득÷총투자액","가능총소득 또는 유효총소득을 쓴다"],["영업경비비율","영업경비÷총소득","문제가 기준 소득을 정한다"],["총소득승수","총투자액÷총소득","총투자액 기준"],["순소득승수","총투자액÷순영업소득","총투자액 기준"],["세전·세후현금수지승수","지분투자액÷세전(세후)현금수지","지분투자액 기준"]]},{"종류":"계산","제목":"대부비율 60%일 때 부채비율","단계":[{"설명":"부동산가치를 100으로 놓는다","식":"부채 = 100 × 0.6","값":"60"},{"설명":"지분","식":"100 − 60","값":"40"},{"설명":"부채비율","식":"부채 ÷ 지분 = 60 ÷ 40","값":"150%"}]}],"함정":"대부비율과 부채비율은 분모가 다르다(부동산가치와 지분). 채무불이행률의 분모는 유효총소득이다. 현금수지승수의 세전·세후를 바꿔 읽기 쉽다."}},{"i":"S3-1-1-학개론-23","r":"S3","g":1,"c":1,"n":23,"s":"학개론","q":"부동산투자의 분석기법에 관한 설명으로 틀린 것은? (단, 다른 조건은 동일함)","b":null,"bs":"없음","img":[],"ch":["수익률법과 승수법은 투자현금흐름의 시간가치를 반영하여 투자타당성을 분석하는 방법이다.","투자자산의 현금흐름에 따라 복수의 내부수익률이 존재할 수 있다.","세후지분투자수익률은 지분투자액에 대한 세후현금흐름의 비율이다.","투자의 타당성은 총투자액 또는 지분투자액을 기준으로 분석할 수 있으며, 총소득승수는 총투자액을 기준으로 분석하는 지표다.","총부채상환비율(DTI)이 높을수록 채무불이행 위험이 높아진다."],"a":[1],"L":"학5-3","o":"기출","x":{"한줄":"수익률법과 승수법은 투자현금흐름의 시간가치를 반영하지 않는 어림셈법이다. 시간가치를 반영하는 방법은 순현가법·내부수익률법·수익성지수법이다.","근거":[{"이론":"투자분석기법의 분류","내용":"어림셈법(비할인법)은 회수기간법·승수법·수익률법·비율분석법이고 현금흐름의 시간가치를 반영하지 않는다. 할인현금흐름분석법은 순현가·내부수익률·수익성지수이며 시간가치를 반영한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"수익률법과 승수법은 시간가치를 반영하지 않는다. 시간가치를 반영하는 것은 순현가법·내부수익률법·수익성지수법이다."},{"번호":2,"판정":"옳음","설명":"부(−)와 정(+)의 현금흐름이 여러 번 바뀌면 순현가를 0으로 만드는 할인율이 둘 이상 나올 수 있다."},{"번호":3,"판정":"옳음","설명":"세후지분투자수익률은 세후현금수지÷지분투자액이다."},{"번호":4,"판정":"옳음","설명":"총소득승수는 총투자액÷총소득이므로 총투자액 기준이다. 세전·세후현금수지승수는 지분투자액 기준이다."},{"번호":5,"판정":"옳음","설명":"총부채상환비율(DTI)은 연간 원리금 상환액÷연소득이다. 높을수록 소득에서 원리금이 차지하는 몫이 커서 채무불이행 위험이 높다."}],"개념":[{"종류":"표","제목":"투자분석기법 분류","머리":["구분","기법","시간가치","기준 자본"],"행":[["어림셈법","회수기간법","반영하지 않음","투자액"],["어림셈법","승수법(총소득승수·순소득승수·세전/세후현금수지승수)","반영하지 않음","총투자액 또는 지분투자액"],["어림셈법","수익률법(종합자본환원율·세전/세후지분투자수익률)","반영하지 않음","총투자액 또는 지분투자액"],["어림셈법","비율분석법(대부비율·부채감당률·채무불이행률 등)","반영하지 않음","-"],["할인현금흐름분석법","순현가법·내부수익률법·수익성지수법","반영함","투자 지출의 현재가치"]]},{"종류":"표","제목":"승수와 수익률의 대응(서로 역수)","머리":["승수","식","대응 수익률","식"],"행":[["총소득승수","총투자액÷총소득","총소득률","총소득÷총투자액"],["순소득승수","총투자액÷순영업소득","종합자본환원율","순영업소득÷총투자액"],["세전현금수지승수","지분투자액÷세전현금수지","세전지분투자수익률","세전현금수지÷지분투자액"],["세후현금수지승수","지분투자액÷세후현금수지","세후지분투자수익률","세후현금수지÷지분투자액"]]}],"함정":"수익률법·승수법을 할인현금흐름분석법과 섞어 읽는 것이 오답 경로이다. 이름에 '수익률'이 들어가도 시간가치를 반영하는 방법이 아니다."}},{"i":"S3-1-1-학개론-24","r":"S3","g":1,"c":1,"n":24,"s":"학개론","q":"다음 조건의 투자안에 관한 설명으로 옳은 것은? (단, 현금흐름은 모두 기간 말에 발생하고 투자 지출은 현재 시점에 일시에 이루어지며, 다른 조건은 동일함)","b":"· 현재 시점의 투자 지출: 2.5억원\n· 1년 말 순현금유입: 1.1억원\n· 2년 말 순현금유입: 2.42억원\n· 요구수익률(할인율): 연 10%","bs":"글자","img":[],"ch":["현금유입의 현재가치 합계는 3.52억원이다.","순현가(NPV)는 1.02억원이다.","수익성지수(PI)는 1.2이고 순현가는 0.5억원이다.","내부수익률은 요구수익률 10%보다 낮다.","수익성지수가 1보다 크면 순현가는 0보다 작다."],"a":[3],"L":"학5-3","o":"변형","x":{"한줄":"현금유입의 현재가치 합계가 3.0억원이므로 순현가는 3.0−2.5=0.5억원, 수익성지수는 3.0÷2.5=1.2이다.","근거":[{"이론":"순현가법·수익성지수법·내부수익률법","내용":"순현가(NPV)=현금유입의 현재가치−현금유출의 현재가치. 수익성지수(PI)=현금유입의 현재가치÷현금유출의 현재가치. 내부수익률(IRR)=순현가를 0으로 만드는 할인율. 순현가>0, 수익성지수>1, 내부수익률>요구수익률이면 채택한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"현금유입을 할인하지 않고 더한 값(1.1+2.42=3.52)이다. 현재가치 합계는 1.0+2.0=3.0억원이다."},{"번호":2,"판정":"틀림","설명":"3.52−2.5=1.02는 할인하지 않은 합계로 구한 값이다. 순현가는 3.0−2.5=0.5억원이다."},{"번호":3,"판정":"옳음","설명":"수익성지수 3.0÷2.5=1.2, 순현가 3.0−2.5=0.5억원이다."},{"번호":4,"판정":"틀림","설명":"순현가가 0보다 크다는 것은 10%에서 현금유입의 현재가치가 지출보다 크다는 뜻이므로 내부수익률은 10%보다 높다. 계산하면 약 22.8%이다."},{"번호":5,"판정":"틀림","설명":"수익성지수>1이면 현금유입의 현재가치가 현금유출의 현재가치보다 크다는 뜻이므로 순현가는 0보다 크다."}],"개념":[{"종류":"계산","제목":"순현가와 수익성지수 (할인율 10%)","단계":[{"설명":"1년 말 유입의 현재가치","식":"1.1 ÷ (1+0.1)","값":"1.0억원"},{"설명":"2년 말 유입의 현재가치","식":"2.42 ÷ (1+0.1)²","값":"2.0억원"},{"설명":"현금유입의 현재가치 합계","식":"1.0 + 2.0","값":"3.0억원"},{"설명":"순현가","식":"3.0 − 2.5","값":"0.5억원"},{"설명":"수익성지수","식":"3.0 ÷ 2.5","값":"1.2"}]},{"종류":"표","제목":"투자판단기법 비교","머리":["기법","구하는 값","채택 기준","할인율·재투자율"],"행":[["순현가법(NPV)","유입의 현가−유출의 현가","0보다 크면 채택","요구수익률"],["수익성지수법(PI)","유입의 현가÷유출의 현가","1보다 크면 채택","요구수익률"],["내부수익률법(IRR)","순현가를 0으로 만드는 할인율","요구수익률보다 크면 채택","내부수익률로 재투자한다고 가정"],["회수기간법","투자액을 회수하는 데 걸리는 기간","기간이 짧은 안 선택","할인하지 않음"]]}],"함정":"현금흐름을 할인하지 않고 합하면 1·2번 값이 나온다. 순현가가 양수이면 내부수익률은 요구수익률보다 높다는 방향을 거꾸로 읽으면 4번에 걸린다."}},{"i":"S3-1-1-학개론-25","r":"S3","g":1,"c":1,"n":25,"s":"학개론","q":"다음 조건에서 원금균등상환방식으로 대출받은 경우, 4회차(4년차 말)에 상환할 원리금은? (단, 이자는 매년 말 기초 대출잔액에 대하여 계산하며, 다른 조건은 동일함)","b":"· 대출금액: 2억원\n· 대출기간: 10년\n· 대출금리: 연 5%\n· 상환방식: 연 단위 후불 상환","bs":"글자","img":[],"ch":["2,600만원","2,700만원","2,800만원","2,900만원","3,000만원"],"a":[2],"L":"학6-1","o":"변형","x":{"한줄":"원금은 매년 2,000만원으로 같고 4회차 이자는 기초잔액 1억 4,000만원의 5%인 700만원이므로 원리금은 2,700만원이다.","근거":[{"이론":"원금균등상환방식","내용":"매기 원금상환액=대출금÷대출기간(일정). 매기 이자=기초 대출잔액×금리. 이자가 잔액에 따라 줄어 매기 원리금도 같은 폭으로 감소한다."}],"선지":[{"번호":1,"판정":"-","설명":"5회차 원리금이다. 기초잔액 1억 2,000만원의 5%인 600만원에 원금 2,000만원을 더한 값이다."},{"번호":2,"판정":"-","설명":"4회차 원리금이다. 기초잔액 2억−2,000만×3=1억 4,000만원, 이자 700만원, 원금 2,000만원이다."},{"번호":3,"판정":"-","설명":"3회차 원리금이다. 기초잔액 1억 6,000만원의 5%인 800만원에 원금 2,000만원을 더한 값이다."},{"번호":4,"판정":"-","설명":"2회차 원리금이다. 기초잔액 1억 8,000만원의 5%인 900만원에 원금 2,000만원을 더한 값이다."},{"번호":5,"판정":"-","설명":"1회차 원리금이다. 대출 전액 2억원의 5%인 1,000만원에 원금 2,000만원을 더한 값이다."}],"개념":[{"종류":"계산","제목":"원금균등상환 4회차 원리금","단계":[{"설명":"매기 원금상환액","식":"2억원 ÷ 10년","값":"2,000만원"},{"설명":"4회차 기초 잔액","식":"2억원 − 2,000만원 × 3","값":"1억 4,000만원"},{"설명":"4회차 이자","식":"1억 4,000만원 × 5%","값":"700만원"},{"설명":"4회차 원리금","식":"2,000만원 + 700만원","값":"2,700만원"}]},{"종류":"표","제목":"대출 상환방식 비교","머리":["구분","원금균등","원리금균등","체증(점증)식","만기일시"],"행":[["매기 원리금","점점 감소","일정","점점 증가","이자만 내다 만기에 원금 전부"],["매기 원금상환액","일정","점점 증가","초기에는 이자에도 못 미칠 수 있음","만기에 한꺼번에"],["1회차 원리금","가장 큼","중간","가장 작음","이자만"],["전체 이자 부담","가장 작음","원금균등보다 큼","원리금균등보다 큼","가장 큼"],["대출잔액 감소 속도","가장 빠름","중간","느림","만기까지 변동 없음"]]}],"함정":"회차 하나씩 어긋난 값이 오답으로 놓여 있다. 이자를 대출 전액에 매기면 1회차 값 3,000만원이 나오고, 3회차 말 잔액을 쓰면 2,700만원 대신 2,600만원 쪽으로 어긋난다."}},{"i":"S3-1-1-학개론-26","r":"S3","g":1,"c":1,"n":26,"s":"학개론","q":"부동산 자금조달 방법 중 지분금융(equity financing)에 해당하지 않는 것은?","b":null,"bs":"없음","img":[],"ch":["자산유동화증권(ABS)","주식의 공모 증자","부동산 신디케이션","조인트벤처(공동투자사업)","부동산투자회사(REITs)"],"a":[1],"L":"학6-1","o":"변형","x":{"한줄":"자산유동화증권(ABS)은 자산을 담보로 발행하는 채권이어서 원리금을 갚아야 하는 부채금융이다.","근거":[{"이론":"부채금융과 지분금융의 구분","내용":"부채금융은 갚을 의무가 있는 조달(저당금융·신탁증서금융·사채·주택상환사채·MBB·ABS·ABCP·프로젝트 금융). 지분금융은 갚을 의무가 없는 조달(주식 발행·공모 증자·부동산 신디케이션·조인트벤처·리츠). 후순위채권·전환사채·신주인수권부사채는 그 중간인 메자닌금융이다."},{"법령":"부동산투자회사법","조문":"제2조제1호가목~다목","원문":"가. 자기관리 부동산투자회사: 자산운용 전문인력을 포함한 임직원을 상근으로 두고 자산의 투자ㆍ운용을 직접 수행하는 회사\n나. 위탁관리 부동산투자회사: 자산의 투자ㆍ운용을 자산관리회사에 위탁하는 회사\n다. 기업구조조정 부동산투자회사: 제49조의2제1항 각 호의 부동산을 투자 대상으로 하며 자산의 투자ㆍ운용을 자산관리회사에 위탁하는 회사"}],"선지":[{"번호":1,"판정":"-","설명":"ABS는 자산의 현금흐름을 담보로 발행하는 채권이다. 투자자는 채권자이므로 부채금융이다."},{"번호":2,"판정":"-","설명":"주식을 발행해 자금을 모으면 갚을 의무가 없다. 지분금융이다."},{"번호":3,"판정":"-","설명":"여러 투자자가 출자해 부동산을 공동 취득·운용하는 방식이다. 출자자는 지분을 갖는다. 지분금융이다."},{"번호":4,"판정":"-","설명":"공동사업체에 자본을 출자해 사업을 하는 방식이다. 지분금융이다."},{"번호":5,"판정":"-","설명":"리츠는 주식회사로서 주식을 발행해 자금을 조달한다. 지분금융이다."}],"개념":[{"종류":"비교","제목":"부채금융과 지분금융","왼쪽":{"이름":"부채금융","항목":["갚을 의무가 있다","투자자는 채권자(이자 수취)","저당금융·신탁증서금융·사채·주택상환사채","MBB·ABS·ABCP·프로젝트 금융"]},"오른쪽":{"이름":"지분금융","항목":["갚을 의무가 없다","투자자는 주주·출자자(배당·지분이익)","주식 발행·공모 증자·부동산 신디케이션","조인트벤처·부동산투자회사(리츠)"]}},{"종류":"표","제목":"부동산투자회사(리츠) 종류별 자본금","머리":["구분","자기관리","위탁관리","기업구조조정"],"행":[["운용 방식","상근 임직원이 직접 운용","자산관리회사에 위탁","자산관리회사에 위탁"],["설립 자본금","5억원 이상","3억원 이상","3억원 이상"],["최저자본금(인가·등록 후 6개월 경과)","70억원 이상","50억원 이상","50억원 이상"],["지점·직원·상근임원","둘 수 있음","없음","없음"]]}],"함정":"ABS·MBB는 이름에 증권이 붙어 주식처럼 보이지만 자산을 담보로 한 채권이다. 리츠는 투자자가 주주이므로 지분금융이다."}},{"i":"S3-1-1-학개론-27","r":"S3","g":1,"c":1,"n":27,"s":"학개론","q":"주택도시기금법령상 주택도시기금 중 주택계정의 용도가 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["국민주택규모 이하의 주택의 임차에 대한 융자","국민주택규모를 초과하는 주택의 구입에 대한 융자","준주택의 개량에 대한 융자","주택도시보증공사에 대한 출자","임대주택의 공급을 촉진하기 위한 부동산투자회사 발행 증권의 매입"],"a":[2],"L":"학6-2","o":"변형","x":{"한줄":"주택계정의 구입·임차·개량 융자는 국민주택규모 이하의 주택에 한정되므로 국민주택규모를 초과하는 주택의 구입 융자는 용도가 아니다.","근거":[{"법령":"주택도시기금법","조문":"제9조제1항제1호","원문":"1. 다음 각 목에 대한 출자 또는 융자\n가. 국민주택의 건설\n나. 국민주택규모 이하의 주택의 구입ㆍ임차 또는 개량\n다. 준주택의 건설\n라. 준주택의 구입ㆍ임차 또는 개량\n마. 국민주택규모 이하인 주택의 리모델링\n바. 국민주택을 건설하기 위한 대지조성사업"},{"법령":"주택도시기금법","조문":"제9조제1항제2호·제3호","원문":"가. 제16조에 따른 주택도시보증공사(이하 \"공사\"라 한다)\n3. 임대주택 및 「공공주택 특별법」 제2조제1호나목의 공공분양주택의 공급을 촉진하기 위한 다음 각 목의 어느 하나에 해당하는 증권의 매입\n가. 「부동산투자회사법」 제2조제1호에 따른 부동산투자회사가 발행하는 증권"}],"선지":[{"번호":1,"판정":"옳음","설명":"국민주택규모 이하의 주택의 구입·임차 또는 개량에 대한 출자 또는 융자는 용도이다(제9조제1항제1호나목). 보기는 용도에 해당한다."},{"번호":2,"판정":"틀림","설명":"구입·임차·개량 융자 대상은 국민주택규모 이하의 주택이다(제9조제1항제1호나목). 85㎡를 초과하는 주택은 대상이 아니다."},{"번호":3,"판정":"옳음","설명":"준주택의 구입·임차 또는 개량에 대한 출자 또는 융자는 용도이다(제9조제1항제1호라목)."},{"번호":4,"판정":"옳음","설명":"주택도시보증공사에 대한 출자·출연 또는 융자는 용도이다(제9조제1항제2호가목)."},{"번호":5,"판정":"옳음","설명":"임대주택 및 공공분양주택의 공급을 촉진하기 위한 부동산투자회사 발행 증권의 매입은 용도이다(제9조제1항제3호가목)."}],"개념":[{"종류":"표","제목":"주택계정의 용도 (주택도시기금법 제9조제1항)","머리":["구분","대상","규모 요건"],"행":[["국민주택의 건설","출자 또는 융자","국민주택규모 이하(국민주택의 요건)"],["국민주택을 건설하기 위한 대지조성사업","출자 또는 융자","-"],["주택의 구입·임차 또는 개량","출자 또는 융자","국민주택규모 이하"],["주택의 리모델링","출자 또는 융자","국민주택규모 이하"],["준주택의 건설, 구입·임차 또는 개량","출자 또는 융자","규모 요건 없음"],["기관·기금·특별회계","주택도시보증공사, 한국토지주택공사, 한국주택금융공사, 주택금융신용보증기금, 유동화전문회사등, 국민주택사업특별회계","출자·출연 또는 융자"],["임대주택·공공분양주택 공급 촉진 증권의 매입","리츠, 부동산집합투자기구 등이 발행한 증권","-"]]},{"종류":"표","제목":"국민주택규모와 준주택 (주택법)","머리":["용어","내용"],"행":[["국민주택규모","주거전용면적 85㎡ 이하(수도권을 제외한 도시지역이 아닌 읍·면 지역은 100㎡ 이하)"],["국민주택","국가·지방자치단체·한국토지주택공사·지방공사가 건설하는 주택, 또는 국가·지방자치단체의 재정이나 주택도시기금의 자금을 지원받아 건설·개량되는 주택으로서 국민주택규모 이하인 주택"],["준주택","기숙사, 다중생활시설, 노인복지주택, 오피스텔"],["민영주택","국민주택을 제외한 주택"]]}],"함정":"국민주택규모 이하라는 요건이 구입·임차·개량·리모델링에 모두 붙는다. 준주택에는 규모 요건이 없다. 이 두 가지를 바꿔 읽으면 2번과 3번을 거꾸로 판정한다."}},{"i":"S3-1-1-학개론-28","r":"S3","g":1,"c":1,"n":28,"s":"학개론","q":"모기지(mortgage) 유동화에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["MPTS(mortgage pass-through securities)는 지분형 증권이다.","MPTB(mortgage pay-through bond)의 경우, 조기상환위험은 증권발행자가 부담하고, 채무불이행 위험은 투자자가 부담한다.","MBB(mortgage backed bond)의 경우, 신용보강을 위한 초과담보가 필요하다.","CMO(collateralized mortgage obligation)는 상환우선순위와 만기가 다른 다수의 층(tranche)으로 구성된 증권이다.","우리나라의 모기지 유동화중개기관으로는 한국주택금융공사가 있다."],"a":[2],"L":"학6-2","o":"기출","x":{"한줄":"MPTB는 저당채권의 소유권을 발행자가 갖기 때문에 채무불이행위험은 발행자가 부담하고, 원리금 수취권이 투자자에게 있어 조기상환위험은 투자자가 부담한다.","근거":[{"이론":"MPTS·MPTB·MBB·CMO의 구조","내용":"MPTS는 지분형으로 소유권·원리금 수취권·조기상환위험이 투자자에게 있고 초과담보가 없다. MPTB는 혼합형으로 소유권은 발행자, 원리금 수취권과 조기상환위험은 투자자이다. MBB는 채권형으로 소유권·원리금 수취권·조기상환위험이 발행자에게 있고 초과담보를 제공한다. CMO는 상환순위·만기가 다른 여러 트랜치로 발행한다."},{"법령":"한국주택금융공사법","조문":"제2조제1호","원문":"1. \"채권유동화\"란 다음 각 목의 어느 하나에 해당하는 것을 말한다.\n가. 한국주택금융공사(이하 \"공사\"라 한다)가 금융기관으로부터 양수한 주택저당채권을 담보로 하여 주택저당채권담보부채권을 발행하고 그 소지자에게 원리금을 지급하는 행위\n나. 공사가 금융기관으로부터 양수한 주택저당채권을 기초로 주택저당증권을 발행하고 그 수익자에게 주택저당채권의 관리ㆍ운용 및 처분으로 생긴 수익을 분배하는 행위"}],"선지":[{"번호":1,"판정":"옳음","설명":"MPTS는 소유권과 원리금 수취권이 모두 투자자에게 넘어가는 지분형 증권이다."},{"번호":2,"판정":"틀림","설명":"MPTB의 조기상환위험은 원리금 수취권을 가진 투자자가 부담하고, 채무불이행위험은 소유권을 가진 발행자가 부담한다."},{"번호":3,"판정":"옳음","설명":"MBB는 발행자가 저당채권을 보유한 채 채권을 발행하므로 신용보강을 위한 초과담보가 필요하다."},{"번호":4,"판정":"옳음","설명":"CMO는 상환우선순위와 만기가 다른 여러 트랜치로 구성한다."},{"번호":5,"판정":"옳음","설명":"한국주택금융공사가 주택저당채권을 양수해 주택저당채권담보부채권과 주택저당증권을 발행한다(한국주택금융공사법 제2조제1호)."}],"개념":[{"종류":"표","제목":"MBS 세 가지 — 누가 무엇을 갖나","머리":["구분","MPTS","MPTB","MBB"],"행":[["성격","지분형","혼합형","채권형"],["저당채권 소유권","투자자","발행자","발행자"],["원리금 수취권","투자자","투자자","발행자"],["조기상환위험","투자자","투자자","발행자"],["채무불이행위험","투자자","발행자","발행자"],["초과담보","없음","-","발행자가 제공"]]},{"종류":"흐름","제목":"주택저당채권이 증권이 되기까지","단계":[{"이름":"1차 저당시장","설명":"차주가 금융기관에서 주택담보대출을 받아 주택저당채권이 생긴다"},{"이름":"유동화중개기관","설명":"한국주택금융공사가 금융기관에서 주택저당채권을 양수한다"},{"이름":"MBS 발행","설명":"양수한 채권을 기초로 증권을 발행해 투자자에게 판다(2차 저당시장)"},{"이름":"자금 환류","설명":"판매대금이 금융기관으로 돌아가 다시 대출 재원이 된다"}]}],"함정":"조기상환위험과 채무불이행위험의 부담 주체를 서로 바꿔 쓴 보기가 정답이다. 소유권을 가진 쪽이 채무불이행위험을, 원리금 수취권을 가진 쪽이 조기상환위험을 진다고 기억하면 구분된다."}},{"i":"S3-1-1-학개론-29","r":"S3","g":1,"c":1,"n":29,"s":"학개론","q":"부동산투자회사(REITs)와 프로젝트 금융에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["프로젝트 금융(PF)은 사업주의 신용이 아니라 프로젝트의 사업성과 장래 현금흐름을 바탕으로 자금을 조달하는 방식이다.","자기관리 부동산투자회사는 자산운용 전문인력을 포함한 임직원을 상근으로 두고 자산의 투자·운용을 직접 수행한다.","주주 1인과 그 특별관계자는 주식 공모를 완료한 이후 부동산투자회사가 발행한 주식 총수의 100분의 30을 초과하여 소유하지 못한다.","위탁관리 부동산투자회사는 영업인가를 받거나 등록을 한 날부터 6개월이 지나면 자본금이 50억원 이상이어야 한다.","부동산투자회사의 자금차입과 사채발행은 원칙적으로 자기자본의 2배를 초과할 수 없으나, 주주총회 특별결의를 거치면 자기자본의 10배까지 할 수 있다."],"a":[3],"L":"학6-3","o":"변형","x":{"한줄":"1인당 주식소유한도는 발행주식 총수의 100분의 50이다. 100분의 30은 영업인가·등록 후 3년 안에 공모해야 하는 최소 비율이다.","근거":[{"법령":"부동산투자회사법","조문":"제15조제1항","원문":"① 주주 1인과 그 특별관계자는 제14조의8제2항에 따른 주식의 공모를 완료한 이후에는 부동산투자회사가 발행한 주식 총수의 100분의 50(이하 \"1인당 주식소유한도\"라 한다)을 초과하여 주식을 소유하지 못한다."},{"법령":"부동산투자회사법","조문":"제10조","원문":"2. 위탁관리 부동산투자회사 및 기업구조조정 부동산투자회사: 50억원"},{"법령":"부동산투자회사법","조문":"제29조제2항","원문":"② 제1항에 따른 자금차입 및 사채발행은 자기자본의 2배를 초과할 수 없다. 다만, 「상법」 제434조의 결의 방법에 따른 주주총회의 특별결의를 한 경우에는 그 합계가 자기자본의 10배를 넘지 아니하는 범위에서 자금차입 및 사채발행을 할 수 있다."},{"법령":"부동산투자회사법","조문":"제2조제1호가목","원문":"가. 자기관리 부동산투자회사: 자산운용 전문인력을 포함한 임직원을 상근으로 두고 자산의 투자ㆍ운용을 직접 수행하는 회사"}],"선지":[{"번호":1,"판정":"옳음","설명":"PF는 사업주와 분리된 프로젝트의 사업성과 현금흐름·사업자산을 상환재원으로 삼는다. 위험은 이해관계자 간 계약으로 나눈다."},{"번호":2,"판정":"옳음","설명":"자기관리 리츠는 임직원을 상근으로 두고 직접 운용한다(제2조제1호가목). 위탁관리·기업구조조정 리츠는 자산관리회사에 위탁한다."},{"번호":3,"판정":"틀림","설명":"1인당 주식소유한도는 발행주식 총수의 100분의 50이다(제15조제1항). 100분의 30은 주식 공모의 최소 비율(제14조의8제2항)이다."},{"번호":4,"판정":"옳음","설명":"위탁관리·기업구조조정 리츠는 영업인가·등록 후 6개월이 지나면 자본금 50억원 이상이어야 한다(제10조제2호). 자기관리 리츠는 70억원이다."},{"번호":5,"판정":"옳음","설명":"자금차입·사채발행 한도는 자기자본의 2배이고, 주주총회 특별결의를 거치면 10배까지 가능하다(제29조제2항)."}],"개념":[{"종류":"표","제목":"부동산투자회사(리츠) 수치 정리","머리":["항목","내용","근거"],"행":[["설립 자본금","자기관리 5억원 이상, 위탁관리·기업구조조정 3억원 이상","제6조"],["최저자본금(인가·등록 후 6개월)","자기관리 70억원, 위탁관리·기업구조조정 50억원","제10조"],["주식 공모","인가·등록 후 3년(프로젝트 리츠는 5년) 이내 발행주식 총수의 100분의 30 이상","제14조의8제2항"],["1인당 주식소유한도","발행주식 총수의 100분의 50","제15조제1항"],["자금차입·사채발행","자기자본의 2배(특별결의 시 10배)","제29조제2항"],["배당","이익배당한도의 100분의 90 이상(자기관리는 100분의 50 이상)","제28조"],["자산 구성","매 분기 말 총자산의 100분의 80 이상을 부동산·관련 증권·현금, 그중 100분의 70 이상은 부동산","제25조제1항"]]},{"종류":"비교","제목":"프로젝트 금융과 기업금융","왼쪽":{"이름":"프로젝트 금융","항목":["대출 판단 기준은 프로젝트의 사업성과 현금흐름","상환재원은 프로젝트에서 나오는 현금흐름","프로젝트 자산·계약을 담보로 삼는다","별도의 프로젝트회사를 세워 비소구 또는 제한소구로 진행한다","위험은 이해관계자 간 계약으로 배분한다"]},"오른쪽":{"이름":"기업금융","항목":["대출 판단 기준은 차입 기업의 신용과 재무상태","상환재원은 기업 전체의 현금흐름","기업의 일반 재산이 책임재산","차입은 기업의 재무제표에 부채로 계상된다"]}}],"함정":"공모 비율 30과 1인당 소유한도 50을 바꿔 쓴 보기가 정답이다. 자본금도 설립 때(5억·3억)와 6개월 후(70억·50억)로 나뉜다."}},{"i":"S3-1-1-학개론-30","r":"S3","g":1,"c":1,"n":30,"s":"학개론","q":"부동산개발에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["워포드(Wofford)의 개발 7단계에서 부지의 모색·확보 단계는 타당성 분석 단계보다 앞선다.","BOT(build-operate-transfer)방식은 민간이 시설을 준공한 뒤 일정 기간 소유·운영하다가 기간이 끝나면 소유권을 공공에 이전하는 방식이다.","환지방식은 개발 전 토지의 권리를 개발 후 조성된 토지에 재분배하는 방식으로, 개발이익이 종전 토지소유자에게 돌아간다.","BTL(build-transfer-lease)방식은 민간이 준공한 시설의 소유권을 공공에 귀속시킨 뒤 이용자에게서 받는 사용료로 투자비를 회수하는 방식이다.","시장성분석 단계에서는 개발할 부동산이 시장에서 매매되거나 임대될 수 있는지와 그 속도인 흡수율을 분석한다."],"a":[4],"L":"학7-1","o":"변형","x":{"한줄":"이용자에게서 사용료를 받아 투자비를 회수하는 방식은 BTO이다. BTL은 공공이 시설을 임차해 지급하는 임대료로 회수한다.","근거":[{"이론":"민간투자사업의 방식","내용":"BTO는 준공 때 소유권을 공공에 이전하고 민간이 운영하며 이용자 사용료로 회수한다. BTL은 준공 때 소유권을 공공에 이전하고 민간이 운영하며 공공이 임차해 임대료를 지급한다. BOT는 민간이 소유·운영하다 기간이 끝나면 공공에 이전한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"개발 7단계는 아이디어→예비적 타당성 분석→부지 모색·확보→타당성 분석→금융→건설→마케팅 순이다."},{"번호":2,"판정":"옳음","설명":"BOT는 준공 후 민간이 소유·운영하고 기간이 끝나면 공공에 이전한다."},{"번호":3,"판정":"옳음","설명":"환지방식은 종전 토지의 권리를 개발 후 토지로 바꿔 주므로 개발이익이 종전 소유자에게 돌아간다."},{"번호":4,"판정":"틀림","설명":"BTL은 공공이 시설을 임차해 임대료를 지급하고 민간이 그 임대료로 투자비를 회수한다. 이용자 사용료로 회수하는 방식은 BTO이다."},{"번호":5,"판정":"옳음","설명":"시장성분석은 개발된 부동산이 시장에서 매매·임대될 가능성을 분석하는 단계이며 흡수율 분석이 들어간다."}],"개념":[{"종류":"표","제목":"민간투자사업 방식 비교","머리":["구분","BTO","BTL","BOT","BOO","BLT"],"행":[["준공 때 소유권","공공","공공","민간","민간","민간"],["운영 기간 중 투자비 회수","이용자 사용료","공공이 임차해 지급하는 임대료","민간이 소유·운영하며 회수","민간이 소유·운영하며 회수","민간이 소유하며 임대"],["기간이 끝나면","이미 공공 소유","이미 공공 소유","공공에 이전","이전 없음","공공에 이전"]]},{"종류":"흐름","제목":"워포드의 개발 7단계","단계":[{"이름":"아이디어","설명":"개발 구상"},{"이름":"예비적 타당성 분석","설명":"수입·비용을 개략적으로 추정"},{"이름":"부지 모색·확보","설명":"땅을 찾고 확보"},{"이름":"타당성 분석","설명":"법률·기술·경제 측면을 세부적으로 검토"},{"이름":"금융","설명":"자금 조달"},{"이름":"건설","설명":"공사"},{"이름":"마케팅","설명":"분양·임대"}]}],"함정":"BTO와 BTL의 투자비 회수 방식을 바꿔 쓴 보기가 정답이다. 두 방식 모두 준공 때 소유권이 공공에 넘어간다. 이용자가 내는 돈이면 BTO, 공공이 내는 임대료이면 BTL이다."}},{"i":"S3-1-1-학개론-31","r":"S3","g":1,"c":1,"n":31,"s":"학개론","q":"부동산 개발사업에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["사업위탁(수탁)방식은 토지소유자가 개발업자에게 토지 소유권을 이전하고, 개발업자가 사업 명의로 개발한 뒤 수수료를 받는 방식이다.","민관합동개발은 공공과 민간이 역할을 나누어 공동으로 개발하는 방식이다.","환지방식은 수용방식에 비해 사업시행자의 토지 매입 부담이 작다.","수용방식은 구역 안 토지를 보상하고 매수하므로, 보상금을 받은 소유자의 대토 수요가 구역 밖 지가를 올리는 요인이 될 수 있다.","도시개발법령상 도시개발사업의 시행방식에는 수용 또는 사용방식, 환지방식, 이를 혼용하는 방식이 있다."],"a":[1],"L":"학7-1","o":"변형","x":{"한줄":"사업위탁방식은 토지 소유권이 소유자에게 그대로 있고 개발업자는 수수료를 받는다. 소유권을 신탁회사로 형식상 이전하는 방식은 토지신탁이다.","근거":[{"법령":"도시개발법","조문":"제21조제1항","원문":"① 도시개발사업은 시행자가 도시개발구역의 토지등을 수용 또는 사용하는 방식이나 환지 방식 또는 이를 혼용하는 방식으로 시행할 수 있다."},{"이론":"사업위탁(수탁)방식과 토지신탁방식","내용":"사업위탁방식은 소유권이 소유자에게 남고 사업 명의도 소유자이며 개발업자는 수수료를 받는다. 토지신탁방식은 소유권이 신탁회사로 형식상 이전되고 신탁회사가 사업 명의로 개발하며 부족한 자금도 조달해 사업 뒤 수익을 소유자에게 돌려준다."}],"선지":[{"번호":1,"판정":"틀림","설명":"사업위탁방식은 소유권을 이전하지 않는다. 소유자가 사업 명의를 갖고 개발업자는 수수료만 받는다. 소유권 이전과 신탁회사의 사업 명의는 토지신탁방식의 특징이다."},{"번호":2,"판정":"옳음","설명":"민관합동개발은 지방자치단체 등 공공과 민간이 함께 참여해 역할을 나누는 방식이다."},{"번호":3,"판정":"옳음","설명":"환지방식은 토지를 사들이지 않고 개발 전 권리를 개발 후 토지로 바꿔 주므로 매입 부담이 작다. 대신 소유자 동의 등 절차가 복잡하다."},{"번호":4,"판정":"옳음","설명":"수용방식은 보상금이 대토 수요로 이어져 구역 밖 땅값이 오를 수 있다."},{"번호":5,"판정":"옳음","설명":"도시개발사업은 수용 또는 사용 방식, 환지 방식 또는 이를 혼용하는 방식으로 시행한다(도시개발법 제21조제1항)."}],"개념":[{"종류":"비교","제목":"수용(매수)방식과 환지방식","왼쪽":{"이름":"수용(매수)방식","항목":["구역 안 토지를 전부 사들인다","빠르지만 보상비·사업비·조성토지 매각 부담이 크다","보상금으로 대토 수요가 생겨 구역 밖 땅값이 오를 수 있다"]},"오른쪽":{"이름":"환지방식","항목":["개발 전 권리를 개발 후 토지로 다시 나누어 준다","소유자 동의 단계가 많아 절차가 복잡하다","개발이익이 종전 소유자에게 돌아간다"]}},{"종류":"비교","제목":"사업위탁방식과 토지신탁방식","왼쪽":{"이름":"사업위탁(수탁)방식","항목":["소유권은 소유자에게 그대로 있다","사업 명의는 소유자","개발업자는 수수료를 받는다"]},"오른쪽":{"이름":"토지신탁방식","항목":["소유권이 신탁회사로 형식상 이전된다","사업 명의는 신탁회사이며 부족 자금도 신탁회사가 조달한다","사업 뒤 수익을 소유자(수익자)에게 돌려준다"]}}],"함정":"'맡긴다'는 점은 같아서 소유권과 사업 명의를 따져야 구분된다. 소유권 이전이 있으면 토지신탁, 없으면 사업위탁이다."}},{"i":"S3-1-1-학개론-32","r":"S3","g":1,"c":1,"n":32,"s":"학개론","q":"부동산신탁에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["부동산신탁의 당사자는 위탁자, 수탁자, 수익자이며 위탁자가 수익자를 겸할 수 있다.","처분신탁은 소유자가 부동산 처분을 수탁자에게 맡기고, 수탁자가 처분이 끝날 때까지 관리업무를 함께 수행하는 신탁이다.","담보신탁은 위탁자가 소유 부동산을 수탁자에게 신탁하고 그 수익권을 담보로 금융기관에서 대출을 받는 방식이다.","분양관리신탁은 건축물 분양 시 사업부지를 신탁하고 분양대금의 자금관리를 신탁회사가 맡아 분양의 안전성을 높이는 방식이다.","관리신탁은 소유권이 위탁자에게 남아 있으므로 신탁회사가 등기부상 소유자가 되지 않은 채 관리업무를 수행한다."],"a":[5],"L":"학7-2","o":"변형","x":{"한줄":"관리신탁도 부동산의 소유권이 신탁회사로 형식상 이전된다. 신탁회사는 소유권을 이전받아 소유권관리·건물수선·임대차관리 등을 수행한다.","근거":[{"이론":"부동산신탁의 구조와 종류","내용":"당사자는 위탁자(소유자)·수탁자(신탁회사)·수익자이다. 관리신탁·처분신탁·담보신탁·토지(개발)신탁·분양관리신탁 모두 신탁재산의 소유권이 수탁자에게 형식상 이전된다. 관리신탁은 소유권관리·건물 유지·임대차관리를, 처분신탁은 처분과 처분 완료 때까지의 관리를, 담보신탁은 수익권을 담보로 한 대출을, 분양관리신탁은 부지 신탁과 분양자금 관리를 맡는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"신탁 당사자는 위탁자·수탁자·수익자이고, 위탁자 자신이 수익자가 되는 경우도 있다."},{"번호":2,"판정":"옳음","설명":"처분신탁은 처분방법이나 절차가 까다로운 부동산의 처분과 처분 완료 때까지의 관리를 수탁자가 맡는다."},{"번호":3,"판정":"옳음","설명":"담보신탁은 수익권을 담보로 금융기관 대출을 받는 방식이다."},{"번호":4,"판정":"옳음","설명":"분양관리신탁은 부지 신탁과 분양자금 관리로 분양의 투명성·안정성을 높인다."},{"번호":5,"판정":"틀림","설명":"관리신탁에서도 소유권은 신탁회사로 이전된다. 소유권이 이전되지 않는다는 서술이 틀렸다."}],"개념":[{"종류":"표","제목":"부동산신탁의 종류","머리":["종류","목적","수탁자(신탁회사)의 업무"],"행":[["관리신탁","부동산 관리를 맡김","소유권관리, 건물 수선·유지, 임대차관리"],["처분신탁","처분이 까다로운 부동산의 처분","처분업무와 처분 완료 때까지의 관리"],["담보신탁","부동산을 담보로 대출","수익권을 담보로 금융기관 대출이 이루어지게 함"],["토지(개발)신탁","토지 개발·분양·임대","개발 후 분양·임대하여 수익을 수익자에게 교부"],["분양관리신탁","분양의 투명성·안정성 확보","사업부지 신탁과 분양대금 자금관리"]]},{"종류":"흐름","제목":"부동산신탁의 진행","단계":[{"이름":"신탁계약","설명":"위탁자(소유자)와 수탁자(신탁회사)가 신탁계약을 맺는다"},{"이름":"소유권 이전","설명":"신탁재산의 소유권이 수탁자 명의로 형식상 이전된다"},{"이름":"신탁업무 수행","설명":"수탁자가 관리·처분·개발 등 신탁 목적에 맞게 업무를 수행한다"},{"이름":"수익 교부","설명":"신탁 수익을 수익자에게 돌려준다"}]}],"함정":"신탁이면 종류와 관계없이 소유권이 수탁자에게 형식상 이전된다는 점을 놓치면 관리신탁을 소유권 이전이 없는 제도로 오해한다."}},{"i":"S3-1-1-학개론-33","r":"S3","g":1,"c":1,"n":33,"s":"학개론","q":"부동산마케팅에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["부동산마케팅은 부동산상품을 수요자의 욕구에 맞게 상품을 개발하고 가격을 결정한 후 시장에서 유통, 촉진, 판매를 관리하는 일련의 과정이다.","STP전략은 대상 집단의 시장세분화(segmentation), 표적시장 선정(targeting), 포지셔닝(positioning)으로 구성된다.","시장세분화 전략은 부동산시장에서 마케팅활동을 수행하기 위하여 수요자의 집단을 세분하는 것이다.","표적시장 전략은 세분화된 시장을 통해 선정된 표적 집단을 대상으로 적합한 마케팅활동을 수행하는 것이다.","AIDA원리는 주의(attention), 관심(interest), 욕망(desire), 행동(action)의 단계를 통해 공급자의 욕구를 파악하여 마케팅 효과를 극대화하는 시장점유마케팅 전략의 하나이다."],"a":[5],"L":"학7-2","o":"기출","x":{"한줄":"AIDA 원리는 공급자가 아니라 소비자의 구매심리 단계(주의·관심·욕망·행동)를 따르는 고객점유 마케팅 전략이다. 시장점유 마케팅은 STP가 중심이다.","근거":[{"이론":"부동산마케팅 전략의 구분","내용":"시장점유 전략은 시장세분화·표적시장 선정·포지셔닝(STP)과 마케팅믹스(4P)로 공급자가 시장을 나누고 겨냥하는 전략이다. 고객점유 전략은 AIDA 원리로 소비자의 구매심리 단계에 맞추는 전략이다. 관계 마케팅은 고객과 장기적 관계를 유지하는 전략이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"부동산마케팅은 상품 개발, 가격 결정, 유통·촉진·판매 관리로 이어지는 과정이다."},{"번호":2,"판정":"옳음","설명":"STP는 시장세분화, 표적시장 선정, 포지셔닝으로 구성된다."},{"번호":3,"판정":"옳음","설명":"시장세분화는 수요자 집단을 세분하는 활동이다."},{"번호":4,"판정":"옳음","설명":"표적시장 전략은 세분된 시장에서 선정한 집단을 대상으로 마케팅활동을 하는 것이다."},{"번호":5,"판정":"틀림","설명":"AIDA는 공급자가 아니라 소비자의 구매심리를 파악하는 고객점유 마케팅 전략이다. 시장점유 마케팅 전략에 해당하는 것은 STP이다."}],"개념":[{"종류":"표","제목":"마케팅 전략 구분","머리":["구분","내용","중심"],"행":[["시장점유 전략","STP(시장세분화→표적시장 선정→포지셔닝)와 4P 믹스","공급자가 시장을 나누고 겨냥함"],["고객점유 전략","AIDA(주의→관심→욕망→행동)","소비자의 구매심리 단계"],["관계 마케팅","고객과의 장기적 관계 유지, 충성도 확보","기존 고객"]]},{"종류":"표","제목":"마케팅믹스 4P","머리":["요소","내용","부동산 예"],"행":[["제품(Product)","수요자 욕구에 맞는 상품 개발","입지·평면·단지 설계"],["가격(Price)","가격 결정","분양가·임대료·할인 정책"],["유통(Place)","판매 경로 관리","분양대행사·모델하우스·중개업소"],["촉진(Promotion)","광고·홍보·인적판매·판매촉진","광고, 견본주택 행사"]]}],"함정":"AIDA 문장은 앞부분이 맞아 보여 끝까지 읽지 않으면 놓친다. 공급자의 욕구와 시장점유 마케팅이라는 두 곳이 틀렸다."}},{"i":"S3-1-1-학개론-34","r":"S3","g":1,"c":1,"n":34,"s":"학개론","q":"부동산 마케팅 전략에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["마케팅믹스 4P 중 가격(price) 전략에는 광고, 홍보, 인적판매, 판매촉진이 포함된다.","표적시장 선정은 수요자 집단을 동질적인 소집단으로 나누는 단계이다.","STP 전략은 포지셔닝, 표적시장 선정, 시장세분화의 순서로 진행한다.","AIDA 원리는 주의, 욕망, 관심, 행동의 순서로 소비자의 구매심리를 파악한다.","포지셔닝은 표적시장의 고객 인식 속에 경쟁 상품과 구별되는 위치를 만드는 활동이다."],"a":[5],"L":"학7-2","o":"변형","x":{"한줄":"포지셔닝은 표적시장 고객의 인식 속에 경쟁 상품과 구별되는 위치를 만드는 활동이다.","근거":[{"이론":"STP와 4P, AIDA","내용":"STP는 시장세분화(수요자를 동질적인 소집단으로 나눔)→표적시장 선정(세분 시장 중 겨냥할 집단 선택)→포지셔닝(고객 인식 속의 위치 형성) 순서이다. 4P는 제품·가격·유통·촉진이고 광고·홍보·인적판매·판매촉진은 촉진이다. AIDA는 주의→관심→욕망→행동이다."}],"선지":[{"번호":1,"판정":"틀림","설명":"광고·홍보·인적판매·판매촉진은 촉진(promotion) 전략이다. 가격 전략은 분양가·임대료 결정이다."},{"번호":2,"판정":"틀림","설명":"수요자 집단을 동질적인 소집단으로 나누는 단계는 시장세분화이다. 표적시장 선정은 세분 시장 중 겨냥할 집단을 고르는 단계이다."},{"번호":3,"판정":"틀림","설명":"STP의 순서는 시장세분화→표적시장 선정→포지셔닝이다."},{"번호":4,"판정":"틀림","설명":"AIDA는 주의→관심→욕망→행동 순서이다. 관심(interest)이 욕망(desire)보다 앞선다."},{"번호":5,"판정":"옳음","설명":"포지셔닝은 STP의 마지막 단계로 경쟁 상품과 차별되는 위치를 고객 인식 속에 만든다."}],"개념":[{"종류":"표","제목":"STP 세 단계","머리":["순서","단계","내용"],"행":[["1","시장세분화(Segmentation)","수요자 집단을 일정 기준으로 동질적인 소집단으로 나눈다"],["2","표적시장 선정(Targeting)","세분 시장 중 겨냥할 집단을 고른다"],["3","포지셔닝(Positioning)","표적시장 고객의 인식 속에 경쟁 상품과 차별되는 위치를 만든다"]]},{"종류":"표","제목":"마케팅믹스 4P와 AIDA","머리":["구분","구성","한 줄 내용"],"행":[["4P","제품(Product)","수요자 욕구에 맞는 상품 개발"],["4P","가격(Price)","분양가·임대료 결정"],["4P","유통(Place)","판매 경로 관리"],["4P","촉진(Promotion)","광고·홍보·인적판매·판매촉진"],["AIDA","주의→관심→욕망→행동","소비자의 구매심리 단계"]]}],"함정":"STP 순서와 AIDA 순서를 한 칸씩 바꿔 놓은 보기가 있다. 세분화는 나누는 단계, 표적시장 선정은 고르는 단계, 포지셔닝은 위치를 만드는 단계이다."}},{"i":"S3-1-1-학개론-35","r":"S3","g":1,"c":1,"n":35,"s":"학개론","q":"다음 건물을 원가법으로 감정평가한 적산가액은? (단, 감가수정은 정액법에 의하며, 다른 조건은 동일함)","b":"· 기준시점 현재 재조달원가: 6억원\n· 경과연수: 12년\n· 경제적 내용연수: 40년\n· 내용연수 만료 시 잔존가치율: 10%","bs":"글자","img":[],"ch":["3.78억원","4.20억원","4.38억원","4.80억원","5.40억원"],"a":[3],"L":"학8-2","o":"신작","x":{"한줄":"정액법의 연 감가액은 6억원×(1−0.1)÷40년=0.135억원이고, 12년 누계 1.62억원을 재조달원가에서 빼면 적산가액은 4.38억원이다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제5호","원문":"5. \"원가법\"이란 대상물건의 재조달원가에 감가수정(減價修正)을 하여 대상물건의 가액을 산정하는 감정평가방법을 말한다."},{"법령":"감정평가에 관한 규칙","조문":"제2조제12호","원문":"12. \"감가수정\"이란 대상물건에 대한 재조달원가를 감액하여야 할 요인이 있는 경우에 물리적 감가, 기능적 감가 또는 경제적 감가 등을 고려하여 그에 해당하는 금액을 재조달원가에서 공제하여 기준시점에 있어서의 대상물건의 가액을 적정화하는 작업을 말한다."}],"선지":[{"번호":1,"판정":"-","설명":"재조달원가에 (1−12/40)을 곱하고 잔존가치율 0.9를 다시 곱한 값(6×0.7×0.9)이다. 잔존가치율은 감가액을 구할 때 한 번만 쓴다."},{"번호":2,"판정":"-","설명":"잔존가치를 0으로 보고 6−6×12/40으로 구한 값이다. 잔존가치율 10%가 주어졌으므로 감가액은 6×0.9×12/40=1.62억원이다."},{"번호":3,"판정":"-","설명":"연 감가액 0.135억원×12년=1.62억원을 빼서 6−1.62=4.38억원이다."},{"번호":4,"판정":"-","설명":"잔존가치 0.6억원을 4.20억원에 더한 값이다. 잔존가치는 감가액 계산에서 제외할 뿐 적산가액에 더하지 않는다."},{"번호":5,"판정":"-","설명":"감가수정 없이 재조달원가에 0.9만 곱한 값이다."}],"개념":[{"종류":"계산","제목":"정액법 적산가액","단계":[{"설명":"연 감가액","식":"6억원 × (1 − 0.1) ÷ 40년","값":"0.135억원"},{"설명":"감가누계액","식":"0.135억원 × 12년","값":"1.62억원"},{"설명":"적산가액","식":"6억원 − 1.62억원","값":"4.38억원"}]},{"종류":"표","제목":"감가수정 방법 세 가지","머리":["구분","정액법","정률법","상환기금법"],"행":[["매년 감가","감가액이 일정","감가율이 일정하여 감가액은 해마다 줄어듦","감채기금계수로 적립(이자 포함)"],["첫해 감가액","중간","가장 큼","가장 작음"],["적산가액","중간","가장 작음","가장 큼"],["어울리는 대상","건물 일반","기계·설비","-"]]}],"함정":"잔존가치율은 연 감가액을 구할 때 (1−잔존가치율)로 한 번 반영한다. 감가수정 후 다시 곱하거나 더하면 3.78억원·4.80억원이 나온다."}},{"i":"S3-1-1-학개론-36","r":"S3","g":1,"c":1,"n":36,"s":"학개론","q":"거래사례비교법으로 산정한 대상 토지의 비준가액은? (단, 다른 조건은 동일함)","b":"· 거래사례: ㎡당 500만원에 거래되었으며, 정상가격보다 10% 높게 거래된 것으로 확인됨\n· 거래시점부터 기준시점까지 지가가 4% 상승함\n· 지역요인: 대상 토지가 거래사례보다 10% 열세임\n· 개별요인: 대상 토지가 거래사례보다 10% 우세임\n· 대상 토지의 면적: 100㎡","bs":"글자","img":[],"ch":["4.68억원","4.73억원","4.78억원","5.15억원","5.66억원"],"a":[1],"L":"학8-2","o":"신작","x":{"한줄":"사례가격 500만원/㎡에 사정보정 100/110, 시점수정 1.04, 지역요인 0.90, 개별요인 1.10을 곱하면 ㎡당 468만원이고, 100㎡이면 4.68억원이다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제7호","원문":"7. \"거래사례비교법\"이란 대상물건과 가치형성요인이 같거나 비슷한 물건의 거래사례와 비교하여 대상물건의 현황에 맞게 사정보정(事情補正), 시점수정, 가치형성요인 비교 등의 과정을 거쳐 대상물건의 가액을 산정하는 감정평가방법을 말한다."}],"선지":[{"번호":1,"판정":"-","설명":"사정보정 100/110, 시점수정 1.04, 지역요인 0.90, 개별요인 1.10을 모두 곱한 값이다. 500×(100/110)×1.04×0.9×1.1=468만원/㎡, 100㎡이면 4.68억원이다."},{"번호":2,"판정":"-","설명":"지역요인과 개별요인을 빼고 사정보정·시점수정만 한 값(500×100/110×1.04=472.7만원/㎡)이다."},{"번호":3,"판정":"-","설명":"지역요인·개별요인 비교치를 대상 기준이 아니라 사례 기준(역수)으로 곱한 값이다. 비교치는 대상÷사례로 잡는다."},{"번호":4,"판정":"-","설명":"사정보정을 하지 않은 값(500×1.04×0.9×1.1=514.8만원/㎡)이다. 정상가격보다 10% 높게 거래되었으므로 100/110을 곱해야 한다."},{"번호":5,"판정":"-","설명":"사정보정을 110/100으로 거꾸로 곱한 값이다. 사정보정치는 정상가격÷거래가격이다."}],"개념":[{"종류":"계산","제목":"거래사례비교법 비준가액","단계":[{"설명":"사정보정","식":"500만원 × 100/110","값":"약 454.5만원/㎡"},{"설명":"시점수정","식":"× 1.04","값":"약 472.7만원/㎡"},{"설명":"지역요인 비교","식":"× 90/100","값":"약 425.5만원/㎡"},{"설명":"개별요인 비교","식":"× 110/100","값":"468만원/㎡"},{"설명":"면적 곱","식":"468만원 × 100㎡","값":"4억 6,800만원"}]},{"종류":"표","제목":"비준가액·공시지가기준법의 순서","머리":["구분","거래사례비교법","공시지가기준법"],"행":[["출발점","거래사례 가격","비교표준지 공시지가"],["거치는 단계","사정보정→시점수정→지역요인 비교→개별요인 비교→면적","시점수정→지역요인 비교→개별요인 비교→그 밖의 요인 보정"],["사정보정","있다","없다"],["비교치 방향","대상÷사례","대상÷비교표준지"],["적용 대상","토지·건물 일괄, 과수원, 자동차 등","토지"]]}],"함정":"사정보정은 사례가 비싸게 거래되었으면 1보다 작게(100/110), 싸게 거래되었으면 1보다 크게 잡는다. 지역요인과 개별요인 비교치는 대상을 사례로 나눈다."}},{"i":"S3-1-1-학개론-37","r":"S3","g":1,"c":1,"n":37,"s":"학개론","q":"다음 부동산을 직접환원법으로 감정평가한 수익가액은? (단, 모든 금액은 연간 기준이며, 다른 조건은 동일함)","b":"· 가능총소득: 1억 2,000만원\n· 공실 및 불량부채: 가능총소득의 10%\n· 기타 소득: 600만원\n· 영업경비: 4,200만원\n· 부채서비스액: 1,200만원\n· 감가상각비: 1,200만원\n· 환원율: 6%","bs":"글자","img":[],"ch":["8억원","10억원","11억원","12억원","14억원"],"a":[4],"L":"학8-2","o":"신작","x":{"한줄":"유효총소득 1억 1,400만원에서 영업경비 4,200만원을 뺀 순영업소득 7,200만원을 환원율 6%로 나누면 수익가액은 12억원이다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제2조제10호","원문":"10. \"수익환원법(收益還元法)\"이란 대상물건이 장래 산출할 것으로 기대되는 순수익이나 미래의 현금흐름을 환원하거나 할인하여 대상물건의 가액을 산정하는 감정평가방법을 말한다."}],"선지":[{"번호":1,"판정":"-","설명":"순영업소득에서 부채서비스액과 감가상각비까지 뺀 4,800만원을 환원한 값이다. 둘 다 영업경비가 아니다."},{"번호":2,"판정":"-","설명":"순영업소득에서 부채서비스액(또는 감가상각비) 1,200만원을 뺀 6,000만원을 환원한 값이다."},{"번호":3,"판정":"-","설명":"기타 소득 600만원을 더하지 않고 (1억 2,000만−1,200만−4,200만)=6,600만원을 환원한 값이다."},{"번호":4,"판정":"-","설명":"유효총소득 1억 1,400만원−영업경비 4,200만원=순영업소득 7,200만원, 7,200만원÷0.06=12억원이다."},{"번호":5,"판정":"-","설명":"공실 및 불량부채를 빼지 않고 (1억 2,000만+600만−4,200만)=8,400만원을 환원한 값이다."}],"개념":[{"종류":"계산","제목":"직접환원법 수익가액","단계":[{"설명":"공실 및 불량부채","식":"1억 2,000만원 × 10%","값":"1,200만원"},{"설명":"유효총소득","식":"1억 2,000만원 − 1,200만원 + 600만원","값":"1억 1,400만원"},{"설명":"순영업소득","식":"1억 1,400만원 − 4,200만원","값":"7,200만원"},{"설명":"수익가액","식":"7,200만원 ÷ 0.06","값":"12억원"}]},{"종류":"표","제목":"영업현금흐름 계산 순서","머리":["단계","계산","비고"],"행":[["가능총소득","임대료 × 임대 단위 수","-"],["유효총소득","− 공실·불량부채 + 기타소득","-"],["순영업소득","− 영업경비","수익환원법에서 환원하는 값"],["세전현금수지","− 부채서비스액(원금+이자)","영업경비 아님"],["세후현금수지","− 영업소득세","영업경비 아님"]]}],"함정":"부채서비스액·감가상각비는 영업경비가 아니어서 순영업소득을 구할 때 빼지 않는다. 기타 소득은 유효총소득에 더하고, 공실·불량부채는 뺀다."}},{"i":"S3-1-1-학개론-38","r":"S3","g":1,"c":1,"n":38,"s":"학개론","q":"감정평가에 관한 규칙상 시장가치기준에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["대상물건에 대한 감정평가액은 원칙적으로 시장가치를 기준으로 결정한다.","감정평가법인등은 법령에 다른 규정이 있는 경우에는 대상물건의 감정평가액을 시장가치 외의 가치를 기준으로 결정할 수 있다.","감정평가법인등은 대상물건의 특성에 비추어 사회통념상 필요하다고 인정되는 경우에는 대상물건의 감정평가액을 시장가치 외의 가치를 기준으로 결정할 수 있다.","감정평가법인등은 감정평가 의뢰인이 요청하여 시장가치 외의 가치를 기준으로 감정평가할 때에는 해당 시장가치 외의 가치의 성격과 특징을 검토하지 않는다.","감정평가법인등은 시장가치 외의 가치를 기준으로 하는 감정평가의 합리성 및 적법성이 결여(缺如)되었다고 판단할 때에는 의뢰를 거부하거나 수임(受任)을 철회할 수 있다."],"a":[4],"L":"학8-3","o":"기출","x":{"한줄":"시장가치 외의 가치를 기준으로 감정평가할 때에는 그 가치의 성격과 특징을 검토해야 한다(법령에 다른 규정이 있는 경우는 제외).","근거":[{"법령":"감정평가에 관한 규칙","조문":"제5조제1항","원문":"① 대상물건에 대한 감정평가액은 시장가치를 기준으로 결정한다."},{"법령":"감정평가에 관한 규칙","조문":"제5조제2항","원문":"② 감정평가법인등은 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 대상물건의 감정평가액을 시장가치 외의 가치를 기준으로 결정할 수 있다.\n1. 법령에 다른 규정이 있는 경우\n2. 감정평가 의뢰인(이하 \"의뢰인\"이라 한다)이 요청하는 경우\n3. 감정평가의 목적이나 대상물건의 특성에 비추어 사회통념상 필요하다고 인정되는 경우"},{"법령":"감정평가에 관한 규칙","조문":"제5조제3항","원문":"③ 감정평가법인등은 제2항에 따라 시장가치 외의 가치를 기준으로 감정평가할 때에는 다음 각 호의 사항을 검토해야 한다. 다만, 제2항제1호의 경우에는 그렇지 않다."},{"법령":"감정평가에 관한 규칙","조문":"제5조제4항","원문":"④ 감정평가법인등은 시장가치 외의 가치를 기준으로 하는 감정평가의 합리성 및 적법성이 결여(缺如)되었다고 판단할 때에는 의뢰를 거부하거나 수임(受任)을 철회할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"감정평가액은 시장가치를 기준으로 결정하는 것이 원칙이다(제5조제1항)."},{"번호":2,"판정":"옳음","설명":"법령에 다른 규정이 있으면 시장가치 외의 가치를 기준으로 결정할 수 있다(제5조제2항제1호)."},{"번호":3,"판정":"옳음","설명":"감정평가의 목적이나 대상물건의 특성에 비추어 사회통념상 필요하다고 인정되면 시장가치 외의 가치를 기준으로 할 수 있다(제5조제2항제3호)."},{"번호":4,"판정":"틀림","설명":"시장가치 외의 가치를 기준으로 할 때에는 그 가치의 성격과 특징, 감정평가의 합리성과 적법성을 검토해야 한다(제5조제3항). 법령에 다른 규정이 있는 경우만 검토를 면한다."},{"번호":5,"판정":"옳음","설명":"합리성과 적법성이 결여되었다고 판단하면 의뢰를 거부하거나 수임을 철회할 수 있다(제5조제4항)."}],"개념":[{"종류":"표","제목":"시장가치 외의 가치를 기준으로 할 수 있는 경우","머리":["사유","검토 사항","합리성·적법성 결여 시"],"행":[["법령에 다른 규정이 있는 경우","검토하지 않는다","-"],["의뢰인이 요청하는 경우","그 가치의 성격과 특징, 합리성과 적법성","의뢰 거부·수임 철회 가능"],["목적이나 대상물건의 특성상 사회통념상 필요한 경우","그 가치의 성격과 특징, 합리성과 적법성","의뢰 거부·수임 철회 가능"]]},{"종류":"표","제목":"기본적 사항의 확정과 용어","머리":["용어·원칙","내용","근거"],"행":[["시장가치","통상적인 시장에서 충분한 기간 공개된 뒤 정통한 당사자 사이에 신중하고 자발적인 거래가 있을 경우 성립될 가능성이 가장 높다고 인정되는 가액","제2조제1호"],["기준시점","감정평가액을 결정하는 기준이 되는 날짜(가격조사를 완료한 날짜가 원칙)","제2조제2호, 제9조제2항"],["기준가치","감정평가의 기준이 되는 가치","제2조제3호"],["현황기준","기준시점의 이용상황(불법적·일시적 이용 제외)과 공법상 제한을 받는 상태 기준","제6조제1항"],["감정평가조건","기준시점의 가치형성요인 등을 실제와 다르게 가정하거나 특수한 경우로 한정하는 조건","제6조제2항"]]}],"함정":"시장가치 외의 가치를 쓸 수 있는 세 사유 중 법령 규정 하나만 검토 의무가 없다. 의뢰인이 요청한 경우에도 성격·특징을 검토해야 한다."}},{"i":"S3-1-1-학개론-39","r":"S3","g":1,"c":1,"n":39,"s":"학개론","q":"감정평가에 관한 규칙상 대상물건별 주된 감정평가방법으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["항공기 - 원가법","과수원 - 수익환원법","영업권 - 수익환원법","구분소유권의 대상이 되는 건물부분과 그 대지사용권의 일괄 - 거래사례비교법","비상장채권 - 수익환원법"],"a":[2],"L":"학8-3","o":"변형","x":{"한줄":"과수원은 거래사례비교법을 적용한다(제18조). 수익환원법은 광업재단·영업권 등 무형자산·비상장채권·기업가치에 쓴다.","근거":[{"법령":"감정평가에 관한 규칙","조문":"제18조","원문":"제18조(과수원의 감정평가) 감정평가법인등은 과수원을 감정평가할 때에 거래사례비교법을 적용해야 한다."},{"법령":"감정평가에 관한 규칙","조문":"제16조","원문":"감정평가법인등은 「집합건물의 소유 및 관리에 관한 법률」에 따른 구분소유권의 대상이 되는 건물부분과 그 대지사용권을 일괄하여 감정평가하는 경우 등 제7조제2항에 따라 토지와 건물을 일괄하여 감정평가할 때에는 거래사례비교법을 적용해야 한다. 이 경우 감정평가액은 합리적인 기준에 따라 토지가액과 건물가액으로 구분하여 표시할 수 있다."},{"법령":"감정평가에 관한 규칙","조문":"제20조제4항","원문":"④ 감정평가법인등은 항공기를 감정평가할 때에 원가법을 적용해야 한다."},{"법령":"감정평가에 관한 규칙","조문":"제23조제3항","원문":"③ 감정평가법인등은 영업권, 특허권, 실용신안권, 디자인권, 상표권, 저작권, 전용측선이용권(專用側線利用權), 그 밖의 무형자산을 감정평가할 때에 수익환원법을 적용해야 한다."},{"법령":"감정평가에 관한 규칙","조문":"제24조제2항제2호","원문":"2. 비상장채권(거래소에서 거래가 이루어지지 아니하는 등 형성된 시세가 없는 채권을 말한다): 수익환원법을 적용할 것"}],"선지":[{"번호":1,"판정":"옳음","설명":"항공기는 원가법을 적용한다(제20조제4항)."},{"번호":2,"판정":"틀림","설명":"과수원은 거래사례비교법을 적용한다(제18조)."},{"번호":3,"판정":"옳음","설명":"영업권·특허권·상표권 등 무형자산은 수익환원법을 적용한다(제23조제3항)."},{"번호":4,"판정":"옳음","설명":"구분소유권의 대상이 되는 건물부분과 대지사용권을 일괄하여 평가하면 거래사례비교법을 적용한다(제16조)."},{"번호":5,"판정":"옳음","설명":"비상장채권은 수익환원법을 적용한다(제24조제2항제2호)."}],"개념":[{"종류":"표","제목":"물건별 주된 감정평가방법","머리":["대상물건","주된 방법","근거"],"행":[["토지","공시지가기준법","제14조제1항"],["토지(적정한 실거래가 기준)","거래사례비교법","제14조제3항"],["건물","원가법","제15조제1항"],["토지와 건물의 일괄","거래사례비교법","제16조"],["산림(산지와 입목은 구분)","입목은 거래사례비교법(소경목림은 원가법 가능), 산지와 입목 일괄은 거래사례비교법","제17조"],["과수원","거래사례비교법","제18조"],["공장재단","구성 물건의 개별 감정평가액 합산(일괄 시 수익환원법 가능)","제19조제1항"],["광업재단","수익환원법","제19조제2항"],["자동차","거래사례비교법","제20조제1항"],["건설기계·항공기","원가법","제20조제2항·제4항"],["선박","선체·기관·의장별로 구분하여 각각 원가법","제20조제3항"],["동산","거래사례비교법(기계·기구류는 원가법)","제21조"],["임대료","임대사례비교법","제22조"],["영업권 등 무형자산","수익환원법","제23조제3항"],["상장주식·상장채권","거래사례비교법","제24조"],["비상장채권·기업가치","수익환원법","제24조제2항·제3항"]]},{"종류":"흐름","제목":"감정평가의 절차 (규칙 제8조)","단계":[{"이름":"기본적 사항의 확정","설명":"의뢰인, 대상물건, 목적, 기준시점, 감정평가조건, 기준가치 등을 의뢰인과 협의해 확정한다"},{"이름":"처리계획 수립","설명":"감정평가 처리계획을 세운다"},{"이름":"대상물건 확인","설명":"실지조사로 대상물건을 확인한다"},{"이름":"자료수집 및 정리","설명":"자료를 모으고 정리한다"},{"이름":"자료검토 및 가치형성요인의 분석","설명":"자료를 검토하고 일반요인·지역요인·개별요인을 분석한다"},{"이름":"감정평가방법의 선정 및 적용","설명":"주된 방법을 적용하고 다른 방식의 시산가액과 비교해 합리성을 검토한다"},{"이름":"감정평가액의 결정 및 표시","설명":"시산가액을 조정해 감정평가액을 결정하고 표시한다"}]}],"함정":"건설기계는 원가법이고 자동차는 거래사례비교법이다. 동산은 거래사례비교법이지만 기계·기구류는 원가법이다. 수익환원법을 쓰는 대상은 광업재단·무형자산·비상장채권·기업가치로 한정된다.","개정":"2023.9.14 개정으로 동산 중 기계·기구류는 원가법을 적용한다(제21조제2항 신설). 동산 일반은 거래사례비교법이다."}},{"i":"S3-1-1-학개론-40","r":"S3","g":1,"c":1,"n":40,"s":"학개론","q":"부동산 가격공시에 관한 법령상 부동산 가격공시제도에 관한 내용으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["표준주택으로 선정된 단독주택, 국세 또는 지방세 부과대상이 아닌 단독주택에 대하여는 개별주택가격을 결정·공시하지 아니할 수 있다.","표준주택가격은 국가·지방자치단체 등이 그 업무와 관련하여 개별주택가격을 산정하는 경우에 그 기준이 된다.","개별주택가격 및 공동주택가격은 주택시장의 가격정보를 제공하고, 국가·지방자치단체 등이 과세 등의 업무와 관련하여 주택의 가격을 산정하는 경우에 그 기준으로 활용될 수 있다.","개별주택가격에 이의가 있는 자는 그 결정·공시일부터 30일 이내에 서면(전자문서를 포함한다)으로 시장·군수 또는 구청장에게 이의를 신청할 수 있다.","시장·군수 또는 구청장은 공시기준일 이후에 토지의 분할, 합병이나 건축물의 신축 등이 발생한 경우에는 대통령령으로 정하는 날을 기준으로 하여 공동주택가격을 결정·공시하여야 한다."],"a":[5],"L":"학8-4","o":"기출","x":{"한줄":"공시기준일 이후 토지 분할·합병이나 건축물 신축 등이 생겨 공동주택가격을 따로 결정·공시하는 주체는 시장·군수·구청장이 아니라 국토교통부장관이다.","근거":[{"법령":"부동산 가격공시에 관한 법률","조문":"제18조제1항·제4항","원문":"① 국토교통부장관은 공동주택에 대하여 매년 공시기준일 현재의 적정가격(이하 \"공동주택가격\"이라 한다)을 조사ㆍ산정하여 제24조에 따른 중앙부동산가격공시위원회의 심의를 거쳐 공시하고, 이를 관계 행정기관 등에 제공하여야 한다. 다만, 대통령령으로 정하는 바에 따라 국세청장이 국토교통부장관과 협의하여 공동주택가격을 별도로 결정ㆍ고시하는 경우는 제외한다.\n④ 국토교통부장관은 공시기준일 이후에 토지의 분할ㆍ합병이나 건축물의 신축 등이 발생한 경우에는 대통령령으로 정하는 날을 기준으로 하여 공동주택가격을 결정ㆍ공시하여야 한다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제17조제2항","원문":"② 제1항에도 불구하고 표준주택으로 선정된 단독주택, 그 밖에 대통령령으로 정하는 단독주택에 대하여는 개별주택가격을 결정ㆍ공시하지 아니할 수 있다. 이 경우 표준주택으로 선정된 주택에 대하여는 해당 주택의 표준주택가격을 개별주택가격으로 본다."},{"법령":"부동산 가격공시에 관한 법률","조문":"제19조","원문":"① 표준주택가격은 국가ㆍ지방자치단체 등이 그 업무와 관련하여 개별주택가격을 산정하는 경우에 그 기준이 된다.\n② 개별주택가격 및 공동주택가격은 주택시장의 가격정보를 제공하고, 국가ㆍ지방자치단체 등이 과세 등의 업무와 관련하여 주택의 가격을 산정하는 경우에 그 기준으로 활용될 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"표준주택으로 선정된 단독주택과 대통령령으로 정하는 단독주택은 개별주택가격을 결정·공시하지 않을 수 있다. 표준주택은 그 표준주택가격을 개별주택가격으로 본다(제17조제2항)."},{"번호":2,"판정":"옳음","설명":"표준주택가격은 국가·지방자치단체 등이 개별주택가격을 산정하는 경우의 기준이 된다(제19조제1항)."},{"번호":3,"판정":"옳음","설명":"개별주택가격과 공동주택가격은 주택시장의 가격정보를 제공하고, 과세 등 업무의 주택 가격 산정에 기준으로 활용될 수 있다(제19조제2항)."},{"번호":4,"판정":"옳음","설명":"개별주택가격에 이의가 있으면 결정·공시일부터 30일 이내에 서면(전자문서 포함)으로 시장·군수·구청장에게 신청한다(제17조제8항, 제11조제1항)."},{"번호":5,"판정":"틀림","설명":"공시기준일 이후 분할·합병·신축 등이 있는 공동주택의 가격은 국토교통부장관이 결정·공시한다(제18조제4항)."}],"개념":[{"종류":"표","제목":"부동산 가격공시의 주체·기준일·기한","머리":["구분","공시 주체","공시기준일","결정·공시 기한","이의신청"],"행":[["표준지공시지가","국토교통부장관","1월 1일","-","공시일부터 30일 이내, 국토교통부장관"],["개별공시지가","시장·군수·구청장","1월 1일","매년 5월 31일까지","결정·공시일부터 30일 이내, 시장·군수·구청장"],["표준주택가격","국토교통부장관","1월 1일","-","공시일부터 30일 이내, 국토교통부장관"],["개별주택가격","시장·군수·구청장","1월 1일","매년 4월 30일까지","결정·공시일부터 30일 이내, 시장·군수·구청장"],["공동주택가격","국토교통부장관","1월 1일","매년 4월 30일까지","공시일부터 30일 이내, 국토교통부장관"]]},{"종류":"비교","제목":"주택가격 공시의 효력과 예외","왼쪽":{"이름":"표준주택가격·개별주택가격","항목":["표준주택가격은 개별주택가격을 산정하는 기준이 된다","개별주택가격은 주택시장 가격정보를 제공하고 과세 등 가격 산정의 기준으로 활용될 수 있다","표준주택으로 선정된 단독주택은 개별주택가격을 공시하지 않을 수 있고 표준주택가격을 개별주택가격으로 본다"]},"오른쪽":{"이름":"공동주택가격","항목":["표준·개별 구분 없이 국토교통부장관이 바로 공시한다","주택시장 가격정보를 제공하고 과세 등 가격 산정의 기준으로 활용될 수 있다","공시기준일 이후 분할·합병·신축 등이 있으면 국토교통부장관이 대통령령으로 정하는 날을 기준으로 결정·공시한다"]}}],"함정":"개별주택가격은 시장·군수·구청장이 결정하지만 공동주택가격은 국토교통부장관이 공시한다. 개별주택가격의 사후 공시를 공동주택에 그대로 옮겨 쓴 보기가 정답이다."}},{"i":"S3-1-1-민법-01","r":"S3","g":1,"c":1,"n":41,"s":"민법","q":"상대방 없는 단독행위에 해당하는 것은?","b":null,"bs":"없음","img":[],"ch":["착오로 인한 계약의 취소","무권대리로 체결된 계약에 대한 본인의 추인","미성년자의 법률행위에 대한 법정대리인의 동의","손자에 대한 부동산의 유증","이행불능으로 인한 계약의 해제"],"a":[4],"L":"민1-1","o":"기출","x":{"한줄":"유증은 유언자 한 사람의 의사표시만으로 성립하고 의사표시를 받을 상대방이 없는 단독행위이다.","근거":[{"법령":"민법","조문":"제1073조제1항","원문":"①유언은 유언자가 사망한 때로부터 그 효력이 생긴다."},{"법령":"민법","조문":"제1074조제1항","원문":"①유증을 받을 자는 유언자의 사망후에 언제든지 유증을 승인 또는 포기할 수 있다."},{"법령":"민법","조문":"제142조","원문":"취소할 수 있는 법률행위의 상대방이 확정한 경우에는 그 취소는 그 상대방에 대한 의사표시로 하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"취소는 상대방이 확정되어 있으면 그 상대방에 대한 의사표시로 한다(제142조). 상대방 있는 단독행위이다."},{"번호":2,"판정":"틀림","설명":"추인은 상대방에 대하여 하지 않으면 그 상대방에게 대항하지 못한다(제132조). 상대방 있는 단독행위이다."},{"번호":3,"판정":"틀림","설명":"동의는 동의를 받을 미성년자에게 하는 의사표시이다(제5조제1항). 상대방 있는 단독행위이다."},{"번호":4,"판정":"옳음","설명":"유증은 유언자의 단독 의사표시로 성립하고 유언자 사망 때 효력이 생긴다(제1073조제1항). 수증자의 승낙은 성립요건이 아니다."},{"번호":5,"판정":"틀림","설명":"해제는 상대방에 대한 의사표시로 한다(제543조제1항). 상대방 있는 단독행위이다."}],"개념":[{"종류":"표","제목":"법률행위의 구분: 의사표시의 수와 상대방","머리":["구분","특징","대표 예"],"행":[["상대방 없는 단독행위","의사표시 1개, 받을 사람 없음","유언·유증, 재단법인 설립(출연), 소유권 포기"],["상대방 있는 단독행위","의사표시 1개, 상대방에게 도달해야 함","취소·추인·동의·철회, 해제·해지, 채무면제, 상계"],["계약","서로 대립하는 의사표시 2개의 합치","매매·증여·임대차·사인증여"],["합동행위","방향이 같은 의사표시 여럿의 합치","사단법인 설립행위"]]},{"종류":"표","제목":"채권행위·물권행위·준물권행위","머리":["구분","효과","예"],"행":[["채권행위","채권·채무 발생","매매·임대차·증여"],["물권행위","물권 변동이 바로 생김","소유권이전의 합의와 등기, 저당권 설정"],["준물권행위","물권 이외의 권리가 바로 변동","채권양도, 채무면제"]]}],"함정":"유증을 받는 사람이 있으니 상대방이 있다고 보기 쉽다. 유증은 수증자의 승낙 없이 성립하고 승인·포기는 사망 뒤 따로 한다. 취소·추인·동의·해제는 모두 상대방에게 가는 의사표시다. 사인증여는 계약이어서 유증과 구별한다."}},{"i":"S3-1-1-민법-02","r":"S3","g":1,"c":1,"n":42,"s":"민법","q":"의사와 표시가 불일치하는 경우에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["통정허위표시의 무효로 대항할 수 없는 제3자에 해당하는지를 판단할 때, 파산관재인은 파산채권자 일부가 선의라면 선의로 다루어진다.","비진의 의사표시는 상대방이 표의자의 진의 아님을 알 수 있었을 경우 취소할 수 있다.","비진의 의사표시는 상대방과 통정이 없었다는 점에서 착오와 구분된다.","통정허위표시의 무효에 대항하려는 제3자는 자신이 선의라는 것을 증명하여야 한다.","매수인의 채무불이행을 이유로 매도인이 계약을 적법하게 해제했다면, 착오를 이유로 한 매수인의 취소권은 소멸한다."],"a":[1],"L":"민1-2","o":"기출","x":{"한줄":"파산관재인은 허위표시의 제3자이고, 파산채권자 전원이 악의가 아닌 한 선의로 다루어지므로 일부만 선의여도 선의이다.","근거":[{"판례":"대법원 2003. 6. 24. 선고 2002다48214","요지":"허위표시로 형성된 외형을 토대로 새로운 법률상 이해관계를 맺은 파산관재인은 제108조제2항의 제3자에 해당한다."},{"판례":"대법원 2006. 3. 10. 선고 2002다1321","요지":"제3자의 선의는 추정되고, 악의라는 사실은 허위표시의 무효를 주장하는 쪽이 증명한다. 제3자의 과실 유무는 따지지 않는다."},{"법령":"민법","조문":"제107조제1항","원문":"①의사표시는 표의자가 진의아님을 알고 한 것이라도 그 효력이 있다. 그러나 상대방이 표의자의 진의아님을 알았거나 이를 알 수 있었을 경우에는 무효로 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"파산관재인은 파산채권자 전원이 악의일 때에만 악의로 보고, 일부라도 선의이면 선의로 다룬다."},{"번호":2,"판정":"틀림","설명":"상대방이 진의 아님을 알았거나 알 수 있었으면 취소가 아니라 무효이다(제107조제1항 단서)."},{"번호":3,"판정":"틀림","설명":"통정이 없다는 점은 통정허위표시와 구분하는 기준이다. 착오와는 표의자가 의사와 표시의 불일치를 알고 있는지로 구분한다."},{"번호":4,"판정":"틀림","설명":"제3자의 선의는 추정된다. 무효를 주장하는 쪽이 제3자의 악의를 증명해야 한다(2002다1321)."},{"번호":5,"판정":"틀림","설명":"해제로 취소권이 사라진다는 규정은 없다. 취소권은 추인·법정추인(제143조~제145조)이나 제척기간 경과(제146조)로 소멸한다. 해제 뒤에도 착오 취소는 가능하다."}],"개념":[{"종류":"표","제목":"의사표시의 불일치와 하자 비교","머리":["유형","불일치 인식","효과","제3자 보호","조문"],"행":[["비진의표시","표의자가 안다","원칙 유효, 상대방이 알았거나 알 수 있었으면 무효","선의 제3자에게 대항 불가","제107조"],["통정허위표시","표의자가 알고 상대방과 통정","무효","선의 제3자에게 대항 불가","제108조"],["착오","표의자가 모른다","중요부분 착오이고 중과실이 없으면 취소","선의 제3자에게 대항 불가","제109조"],["사기·강박","의사결정이 방해됨","취소(제3자 사기는 상대방이 알았거나 알 수 있었을 때)","선의 제3자에게 대항 불가","제110조"]]},{"종류":"표","제목":"허위표시 무효에 대항 못하는 제3자","머리":["해당","해당하지 않음"],"행":[["가장채권의 양수인","당사자의 포괄승계인(상속인)"],["가장매수인에게서 저당권을 취득한 자","허위표시 당사자의 일반채권자(압류 전)"],["가장매수인의 압류·가압류 채권자","-"],["파산관재인","-"]]}],"함정":"선지 ③은 착오와 비진의의 구별 기준을 통정 유무로 잘못 잡았다. 선지 ④는 증명책임이 제3자가 아니라 무효를 주장하는 쪽에 있다. 선지 ②는 취소와 무효가 바뀌어 있다."}},{"i":"S3-1-1-민법-03","r":"S3","g":1,"c":1,"n":43,"s":"민법","q":"甲은 채권자의 강제집행을 피하려고 乙과 통정하여 자기 소유 X토지를 乙에게 매도한 것처럼 꾸미고 乙 명의로 소유권이전등기를 마쳤다. 이에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲과 乙 사이의 매매계약은 당사자 사이에서 무효이므로, 甲은 소유권에 기하여 乙 명의 등기의 말소를 청구할 수 있다.","乙이 X토지를 선의의 丙에게 매도하고 이전등기를 해 준 경우, 甲은 丙에게 매매의 무효를 대항하지 못한다.","乙의 채권자 丁이 선의로 X토지에 가압류집행을 한 경우, 甲은 丁에게 매매의 무효를 대항하지 못한다.","선의의 丙으로부터 X토지를 전득한 丁이 악의인 경우에도, 甲은 丁에게 매매의 무효를 대항하지 못한다.","丙이 제108조제2항의 제3자로 보호받으려면 선의일 뿐 아니라 무과실이어야 한다."],"a":[5],"L":"민1-2","o":"변형","x":{"한줄":"허위표시의 무효로 대항하지 못하는 제3자는 선의이면 족하고 과실 유무는 따지지 않는다.","근거":[{"법령":"민법","조문":"제108조","원문":"①상대방과 통정한 허위의 의사표시는 무효로 한다.\n②전항의 의사표시의 무효는 선의의 제삼자에게 대항하지 못한다."},{"판례":"대법원 2006. 3. 10. 선고 2002다1321","요지":"제3자는 선의 여부가 문제이고 과실 유무는 따질 것이 아니다. 선의는 추정되며 악의의 증명책임은 무효를 주장하는 자에게 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"통정허위표시는 당사자 사이에서 언제나 무효이다(제108조제1항). 甲은 소유자로서 말소를 구할 수 있다."},{"번호":2,"판정":"옳음","설명":"선의의 제3자에게는 무효를 대항하지 못한다(제108조제2항)."},{"번호":3,"판정":"옳음","설명":"가장매수인의 가압류 채권자는 외형을 토대로 새로운 이해관계를 맺은 제3자이고, 선의이면 보호된다."},{"번호":4,"판정":"옳음","설명":"선의의 제3자가 얻은 권리는 전득자가 악의여도 그대로 이어진다. 전득자에게도 무효를 대항하지 못한다."},{"번호":5,"판정":"틀림","설명":"제108조제2항은 선의만 요구한다. 선의는 추정되고 제3자의 과실은 따지지 않는다(2002다1321)."}],"개념":[{"종류":"비교","제목":"통정허위표시와 비진의표시","왼쪽":{"이름":"통정허위표시(제108조)","항목":["상대방과 통정","당사자 사이 언제나 무효","선의 제3자에게 대항 불가","은닉행위는 요건을 갖추면 유효(증여를 매매로 가장하면 증여는 유효할 수 있음)"]},"오른쪽":{"이름":"비진의표시(제107조)","항목":["상대방과 통정 없음","원칙적으로 유효","상대방이 알았거나 알 수 있었으면 무효","무효여도 선의 제3자에게 대항 불가"]}},{"종류":"표","제목":"통정허위표시의 법률관계","머리":["쟁점","결론","근거"],"행":[["당사자 사이","무효, 소유자는 말소 청구 가능","제108조제1항"],["선의 제3자","무효 대항 불가, 과실 불문","제108조제2항"],["선의 판단","선의 추정, 악의는 무효 주장자가 증명","판례"],["전득자","선의 제3자의 지위를 이어받음","판례"],["추인","소급효 없음, 새로운 행위로 봄","제139조"],["채권자취소권","허위표시 행위도 대상이 될 수 있음","제406조"]]}],"함정":"선지 ⑤는 제3자 보호요건에 무과실을 덧붙였다. 제108조제2항의 요건은 선의 하나다."}},{"i":"S3-1-1-민법-04","r":"S3","g":1,"c":1,"n":44,"s":"민법","q":"甲은 乙에게 자기 소유 X토지를 증여한다고 말했으나 이는 진의가 아니었다. 이에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["乙이 甲의 진의 아님을 알 수 있었던 경우, 甲은 증여의 의사표시를 취소할 수 있다.","甲의 대리인 A가 진의 아니게 증여의 의사표시를 한 경우, 진의 아닌 의사표시인지 여부는 본인 甲을 표준으로 정한다.","乙이 甲의 진의 아님을 알았던 경우, 증여는 무효이지만 乙로부터 X토지를 취득하여 등기한 선의의 丙에게 甲은 무효를 대항하지 못한다.","진의란 표의자가 진정으로 마음속에서 바라는 사항을 뜻한다.","乙이 선의·무과실인 경우, 甲은 착오를 이유로 증여의 의사표시를 취소할 수 있다."],"a":[3],"L":"민1-2","o":"변형","x":{"한줄":"비진의표시가 무효로 되는 경우에도 선의의 제3자에게는 무효를 대항하지 못한다.","근거":[{"법령":"민법","조문":"제107조","원문":"①의사표시는 표의자가 진의아님을 알고 한 것이라도 그 효력이 있다. 그러나 상대방이 표의자의 진의아님을 알았거나 이를 알 수 있었을 경우에는 무효로 한다.\n②전항의 의사표시의 무효는 선의의 제삼자에게 대항하지 못한다."},{"법령":"민법","조문":"제116조제1항","원문":"①의사표시의 효력이 의사의 흠결, 사기, 강박 또는 어느 사정을 알았거나 과실로 알지 못한 것으로 인하여 영향을 받을 경우에 그 사실의 유무는 대리인을 표준하여 결정한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"상대방이 진의 아님을 알았거나 알 수 있었으면 취소가 아니라 무효이다(제107조제1항 단서)."},{"번호":2,"판정":"틀림","설명":"대리행위의 하자는 대리인을 표준으로 정한다(제116조제1항)."},{"번호":3,"판정":"옳음","설명":"상대방이 알았으므로 무효이고(제107조제1항 단서), 그 무효는 선의의 제3자에게 대항하지 못한다(같은 조 제2항). 丙의 등기는 보호된다."},{"번호":4,"판정":"틀림","설명":"진의는 특정한 내용의 의사표시를 하고자 하는 표의자의 생각이다. 마음속으로 진정 바라는 사항이 아니다."},{"번호":5,"판정":"틀림","설명":"甲은 표시와 다른 의사임을 알고 있었으므로 착오(제109조)가 아니다. 乙이 선의·무과실이면 증여는 유효하다."}],"개념":[{"종류":"표","제목":"의사표시 하자의 효과와 제3자 보호","머리":["유형","효과","제3자 보호","특징"],"행":[["비진의표시","원칙 유효, 상대방 악의·과실이면 무효","선의 제3자","표의자가 불일치를 안다"],["통정허위표시","무효","선의 제3자","상대방과 통정"],["착오","취소","선의 제3자","표의자가 불일치를 모른다"],["사기·강박","취소","선의 제3자","제3자 사기·강박은 상대방 악의·과실 필요"]]},{"종류":"비교","제목":"대리행위의 하자 판단 기준","왼쪽":{"이름":"대리인을 표준(제116조제1항)","항목":["의사의 흠결(비진의·허위표시·착오)","사기·강박","악의·과실 유무"]},"오른쪽":{"이름":"본인의 사정이 문제되는 경우(제116조제2항)","항목":["특정 법률행위를 위임받은 대리인이 본인의 지시대로 행위한 때","본인이 안 사정, 과실로 몰랐던 사정은 대리인의 부지를 주장하지 못함"]}}],"함정":"선지 ②는 대리행위의 하자 판단 기준을 본인으로 잡았다. 선지 ⑤는 비진의와 착오가 섞여 있다. 비진의는 표의자가 불일치를 알고, 착오는 모른다."}},{"i":"S3-1-1-민법-05","r":"S3","g":1,"c":1,"n":45,"s":"민법","q":"대리권 없는 甲이 乙의 대리인으로서 丙과 X토지 매매계약을 체결하였다. 이에 관한 설명으로 틀린 것은? (표현대리는 고려하지 않으며, 다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["乙이 甲에게 추인의 의사표시를 한 경우, 丙이 그 사실을 알기 전에는 乙은 丙에게 추인의 효과를 주장하지 못한다.","계약 당시 甲에게 대리권이 없음을 알고 있던 丙은 乙이 추인하기 전이라도 계약을 철회할 수 없다.","계약 당시 대리권 없음을 몰랐던 丙은 乙이 추인할 때까지 乙 또는 甲에게 계약을 철회할 수 있다.","甲이 乙을 단독상속한 후 본인의 지위에서 추인을 거절하는 것은 신의칙에 반하여 허용되지 않는다.","甲이 미성년자인 경우에도 丙은 선택에 따라 甲에게 계약의 이행 또는 손해배상을 청구할 수 있다."],"a":[5],"L":"민1-3","o":"변형","x":{"한줄":"대리인으로 계약한 사람이 제한능력자이면 무권대리인의 책임을 지지 않는다.","근거":[{"법령":"민법","조문":"제135조","원문":"① 다른 자의 대리인으로서 계약을 맺은 자가 그 대리권을 증명하지 못하고 또 본인의 추인을 받지 못한 경우에는 그는 상대방의 선택에 따라 계약을 이행할 책임 또는 손해를 배상할 책임이 있다.\n② 대리인으로서 계약을 맺은 자에게 대리권이 없다는 사실을 상대방이 알았거나 알 수 있었을 때 또는 대리인으로서 계약을 맺은 사람이 제한능력자일 때에는 제1항을 적용하지 아니한다."},{"법령":"민법","조문":"제134조","원문":"대리권없는 자가 한 계약은 본인의 추인이 있을 때까지 상대방은 본인이나 그 대리인에 대하여 이를 철회할 수 있다. 그러나 계약당시에 상대방이 대리권 없음을 안 때에는 그러하지 아니하다."},{"판례":"대법원 1994. 9. 27. 선고 94다20617","요지":"무권대리인이 본인을 상속한 뒤 본인의 지위에서 추인을 거절하는 것은 신의칙에 반한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"추인·거절은 상대방에게 하지 않으면 그 상대방에게 대항하지 못한다. 상대방이 그 사실을 안 때에는 예외이다(제132조)."},{"번호":2,"판정":"옳음","설명":"계약 당시 대리권 없음을 안 상대방에게는 철회권이 없다(제134조 단서)."},{"번호":3,"판정":"옳음","설명":"선의의 상대방은 본인의 추인이 있을 때까지 본인이나 그 대리인에게 철회할 수 있다(제134조 본문)."},{"번호":4,"판정":"옳음","설명":"무권대리인이 본인을 상속하면 본인 지위에서 하는 추인 거절은 신의칙에 반한다(94다20617)."},{"번호":5,"판정":"틀림","설명":"무권대리인이 제한능력자이면 제135조제1항이 적용되지 않는다(제135조제2항)."}],"개념":[{"종류":"흐름","제목":"무권대리 계약의 처리 흐름","단계":[{"이름":"무권대리 계약","설명":"대리권 없는 자가 한 계약은 본인이 추인하지 않으면 본인에게 효력이 없다(제130조)"},{"이름":"본인의 선택","설명":"추인하면 계약 시에 소급해 유효, 제3자 권리는 해하지 못함(제133조). 거절하면 확정적 무효"},{"이름":"상대방의 선택","설명":"최고(선의·악의 불문): 기간 내 확답이 없으면 추인 거절로 봄(제131조). 철회(선의만): 추인 전까지(제134조)"},{"이름":"무권대리인 책임","설명":"추인도 대리권 증명도 없으면 상대방 선택으로 이행 또는 손해배상(제135조제1항)"}]},{"종류":"표","제목":"무권대리 상대방의 권리 비교","머리":["권리","요건","상대방 인식","조문"],"행":[["최고권","상당한 기간을 정해 추인 여부 확답 요구","선의·악의 불문","제131조"],["철회권","본인의 추인 전","계약 당시 선의일 것","제134조"],["무권대리인 책임","대리권 증명 불가, 추인 없음","대리권 없음을 알았거나 알 수 있었으면 면책, 대리인이 제한능력자여도 면책","제135조"]]}],"함정":"선지 ⑤는 무권대리인 책임의 면책사유를 놓치기 쉽다. 제135조제2항이 상대방의 악의·과실과 무권대리인의 제한능력을 면책사유로 둔다."}},{"i":"S3-1-1-민법-06","r":"S3","g":1,"c":1,"n":46,"s":"민법","q":"甲은 자신의 X토지를 매도하기 위하여 乙에게 대리권을 수여하였다. 이에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["乙이 미성년자인 경우, 乙이 한 대리행위는 乙의 법정대리인이 동의하지 않았다면 취소할 수 있다.","乙은 甲의 승낙이 있거나 부득이한 사유가 있으면 복대리인을 선임할 수 있다.","甲의 승낙을 얻어 丙을 복대리인으로 선임한 乙은 丙의 선임·감독에 관하여 책임이 없다.","복대리인 丙은 乙의 대리인이므로 乙의 이름으로 대리행위를 한다.","乙이 한정후견개시의 심판을 받으면 乙의 대리권은 소멸한다."],"a":[2],"L":"민1-3","o":"변형","x":{"한줄":"임의대리인은 본인의 승낙이 있거나 부득이한 사유가 있을 때에만 복대리인을 선임할 수 있다.","근거":[{"법령":"민법","조문":"제120조","원문":"대리권이 법률행위에 의하여 부여된 경우에는 대리인은 본인의 승낙이 있거나 부득이한 사유있는 때가 아니면 복대리인을 선임하지 못한다."},{"법령":"민법","조문":"제121조제1항","원문":"①전조의 규정에 의하여 대리인이 복대리인을 선임한 때에는 본인에게 대하여 그 선임감독에 관한 책임이 있다."},{"법령":"민법","조문":"제127조","원문":"대리권은 다음 각 호의 어느 하나에 해당하는 사유가 있으면 소멸된다.\n  1. 본인의 사망\n  2. 대리인의 사망, 성년후견의 개시 또는 파산"}],"선지":[{"번호":1,"판정":"틀림","설명":"대리인은 행위능력자임을 요하지 않는다(제117조). 미성년자의 대리행위는 제한능력을 이유로 취소할 수 없다."},{"번호":2,"판정":"옳음","설명":"임의대리인의 복임권은 제한된다(제120조). 본인의 승낙이나 부득이한 사유가 있어야 한다."},{"번호":3,"판정":"틀림","설명":"승낙을 얻어 선임해도 본인에 대한 선임·감독 책임이 있다(제121조제1항). 본인이 지명한 경우에만 책임이 줄어든다(같은 조 제2항)."},{"번호":4,"판정":"틀림","설명":"복대리인은 본인의 대리인이다. 그 권한 안에서 본인을 대리한다(제123조제1항)."},{"번호":5,"판정":"틀림","설명":"대리인에 관한 소멸사유는 성년후견의 개시이고 한정후견은 포함되지 않는다(제127조제2호)."}],"개념":[{"종류":"표","제목":"대리권의 소멸사유(제127조)","머리":["구분","소멸 사유","소멸사유가 아닌 것"],"행":[["본인","사망","-"],["대리인","사망, 성년후견 개시, 파산","한정후견 개시, 미성년자 신분"]]},{"종류":"표","제목":"복대리인 선임: 임의대리와 법정대리","머리":["구분","선임 가능","선임 책임"],"행":[["임의대리인","본인 승낙 또는 부득이한 사유(제120조)","본인에 대한 선임·감독 책임(제121조제1항). 본인이 지명했으면 부적임·불성실을 알고 통지·해임을 게을리한 때만 책임(제121조제2항)"],["법정대리인","자기 책임으로 언제든지(제122조)","전부 책임. 부득이한 사유로 선임했으면 선임·감독 책임만(제122조 단서)"],["복대리인의 지위","본인의 대리인(제123조제1항)","대리인과 동일한 권리·의무(제123조제2항)"]]}],"함정":"선지 ⑤는 한정후견과 성년후견이 섞여 있다. 선지 ④는 복대리인을 乙의 대리인으로 본 것인데, 복대리인은 본인을 대리한다."}},{"i":"S3-1-1-민법-07","r":"S3","g":1,"c":1,"n":47,"s":"민법","q":"행위능력자 乙은 대리권 없이 甲을 대리하여 甲이 보유하고 있던 매수인의 지위를 丙에게 양도하기로 약정하고, 이에 丙은 乙에게 계약금을 지급하였다. 乙은 그 계약금을 유흥비로 탕진하였다. 이에 관한 설명으로 틀린 것은? (단, 표현대리는 성립하지 않으며, 다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["매수인의 지위 양도계약 체결 당시 乙의 무권대리를 모른 丙은 甲의 추인이 있을 때까지 계약을 철회할 수 있다.","丙이 계약을 유효하게 철회하면, 무권대리행위는 확정적으로 무효가 된다.","丙이 계약을 유효하게 철회하면, 丙은 甲을 상대로 계약금 상당의 부당이득반환을 청구할 수 있다.","丙이 계약을 철회한 경우, 甲이 그 철회의 유효를 다투기 위해서는 乙에게 대리권이 없음을 丙이 알았다는 것에 대해 증명해야 한다.","丙의 계약 철회 전 甲이 사망하고 乙이 단독상속인이 된 경우, 乙이 선의ㆍ무과실인 丙에게 추인을 거절하는 것은 신의칙에 반한다."],"a":[3],"L":"민1-3","o":"기출","x":{"한줄":"계약금은 乙이 받아 탕진했고 甲에게 귀속된 이익이 없으므로 丙은 甲에게 부당이득반환을 청구할 수 없다.","근거":[{"법령":"민법","조문":"제134조","원문":"대리권없는 자가 한 계약은 본인의 추인이 있을 때까지 상대방은 본인이나 그 대리인에 대하여 이를 철회할 수 있다. 그러나 계약당시에 상대방이 대리권 없음을 안 때에는 그러하지 아니하다."},{"법령":"민법","조문":"제741조","원문":"법률상 원인없이 타인의 재산 또는 노무로 인하여 이익을 얻고 이로 인하여 타인에게 손해를 가한 자는 그 이익을 반환하여야 한다."},{"판례":"대법원 1994. 9. 27. 선고 94다20617","요지":"무권대리인이 본인을 상속한 뒤 본인의 지위에서 추인을 거절하는 것은 신의칙에 반한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"대리권 없음을 모른 상대방은 추인이 있을 때까지 철회할 수 있다(제134조 본문)."},{"번호":2,"판정":"옳음","설명":"철회하면 본인이 추인할 여지가 없어 무권대리행위는 확정적으로 효력이 없게 된다."},{"번호":3,"판정":"틀림","설명":"부당이득은 이익을 얻은 자에게 청구한다(제741조). 계약금은 乙이 가져가 탕진했고 甲은 받은 바 없다. 丙은 乙에게 책임을 물어야 한다(제135조)."},{"번호":4,"판정":"옳음","설명":"철회권은 선의의 상대방에게 있고(제134조 단서), 철회의 유효를 다투는 쪽이 상대방의 악의를 증명한다."},{"번호":5,"판정":"옳음","설명":"무권대리인이 본인을 상속한 뒤 추인을 거절하는 것은 신의칙에 반한다(94다20617)."}],"개념":[{"종류":"흐름","제목":"무권대리 상대방이 철회한 뒤의 법률관계","단계":[{"이름":"철회","설명":"선의의 상대방이 본인 또는 대리인에게 의사표시, 추인 전까지만 가능(제134조)"},{"이름":"효과","설명":"계약은 본인에게 확정적으로 효력 없음, 이후 추인 불가"},{"이름":"본인에 대한 청구","설명":"본인이 이익을 얻지 않았다면 부당이득반환 청구 불가(제741조)"},{"이름":"무권대리인에 대한 청구","설명":"대리권 증명 못 하고 추인 없으면 이행 또는 손해배상(제135조제1항). 상대방이 선의·무과실이고 대리인이 행위능력자일 때"}]},{"종류":"표","제목":"무권대리와 상속","머리":["상황","결론","근거"],"행":[["무권대리인이 본인을 상속","본인 지위에서 추인 거절은 신의칙 위반","94다20617"],["철회 후 본인의 추인","효력 없음","제134조"],["본인이 추인 전 사망","상속인이 추인·거절 권한을 이어받음","상속의 일반 법리"]]}],"함정":"선지 ③은 철회로 계약이 없어졌으니 건넨 돈을 본인에게 돌려받는다고 보기 쉽다. 돈은 본인이 받지 않았으므로 본인에게는 반환할 이익이 없다."}},{"i":"S3-1-1-민법-08","r":"S3","g":1,"c":1,"n":48,"s":"민법","q":"토지거래허가구역 내에 있는 甲 소유 X토지에 관하여 甲과 乙이 허가 없이 매매계약을 체결하였다. 이 계약이 확정적으로 무효는 아닌 경우, 이에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["乙이 허가 전에 매매대금을 지급했다면, 乙은 허가를 받기 전이라도 부당이득을 이유로 대금의 반환을 청구할 수 있다.","甲과 乙 중 한쪽은 상대방의 협조 없이 단독으로 토지거래허가를 신청할 수 있다.","허가구역 지정이 해제되면 위 계약은 허가 없이도 확정적으로 유효가 된다.","위 계약이 처음부터 허가를 배제하거나 잠탈하려는 내용이어도 유동적 무효 상태에 있다.","甲이 허가신청에 협력하지 않는 경우, 乙은 甲에게 협력의무의 이행을 소로써 청구할 수 없다."],"a":[3],"L":"민1-4","o":"변형","x":{"한줄":"허가 없이 체결되어 유동적 무효 상태인 계약은 허가구역 지정이 해제되면 확정적으로 유효가 된다.","근거":[{"판례":"대법원 1999. 6. 17. 선고 98다40459 전원합의체","요지":"허가구역 지정이 해제되거나 지정기간이 만료된 뒤 재지정이 없으면, 그 전에 확정적 무효가 된 경우가 아닌 한 유동적 무효 상태의 계약은 허가 없이도 확정적으로 유효가 된다. 허가를 배제하거나 잠탈하는 내용의 계약은 확정적 무효이다."},{"판례":"대법원 1991. 12. 24. 선고 90다12243 전원합의체","요지":"유동적 무효 상태에서 당사자는 허가신청에 협력할 의무를 지고, 협력하지 않는 상대방에게 그 이행을 소로 청구할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제11조제1항","원문":"① 허가구역에 있는 토지에 관한 소유권ㆍ지상권(소유권ㆍ지상권의 취득을 목적으로 하는 권리를 포함한다)을 이전하거나 설정(대가를 받고 이전하거나 설정하는 경우만 해당한다)하는 계약(예약을 포함한다. 이하 \"토지거래계약\"이라 한다)을 체결하려는 당사자는 공동으로 대통령령으로 정하는 바에 따라 시장ㆍ군수 또는 구청장의 허가를 받아야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"유동적 무효 상태에서는 이미 지급한 대금도 부당이득으로 돌려받을 수 없다. 불허가로 확정적 무효가 된 뒤에 반환을 청구할 수 있다(93다26397 전원합의체)."},{"번호":2,"판정":"틀림","설명":"허가는 당사자가 공동으로 신청한다(부동산 거래신고 등에 관한 법률 제11조제1항)."},{"번호":3,"판정":"옳음","설명":"지정 해제로 허가가 필요 없게 되면 유동적 무효였던 계약은 확정적으로 유효가 된다(98다40459 전합)."},{"번호":4,"판정":"틀림","설명":"허가를 배제하거나 잠탈하는 내용의 계약은 처음부터 확정적 무효이다. 유동적 무효는 허가를 전제로 한 계약에서만 인정된다."},{"번호":5,"판정":"틀림","설명":"각 당사자는 상대방에게 협력의무의 이행을 소로 구할 수 있다(90다12243 전합)."}],"개념":[{"종류":"흐름","제목":"토지거래허가구역 내 계약의 효력 변화","단계":[{"이름":"계약 체결","설명":"허가를 받지 않고 체결 → 효력 발생하지 않음(제11조제6항), 허가를 전제로 하면 유동적 무효"},{"이름":"허가 신청","설명":"당사자 공동 신청(제11조제1항), 협력의무 이행은 소로 청구 가능"},{"이름":"허가를 받은 경우","설명":"계약 시에 소급해 확정적 유효"},{"이름":"불허가·허가 거부 확정","설명":"확정적 무효, 이미 낸 대금은 부당이득으로 반환 청구 가능"},{"이름":"지정 해제·기간 만료 후 재지정 없음","설명":"확정적 유효(그 전에 확정적 무효가 된 경우는 제외)"}]},{"종류":"표","제목":"유동적 무효 상태에서 가능한 것과 불가능한 것","머리":["구분","가능","불가능"],"행":[["청구","허가신청 협력의무 이행 청구","이전등기·대금 지급 청구"],["해제","허가 후 또는 확정적 유효 후의 해제","허가 전 채무불이행을 이유로 한 해제"],["대금","-","이미 지급한 대금의 부당이득 반환(확정적 무효 전)"],["성질","허가 전제 계약","허가 배제·잠탈 계약은 확정적 무효"]]}],"함정":"선지 ④는 유동적 무효와 확정적 무효의 경계를 묻는다. 허가를 피하려는 계약은 확정적 무효이다. 선지 ①은 허가 전 부당이득 반환을 인정하고, 선지 ⑤는 협력의무 청구를 부정해 반대로 적었다."}},{"i":"S3-1-1-민법-09","r":"S3","g":1,"c":1,"n":49,"s":"민법","q":"법률행위의 무효와 취소에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["법률행위의 일부분이 무효이면 나머지 부분은 언제나 유효하다.","무효인 법률행위를 당사자가 무효임을 알고 추인하면 그 법률행위는 처음부터 유효였던 것으로 된다.","불공정한 법률행위가 되려면 궁박, 경솔, 무경험이 모두 갖추어져야 한다.","반사회질서의 법률행위의 무효는 선의의 제3자에게 대항하지 못한다.","무효인 법률행위가 다른 법률행위의 요건을 갖추고 당사자가 그 무효를 알았더라면 다른 법률행위를 의욕하였으리라고 인정되면, 그 다른 법률행위로서 효력이 있다."],"a":[5],"L":"민1-4","o":"변형","x":{"한줄":"무효행위 전환은 무효인 법률행위가 다른 법률행위의 요건을 갖추고, 당사자가 무효를 알았다면 다른 행위를 의욕했으리라고 인정될 때 인정된다.","근거":[{"법령":"민법","조문":"제138조","원문":"무효인 법률행위가 다른 법률행위의 요건을 구비하고 당사자가 그 무효를 알았더라면 다른 법률행위를 하는 것을 의욕하였으리라고 인정될 때에는 다른 법률행위로서 효력을 가진다."},{"법령":"민법","조문":"제137조","원문":"법률행위의 일부분이 무효인 때에는 그 전부를 무효로 한다. 그러나 그 무효부분이 없더라도 법률행위를 하였을 것이라고 인정될 때에는 나머지 부분은 무효가 되지 아니한다."},{"법령":"민법","조문":"제139조","원문":"무효인 법률행위는 추인하여도 그 효력이 생기지 아니한다. 그러나 당사자가 그 무효임을 알고 추인한 때에는 새로운 법률행위로 본다."},{"법령":"민법","조문":"제104조","원문":"당사자의 궁박, 경솔 또는 무경험으로 인하여 현저하게 공정을 잃은 법률행위는 무효로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"일부무효는 전부무효가 원칙이다. 무효 부분이 없어도 법률행위를 했으리라고 인정될 때에만 나머지가 유효하다(제137조)."},{"번호":2,"판정":"틀림","설명":"무효행위의 추인은 새로운 법률행위로 보며, 소급해서 유효가 되지 않는다(제139조)."},{"번호":3,"판정":"틀림","설명":"궁박·경솔·무경험은 모두 갖출 필요가 없고 어느 하나만 있으면 된다. 현저한 불균형은 별도 요건이다(제104조)."},{"번호":4,"판정":"틀림","설명":"반사회질서 법률행위의 무효는 절대적 무효이다. 선의의 제3자에게도 대항할 수 있다. 선의 제3자 보호 규정은 제107조~제110조에 있다."},{"번호":5,"판정":"옳음","설명":"제138조의 무효행위 전환 요건을 그대로 갖춘 서술이다."}],"개념":[{"종류":"표","제목":"무효와 취소 비교","머리":["구분","무효","취소"],"행":[["효력","처음부터 효력 없음","취소 전까지 유효, 취소하면 처음부터 무효(제141조)"],["주장","원칙적으로 누구나","취소권자만(제140조)"],["추인","소급효 없음, 새로운 행위로 봄(제139조)","추인하면 확정적 유효(제143조), 취소 원인이 소멸한 후에 해야 함(제144조)"],["기간","제한 없음","추인할 수 있는 날부터 3년, 법률행위를 한 날부터 10년(제146조)"]]},{"종류":"표","제목":"무효의 여러 모습","머리":["유형","내용","조문·예"],"행":[["일부무효","나머지만으로도 했으리라 인정되면 나머지 유효","제137조"],["무효행위의 전환","다른 행위의 요건 충족 + 당사자 의욕 인정","제138조"],["무효행위의 추인","새로운 법률행위로 봄","제139조"],["유동적 무효","허가·동의를 받으면 유효, 불허가면 확정적 무효","토지거래허가"],["절대적 무효","선의 제3자에게도 주장 가능","제103조, 제104조"]]}],"함정":"선지 ③은 불공정행위의 주관적 요건을 모두 갖춰야 한다고 적었다. 선지 ④는 선의 제3자 보호를 반사회질서에 끌어왔다. 선의 제3자 보호는 의사표시 하자 규정(제107조~제110조)에만 있다."}},{"i":"S3-1-1-민법-10","r":"S3","g":1,"c":1,"n":50,"s":"민법","q":"조건과 기한에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["정지조건이 법률행위 당시 이미 성취된 것이면 그 법률행위는 조건 없는 법률행위가 된다.","해제조건부 법률행위는 조건이 성취된 때부터 효력을 잃는다.","조건이 선량한 풍속 기타 사회질서에 위반한 것이면 그 조건만 무효이고 법률행위 자체는 유효하다.","조건의 성취로 불이익을 받을 당사자가 신의성실에 반하여 조건의 성취를 방해한 때에는 상대방은 그 조건이 성취된 것으로 주장할 수 있다.","기한의 이익은 포기할 수 있으나 상대방의 이익을 해하지 못한다."],"a":[3],"L":"민1-5","o":"변형","x":{"한줄":"불법조건을 붙인 법률행위는 조건만이 아니라 법률행위 전부가 무효이다.","근거":[{"법령":"민법","조문":"제151조제1항","원문":"①조건이 선량한 풍속 기타 사회질서에 위반한 것인 때에는 그 법률행위는 무효로 한다."},{"법령":"민법","조문":"제150조제1항","원문":"①조건의 성취로 인하여 불이익을 받을 당사자가 신의성실에 반하여 조건의 성취를 방해한 때에는 상대방은 그 조건이 성취한 것으로 주장할 수 있다."},{"법령":"민법","조문":"제153조","원문":"①기한은 채무자의 이익을 위한 것으로 추정한다.\n②기한의 이익은 이를 포기할 수 있다. 그러나 상대방의 이익을 해하지 못한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"이미 성취된 정지조건은 조건 없는 법률행위가 되고, 이미 성취된 해제조건이면 법률행위가 무효이다(제151조제2항)."},{"번호":2,"판정":"옳음","설명":"해제조건이 성취된 때부터 효력을 잃는다(제147조제2항)."},{"번호":3,"판정":"틀림","설명":"불법조건이 붙으면 그 법률행위 전부가 무효이다(제151조제1항). 조건만 분리해서 무효로 하지 않는다."},{"번호":4,"판정":"옳음","설명":"조건 성취를 방해한 쪽에는 조건이 성취된 것으로 주장할 수 있다(제150조제1항)."},{"번호":5,"판정":"옳음","설명":"기한의 이익은 포기할 수 있으나 상대방의 이익을 해하지 못한다(제153조제2항)."}],"개념":[{"종류":"표","제목":"조건의 종류와 효과","머리":["구분","효과","조문"],"행":[["정지조건","성취한 때부터 효력 발생","제147조제1항"],["해제조건","성취한 때부터 효력 상실","제147조제2항"],["소급효 특약","당사자 의사에 따름","제147조제3항"],["불법조건","법률행위 전부 무효","제151조제1항"],["기성조건","정지조건이면 조건 없는 행위, 해제조건이면 무효","제151조제2항"],["불능조건","해제조건이면 조건 없는 행위, 정지조건이면 무효","제151조제3항"]]},{"종류":"비교","제목":"조건과 기한","왼쪽":{"이름":"조건","항목":["성취 여부가 불확실","성취 때부터 효력, 소급은 특약(제147조)","신의칙 위반 방해·성취 규정(제150조)","친하지 않은 행위: 혼인·입양 등 가족법상 행위, 취소·해제·상계 같은 상대방 지위를 흔드는 단독행위"]},"오른쪽":{"이름":"기한","항목":["도래가 확실","도래한 때부터 효력(제152조), 소급 불가","채무자 이익으로 추정(제153조제1항)","이익 포기 가능, 상대방 이익은 해하지 못함"]}}],"함정":"선지 ③은 조건과 법률행위를 분리해 조건만 무효라고 적었다. 불법조건은 법률행위 전체를 무효로 한다."}},{"i":"S3-1-1-민법-11","r":"S3","g":1,"c":1,"n":51,"s":"민법","q":"물권적 청구권에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["소유권에 기한 방해제거청구권은 소멸시효의 대상이 아니다.","소유권에 기한 방해제거청구권은 방해자에게 고의 또는 과실이 있는 경우에만 행사할 수 있다.","소유자는 소유권을 방해할 염려가 있는 행위를 하는 자에게 그 예방이나 손해배상의 담보를 청구할 수 있다.","타인 토지에 무단으로 신축된 미등기건물을 매수하여 대금을 지급하고 점유하는 자는 건물철거청구의 상대방이 될 수 있다.","지상권자는 지상권을 방해하는 자에게 소유물방해제거청구권에 관한 규정을 준용하여 방해제거를 청구할 수 있다."],"a":[2],"L":"민2-1","o":"변형","x":{"한줄":"물권적 방해제거청구권은 방해 상태가 있으면 되고 방해자의 고의·과실을 요하지 않는다.","근거":[{"법령":"민법","조문":"제214조","원문":"소유자는 소유권을 방해하는 자에 대하여 방해의 제거를 청구할 수 있고 소유권을 방해할 염려있는 행위를 하는 자에 대하여 그 예방이나 손해배상의 담보를 청구할 수 있다."},{"법령":"민법","조문":"제162조제2항","원문":"②채권 및 소유권 이외의 재산권은 20년간 행사하지 아니하면 소멸시효가 완성한다."},{"법령":"민법","조문":"제290조제1항","원문":"①제213조, 제214조, 제216조 내지 제244조의 규정은 지상권자간 또는 지상권자와 인지소유자간에 이를 준용한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"소유권은 소멸시효에 걸리지 않고(제162조제2항), 소유권에 기한 물권적 청구권도 독립해서 시효로 소멸하지 않는다."},{"번호":2,"판정":"틀림","설명":"방해제거청구권은 방해자의 귀책사유를 요건으로 하지 않는다. 귀책사유는 손해배상청구(제750조)에서 요구된다."},{"번호":3,"판정":"옳음","설명":"방해할 염려가 있는 행위에는 예방 또는 손해배상의 담보를 청구할 수 있다(제214조 후단)."},{"번호":4,"판정":"옳음","설명":"미등기건물을 매수해 점유하며 법률상·사실상 처분권을 가진 자는 철거청구의 상대방이 된다."},{"번호":5,"판정":"옳음","설명":"지상권자에게는 제213조·제214조가 준용된다(제290조제1항)."}],"개념":[{"종류":"표","제목":"물권적 청구권의 종류","머리":["종류","요건","내용","조문"],"행":[["반환청구권","점유 상실, 상대방이 점유할 권리 없음","물건 반환","제213조"],["방해제거청구권","현재 방해 상태","방해 제거","제214조 전단"],["방해예방청구권","방해 염려","예방 또는 손해배상 담보","제214조 후단"]]},{"종류":"표","제목":"물권적 청구권의 준용","머리":["권리","준용 범위","조문"],"행":[["점유권","점유보호청구권(반환·방해제거·예방)을 따로 규정","제204조~제206조"],["지상권","제213조, 제214조 등","제290조"],["지역권","제214조만","제301조"],["전세권","제213조, 제214조 등","제319조"],["저당권","제214조만(점유 없으므로 반환청구 제외)","제370조"]]}],"함정":"선지 ②는 불법행위 책임(제750조)과 섞은 것이다. 물권적 청구권은 방해 상태 자체를 요건으로 하고 상대방의 귀책사유를 따지지 않는다."}},{"i":"S3-1-1-민법-12","r":"S3","g":1,"c":1,"n":52,"s":"민법","q":"권리의 객체가 토지인 경우, 그 토지를 점유할 권리가 인정되지 않는 물권을 모두 고른 것은? (다툼이 있으면 판례에 따름)","b":"ㄱ. 저당권\nㄴ. 전세권\nㄷ. 지상권","bs":"글자","img":[],"ch":["ㄱ","ㄷ","ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":[1],"L":"민2-1","o":"기출","x":{"한줄":"저당권은 점유를 이전하지 않는 담보물권이라 토지를 점유할 권리가 없다. 전세권과 지상권은 토지를 점유·사용하는 용익물권이다.","근거":[{"법령":"민법","조문":"제356조","원문":"저당권자는 채무자 또는 제삼자가 점유를 이전하지 아니하고 채무의 담보로 제공한 부동산에 대하여 다른 채권자보다 자기채권의 우선변제를 받을 권리가 있다."},{"법령":"민법","조문":"제303조제1항","원문":"①전세권자는 전세금을 지급하고 타인의 부동산을 점유하여 그 부동산의 용도에 좇아 사용ㆍ수익하며, 그 부동산 전부에 대하여 후순위권리자 기타 채권자보다 전세금의 우선변제를 받을 권리가 있다."},{"법령":"민법","조문":"제279조","원문":"지상권자는 타인의 토지에 건물 기타 공작물이나 수목을 소유하기 위하여 그 토지를 사용하는 권리가 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"ㄱ만 해당한다. 저당권은 점유 없이 우선변제권만 갖는다."},{"번호":2,"판정":"틀림","설명":"지상권은 토지를 사용하는 권리여서 점유할 권리가 인정된다(제279조)."},{"번호":3,"판정":"틀림","설명":"전세권은 부동산을 점유하여 사용·수익하는 권리다(제303조제1항)."},{"번호":4,"판정":"틀림","설명":"전세권과 지상권은 모두 점유할 권리가 인정된다."},{"번호":5,"판정":"틀림","설명":"ㄴ과 ㄷ은 점유할 권리가 인정되는 물권이다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"저당권은 점유 이전 없이 설정되므로 토지를 점유할 권리가 없다(제356조)."},{"기호":"ㄴ","판정":"틀림","설명":"전세권자는 부동산을 점유하여 사용·수익한다(제303조제1항)."},{"기호":"ㄷ","판정":"틀림","설명":"지상권자는 타인의 토지를 사용하는 권리가 있어 점유할 권리가 인정된다(제279조)."}],"개념":[{"종류":"표","제목":"물권별 점유권능","머리":["물권","종류","토지 점유 권능","근거"],"행":[["지상권","용익물권","있음","제279조"],["전세권","용익물권","있음","제303조제1항"],["지역권","용익물권","승역지를 점유하지 않고 이용만 함","제291조"],["저당권","담보물권","없음(점유를 이전하지 않음)","제356조"],["유치권","담보물권","있음(점유가 성립·존속 요건)","제320조"],["질권","담보물권","있음(동산 점유 이전이 효력요건)","제330조"]]}],"함정":"전세권이 담보물권의 성격도 갖는다는 이유로 점유권능이 없다고 보기 쉽다. 전세권은 점유를 수반하는 용익물권이다."}},{"i":"S3-1-1-민법-13","r":"S3","g":1,"c":1,"n":53,"s":"민법","q":"법률행위에 의하지 않은 부동산물권의 변동에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["이행판결에 기한 부동산물권의 변동시기는 판결이 확정된 때이다.","상속인은 상속등기를 하지 않고도 상속받은 부동산을 제3자에게 처분할 수 있다.","경매로 인한 부동산 소유권의 취득시기는 매각허가결정이 확정된 때이다.","자기 비용과 노력으로 건물을 신축한 사람은 소유권보존등기를 하지 않아도 그 건물의 소유권을 취득한다.","20년간 소유의 의사로 평온·공연하게 부동산을 점유한 자는 등기 없이도 점유 20년이 지난 때 소유권을 취득한다."],"a":[4],"L":"민2-2","o":"변형","x":{"한줄":"건물을 신축한 사람은 원시취득자로서 보존등기 없이도 소유권을 취득한다.","근거":[{"법령":"민법","조문":"제187조","원문":"상속, 공용징수, 판결, 경매 기타 법률의 규정에 의한 부동산에 관한 물권의 취득은 등기를 요하지 아니한다. 그러나 등기를 하지 아니하면 이를 처분하지 못한다."},{"법령":"민사집행법","조문":"제135조","원문":"매수인은 매각대금을 다 낸 때에 매각의 목적인 권리를 취득한다."},{"법령":"민법","조문":"제245조제1항","원문":"①20년간 소유의 의사로 평온, 공연하게 부동산을 점유하는 자는 등기함으로써 그 소유권을 취득한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"제187조의 판결은 형성판결만 뜻한다. 이행판결로는 등기를 해야 물권변동이 생긴다."},{"번호":2,"판정":"틀림","설명":"상속은 등기 없이 취득하나, 등기하지 않으면 처분하지 못한다(제187조 단서)."},{"번호":3,"판정":"틀림","설명":"매수인은 매각대금을 다 낸 때에 소유권을 취득한다(민사집행법 제135조)."},{"번호":4,"판정":"옳음","설명":"신축은 법률의 규정에 의한 원시취득이어서 등기를 요하지 않는다. 처분하려면 보존등기를 해야 한다(제187조 단서)."},{"번호":5,"판정":"틀림","설명":"점유취득시효는 20년 점유에 더해 등기를 해야 소유권을 취득한다(제245조제1항)."}],"개념":[{"종류":"표","제목":"제187조에 따라 등기 없이 취득하는 경우와 처분 요건","머리":["원인","등기 없이 취득","처분하려면"],"행":[["상속","피상속인 사망 때","상속등기 필요"],["공용징수","수용의 개시일","등기 필요"],["판결","형성판결 확정 때(공유물분할 등)","등기 필요"],["경매","매각대금을 다 낸 때(민사집행법 제135조)","등기 필요"],["신축","건축주의 원시취득","보존등기 필요"]]},{"종류":"비교","제목":"등기 없이 취득하는 경우와 등기해야 취득하는 경우","왼쪽":{"이름":"등기 없이 취득","항목":["상속","경매 매수인의 소유권(대금 완납 시)","건물 신축","형성판결 확정","관습법상 법정지상권"]},"오른쪽":{"이름":"등기해야 취득","항목":["법률행위로 인한 변동(제186조)","점유취득시효(제245조제1항)","이행판결에 기한 변동"]}}],"함정":"선지 ①의 이행판결은 형성판결이 아니다. 선지 ⑤는 점유취득시효와 등기부취득시효를 섞었다. 점유취득시효는 등기해야 취득한다."}},{"i":"S3-1-1-민법-14","r":"S3","g":1,"c":1,"n":54,"s":"민법","q":"부동산 물권변동에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["소유권이전등기가 마쳐져 있으면 등기명의인은 적법한 등기원인에 의하여 소유권을 취득한 것으로 추정된다.","중간생략등기가 합의 없이 이미 마쳐졌더라도 실체관계에 부합하면 중간자의 동의가 없었다는 이유만으로 그 말소를 구할 수 없다.","소유권이전등기청구권의 보전을 위한 가등기에 기하여 본등기가 행해지면 물권변동의 효력은 본등기가 행해진 때 발생한다.","매수한 부동산을 인도받아 점유하는 매수인의 소유권이전등기청구권은 소멸시효에 걸리지 않는다.","甲이 乙에게, 乙이 丙에게 순차로 매도한 경우, 중간생략등기에 관한 합의가 없더라도 丙은 乙의 동의 없이 甲에게 직접 자신에게로의 이전등기를 청구할 수 있다."],"a":[5],"L":"민2-2","o":"변형","x":{"한줄":"순차 매매에서 최종 양수인이 최초 양도인에게 직접 이전등기를 청구하려면 관계자 전원의 중간생략등기 합의가 있어야 한다.","근거":[{"판례":"대법원 1976. 11. 6. 선고 76다148 전원합의체","요지":"매수인이 부동산을 인도받아 사용·수익하는 동안은 소유권이전등기청구권의 소멸시효가 진행하지 않는다."},{"법령":"민법","조문":"제186조","원문":"부동산에 관한 법률행위로 인한 물권의 득실변경은 등기하여야 그 효력이 생긴다."}],"선지":[{"번호":1,"판정":"옳음","설명":"등기에는 추정력이 있어 등기명의인은 적법한 권리자로 추정된다."},{"번호":2,"판정":"옳음","설명":"중간생략등기가 이미 마쳐져 실체관계에 부합하면 유효하다. 중간자 동의가 없었다는 이유만으로 말소를 구할 수 없다."},{"번호":3,"판정":"옳음","설명":"가등기는 순위보전의 효력만 있고, 물권변동은 본등기를 한 때 생긴다."},{"번호":4,"판정":"옳음","설명":"인도받아 사용·수익하는 매수인은 권리 위에 잠자는 자가 아니다. 점유를 상실하면 그때부터 시효가 진행한다(76다148 전합)."},{"번호":5,"판정":"틀림","설명":"중간생략등기 합의가 없으면 丙이 직접 청구할 수 없다. 중간자 乙의 동의와 최초 양도인 甲의 승낙이 있어야 한다."}],"개념":[{"종류":"흐름","제목":"순차 매매와 중간생략등기","단계":[{"이름":"매매 1","설명":"甲이 乙에게 매도: 乙은 甲에게 이전등기청구권"},{"이름":"매매 2","설명":"乙이 丙에게 전매: 丙은 乙에게 이전등기청구권"},{"이름":"합의","설명":"甲·乙·丙 전원의 중간생략등기 합의가 있으면 丙이 甲에게 직접 청구 가능"},{"이름":"합의 없이 마쳐진 경우","설명":"실체관계에 부합하면 등기는 유효, 말소 청구 불가"},{"이름":"제한","설명":"토지거래허가구역에서는 중간생략등기 합의가 허가 잠탈이 될 수 있음"}]},{"종류":"표","제목":"등기의 효력","머리":["쟁점","내용"],"행":[["추정력","등기명의인은 적법한 권리자로 추정"],["가등기","순위보전, 물권변동은 본등기 때"],["공신력","없음(등기를 믿고 거래해도 보호받지 못함)"],["인도받은 매수인의 등기청구권","소멸시효에 걸리지 않음, 점유 상실 때부터 진행"]]}],"함정":"선지 ⑤는 중간생략등기가 허용되는 요건을 낮춰 적었다. 실체관계에 부합해 이미 마쳐진 등기가 유효하다는 것과 사전에 직접 청구할 수 있다는 것은 다르다."}},{"i":"S3-1-1-민법-15","r":"S3","g":1,"c":1,"n":55,"s":"민법","q":"점유에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["점유자는 소유의 의사로 선의, 평온 및 공연하게 점유한 것으로 추정한다.","점유자의 승계인이 전점유자의 점유를 아울러 주장하는 경우에는 전점유자의 점유의 하자도 승계한다.","소유의 의사가 없는 선의의 점유자는 점유물이 자신의 책임 있는 사유로 멸실된 경우 이익이 현존하는 한도에서만 배상하면 된다.","점유자가 점유의 침탈을 당한 때에는 침탈을 당한 날부터 1년 내에 그 물건의 반환을 청구할 수 있다.","점유자가 과실을 취득한 경우에는 점유물을 반환할 때 통상의 필요비의 상환을 청구하지 못한다."],"a":[3],"L":"민2-3","o":"변형","x":{"한줄":"소유의 의사가 없는 점유자는 선의여도 점유물의 멸실·훼손으로 인한 손해 전부를 배상해야 한다.","근거":[{"법령":"민법","조문":"제202조","원문":"점유물이 점유자의 책임있는 사유로 인하여 멸실 또는 훼손한 때에는 악의의 점유자는 그 손해의 전부를 배상하여야 하며 선의의 점유자는 이익이 현존하는 한도에서 배상하여야 한다. 소유의 의사가 없는 점유자는 선의인 경우에도 손해의 전부를 배상하여야 한다."},{"법령":"민법","조문":"제197조제1항","원문":"①점유자는 소유의 의사로 선의, 평온 및 공연하게 점유한 것으로 추정한다."},{"법령":"민법","조문":"제203조제1항","원문":"①점유자가 점유물을 반환할 때에는 회복자에 대하여 점유물을 보존하기 위하여 지출한 금액 기타 필요비의 상환을 청구할 수 있다. 그러나 점유자가 과실을 취득한 경우에는 통상의 필요비는 청구하지 못한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"점유의 태양은 소유의 의사, 선의, 평온, 공연이 추정된다(제197조제1항). 무과실은 추정에 포함되지 않는다."},{"번호":2,"판정":"옳음","설명":"전점유자의 점유를 아울러 주장하면 그 하자도 계승한다(제199조제2항)."},{"번호":3,"판정":"틀림","설명":"소유의 의사가 없는 타주점유자는 선의여도 손해 전부를 배상한다(제202조 후단). 현존이익 한도의 배상은 소유의 의사가 있는 선의 점유자에게 적용된다."},{"번호":4,"판정":"옳음","설명":"침탈을 당한 날부터 1년 내에 점유물 반환을 청구한다(제204조제1항·제3항)."},{"번호":5,"판정":"옳음","설명":"과실을 취득한 점유자는 통상의 필요비를 청구하지 못한다(제203조제1항 단서)."}],"개념":[{"종류":"표","제목":"점유자와 회복자의 관계","머리":["쟁점","선의 자주점유자","악의 점유자","타주점유자(소유 의사 없음)"],"행":[["과실","취득(제201조제1항)","수취한 과실 반환, 소비·훼손한 과실은 대가 보상(제201조제2항)","-"],["멸실·훼손 책임","이익이 현존하는 한도(제202조)","손해 전부(제202조)","선의여도 손해 전부(제202조)"],["필요비","점유물 반환 시 상환 청구, 과실 취득했으면 통상 필요비 제외(제203조제1항)","상환 청구 가능","상환 청구 가능"],["유익비","가액 증가가 현존할 때 회복자 선택으로 지출액 또는 증가액 상환(제203조제2항)","같음","같음"]]},{"종류":"표","제목":"점유보호청구권","머리":["구분","내용","행사 기간","조문"],"행":[["점유회수","침탈 시 반환·손해배상, 악의 특별승계인에게만 가능","침탈당한 날부터 1년","제204조"],["점유보유","방해 제거·손해배상","방해 종료일부터 1년(공사는 착수 후 1년 또는 완성 시)","제205조"],["점유보전","방해 염려 시 예방·손해배상 담보","-","제206조"]]}],"함정":"선지 ③은 소유 의사가 없는 점유자의 책임을 선의 자주점유자와 같게 적었다. 제202조 후단이 타주점유자는 선의여도 전부 배상으로 정한다. 선의 점유자는 과실 취득과 현존이익 배상으로만 보호된다."}},{"i":"S3-1-1-민법-16","r":"S3","g":1,"c":1,"n":56,"s":"민법","q":"민법상 공유에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["공유자는 5년 내의 기간으로 공유물을 분할하지 않기로 약정할 수 있고, 이를 갱신한 경우 그 기간은 갱신한 날부터 5년을 넘지 못한다.","공유물을 처분하거나 변경하려면 공유자의 지분 과반수의 동의가 있으면 된다.","공유물의 관리에 관한 사항은 공유자 전원의 동의로 결정한다.","공유자 사이에 분할 협의가 성립하지 않으면 법원은 반드시 현물로 분할해야 한다.","제3자가 공유물을 불법점유하는 경우, 공유자 한 사람은 지분 범위에서만 반환을 청구할 수 있고 공유물 전부의 인도를 청구할 수 없다."],"a":[1],"L":"민2-4","o":"변형","x":{"한줄":"공유물 분할금지 약정은 5년 내로만 할 수 있고, 갱신해도 갱신한 날부터 5년을 넘지 못한다.","근거":[{"법령":"민법","조문":"제268조","원문":"①공유자는 공유물의 분할을 청구할 수 있다. 그러나 5년내의 기간으로 분할하지 아니할 것을 약정할 수 있다.\n②전항의 계약을 갱신한 때에는 그 기간은 갱신한 날로부터 5년을 넘지 못한다."},{"법령":"민법","조문":"제264조","원문":"공유자는 다른 공유자의 동의없이 공유물을 처분하거나 변경하지 못한다."},{"법령":"민법","조문":"제265조","원문":"공유물의 관리에 관한 사항은 공유자의 지분의 과반수로써 결정한다. 그러나 보존행위는 각자가 할 수 있다."},{"법령":"민법","조문":"제269조제2항","원문":"②현물로 분할할 수 없거나 분할로 인하여 현저히 그 가액이 감손될 염려가 있는 때에는 법원은 물건의 경매를 명할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"분할금지 약정은 5년 내의 기간으로 하고, 갱신해도 갱신한 날부터 5년을 넘지 못한다(제268조제1항·제2항)."},{"번호":2,"판정":"틀림","설명":"처분·변경은 다른 공유자 전원의 동의가 필요하다(제264조)."},{"번호":3,"판정":"틀림","설명":"관리는 지분의 과반수로 결정한다(제265조 본문). 전원 동의는 처분·변경에서 필요하다."},{"번호":4,"판정":"틀림","설명":"현물로 분할할 수 없거나 가액이 현저히 감손될 염려가 있으면 경매를 명할 수 있다(제269조제2항)."},{"번호":5,"판정":"틀림","설명":"불법점유자에게는 각 공유자가 보존행위(제265조 단서)로서 공유물 전부의 반환을 청구할 수 있다."}],"개념":[{"종류":"표","제목":"공유물에 관한 행위와 필요한 지분","머리":["행위","결정 요건","조문"],"행":[["지분 처분","공유자 각자 자유","제263조"],["처분·변경","공유자 전원 동의","제264조"],["관리","지분의 과반수","제265조 본문"],["보존","각자 단독","제265조 단서"],["분할 청구","각자 가능, 5년 내 불분할 약정 가능","제268조"]]},{"종류":"표","제목":"공유·합유·총유 비교","머리":["구분","주체","처분·변경","지분 처분","분할"],"행":[["공유","수인(지분 있음)","전원 동의(제264조)","자유(제263조)","청구 가능(제268조)"],["합유","조합체","전원 동의(제272조)","전원 동의(제273조제1항)","청구 불가(제273조제2항)"],["총유","법인 아닌 사단","사원총회 결의(제276조제1항)","지분 개념 없음","청구 불가"]]}],"함정":"선지 ②와 ③은 처분·변경에는 전원 동의, 관리에는 과반수라는 구분을 서로 바꿔 놓았다. 선지 ⑤는 공유자가 제3자에게 지분 범위만 청구할 수 있다고 한 것인데, 보존행위로 전부 반환을 청구할 수 있다."}},{"i":"S3-1-1-민법-17","r":"S3","g":1,"c":1,"n":57,"s":"민법","q":"점유로 인한 부동산 소유권 취득에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["점유취득시효가 완성된 후 점유자가 등기하기 전에 소유자가 제3자에게 소유권이전등기를 해 준 경우, 점유자는 그 제3자에게 시효취득을 주장할 수 있다.","점유로 인한 소유권취득의 효력은 점유를 개시한 때에 소급한다.","점유취득시효의 완성으로 점유자가 갖는 소유권이전등기청구권은 물권적 청구권이다.","점유취득시효가 완성되면 점유자는 등기 없이도 그 시점에 소유권을 취득한다.","부동산의 소유자로 등기한 자가 10년간 소유의 의사로 평온·공연하게 점유하면, 선의·무과실이 아니어도 소유권을 취득한다."],"a":[2],"L":"민2-4","o":"변형","x":{"한줄":"시효취득으로 소유권을 얻으면 그 효력은 점유를 개시한 때로 소급한다.","근거":[{"법령":"민법","조문":"제247조제1항","원문":"①전2조의 규정에 의한 소유권취득의 효력은 점유를 개시한 때에 소급한다."},{"법령":"민법","조문":"제245조","원문":"①20년간 소유의 의사로 평온, 공연하게 부동산을 점유하는 자는 등기함으로써 그 소유권을 취득한다.\n②부동산의 소유자로 등기한 자가 10년간 소유의 의사로 평온, 공연하게 선의이며 과실없이 그 부동산을 점유한 때에는 소유권을 취득한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"시효완성 후 소유자가 제3자에게 등기를 이전하면 점유자는 그 제3자에게 시효취득을 주장하지 못한다. 소유자에게 이행불능에 따른 손해배상을 구할 수 있을 뿐이다."},{"번호":2,"판정":"옳음","설명":"시효취득의 효력은 점유 개시 시로 소급한다(제247조제1항)."},{"번호":3,"판정":"틀림","설명":"시효완성자의 등기청구권은 소유자에 대한 채권적 청구권이다."},{"번호":4,"판정":"틀림","설명":"점유취득시효는 등기함으로써 소유권을 취득한다(제245조제1항)."},{"번호":5,"판정":"틀림","설명":"등기부취득시효는 10년 점유에 더해 선의·무과실이 필요하다(제245조제2항)."}],"개념":[{"종류":"표","제목":"점유취득시효와 등기부취득시효","머리":["구분","점유취득시효(제245조제1항)","등기부취득시효(제245조제2항)"],"행":[["기간","20년","10년"],["주체","점유자(등기명의 불문)","소유자로 등기한 자"],["점유 요건","소유의 의사, 평온, 공연","소유의 의사, 평온, 공연, 선의·무과실"],["소유권 취득","등기함으로써","요건 충족 시"],["효력","점유 개시 시로 소급(제247조제1항)","점유 개시 시로 소급(제247조제1항)"]]},{"종류":"표","제목":"부동산과 동산의 취득시효","머리":["구분","기간","선의·무과실","조문"],"행":[["부동산(점유)","20년","불필요","제245조제1항"],["부동산(등기)","10년","필요","제245조제2항"],["동산","10년","불필요","제246조제1항"],["동산(선의·무과실 개시)","5년","필요","제246조제2항"]]}],"함정":"선지 ④는 취득시효 완성과 소유권 취득 시점을 같다고 보게 한다. 점유취득시효는 등기를 해야 소유권을 취득하고, 효력만 점유 개시 시로 소급한다."}},{"i":"S3-1-1-민법-18","r":"S3","g":1,"c":1,"n":58,"s":"민법","q":"甲, 乙, 丙은 X토지를 각 1/2, 1/4, 1/4의 지분으로 공유하고 있다. 이에 관한 설명으로 옳은 것은? (단, 구분소유적 공유관계는 아니며, 다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["乙이 X토지에 대한 자신의 지분을 포기한 경우, 乙의 지분은 甲, 丙에게 균등한 비율로 귀속된다.","당사자간의 특약이 없는 경우, 甲은 단독으로 X토지를 제3자에게 임대할 수 있다.","甲, 乙은 X토지에 대한 관리방법으로 X토지에 건물을 신축할 수 있다.","甲, 乙, 丙이 X토지의 관리에 관한 특약을 한 경우, 그 특약은 특별한 사정이 없는 한 그들의 특정승계인에게도 효력이 미친다.","丙이 甲, 乙과의 협의없이 X토지를 배타적ㆍ독점적으로 점유하고 있는 경우, 乙은 공유물에 대한 보존행위로 X토지의 인도를 청구할 수 있다."],"a":[4],"L":"민2-4","o":"기출","x":{"한줄":"공유물의 관리에 관한 특약은 지분권의 본질적 부분을 침해하지 않는 한 공유자의 특정승계인에게도 효력이 미친다.","근거":[{"법령":"민법","조문":"제267조","원문":"공유자가 그 지분을 포기하거나 상속인없이 사망한 때에는 그 지분은 다른 공유자에게 각 지분의 비율로 귀속한다."},{"법령":"민법","조문":"제265조","원문":"공유물의 관리에 관한 사항은 공유자의 지분의 과반수로써 결정한다. 그러나 보존행위는 각자가 할 수 있다."},{"판례":"대법원 2020. 5. 21. 선고 2018다287522 전원합의체","요지":"공유물을 소수지분권자가 배타적으로 점유하는 경우 다른 소수지분권자는 보존행위로 공유물의 인도를 청구할 수 없고, 방해배제만 청구할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"포기된 지분은 다른 공유자에게 각 지분의 비율로 귀속한다(제267조). 甲과 丙에게 2:1로 귀속된다."},{"번호":2,"판정":"틀림","설명":"임대는 관리행위이므로 지분의 과반수가 필요하다(제265조). 甲의 지분은 1/2로 과반수에 미치지 못한다."},{"번호":3,"판정":"틀림","설명":"건물 신축은 공유물의 변경이어서 전원의 동의가 필요하다(제264조). 甲, 乙의 지분은 3/4이라도 부족하다."},{"번호":4,"판정":"옳음","설명":"공유물 관리에 관한 특약은 특별한 사정이 없는 한 특정승계인에게도 효력이 미친다."},{"번호":5,"판정":"틀림","설명":"소수지분권자 丙이 독점 점유하는 경우 다른 소수지분권자 乙은 인도를 청구할 수 없고 방해배제를 청구할 수 있다(2018다287522 전합)."}],"개념":[{"종류":"표","제목":"공유물 분쟁의 해결 구조","머리":["상황","결론","근거"],"행":[["지분 포기","다른 공유자에게 지분 비율로 귀속","제267조"],["임대 등 관리","지분 과반수(1/2 초과)","제265조"],["건물 신축 등 변경","전원 동의","제264조"],["소수지분권자의 독점 점유","다른 소수지분권자는 인도 청구 불가, 방해배제 청구 가능","2018다287522 전합"],["제3자의 불법점유","각자가 보존행위로 전부 반환 청구","제265조 단서"],["관리 특약","특정승계인에게도 효력(지분권 본질 침해 제외)","판례"]]}],"함정":"선지 ⑤는 종전 전합 판례(소수지분권자 점유에 대한 인도 청구 허용)를 따르면 옳은 것처럼 보인다. 2020년 전원합의체 판결로 방해배제만 가능하다. 선지 ②는 1/2 지분이 과반수라고 착각하기 쉽다."}},{"i":"S3-1-1-민법-19","r":"S3","g":1,"c":1,"n":59,"s":"민법","q":"지상권과 이와 유사한 토지이용권에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["견고한 건물의 소유를 목적으로 지상권을 설정하면서 존속기간을 정하지 않았다면, 그 존속기간은 30년이다.","지상권 설정계약에서 지료를 약정하지 않았다면 토지소유자는 지상권자에게 지료를 청구할 수 없다.","지상권자는 토지소유자의 동의 없이 지상권을 양도할 수 있다.","저당물의 경매로 법정지상권이 성립한 경우 지료는 당사자의 청구에 의하여 법원이 정한다.","20년간 평온·공연하게 분묘를 점유하여 분묘기지권을 시효취득한 자는 분묘를 설치한 때부터 소급하여 토지소유자에게 지료를 지급할 의무가 있다."],"a":[5],"L":"민2-5","o":"변형","x":{"한줄":"시효취득한 분묘기지권자는 토지소유자가 지료를 청구한 날부터의 지료를 지급할 의무가 있고, 설치 시로 소급하지 않는다.","근거":[{"판례":"대법원 2021. 4. 29. 선고 2017다228007 전원합의체","요지":"시효로 분묘기지권을 취득한 자는 토지소유자가 지료를 청구한 날부터의 지료를 지급할 의무가 있다."},{"법령":"민법","조문":"제281조제1항","원문":"①계약으로 지상권의 존속기간을 정하지 아니한 때에는 그 기간은 전조의 최단존속기간으로 한다."},{"법령":"민법","조문":"제282조","원문":"지상권자는 타인에게 그 권리를 양도하거나 그 권리의 존속기간 내에서 그 토지를 임대할 수 있다."},{"법령":"민법","조문":"제366조","원문":"저당물의 경매로 인하여 토지와 그 지상건물이 다른 소유자에 속한 경우에는 토지소유자는 건물소유자에 대하여 지상권을 설정한 것으로 본다. 그러나 지료는 당사자의 청구에 의하여 법원이 이를 정한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"석조·석회조·연와조 등 견고한 건물의 소유를 목적으로 하면 최단존속기간은 30년이다(제280조제1항제1호). 기간 약정이 없으면 이 기간이 된다(제281조제1항)."},{"번호":2,"판정":"옳음","설명":"지료는 지상권의 요소가 아니다. 지료 약정이 없으면 지상권은 무상이어서 지료를 청구하지 못한다."},{"번호":3,"판정":"옳음","설명":"지상권자는 양도와 임대가 자유롭다(제282조). 양도금지 특약은 효력이 없다(제289조)."},{"번호":4,"판정":"옳음","설명":"법정지상권의 지료는 협의가 안 되면 법원이 정한다(제366조 단서)."},{"번호":5,"판정":"틀림","설명":"시효취득한 분묘기지권자의 지료 지급의무는 토지소유자가 지료를 청구한 날부터 생긴다(2017다228007 전합). 설치일로 소급하지 않는다."}],"개념":[{"종류":"표","제목":"지상권의 주요 규정","머리":["항목","내용","조문"],"행":[["최단존속기간","견고한 건물·수목 30년, 그 밖의 건물 15년, 건물 이외 공작물 5년","제280조제1항"],["기간 약정이 없을 때","최단존속기간으로 함, 공작물 종류를 정하지 않았으면 15년 건물로 봄","제281조"],["양도·임대","자유, 이를 금지하는 지상권자에게 불리한 약정은 무효","제282조, 제289조"],["지료 연체","2년 이상 연체하면 지상권설정자가 소멸청구","제287조"],["저당권자 통지","지상권이 저당권 목적이면 소멸청구는 통지 후 상당 기간 경과로 효력","제288조"],["갱신·매수청구","지상권 소멸 시 지상물 있으면 갱신 청구, 거절 시 상당한 가액의 매수 청구","제283조"]]},{"종류":"표","제목":"분묘기지권","머리":["취득 유형","내용"],"행":[["승낙형","토지소유자의 승낙을 받아 분묘를 설치"],["양도형","자기 소유 토지에 분묘를 설치하고 이장 특약 없이 토지를 처분"],["시효취득형","타인 토지에 승낙 없이 설치해 20년간 평온·공연하게 점유, 지료는 토지소유자가 청구한 날부터 발생"],["장사법 제27조제3항","토지 소유자의 승낙 없이 설치한 분묘의 연고자는 토지사용권을 주장할 수 없음"]]}],"함정":"분묘기지권을 시효취득하면 설치일부터 지료를 내야 한다고 생각하기 쉽다. 2021년 전원합의체 판결은 토지소유자가 지료를 청구한 날부터라고 정했다."}},{"i":"S3-1-1-민법-20","r":"S3","g":1,"c":1,"n":60,"s":"민법","q":"지역권에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["지역권은 요역지와 분리하여 양도할 수 없다.","지역권은 표현된 것이 아니더라도 시효취득할 수 있다.","요역지의 소유권이 이전되면 다른 약정이 없는 한 지역권도 이전된다.","요역지의 공유자 1인은 그 토지 지분에 관한 지역권을 소멸시킬 수 없다.","공유자의 1인이 지역권을 취득한 때에는 다른 공유자도 지역권을 취득한다."],"a":[2],"L":"민2-5","o":"기출","x":{"한줄":"지역권은 계속되고 표현된 것에 한하여 시효취득할 수 있다.","근거":[{"법령":"민법","조문":"제294조","원문":"지역권은 계속되고 표현된 것에 한하여 제245조의 규정을 준용한다."},{"법령":"민법","조문":"제292조","원문":"①지역권은 요역지소유권에 부종하여 이전하며 또는 요역지에 대한 소유권이외의 권리의 목적이 된다. 그러나 다른 약정이 있는 때에는 그 약정에 의한다.\n②지역권은 요역지와 분리하여 양도하거나 다른 권리의 목적으로 하지 못한다."},{"법령":"민법","조문":"제293조제1항","원문":"①토지공유자의 1인은 지분에 관하여 그 토지를 위한 지역권 또는 그 토지가 부담한 지역권을 소멸하게 하지 못한다."},{"법령":"민법","조문":"제295조제1항","원문":"①공유자의 1인이 지역권을 취득한 때에는 다른 공유자도 이를 취득한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지역권은 요역지와 분리하여 양도하거나 다른 권리의 목적으로 하지 못한다(제292조제2항)."},{"번호":2,"판정":"틀림","설명":"표현되지 않은 지역권은 시효취득할 수 없다. 계속되고 표현된 것에 한한다(제294조)."},{"번호":3,"판정":"옳음","설명":"지역권은 요역지소유권에 부종하여 이전한다(제292조제1항)."},{"번호":4,"판정":"옳음","설명":"공유자 1인은 지분에 관한 지역권을 소멸하게 하지 못한다(제293조제1항)."},{"번호":5,"판정":"옳음","설명":"공유자 1인이 취득하면 다른 공유자도 취득한다(제295조제1항)."}],"개념":[{"종류":"표","제목":"지역권의 성질","머리":["성질","내용","조문"],"행":[["부종성","요역지 소유권과 함께 이전, 요역지와 분리하여 양도 불가","제292조"],["불가분성(소멸)","공유자 1인이 지분에 관한 지역권을 소멸시키지 못함","제293조제1항"],["불가분성(취득)","공유자 1인이 취득하면 다른 공유자도 취득","제295조제1항"],["불가분성(시효)","시효 중단·정지는 다른 공유자를 위해서도 효력(소멸시효), 취득기간 중단은 모든 공유자에 대한 사유일 때만","제295조제2항, 제296조"],["시효취득","계속되고 표현된 것에 한함","제294조"]]},{"종류":"비교","제목":"지상권과 지역권","왼쪽":{"이름":"지상권","항목":["타인 토지에서 건물·수목 등을 소유하기 위해 그 토지를 사용","토지 점유를 수반","양도·임대 가능","지료 약정은 요소 아님"]},"오른쪽":{"이름":"지역권","항목":["자기 토지의 편익을 위해 타인 토지를 이용","승역지를 점유하지 않고 이용","요역지와 분리하여 양도 불가","표현되지 않은 것은 시효취득 불가"]}}],"함정":"선지 ②는 시효취득 요건인 계속과 표현 가운데 표현을 빼고 읽게 한다. 표현되지 않은 지역권은 시효취득할 수 없다."}},{"i":"S3-1-1-민법-21","r":"S3","g":1,"c":1,"n":61,"s":"민법","q":"전세권에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["전세금의 반환은 전세권말소등기에 필요한 서류를 교부하기 전에 이루어져야 한다.","전세권자는 전세권설정자에 대하여 통상의 수선에 필요한비용의 상환을 청구할 수 없다.","전전세한 목적물에 불가항력으로 인한 손해가 발생한 경우, 그 손해가 전전세하지 않았으면 면할 수 있는 것이었던 때에는 전세권자는 그 책임을 부담한다.","대지와 건물을 소유한 자가 건물에 대해서만 전세권을 설정한 후 대지를 제3자에게 양도한 경우, 제3자는 전세권설정자에 대하여 대지에 대한 지상권을 설정한 것으로 본다.","타인의 토지에 지상권을 설정한 자가 그 위에 건물을 신축하여 그 건물에 전세권을 설정한 경우, 그 건물소유자는 전세권자의 동의 없이 지상권을 소멸하게 하는 행위를 할 수 없다."],"a":[1],"L":"민2-6","o":"기출","x":{"한줄":"전세권이 소멸하면 전세금 반환과 목적물 인도·말소등기 서류 교부가 동시이행이므로, 반환이 서류 교부보다 먼저 이루어져야 하는 것은 아니다.","근거":[{"법령":"민법","조문":"제317조","원문":"전세권이 소멸한 때에는 전세권설정자는 전세권자로부터 그 목적물의 인도 및 전세권설정등기의 말소등기에 필요한 서류의 교부를 받는 동시에 전세금을 반환하여야 한다."},{"법령":"민법","조문":"제308조","원문":"전세권의 목적물을 전전세 또는 임대한 경우에는 전세권자는 전전세 또는 임대하지 아니하였으면 면할 수 있는 불가항력으로 인한 손해에 대하여 그 책임을 부담한다."},{"법령":"민법","조문":"제309조","원문":"전세권자는 목적물의 현상을 유지하고 그 통상의 관리에 속한 수선을 하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"전세금 반환과 목적물 인도 및 말소등기 서류 교부는 동시이행 관계다(제317조). 서류 교부가 반환보다 뒤에 와도 되고, 반환이 먼저 이루어져야 하는 것도 아니다."},{"번호":2,"판정":"옳음","설명":"통상의 관리에 속한 수선은 전세권자가 할 의무다(제309조). 그래서 통상 수선비는 상환 청구 대상이 아니다. 유익비는 가액 증가가 남아 있을 때만 소유자 선택에 따라 청구한다(제310조제1항)."},{"번호":3,"판정":"옳음","설명":"전전세·임대한 경우 전세권자는 전전세하지 않았으면 면했을 불가항력 손해까지 책임진다(제308조)."},{"번호":4,"판정":"옳음","설명":"대지와 건물이 같은 소유자일 때 건물에만 전세권을 설정하면 대지소유권의 특별승계인은 전세권설정자에 대하여 지상권을 설정한 것으로 본다. 지료는 당사자 청구로 법원이 정한다(제305조제1항)."},{"번호":5,"판정":"옳음","설명":"타인 토지 위 건물에 전세권을 설정하면 전세권의 효력이 건물 소유를 위한 지상권·임차권에 미치고, 설정자는 전세권자 동의 없이 그 지상권·임차권을 소멸시키는 행위를 하지 못한다(제304조)."}],"개념":[{"종류":"표","제목":"전세권의 존속기간·갱신·소멸통고","머리":["구분","내용","조문"],"행":[["최장 존속기간","10년(약정이 더 길면 10년으로 단축)","제312조제1항"],["건물 전세권의 최단 기간","1년(1년 미만으로 정하면 1년)","제312조제2항"],["갱신","갱신 가능, 갱신한 날부터 10년을 넘지 못함","제312조제3항"],["건물 전세권의 법정갱신","만료 전 6월~1월 사이에 설정자가 갱신거절·조건변경 통지를 하지 않으면 종전과 같은 조건으로 다시 설정한 것으로 봄, 존속기간은 정함 없음","제312조제4항"],["기간 약정이 없는 경우","각 당사자가 언제든 소멸 통고, 상대방이 통고를 받은 날부터 6월이 지나면 소멸","제313조"],["목적물","농경지는 전세권의 목적이 될 수 없음","제303조제2항"]]},{"종류":"흐름","제목":"전세권 소멸 후 정산 절차","단계":[{"이름":"소멸","설명":"존속기간 만료·소멸통고·소멸청구 등. 전세권자는 목적물을 원상회복하고 부속시킨 물건을 수거할 수 있다(제316조제1항)"},{"이름":"부속물 정리","설명":"설정자가 매수를 청구하면 전세권자는 정당한 이유 없이 거절하지 못한다. 설정자 동의를 얻어 부속시킨 물건은 전세권자가 매수를 청구할 수 있다(제316조)"},{"이름":"동시이행","설명":"목적물 인도·말소등기 서류 교부와 전세금 반환이 동시이행(제317조)"},{"이름":"반환 지체","설명":"설정자가 전세금 반환을 지체하면 전세권자는 민사집행법에 따라 목적물 경매를 청구할 수 있다(제318조)"},{"이름":"손해 충당","설명":"전세권자 책임 있는 사유로 목적물이 멸실된 때 설정자는 전세금에서 손해를 충당하고 잉여를 반환, 부족하면 다시 청구(제315조제2항)"}]}],"함정":"4번과 5번을 틀린 문장으로 고르기 쉽다. 제304조·제305조는 건물 전세권의 특칙이라 낯설 뿐 두 문장 모두 조문 그대로 옳다. 1번은 동시이행(제317조)을 반환 선행으로 바꾼 문장이다. 정답률 24%."}},{"i":"S3-1-1-민법-22","r":"S3","g":1,"c":1,"n":62,"s":"민법","q":"유치권에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["유치권자는 채무자의 승낙 없이도 유치물을 타인에게 담보로 제공할 수 있다.","유치권을 행사하는 동안에는 피담보채권의 소멸시효가 진행하지 않는다.","유치물이 경매되면 유치권자는 그 대가에서 다른 채권자보다 먼저 변제를 받을 수 있다.","유치권자가 점유를 침탈당한 후 점유회수의 소를 제기하여 점유를 회복하면 유치권은 소멸하지 않은 것으로 본다.","건물 임차인의 임대인에 대한 임차보증금반환채권은 임차건물에 관하여 생긴 채권이므로, 이를 담보하기 위하여 그 건물에 대한 유치권이 성립한다."],"a":[4],"L":"민2-7","o":"변형","x":{"한줄":"점유를 잃으면 유치권이 소멸하지만(제328조), 점유를 침탈당했다가 점유회수의 소로 점유를 되찾으면 점유를 상실하지 않은 것으로 되어 유치권이 그대로 유지된다.","근거":[{"법령":"민법","조문":"제328조","원문":"유치권은 점유의 상실로 인하여 소멸한다."},{"법령":"민법","조문":"제324조제2항","원문":"유치권자는 채무자의 승낙없이 유치물의 사용, 대여 또는 담보제공을 하지 못한다. 그러나 유치물의 보존에 필요한 사용은 그러하지 아니하다."},{"법령":"민법","조문":"제326조","원문":"유치권의 행사는 채권의 소멸시효의 진행에 영향을 미치지 아니한다."},{"판례":"대법원 판례(점유회수와 유치권)","요지":"점유를 침탈당한 유치권자가 점유회수의 소를 제기하여 점유를 회복하면 점유를 상실하지 않은 것으로 되어 유치권은 소멸하지 않는다. 점유회수의 소를 제기하지 않고 점유를 잃은 채로 두면 소멸한다."},{"판례":"대법원 판례(임차보증금·권리금)","요지":"건물 임차인의 임차보증금반환채권, 권리금반환청구권은 그 건물 자체에 관하여 생긴 채권이 아니어서 견련성이 없고, 이를 담보하는 유치권은 성립하지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"유치권자는 채무자 승낙 없이 유치물을 사용·대여·담보제공할 수 없다. 보존에 필요한 사용만 예외다(제324조제2항). 위반하면 채무자가 유치권 소멸을 청구할 수 있다(제324조제3항)."},{"번호":2,"판정":"틀림","설명":"유치권의 행사는 피담보채권의 소멸시효 진행에 영향이 없다. 유치하고 있어도 시효는 계속 진행한다(제326조)."},{"번호":3,"판정":"틀림","설명":"유치권에는 우선변제권이 없다. 유치권자는 채권 변제를 위해 경매할 수 있을 뿐이고(제322조제1항), 경매로 환가된 대가에서 먼저 변제받는 권리는 없다. 다만 경락인에게 인도를 거절할 수 있다."},{"번호":4,"판정":"옳음","설명":"점유회수의 소로 점유를 회복하면 점유를 상실하지 않은 것으로 다룬다(판례). 점유를 상실하면 소멸한다는 제328조의 예외다."},{"번호":5,"판정":"틀림","설명":"임차보증금반환채권은 건물 자체에서 생긴 채권이 아니라 임대차계약에서 생긴 채권이어서 견련성이 없다. 판례는 유치권을 인정하지 않는다."}],"개념":[{"종류":"표","제목":"유치권자의 권리·의무","머리":["구분","내용","조문"],"행":[["성립요건","타인의 물건·유가증권 점유 + 그 물건에 관하여 생긴 채권 + 변제기 도래 + 점유가 불법행위로 인한 것이 아닐 것","제320조"],["불가분성","채권 전부를 변제받을 때까지 유치물 전부에 대해 행사","제321조"],["경매·간이변제충당","경매 가능, 정당한 이유가 있으면 감정인 평가로 직접 변제충당을 법원에 청구(미리 채무자에게 통지)","제322조"],["과실수취","과실을 수취해 다른 채권보다 먼저 채권 변제에 충당, 금전이 아닌 과실은 경매","제323조"],["선관의무","선량한 관리자의 주의로 점유, 채무자 승낙 없는 사용·대여·담보제공 금지(보존에 필요한 사용 제외)","제324조"],["상환청구","필요비는 소유자에게 상환 청구, 유익비는 가액 증가가 현존할 때 소유자 선택에 따라 청구","제325조"],["시효","유치권 행사는 피담보채권 소멸시효 진행에 영향 없음","제326조"]]},{"종류":"표","제목":"유치권의 소멸","머리":["사유","소멸 여부","설명"],"행":[["포기","소멸","유치권자가 포기하면 소멸한다"],["점유의 상실","소멸","제328조. 침탈당했다가 점유회수의 소로 회복하면 소멸하지 않은 것으로 봄"],["목적물 전부 멸실","소멸","목적물이 없어지면 유치권도 없어진다"],["피담보채권 소멸","소멸","담보물권의 부종성"],["채무자의 소멸청구","소멸","의무 위반 시(제324조제3항), 상당한 담보 제공 시(제327조)"],["소유자의 목적물 양도","소멸하지 않음","유치권은 물권이라 새 소유자에게도 주장할 수 있다"]]}],"함정":"5번을 고르기 쉽다. 임차보증금반환채권과 권리금반환청구권은 건물 자체에서 생긴 채권이 아니어서 견련성이 없다. 2번은 제326조에 반한다. 유치권 행사 중에도 시효는 진행한다."}},{"i":"S3-1-1-민법-23","r":"S3","g":1,"c":1,"n":63,"s":"민법","q":"저당권에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["전세권은 저당권의 객체가 될 수 없다.","저당권 설정은 권리의 이전적 승계에 해당한다.","민법 제365조에 따라 토지와 건물의 일괄경매를 청구한 토지 저당권자는 그 건물의 경매대가에서 우선변제를 받을 수 있다.","건물 건축 개시 전의 나대지에 저당권이 설정될 당시 저당권자가 그 토지 소유자의 건물 건축에 동의한 경우, 저당토지의 임의경매로 인한 법정지상권은 성립하지 않는다.","저당물의 소유권을 취득한 제3자는 그 저당물의 보존을 위해 필요비를 지출하더라도 특별한 사정이 없는 한 그 저당물의 경매대가에서 우선상환을 받을 수 없다."],"a":[4],"L":"민2-8","o":"기출","x":{"한줄":"법정지상권(제366조)은 경매 당시 토지와 건물이 다른 소유자에 속하게 될 때 저당권 설정 당시 건물이 있었던 경우에 성립한다. 나대지에 설정한 저당권은 건축에 동의했어도 법정지상권이 성립하지 않는다.","근거":[{"법령":"민법","조문":"제366조","원문":"저당물의 경매로 인하여 토지와 그 지상건물이 다른 소유자에 속한 경우에는 토지소유자는 건물소유자에 대하여 지상권을 설정한 것으로 본다. 그러나 지료는 당사자의 청구에 의하여 법원이 이를 정한다."},{"법령":"민법","조문":"제365조","원문":"토지를 목적으로 저당권을 설정한 후 그 설정자가 그 토지에 건물을 축조한 때에는 저당권자는 토지와 함께 그 건물에 대하여도 경매를 청구할 수 있다. 그러나 그 건물의 경매대가에 대하여는 우선변제를 받을 권리가 없다."},{"법령":"민법","조문":"제367조","원문":"저당물의 제삼취득자가 그 부동산의 보존, 개량을 위하여 필요비 또는 유익비를 지출한 때에는 제203조제1항, 제2항의 규정에 의하여 저당물의 경매대가에서 우선상환을 받을 수 있다."},{"법령":"민법","조문":"제371조제1항","원문":"본장의 규정은 지상권 또는 전세권을 저당권의 목적으로 한 경우에 준용한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"전세권도 저당권의 목적이 된다. 지상권·전세권을 목적으로 한 저당권에는 저당권 규정을 준용한다(제371조제1항)."},{"번호":2,"판정":"틀림","설명":"저당권 설정은 소유권 위에 제한물권을 새로 만드는 설정적(창설적) 승계다. 이전적 승계는 소유권 양도처럼 권리가 그대로 넘어가는 경우다."},{"번호":3,"판정":"틀림","설명":"일괄경매를 청구해도 건물의 경매대가에서는 우선변제를 받지 못한다. 우선변제는 토지의 경매대가에서만 받는다(제365조 단서)."},{"번호":4,"판정":"옳음","설명":"저당권 설정 당시 건물이 없던 나대지는 법정지상권이 성립하지 않는다. 저당권자가 건축에 동의했더라도 같다는 것이 판례다."},{"번호":5,"판정":"틀림","설명":"저당물의 제3취득자가 지출한 필요비·유익비는 제203조에 따라 경매대가에서 우선상환을 받는다(제367조)."}],"개념":[{"종류":"비교","제목":"저당토지 위 건물의 법적 취급","왼쪽":{"이름":"저당권 설정 당시 건물이 있던 경우","항목":["토지와 건물이 동일 소유자 소유였을 것","경매로 토지와 건물의 소유자가 달라지면 법정지상권 성립(제366조)","지료는 당사자 청구로 법원이 정함","건물이 개축·신축되어도 구건물을 기준으로 한 범위에서 성립(판례)"]},"오른쪽":{"이름":"나대지에 저당권이 설정된 후 건물이 지어진 경우","항목":["법정지상권 성립하지 않음(저당권자가 건축에 동의했어도 같음, 판례)","저당권자는 토지와 건물의 일괄경매 청구 가능(제365조 본문)","일괄경매에서도 건물 경매대가에서는 우선변제 불가(제365조 단서)","건물 소유자에게 법정지상권이 없으므로 경매 후 매수인은 건물 철거를 청구할 수 있음"]}},{"종류":"비교","제목":"승계의 구분","왼쪽":{"이름":"설정적(창설적) 승계","항목":["소유권 위에 제한물권을 새로 만드는 것","지상권·전세권·저당권의 설정","저당권 설정이 여기에 해당"]},"오른쪽":{"이름":"이전적 승계","항목":["권리가 동일성을 유지한 채 이전","소유권 양도, 저당권부 채권의 양도","이 경우 저당권도 수반성에 따라 함께 이전"]}}],"함정":"3번은 일괄경매를 청구하면 건물 대가에서도 우선변제를 받는다고 오해하기 쉽다. 제365조 단서가 이를 막는다. 4번은 정답률 21%로, 건축 동의 사실이 법정지상권을 만든다고 생각하면 틀린다. 법정지상권은 설정 당시 건물이 있었는지를 본다."}},{"i":"S3-1-1-민법-24","r":"S3","g":1,"c":1,"n":64,"s":"민법","q":"저당권에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["저당권의 효력은 설정행위에 다른 약정이 없으면 저당부동산에 부합된 물건과 종물에 미친다.","저당권으로 담보되는 지연배상은 원본의 이행기일을 경과한 후의 2년분에 한한다.","저당권의 실행비용은 그 비용이 있음을 등기하지 않으면 피담보채권의 범위에 속하지 않는다.","저당권은 그 담보한 채권과 분리하여 다른 채권의 담보로 제공할 수 있다.","저당물의 소유권을 취득한 제3자는 그 저당물의 경매에서 경매인이 될 수 없다."],"a":[1],"L":"민2-8","o":"변형","x":{"한줄":"저당권의 효력은 저당부동산에 부합된 물건과 종물에 미치고, 설정행위로 달리 정할 수 있다(제358조).","근거":[{"법령":"민법","조문":"제358조","원문":"저당권의 효력은 저당부동산에 부합된 물건과 종물에 미친다. 그러나 법률에 특별한 규정 또는 설정행위에 다른 약정이 있으면 그러하지 아니하다."},{"법령":"민법","조문":"제360조","원문":"저당권은 원본, 이자, 위약금, 채무불이행으로 인한 손해배상 및 저당권의 실행비용을 담보한다. 그러나 지연배상에 대하여는 원본의 이행기일을 경과한 후의 1년분에 한하여 저당권을 행사할 수 있다."},{"법령":"민법","조문":"제361조","원문":"저당권은 그 담보한 채권과 분리하여 타인에게 양도하거나 다른 채권의 담보로 하지 못한다."},{"법령":"민법","조문":"제363조제2항","원문":"저당물의 소유권을 취득한 제삼자도 경매인이 될 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"부합물과 종물에 효력이 미친다. 특약으로 제외할 수 있다(제358조). 종물은 저당권 설정 당시 이미 있던 것에도, 설정 후 생긴 것에도 미친다는 것이 판례다."},{"번호":2,"판정":"틀림","설명":"지연배상은 원본의 이행기일을 경과한 후 1년분에 한해 담보된다(제360조 단서). 후순위권리자와 제3취득자를 보호하려는 규정이다."},{"번호":3,"판정":"틀림","설명":"저당권 실행비용은 등기하지 않아도 피담보채권의 범위에 들어간다(제360조). 이자는 등기해야 담보된다."},{"번호":4,"판정":"틀림","설명":"저당권은 피담보채권과 분리하여 양도하거나 다른 채권의 담보로 제공하지 못한다(제361조). 부종성·수반성 때문이다."},{"번호":5,"판정":"틀림","설명":"저당물의 소유권을 취득한 제3자도 경매인이 될 수 있다(제363조제2항)."}],"개념":[{"종류":"표","제목":"저당권의 효력이 미치는 범위","머리":["대상","효력 여부","조문·설명"],"행":[["부합물·종물","미침(특약으로 제외 가능)","제358조"],["과실","압류 후 설정자가 수취한 과실 또는 수취할 수 있는 과실에 미침","제359조"],["물상대위","멸실·훼손·공용징수로 설정자가 받을 금전에 미침, 지급·인도 전에 압류 필요","제370조, 제342조"],["저당지상 건물","설정자가 축조한 건물에 대해 일괄경매 청구 가능, 건물 대가는 우선변제 불가","제365조"],["법정지상권","설정 당시 건물이 있고 경매로 소유자가 달라지면 성립","제366조"],["저당물의 보충","설정자 책임 있는 사유로 가액이 현저히 감소하면 원상회복·담보제공 청구","제362조"]]},{"종류":"표","제목":"피담보채권의 범위(제360조)","머리":["항목","등기 필요 여부","내용"],"행":[["원본","필요","등기된 채권액"],["이자","필요","등기해야 담보됨"],["위약금","불필요","제360조에 열거"],["채무불이행 손해배상","불필요","지연배상은 이행기일 경과 후 1년분에 한함"],["저당권 실행비용","불필요","경매 신청비용 등"]]}],"함정":"4번은 피담보채권 양도와 분리해서 담보로 제공할 수 있다고 하는데, 부종성 때문에 제361조가 금지한다. 2번은 1년분을 2년분으로 바꾼 것이다. 3번은 이자와 실행비용의 등기 요부를 뒤바꾼 것이다."}},{"i":"S3-1-1-민법-25","r":"S3","g":1,"c":1,"n":65,"s":"민법","q":"甲(요약자)과 乙(낙약자)은 乙이 丙(수익자)에게 1억원을 지급하기로 하는 제3자를 위한 계약을 체결하였다. 이에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["丙의 권리는 계약이 체결된 때에 당연히 생기며, 丙의 수익의 의사표시는 필요하지 않다.","乙은 甲과의 계약에 기한 동시이행의 항변으로 丙에게 대항할 수 있다.","丙이 수익의 의사표시를 한 후에도 甲과 乙은 합의로 丙의 권리를 변경하거나 소멸시킬 수 있다.","甲의 착오로 계약이 취소된 경우, 丙은 착오취소로써 대항할 수 없는 제3자에 해당한다.","丙은 계약의 당사자가 아니므로 乙의 채무불이행을 이유로 한 손해배상을 乙에게 청구할 수 없다."],"a":[2],"L":"민3-1","o":"변형","x":{"한줄":"낙약자는 요약자와의 계약에서 생긴 항변으로 수익자에게 대항할 수 있다(제542조). 동시이행의 항변도 포함된다.","근거":[{"법령":"민법","조문":"제542조","원문":"채무자는 제539조의 계약에 기한 항변으로 그 계약의 이익을 받을 제삼자에게 대항할 수 있다."},{"법령":"민법","조문":"제539조","원문":"①계약에 의하여 당사자 일방이 제삼자에게 이행할 것을 약정한 때에는 그 제삼자는 채무자에게 직접 그 이행을 청구할 수 있다. ②전항의 경우에 제삼자의 권리는 그 제삼자가 채무자에 대하여 계약의 이익을 받을 의사를 표시한 때에 생긴다."},{"법령":"민법","조문":"제541조","원문":"제539조의 규정에 의하여 제삼자의 권리가 생긴 후에는 당사자는 이를 변경 또는 소멸시키지 못한다."},{"판례":"대법원 판례(수익자와 착오취소)","요지":"제3자를 위한 계약의 수익자는 요약자의 착오취소를 이유로 대항할 수 없는 제3자(제109조제2항)에 해당하지 않는다. 계약이 취소되면 수익자도 그 효과를 받는다."},{"판례":"대법원 판례(수익자의 손해배상청구)","요지":"수익의 의사표시를 한 수익자는 낙약자의 채무불이행으로 입은 손해의 배상을 낙약자에게 청구할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"수익자의 권리는 수익의 의사표시를 한 때에 생긴다(제539조제2항). 계약체결만으로 당연히 생기지 않는다."},{"번호":2,"판정":"옳음","설명":"낙약자는 요약자와의 계약에 기한 항변(동시이행, 무효·취소 사유 등)으로 수익자에게 대항할 수 있다(제542조)."},{"번호":3,"판정":"틀림","설명":"수익자의 권리가 생긴 후에는 당사자가 이를 변경하거나 소멸시키지 못한다(제541조)."},{"번호":4,"판정":"틀림","설명":"수익자는 착오취소로 대항할 수 없는 제3자에 해당하지 않는다(판례). 계약 당사자와 동일하게 취소의 영향을 받는다."},{"번호":5,"판정":"틀림","설명":"수익의 의사표시를 한 수익자는 낙약자의 채무불이행으로 입은 손해의 배상을 낙약자에게 청구할 수 있다(판례). 해제권과 원상회복청구권이 없을 뿐이다."}],"개념":[{"종류":"흐름","제목":"제3자를 위한 계약의 법률관계","단계":[{"이름":"요약자↔낙약자(기본관계·보상관계)","설명":"계약의 효력은 이 관계에서 생긴다. 요약자·낙약자가 계약의 당사자다"},{"이름":"낙약자→수익자","설명":"낙약자가 제3자에게 이행하기로 약정(제539조제1항)"},{"이름":"수익의 의사표시","설명":"수익자가 낙약자에게 계약의 이익을 받겠다는 의사표시를 한 때 수익자의 권리가 생김(제539조제2항)"},{"이름":"권리 확정","설명":"권리가 생긴 후 당사자는 변경·소멸 불가(제541조)"},{"이름":"낙약자의 최고","설명":"상당한 기간을 정해 확답을 최고, 기간 내 확답이 없으면 거절한 것으로 봄(제540조)"}]},{"종류":"표","제목":"제3자를 위한 계약의 당사자별 권리","머리":["당사자","할 수 있는 것","할 수 없는 것"],"행":[["수익자","낙약자에 대한 이행청구, 채무불이행에 따른 손해배상 청구","계약 해제권, 해제에 따른 원상회복청구권"],["요약자","낙약자에게 수익자에게 이행하라고 청구, 낙약자 채무불이행 시 해제권","—"],["낙약자","요약자와의 계약에 기한 항변으로 수익자에게 대항(제542조)","수익자에 대한 부당이득반환 청구(해제 후)"],["대가관계","요약자와 수익자 사이의 관계가 무효여도 요약자·낙약자 계약 효력에 영향 없음","요약자가 대가관계 부존재를 이유로 낙약자에 대한 채무 이행을 거절하는 것"]]}],"함정":"4번은 정답률이 낮은 고전 쟁점이다. 수익자를 제109조제2항의 보호받는 제3자로 보면 틀린다. 3번은 수익의 의사표시 이후의 권리 확정(제541조)을 놓친 경우에 고르게 된다."}},{"i":"S3-1-1-민법-26","r":"S3","g":1,"c":1,"n":66,"s":"민법","q":"부동산 매매계약이 합의해제된 경우에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["매도인은 수령한 대금에 그 받은 날부터의 이자를 가산하여 반환하여야 한다.","특약이 없더라도 매수인은 매도인에게 채무불이행에 따른 손해배상을 청구할 수 있다.","합의해제는 해제권자의 일방적 의사표시만으로 효력이 생긴다.","합의해제의 소급효는 법정해제의 경우와 같이 제3자의 권리를 해하지 못한다.","매도인에게 소유권이 복귀하려면 매수인 명의의 이전등기가 말소되어야 한다."],"a":[4],"L":"민3-1","o":"변형","x":{"한줄":"합의해제도 소급효가 있지만 법정해제처럼 제3자의 권리를 해하지 못한다(제548조제1항 단서의 취지).","근거":[{"법령":"민법","조문":"제548조","원문":"①당사자 일방이 계약을 해제한 때에는 각 당사자는 그 상대방에 대하여 원상회복의 의무가 있다. 그러나 제삼자의 권리를 해하지 못한다. ②전항의 경우에 반환할 금전에는 그 받은 날로부터 이자를 가하여야 한다."},{"법령":"민법","조문":"제543조제1항","원문":"계약 또는 법률의 규정에 의하여 당사자의 일방이나 쌍방이 해지 또는 해제의 권리가 있는 때에는 그 해지 또는 해제는 상대방에 대한 의사표시로 한다."},{"법령":"민법","조문":"제551조","원문":"계약의 해지 또는 해제는 손해배상의 청구에 영향을 미치지 아니한다."},{"판례":"대법원 판례(합의해제의 효과)","요지":"합의해제는 계약으로 하는 해제라 법정해제 규정이 그대로 적용되지 않는다. 반환할 금전에 이자를 붙일 의무가 없고, 손해배상은 특약이 없으면 청구할 수 없다. 소급효가 제3자의 권리를 해하지 못한다는 점은 법정해제와 같다."}],"선지":[{"번호":1,"판정":"틀림","설명":"받은 날부터의 이자 가산은 법정해제의 효과다(제548조제2항). 합의해제는 이자를 붙이는 특약이 없으면 가산하지 않는다(판례)."},{"번호":2,"판정":"틀림","설명":"손해배상을 청구하려면 합의에서 정해야 한다. 제551조는 법정해제 규정이어서 합의해제에는 적용되지 않는다(판례)."},{"번호":3,"판정":"틀림","설명":"합의해제는 당사자 쌍방의 합의(계약)로 한다. 해제권자의 일방적 의사표시로 하는 것은 법정해제와 약정해제다(제543조제1항)."},{"번호":4,"판정":"옳음","설명":"합의해제의 소급효는 제3자의 권리를 해하지 못한다(판례). 이때 제3자는 합의해제 이전에 새로운 이해관계를 맺고 등기·인도 등으로 완전한 권리를 취득한 자다."},{"번호":5,"판정":"틀림","설명":"해제의 물권적 효과로 소유권은 말소등기 없이도 당연히 매도인에게 복귀한다(판례). 말소등기는 대외적 정리를 위해 필요하다."}],"개념":[{"종류":"비교","제목":"법정해제와 합의해제","왼쪽":{"이름":"법정해제(법률·약정에 의한 해제권 행사)","항목":["해제권자의 일방적 의사표시(제543조)","반환 금전에 받은 날부터 이자 가산(제548조제2항)","손해배상 청구 가능(제551조)","제3자의 권리를 해하지 못함(제548조제1항 단서)","상대방의 원상회복의무와 동시이행(제549조)"]},"오른쪽":{"이름":"합의해제(쌍방의 해제계약)","항목":["당사자 쌍방의 합의가 필요","이자 가산 의무 없음(특약 시 가능)","손해배상은 합의 내용에 따름(특약이 없으면 청구 불가)","제3자의 권리를 해하지 못함(판례)","원상회복 범위도 합의 내용에 따름"]}},{"종류":"표","제목":"법정해제권의 발생과 소멸","머리":["구분","내용","조문"],"행":[["이행지체","상당한 기간을 정해 최고, 그 기간 내 이행하지 않으면 해제. 미리 이행하지 않을 의사를 표시한 경우 최고 불필요","제544조"],["정기행위","일정한 시일·기간 내 이행하지 않으면 목적을 달성할 수 없는 경우 최고 없이 해제","제545조"],["이행불능","채무자의 책임 있는 사유로 이행불능이면 해제","제546조"],["당사자가 여럿일 때","해제는 전원으로부터 또는 전원에 대하여, 1인에 대한 소멸은 모두에게 소멸","제547조"],["해제권 행사 여부의 최고","행사기간이 없으면 상당한 기간을 정해 확답 최고, 기간 내 통지가 없으면 해제권 소멸","제552조"],["해제권의 소멸","해제권자의 고의·과실로 목적물이 현저히 훼손되거나 반환 불능이 된 때, 가공·개조로 다른 종류의 물건이 된 때","제553조"]]}],"함정":"2번은 법정해제의 손해배상(제551조)을 합의해제에 그대로 적용한 오답이다. 1번도 같은 혼동이다. 5번은 말소등기가 있어야 소유권이 복귀한다고 보는 오해다. 해제의 물권적 효과는 당연 복귀다."}},{"i":"S3-1-1-민법-27","r":"S3","g":1,"c":1,"n":67,"s":"민법","q":"甲은 자신의 X토지를 乙에게 매도하면서 매매대금은 乙이 丙에게 직접 지급하기로 약정하였다. 그 후 丙은 乙에게 수익의 의사표시를 하였다. 이에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲과 乙은 丙의 동의 없이 계약을 합의해제하여 丙의 권리를 소멸시킬 수 없다.","乙이 대금을 지급하지 않으면 丙은 乙에게 직접 대금의 지급을 청구할 수 있다.","甲이 소유권이전등기를 지체하는 경우, 乙은 동시이행의 항변권으로 丙의 대금지급청구를 거절할 수 있다.","乙이 대금을 지급하지 않으면 甲은 丙의 동의 없이도 상당한 기간을 정한 최고 후 계약을 해제할 수 있다.","乙이 丙에게 대금을 이미 지급한 후 甲의 채무불이행을 이유로 乙이 계약을 해제한 경우, 乙은 丙을 상대로 지급한 대금의 반환을 청구할 수 있다."],"a":[5],"L":"민3-1","o":"변형","x":{"한줄":"해제 후 원상회복은 계약 당사자 사이에서 한다. 낙약자 乙은 수익자 丙이 아니라 요약자 甲에게 이미 지급한 대금의 반환을 청구한다.","근거":[{"법령":"민법","조문":"제541조","원문":"제539조의 규정에 의하여 제삼자의 권리가 생긴 후에는 당사자는 이를 변경 또는 소멸시키지 못한다."},{"법령":"민법","조문":"제542조","원문":"채무자는 제539조의 계약에 기한 항변으로 그 계약의 이익을 받을 제삼자에게 대항할 수 있다."},{"법령":"민법","조문":"제548조제1항","원문":"당사자 일방이 계약을 해제한 때에는 각 당사자는 그 상대방에 대하여 원상회복의 의무가 있다. 그러나 제삼자의 권리를 해하지 못한다."},{"판례":"대법원 판례(제3자를 위한 계약의 해제)","요지":"요약자는 수익자의 동의 없이 낙약자의 채무불이행을 이유로 계약을 해제할 수 있다. 해제 후 낙약자의 부당이득반환 청구는 계약 상대방인 요약자를 상대로 하고 수익자를 상대로는 하지 못한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"수익의 의사표시로 수익자의 권리가 확정되면 당사자는 이를 변경·소멸시키지 못한다(제541조). 합의해제도 수익자의 동의가 있어야 효력을 주장할 수 있다(판례)."},{"번호":2,"판정":"옳음","설명":"수익의 의사표시를 한 수익자는 낙약자에게 직접 이행을 청구할 수 있다(제539조)."},{"번호":3,"판정":"옳음","설명":"낙약자는 요약자와의 계약에 기한 항변(동시이행)으로 수익자에게 대항할 수 있다(제542조)."},{"번호":4,"판정":"옳음","설명":"요약자는 계약 당사자라 낙약자의 이행지체에 대해 제544조에 따라 최고·해제를 할 수 있고 수익자의 동의는 필요 없다(판례)."},{"번호":5,"판정":"틀림","설명":"해제 후 원상회복은 계약 당사자 사이에서만 이루어진다. 乙은 丙이 아니라 甲에게 지급한 대금의 반환을 청구한다(판례)."}],"개념":[{"종류":"표","제목":"제3자를 위한 계약과 해제","머리":["상황","해제권자","효과"],"행":[["낙약자 채무불이행","요약자","수익자 동의 없이 최고 후 해제 가능(제544조)"],["요약자 채무불이행","낙약자","낙약자가 해제 후 요약자에게 반환 청구"],["수익자","해제권 없음","해제를 원인으로 한 원상회복청구권도 없음"],["합의해제","요약자·낙약자","수익의 의사표시 후에는 수익자 동의 없이 권리를 소멸시키지 못함(제541조)"],["해제 후 수익자의 지위","—","낙약자의 채무불이행으로 입은 손해는 수익자가 낙약자에게 배상 청구 가능"]]},{"종류":"흐름","제목":"대금을 丙에게 지급하기로 한 매매의 흐름","단계":[{"이름":"계약 체결","설명":"甲(요약자·매도인)과 乙(낙약자·매수인)이 대금을 丙에게 지급하기로 약정"},{"이름":"수익의 의사표시","설명":"丙이 乙에게 수익의 의사표시를 하면 직접 청구권이 확정(제539조제2항)"},{"이름":"이행 단계","설명":"乙은 甲의 이전등기 이행과 동시이행으로 丙에게 대금 지급(제542조)"},{"이름":"채무불이행","설명":"乙 불이행: 甲이 최고 후 해제 / 甲 불이행: 乙이 해제"},{"이름":"원상회복","설명":"계약 당사자끼리 정리. 丙의 정리는 요약자·낙약자가 하고 수익자에게 직접 청구하지 않음"}]}],"함정":"5번이 정답이다. 이미 지급한 대금을 수익자에게 돌려달라고 하기 쉽지만, 판례는 계약 당사자 사이에서 청산하게 한다. 1번은 제541조 때문에 옳다. 4번은 수익자 동의가 필요하다고 오해하기 쉽다. 정답률 30%."}},{"i":"S3-1-1-민법-28","r":"S3","g":1,"c":1,"n":68,"s":"민법","q":"쌍무계약상 위험부담에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["채무자의 책임 있는 사유로 후발적 불능이 발생한 경우에는 위험부담의 법리가 적용되어 채무자는 상대방의 이행을 청구하지 못한다.","매매목적물이 이행기 전에 강제수용된 경우, 매수인이 대상청구권을 행사하더라도 매도인은 매매대금의 지급을 청구할 수 없다.","채권자의 수령지체 중에 당사자 쌍방의 책임 없는 사유로 이행불능이 된 경우, 채무자는 상대방의 이행을 청구할 수 있다.","매도인의 책임 없는 사유로 목적물이 멸실된 경우, 매수인이 이미 지급한 대금은 반환을 청구하지 못한다.","채권자의 책임 있는 사유로 채무가 불능이 된 경우, 채무자는 자기 채무를 면함으로써 얻은 이익이 있어도 이를 채권자에게 상환할 필요가 없다."],"a":[3],"L":"민3-1","o":"변형","x":{"한줄":"채권자의 수령지체 중에 당사자 쌍방의 책임 없는 사유로 불능이 된 때에도 채무자는 상대방의 이행을 청구할 수 있다(제538조제1항 후단).","근거":[{"법령":"민법","조문":"제537조","원문":"쌍무계약의 당사자 일방의 채무가 당사자쌍방의 책임없는 사유로 이행할 수 없게 된 때에는 채무자는 상대방의 이행을 청구하지 못한다."},{"법령":"민법","조문":"제538조","원문":"①쌍무계약의 당사자 일방의 채무가 채권자의 책임있는 사유로 이행할 수 없게 된 때에는 채무자는 상대방의 이행을 청구할 수 있다. 채권자의 수령지체 중에 당사자쌍방의 책임없는 사유로 이행할 수 없게 된 때에도 같다. ②전항의 경우에 채무자는 자기의 채무를 면함으로써 이익을 얻은 때에는 이를 채권자에게 상환하여야 한다."},{"법령":"민법","조문":"제546조","원문":"채무자의 책임있는 사유로 이행이 불능하게 된 때에는 채권자는 계약을 해제할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"채무자의 책임 있는 사유로 이행불능이 되면 위험부담이 아니라 채무불이행 문제다. 채권자는 계약을 해제하고(제546조) 손해배상을 청구한다(제551조)."},{"번호":2,"판정":"틀림","설명":"대상청구권을 행사하는 매수인은 반대급부인 매매대금을 지급할 의무를 진다. 매도인은 대금 지급을 청구할 수 있다(판례)."},{"번호":3,"판정":"옳음","설명":"수령지체 중에 쌍방 무책 사유로 불능이 되면 채무자는 반대급부를 청구할 수 있다(제538조제1항 후단)."},{"번호":4,"판정":"틀림","설명":"쌍방 무책 불능이면 매도인은 대금을 청구할 수 없고(제537조), 이미 받은 대금은 법률상 원인 없는 이득이어서 부당이득으로 반환해야 한다."},{"번호":5,"판정":"틀림","설명":"채무자는 채무를 면함으로써 얻은 이익을 채권자에게 상환해야 한다(제538조제2항)."}],"개념":[{"종류":"표","제목":"이행불능의 원인별 효과","머리":["불능의 원인","채무","반대급부(대금 등)","조문"],"행":[["채무자의 책임 있는 사유","본래 채무 소멸, 손해배상 채무로 전환","채권자는 해제 가능","제546조, 제551조"],["당사자 쌍방의 책임 없는 사유","소멸","채무자는 청구 못함, 이미 받았다면 반환(채무자위험부담주의)","제537조"],["채권자의 책임 있는 사유","소멸","채무자는 청구 가능, 면함으로써 얻은 이익은 상환","제538조"],["채권자의 수령지체 중 쌍방 무책","소멸","채무자는 청구 가능","제538조제1항 후단"],["대상청구권(판례)","불능으로 채무자가 얻은 대상(보상금·배상금 등)","대상청구권을 행사하면 채권자도 반대급부 이행","—"]]},{"종류":"흐름","제목":"쌍무계약 이행불능 사건 판단 순서","단계":[{"이름":"1단계","설명":"불능이 계약 성립 후에 생긴 후발적 불능인지 확인(원시적 불능은 계약체결상의 과실 문제)"},{"이름":"2단계","설명":"채무자에게 책임 있으면 채무불이행. 해제(제546조)와 손해배상"},{"이름":"3단계","설명":"당사자 쌍방 무책이면 제537조. 채무자는 반대급부 청구 불가"},{"이름":"4단계","설명":"채권자 책임 또는 수령지체 중 쌍방 무책이면 제538조. 채무자는 반대급부 청구 가능"},{"이름":"5단계","설명":"채무자가 대상을 얻었으면 채권자가 대상청구권 행사 가능, 이때 반대급부도 이행"}]}],"함정":"1번이 잘 걸린다. 채무자 책임 사유는 위험부담이 아니라 채무불이행이다. 5번은 제538조제2항의 이익 상환을 빠뜨린 문장이다. 4번은 제537조의 결과로 이미 지급한 대금이 부당이득이 되는 점을 놓친다."}},{"i":"S3-1-1-민법-29","r":"S3","g":1,"c":1,"n":69,"s":"민법","q":"제3자를 위한 계약에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["요약자와 낙약자의 계약이 무효이거나 취소된 경우, 수익자는 낙약자에게 이행을 청구할 수 없다.","수익자는 계약 체결 당시에 현존하고 특정되어 있어야 하므로, 태아나 설립 중의 법인은 수익자가 될 수 없다.","낙약자가 상당한 기간을 정하여 수익 여부의 확답을 수익자에게 최고하였으나 그 기간 내에 확답을 받지 못한 경우, 수익자가 계약의 이익을 받기를 거절한 것으로 본다.","채무자와 인수인의 계약으로 체결되는 병존적 채무인수는 제3자를 위한 계약으로 볼 수 있다.","요약자와 수익자 사이의 대가관계가 무효이더라도, 낙약자는 그 부존재를 이유로 수익자에 대한 이행을 거절할 수 없다."],"a":[2],"L":"민3-1","o":"변형","x":{"한줄":"수익자는 계약 체결 당시에 현존하거나 특정되어 있을 필요가 없다. 태아나 설립 중의 법인도 수익자가 될 수 있다.","근거":[{"법령":"민법","조문":"제540조","원문":"전조의 경우에 채무자는 상당한 기간을 정하여 계약의 이익의 향수여부의 확답을 제삼자에게 최고할 수 있다. 채무자가 그 기간내에 확답을 받지 못한 때에는 제삼자가 계약의 이익을 받을 것을 거절한 것으로 본다."},{"법령":"민법","조문":"제542조","원문":"채무자는 제539조의 계약에 기한 항변으로 그 계약의 이익을 받을 제삼자에게 대항할 수 있다."},{"판례":"대법원 판례(수익자의 자격)","요지":"제3자를 위한 계약에서 제3자는 계약 체결 당시 현존하거나 특정되어 있을 필요가 없고, 수익의 의사표시를 할 때 현존·특정되면 된다."},{"판례":"대법원 판례(대가관계)","요지":"요약자와 수익자 사이의 대가관계의 부존재나 하자는 낙약자와 요약자 사이의 계약 효력에 영향이 없다. 낙약자는 대가관계의 흠을 이유로 수익자에 대한 이행을 거절하지 못한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"기본계약이 무효·취소되면 낙약자는 그 항변으로 수익자에게 대항할 수 있다(제542조). 수익자의 권리는 유효한 기본계약을 전제로 한다."},{"번호":2,"판정":"틀림","설명":"수익자는 계약 체결 당시 현존·특정되어 있지 않아도 된다(판례). 태아, 설립 중의 법인도 수익자가 될 수 있다."},{"번호":3,"판정":"옳음","설명":"낙약자의 최고에 대해 기간 내 확답이 없으면 수익자가 이익을 받기를 거절한 것으로 본다(제540조)."},{"번호":4,"판정":"옳음","설명":"채무자와 인수인 사이의 계약으로 하는 병존적 채무인수는 채권자를 수익자로 하는 제3자를 위한 계약으로 본다(판례). 채권자의 수익의 의사표시로 인수인에 대한 권리가 생긴다."},{"번호":5,"판정":"옳음","설명":"대가관계의 하자는 낙약자가 수익자에게 주장할 항변이 아니다(판례). 낙약자가 대항할 수 있는 항변은 낙약자와 요약자 사이의 계약에서 생긴 것이다."}],"개념":[{"종류":"표","제목":"제3자를 위한 계약의 쟁점별 정리","머리":["쟁점","내용","비고"],"행":[["수익자의 현존·특정","계약 체결 당시 현존·특정될 필요 없음","태아, 설립 중의 법인 가능"],["병존적 채무인수","채무자와 인수인의 계약이면 채권자를 수익자로 하는 제3자 계약","채권자가 수익의 의사표시로 직접 청구"],["채무면제","당사자가 제3자에 대하여 가진 채권을 면제하는 계약도 제3자 계약에 준함","유효"],["대가관계의 하자","기본계약 효력에 영향 없음","낙약자는 대가관계 부존재로 이행 거절 불가"],["기본관계의 하자","무효·취소·해제 시 낙약자는 수익자에게 항변 가능","제542조"],["최고권","낙약자가 확답을 최고, 기간 내 확답 없으면 거절로 봄","제540조"]]}],"함정":"2번을 맞는 문장으로 읽기 쉽다. 수익자가 현존해야 한다는 서술은 판례와 맞지 않는다. 1번은 낙약자의 항변(제542조)을 몰라 틀렸다고 고르는 경우가 있다."}},{"i":"S3-1-1-민법-30","r":"S3","g":1,"c":1,"n":70,"s":"민법","q":"부동산 매매에서 환매특약을 한 경우에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["환매특약은 매매계약 체결 후 소유권이전등기를 하기 전까지 별도의 합의로 할 수 있다.","환매기간을 약정하지 않으면 그 기간은 3년이다.","매매등기와 동시에 환매권의 보류를 등기하면 제3자에 대하여 효력이 있다.","환매기간을 7년으로 약정하면 환매특약은 전부 무효이다.","매도인이 환매기간 내에 환매의 의사표시만 하면 환매대금의 제공 없이도 환매권을 잃지 않는다."],"a":[3],"L":"민3-2","o":"변형","x":{"한줄":"부동산 매매에서 매매등기와 동시에 환매권의 보류를 등기하면 제3자에 대해서도 효력이 있다(제592조).","근거":[{"법령":"민법","조문":"제590조제1항","원문":"매도인이 매매계약과 동시에 환매할 권리를 보류한 때에는 그 영수한 대금 및 매수인이 부담한 매매비용을 반환하고 그 목적물을 환매할 수 있다."},{"법령":"민법","조문":"제591조","원문":"①환매기간은 부동산은 5년, 동산은 3년을 넘지 못한다. 약정기간이 이를 넘는 때에는 부동산은 5년, 동산은 3년으로 단축한다. ②환매기간을 정한 때에는 다시 이를 연장하지 못한다. ③환매기간을 정하지 아니한 때에는 그 기간은 부동산은 5년, 동산은 3년으로 한다."},{"법령":"민법","조문":"제592조","원문":"매매의 목적물이 부동산인 경우에 매매등기와 동시에 환매권의 보류를 등기한 때에는 제삼자에 대하여 그 효력이 있다."},{"법령":"민법","조문":"제594조제1항","원문":"매도인은 기간내에 대금과 매매비용을 매수인에게 제공하지 아니하면 환매할 권리를 잃는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"환매권은 매매계약과 동시에 보류해야 한다(제590조제1항). 계약 체결 후에 하는 합의는 환매특약이 아니다."},{"번호":2,"판정":"틀림","설명":"환매기간을 정하지 않으면 부동산은 5년, 동산은 3년이다(제591조제3항). 부동산에 3년은 틀리다."},{"번호":3,"판정":"옳음","설명":"매매등기와 동시에 환매권 보류를 등기해야 제3자에게 대항한다(제592조)."},{"번호":4,"판정":"틀림","설명":"약정기간이 5년을 넘으면 부동산은 5년으로 단축될 뿐이다(제591조제1항). 특약 전체가 무효가 되지는 않는다."},{"번호":5,"판정":"틀림","설명":"환매권자는 기간 내에 대금과 매매비용을 제공해야 하고, 제공하지 않으면 환매권을 잃는다(제594조제1항). 환매의 의사표시만으로는 부족하다."}],"개념":[{"종류":"표","제목":"환매의 요건과 효과","머리":["구분","내용","조문"],"행":[["보류 시기","매매계약과 동시에 환매권 보류","제590조제1항"],["환매대금","영수한 대금 + 매수인이 부담한 매매비용, 특약이 있으면 그에 따름","제590조제1항·제2항"],["과실과 이자","특약이 없으면 상계한 것으로 봄","제590조제3항"],["환매기간","부동산 5년·동산 3년 이내, 초과하면 단축, 정한 후에는 연장 불가, 정하지 않으면 부동산 5년·동산 3년","제591조"],["환매등기","매매등기와 동시에 환매권 보류를 등기하면 제3자에 대하여 효력","제592조"],["환매권의 상실","기간 내에 대금과 매매비용을 제공하지 않으면 환매권을 잃음","제594조제1항"],["비용 상환","매수인·전득자가 목적물에 지출한 비용은 제203조에 따라 상환, 유익비는 법원이 상환기간을 허여할 수 있음","제594조제2항"],["공유지분","공유자 1인이 환매권을 보류하고 지분을 매도한 후 분할·경매가 있으면 받은 부분이나 대금에 대해 환매권 행사","제595조"]]},{"종류":"흐름","제목":"부동산 환매 실행 절차","단계":[{"이름":"매매","설명":"매매계약과 동시에 환매권 보류(제590조)"},{"이름":"등기","설명":"매매등기와 동시에 환매권 보류 등기(제592조)"},{"이름":"제공","설명":"환매기간 안에 대금과 매매비용을 매수인에게 제공(제594조제1항)"},{"이름":"환매 의사표시","설명":"환매의 의사표시로 환매의 효력 발생, 환매에 따른 이전등기"},{"이름":"비용 정산","설명":"매수인·전득자의 지출 비용을 제203조에 따라 상환(제594조제2항)"}]}],"함정":"1번은 환매권을 계약 후에도 보류할 수 있다고 보는 오해다. 2번은 부동산과 동산의 기간을 바꿔 외운 경우에 고른다. 4번은 초과 약정이 무효가 아니라 5년으로 단축되는 점을 놓친다. 5번은 의사표시와 대금 제공을 별개로 보는 오답이다."}},{"i":"S3-1-1-민법-31","r":"S3","g":1,"c":1,"n":71,"s":"민법","q":"매매의 일방예약에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["예약완결권의 행사기간을 약정하지 않은 경우, 예약완결권은 예약이 성립한 날부터 10년 내에 행사하여야 한다.","예약완결권자가 매매완결의 의사표시를 하더라도 상대방의 승낙이 있어야 매매의 효력이 생긴다.","예약완결권의 행사기간이 지났는지 여부는 당사자의 주장이 있어야 법원이 판단할 수 있다.","예약완결권은 일신전속적 권리여서 타인에게 양도할 수 없다.","행사기간을 정하지 않은 경우, 예약자가 상당한 기간을 정하여 확답을 최고하였으나 그 기간 내에 확답을 받지 못하면 매매완결의 의사표시가 있는 것으로 본다."],"a":[1],"L":"민3-2","o":"변형","x":{"한줄":"예약완결권은 형성권이고, 행사기간을 정하지 않았다면 예약이 성립한 때부터 10년 이내에 행사해야 한다.","근거":[{"법령":"민법","조문":"제564조","원문":"①매매의 일방예약은 상대방이 매매를 완결할 의사를 표시하는 때에 매매의 효력이 생긴다. ②전항의 의사표시의 기간을 정하지 아니한 때에는 예약자는 상당한 기간을 정하여 매매완결여부의 확답을 상대방에게 최고할 수 있다. ③예약자가 전항의 기간내에 확답을 받지 못한 때에는 예약은 그 효력을 잃는다."},{"판례":"대법원 판례(예약완결권의 행사기간)","요지":"예약완결권은 형성권으로서 행사기간을 정하지 않았으면 예약이 성립한 때부터 10년 내에 행사해야 하고, 이 기간은 제척기간이라 당사자의 주장이 없어도 법원이 직권으로 조사한다. 재산권이므로 특별한 사정이 없으면 양도할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"행사기간을 약정하지 않으면 예약 성립일부터 10년이 제척기간이다(판례). 5년은 환매기간(제591조)과 혼동한 숫자다."},{"번호":2,"판정":"틀림","설명":"예약완결권자가 완결의 의사표시를 하는 때에 매매의 효력이 생긴다(제564조제1항). 상대방의 승낙은 필요 없다."},{"번호":3,"판정":"틀림","설명":"제척기간 도과 여부는 법원의 직권조사사항이다. 당사자의 주장이 없어도 법원이 고려해야 한다(판례)."},{"번호":4,"판정":"틀림","설명":"예약완결권은 재산권이어서 특별한 사정이 없으면 양도할 수 있다(판례)."},{"번호":5,"판정":"틀림","설명":"확답을 받지 못하면 예약은 효력을 잃는다(제564조제3항). 완결의 의사표시가 있는 것으로 보지 않는다."}],"개념":[{"종류":"표","제목":"매매의 예약과 예약완결권","머리":["구분","내용","근거"],"행":[["일방예약의 효력","상대방(예약완결권자)이 매매완결 의사를 표시하는 때 매매의 효력 발생","제564조제1항"],["예약완결권의 성질","형성권, 재산권이라 특별한 사정이 없으면 양도 가능","판례"],["행사기간을 정한 경우","그 기간 안에 행사(10년을 넘겨 정해도 유효)","판례"],["행사기간을 정하지 않은 경우","예약이 성립한 때부터 10년 이내, 제척기간이라 법원이 직권조사","판례"],["예약자의 최고권","상당한 기간을 정해 확답을 최고할 수 있음","제564조제2항"],["확답이 없을 때","예약은 효력을 잃음","제564조제3항"]]},{"종류":"표","제목":"매매 관련 기간 비교","머리":["제도","기간","비고"],"행":[["예약완결권(기간 약정 없음)","예약 성립일부터 10년","제척기간(판례)"],["환매기간(부동산)","5년을 넘지 못함, 정하지 않으면 5년","제591조"],["환매기간(동산)","3년을 넘지 못함, 정하지 않으면 3년","제591조"],["하자담보 권리행사","매수인이 안 날부터 6월","제582조"],["권리의 일부가 타인에게 속한 경우 권리행사","선의: 안 날부터 1년, 악의: 계약한 날부터 1년","제573조"]]}],"함정":"4번은 일신전속권으로 오해해 고르는 경우가 있다. 예약완결권은 재산권이라 양도할 수 있다. 3번은 제척기간을 소멸시효처럼 당사자 주장이 있어야 하는 것으로 본 오답이다."}},{"i":"S3-1-1-민법-32","r":"S3","g":1,"c":1,"n":72,"s":"민법","q":"甲은 자신의 X건물(5억원 상당)을 乙의 Y토지(3억원 상당)와 교환하는 계약을 체결하면서, 乙이 甲에게 보충금 2억원을 지급하기로 약정하였다. 다음 설명 중 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["교환계약은 낙성·불요식 계약이어서 계약서를 작성하지 않아도 성립한다.","乙이 보충금 지급을 지체하면 甲은 상당한 기간을 정하여 최고한 후 교환계약을 해제할 수 있다.","계약체결 후 이행 전에 X건물이 당사자 쌍방의 책임 없는 사유로 멸실된 경우, 甲은 乙에게 Y토지의 이전을 청구하지 못한다.","X건물에 설정된 저당권이 실행되어 乙이 소유권을 취득할 수 없게 된 경우, 乙은 계약을 해제할 수 있다.","교환계약이 해제된 경우, 甲과 乙의 원상회복의무는 동시이행 관계에 있지 않다."],"a":[5],"L":"민3-2","o":"변형","x":{"한줄":"해제에 따른 원상회복의무는 서로 동시이행 관계에 있다(제549조). 교환계약에도 마찬가지다.","근거":[{"법령":"민법","조문":"제596조","원문":"교환은 당사자 쌍방이 금전 이외의 재산권을 상호이전할 것을 약정함으로써 그 효력이 생긴다."},{"법령":"민법","조문":"제597조","원문":"당사자 일방이 전조의 재산권이전과 금전의 보충지급을 약정한 때에는 그 금전에 대하여는 매매대금에 관한 규정을 준용한다."},{"법령":"민법","조문":"제549조","원문":"제536조의 규정은 전조의 경우에 준용한다."},{"법령":"민법","조문":"제537조","원문":"쌍무계약의 당사자 일방의 채무가 당사자쌍방의 책임없는 사유로 이행할 수 없게 된 때에는 채무자는 상대방의 이행을 청구하지 못한다."},{"법령":"민법","조문":"제576조제1항","원문":"매매의 목적이 된 부동산에 설정된 저당권 또는 전세권의 행사로 인하여 매수인이 그 소유권을 취득할 수 없거나 취득한 소유권을 잃은 때에는 매수인은 계약을 해제할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"교환은 금전 이외의 재산권을 상호이전하기로 약정하면 성립하는 낙성·불요식 계약이다(제596조)."},{"번호":2,"판정":"옳음","설명":"보충금에는 매매대금 규정이 준용되고(제597조), 이행지체를 이유로 한 해제는 제544조에 따른다."},{"번호":3,"판정":"옳음","설명":"쌍방 무책 사유로 X건물을 이전할 채무가 불능이 되면 甲은 반대급부인 Y토지 이전을 청구하지 못한다(제537조)."},{"번호":4,"판정":"옳음","설명":"매매 규정이 교환에 준용되므로(제567조) 저당권 행사로 소유권을 취득할 수 없게 된 乙은 해제할 수 있다(제576조제1항)."},{"번호":5,"판정":"틀림","설명":"해제 후 원상회복의무는 동시이행 관계다(제549조, 제536조). 먼저 이행해야 하는 것은 아니다."}],"개념":[{"종류":"표","제목":"교환계약의 특징과 준용 규정","머리":["구분","내용","조문"],"행":[["성립","금전 이외의 재산권을 상호이전하기로 약정, 낙성·불요식·쌍무·유상","제596조"],["보충금","매매대금 규정 준용(이자·동시이행 등)","제597조"],["준용","매매 규정을 유상계약에 준용(성질상 허용되지 않으면 제외)","제567조"],["양 당사자의 지위","각 당사자가 자기 목적물에 대해서는 매도인, 상대방 목적물에 대해서는 매수인","—"],["계약비용","당사자 쌍방이 균분하여 부담(매매 규정 준용)","제566조"],["해제의 원상회복","동시이행","제549조"]]},{"종류":"표","제목":"매도인의 담보책임 정리(교환에 준용)","머리":["유형","매수인의 권리","행사기간"],"행":[["타인의 권리 매매","해제, 악의가 아니면 손해배상","제한 없음(제570조)"],["권리의 일부가 타인에게 속함","대금감액, 선의면 잔존부분만으로 매수하지 않았을 때 전부 해제와 손해배상","선의 안 날부터 1년, 악의 계약한 날부터 1년(제573조)"],["제한물권 있음","계약 목적 달성 불가 시 해제, 기타 손해배상","안 날부터 1년(제575조제3항)"],["저당권·전세권 행사","소유권을 취득할 수 없거나 잃은 때 해제, 출재 상환, 손해배상","제한 없음(제576조)"],["하자담보책임","해제·손해배상(선의·무과실)","안 날부터 6월(제582조)"]]}],"함정":"5번은 해제의 원상회복을 선이행으로 읽는 오답이다. 3번은 위험부담(제537조)을 몰라 틀린 문장으로 고르기 쉽다. 정답률 31%."}},{"i":"S3-1-1-민법-33","r":"S3","g":1,"c":1,"n":73,"s":"민법","q":"임대차에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["건물 임대차에서 임차인의 차임연체액이 2기의 차임액에 달하면 임대인은 계약을 해지할 수 있다.","여럿이 공동으로 임차한 경우, 임차인은 연대하여 차임지급의무를 부담한다.","임차물의 일부가 임차인의 과실 없이 멸실되어 사용·수익할 수 없는 경우, 임차인은 그 부분의 비율에 의한 차임의 감액을 청구할 수 있다.","연체차임액이 1기의 차임액에 이르면 건물임대인이 해지할 수 있다는 약정은 임차인에게 불리하지만 유효하다.","임차인은 보증금이 있다는 이유로 차임의 지급을 거절할 수 없다."],"a":[4],"L":"민3-3","o":"변형","x":{"한줄":"차임연체로 인한 해지 규정(제640조)에 반하는 약정으로 임차인에게 불리한 것은 효력이 없다(제652조).","근거":[{"법령":"민법","조문":"제640조","원문":"건물 기타 공작물의 임대차에는 임차인의 차임연체액이 2기의 차임액에 달하는 때에는 임대인은 계약을 해지할 수 있다."},{"법령":"민법","조문":"제652조","원문":"제627조, 제628조, 제631조, 제635조, 제638조, 제640조, 제641조, 제643조 내지 제647조의 규정에 위반하는 약정으로 임차인이나 전차인에게 불리한 것은 그 효력이 없다."},{"법령":"민법","조문":"제616조","원문":"수인이 공동하여 물건을 차용한 때에는 연대하여 그 의무를 부담한다."},{"법령":"민법","조문":"제627조제1항","원문":"임차물의 일부가 임차인의 과실없이 멸실 기타 사유로 인하여 사용, 수익할 수 없는 때에는 임차인은 그 부분의 비율에 의한 차임의 감액을 청구할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"건물 기타 공작물의 임대차는 연체액이 2기의 차임액에 달하면 임대인이 해지할 수 있다(제640조)."},{"번호":2,"판정":"옳음","설명":"공동임차인은 제654조가 준용하는 제616조에 따라 연대하여 의무를 부담한다."},{"번호":3,"판정":"옳음","설명":"일부 멸실로 사용·수익할 수 없는 부분의 비율로 차임 감액을 청구할 수 있다(제627조제1항)."},{"번호":4,"판정":"틀림","설명":"1기로 해지할 수 있다는 약정은 임차인에게 불리한 제640조 위반 약정이라 무효다(제652조)."},{"번호":5,"판정":"옳음","설명":"보증금은 임대인이 연체차임에 충당할 수 있는 담보일 뿐, 임차인이 보증금을 이유로 차임 지급을 거절할 권리는 없다(판례)."}],"개념":[{"종류":"표","제목":"임차인에게 불리한 약정이 무효인 규정(제652조)","머리":["조문","내용","불리한 약정의 효력"],"행":[["제627조","일부멸실 시 차임 감액청구, 잔존부분으로 목적 달성 불가 시 해지","무효"],["제628조","경제사정 변동에 따른 차임증감청구","무효"],["제631조","동의 얻은 전대에서 합의종료해도 전차인 권리 존속","무효"],["제635조","기간의 약정이 없는 임대차의 해지통고","무효"],["제638조","해지통고 시 전차인에 대한 통지","무효"],["제640조·제641조","차임연체 2기 해지","무효"],["제643조~제647조","갱신청구·지상물매수청구, 전차인의 임대·매수청구, 부속물매수청구","무효"]]},{"종류":"표","제목":"임차인이 청구할 수 있는 비용·매수","머리":["권리","요건·시기","불리한 특약"],"행":[["필요비 상환(제626조제1항)","보존에 관한 필요비 지출 즉시 청구","유효"],["유익비 상환(제626조제2항)","임대차 종료 시 가액 증가가 현존하는 때","유효"],["부속물매수청구(제646조)","임대인 동의를 얻어 부속시킨 물건이나 임대인에게서 매수한 물건, 임대차 종료 시","무효"],["지상물매수청구(제643조)","건물·수목 소유 목적 토지임대차 기간 만료, 지상시설 현존","무효"]]}],"함정":"4번은 불리한 약정은 무효라는 제652조를 놓쳐 맞는 문장으로 읽는 오답이다. 2기와 1기의 숫자를 바꾼 약정이 함정이다. 5번은 보증금을 차임과 상계할 수 있다고 오해하기 쉽지만 임차인은 거절권이 없다."}},{"i":"S3-1-1-민법-34","r":"S3","g":1,"c":1,"n":74,"s":"민법","q":"임차인 甲이 임대인 乙에게 지상물매수청구권을 행사하는 경우에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲의 매수청구가 유효하려면 乙의 승낙이 있어야 한다.","甲이 매수청구권을 행사하면 乙의 승낙이 없어도 甲과 乙 사이에 지상물에 관한 매매계약이 성립한 것과 같은 효과가 생긴다.","甲이 乙의 동의 없이 지은 건물에 대해서는 매수청구를 할 수 없다.","임대차가 甲의 차임 연체로 해지된 경우에도 甲은 매수청구를 할 수 있다.","甲은 임대차계약의 갱신을 청구하지 않으면 매수청구를 할 수 없다."],"a":[2],"L":"민3-3","o":"변형","x":{"한줄":"지상물매수청구권은 형성권이어서 임차인의 일방적 의사표시로 임대인과 임차인 사이에 매매계약이 성립한 것과 같은 효과가 생긴다.","근거":[{"법령":"민법","조문":"제643조","원문":"건물 기타 공작물의 소유 또는 식목, 채염, 목축을 목적으로 한 토지임대차의 기간이 만료한 경우에 건물, 수목 기타 지상시설이 현존한 때에는 제283조의 규정을 준용한다."},{"법령":"민법","조문":"제283조","원문":"①지상권이 소멸한 경우에 건물 기타 공작물이나 수목이 현존한 때에는 지상권자는 계약의 갱신을 청구할 수 있다. ②지상권설정자가 계약의 갱신을 원하지 아니하는 때에는 지상권자는 상당한 가액으로 전항의 공작물이나 수목의 매수를 청구할 수 있다."},{"판례":"대법원 판례(지상물매수청구권)","요지":"지상물매수청구권은 형성권이라 행사하면 임대인의 승낙 없이 매매계약이 성립한 것과 같은 효과가 생긴다. 임대인의 동의 없이 지은 건물도 대상이 되고, 갱신을 청구하지 않고도 행사할 수 있다. 임차인의 채무불이행(차임 연체 등)으로 해지된 때에는 행사할 수 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"형성권이라 임대인의 승낙은 필요 없다(판례)."},{"번호":2,"판정":"옳음","설명":"청구권자의 일방적 의사표시로 매매계약이 성립한 것과 같은 효과가 생긴다(판례)."},{"번호":3,"판정":"틀림","설명":"임대인의 동의 여부는 요건이 아니다. 동의 없이 지은 건물도 매수청구 대상이 된다(판례). 제외되는 것은 경제적 가치가 없는 건물 등이다."},{"번호":4,"판정":"틀림","설명":"임차인의 채무불이행으로 임대차가 해지된 경우 지상물매수청구권은 생기지 않는다(판례)."},{"번호":5,"판정":"틀림","설명":"갱신청구는 매수청구의 요건이 아니다. 임대인이 갱신을 거절한 경우뿐 아니라 갱신청구 없이도 기간 만료 후 매수를 청구할 수 있다(판례)."}],"개념":[{"종류":"표","제목":"토지 임대차와 지상물 관련 권리","머리":["권리·제도","내용","조문"],"행":[["갱신청구권","기간 만료 시 지상시설이 현존하면 임차인이 갱신 청구","제643조, 제283조제1항"],["지상물매수청구권","임대인이 갱신을 원하지 않으면 상당한 가액으로 매수 청구","제643조, 제283조제2항"],["전차인의 임대청구·매수청구","적법한 전대에서 임대차·전대차 기간이 동시에 만료하고 지상시설이 현존하면 전차인이 임대인에게 전전대차와 같은 조건으로 임대 청구, 원하지 않으면 매수 청구","제644조"],["지상권자의 임차인","지상권자가 토지를 임대한 경우 준용","제645조"],["건물등기 있는 차지권","임대차 등기가 없어도 임차인이 지상건물을 등기하면 제3자에게 효력","제622조"],["법정저당권","토지임대인이 변제기를 경과한 최후 2년의 차임채권으로 임차인 소유 건물을 압류하면 저당권과 동일한 효력","제649조"]]},{"종류":"흐름","제목":"토지 임대차 종료와 지상물 정리","단계":[{"이름":"기간 만료","설명":"건물·수목 소유 목적 토지임대차의 기간이 만료하고 지상시설이 현존"},{"이름":"갱신 청구","설명":"임차인이 갱신 청구 가능(필수 요건은 아님)"},{"이름":"임대인의 거절","설명":"임대인이 갱신을 원하지 않음"},{"이름":"매수 청구","설명":"임차인의 일방적 의사표시로 매매계약 성립 효과(형성권)"},{"이름":"대금 정산","설명":"건물 인도·이전등기와 매매대금 지급이 동시이행"}]}],"함정":"1번은 임대인의 승낙을 요건으로 보는 오해이고, 3번·4번은 요건과 배제 사유를 섞은 오답이다. 4번은 기간 만료가 아닌 채무불이행 해지라 매수청구가 불가능하다. 5번은 갱신청구를 선행 요건으로 오해한 선지다."}},{"i":"S3-1-1-민법-35","r":"S3","g":1,"c":1,"n":75,"s":"민법","q":"주택임대차보호법에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["임차인의 계약갱신요구에 따라 갱신된 임대차에서 임차인은 언제든지 계약해지를 통지할 수 있고, 임대인이 통지를 받은 날부터 3개월이 지나면 해지의 효력이 발생한다.","임대인의 직계비속이 목적 주택에 실제 거주하려는 경우에는 임대인은 임차인의 갱신요구를 거절할 수 없다.","임차인이 3기의 차임액에 해당하는 금액에 이르도록 차임을 연체한 사실이 있는 경우에 한하여 임대인은 갱신요구를 거절할 수 있다.","임차인이 계약갱신요구권을 행사하여 갱신되는 임대차의 존속기간은 1년으로 본다.","임차권등기명령에 따른 임차권등기를 마친 후 임차인이 주택을 인도하면 이미 취득한 대항력과 우선변제권은 상실된다."],"a":[1],"L":"민4-1","o":"변형","x":{"한줄":"갱신요구로 갱신된 임대차의 해지는 제6조의2를 준용하므로 임차인은 언제든 통지할 수 있고 임대인이 받은 날부터 3개월 후에 효력이 생긴다.","근거":[{"법령":"주택임대차보호법","조문":"제6조의3제4항","원문":"제1항에 따라 갱신되는 임대차의 해지에 관하여는 제6조의2를 준용한다."},{"법령":"주택임대차보호법","조문":"제6조의2","원문":"① 제6조제1항에 따라 계약이 갱신된 경우 같은 조 제2항에도 불구하고 임차인은 언제든지 임대인에게 계약해지(契約解止)를 통지할 수 있다. ② 제1항에 따른 해지는 임대인이 그 통지를 받은 날부터 3개월이 지나면 그 효력이 발생한다."},{"법령":"주택임대차보호법","조문":"제6조의3제1항제1호·제8호","원문":"임차인이 2기의 차임액에 해당하는 금액에 이르도록 차임을 연체한 사실이 있는 경우 / 임대인(임대인의 직계존속ㆍ직계비속을 포함한다)이 목적 주택에 실제 거주하려는 경우"},{"법령":"주택임대차보호법","조문":"제6조의3제2항","원문":"임차인은 제1항에 따른 계약갱신요구권을 1회에 한하여 행사할 수 있다. 이 경우 갱신되는 임대차의 존속기간은 2년으로 본다."},{"법령":"주택임대차보호법","조문":"제3조의3제5항","원문":"임차인은 임차권등기명령의 집행에 따른 임차권등기를 마치면 제3조제1항ㆍ제2항 또는 제3항에 따른 대항력과 제3조의2제2항에 따른 우선변제권을 취득한다. 다만, 임차인이 임차권등기 이전에 이미 대항력이나 우선변제권을 취득한 경우에는 그 대항력이나 우선변제권은 그대로 유지되며, 임차권등기 이후에는 제3조제1항ㆍ제2항 또는 제3항의 대항요건을 상실하더라도 이미 취득한 대항력이나 우선변제권을 상실하지 아니한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"묵시적 갱신 때와 같이 임차인은 언제든 해지를 통지할 수 있고, 임대인이 통지를 받은 날부터 3개월이 지나면 효력이 생긴다(제6조의3제4항, 제6조의2)."},{"번호":2,"판정":"틀림","설명":"임대인의 직계존속·직계비속이 실제 거주하려는 경우도 임대인의 거절 사유다(제6조의3제1항제8호)."},{"번호":3,"판정":"틀림","설명":"거절 사유가 되는 연체는 2기의 차임액에 이른 경우다(제6조의3제1항제1호). 3기는 상가건물 임대차보호법의 기준이다(제10조제1항제1호)."},{"번호":4,"판정":"틀림","설명":"갱신요구권은 1회에 한하여 행사할 수 있고 갱신되는 존속기간은 2년이다(제6조의3제2항)."},{"번호":5,"판정":"틀림","설명":"임차권등기 후에는 대항요건을 상실해도 이미 취득한 대항력·우선변제권을 잃지 않는다(제3조의3제5항 단서)."}],"개념":[{"종류":"표","제목":"주택임대차와 상가건물 임대차 비교","머리":["구분","주택임대차보호법","상가건물 임대차보호법"],"행":[["대항요건","주택의 인도 + 주민등록(전입신고), 다음 날부터 효력(제3조제1항)","건물의 인도 + 사업자등록 신청, 다음 날부터 효력(제3조제1항)"],["최단 존속기간","정함 없거나 2년 미만이면 2년, 임차인은 단기 주장 가능(제4조)","정함 없거나 1년 미만이면 1년, 임차인은 단기 주장 가능(제9조)"],["묵시적 갱신의 통지기간","임대인: 기간 끝나기 6개월 전부터 2개월 전까지, 임차인: 2개월 전까지(제6조)","임대인: 6개월 전부터 1개월 전까지(제10조제4항)"],["갱신요구","6개월 전부터 2개월 전까지, 1회, 갱신 존속기간 2년(제6조의3)","6개월 전부터 1개월 전까지, 전체 기간 10년 이내(제10조)"],["갱신요구 거절 연체","2기의 차임액(제6조의3제1항제1호)","3기의 차임액(제10조제1항제1호)"],["갱신 후 해지","임차인은 언제든 통지, 3개월 후 효력(제6조의2)","임차인은 언제든 통고, 3개월 후 효력(제10조제5항)"],["증액 상한","약정한 차임·보증금의 20분의 1(조례로 달리 정할 수 있음), 증액 후 1년 이내 불가(제7조)","청구 당시 차임·보증금의 100분의 5, 증액 후 1년 이내 불가(제11조, 시행령 제4조)"]]},{"종류":"흐름","제목":"주택 계약갱신요구 절차","단계":[{"이름":"요구","설명":"임대차기간이 끝나기 6개월 전부터 2개월 전까지 임차인이 갱신요구"},{"이름":"거절 사유 확인","설명":"2기 연체, 부정한 방법으로 임차, 합의 보상, 무단 전대, 고의·중대한 과실 파손, 멸실, 철거·재건축, 임대인(직계존·비속 포함) 실거주, 의무 현저한 위반 등(제6조의3제1항)"},{"이름":"갱신","설명":"전 임대차와 동일한 조건, 차임·보증금은 제7조 범위(20분의 1 이내)에서 증감"},{"이름":"존속기간","설명":"1회에 한하여, 갱신되는 존속기간은 2년"},{"이름":"해지","설명":"임차인은 언제든 통지, 임대인이 받은 날부터 3개월 후 효력"}]}],"함정":"3번은 상가의 기준인 3기를 주택에 적용한 오답이다. 4번은 묵시적 갱신 때의 2년과 같은 숫자지만 갱신요구권은 1회 행사한다는 점을 함께 알아야 한다. 5번은 임차권등기 후에는 인도해도 대항력·우선변제권이 남는다는 규정을 놓친 선지다."}},{"i":"S3-1-1-민법-36","r":"S3","g":1,"c":1,"n":76,"s":"민법","q":"임차인 乙은 甲소유의 X상가건물에 관하여 월차임 200만원, 기간 2023. 5. 24. ~ 2024. 5. 23.로 하는 임대차계약을 甲과 체결하였고, 기간만료 14일 전인 2024. 5. 9. 갱신거절의 통지를 하여 다음날 甲에게 도달하였다. 임대차계약의 종료일은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["2024. 5. 10.","2024. 5. 23.","2024. 8. 23.","2024. 11. 23.","2025. 5. 23."],"a":[2],"L":"민4-2","o":"기출","x":{"한줄":"임차인이 만료 전에 갱신거절을 통지하여 임대인에게 도달했으므로 묵시적 갱신이 이루어지지 않고 임대차는 약정 기간 만료일인 2024. 5. 23.에 끝난다.","근거":[{"법령":"상가건물 임대차보호법","조문":"제10조제4항","원문":"임대인이 제1항의 기간 이내에 임차인에게 갱신 거절의 통지 또는 조건 변경의 통지를 하지 아니한 경우에는 그 기간이 만료된 때에 전 임대차와 동일한 조건으로 다시 임대차한 것으로 본다. 이 경우에 임대차의 존속기간은 1년으로 본다."},{"법령":"상가건물 임대차보호법","조문":"제10조제5항","원문":"제4항의 경우 임차인은 언제든지 임대인에게 계약해지의 통고를 할 수 있고, 임대인이 통고를 받은 날부터 3개월이 지나면 효력이 발생한다."}],"선지":[{"번호":1,"판정":"-","설명":"갱신거절 통지가 도달한 날은 2024. 5. 10.이지만 통지가 도달해도 임대차가 그날 끝나는 것은 아니다. 약정 기간이 남아 있다."},{"번호":2,"판정":"-","설명":"정답. 임차인이 스스로 갱신하지 않겠다는 통지를 했고 그 통지가 임대인에게 도달했으므로 묵시적 갱신이 되지 않아 약정 기간 만료일에 끝난다."},{"번호":3,"판정":"-","설명":"만료일에 3개월을 더한 날이다. 묵시적으로 갱신된 임대차에서 임차인이 해지를 통고하는 경우의 3개월(제10조제5항)을 잘못 적용한 값이다."},{"번호":4,"판정":"-","설명":"만료일에 6개월을 더한 날로 근거 조문이 없다."},{"번호":5,"판정":"-","설명":"묵시적으로 갱신된 경우의 존속기간 1년(제10조제4항)을 적용한 날이다. 임차인이 갱신거절을 통지했으므로 갱신되지 않는다."}],"개념":[{"종류":"표","제목":"상가건물 임대차보호법 시행령의 금액 기준","머리":["지역","적용 보증금 상한(제2조)","우선변제 임차인 범위(제6조)","보증금 중 일정액 한도(제7조제1항)"],"행":[["서울특별시","9억원","6천500만원","2천200만원"],["과밀억제권역(서울 제외)","6억9천만원 (부산광역시 포함)","5천500만원","1천900만원"],["광역시 등(과밀억제권역·군지역 제외)","5억4천만원 (세종, 파주, 화성, 안산, 용인, 김포, 광주 포함)","3천8백만원 (안산, 용인, 김포, 광주 포함)","1천300만원"],["그 밖의 지역","3억7천만원","3천만원","1천만원"]]},{"종류":"표","제목":"환산보증금과 권리금","머리":["구분","내용","조문"],"행":[["환산보증금","보증금 + 월차임 × 100(1분의 100)","법 제2조제2항, 시행령 제2조제3항"],["보증금액 초과 임대차에도 적용","대항력(제3조), 갱신요구(제10조제1항·제2항·제3항 본문), 권리금 규정(제10조의2~제10조의9) 등","법 제2조제3항"],["권리금 회수기회 보호 기간","임대차기간이 끝나기 6개월 전부터 임대차 종료 시까지","법 제10조의4제1항"],["권리금 손해배상 상한","신규임차인이 지급하기로 한 권리금과 임대차 종료 당시 권리금 중 낮은 금액","법 제10조의4제3항"],["손해배상청구권 시효","임대차가 종료한 날부터 3년","법 제10조의4제4항"],["차임연체 해지","3기의 차임액","법 제10조의8"]]}],"함정":"1번은 통지 도달일을 종료일로 읽은 오답이고, 5번은 묵시적 갱신 효과(1년)를 적용한 오답이다. 임차인이 통지를 하면 임대인이 통지를 하지 않았다는 이유로 갱신되지 않는다. 정답률 38%."}},{"i":"S3-1-1-민법-37","r":"S3","g":1,"c":1,"n":77,"s":"민법","q":"乙은 甲으로부터 1억원을 빌리면서 자신의 Y토지(시가 3억원)에 관하여 대물변제의 예약을 하고, 甲 앞으로 소유권이전청구권 가등기를 마쳐 주었다. 변제기가 지나 甲이 담보권을 실행하려 한다. 「가등기담보 등에 관한 법률」에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲이 소유권을 취득하려면 변제기 후에 청산금의 평가액을 乙에게 통지하고, 그 통지가 도달한 날부터 2개월이 지나야 한다.","甲의 통지에는 통지 당시의 담보목적부동산의 평가액과 민법 제360조에 규정된 채권액을 밝혀야 한다.","甲의 청산금 지급채무와 乙의 본등기 및 인도채무의 이행은 동시이행 관계에 있다.","乙은 청산금채권을 변제받을 때까지 채무액을 甲에게 지급하고 가등기의 말소를 청구할 수 있는데, 이 권리는 변제기가 지난 때부터 10년이 지나도 소멸하지 않는다.","甲이 담보가등기를 마친 Y토지에 대하여 제3자의 신청으로 강제경매가 개시된 경우, 甲은 저당권자로 보아 다른 채권자보다 우선변제를 받을 수 있다."],"a":[4],"L":"민4-3","o":"변형","x":{"한줄":"채무자등의 말소청구권은 변제기가 지난 때부터 10년이 지나거나 선의의 제3자가 소유권을 취득하면 행사할 수 없다.","근거":[{"법령":"가등기담보 등에 관한 법률","조문":"제3조","원문":"① 채권자가 담보계약에 따른 담보권을 실행하여 그 담보목적부동산의 소유권을 취득하기 위하여는 그 채권(債權)의 변제기(辨濟期) 후에 제4조의 청산금(淸算金)의 평가액을 채무자등에게 통지하고, 그 통지가 채무자등에게 도달한 날부터 2개월(이하 \"청산기간\"이라 한다)이 지나야 한다. 이 경우 청산금이 없다고 인정되는 경우에는 그 뜻을 통지하여야 한다. ② 제1항에 따른 통지에는 통지 당시의 담보목적부동산의 평가액과 「민법」 제360조에 규정된 채권액을 밝혀야 한다."},{"법령":"가등기담보 등에 관한 법률","조문":"제4조제2항·제3항","원문":"② 채권자는 담보목적부동산에 관하여 이미 소유권이전등기를 마친 경우에는 청산기간이 지난 후 청산금을 채무자등에게 지급한 때에 담보목적부동산의 소유권을 취득하며, 담보가등기를 마친 경우에는 청산기간이 지나야 그 가등기에 따른 본등기(本登記)를 청구할 수 있다. ③ 청산금의 지급채무와 부동산의 소유권이전등기 및 인도채무(引渡債務)의 이행에 관하여는 동시이행의 항변권(抗辯權)에 관한 「민법」 제536조를 준용한다."},{"법령":"가등기담보 등에 관한 법률","조문":"제11조","원문":"채무자등은 청산금채권을 변제받을 때까지 그 채무액(반환할 때까지의 이자와 손해금을 포함한다)을 채권자에게 지급하고 그 채권담보의 목적으로 마친 소유권이전등기의 말소를 청구할 수 있다. 다만, 그 채무의 변제기가 지난 때부터 10년이 지나거나 선의의 제삼자가 소유권을 취득한 경우에는 그러하지 아니하다."},{"법령":"가등기담보 등에 관한 법률","조문":"제13조","원문":"담보가등기를 마친 부동산에 대하여 강제경매등이 개시된 경우에 담보가등기권리자는 다른 채권자보다 자기채권을 우선변제 받을 권리가 있다. 이 경우 그 순위에 관하여는 그 담보가등기권리를 저당권으로 보고, 그 담보가등기를 마친 때에 그 저당권의 설정등기(設定登記)가 행하여진 것으로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"변제기 후 청산금 평가액을 통지하고, 도달일부터 2개월(청산기간)이 지나야 한다(제3조제1항)."},{"번호":2,"판정":"옳음","설명":"통지에는 통지 당시의 부동산 평가액과 민법 제360조의 채권액을 밝혀야 한다(제3조제2항)."},{"번호":3,"판정":"옳음","설명":"청산금 지급채무와 본등기·인도채무는 동시이행이다(제4조제3항)."},{"번호":4,"판정":"틀림","설명":"변제기가 지난 때부터 10년이 지나면 말소를 청구할 수 없다(제11조 단서). 선의의 제3자가 소유권을 취득한 경우도 같다."},{"번호":5,"판정":"옳음","설명":"담보가등기권리는 저당권으로 보고, 가등기를 마친 때에 설정등기가 된 것으로 본다(제13조)."}],"개념":[{"종류":"흐름","제목":"가등기담보권의 실행(소유권 취득) 절차","단계":[{"이름":"변제기 도래","설명":"채무자가 변제기까지 변제하지 못함. 이후에 실행 통지가 가능"},{"이름":"청산금 평가액 통지","설명":"채무자등에게 통지. 부동산 평가액과 민법 제360조의 채권액을 밝힘. 청산금이 없으면 그 뜻 통지(제3조)"},{"이름":"후순위권리자 등에 통지","설명":"통지가 도달하면 지체 없이 후순위권리자와 등기한 제3자에게 통지의 사실과 내용·도달일 통지(제6조)"},{"이름":"청산기간","설명":"통지가 도달한 날부터 2개월(제3조제1항)"},{"이름":"청산금 지급","설명":"소유권이전등기형은 청산기간 후 청산금을 지급한 때 소유권 취득. 가등기형은 청산기간이 지나야 본등기 청구(제4조제2항)"},{"이름":"동시이행","설명":"청산금 지급과 본등기·인도는 동시이행(제4조제3항)"}]},{"종류":"표","제목":"채무자등 보호와 담보가등기의 지위","머리":["구분","내용","조문"],"행":[["채무자등","채무자, 물상보증인, 담보가등기 후 소유권을 취득한 제3자","제2조제2호"],["불리한 특약","제4조제1항~제3항에 어긋나는 특약으로 채무자등에게 불리한 것은 무효, 청산기간 지난 후의 특약으로 제3자의 권리를 침해하지 않는 것은 유효","제4조제4항"],["통지의 구속력","채권자는 통지한 청산금 금액에 대해 다툴 수 없음","제9조"],["법정지상권","토지와 건물이 동일 소유자에 속하고 그 토지·건물에 소유권 취득 또는 본등기가 된 경우 건물 소유를 위한 지상권이 설정된 것으로 봄","제10조"],["말소청구권","청산금채권 변제 전까지 채무액을 지급하고 말소 청구, 변제기 후 10년 지나거나 선의의 제3자 소유권 취득 시 불가","제11조"],["경매·우선변제","담보가등기권리자는 경매 청구 가능, 강제경매 등에서 저당권으로 보아 우선변제","제12조, 제13조"],["양도담보","부동산을 채권담보 목적으로 양도한 경우 특별한 사정이 없으면 사용·수익권은 설정자(채무자)에게 있음","판례"]]}],"함정":"4번은 말소청구에 기간 제한이 없는 것처럼 쓴 틀린 문장이다. 3번을 청산금 선지급 의무로 오해해 고르기 쉽지만 동시이행이 맞다. 정답률 28%."}},{"i":"S3-1-1-민법-38","r":"S3","g":1,"c":1,"n":78,"s":"민법","q":"집합건물의 소유 및 관리에 관한 법률에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["규약으로 공용부분으로 정한 경우에는 공용부분이라는 취지를 등기하여야 한다.","관리인은 구분소유자일 필요가 없고, 그 임기는 2년의 범위에서 규약으로 정한다.","재건축 결의는 구분소유자의 4분의 3 이상 및 의결권의 4분의 3 이상의 결의에 따른다.","규약의 설정·변경 및 폐지는 관리단집회에서 구분소유자의 4분의 3 이상 및 의결권의 4분의 3 이상의 찬성을 얻어서 한다.","구분소유자의 5분의 1 이상이 회의의 목적 사항을 구체적으로 밝혀 관리단집회의 소집을 청구하면 관리인은 관리단집회를 소집하여야 하며, 이 정수는 규약으로 감경할 수 있다."],"a":[3],"L":"민4-4","o":"변형","x":{"한줄":"재건축 결의는 구분소유자의 5분의 4 이상 및 의결권의 5분의 4 이상의 결의로 한다.","근거":[{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제47조제2항","원문":"제1항의 결의는 구분소유자의 5분의 4 이상 및 의결권의 5분의 4 이상의 결의에 따른다. 다만, 「관광진흥법」 제3조제1항제2호나목에 따른 휴양 콘도미니엄업의 운영을 위한 휴양 콘도미니엄의 재건축 결의는 구분소유자의 3분의 2 이상 및 의결권의 3분의 2 이상의 결의에 따른다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제3조제4항","원문":"제2항과 제3항의 경우에는 공용부분이라는 취지를 등기하여야 한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제24조제2항","원문":"관리인은 구분소유자일 필요가 없으며, 그 임기는 2년의 범위에서 규약으로 정한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제29조제1항","원문":"규약의 설정ㆍ변경 및 폐지는 관리단집회에서 구분소유자의 4분의 3 이상 및 의결권의 4분의 3 이상의 찬성을 얻어서 한다. 이 경우 규약의 설정ㆍ변경 및 폐지가 일부 구분소유자의 권리에 특별한 영향을 미칠 때에는 그 구분소유자의 승낙을 받아야 한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제33조제2항","원문":"구분소유자의 5분의 1 이상이 회의의 목적 사항을 구체적으로 밝혀 관리단집회의 소집을 청구하면 관리인은 관리단집회를 소집하여야 한다. 이 정수(定數)는 규약으로 감경할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"규약상 공용부분은 공용부분이라는 취지를 등기해야 한다(제3조제4항). 구조상 공용부분은 등기 없이 공용부분이 된다."},{"번호":2,"판정":"옳음","설명":"관리인은 구분소유자가 아니어도 되고 임기는 2년의 범위에서 규약으로 정한다(제24조제2항)."},{"번호":3,"판정":"틀림","설명":"재건축 결의의 정족수는 구분소유자 및 의결권 각 5분의 4 이상이다(제47조제2항). 4분의 3은 규약 설정·변경·폐지 등의 정족수다."},{"번호":4,"판정":"옳음","설명":"규약의 설정·변경·폐지는 각 4분의 3 이상의 찬성이다(제29조제1항)."},{"번호":5,"판정":"옳음","설명":"5분의 1 이상이 구체적으로 밝혀 청구하면 관리인은 소집해야 하고, 이 정수는 규약으로 감경할 수 있다(제33조제2항)."}],"개념":[{"종류":"표","제목":"집합건물법 결의 정족수","머리":["안건","정족수","조문"],"행":[["공용부분의 관리(일반)","구분소유자 과반수 및 의결권 과반수(통상결의)","제16조제1항, 제38조제1항"],["공용부분의 변경","구분소유자 3분의 2 이상 및 의결권 3분의 2 이상(개량 목적이고 과다 비용이 아니면 통상결의)","제15조제1항"],["권리변동 있는 공용부분의 변경","구분소유자 5분의 4 이상 및 의결권 5분의 4 이상","제15조의2제1항"],["규약의 설정·변경·폐지","구분소유자 4분의 3 이상 및 의결권 4분의 3 이상","제29조제1항"],["서면·전자적 합의","구분소유자 4분의 3 이상 및 의결권 4분의 3 이상","제41조제1항"],["사용금지 청구·구분소유권 경매·점유자 인도청구","구분소유자 4분의 3 이상 및 의결권 4분의 3 이상","제44조~제46조"],["재건축 결의","구분소유자 5분의 4 이상 및 의결권 5분의 4 이상","제47조제2항"],["건물가격 2분의 1 초과 일부 멸실 시 공용부분 복구 결의","구분소유자 5분의 4 이상 및 의결권 5분의 4 이상","제50조제4항"]]},{"종류":"표","제목":"관리단·관리인·집회","머리":["구분","내용","조문"],"행":[["관리단","구분소유관계가 성립하면 구분소유자 전원으로 당연 설립","제23조제1항"],["관리인 선임","구분소유자 10인 이상이면 선임 의무, 관리단집회 결의로 선임·해임","제24조제1항·제3항"],["대표권 제한","제한할 수 있으나 선의의 제3자에게 대항 불가","제25조제2항"],["정기집회","매년 회계연도 종료 후 3개월 이내 소집","제32조"],["임시집회","구분소유자 5분의 1 이상 청구(규약으로 감경 가능), 관리인 없으면 5분의 1 이상이 소집 가능","제33조"],["소집통지","집회일 1주일 전에 회의 목적사항을 구체적으로 밝혀 통지(규약으로 달리 정할 수 있음)","제34조제1항"],["소집절차 생략","구분소유자 전원이 동의하면 가능","제35조"]]}],"함정":"3번은 4분의 3을 재건축에도 쓴 틀린 선지다. 규약 설정(4분의 3)과 재건축(5분의 4)의 숫자를 바꿔 외우면 4번과 3번의 판단이 뒤바뀐다. 공용부분 변경은 3분의 2다."}},{"i":"S3-1-1-민법-39","r":"S3","g":1,"c":1,"n":79,"s":"민법","q":"甲은 乙에게 부동산 매수를 부탁하면서 매수자금을 대 주었고, 乙은 자기 이름으로 丙 소유의 X토지를 매수하여 乙 명의로 소유권이전등기를 마쳤다. 丙은 명의신탁약정이 있다는 사실을 알지 못하였다. 이에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲과 乙의 명의신탁약정은 무효이다.","乙은 X토지의 소유권을 취득한다.","乙이 X토지를 丁에게 처분하여 丁 명의로 등기가 된 경우, 丁이 명의신탁약정을 알았더라도 丁은 소유권을 취득한다.","甲은 乙에게 매수자금 상당의 부당이득반환을 청구할 수 있다.","甲은 乙에게 명의신탁약정에 기하여 X토지의 소유권이전등기를 청구할 수 있다."],"a":[5],"L":"민4-5","o":"변형","x":{"한줄":"명의신탁약정은 무효이므로 신탁자는 약정을 이유로 수탁자에게 소유권이전등기를 청구할 수 없다.","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조","원문":"① 명의신탁약정은 무효로 한다. ② 명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다. ③ 제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."},{"판례":"대법원 판례(계약명의신탁)","요지":"매도인이 선의인 계약명의신탁에서 수탁자는 소유권을 취득한다. 명의신탁약정은 무효여서 신탁자는 약정에 기한 이전등기를 청구할 수 없고, 수탁자에게 매수자금 상당의 부당이득반환을 청구할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"명의신탁약정은 무효다(제4조제1항)."},{"번호":2,"판정":"옳음","설명":"계약명의신탁에서 매도인이 선의이면 수탁자 명의의 물권변동은 유효다(제4조제2항 단서). 乙이 소유권을 취득한다."},{"번호":3,"판정":"옳음","설명":"명의신탁약정과 등기의 무효는 제3자에게 대항하지 못한다(제4조제3항). 제3자의 선의·악의는 묻지 않는다(판례)."},{"번호":4,"판정":"옳음","설명":"신탁자가 매수자금을 부담했다면 수탁자는 법률상 원인 없이 그 이익을 얻은 것이므로 부당이득반환 의무가 있다(판례)."},{"번호":5,"판정":"틀림","설명":"약정이 무효이므로 약정에 기한 이전등기청구는 허용되지 않는다. 신탁자는 부당이득반환만 청구한다."}],"개념":[{"종류":"표","제목":"명의신탁의 유형별 효력","머리":["유형","약정","등기·물권변동","소유자","신탁자의 구제"],"행":[["양자간 등기명의신탁(신탁자 소유 부동산을 수탁자 앞으로 등기)","무효","무효","신탁자","소유권에 기한 말소(진정명의회복 이전등기) 청구. 수탁자가 제3자에게 처분하면 제3자가 취득(제4조제3항)"],["3자간 등기명의신탁(매도인에게서 수탁자 앞으로 직접 이전등기)","무효","무효","매도인","매도인에 대한 이전등기청구권을 보전하기 위해 매도인을 대위하여 수탁자 명의 말소 청구"],["계약명의신탁(매도인 선의)","무효","유효(제4조제2항 단서)","수탁자","수탁자에게 매수자금 상당 부당이득반환 청구"],["계약명의신탁(매도인 악의)","무효","무효","매도인","매도인에게 소유권이 있음, 신탁자와 수탁자 사이는 약정 무효로 정리"]]},{"종류":"표","제목":"특례와 제재","머리":["구분","내용","조문"],"행":[["종중·배우자·종교단체 특례","조세 포탈, 강제집행 면탈, 법령상 제한 회피 목적이 아니면 제4조~제7조 등을 적용하지 않음","제8조"],["과징금","부동산 가액의 100분의 30의 범위, 명의신탁자와 담보 서면 위반 채권자","제5조"],["이행강제금","과징금 부과일부터 1년이 지난 때 부동산평가액의 100분의 10, 다시 1년이 지난 때 100분의 20","제6조"],["벌칙","명의신탁자 5년 이하 징역 또는 2억원 이하 벌금, 명의수탁자 3년 이하 징역 또는 1억원 이하 벌금","제7조"],["기존 명의신탁","시행일부터 1년의 유예기간 내에 실명등기 필요","제11조"]]}],"함정":"5번이 정답이다. 약정에 기해 등기를 청구하고 싶겠지만 약정이 무효여서 불가능하다. 3번은 제3자가 악의면 보호되지 않을 것 같지만 제4조제3항은 선악을 묻지 않는다. 정답률 26%."}},{"i":"S3-1-1-민법-40","r":"S3","g":1,"c":1,"n":80,"s":"민법","q":"甲은 친구 乙과의 명의신탁약정에 따라 2024. 3. 5. 자신의 X부동산을 乙명의로 소유권이전등기를 해 주었고, 그 후 乙은 丙에게 이를 매도하고 丙명의로 소유권이전등기를 해 주었다. 다음 설명 중 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["甲은 乙을 상대로 불법행위로 인한 손해배상을 청구할 수 있다.","甲과 乙의 명의신탁약정으로 인해 乙과 丙의 매매계약은 무효이다.","甲은 丙을 상대로 X부동산에 관한 소유권이전등기말소를 청구할 수 있다.","甲은 乙을 상대로 명의신탁약정 해지를 원인으로 하는 소유권이전등기를 청구할 수 있다.","만약 乙이 X부동산의 소유권을 丙으로부터 다시 취득한다면, 甲은 乙을 상대로 소유권에 기하여 이전등기를 청구할 수 있다."],"a":[1],"L":"민4-5","o":"기출","x":{"한줄":"수탁자의 처분으로 丙이 소유권을 취득하면 甲은 소유권을 잃게 되고, 이는 乙의 불법행위에 해당해 손해배상을 청구할 수 있다.","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조","원문":"① 명의신탁약정은 무효로 한다. ② 명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다. ③ 제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."},{"판례":"대법원 판례(양자간 명의신탁과 수탁자의 처분)","요지":"수탁자가 신탁부동산을 제3자에게 처분하면 제3자는 소유권을 취득하고(제4조제3항), 신탁자는 소유권을 잃는다. 신탁자는 수탁자에게 불법행위로 인한 손해배상을 청구할 수 있다. 신탁자가 해지를 원인으로 이전등기를 청구하는 것은 허용되지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"수탁자 乙의 처분으로 甲이 소유권을 잃었으므로 乙은 甲에게 불법행위 책임을 진다(판례)."},{"번호":2,"판정":"틀림","설명":"명의신탁약정의 무효는 乙과 丙 사이의 매매에 영향을 주지 않는다. 매매계약은 유효하고 丙은 소유권을 취득한다(제4조제3항)."},{"번호":3,"판정":"틀림","설명":"丙은 제3자로서 소유권을 확정적으로 취득하므로 甲은 말소를 청구할 수 없다(제4조제3항)."},{"번호":4,"판정":"틀림","설명":"명의신탁약정이 무효이므로 약정 해지를 원인으로 한 이전등기 청구는 인정되지 않는다."},{"번호":5,"판정":"틀림","설명":"丙 앞의 등기가 유효하여 甲은 이미 소유권을 잃었다. 乙이 다시 취득해도 甲의 소유권이 되살아나지 않으므로 소유권에 기한 이전등기 청구를 할 수 없다."}],"개념":[{"종류":"흐름","제목":"양자간 명의신탁 후 수탁자의 처분","단계":[{"이름":"명의신탁약정","설명":"甲이 자기 소유 X를 乙 명의로 등기. 약정과 등기 모두 무효(제4조제1항·제2항)"},{"이름":"처분 전","설명":"소유권은 甲에게 있고, 甲은 말소 또는 진정명의회복 이전등기를 청구 가능. 해지를 원인으로 한 이전등기는 불가"},{"이름":"수탁자의 처분","설명":"乙이 丙에게 매도하여 등기. 매매는 유효, 丙은 제3자로서 소유권 취득(제4조제3항)"},{"이름":"신탁자의 지위","설명":"甲은 소유권 상실. 乙에게 불법행위 손해배상 청구 가능, 丙에게 말소 청구 불가"},{"이름":"재취득","설명":"乙이 丙에게서 다시 취득해도 甲은 소유권에 기한 이전등기 청구 불가"}]},{"종류":"표","제목":"양자간 명의신탁에서 신탁자의 청구 가부","머리":["청구","가부","이유"],"행":[["수탁자 상대 소유권에 기한 말소(진정명의회복 이전등기)","가능","약정·등기 무효, 소유권은 신탁자에게 있음"],["수탁자 상대 명의신탁 해지를 원인으로 한 이전등기","불가","약정이 무효이므로 해지권도 없음"],["처분 후 제3자 상대 말소","불가","무효를 제3자에게 대항하지 못함(제4조제3항)"],["처분 후 수탁자 상대 손해배상","가능","수탁자의 처분으로 소유권 상실, 불법행위"],["수탁자의 점유","타주점유","소유권이 없음을 알고 있음"]]}],"함정":"정답률이 10%로 가장 낮다. 2번·3번·4번·5번은 명의신탁 무효 법리를 확장 적용한 오답이다. 매매는 유효하고, 丙은 소유권을 취득하며, 甲의 구제는 손해배상이다."}},{"i":"S3-2-1-중개사법-01","r":"S3","g":2,"c":2,"n":1,"s":"중개사법","q":"공인중개사법령상 용어의 정의에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["중개보조원이란 공인중개사가 아닌 자로서 개업공인중개사에 소속되어 중개대상물에 대한 현장안내 및 일반서무 등 단순한 업무를 보조하는 자를 말한다.","중개업이란 다른 사람의 의뢰에 의하여 보수의 유무와 관계없이 중개를 업으로 행하는 것을 말한다.","소속공인중개사란 개업공인중개사에 소속된 공인중개사로서 중개업무를 수행하거나 보조하는 자를 말하며, 개업공인중개사인 법인의 사원 또는 임원인 공인중개사는 이에 포함되지 않는다.","개업공인중개사란 공인중개사로서 중개사무소의 개설등록을 한 자를 말하며, 법인은 이에 포함되지 않는다.","중개란 중개대상물에 대하여 거래당사자 간의 매매ㆍ교환ㆍ임대차 그 밖의 권리의 득실변경에 관한 행위를 직접 체결하는 것을 말한다."],"a":[1],"L":"중1-1","o":"변형","x":{"한줄":"중개보조원은 공인중개사 자격이 없으면서 개업공인중개사에 소속되어 현장안내와 일반서무 같은 단순업무만 보조하는 자다.","근거":[{"법령":"공인중개사법","조문":"제2조제6호","원문":"\"중개보조원\"이라 함은 공인중개사가 아닌 자로서 개업공인중개사에 소속되어 중개대상물에 대한 현장안내 및 일반서무 등 개업공인중개사의 중개업무와 관련된 단순한 업무를 보조하는 자를 말한다."},{"법령":"공인중개사법","조문":"제2조제3호","원문":"\"중개업\"이라 함은 다른 사람의 의뢰에 의하여 일정한 보수를 받고 중개를 업으로 행하는 것을 말한다."},{"법령":"공인중개사법","조문":"제2조제5호","원문":"\"소속공인중개사\"라 함은 개업공인중개사에 소속된 공인중개사(개업공인중개사인 법인의 사원 또는 임원으로서 공인중개사인 자를 포함한다)로서 중개업무를 수행하거나 개업공인중개사의 중개업무를 보조하는 자를 말한다."},{"법령":"공인중개사법","조문":"제2조제1호","원문":"\"중개\"라 함은 제3조에 따른 중개대상물에 대하여 거래당사자간의 매매ㆍ교환ㆍ임대차 그 밖의 권리의 득실변경에 관한 행위를 알선하는 것을 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제2조제6호의 정의와 같다. 중개보조원은 자격이 없고, 현장안내와 일반서무 같은 단순업무만 맡는다."},{"번호":2,"판정":"틀림","설명":"중개업은 일정한 보수를 받는 것이 요소다. 보수 없이 하는 중개는 중개업이 아니다(제2조제3호)."},{"번호":3,"판정":"틀림","설명":"법인인 개업공인중개사의 사원ㆍ임원으로서 공인중개사인 자도 소속공인중개사에 포함한다(제2조제5호 괄호)."},{"번호":4,"판정":"틀림","설명":"개업공인중개사는 개설등록을 한 자이고(제2조제4호), 법인도 개설등록을 신청할 수 있다. 법인인 개업공인중개사가 따로 있다(제9조제2항)."},{"번호":5,"판정":"틀림","설명":"중개는 거래당사자 사이의 권리 득실변경 행위를 알선하는 것이다. 계약을 직접 체결하는 행위는 중개가 아니다(제2조제1호)."}],"개념":[{"종류":"표","제목":"공인중개사법상 인적 구분 비교","머리":["구분","자격","개설등록","소속","하는 일","근거"],"행":[["공인중개사","자격시험 합격자(자격증 교부)","해당 없음","해당 없음","자격 보유","제2조제2호"],["개업공인중개사","공인중개사 또는 법인","등록관청에 개설등록","해당 없음","중개업 영위","제2조제4호, 제9조"],["소속공인중개사","공인중개사(법인의 사원ㆍ임원인 공인중개사 포함)","해당 없음","개업공인중개사에 소속","중개업무 수행 또는 보조","제2조제5호"],["중개보조원","공인중개사 아님","해당 없음","개업공인중개사에 소속","현장안내ㆍ일반서무 등 단순업무 보조","제2조제6호"]]},{"종류":"표","제목":"중개대상물의 범위","머리":["구분","내용","근거"],"행":[["토지","토지 전부","법 제3조제1호"],["건축물 그 밖의 토지의 정착물","건축물, 정착물","법 제3조제2호"],["입목","「입목에 관한 법률」에 따른 입목","영 제2조제1호"],["공장재단ㆍ광업재단","「공장 및 광업재단 저당법」에 따른 공장재단, 광업재단","영 제2조제2호"]]}],"함정":"정의 문제는 핵심 낱말 하나만 바꿔서 낸다. 중개업은 '일정한 보수', 중개는 '알선', 소속공인중개사는 '법인의 사원ㆍ임원 포함', 개업공인중개사는 '개설등록을 한 자(법인 포함)'가 열쇠다."}},{"i":"S3-2-1-중개사법-02","r":"S3","g":2,"c":2,"n":2,"s":"중개사법","q":"공인중개사법령상 공인중개사자격증에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["시ㆍ도지사는 공인중개사자격 시험합격자의 결정 공고일부터 2개월 이내에 시험합격자에게 공인중개사자격증을 교부해야 한다.","공인중개사자격증의 재교부를 신청하는 자는 재교부신청서를 자격증을 교부한 시ㆍ도지사에게 제출해야 한다.","공인중개사자격증의 재교부를 신청하는 자는 해당 지방자치단체의 조례로 정하는 바에 따라 수수료를 납부해야 한다.","공인중개사는 유ㆍ무상 여부를 불문하고 자기의 공인중개사자격증을 양도해서는 아니된다.","공인중개사가 아닌 자로서 공인중개사 명칭을 사용한 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다."],"a":[1],"L":"중1-2","o":"기출","x":{"한줄":"공인중개사자격증은 합격자 결정 공고일부터 1개월 이내에 교부한다. 2개월이 아니다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제3조제1항","원문":"특별시장ㆍ광역시장ㆍ도지사ㆍ특별자치도지사(이하 \"시ㆍ도지사\"라 한다)는 「공인중개사법」(이하 \"법\"이라 한다) 제5조제1항에 따른 시험합격자의 결정 공고일부터 1개월 이내에 시험합격자에 관한 사항을 별지 제2호서식의 공인중개사자격증교부대장에 기재한 후, 시험 합격자에게 별지 제3호서식의 공인중개사자격증을 교부하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제3조제2항","원문":"법 제5조제3항의 규정에 따라 공인중개사자격증의 재교부를 신청하는 자는 별지 제4호서식의 재교부신청서를 자격증을 교부한 시ㆍ도지사에게 제출하여야 한다."},{"법령":"공인중개사법","조문":"제47조제1항제2호","원문":"제5조제3항에 따라 공인중개사자격증의 재교부를 신청하는 자"},{"법령":"공인중개사법","조문":"제7조제1항","원문":"공인중개사는 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 자기의 공인중개사자격증을 양도 또는 대여하여서는 아니된다."},{"법령":"공인중개사법","조문":"제49조제1항제2호","원문":"제8조의 규정을 위반하여 공인중개사가 아닌 자로서 공인중개사 또는 이와 유사한 명칭을 사용한 자"}],"선지":[{"번호":1,"판정":"틀림","설명":"교부기한은 공고일부터 1개월 이내다(시행규칙 제3조제1항)."},{"번호":2,"판정":"옳음","설명":"재교부는 재교부신청서(별지 제4호서식)를 자격증을 교부한 시ㆍ도지사에게 제출해 신청한다(시행규칙 제3조제2항, 법 제5조제3항)."},{"번호":3,"판정":"옳음","설명":"재교부 신청자는 해당 지방자치단체의 조례로 정한 수수료를 낸다(법 제47조제1항제2호)."},{"번호":4,"판정":"옳음","설명":"유상ㆍ무상을 가리지 않고 자격증을 양도ㆍ대여할 수 없다(법 제7조제1항)."},{"번호":5,"판정":"옳음","설명":"공인중개사가 아니면서 공인중개사 명칭을 쓰면 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제8조, 제49조제1항제2호)."}],"개념":[{"종류":"표","제목":"공인중개사자격증과 자격 관련 규정 모음","머리":["구분","내용","근거"],"행":[["교부","합격자 결정 공고일부터 1개월 이내, 시ㆍ도지사가 교부","시행규칙 제3조제1항"],["재교부","잃어버리거나 못쓰게 된 경우, 교부한 시ㆍ도지사에게 신청","법 제5조제3항, 시행규칙 제3조제2항"],["수수료","지방자치단체 조례로 정함(국토교통부장관이 시행하는 시험의 응시수수료는 장관이 결정ㆍ공고)","법 제47조제1항"],["양도ㆍ대여 금지","양도ㆍ대여, 양수ㆍ대여받아 사용, 이를 알선하는 행위 금지","법 제7조"],["유사명칭 금지","공인중개사 아닌 자의 사용 금지, 1년 이하 징역 또는 1천만원 이하 벌금","법 제8조, 제49조제1항제2호"],["반납","자격취소처분을 받은 날부터 7일 이내 교부한 시ㆍ도지사에게 반납","법 제35조제3항, 시행규칙 제21조"]]},{"종류":"비교","제목":"자격취소와 자격정지","왼쪽":{"이름":"자격취소(법 제35조)","항목":["처분권자: 시ㆍ도지사, 청문 필수","사유: 부정한 방법으로 자격 취득, 자격증 양도ㆍ대여, 자격정지기간 중 중개업무, 형법 일정 조문 위반으로 금고 이상 형 선고(집행유예 포함)","효과: 자격증 반납, 취소 후 3년간 공인중개사가 될 수 없음(법 제6조)","필요적 취소(하여야 한다)"]},"오른쪽":{"이름":"자격정지(법 제36조)","항목":["처분권자: 시ㆍ도지사","대상: 소속공인중개사로서 업무를 수행하는 기간 중의 공인중개사","사유: 이중소속, 인장 미등록ㆍ미사용, 확인ㆍ설명 소홀, 서명날인 누락, 거래계약서 거짓 기재, 금지행위","기간: 6개월의 범위에서 정함, 임의적 처분(할 수 있다)"]}}],"함정":"숫자 하나를 바꾼 선지다. 교부기한 1개월을 2개월로 늘렸을 뿐 나머지 네 선지는 모두 사실이라, 합격 후 절차의 기한을 알면 바로 가려진다."}},{"i":"S3-2-1-중개사법-03","r":"S3","g":2,"c":2,"n":3,"s":"중개사법","q":"공인중개사법령상 공인중개사 정책심의위원회에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["심의위원회가 공인중개사의 시험 등 자격취득에 관한 사항을 심의한 경우 시ㆍ도지사는 이에 따라야 한다.","심의위원회의 위원장은 국토교통부장관이 된다.","심의위원회는 위원장 1명을 포함하여 9명 이상 15명 이내의 위원으로 구성한다.","심의위원회의 회의는 재적위원 3분의 2 이상의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결한다.","심의위원이 해당 안건에 대하여 연구, 용역 또는 감정을 한 경우 심의에는 참여할 수 있으나 의결에서는 제척된다."],"a":[1],"L":"중1-2","o":"변형","x":{"한줄":"심의위원회가 심의한 사항 중 시ㆍ도지사를 구속하는 것은 시험 등 자격취득에 관한 사항뿐이다.","근거":[{"법령":"공인중개사법","조문":"제2조의2제1항","원문":"공인중개사의 업무에 관한 다음 각 호의 사항을 심의하기 위하여 국토교통부에 공인중개사 정책심의위원회를 둘 수 있다."},{"법령":"공인중개사법","조문":"제2조의2제3항","원문":"제1항에 따라 공인중개사 정책심의위원회에서 심의한 사항 중 제1호의 경우에는 특별시장ㆍ광역시장ㆍ도지사ㆍ특별자치도지사(이하 \"시ㆍ도지사\"라 한다)는 이에 따라야 한다."},{"법령":"공인중개사법 시행령","조문":"제1조의2제1항","원문":"위원장 1명을 포함하여 7명 이상 11명 이내의 위원으로 구성한다."},{"법령":"공인중개사법 시행령","조문":"제1조의2제2항","원문":"심의위원회 위원장은 국토교통부 제1차관이 되고,"},{"법령":"공인중개사법 시행령","조문":"제1조의3제1항제3호","원문":"위원이 해당 안건에 대하여 증언, 진술, 자문, 조사, 연구, 용역 또는 감정을 한 경우"},{"법령":"공인중개사법 시행령","조문":"제1조의5제2항","원문":"심의위원회의 회의는 재적위원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"심의사항 중 제1호(자격취득에 관한 사항)에 한해 시ㆍ도지사가 따라야 한다(법 제2조의2제3항)."},{"번호":2,"판정":"틀림","설명":"위원장은 국토교통부 제1차관이다(영 제1조의2제2항)."},{"번호":3,"판정":"틀림","설명":"위원장 1명을 포함해 7명 이상 11명 이내로 구성한다(영 제1조의2제1항)."},{"번호":4,"판정":"틀림","설명":"재적위원 과반수의 출석으로 개의하고 출석위원 과반수의 찬성으로 의결한다(영 제1조의5제2항)."},{"번호":5,"판정":"틀림","설명":"안건에 연구ㆍ용역ㆍ감정을 한 위원은 심의와 의결 모두에서 제척된다(영 제1조의3제1항제3호)."}],"개념":[{"종류":"표","제목":"심의사항과 시ㆍ도지사에 대한 구속력","머리":["심의사항","근거","시ㆍ도지사 구속"],"행":[["공인중개사의 시험 등 공인중개사의 자격취득에 관한 사항","법 제2조의2제1항제1호","있음(따라야 한다)"],["부동산 중개업의 육성에 관한 사항","제2호","없음"],["중개보수 변경에 관한 사항","제3호","없음"],["손해배상책임의 보장 등에 관한 사항","제4호","없음"],["국토교통부장관이 직접 출제ㆍ시행하는 시험","영 제3조","심의위원회 의결을 미리 거쳐야 함"],["부득이한 사정으로 당해 연도 시험을 시행하지 않는 경우","영 제7조제1항","심의위원회 의결을 거쳐야 함"],["선발예정인원 공고 후 고득점자순 합격 결정","영 제10조제2항","심의위원회 의결을 거쳐야 함"]]},{"종류":"표","제목":"심의위원회 구성과 운영","머리":["항목","내용","근거"],"행":[["구성","위원장 1명 포함 7명 이상 11명 이내","영 제1조의2제1항"],["위원장","국토교통부 제1차관","영 제1조의2제2항"],["위원 임기","2년(제2호~제8호 위원), 보궐위원은 전임자의 남은 기간","영 제1조의2제3항"],["위원장 직무대행","위원장이 미리 지명한 위원","영 제1조의4제2항"],["개의ㆍ의결","재적위원 과반수 출석, 출석위원 과반수 찬성","영 제1조의5제2항"],["소집 통보","회의 7일 전까지(긴급 시 전날까지)","영 제1조의5제3항"],["제척","당사자ㆍ배우자ㆍ친족, 증언ㆍ자문ㆍ연구ㆍ용역ㆍ감정을 한 위원, 대리인이었던 위원 등","영 제1조의3제1항"],["기피","당사자가 신청하고 심의위원회가 의결로 결정, 대상 위원은 의결에 참여하지 못함","영 제1조의3제2항"]]}],"함정":"'중개보수 변경 사항을 심의하면 시ㆍ도지사가 따라야 한다'는 식의 선지가 반복해서 나온다. 구속력이 붙는 심의사항은 제1호 하나다."}},{"i":"S3-2-1-중개사법-04","r":"S3","g":2,"c":2,"n":4,"s":"중개사법","q":"공인중개사법령상 중개사무소의 개설등록 및 등록증 교부에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["법인이 중개사무소의 개설등록을 신청하려면 대표자는 공인중개사이어야 하고, 대표자를 제외한 임원 또는 사원의 3분의 1 이상이 공인중개사이어야 한다.","등록관청은 개설등록 신청을 받은 날부터 7일 이내에 등록신청인에게 서면으로 통지하여야 한다.","등록관청은 개설등록을 한 자가 손해배상책임을 보장하기 위한 보증을 설정하기 전에도 중개사무소등록증을 교부할 수 있고, 보증은 업무를 개시하기 전까지 설정하면 된다.","공인중개사인 개업공인중개사의 개설등록신청서에는 여권용 사진과 중개사무소 확보를 증명하는 서류를 첨부하여야 한다.","등록관청은 신청인이 결격사유에 해당하지 않고 등록기준에 적합한 경우에는 개설등록을 해 주어야 한다."],"a":[3],"L":"중1-3","o":"변형","x":{"한줄":"등록증은 등록관청이 보증 설정 여부를 확인한 뒤에 교부한다. 보증 설정이 등록증 교부보다 앞선다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제5조제1항","원문":"등록관청은 중개사무소의 개설등록을 한 자가 영 제24조제2항의 규정에 따른 보증(이하 \"보증\"이라 한다)을 설정하였는지 여부를 확인한 후 법 제11조제1항의 규정에 따라 별지 제6호서식의 중개사무소등록증을 지체 없이 교부하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제4조제2항","원문":"개설등록 신청을 받은 날부터 7일 이내에 등록신청인에게 서면으로 통지하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제13조제1항제2호다목","원문":"대표자는 공인중개사이어야 하며, 대표자를 제외한 임원 또는 사원(합명회사 또는 합자회사의 무한책임사원을 말한다. 이하 이 조에서 같다)의 3분의 1 이상은 공인중개사일 것"},{"법령":"공인중개사법 시행령","조문":"제13조제2항","원문":"법 제9조에 따른 개설등록 신청이 다음 각 호의 어느 하나에 해당하는 경우를 제외하고는 개설등록을 해 주어야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"법인의 대표자는 공인중개사이고, 대표자를 뺀 임원ㆍ사원의 3분의 1 이상이 공인중개사여야 한다(영 제13조제1항제2호다목)."},{"번호":2,"판정":"옳음","설명":"신청을 받은 날부터 7일 이내에 종별(법인ㆍ공인중개사)에 따라 개설등록을 하고 서면으로 통지한다(시행규칙 제4조제2항)."},{"번호":3,"판정":"틀림","설명":"등록증은 등록관청이 보증 설정 여부를 확인한 후 교부한다(시행규칙 제5조제1항). 보증은 업무를 시작하기 전에 설정하고 증명서류를 갖춰 등록관청에 신고한다(영 제24조제2항)."},{"번호":4,"판정":"옳음","설명":"신청서에 여권용 사진, 건축물대장에 기재된 건물에 사무소를 확보했음을 증명하는 서류 등을 첨부한다(시행규칙 제4조제1항제4호ㆍ제5호)."},{"번호":5,"판정":"옳음","설명":"등록관청은 공인중개사ㆍ법인이 아닌 자의 신청, 결격사유 해당, 등록기준 부적합, 다른 법령 위반에 해당하지 않으면 등록해 주어야 한다(영 제13조제2항)."}],"개념":[{"종류":"흐름","제목":"개설등록 신청부터 인장등록까지","단계":[{"이름":"실무교육","설명":"등록신청일 전 1년 이내에 시ㆍ도지사가 실시하는 실무교육을 받는다. 법인은 사원ㆍ임원 전원, 분사무소는 책임자가 받는다(법 제34조제1항)."},{"이름":"신청서 제출","설명":"중개사무소를 두려는 지역의 등록관청에 신청서를 낸다. 실무교육 수료확인증 사본, 여권용 사진, 사무소 확보 증명서류를 첨부한다(시행규칙 제4조제1항)."},{"이름":"자격ㆍ서류 확인","설명":"등록관청이 자격증을 발급한 시ㆍ도지사에 자격 확인을 요청하고, 법인등기사항증명서와 건축물대장은 행정정보 공동이용으로 확인한다(시행규칙 제4조제1항)."},{"이름":"등록ㆍ통지","설명":"결격사유와 등록기준을 심사해 개설등록을 하고, 신청 받은 날부터 7일 이내 서면 통지한다(시행규칙 제4조제2항)."},{"이름":"보증 설정","설명":"업무 시작 전에 보증보험ㆍ공제 가입 또는 공탁을 하고 증명서류를 등록관청에 신고한다(영 제24조제2항)."},{"이름":"등록증 교부","설명":"등록관청이 보증 설정 여부를 확인한 후 지체 없이 교부한다(시행규칙 제5조제1항)."},{"이름":"인장 등록","설명":"업무 개시 전 중개행위에 쓸 인장을 등록한다. 개설등록 신청과 같이 할 수 있다(시행규칙 제9조제1항ㆍ제6항)."}]},{"종류":"표","제목":"공인중개사와 법인의 개설등록 기준 비교","머리":["구분","공인중개사","법인"],"행":[["자본금","요건 없음","「상법」상 회사 또는 협동조합(사회적협동조합 제외)으로서 5천만원 이상"],["영업 범위","제한 없음","법 제14조에 규정된 업무만 영위할 목적으로 설립"],["인적 요건","본인이 공인중개사","대표자는 공인중개사, 대표자 제외 임원ㆍ사원의 3분의 1 이상이 공인중개사"],["실무교육","본인 수료","대표자ㆍ임원ㆍ사원 전원, 분사무소 설치 시 책임자까지 수료"],["사무소","건축물대장에 기재된 건물에 사용권 확보","같음"]]}],"함정":"'보증은 업무 개시 전에만 설정하면 되니 등록증이 먼저 나간다'고 읽기 쉽다. 시행규칙 제5조제1항은 보증 설정 여부를 확인한 후에 등록증을 교부하라고 정한다."}},{"i":"S3-2-1-중개사법-05","r":"S3","g":2,"c":2,"n":5,"s":"중개사법","q":"공인중개사법령상 甲이 중개사무소의 개설등록을 할 수 있는 경우에 해당하는 것은?","b":null,"bs":"없음","img":[],"ch":["甲이 파산선고를 받고 복권되지 아니한 경우","甲이 「형법」상 업무상과실치상죄로 금고 1년의 실형을 선고받고 그 집행이 종료된 날부터 2년이 지난 경우","甲이 이 법을 위반하여 300만원의 벌금형을 선고받고 2년이 지난 경우","甲이 소속공인중개사로 업무를 수행하다가 공인중개사 자격정지처분을 받았고, 그 자격정지기간이 만료된 경우","甲이 거짓으로 중개사무소의 개설등록을 하여 그 등록이 취소된 후 2년이 지난 경우"],"a":[4],"L":"중1-3","o":"변형","x":{"한줄":"공인중개사 자격정지는 정지기간 중에 있는 자만 결격사유다. 기간이 만료된 甲은 개설등록을 할 수 있다.","근거":[{"법령":"공인중개사법","조문":"제10조제1항제7호","원문":"제36조제1항에 따라 공인중개사의 자격이 정지된 자로서 자격정지기간중에 있는 자"},{"법령":"공인중개사법","조문":"제10조제1항제3호","원문":"파산선고를 받고 복권되지 아니한 자"},{"법령":"공인중개사법","조문":"제10조제1항제4호","원문":"금고 이상의 실형의 선고를 받고 그 집행이 종료(집행이 종료된 것으로 보는 경우를 포함한다)되거나 집행이 면제된 날부터 3년이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"제10조제1항제11호","원문":"이 법을 위반하여 300만원 이상의 벌금형의 선고를 받고 3년이 지나지 아니한 자"},{"법령":"공인중개사법","조문":"제10조제1항제8호","원문":"제38조제1항제2호ㆍ제4호부터 제8호까지, 같은 조 제2항제2호부터 제11호까지에 해당하는 사유로 중개사무소의 개설등록이 취소된 후 3년"}],"선지":[{"번호":1,"판정":"틀림","설명":"파산선고를 받고 복권되지 않은 동안은 결격이다(제10조제1항제3호)."},{"번호":2,"판정":"틀림","설명":"금고 이상 실형은 죄명을 가리지 않고 집행 종료 또는 면제일부터 3년이 지나야 결격에서 벗어난다. 2년은 부족하다(제4호)."},{"번호":3,"판정":"틀림","설명":"이 법 위반으로 300만원 이상 벌금형을 선고받으면 선고 후 3년간 결격이다. 2년은 부족하다(제11호)."},{"번호":4,"판정":"옳음","설명":"자격정지기간 중에 있는 자만 결격이다(제7호). 기간이 만료됐으므로 신청할 수 있다."},{"번호":5,"판정":"틀림","설명":"거짓ㆍ부정한 방법의 등록(제38조제1항제2호)으로 취소된 후 3년간 결격이다. 2년은 부족하다(제10조제1항제8호)."}],"개념":[{"종류":"표","제목":"개설등록 결격사유와 결격 기간(법 제10조제1항)","머리":["호","사유","결격 기간"],"행":[["1","미성년자","미성년인 동안"],["2","피성년후견인ㆍ피한정후견인","해당 신분인 동안"],["3","파산선고를 받고 복권되지 아니한 자","복권될 때까지"],["4","금고 이상의 실형 선고","집행 종료ㆍ면제일부터 3년"],["5","금고 이상의 형의 집행유예","유예기간 만료일부터 2년"],["6","공인중개사 자격취소","취소 후 3년"],["7","공인중개사 자격정지","정지기간 중"],["8","개설등록 취소(제38조제1항제2호ㆍ제4호~제8호, 제2항제2호~제11호)","취소 후 3년(제40조제3항에 따른 취소는 폐업기간 공제)"],["9","업무정지처분 후 폐업신고","업무정지기간이 지날 때까지(폐업해도 진행)"],["10","업무정지처분을 받은 법인의 사유 발생 당시 사원ㆍ임원","해당 업무정지기간이 지날 때까지"],["11","이 법 위반 300만원 이상 벌금형","선고 후 3년"],["12","사원ㆍ임원 중 1호~11호 해당자가 있는 법인","해당자가 있는 동안"]]},{"종류":"비교","제목":"개업공인중개사와 소속공인중개사ㆍ중개보조원의 결격 적용","왼쪽":{"이름":"개업공인중개사 등록(법 제10조제1항)","항목":["1호~12호 모두 적용","법인은 사원ㆍ임원 중 1호~11호 해당자가 있으면 결격(12호)","결격사유에 해당하게 되면 등록취소 대상(제38조제1항제3호), 법인의 12호는 사유 발생일부터 2개월 이내 해소하면 제외"]},"오른쪽":{"이름":"소속공인중개사ㆍ중개보조원(법 제10조제2항)","항목":["1호~11호만 적용(12호 제외)","결격자를 고용하면 개업공인중개사는 업무정지 대상이나 사유 발생일부터 2개월 이내 해소하면 제외(제39조제1항제1호)","고용 신고를 받은 등록관청이 결격사유 해당 여부를 확인(시행규칙 제8조제3항)"]}}],"함정":"기간 숫자가 섞인다. 금고 이상 실형은 3년, 집행유예는 유예기간 만료 후 2년, 300만원 이상 벌금은 3년이고, 자격정지는 기간 중에만 결격이라 기간 경과 후에는 해소된다."}},{"i":"S3-2-1-중개사법-06","r":"S3","g":2,"c":2,"n":6,"s":"중개사법","q":"공인중개사법령상 중개사무소의 명칭 및 등록증 등의 게시에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["공인중개사인 개업공인중개사는 공인중개사자격증 원본을 해당 중개사무소 안의 보기 쉬운 곳에 게시하여야 한다.","개업공인중개사는 「부가가치세법 시행령」 에 따른 사업자등록증을 해당 중개사무소 안의 보기 쉬운 곳에 게시하여야 한다.","법인인 개업공인중개사는 그 사무소의 명칭에 '공인중개사사무소' 또는 '부동산중개'라는 문자를 사용하여야 한다.","법인인 개업공인중개사의 분사무소에 옥외광고물을 설치하는 경우 분사무소설치 신고확인서에 기재된 책임자의 성명을 표기하여야 한다.","법 제7638호 부칙 제6조제2항에 따른 개업공인중개사는 그 사무소의 명칭에 '공인중개사사무소' 및 '부동산중개'라는 문자를 사용하여서는 아니된다."],"a":[5],"L":"중1-4","o":"기출","x":{"한줄":"법률 제7638호 부칙 제6조제2항의 개업공인중개사도 사무소 명칭에 '부동산중개'를 사용하여야 한다. 사용이 금지되는 것은 '공인중개사사무소'다.","근거":[{"법령":"공인중개사법","조문":"제18조제1항","원문":"개업공인중개사는 그 사무소의 명칭에 \"공인중개사사무소\" 또는 \"부동산중개\"라는 문자를 사용하여야 한다."},{"법령":"공인중개사법","조문":"제18조제3항","원문":"개업공인중개사가 「옥외광고물 등의 관리와 옥외광고산업 진흥에 관한 법률」 제2조제1호에 따른 옥외광고물을 설치하는 경우 중개사무소등록증에 표기된 개업공인중개사(법인의 경우에는 대표자, 법인 분사무소의 경우에는 제13조제4항의 규정에 따른 신고확인서에 기재된 책임자를 말한다)의 성명을 표기하여야 한다."},{"법령":"공인중개사법","조문":"제17조","원문":"개업공인중개사는 중개사무소등록증ㆍ중개보수표 그 밖에 국토교통부령으로 정하는 사항을 해당 중개사무소 안의 보기 쉬운 곳에 게시하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제10조제3호","원문":"개업공인중개사 및 소속공인중개사의 공인중개사자격증 원본(해당되는 자가 있는 경우로 한정한다)"},{"법령":"공인중개사법 시행규칙","조문":"제10조제5호","원문":"「부가가치세법 시행령」 제11조에 따른 사업자등록증"}],"선지":[{"번호":1,"판정":"옳음","설명":"개업공인중개사와 소속공인중개사의 자격증 원본을 게시한다. 해당자가 있는 경우에 한한다(시행규칙 제10조제3호)."},{"번호":2,"판정":"옳음","설명":"사업자등록증도 게시 대상이다(시행규칙 제10조제5호)."},{"번호":3,"판정":"옳음","설명":"법인도 개업공인중개사이므로 '공인중개사사무소' 또는 '부동산중개' 중 하나를 사용하여야 한다(법 제18조제1항)."},{"번호":4,"판정":"옳음","설명":"분사무소의 옥외광고물에는 분사무소설치신고확인서에 기재된 책임자의 성명을 표기한다(법 제18조제3항)."},{"번호":5,"판정":"틀림","설명":"부칙(법률 제7638호) 제6조의 개업공인중개사는 '공인중개사사무소'를 쓸 수 없고, '부동산중개'를 쓰도록 되어 있다. 두 문자를 모두 쓰지 못하는 것이 아니다(법 제18조제1항 참조)."}],"개념":[{"종류":"표","제목":"중개사무소 안에 게시할 사항(법 제17조, 시행규칙 제10조)","머리":["게시 대상","비고","근거"],"행":[["중개사무소등록증 원본","법인의 분사무소는 분사무소설치신고확인서 원본","시행규칙 제10조제1호"],["중개보수ㆍ실비의 요율 및 한도액표","주택 외 대상은 실제 받으려는 상한요율 명시","시행규칙 제10조제2호, 제20조제7항"],["개업공인중개사ㆍ소속공인중개사의 공인중개사자격증 원본","해당자가 있는 경우로 한정","시행규칙 제10조제3호"],["보증의 설정을 증명할 수 있는 서류","보증보험증서ㆍ공제증서ㆍ공탁증서 사본 등","시행규칙 제10조제4호"],["사업자등록증","「부가가치세법 시행령」 제11조에 따른 것","시행규칙 제10조제5호"]]},{"종류":"표","제목":"사무소 명칭과 옥외광고물 규정 비교","머리":["대상","명칭","옥외광고물 성명 표기","위반 시"],"행":[["공인중개사인 개업공인중개사","'공인중개사사무소' 또는 '부동산중개' 사용","등록증에 표기된 개업공인중개사 성명","과태료 100만원 이하(법 제51조제3항제2호)"],["법인인 개업공인중개사","같음","대표자 성명","같음"],["법인의 분사무소","같음","신고확인서에 기재된 책임자 성명","같음"],["부칙(법률 제7638호) 제6조제2항 개업공인중개사","'공인중개사사무소' 사용 금지, '부동산중개' 사용","등록증에 표기된 성명","같음"],["개업공인중개사가 아닌 자","'공인중개사사무소'ㆍ'부동산중개'ㆍ유사 명칭 사용 금지","해당 없음","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제6호), 등록관청의 간판 철거 명령ㆍ대집행(법 제18조제5항)"]]}],"함정":"법 제18조제1항의 '또는'을 '및'으로 읽으면 안 된다. ⑤처럼 두 문자를 모두 못 쓴다고 쓴 선지가 틀린 이유는 부칙 대상 개업공인중개사도 '부동산중개'는 써야 하기 때문이다."}},{"i":"S3-2-1-중개사법-07","r":"S3","g":2,"c":2,"n":7,"s":"중개사법","q":"공인중개사법령상 개업공인중개사의 휴업ㆍ폐업 등에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["법인인 개업공인중개사가 분사무소를 폐업하려는 경우에는 분사무소설치신고확인서를 첨부하여 분사무소별로 폐업신고를 할 수 있다.","개업공인중개사가 3개월 이하로 휴업하는 경우에도 등록관청에 휴업신고를 하여야 한다.","개업공인중개사는 질병으로 인한 요양을 이유로 하는 경우에만 6개월을 초과하여 휴업할 수 있다.","개업공인중개사가 다른 등록관청의 관할 구역으로 중개사무소를 이전하고 이전신고를 한 경우에는 종전 사무소의 간판을 철거하지 않아도 된다.","개업공인중개사가 3개월을 초과하여 휴업한 중개업을 재개하려는 경우에는 중개사무소등록증을 첨부하여 재개신고서를 제출하여야 한다."],"a":[1],"L":"중1-4","o":"변형","x":{"한줄":"분사무소를 둔 법인은 휴업ㆍ폐업 신고를 분사무소별로 할 수 있고, 폐업이나 3개월 초과 휴업이면 분사무소설치신고확인서를 첨부한다.","근거":[{"법령":"공인중개사법 시행령","조문":"제18조제2항","원문":"법인인 개업공인중개사는 제1항에도 불구하고 법 제13조제3항에 따라 분사무소를 둔 경우에는 제1항에 따른 신고를 분사무소별로 할 수 있다. 이 경우 법 제13조제4항에 따른 신고확인서를 첨부(제1항제1호 및 제2호의 경우만 해당한다)해야 한다."},{"법령":"공인중개사법","조문":"제21조제1항","원문":"개업공인중개사는 3개월을 초과하는 휴업(중개사무소의 개설등록 후 업무를 개시하지 아니하는 경우를 포함한다. 이하 같다), 폐업 또는 휴업한 중개업을 재개하고자 하는 때에는 등록관청에 그 사실을 신고하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제18조제6항","원문":"법 제21조제2항에서 \"대통령령으로 정하는 부득이한 사유\"란 다음 각 호의 어느 하나에 해당하는 사유를 말한다."},{"법령":"공인중개사법","조문":"제21조의2제1항제1호","원문":"제20조제1항에 따라 등록관청에 중개사무소의 이전사실을 신고한 경우"},{"법령":"공인중개사법 시행령","조문":"제18조제1항","원문":"개업공인중개사는 법 제21조제1항에 따라 다음 각 호의 어느 하나에 해당하는 경우에는 국토교통부령으로 정하는 신고서에 중개사무소등록증을 첨부(제1호 및 제2호의 경우만 해당한다)하여 등록관청에 미리 신고"}],"선지":[{"번호":1,"판정":"옳음","설명":"분사무소별 신고가 가능하고, 폐업(휴업 3개월 초과 포함)이면 신고확인서를 첨부한다(영 제18조제2항)."},{"번호":2,"판정":"틀림","설명":"신고 대상은 3개월을 초과하는 휴업이다. 3개월 이하 휴업은 신고하지 않아도 된다(법 제21조제1항)."},{"번호":3,"판정":"틀림","설명":"6개월을 넘기는 휴업이 허용되는 사유는 질병으로 인한 요양, 징집으로 인한 입영, 취학, 임신 또는 출산, 이에 준하는 고시 사유다(영 제18조제6항)."},{"번호":4,"판정":"틀림","설명":"이전신고를 한 경우에도 지체 없이 간판을 철거하여야 한다(법 제21조의2제1항제1호). 폐업신고와 등록취소 처분을 받은 경우도 같다."},{"번호":5,"판정":"틀림","설명":"등록증 첨부 대상은 3개월 초과 휴업과 폐업뿐이다. 재개신고에는 첨부하지 않고, 등록관청이 휴업 때 반납받은 등록증을 즉시 반환한다(영 제18조제1항ㆍ제5항)."}],"개념":[{"종류":"표","제목":"신고 유형별 시기와 등록증 첨부","머리":["신고 유형","신고 시기","등록증 첨부","근거"],"행":[["3개월 초과 휴업(개설등록 후 업무 미개시 포함)","미리 신고","첨부","영 제18조제1항제1호"],["폐업","미리 신고","첨부","영 제18조제1항제2호"],["3개월 초과 휴업한 중개업의 재개","미리 신고","첨부 없음(등록관청이 즉시 반환)","영 제18조제1항제3호ㆍ제5항"],["신고한 휴업기간 변경","미리 신고","첨부 없음","영 제18조제1항제4호"],["법인의 분사무소","분사무소별 신고 가능","분사무소설치신고확인서(휴업ㆍ폐업의 경우)","영 제18조제2항"],["3개월 이하 휴업","신고 불필요","해당 없음","법 제21조제1항"]]},{"종류":"표","제목":"휴업의 제한과 위반 효과","머리":["항목","내용","근거"],"행":[["휴업 기간 상한","6개월을 초과할 수 없음","법 제21조제2항 본문"],["예외 사유","질병 요양, 징집 입영, 취학, 임신ㆍ출산, 이에 준하는 국토교통부장관 고시 사유","법 제21조제2항 단서, 영 제18조제6항"],["상한 위반","등록관청이 개설등록을 취소할 수 있음","법 제38조제2항제5호"],["신고 의무 위반","100만원 이하의 과태료","법 제51조제3항제4호"],["간판 철거","이전신고, 폐업신고, 등록취소 처분 시 지체 없이 철거, 불이행 시 행정대집행","법 제21조의2"],["부가가치세법 신고와 병행","휴업ㆍ폐업 신고서와 함께 제출 가능, 세무서장이 송부하면 제출된 것으로 봄","영 제18조제3항ㆍ제4항"]]}],"함정":"신고는 '3개월 초과' 휴업부터이고, 등록증 첨부는 휴업과 폐업 둘뿐이다. 재개나 기간 변경에도 첨부한다고 확장한 선지에 걸린다."}},{"i":"S3-2-1-중개사법-08","r":"S3","g":2,"c":2,"n":8,"s":"중개사법","q":"공인중개사법령상 개업공인중개사의 휴업의 신고 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["법인인 개업공인중개사가 4개월간 분사무소의 휴업을 하려는 경우 휴업신고서에 그 분사무소설치 신고확인서를 첨부하여 분사무소의 휴업신고를 해야 한다.","개업공인중개사가 신고한 휴업기간을 변경하려는 경우 휴업기간 변경신고서에 중개사무소등록증을 첨부하여 등록관청에 미리 신고해야 한다.","관할 세무서장이 ｢부가가치세법 시행령｣에 따라 공인중개사법령상의 휴업신고서를 함께 받아 이를 해당 등록관청에 송부한 경우에는 휴업신고서가 제출된 것으로 본다.","등록관청은 개업공인중개사가 대통령령으로 정하는 부득이한 사유가 없음에도 계속하여 6개월을 초과하여 휴업한 경우 중개사무소의 개설등록을 취소할 수 있다.","개업공인중개사가 휴업한 중개업을 재개하고자 등록관청에 중개사무소재개신고를 한 경우 해당 등록관청은 반납받은 중개사무소등록증을 즉시 반환해야 한다."],"a":[2],"L":"중1-4","o":"기출","x":{"한줄":"휴업기간 변경신고서에는 중개사무소등록증을 첨부하지 않는다. 등록증 첨부 대상은 3개월 초과 휴업과 폐업 신고뿐이다.","근거":[{"법령":"공인중개사법 시행령","조문":"제18조제1항","원문":"개업공인중개사는 법 제21조제1항에 따라 다음 각 호의 어느 하나에 해당하는 경우에는 국토교통부령으로 정하는 신고서에 중개사무소등록증을 첨부(제1호 및 제2호의 경우만 해당한다)하여 등록관청에 미리 신고(제3호 및 제4호에 해당하여 신고하는 경우에는 전자문서에 의한 신고를 포함한다)해야 한다."},{"법령":"공인중개사법 시행령","조문":"제18조제5항","원문":"제1항 또는 제2항에 따른 중개사무소재개신고를 받은 등록관청은 반납받은 중개사무소등록증 또는 신고확인서를 즉시 반환해야 한다."},{"법령":"공인중개사법 시행령","조문":"제18조제4항","원문":"관할 세무서장이 「부가가치세법 시행령」 제13조제5항에 따라 제1항의 신고서를 받아 해당 등록관청에 송부한 경우에는 제1항의 신고서가 제출된 것으로 본다."},{"법령":"공인중개사법","조문":"제38조제2항제5호","원문":"제21조제2항의 규정을 위반하여 계속하여 6개월을 초과하여 휴업한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"분사무소의 3개월 초과 휴업은 분사무소설치신고확인서를 첨부해 분사무소별로 신고한다(영 제18조제2항)."},{"번호":2,"판정":"틀림","설명":"변경신고는 영 제18조제1항제4호이고, 등록증 첨부는 제1호ㆍ제2호만 해당한다."},{"번호":3,"판정":"옳음","설명":"세무서장이 휴업신고서를 받아 등록관청에 송부하면 제출된 것으로 본다(영 제18조제4항)."},{"번호":4,"판정":"옳음","설명":"부득이한 사유 없이 계속해서 6개월을 초과해 휴업하면 등록관청이 개설등록을 취소할 수 있다(법 제38조제2항제5호). 취소 여부는 재량이다."},{"번호":5,"판정":"옳음","설명":"재개신고를 받은 등록관청은 반납받은 등록증을 즉시 반환한다(영 제18조제5항)."}],"개념":[{"종류":"흐름","제목":"휴업 신고에서 재개까지","단계":[{"이름":"휴업 신고","설명":"3개월을 초과해 휴업하려면 미리 신고한다. 신고서에 중개사무소등록증을 첨부한다. 분사무소는 신고확인서를 첨부한다(영 제18조제1항제1호ㆍ제2항)."},{"이름":"휴업기간 변경","설명":"기간을 바꾸려면 미리 변경신고를 한다. 등록증은 첨부하지 않는다(영 제18조제1항제4호)."},{"이름":"휴업 상한","설명":"휴업은 6개월을 넘길 수 없다. 질병 요양, 징집 입영, 취학, 임신ㆍ출산 등 부득이한 사유는 예외다(법 제21조제2항, 영 제18조제6항)."},{"이름":"재개 신고","설명":"3개월을 초과해 휴업한 중개업을 다시 하려면 미리 신고한다(영 제18조제1항제3호)."},{"이름":"등록증 반환","설명":"재개신고를 받은 등록관청은 반납받은 등록증을 즉시 반환한다(영 제18조제5항)."},{"이름":"위반 시 처분","설명":"부득이한 사유 없이 계속하여 6개월을 초과해 휴업하면 개설등록 취소 사유다(법 제38조제2항제5호). 신고를 하지 않으면 100만원 이하의 과태료다(법 제51조제3항제4호)."}]},{"종류":"표","제목":"부동산중개업 휴업(폐업ㆍ재개ㆍ휴업기간변경)신고서의 신고사항 기재(별지 제13호서식)","머리":["신고 종류","기재하는 내용"],"행":[["휴업","휴업기간(시작일~종료일, 일수)"],["폐업","폐업일"],["재개","재개일"],["휴업기간 변경","원래 휴업기간과 변경 휴업기간"],["공통","신고인, 개업공인중개사 종별(법인ㆍ공인중개사ㆍ부칙 제6조제2항 개업공인중개사), 중개사무소 명칭ㆍ등록번호ㆍ소재지"]]}],"함정":"'휴업은 모두 등록증을 첨부한다'로 일반화하면 변경신고에서 걸린다. 영 제18조제1항은 제1호(3개월 초과 휴업)와 제2호(폐업)에만 첨부를 요구한다."}},{"i":"S3-2-1-중개사법-09","r":"S3","g":2,"c":2,"n":9,"s":"중개사법","q":"공인중개사법령상 중개사무소의 명칭 및 표시ㆍ광고에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["공인중개사인 개업공인중개사는 그 사무소의 명칭에 \"공인중개사사무소\"만 사용하여야 하며 \"부동산중개\"는 사용할 수 없다.","법인인 개업공인중개사가 옥외광고물을 설치하는 경우에는 대표자가 아니라 소속공인중개사의 성명을 표기하여도 된다.","개업공인중개사가 아닌 자는 \"공인중개사사무소\"라는 명칭은 사용할 수 없으나 \"부동산중개\"나 이와 유사한 명칭은 사용할 수 있다.","등록관청은 개설등록을 하지 않은 공인중개사가 사무소에 \"공인중개사사무소\"라는 명칭을 사용한 경우 그 명칭이 사용된 간판 등의 철거를 명할 수 있다.","개업공인중개사가 의뢰받은 중개대상물에 대하여 표시ㆍ광고를 하려는 경우에는 중개사무소의 명칭ㆍ소재지ㆍ연락처ㆍ등록번호와 개업공인중개사의 성명뿐 아니라 중개보조원의 성명도 명시하여야 한다."],"a":[4],"L":"중1-4","o":"변형","x":{"한줄":"명칭 규정을 위반한 간판은 등록관청이 철거를 명할 수 있고, 따르지 않으면 행정대집행을 할 수 있다.","근거":[{"법령":"공인중개사법","조문":"제18조제5항","원문":"등록관청은 제1항부터 제3항까지의 규정을 위반한 사무소의 간판 등에 대하여 철거를 명할 수 있다. 이 경우 그 명령을 받은 자가 철거를 이행하지 아니하는 경우에는 「행정대집행법」에 의하여 대집행을 할 수 있다."},{"법령":"공인중개사법","조문":"제18조제2항","원문":"개업공인중개사가 아닌 자는 \"공인중개사사무소\", \"부동산중개\" 또는 이와 유사한 명칭을 사용하여서는 아니된다."},{"법령":"공인중개사법","조문":"제18조의2제1항","원문":"중개보조원에 관한 사항은 명시해서는 아니 된다."},{"법령":"공인중개사법 시행령","조문":"제17조의2제1항","원문":"법 제18조의2제1항에서 \"대통령령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다.\n1. 중개사무소의 명칭, 소재지, 연락처 및 등록번호\n2. 개업공인중개사의 성명(법인인 경우에는 대표자의 성명)"}],"선지":[{"번호":1,"판정":"틀림","설명":"두 문자 중 어느 하나를 사용하면 된다(법 제18조제1항 '또는')."},{"번호":2,"판정":"틀림","설명":"법인이 설치하는 옥외광고물에는 등록증에 표기된 대표자의 성명을 표기한다(법 제18조제3항)."},{"번호":3,"판정":"틀림","설명":"개업공인중개사가 아닌 자는 '공인중개사사무소', '부동산중개', 이와 유사한 명칭을 모두 사용할 수 없다(법 제18조제2항)."},{"번호":4,"판정":"옳음","설명":"개설등록을 하지 않은 공인중개사는 개업공인중개사가 아닌 자라 제2항 위반이 된다. 철거 명령권자는 등록관청이다(법 제18조제5항)."},{"번호":5,"판정":"틀림","설명":"표시ㆍ광고에는 중개보조원에 관한 사항을 명시해서는 안 된다(법 제18조의2제1항). 명시할 사항은 사무소 명칭ㆍ소재지ㆍ연락처ㆍ등록번호와 개업공인중개사 성명이다(영 제17조의2제1항)."}],"개념":[{"종류":"비교","제목":"개업공인중개사와 개업공인중개사가 아닌 자","왼쪽":{"이름":"개업공인중개사","항목":["명칭: '공인중개사사무소' 또는 '부동산중개' 사용 의무(법 제18조제1항)","옥외광고물: 등록증에 표기된 개업공인중개사의 성명 표기(법인은 대표자, 분사무소는 신고확인서의 책임자)","표시ㆍ광고: 명시사항을 밝히고 중개보조원은 명시하지 않음","의무 위반: 100만원 이하 과태료(법 제51조제3항제2호ㆍ제2호의2)"]},"오른쪽":{"이름":"개업공인중개사가 아닌 자(미등록 공인중개사 포함)","항목":["명칭: '공인중개사사무소'ㆍ'부동산중개'ㆍ유사 명칭 사용 금지(법 제18조제2항)","표시ㆍ광고: 중개대상물에 대한 표시ㆍ광고 금지(법 제18조의2제3항)","간판: 등록관청이 철거 명령, 불이행 시 행정대집행(법 제18조제5항)","벌칙: 1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제6호ㆍ제6호의2)"]}},{"종류":"표","제목":"중개대상물 표시ㆍ광고 규정","머리":["구분","내용","근거"],"행":[["모든 표시ㆍ광고에 명시","중개사무소 명칭ㆍ소재지ㆍ연락처ㆍ등록번호, 개업공인중개사 성명(법인은 대표자)","영 제17조의2제1항"],["명시 금지","중개보조원에 관한 사항","법 제18조의2제1항"],["인터넷 광고 추가 명시","소재지, 면적, 가격, 중개대상물 종류, 거래 형태, 건축물은 총 층수ㆍ사용승인일ㆍ방향ㆍ방과 욕실 수ㆍ입주가능일ㆍ주차대수ㆍ관리비","법 제18조의2제2항, 영 제17조의2제2항"],["부당 표시ㆍ광고 금지","존재하지 않는 물건, 가격 등 거짓ㆍ과장, 존재하나 중개 대상이 될 수 없거나 중개할 의사가 없는 물건, 중요사실 은폐ㆍ축소","법 제18조의2제4항, 영 제17조의2제4항"],["위반 제재","명시의무 위반 100만원 이하 과태료, 부당 표시ㆍ광고 500만원 이하 과태료","법 제51조제3항제2호의2, 제2항제1호"],["인터넷 모니터링","국토교통부장관이 모니터링, 정보통신서비스 제공자에 자료 제출 요구 가능","법 제18조의3"]]}],"함정":"철거 명령권자를 국토교통부장관으로 바꿔 쓰거나, 미등록 공인중개사가 '부동산중개'는 쓸 수 있다고 쓰는 선지가 자주 나온다. 명칭 사용 금지는 두 명칭과 유사 명칭 전부다."}},{"i":"S3-2-1-중개사법-10","r":"S3","g":2,"c":2,"n":10,"s":"중개사법","q":"공인중개사법령상 인장등록에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["법인인 개업공인중개사의 인장등록은 「상업등기규칙」에 따른 인감증명서의 제출로 갈음한다.","소속공인중개사는 중개행위에 사용할 인장을 업무를 개시하기 전에 등록관청에 등록하여야 한다.","공인중개사인 개업공인중개사가 등록할 인장은 주민등록표에 기재된 성명이 나타난 인장으로서 그 크기가 가로ㆍ세로 각각 10밀리미터 이상 50밀리미터 이내이어야 한다.","법인인 개업공인중개사의 분사무소에서 사용할 인장은 법인의 대표자가 보증하는 인장을 등록할 수 있다.","개업공인중개사가 등록하지 아니한 인장을 중개행위에 사용한 경우 등록관청은 6개월의 범위 안에서 업무의 정지를 명할 수 있다."],"a":[3],"L":"중1-4","o":"변형","x":{"한줄":"공인중개사인 개업공인중개사의 인장 크기는 가로ㆍ세로 각각 7밀리미터 이상 30밀리미터 이내다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제9조제3항","원문":"가로ㆍ세로 각각 7밀리미터 이상 30밀리미터 이내인 인장이어야 하며, 법인인 개업공인중개사의 경우에는 「상업등기규칙」에 따라 신고한 법인의 인장이어야 한다. 다만, 분사무소에서 사용할 인장의 경우에는 「상업등기규칙」 제35조제3항에 따라 법인의 대표자가 보증하는 인장을 등록할 수 있다."},{"법령":"공인중개사법 시행규칙","조문":"제9조제4항","원문":"법인인 개업공인중개사의 제1항 및 제2항에 따른 인장 등록은 「상업등기규칙」에 따른 인감증명서의 제출로 갈음한다."},{"법령":"공인중개사법 시행규칙","조문":"제9조제1항","원문":"개업공인중개사 및 소속공인중개사는 법 제16조제1항의 규정에 따라 업무를 개시하기 전에 중개행위에 사용할 인장을 등록관청에 등록(전자문서에 의한 등록을 포함한다)하여야 한다."},{"법령":"공인중개사법","조문":"제39조제1항제2호","원문":"제16조의 규정을 위반하여 인장등록을 하지 아니하거나 등록하지 아니한 인장을 사용한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"법인의 인장등록은 인감증명서 제출로 갈음한다(시행규칙 제9조제4항)."},{"번호":2,"판정":"옳음","설명":"개업공인중개사와 소속공인중개사 모두 업무 개시 전에 등록한다(시행규칙 제9조제1항)."},{"번호":3,"판정":"틀림","설명":"크기는 가로ㆍ세로 각각 7밀리미터 이상 30밀리미터 이내다(시행규칙 제9조제3항)."},{"번호":4,"판정":"옳음","설명":"분사무소 인장은 「상업등기규칙」 제35조제3항에 따라 대표자가 보증하는 인장을 등록할 수 있다(시행규칙 제9조제3항 단서)."},{"번호":5,"판정":"옳음","설명":"등록하지 않은 인장을 사용한 개업공인중개사는 6개월 범위의 업무정지 대상이다(법 제39조제1항제2호). 소속공인중개사는 시ㆍ도지사의 자격정지 대상이다(법 제36조제1항제2호)."}],"개념":[{"종류":"표","제목":"인장등록 요건 모음","머리":["항목","내용","근거"],"행":[["등록 대상","개업공인중개사, 소속공인중개사","법 제16조제1항"],["등록 시기","업무개시 전","시행규칙 제9조제1항"],["변경 시","변경일부터 7일 이내 변경 인장 등록","시행규칙 제9조제2항"],["인장 규격(개인)","가족관계등록부 또는 주민등록표의 성명이 나타난 인장, 가로ㆍ세로 각 7mm 이상 30mm 이내","시행규칙 제9조제3항"],["인장 규격(법인)","「상업등기규칙」에 따라 신고한 법인의 인장, 분사무소는 대표자 보증 인장 가능","시행규칙 제9조제3항"],["법인의 등록 방법","인감증명서 제출로 갈음","시행규칙 제9조제4항"],["함께 할 수 있는 절차","개설등록 신청, 소속공인중개사ㆍ중개보조원 고용 신고","시행규칙 제9조제6항"],["사용 의무","중개행위를 하는 경우 등록한 인장을 사용","법 제16조제2항"]]},{"종류":"비교","제목":"같은 위반에 대한 처분 대상 비교","왼쪽":{"이름":"개업공인중개사","항목":["위반: 인장등록을 하지 않거나 등록하지 않은 인장을 사용","처분: 업무정지(6개월의 범위)","처분권자: 등록관청","근거: 법 제39조제1항제2호"]},"오른쪽":{"이름":"소속공인중개사","항목":["위반: 같은 행위(소속공인중개사로서 업무를 수행하는 기간 중)","처분: 자격정지(6개월의 범위)","처분권자: 시ㆍ도지사, 등록관청은 알게 된 때 지체 없이 시ㆍ도지사에게 통보","근거: 법 제36조제1항제2호ㆍ제2항"]}}],"함정":"수치가 열쇠다. 변경 시 등록은 7일 이내, 인장 크기는 7mm 이상 30mm 이내, 정지는 6개월 범위다. 소속공인중개사에게는 업무정지가 아니라 자격정지가 나간다."}},{"i":"S3-2-1-중개사법-11","r":"S3","g":2,"c":2,"n":11,"s":"중개사법","q":"공인중개사법령상 법인인 개업공인중개사가 중개업과 함께 할 수 있는 업무로 옳은 것은? (다른 법률에 규정된 경우는 제외함)","b":null,"bs":"없음","img":[],"ch":["주택의 매매업","토지에 대한 분양대행","건축물의 신축 공사 시공","일반 소비자를 상대로 한 이삿짐 운송업","상업용 건축물의 분양대행"],"a":[5],"L":"중1-4","o":"변형","x":{"한줄":"법인인 개업공인중개사는 중개업과 법 제14조제1항 각 호의 업무 외에는 겸업할 수 없다. 상업용 건축물 및 주택의 분양대행이 제4호에 있다.","근거":[{"법령":"공인중개사법","조문":"제14조제1항","원문":"법인인 개업공인중개사는 다른 법률에 규정된 경우를 제외하고는 중개업 및 다음 각 호에 규정된 업무와 제2항에 규정된 업무 외에 다른 업무를 함께 할 수 없다."},{"법령":"공인중개사법","조문":"제14조제1항제4호","원문":"상업용 건축물 및 주택의 분양대행"},{"법령":"공인중개사법 시행령","조문":"제17조제2항","원문":"법 제14조제1항제5호에서 \"대통령령이 정하는 업무\"라 함은 중개의뢰인의 의뢰에 따른 도배ㆍ이사업체의 소개 등 주거이전에 부수되는 용역의 알선을 말한다."},{"법령":"공인중개사법","조문":"제33조제1항제1호","원문":"제3조에 따른 중개대상물의 매매를 업으로 하는 행위"}],"선지":[{"번호":1,"판정":"틀림","설명":"중개대상물의 매매를 업으로 하는 행위는 법인이든 개인이든 금지행위다(법 제33조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"분양대행은 상업용 건축물 및 주택만 가능하다. 토지는 포함되지 않는다(법 제14조제1항제4호)."},{"번호":3,"판정":"틀림","설명":"열거된 업무가 아니다. 겸업 제한을 위반하면 등록취소 사유가 된다(법 제38조제2항제4호)."},{"번호":4,"판정":"틀림","설명":"허용되는 것은 도배ㆍ이사업체의 '소개' 등 주거이전에 부수되는 용역의 알선이다(영 제17조제2항). 운송업을 직접 영위하는 것은 열거 밖이다."},{"번호":5,"판정":"옳음","설명":"상업용 건축물 및 주택의 분양대행은 법 제14조제1항제4호의 겸업 가능 업무다."}],"개념":[{"종류":"표","제목":"법인인 개업공인중개사의 겸업 가능 업무","머리":["업무","내용","근거"],"행":[["부동산 관리대행","상업용 건축물 및 주택의 임대관리 등","법 제14조제1항제1호"],["상담","부동산의 이용ㆍ개발 및 거래에 관한 상담","제2호"],["경영정보 제공","개업공인중개사를 대상으로 한 중개업의 경영기법 및 경영정보의 제공","제3호"],["분양대행","상업용 건축물 및 주택(토지 제외)","제4호"],["부수 업무","중개의뢰인의 의뢰에 따른 도배ㆍ이사업체의 소개 등 주거이전에 부수되는 용역의 알선","제5호, 영 제17조제2항"],["경매ㆍ공매 관련","경매ㆍ공매 대상 부동산의 권리분석, 취득 알선, 매수신청ㆍ입찰신청 대리","법 제14조제2항"]]},{"종류":"비교","제목":"법인과 개인 개업공인중개사의 겸업 규제","왼쪽":{"이름":"법인인 개업공인중개사","항목":["법 제14조제1항 각 호 업무 외 겸업 금지","위반 시 등록취소 가능(법 제38조제2항제4호)","경매 매수신청 대리는 가능"]},"오른쪽":{"이름":"법인이 아닌 개업공인중개사","항목":["법 제14조제1항의 겸업 제한 없음","중개대상물 매매업은 금지(법 제33조제1항제1호)","경매 매수신청 대리는 가능"]}}],"함정":"분양대행은 '상업용 건축물 및 주택'으로 한정된다. 토지 분양대행을 넣거나, 이사업체 '소개'를 이사 운송업 직접 영위로 바꿔 놓은 선지가 오답이다."}},{"i":"S3-2-1-중개사법-12","r":"S3","g":2,"c":2,"n":12,"s":"중개사법","q":"공인중개사법령상 개업공인중개사의 고용인에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["중개보조원의 업무상 행위는 그를 고용한 개업공인중개사의 행위로 보지 아니한다.","소속공인중개사를 고용하려는 개업공인중개사는 고용전에 미리 등록관청에 신고해야 한다.","개업공인중개사는 중개보조원과의 고용관계가 종료된 때에는 고용관계가 종료된 날부터 10일 이내에 등록관청에 신고하여야 한다.","개업공인중개사가 소속공인중개사의 고용 신고를 할 때에는 해당 소속공인중개사의 실무교육 수료확인증을 제출하여야 한다.","개업공인중개사는 외국인을 중개보조원으로 고용할 수 없다."],"a":[3],"L":"중1-5","o":"기출","x":{"한줄":"소속공인중개사나 중개보조원과의 고용관계가 종료되면 종료일부터 10일 이내에 등록관청에 신고한다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제8조제4항","원문":"개업공인중개사는 소속공인중개사 또는 중개보조원과의 고용관계가 종료된 때에는 법 제15조제1항에 따라 고용관계가 종료된 날부터 10일 이내에 등록관청에 신고하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제8조제1항","원문":"개업공인중개사는 소속공인중개사 또는 중개보조원을 고용한 경우에는 법 제34조제2항 또는 제3항에 따른 교육을 받도록 한 후 법 제15조제1항에 따라 업무개시 전까지 등록관청에 신고(전자문서에 의한 신고를 포함한다)하여야 한다."},{"법령":"공인중개사법","조문":"제15조제2항","원문":"소속공인중개사 또는 중개보조원의 업무상 행위는 그를 고용한 개업공인중개사의 행위로 본다."},{"법령":"공인중개사법 시행규칙","조문":"제8조제5항","원문":"이 경우 소속공인중개사 또는 중개보조원으로 외국인을 고용하는 경우에는 제4조제1항제6호가목의 서류를 첨부하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"고용인의 업무상 행위는 그를 고용한 개업공인중개사의 행위로 본다(법 제15조제2항)."},{"번호":2,"판정":"틀림","설명":"고용 신고는 업무개시 전까지 하면 된다. 고용 전에 미리 하라는 규정은 없다(시행규칙 제8조제1항)."},{"번호":3,"판정":"옳음","설명":"고용관계 종료 신고는 종료된 날부터 10일 이내다(시행규칙 제8조제4항)."},{"번호":4,"판정":"틀림","설명":"교육을 받도록 한 후 신고하며, 등록관청이 교육 수료 여부를 확인한다(시행규칙 제8조제1항ㆍ제3항). 수료확인증 제출 규정은 없다."},{"번호":5,"판정":"틀림","설명":"외국인도 고용할 수 있다. 이때 결격사유에 해당하지 않음을 증명하는 외국 서류를 첨부한다(시행규칙 제8조제5항)."}],"개념":[{"종류":"표","제목":"소속공인중개사와 중개보조원 비교","머리":["항목","소속공인중개사","중개보조원"],"행":[["고용 신고","업무개시 전까지 등록관청에 신고(시행규칙 제8조제1항)","같음"],["고용종료 신고","종료일부터 10일 이내(시행규칙 제8조제4항)","같음"],["고용 전 교육","고용 신고일 전 1년 이내 실무교육 45시간(법 제34조제2항, 영 제28조제1항)","고용 신고일 전 1년 이내 직무교육 3시간 이상 4시간 이하(법 제34조제3항, 영 제28조제2항)"],["연수교육","실무교육 후 2년마다 12시간 이상 16시간 이하(법 제34조제4항, 영 제28조제3항)","대상 아님"],["결격사유","법 제10조제1항제1호~제11호 해당자는 될 수 없음(법 제10조제2항)","같음"],["이중소속","다른 개업공인중개사의 소속이 될 수 없음(법 제12조제2항)","같음"],["인원 제한","없음","개업공인중개사와 소속공인중개사를 합한 수의 5배 초과 불가(법 제15조제3항)"],["인장등록","필요(법 제16조)","없음"],["고지의무","없음","현장안내 등 보조 시 중개의뢰인에게 중개보조원이라는 사실을 미리 고지(법 제18조의4)"]]},{"종류":"흐름","제목":"고용 신고 절차와 위반 효과","단계":[{"이름":"사전 확인","설명":"결격사유(법 제10조제2항)와 다른 사무소 소속 여부(법 제12조제2항)를 확인한다."},{"이름":"교육","설명":"소속공인중개사는 실무교육, 중개보조원은 직무교육을 받도록 한다(시행규칙 제8조제1항)."},{"이름":"신고","설명":"업무개시 전까지 별지 제11호서식으로 신고한다. 전자문서 신고가 가능하고, 외국인은 서류를 첨부한다(시행규칙 제8조제1항ㆍ제5항)."},{"이름":"등록관청 확인","설명":"시ㆍ도지사에게 자격 확인을 요청하고, 결격사유와 교육 수료 여부를 확인한다(시행규칙 제8조제2항ㆍ제3항)."},{"이름":"종료 신고","설명":"고용관계 종료일부터 10일 이내에 신고한다(시행규칙 제8조제4항)."},{"이름":"위반 효과","설명":"결격자를 고용하면 업무정지(사유 발생일부터 2개월 내 해소 시 제외, 법 제39조제1항제1호). 중개보조원 수 초과 고용은 등록취소(법 제38조제1항제5호의2)와 1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제5호의2) 대상이다."}]}],"함정":"신고 시기를 '고용 전에 미리'로 쓴 ②와 '수료확인증 제출'을 요구하는 ④가 그럴듯하다. 고용 신고는 업무개시 전까지, 종료 신고는 10일 이내다."}},{"i":"S3-2-1-중개사법-13","r":"S3","g":2,"c":2,"n":13,"s":"중개사법","q":"공인중개사법령상 거래정보사업자지정대장 서식에 기재되는 사항이 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["지정 번호 및 지정 연월일","상호 또는 명칭 및 대표자의 성명","주된 컴퓨터설비의 내역","전문자격자의 보유에 관한 사항","｢전기통신사업법｣에 따른 부가통신사업자번호"],"a":[5],"L":"중1-6","o":"기출","x":{"한줄":"거래정보사업자지정대장에는 지정 번호ㆍ연월일, 상호ㆍ대표자, 사무소 소재지, 주된 컴퓨터설비의 내역, 전문자격자 보유 사항을 적는다. 부가통신사업자번호는 없다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제15조제3항","원문":"지정 번호 및 지정 연월일\n2. 상호 또는 명칭 및 대표자의 성명\n3. 사무소의 소재지\n4. 주된 컴퓨터설비의 내역\n5. 전문자격자의 보유에 관한 사항"},{"법령":"공인중개사법","조문":"제24조제2항","원문":"제1항에 따라 지정을 받을 수 있는 자는 「전기통신사업법」의 규정에 의한 부가통신사업자로서 국토교통부령으로 정하는 요건을 갖춘 자로 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지정대장 기재사항이다(시행규칙 제15조제3항제1호)."},{"번호":2,"판정":"옳음","설명":"지정대장 기재사항이다(제2호)."},{"번호":3,"판정":"옳음","설명":"지정대장 기재사항이다(제4호)."},{"번호":4,"판정":"옳음","설명":"지정대장 기재사항이다(제5호)."},{"번호":5,"판정":"틀림","설명":"부가통신사업자라는 점은 지정을 받을 수 있는 자의 자격이다(법 제24조제2항). 사업자번호는 지정대장 기재사항이 아니다."}],"개념":[{"종류":"흐름","제목":"거래정보사업자 지정부터 취소까지","단계":[{"이름":"지정 신청","설명":"지정신청서(별지 제16호서식)에 개업공인중개사의 가입ㆍ이용신청서와 등록증 사본, 정보처리기사ㆍ공인중개사 자격증 사본, 컴퓨터 용량ㆍ성능 서류, 부가통신사업 신고 확인 서류를 첨부해 국토교통부장관에게 낸다(시행규칙 제15조제1항)."},{"이름":"지정 요건","설명":"가입ㆍ이용신청 개업공인중개사 500명 이상이고 2개 이상 시ㆍ도에서 각 30인 이상, 정보처리기사 1명 이상, 공인중개사 1명 이상, 국토교통부장관이 정한 용량ㆍ성능의 컴퓨터설비(시행규칙 제15조제2항)."},{"이름":"지정ㆍ교부","설명":"신청 받은 날부터 30일 이내에 검토해 적합하면 지정하고, 지정대장에 적은 뒤 지정서를 교부한다(시행규칙 제15조제3항)."},{"이름":"운영규정 승인","설명":"지정받은 날부터 3개월 이내에 운영규정을 정해 국토교통부장관의 승인을 받는다. 변경할 때도 같다(법 제24조제3항)."},{"이름":"설치ㆍ운영","설명":"정당한 사유 없이 지정받은 날부터 1년 이내에 설치ㆍ운영하지 않으면 지정취소 사유다(법 제24조제5항제4호)."},{"이름":"취소","설명":"지정취소 사유 중 제1호~제4호로 취소하려면 청문을 실시한다(법 제24조제6항)."}]},{"종류":"비교","제목":"지정대장 기재사항과 운영규정 포함사항","왼쪽":{"이름":"지정대장 기재사항(시행규칙 제15조제3항)","항목":["지정 번호 및 지정 연월일","상호 또는 명칭 및 대표자의 성명","사무소의 소재지","주된 컴퓨터설비의 내역","전문자격자의 보유에 관한 사항"]},"오른쪽":{"이름":"운영규정 포함사항(시행규칙 제15조제4항)","항목":["부동산거래정보망에의 등록절차","자료의 제공 및 이용방법에 관한 사항","가입자에 대한 회비 및 그 징수에 관한 사항","거래정보사업자 및 가입자의 권리ㆍ의무에 관한 사항","그 밖에 부동산거래정보망의 이용에 관하여 필요한 사항"]}}],"함정":"신청 첨부서류(부가통신사업 신고 확인 서류)와 지정대장 기재사항을 섞은 선지다. 대장 기재사항은 다섯 가지로 닫혀 있다."}},{"i":"S3-2-1-중개사법-14","r":"S3","g":2,"c":2,"n":14,"s":"중개사법","q":"개업공인중개사가 주택을 임차하려는 중개의뢰인과 일반중개계약을 체결하면서 공인중개사법령상 표준서식인 일반중개계약서를 작성할 때 기재할 사항은?","b":null,"bs":"없음","img":[],"ch":["소유자 및 등기명의인","은행융자ㆍ권리금ㆍ제세공과금 등","중개의뢰 금액","희망 지역","거래규제 및 공법상 제한사항"],"a":[4],"L":"중1-6","o":"기출","x":{"한줄":"임차는 권리취득용(Ⅱ)에 적으며, 항목은 희망물건의 종류, 취득 희망가격, 희망 지역, 그 밖의 희망조건이다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"제13조","원문":"영 제19조의 규정에 따른 일반중개계약서는 별지 제14호서식에 따른다."},{"법령":"공인중개사법 시행규칙","조문":"별지 제14호서식(뒤쪽) Ⅱ","원문":"Ⅱ. 권리취득용(매수ㆍ임차 등): 희망물건의 종류 / 취득 희망가격 / 희망 지역 / 그 밖의 희망조건 / 첨부서류(중개보수 요율표)"},{"법령":"공인중개사법","조문":"제22조","원문":"중개의뢰인은 중개의뢰내용을 명확하게 하기 위하여 필요한 경우에는 개업공인중개사에게 다음 각 호의 사항을 기재한 일반중개계약서의 작성을 요청할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"소유자 및 등기명의인은 권리이전용(매도ㆍ임대 등) 항목이다."},{"번호":2,"판정":"틀림","설명":"은행융자ㆍ권리금ㆍ제세공과금 등(또는 월임대료ㆍ보증금ㆍ관리비 등)은 권리이전용의 '권리관계'란이다."},{"번호":3,"판정":"틀림","설명":"중개의뢰 금액은 권리이전용 항목이다."},{"번호":4,"판정":"옳음","설명":"희망 지역은 권리취득용(매수ㆍ임차 등) 항목이다."},{"번호":5,"판정":"틀림","설명":"거래규제 및 공법상 제한사항은 권리이전용 항목이다."}],"개념":[{"종류":"비교","제목":"일반중개계약서 뒤쪽: 권리이전용과 권리취득용","왼쪽":{"이름":"Ⅰ. 권리이전용(매도ㆍ임대 등)","항목":["구분: 매도ㆍ임대ㆍ그 밖의 사항","소유자 및 등기명의인(성명, 생년월일, 주소)","중개대상물의 표시(건축물ㆍ토지)","권리관계: 은행융자ㆍ권리금ㆍ제세공과금 등(또는 월임대료ㆍ보증금ㆍ관리비 등)","거래규제 및 공법상 제한사항","중개의뢰 금액, 그 밖의 사항"]},"오른쪽":{"이름":"Ⅱ. 권리취득용(매수ㆍ임차 등)","항목":["구분: 매수ㆍ임차ㆍ그 밖의 사항","희망물건의 종류","취득 희망가격","희망 지역","그 밖의 희망조건","첨부서류: 중개보수 요율표"]}},{"종류":"표","제목":"일반중개계약서 앞쪽의 주요 내용","머리":["항목","내용"],"행":[["을(개업공인중개사)의 의무","거래가 조속히 이루어지도록 성실히 노력"],["갑(중개의뢰인)의 권리ㆍ의무","다른 개업공인중개사에게도 중개를 의뢰할 수 있고, 확인ㆍ설명의무 이행에 협조"],["유효기간","3개월을 원칙으로 하되 합의로 별도 정할 수 있음"],["중개보수","거래가액의 일정 비율(또는 금액), 뒤쪽 별표의 요율을 넘지 않아야 하며 실비는 별도 지급"],["손해배상 책임","보수ㆍ실비 과다수령은 차액 환급, 확인ㆍ설명 소홀로 재산상 피해를 낸 경우 손해액 배상"],["작성","계약서 2통을 작성해 쌍방이 1통씩 보관"]]}],"함정":"서식 뒤쪽이 거래 방향에 따라 둘로 나뉜다는 점을 놓치면 권리이전용 항목(소유자, 권리관계, 공법상 제한, 중개의뢰 금액)을 임차인 계약서에 적게 된다."}},{"i":"S3-2-1-중개사법-15","r":"S3","g":2,"c":2,"n":15,"s":"중개사법","q":"공인중개사법령상 개업공인중개사와 중개의뢰인의 중개계약에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["일반중개계약은 계약서의 작성 없이도 체결할 수 있다.","전속중개계약을 체결하면서 유효기간을 3개월 미만으로 약정한 경우 그 유효기간은 3개월로 한다.","전속중개계약을 체결한 개업공인중개사는 중개대상물의 권리자의 인적 사항에 관한 정보를 공개해서는 안 된다.","중개의뢰인은 일반중개계약을 체결하면서 거래예정가격을 포함한 일반중개계약서의 작성을 요청할 수 있다.","임대차에 대한 전속중개계약을 체결한 개업공인중개사는 중개의뢰인의 비공개 요청이 없어도 중개대상물의 공시지가를 공개하지 아니할 수 있다."],"a":[2],"L":"중1-6","o":"기출","x":{"한줄":"전속중개계약의 유효기간은 3개월이 원칙이고 당사자가 달리 약정하면 그 약정에 따른다. 3개월 미만으로 정해도 약정한 기간이 유효기간이다.","근거":[{"법령":"공인중개사법 시행령","조문":"제20조제1항","원문":"법 제23조제1항의 규정에 따른 전속중개계약의 유효기간은 3월로 한다. 다만, 당사자간에 다른 약정이 있는 경우에는 그 약정에 따른다."},{"법령":"공인중개사법 시행령","조문":"제20조제2항제5호","원문":"소유권ㆍ전세권ㆍ저당권ㆍ지상권 및 임차권 등 중개대상물의 권리관계에 관한 사항. 다만, 각 권리자의 주소ㆍ성명 등 인적 사항에 관한 정보는 공개하여서는 아니 된다."},{"법령":"공인중개사법 시행령","조문":"제20조제2항제7호","원문":"중개대상물의 거래예정금액 및 공시지가. 다만, 임대차의 경우에는 공시지가를 공개하지 아니할 수 있다."},{"법령":"공인중개사법","조문":"제22조제2호","원문":"거래예정가격"}],"선지":[{"번호":1,"판정":"옳음","설명":"법 제22조는 중개의뢰인이 계약서 작성을 요청할 수 있다고만 정한다. 일반중개계약은 서면 없이도 체결된다."},{"번호":2,"판정":"틀림","설명":"3개월 미만으로 약정하면 그 약정이 유효기간이다(영 제20조제1항 단서). 3개월로 늘려 보정하지 않는다."},{"번호":3,"판정":"옳음","설명":"권리자의 주소ㆍ성명 등 인적 사항은 공개하지 않는다(영 제20조제2항제5호 단서)."},{"번호":4,"판정":"옳음","설명":"일반중개계약서 기재사항에 거래예정가격이 있다(법 제22조제2호)."},{"번호":5,"판정":"옳음","설명":"임대차의 경우 공시지가는 공개하지 않을 수 있다(영 제20조제2항제7호 단서). 비공개 요청 여부와 관계가 없다."}],"개념":[{"종류":"비교","제목":"일반중개계약과 전속중개계약","왼쪽":{"이름":"일반중개계약(법 제22조)","항목":["다른 개업공인중개사에게도 중개를 의뢰할 수 있음","서면 작성은 중개의뢰인의 요청이 있을 때, 표준서식은 별지 제14호서식(영 제19조)","기재사항: 중개대상물의 위치ㆍ규모, 거래예정가격, 중개보수, 그 밖의 준수사항","유효기간 3개월 원칙, 합의로 달리 정함(서식)","정보공개 의무 없음"]},"오른쪽":{"이름":"전속중개계약(법 제23조)","항목":["특정 개업공인중개사에 한정해 중개를 의뢰","국토교통부령이 정한 계약서(별지 제15호서식)에 의해야 하며 3년 보존(시행규칙 제14조제2항)","유효기간 3개월 원칙, 약정이 있으면 약정에 따름(영 제20조제1항)","체결 시 부동산거래정보망 또는 일간신문에 정보 공개, 의뢰인이 비공개를 요청하면 공개 금지(법 제23조제3항)","서식상 공개는 체결 후 7일 이내, 처리상황은 2주일에 1회 이상 문서 통지"]}},{"종류":"표","제목":"전속중개계약 공개 정보의 범위(영 제20조제2항)","머리":["공개 정보","공개 여부와 예외"],"행":[["중개대상물의 종류ㆍ소재지ㆍ지목ㆍ면적ㆍ건축물 용도ㆍ구조ㆍ건축연도","공개"],["벽면 및 도배의 상태","공개"],["수도ㆍ전기ㆍ가스ㆍ소방ㆍ열공급ㆍ승강기 설비, 오수ㆍ폐수ㆍ쓰레기 처리시설 상태","공개"],["도로ㆍ대중교통 연계성, 시장ㆍ학교 근접성, 입지ㆍ환경 조건","공개"],["소유권ㆍ전세권ㆍ저당권ㆍ지상권ㆍ임차권 등 권리관계","공개하되 권리자의 주소ㆍ성명 등 인적 사항은 공개 금지"],["공법상 이용제한 및 거래규제","공개"],["거래예정금액 및 공시지가","공개하되 임대차는 공시지가를 공개하지 않을 수 있음"]]}],"함정":"'3개월 미만으로 정하면 3개월로 본다'는 보정 규정은 없다. 영 제20조제1항 단서가 약정을 우선한다."}},{"i":"S3-2-1-중개사법-16","r":"S3","g":2,"c":2,"n":16,"s":"중개사법","q":"공인중개사법령상 개업공인중개사등의 금지행위에 해당하는 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["대법원규칙으로 정하는 요건을 갖추어 법원에 등록한 개업공인중개사가 경매 대상 부동산의 매수신청을 대리하는 행위","개업공인중개사가 중개대상물이 아닌 중고 자동차의 매매를 업으로 하는 행위","개업공인중개사가 자기 소유 상가의 매수를 중개의뢰한 사람에게 직접 그 상가를 매도하는 행위","개업공인중개사가 중개의뢰인이 제시한 매도 희망가보다 높은 가격에 거래를 성사시키고 법정 한도 내의 중개보수만 받은 행위","법인이 아닌 개업공인중개사가 상업용 건축물의 임대관리를 대행하는 행위"],"a":[3],"L":"중1-7","o":"변형","x":{"한줄":"개업공인중개사가 중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위는 금지행위다.","근거":[{"법령":"공인중개사법","조문":"제33조제1항제6호","원문":"중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위"},{"법령":"공인중개사법","조문":"제33조제1항제1호","원문":"제3조에 따른 중개대상물의 매매를 업으로 하는 행위"},{"법령":"공인중개사법","조문":"제33조제1항제3호","원문":"사례ㆍ증여 그 밖의 어떠한 명목으로도 제32조에 따른 보수 또는 실비를 초과하여 금품을 받는 행위"},{"법령":"공인중개사법","조문":"제14조제2항","원문":"개업공인중개사는 「민사집행법」에 의한 경매 및 「국세징수법」 그 밖의 법령에 의한 공매대상 부동산에 대한 권리분석 및 취득의 알선과 매수신청 또는 입찰신청의 대리를 할 수 있다."},{"법령":"공인중개사법","조문":"제14조제1항","원문":"법인인 개업공인중개사는 다른 법률에 규정된 경우를 제외하고는 중개업 및 다음 각 호에 규정된 업무와 제2항에 규정된 업무 외에 다른 업무를 함께 할 수 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"경매 대상 부동산의 권리분석과 매수신청 대리는 법이 허용한다. 대법원규칙의 요건을 갖춰 법원에 등록하고 감독을 받으면 된다(법 제14조제2항ㆍ제3항)."},{"번호":2,"판정":"틀림","설명":"금지되는 것은 '제3조에 따른 중개대상물'의 매매업이다(법 제33조제1항제1호). 중고 자동차는 중개대상물이 아니다."},{"번호":3,"판정":"옳음","설명":"중개를 의뢰한 사람에게 개업공인중개사가 직접 매도인으로 나서는 것은 중개의뢰인과의 직접 거래다(법 제33조제1항제6호)."},{"번호":4,"판정":"틀림","설명":"금지되는 것은 보수 또는 실비를 '초과'한 금품 수수다(제3호). 한도 안의 보수는 거래가격이 높게 성사되어도 문제없다."},{"번호":5,"판정":"틀림","설명":"겸업 제한은 법인인 개업공인중개사에게만 적용된다(법 제14조제1항). 법인 아닌 개업공인중개사의 임대관리 대행에는 제한이 없다."}],"개념":[{"종류":"표","제목":"개업공인중개사등의 금지행위(법 제33조제1항)와 벌칙","머리":["호","금지행위","벌칙"],"행":[["1","중개대상물의 매매를 업으로 하는 행위","1년 이하 징역 또는 1천만원 이하 벌금(법 제49조제1항제10호)"],["2","무등록 중개업자인 사실을 알면서 그를 통해 중개를 의뢰받거나 자기 명의를 이용하게 하는 행위","같음"],["3","보수 또는 실비를 초과하여 금품을 받는 행위","같음"],["4","거래상 중요사항에 관한 거짓된 언행으로 중개의뢰인의 판단을 그르치게 하는 행위","같음"],["5","관계 법령에서 양도ㆍ알선 등이 금지된 부동산의 분양ㆍ임대 등과 관련 있는 증서 등의 매매ㆍ교환 등을 중개하거나 그 매매를 업으로 하는 행위","3년 이하 징역 또는 3천만원 이하 벌금(법 제48조제3호)"],["6","중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위","같음"],["7","탈세 등 관계 법령 위반 목적으로 미등기 부동산이나 전매 등이 제한된 부동산의 매매를 중개하는 등 부동산투기를 조장하는 행위","같음"],["8","부당한 이익을 얻거나 얻게 할 목적으로 거짓으로 거래가 완료된 것처럼 꾸미는 등 시세에 부당한 영향을 주는 행위","같음"],["9","단체를 구성하여 특정 중개대상물에 대한 중개를 제한하거나 단체 구성원 이외의 자와의 공동중개를 제한하는 행위","같음"]]},{"종류":"표","제목":"누구든지 할 수 없는 업무방해 행위(법 제33조제2항)","머리":["호","금지 행위"],"행":[["1","안내문, 온라인 커뮤니티 등으로 특정 개업공인중개사등에 대한 중개의뢰를 제한하거나 제한을 유도"],["2","시세보다 현저히 높게 표시ㆍ광고 또는 중개하는 특정 개업공인중개사등에게만 중개의뢰를 하도록 유도해 다른 개업공인중개사등을 부당하게 차별"],["3","특정 가격 이하로 중개를 의뢰하지 않도록 유도"],["4","정당한 사유 없이 정당한 표시ㆍ광고 행위를 방해"],["5","중개대상물을 시세보다 현저히 높게 표시ㆍ광고하도록 강요하거나 대가를 약속하고 유도"]]}],"함정":"'중개대상물의 매매업' 금지에서 중개대상물이 아닌 물건(자동차 등)은 빠진다. 반대로 개업공인중개사 본인이 중개의뢰인의 상대방이 되면 매매를 업으로 하지 않아도 직접 거래 금지에 걸린다."}},{"i":"S3-2-1-중개사법-17","r":"S3","g":2,"c":2,"n":17,"s":"중개사법","q":"공인중개사법령상 개업공인중개사가 주거용 건축물의 중개대상물 확인ㆍ설명서[Ⅰ]를 작성하는 방법에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["건축물대장에서 내진설계 적용여부와 내진능력을 확인하기 어려운 경우에는 해당 항목을 비워 둔다.","건축물의 방향은 주택의 경우 건축물의 주된 출입구의 방향을 기준으로 적는다.","임대차로서 거래예정금액이 5천만원 미만인 경우에도 임대보증금에 월 단위의 차임액에 100을 곱한 금액을 합산하여 거래예정금액으로 한다.","내부ㆍ외부 시설물의 상태, 벽면ㆍ바닥면 및 도배 상태, 환경조건은 개업공인중개사가 매도(임대)의뢰인에게 자료를 요구하여 확인한 사항을 적는다.","취득 시 부담할 조세의 종류 및 세율은 임대차의 경우에도 적어야 한다."],"a":[4],"L":"중1-8","o":"변형","x":{"한줄":"⑪ 내부ㆍ외부 시설물의 상태, ⑫ 벽면ㆍ바닥면 및 도배 상태, ⑬ 환경조건은 개업공인중개사가 매도(임대)의뢰인에게 자료를 요구하여 확인한 사항을 적는다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식 작성방법 12","원문":"⑪ 내부ㆍ외부 시설물의 상태(건축물), ⑫ 벽면ㆍ바닥면 및 도배 상태와 ⑬ 환경조건은 중개대상물에 대해 개업공인중개사가 매도(임대)의뢰인에게 자료를 요구하여 확인한 사항을 적고"},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식 작성방법 3","원문":"건축물의 방향은 주택의 경우 거실이나 안방 등 주실(主室)의 방향을, 그 밖의 건축물은 주된 출입구의 방향을 기준으로 남향, 북향 등 방향을 적고"},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식 작성방법 3","원문":"건축물대장에서 \"내진설계 적용여부\", \"내진능력\"을 확인하기 어려운 경우에는 '확인불가' 등으로 그 사유를 적습니다."},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식 작성방법 13","원문":"다만, 임대차로서 거래예정금액이 5천만원 미만인 경우에는 \"임대보증금 + 월 단위의 차임액 × 70\"을 거래예정금액으로 합니다."},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식 작성방법 10","원문":"⑨ 취득 시 부담할 조세의 종류 및 세율은 중개가 완성되기 전 「지방세법」의 내용을 확인하여 적습니다(임대차의 경우에는 제외합니다)."}],"선지":[{"번호":1,"판정":"틀림","설명":"확인하기 어려우면 '확인불가' 등으로 그 사유를 적는다."},{"번호":2,"판정":"틀림","설명":"주택은 거실이나 안방 등 주실의 방향을 기준으로 한다. 주된 출입구 방향은 주택 외 건축물의 기준이다."},{"번호":3,"판정":"틀림","설명":"합산액이 5천만원 미만이면 월 단위의 차임액에 70을 곱해 합산한다(시행규칙 제20조제5항제1호 단서와 같은 취지)."},{"번호":4,"판정":"옳음","설명":"⑪~⑬은 개업공인중개사가 매도(임대)의뢰인에게 자료를 요구해 확인한 사항을 적는다. 불응하면 그 사실을 매수ㆍ임차의뢰인에게 설명하고 서식에 기재한다(영 제21조제2항)."},{"번호":5,"판정":"틀림","설명":"취득 시 부담할 조세는 임대차의 경우 제외한다."}],"개념":[{"종류":"표","제목":"중개대상물 확인ㆍ설명서[Ⅰ](주거용 건축물)의 구성","머리":["구분","항목","작성 방법"],"행":[["Ⅰ. 기본 확인사항","① 대상물건의 표시, ② 권리관계, ③ 토지이용계획ㆍ공법상 이용제한(토지), ④ 임대차 확인사항, ⑤ 입지조건, ⑥ 관리에 관한 사항, ⑦ 비선호시설(1km 이내), ⑧ 거래예정금액 등, ⑨ 취득 시 부담할 조세","개업공인중개사가 확인한 사항을 적음"],["Ⅱ. 세부 확인사항","⑩ 실제 권리관계 또는 공시되지 않은 물건의 권리 사항","매도(임대)의뢰인이 고지한 사항"],["Ⅱ. 세부 확인사항","⑪ 내부ㆍ외부 시설물의 상태, ⑫ 벽면ㆍ바닥면 및 도배 상태, ⑬ 환경조건","매도(임대)의뢰인에게 자료를 요구해 확인한 사항"],["Ⅱ. 세부 확인사항","⑭ 현장안내(현장안내자, 중개보조원 신분고지 여부)","해당 사항에 표시"],["Ⅲ. 중개보수 등","⑮ 중개보수 및 실비의 금액과 산출내역","협의로 결정한 금액, 거래예정금액 기준으로 산출"],["임대차의 경우 생략ㆍ제외","③ 토지이용계획ㆍ공법상 제한은 생략 가능, ⑧의 개별공시지가ㆍ주택공시가격은 생략 가능, ⑨ 조세는 제외","작성방법 5, 9, 10"]]},{"종류":"표","제목":"확인ㆍ설명서의 서식 구분과 작성ㆍ보존","머리":["구분","내용","근거"],"행":[["[Ⅰ] 주거용 건축물","별지 제20호서식","시행규칙 제16조제1호"],["[Ⅱ] 비주거용 건축물","별지 제20호의2서식","제2호"],["[Ⅲ] 토지","별지 제20호의3서식","제3호"],["[Ⅳ] 입목ㆍ광업재단ㆍ공장재단","별지 제20호의4서식","제4호"],["확인ㆍ설명 시기","중개가 완성되기 전, 권리를 취득하려는 중개의뢰인에게 설명하고 근거자료 제시","법 제25조제1항"],["서명ㆍ날인","개업공인중개사(법인은 대표자, 분사무소는 책임자)가 서명 및 날인, 해당 중개행위를 한 소속공인중개사가 있으면 함께 서명 및 날인","법 제25조제4항"],["보존 기간","확인ㆍ설명서 원본ㆍ사본ㆍ전자문서 3년, 거래계약서 5년","영 제21조제4항, 제22조제2항"]]}],"함정":"작성방법의 '구분'이 열쇠다. 주택은 주실, 그 밖은 출입구, 5천만원 미만은 ×70, 임대차는 조세 제외, 확인이 어려우면 '확인불가'라고 사유를 적는다."}},{"i":"S3-2-1-중개사법-18","r":"S3","g":2,"c":2,"n":18,"s":"중개사법","q":"공인중개사법령상 중개대상물 확인ㆍ설명서[I] (주거용 건축물) 서식의 기재내용으로 개업공인중개사 기본 확인사항 중 임대차 확인사항에 해당하는 것을 모두 고른 것은?","b":"ㄱ. 국세 및 지방세 체납정보\nㄴ. 민간임대등록 여부\nㄷ. 현장안내 중개보조원 신분 고지 여부\nㄹ. 최우선변제금","bs":"글자","img":[],"ch":["ㄱ, ㄷ","ㄴ, ㄹ","ㄱ, ㄴ, ㄹ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":[3],"L":"중1-8","o":"기출","x":{"한줄":"④ 임대차 확인사항에는 확정일자 부여현황, 국세ㆍ지방세 체납정보, 전입세대 확인서, 최우선변제금, 민간임대 등록 여부가 있다. 현장안내 중개보조원 신분고지는 세부 확인사항 ⑭다.","근거":[{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식 Ⅰ. ④ 임대차 확인사항","원문":"확정일자 부여현황 정보 / 국세 및 지방세 체납정보 / 전입세대 확인서 / 최우선변제금 / 민간임대 등록여부"},{"법령":"공인중개사법 시행규칙","조문":"별지 제20호서식 Ⅱ. ⑭ 현장안내","원문":"현장안내자 [ ]개업공인중개사 [ ]소속공인중개사 [ ]중개보조원(신분고지 여부: [ ] 예 [ ] 아니오) [ ]해당 없음"},{"법령":"공인중개사법","조문":"제18조의4","원문":"중개보조원은 현장안내 등 중개업무를 보조하는 경우 중개의뢰인에게 본인이 중개보조원이라는 사실을 미리 알려야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"ㄱ은 임대차 확인사항이나 ㄷ은 세부 확인사항(⑭)이다."},{"번호":2,"판정":"틀림","설명":"ㄴ과 ㄹ은 임대차 확인사항이지만 ㄱ이 빠졌다."},{"번호":3,"판정":"옳음","설명":"ㄱ, ㄴ, ㄹ이 ④ 임대차 확인사항에 해당한다."},{"번호":4,"판정":"틀림","설명":"ㄷ은 임대차 확인사항이 아니다."},{"번호":5,"판정":"틀림","설명":"ㄷ이 섞여 있다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"국세 및 지방세 체납정보는 ④ 임대차 확인사항의 항목이다. 임대인 자료 제출 또는 열람 동의로 갈음했는지 표시하고 임차인 권리를 설명한다."},{"기호":"ㄴ","판정":"옳음","설명":"민간임대 등록 여부(장기일반ㆍ공공지원 등 유형, 임대의무기간, 임대개시일, 임대보증금 보증 설명)는 ④ 임대차 확인사항이다."},{"기호":"ㄷ","판정":"틀림","설명":"현장안내자가 중개보조원이면 신분고지 여부를 표시하는 곳은 Ⅱ 세부 확인사항 ⑭다."},{"기호":"ㄹ","판정":"옳음","설명":"최우선변제금(소액임차인범위와 최우선변제금액)은 ④ 임대차 확인사항이다. 선순위 담보물권 설정 당시 기준으로 적는다."}],"개념":[{"종류":"표","제목":"확인ㆍ설명서[Ⅰ] ④ 임대차 확인사항의 항목과 표시 방법","머리":["항목","표시 방법"],"행":[["확정일자 부여현황 정보","임대인 자료 제출 또는 열람 동의, 임차인 권리 설명"],["국세 및 지방세 체납정보","임대인 자료 제출 또는 열람 동의, 임차인 권리 설명"],["전입세대 확인서","확인(서류 첨부) / 미확인(열람ㆍ교부 신청방법 설명) / 해당 없음"],["최우선변제금","소액임차인범위와 최우선변제금액, 선순위 담보물권 설정 당시 기준"],["민간임대 등록여부","등록 유형, 임대의무기간ㆍ임대개시일, 임대보증금 보증 설명 / 미등록"]]},{"종류":"표","제목":"확인ㆍ설명서[Ⅰ]에서 헷갈리는 항목의 위치","머리":["위치","항목"],"행":[["Ⅰ-② 권리관계","등기부 기재사항, 신탁등기 여부, 공동담보 여부, 계약갱신요구권 행사 여부(2026.8.11 개정으로 이동)"],["Ⅰ-④ 임대차 확인사항","확정일자 부여현황, 국세ㆍ지방세 체납정보, 전입세대 확인서, 최우선변제금, 민간임대 등록 여부"],["Ⅰ-⑥ 관리에 관한 사항","경비실, 관리주체, 관리비 금액ㆍ포함 비목ㆍ부과방식"],["Ⅱ-⑪ 내부ㆍ외부 시설물","수도, 전기, 가스, 소방(단독경보형 감지기), 난방, 승강기, 배수"],["Ⅱ-⑭ 현장안내","현장안내자, 중개보조원 신분고지 여부"]]}],"함정":"서식 개정 전 위치로 암기하면 흔들린다. 계약갱신요구권은 현재 ② 권리관계에 있고, ④에는 최우선변제금이 남아 있다. ㄷ의 신분고지는 어느 판이든 ⑭다.","개정":"별지 제20호서식이 2026.8.11 개정되어 '계약갱신요구권 행사 여부'가 ④ 임대차 확인사항에서 ② 권리관계로 옮겨졌다. 기출 보기 ㄹ을 현행 ④ 항목인 '최우선변제금'으로 교체했고, 정답 ③은 그대로다."}},{"i":"S3-2-1-중개사법-19","r":"S3","g":2,"c":2,"n":19,"s":"중개사법","q":"공인중개사법령상 손해배상책임의 보장에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["개업공인중개사는 중개가 완성된 때에는 거래당사자에게 손해배상책임의 보장기간을 설명해야 한다.","개업공인중개사는 고의로 거래당사자에게 손해를 입힌 경우에는 재산상의 손해뿐만 아니라 비재산적 손해에 대해서도 공인중개사법령상 손해배상책임보장규정에 의해 배상할 책임이 있다.","개업공인중개사가 자기의 중개사무소를 다른 사람의 중개행위의 장소로 제공하여 거래당사자에게 재산상의 손해를 발생하게 한 때에는 그 손해를 배상할 책임이 있다.","법인인 개업공인중개사가 분사무소를 두는 경우 분사무소마다 추가로 2억원 이상의 손해배상책임의 보증설정을 해야 하나 보장금액의 상한은 없다.","지역농업협동조합이 ｢농업협동조합법｣에 의해 부동산중개업을 하는 경우 보증기관에 설정하는 손해배상책임보증의 최저보장금액은 개업공인중개사의 최저보장금액과 다르다."],"a":[2],"L":"중1-9","o":"기출","x":{"한줄":"손해배상책임 보장 규정이 다루는 손해는 재산상 손해다. 비재산적 손해까지 보장규정으로 배상하는 것은 아니다.","근거":[{"법령":"공인중개사법","조문":"제30조제1항","원문":"개업공인중개사는 중개행위를 하는 경우 고의 또는 과실로 인하여 거래당사자에게 재산상의 손해를 발생하게 한 때에는 그 손해를 배상할 책임이 있다."},{"법령":"공인중개사법","조문":"제30조제2항","원문":"개업공인중개사는 자기의 중개사무소를 다른 사람의 중개행위의 장소로 제공함으로써 거래당사자에게 재산상의 손해를 발생하게 한 때에는 그 손해를 배상할 책임이 있다."},{"법령":"공인중개사법","조문":"제30조제5항","원문":"개업공인중개사는 중개가 완성된 때에는 거래당사자에게 손해배상책임의 보장에 관한 다음 각 호의 사항을 설명하고 관계 증서의 사본을 교부하거나 관계 증서에 관한 전자문서를 제공하여야 한다."},{"법령":"공인중개사법 시행령","조문":"제24조제1항","원문":"개업공인중개사는 법 제30조제3항에 따라 다음 각 호의 구분에 따른 금액을 보장하는 보증보험 또는 공제에 가입하거나 공탁을 해야 한다."},{"법령":"공인중개사법 시행령","조문":"제24조제1항제1호","원문":"법인인 개업공인중개사 : 4억원 이상. 다만, 분사무소를 두는 경우에는 분사무소마다 2억원 이상을 추가로 설정해야 한다."},{"법령":"공인중개사법 시행령","조문":"제24조제1항제2호","원문":"법인이 아닌 개업공인중개사 : 2억원 이상"},{"법령":"공인중개사법 시행령","조문":"제24조제3항","원문":"다른 법률에 따라 부동산중개업을 할 수 있는 자가 부동산중개업을 하려는 경우에는 중개업무를 개시하기 전에 보장금액 2천만원 이상의 보증을 보증기관에 설정하고 그 증명서류를 갖추어 등록관청에 신고해야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"중개가 완성되면 보장금액, 보증기관과 소재지, 보장기간을 설명한다(법 제30조제5항)."},{"번호":2,"판정":"틀림","설명":"보장규정이 정한 배상 대상은 '재산상의 손해'다(법 제30조제1항ㆍ제2항). 비재산적 손해는 보장규정의 배상 대상이 아니다."},{"번호":3,"판정":"옳음","설명":"중개사무소를 다른 사람의 중개행위 장소로 제공해 재산상 손해를 발생시키면 배상책임이 있다(법 제30조제2항)."},{"번호":4,"판정":"옳음","설명":"분사무소를 두면 분사무소마다 2억원 이상을 추가로 설정한다. 이상이므로 상한은 없다(영 제24조제1항제1호)."},{"번호":5,"판정":"옳음","설명":"다른 법률에 따라 중개업을 하는 지역농협은 2천만원 이상이고, 개업공인중개사는 법인 4억원, 법인 아닌 경우 2억원이다(영 제24조제1항ㆍ제3항)."}],"개념":[{"종류":"표","제목":"손해배상책임 보장의 금액과 운영","머리":["항목","내용","근거"],"행":[["법인인 개업공인중개사","4억원 이상, 분사무소마다 2억원 이상 추가","영 제24조제1항제1호"],["법인이 아닌 개업공인중개사","2억원 이상","영 제24조제1항제2호"],["다른 법률에 따라 중개업을 하는 자","보장금액 2천만원 이상","영 제24조제3항"],["보증 방법","보증보험 또는 공제 가입, 공탁","법 제30조제3항"],["설정 시기","업무를 시작하기 전, 증명서류를 갖춰 등록관청에 신고(보증기관이 직접 통보하면 생략)","영 제24조제2항"],["설명ㆍ교부","중개가 완성된 때 보장금액ㆍ보증기관 및 소재지ㆍ보장기간 설명, 관계 증서 사본 교부 또는 전자문서 제공","법 제30조제5항"],["보증 변경","기존 보증의 효력 기간 중에 다른 보증을 설정하고 신고, 보증기간 만료 시 만료일까지 다시 설정","영 제25조"],["보험금 지급","합의서ㆍ화해조서ㆍ확정판결문 사본 등을 첨부해 보증기관에 청구, 지급 후 15일 이내 재가입 또는 부족액 보전","영 제26조"],["공탁금 회수","폐업 또는 사망한 날부터 3년 이내에는 회수 불가","법 제30조제4항"]]},{"종류":"표","제목":"계약금등의 반환채무이행 보장(법 제31조)","머리":["항목","내용","근거"],"행":[["예치 권고","거래 안전을 위해 필요하면 계약금ㆍ중도금ㆍ잔금을 금융기관 등에 예치하도록 거래당사자에게 권고","법 제31조제1항"],["예치기관","은행, 보험회사, 신탁업자, 체신관서, 공제사업자, 계약이행 보장 전문회사","영 제27조제1항"],["예치명의자","개업공인중개사 또는 대통령령으로 정하는 자","법 제31조제1항"],["미리 수령","매도인ㆍ임대인 등은 계약 해제 시 반환을 보장하는 금융기관ㆍ보증보험회사 보증서를 예치명의자에게 교부하고 미리 수령 가능","법 제31조제2항"],["개업공인중개사 명의로 예치","자기 소유 예치금과 분리 관리, 거래당사자 동의 없이 인출 금지, 예치금액 상당 보증보험ㆍ공제 가입 또는 공탁하고 관계 증서 사본 교부","영 제27조제3항ㆍ제4항"],["실비","반환채무이행 보장에 소요되는 실비는 매수ㆍ임차 등 권리를 취득하려는 중개의뢰인에게 청구","법 제32조제2항, 시행규칙 제20조제2항"]]}],"함정":"금액 선지는 법 개정을 따라 움직인다. 현행 영 제24조는 법인 4억원, 분사무소 2억원 추가, 법인 아닌 경우 2억원이다. 정답을 가르는 쟁점은 금액이 아니라 보장 대상이 재산상 손해뿐이라는 점이다.","개정":"기출 원문의 ④ 분사무소 추가 보증 금액 1억원을 현행 2억원으로 고쳤다(영 제24조제1항제1호 단서, 2021.12.31 개정). ⑤의 지역농협 2천만원은 영 제24조제3항 그대로이며, 개업공인중개사 최저보장금액(법인 4억원, 법인 아닌 경우 2억원)과 다르다. 정답 ②는 그대로다."}},{"i":"S3-2-1-중개사법-20","r":"S3","g":2,"c":2,"n":20,"s":"중개사법","q":"공인중개사인 개업공인중개사 甲의 소속공인중개사 乙과 중개보조원 丙이 관여하여 중개가 완성되었다. 공인중개사법령상 이에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["乙의 중개행위가 금지행위에 해당하여 乙이 벌금형을 선고받은 경우, 甲이 상당한 주의와 감독을 게을리하지 않았더라도 甲에게 해당 조에 규정된 벌금형이 과해진다.","丙이 현장안내를 하면서 중개의뢰인에게 본인이 중개보조원이라는 사실을 미리 알리지 않으면 丙은 500만원 이하의 과태료 부과 대상이 된다.","乙이 해당 중개행위를 한 경우 중개대상물 확인ㆍ설명서에는 甲과 乙이 함께 서명 및 날인하여야 한다.","乙이 등록하지 아니한 인장을 중개행위에 사용한 경우 시ㆍ도지사는 6개월의 범위 안에서 乙의 자격을 정지할 수 있다.","甲은 중개가 완성된 때 거래당사자에게 보장금액, 보증기관 및 그 소재지, 보장기간을 설명하고 관계 증서의 사본을 교부하거나 전자문서를 제공하여야 한다."],"a":[1],"L":"중1-10","o":"변형","x":{"한줄":"소속공인중개사ㆍ중개보조원의 위반에 대한 양벌규정은, 개업공인중개사가 상당한 주의와 감독을 게을리하지 않았으면 적용되지 않는다.","근거":[{"법령":"공인중개사법","조문":"제50조","원문":"소속공인중개사ㆍ중개보조원 또는 개업공인중개사인 법인의 사원ㆍ임원이 중개업무에 관하여 제48조 또는 제49조의 규정에 해당하는 위반행위를 한 때에는 그 행위자를 벌하는 외에 그 개업공인중개사에 대하여도 해당 조에 규정된 벌금형을 과한다. 다만, 그 개업공인중개사가 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우에는 그러하지 아니하다."},{"법령":"공인중개사법","조문":"제51조제2항제1호의4","원문":"제18조의4를 위반하여 중개의뢰인에게 본인이 중개보조원이라는 사실을 미리 알리지 아니한 사람 및 그가 소속된 개업공인중개사. 다만, 개업공인중개사가 그 위반행위를 방지하기 위하여 해당 업무에 관하여 상당한 주의와 감독을 게을리하지 아니한 경우는 제외한다."},{"법령":"공인중개사법","조문":"제25조제4항","원문":"해당 중개행위를 한 소속공인중개사가 있는 경우에는 소속공인중개사가 함께 서명 및 날인하여야 한다."},{"법령":"공인중개사법","조문":"제36조제1항제2호","원문":"제16조의 규정을 위반하여 인장등록을 하지 아니하거나 등록하지 아니한 인장을 사용한 경우"},{"법령":"공인중개사법","조문":"제30조제5항","원문":"개업공인중개사는 중개가 완성된 때에는 거래당사자에게 손해배상책임의 보장에 관한 다음 각 호의 사항을 설명하고 관계 증서의 사본을 교부하거나 관계 증서에 관한 전자문서를 제공하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"甲이 위반행위를 방지하려고 상당한 주의와 감독을 게을리하지 않았다면 양벌규정이 적용되지 않는다(법 제50조 단서)."},{"번호":2,"판정":"옳음","설명":"중개보조원의 고지의무 위반은 그 사람과 소속 개업공인중개사 모두 500만원 이하 과태료 대상이다. 개업공인중개사는 상당한 주의와 감독을 했으면 제외된다(법 제51조제2항제1호의4)."},{"번호":3,"판정":"옳음","설명":"확인ㆍ설명서에는 개업공인중개사가 서명ㆍ날인하고, 해당 중개행위를 한 소속공인중개사가 있으면 함께 서명ㆍ날인한다(법 제25조제4항)."},{"번호":4,"판정":"옳음","설명":"소속공인중개사가 등록하지 않은 인장을 사용하면 시ㆍ도지사가 6개월 범위에서 자격을 정지할 수 있다(법 제36조제1항제2호)."},{"번호":5,"판정":"옳음","설명":"보장금액, 보증기관 및 소재지, 보장기간을 설명하고 증서 사본을 교부하거나 전자문서를 제공한다(법 제30조제5항)."}],"개념":[{"종류":"표","제목":"고용인의 행위에 대한 개업공인중개사의 책임","머리":["구분","내용","근거"],"행":[["업무상 행위의 귀속","소속공인중개사ㆍ중개보조원의 업무상 행위는 개업공인중개사의 행위로 봄","법 제15조제2항"],["양벌규정 적용 행위자","소속공인중개사, 중개보조원, 법인의 사원ㆍ임원이 중개업무에 관해 제48조ㆍ제49조 위반","법 제50조"],["개업공인중개사의 책임","행위자를 벌하는 외에 해당 조에 규정된 벌금형(징역형은 적용되지 않음)","법 제50조"],["면책","위반행위 방지를 위해 상당한 주의와 감독을 게을리하지 않은 경우","법 제50조 단서"],["중개보조원 고지의무 위반","중개보조원 및 소속 개업공인중개사에게 500만원 이하 과태료, 개업공인중개사는 상당한 주의ㆍ감독 시 제외","법 제51조제2항제1호의4"],["소속공인중개사의 위반","시ㆍ도지사가 6개월 범위에서 자격정지(인장, 확인ㆍ설명, 서명날인 누락, 금지행위 등)","법 제36조제1항"]]},{"종류":"계산","제목":"주택 임대차 중개보수 상한 계산(보증금 1억원, 월차임 50만원)","단계":[{"설명":"거래금액 산정 공식: 보증금 + 월차임 × 100 (합산액이 5천만원 미만이면 월차임 × 70)","식":"보증금 + 월차임 × 100","값":"시행규칙 제20조제5항제1호"},{"설명":"대입","식":"100,000,000 + 500,000 × 100 = 100,000,000 + 50,000,000","값":"150,000,000원"},{"설명":"5천만원 이상이므로 × 100 방식을 그대로 적용","식":"150,000,000 ≥ 50,000,000","값":"× 100 유지"},{"설명":"별표 1 구간 확인: 임대차 등에서 1억원 이상 6억원 미만의 상한요율은 1천분의 3, 한도액 없음","식":"1천분의 3","값":"0.3%"},{"설명":"중개보수 상한 계산(실제로는 시ㆍ도 조례의 요율한도 이내에서 협의, 부가가치세 별도)","식":"150,000,000 × 0.003","값":"450,000원"}]}],"함정":"양벌규정은 '개업공인중개사는 반드시 같이 처벌된다'로 단정하기 쉽다. 상당한 주의와 감독을 다한 경우의 면책(단서)과 징역형이 아닌 벌금형만 과한다는 점이 열쇠다."}},{"i":"S3-2-1-중개사법-21","r":"S3","g":2,"c":2,"n":21,"s":"중개사법","q":"공인중개사법령상 포상금에 관한 설명으로 옳은 것을 모두 고른 것은?","b":"ㄱ. 포상금을 지급받으려는 자는 포상금지급신청서를 국토교통부장관에게 제출하여야 한다.\nㄴ. 포상금은 수사기관에 고발한 자에게 그 사건에 대해 검사가 공소제기의 결정을 한 경우에 한하여 지급한다.\nㄷ. 포상금은 1건당 50만원으로 한다.","bs":"글자","img":[],"ch":["ㄱ","ㄷ","ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":[2],"L":"중1-11","o":"기출","x":{"한줄":"포상금 신청서는 등록관청에 내고, 지급은 검사의 공소제기 또는 기소유예 결정이 있어야 하며, 금액은 1건당 50만원이다. 보기 중 ㄷ만 맞다.","근거":[{"법령":"공인중개사법","조문":"제46조 제1항","원문":"①등록관청은 다음 각 호의 어느 하나에 해당하는 자를 등록관청, 수사기관이나 제47조의2에 따른 부동산거래질서교란행위 신고센터에 신고 또는 고발한 자에 대하여 대통령령으로 정하는 바에 따라 포상금을 지급할 수 있다.\n1. 제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 한 자\n2. 거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 자\n3. 중개사무소등록증 또는 공인중개사자격증을 다른 사람에게 양도ㆍ대여하거나 다른 사람으로부터 양수ㆍ대여받은 자\n4. 제18조의2제3항을 위반하여 표시ㆍ광고를 한 자\n5. 제33조제1항제8호 또는 제9호에 따른 행위를 한 자\n6. 제33조제2항을 위반하여 개업공인중개사등의 업무를 방해한 자"},{"법령":"공인중개사법 시행령","조문":"제36조의2 제1항 제2항 제3항","원문":"①법 제46조제1항의 규정에 따른 포상금은 1건당 50만원으로 한다.\n②제1항의 규정에 따른 포상금은 법 제46조제1항 각 호의 어느 하나에 해당하는 자가 행정기관에 의하여 발각되기 전에 등록관청이나 수사기관에 신고 또는 고발한 자에게 그 신고 또는 고발사건에 대하여 검사가 공소제기 또는 기소유예의 결정을 한 경우에 한하여 지급한다.\n③법 제46조제2항의 규정에 따라 포상금의 지급에 소요되는 비용 중 국고에서 보조할 수 있는 비율은 100분의 50이내로 한다."},{"법령":"공인중개사법 시행규칙","조문":"제28조 제1항 제2항","원문":"①영 제36조의2에 따른 포상금을 지급받으려는 자는 별지 제28호서식의 포상금지급신청서를 등록관청에 제출해야 한다.\n②제1항의 규정에 따라 포상금지급신청서를 제출받은 등록관청은 그 사건에 관한 수사기관의 처분내용을 조회한 후 포상금의 지급을 결정하고, 그 결정일부터 1월 이내에 포상금을 지급하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ은 틀린 설명이다. 맞는 ㄷ이 빠져 있어 정답 조합이 아니다."},{"번호":2,"판정":"-","설명":"ㄷ만 맞는 설명이므로 정답 조합이다."},{"번호":3,"판정":"-","설명":"ㄱ과 ㄴ은 둘 다 틀린 설명이다."},{"번호":4,"판정":"-","설명":"ㄴ은 틀린 설명이다. 기소유예 결정에도 지급하므로 ㄴ을 포함한 조합은 맞지 않다."},{"번호":5,"판정":"-","설명":"ㄱ과 ㄴ이 틀린 설명이라 세 개를 모두 고를 수 없다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"포상금지급신청서는 등록관청에 제출한다(시행규칙 제28조제1항). 국토교통부장관이 받는 것이 아니다."},{"기호":"ㄴ","판정":"틀림","설명":"검사가 공소제기 또는 기소유예의 결정을 한 경우에 지급한다(시행령 제36조의2제2항). 공소제기만 요건으로 적으면 틀리다."},{"기호":"ㄷ","판정":"옳음","설명":"포상금은 1건당 50만원이다(시행령 제36조의2제1항)."}],"개념":[{"종류":"표","제목":"포상금 지급 대상 (법 제46조제1항)","머리":["신고·고발 대상","근거"],"행":[["중개사무소 개설등록 없이 중개업을 한 자","제1호"],["거짓이나 그 밖의 부정한 방법으로 개설등록을 한 자","제2호"],["중개사무소등록증·공인중개사자격증을 양도·대여하거나 양수·대여받은 자","제3호"],["개업공인중개사가 아니면서 중개대상물을 표시·광고한 자","제4호 (법 제18조의2제3항)"],["거짓 거래완료로 시세에 부당한 영향을 주는 행위, 단체 구성으로 중개·공동중개를 제한하는 행위","제5호 (법 제33조제1항제8호·제9호)"],["시세에 영향을 줄 목적으로 개업공인중개사등의 업무를 방해한 자","제6호 (법 제33조제2항)"]]},{"종류":"흐름","제목":"포상금 지급 절차","단계":[{"이름":"신고·고발","설명":"행정기관에 발각되기 전에 등록관청·수사기관·신고센터에 신고 또는 고발한다."},{"이름":"검사의 처분","설명":"검사가 공소제기 또는 기소유예를 결정해야 지급 요건이 갖춰진다."},{"이름":"신청서 제출","설명":"포상금지급신청서를 등록관청에 낸다."},{"이름":"지급 결정","설명":"등록관청이 수사기관의 처분내용을 조회한 뒤 지급을 결정한다."},{"이름":"지급","설명":"결정일부터 1개월 이내에 1건당 50만원을 지급한다. 공동 신고는 균등 배분(합의가 있으면 그 방법), 같은 사건의 2건 이상 신고는 최초 신고자에게 지급한다."}]}],"함정":"신청서는 국토교통부장관이 아니라 등록관청에 낸다. 지급 요건에는 공소제기 외에 기소유예도 들어간다. 지급 주체는 등록관청이고, 국고 보조는 100분의 50 이내다."}},{"i":"S3-2-1-중개사법-22","r":"S3","g":2,"c":2,"n":22,"s":"중개사법","q":"공인중개사법령상 한국공인중개사협회(이하 '협회'라 함)에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["협회가 공제규정을 변경하려는 때에도 국토교통부장관의 승인을 얻어야 한다.","공제규정에서 정하는 책임준비금의 적립비율은 공제금 지급액의 100분의 10 이상으로 한다.","협회는 공제사업 운용실적을 일간신문 또는 협회보에 공시하면 되고, 협회의 인터넷 홈페이지에 게시할 의무는 없다.","공제사업 운영위원회 위원 중 협회 회장과 협회 이사회가 선임한 임원 위원의 수는 전체 위원 수의 3분의 1 이상이어야 한다.","협회가 지회를 설치한 때에는 시·도지사에게 신고하여야 한다."],"a":[1],"L":"중1-12","o":"변형","x":{"한줄":"공제규정은 제정할 때만이 아니라 변경할 때도 국토교통부장관의 승인을 받아야 한다(법 제42조제2항).","근거":[{"법령":"공인중개사법","조문":"제42조 제2항 제4항","원문":"②협회는 제1항에 따른 공제사업을 하고자 하는 때에는 공제규정을 제정하여 국토교통부장관의 승인을 얻어야 한다. 공제규정을 변경하고자 하는 때에도 또한 같다.\n④협회는 공제사업을 다른 회계와 구분하여 별도의 회계로 관리하여야 하며, 책임준비금을 다른 용도로 사용하고자 하는 경우에는 국토교통부장관의 승인을 얻어야 한다."},{"법령":"공인중개사법 시행령","조문":"제34조 제3호","원문":"3. 책임준비금의 적립비율 : 공제사고 발생률 및 공제금 지급액 등을 종합적으로 고려하여 정하되, 공제료 수입액의 100분의 10이상으로 정한다."},{"법령":"공인중개사법 시행령","조문":"제35조","원문":"제35조(공제사업 운용실적의 공시) 협회는 법 제42조제5항에 따라 다음 각 호의 사항을 매 회계연도 종료 후 3개월 이내에 일간신문 또는 협회보에 공시하고 협회의 인터넷 홈페이지에 게시해야 한다.\n1. 결산서인 요약 재무상태표, 손익계산서 및 감사보고서\n2. 공제료 수입액, 공제금 지급액, 책임준비금 적립액\n3. 그 밖에 공제사업의 운용과 관련된 참고사항"},{"법령":"공인중개사법 시행령","조문":"제35조의2 제2항","원문":"② 운영위원회는 성별을 고려하여 다음 각 호의 사람으로 구성한다. 이 경우 제2호 및 제3호에 해당하는 위원의 수는 전체 위원 수의 3분의 1 미만으로 한다.\n1. 국토교통부장관이 소속 공무원 중에서 지명하는 사람 1명\n2. 협회의 회장\n3. 협회 이사회가 협회의 임원 중에서 선임하는 사람\n4. 다음 각 목의 어느 하나에 해당하는 사람으로서 협회의 회장이 추천하여 국토교통부장관의 승인을 받아 위촉하는 사람\n가. 대학 또는 정부출연연구기관에서 부교수 또는 책임연구원 이상으로 재직하고 있거나 재직하였던 사람으로서 부동산 분야 또는 법률ㆍ회계ㆍ금융ㆍ보험 분야를 전공한 사람\n나. 변호사ㆍ공인회계사 또는 공인중개사의 자격이 있는 사람\n다. 금융감독원 또는 금융기관에서 임원 이상의 직에 있거나 있었던 사람\n라. 공제조합 관련 업무에 관한 학식과 경험이 풍부한 사람으로서 해당 업무에 5년 이상 종사한 사람\n마.「소비자기본법」 제29조에 따라 등록한 소비자단체 및 같은 법 제33조에 따른 한국소비자원의 임원으로 재직 중인 사람"},{"법령":"공인중개사법 시행령","조문":"제32조 제2항","원문":"②협회가 그 시ㆍ도회 또는 지회를 설치할 때에는 그 시ㆍ도회는 시ㆍ도지사에게, 지회는 등록관청에 신고하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"공제규정을 제정하려는 때는 물론 변경하려는 때에도 국토교통부장관의 승인을 얻어야 한다(법 제42조제2항)."},{"번호":2,"판정":"틀림","설명":"책임준비금 적립비율의 기준은 공제금 지급액이 아니라 공제료 수입액이다. 공제료 수입액의 100분의 10 이상으로 정한다(시행령 제34조제3호)."},{"번호":3,"판정":"틀림","설명":"매 회계연도 종료 후 3개월 이내에 일간신문 또는 협회보에 공시하고 협회의 인터넷 홈페이지에도 게시해야 한다(시행령 제35조)."},{"번호":4,"판정":"틀림","설명":"협회 회장과 이사회가 선임한 임원 위원은 전체 위원 수의 3분의 1 미만이다(시행령 제35조의2제2항)."},{"번호":5,"판정":"틀림","설명":"시·도회를 설치하면 시·도지사에게, 지회를 설치하면 등록관청에 신고한다(시행령 제32조제2항)."}],"개념":[{"종류":"표","제목":"협회·공제사업 관련 수치와 기한","머리":["항목","내용","근거"],"행":[["책임준비금 적립비율","공제료 수입액의 100분의 10 이상","시행령 제34조제3호"],["운용실적 공시","회계연도 종료 후 3개월 이내, 일간신문·협회보 공시 + 홈페이지 게시","시행령 제35조"],["운영위원회 위원 수","19명 이내","법 제42조의2제2항"],["회장·이사회 선임 위원","전체 위원 수의 3분의 1 미만","시행령 제35조의2제2항"],["선임·위촉 위원 임기","2년, 1회 연임","시행령 제35조의2제3항"],["재무건전성","지급여력비율 100분의 100 이상 유지","시행령 제35조의3제1항"]]},{"종류":"표","제목":"협회에 대한 국토교통부장관·신고 절차","머리":["사항","상대방·절차"],"행":[["정관 제정·변경","국토교통부장관 인가 (법 제41조제2항)"],["총회 의결내용","지체 없이 국토교통부장관에게 보고 (법 제41조의2제3항)"],["시·도회 설치","시·도지사에게 신고 (시행령 제32조제2항)"],["지회 설치","등록관청에 신고 (시행령 제32조제2항)"],["공제규정 제정·변경","국토교통부장관 승인 (법 제42조제2항)"],["책임준비금 다른 용도 사용","국토교통부장관 승인 (법 제42조제4항)"]]}],"함정":"적립비율의 기준은 공제금 지급액이 아니라 공제료 수입액이다. 지회는 등록관청에, 시·도회는 시·도지사에 신고한다. 운용실적은 일간신문·협회보에 공시하고 홈페이지에도 게시한다.","개정":"협회 명칭이 「공인중개사협회」에서 「한국공인중개사협회」로 법정화되었고, 협회 설립 절차를 정하던 법 제41조제3항이 삭제되었다(2026.2.27. 개정). 공제사업 규정은 그대로다."}},{"i":"S3-2-1-중개사법-23","r":"S3","g":2,"c":2,"n":23,"s":"중개사법","q":"공인중개사법령상 중개업무를 수행하는 소속공인중개사의 자격정지 사유에 해당하지 않는 것은?","b":null,"bs":"없음","img":[],"ch":["등록하지 아니한 인장을 거래계약서에 사용한 경우","중개의뢰인과 직접 거래를 한 경우","중개한 거래계약서에 서명 및 날인을 하지 아니한 경우","중개대상물 확인·설명서를 거래당사자에게 교부하지 아니한 경우","거래상 중요사항에 관하여 거짓된 언행으로 중개의뢰인의 판단을 그르치게 한 경우"],"a":[4],"L":"중1-13","o":"변형","x":{"한줄":"확인·설명서의 교부·보존 의무는 개업공인중개사에게 있어, 이를 어기면 개업공인중개사의 업무정지 사유가 된다. 소속공인중개사의 자격정지 사유는 법 제36조제1항의 7가지뿐이다.","근거":[{"법령":"공인중개사법","조문":"제36조 제1항","원문":"①시ㆍ도지사는 공인중개사가 소속공인중개사로서 업무를 수행하는 기간 중에 다음 각 호의 어느 하나에 해당하는 경우에는 6개월의 범위 안에서 기간을 정하여 그 자격을 정지할 수 있다.\n1. 제12조제2항의 규정을 위반하여 둘 이상의 중개사무소에 소속된 경우\n2. 제16조의 규정을 위반하여 인장등록을 하지 아니하거나 등록하지 아니한 인장을 사용한 경우\n3. 제25조제1항의 규정을 위반하여 성실ㆍ정확하게 중개대상물의 확인ㆍ설명을 하지 아니하거나 설명의 근거자료를 제시하지 아니한 경우\n4. 제25조제4항의 규정을 위반하여 중개대상물확인ㆍ설명서에 서명 및 날인을 하지 아니한 경우\n5. 제26조제2항의 규정을 위반하여 거래계약서에 서명 및 날인을 하지 아니한 경우\n6. 제26조제3항의 규정을 위반하여 거래계약서에 거래금액 등 거래내용을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서를 작성한 경우\n7. 제33조제1항 각 호에 규정된 금지행위를 한 경우"},{"법령":"공인중개사법","조문":"제25조 제3항","원문":"③개업공인중개사는 중개가 완성되어 거래계약서를 작성하는 때에는 제1항에 따른 확인ㆍ설명사항을 대통령령으로 정하는 바에 따라 서면으로 작성하여 거래당사자에게 교부하고 대통령령으로 정하는 기간 동안 그 원본, 사본 또는 전자문서를 보존하여야 한다. 다만, 확인ㆍ설명사항이 「전자문서 및 전자거래 기본법」 제2조제9호에 따른 공인전자문서센터(이하 \"공인전자문서센터\"라 한다)에 보관된 경우에는 그러하지 아니하다."},{"법령":"공인중개사법","조문":"제39조 제1항","원문":"①등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 6개월의 범위 안에서 기간을 정하여 업무의 정지를 명할 수 있다. 이 경우 법인인 개업공인중개사에 대하여는 법인 또는 분사무소별로 업무의 정지를 명할 수 있다.\n1. 제10조제2항의 규정을 위반하여 같은 조 제1항제1호부터 제11호까지의 어느 하나에 해당하는 자를 소속공인중개사 또는 중개보조원으로 둔 경우. 다만, 그 사유가 발생한 날부터 2개월 이내에 그 사유를 해소한 경우에는 그러하지 아니하다.\n2. 제16조의 규정을 위반하여 인장등록을 하지 아니하거나 등록하지 아니한 인장을 사용한 경우\n3. 제23조제2항의 규정을 위반하여 국토교통부령으로 정하는 전속중개계약서에 의하지 아니하고 전속중개계약을 체결하거나 계약서를 보존하지 아니한 경우\n4. 제24조제7항의 규정을 위반하여 중개대상물에 관한 정보를 거짓으로 공개하거나 거래정보사업자에게 공개를 의뢰한 중개대상물의 거래가 완성된 사실을 해당 거래정보사업자에게 통보하지 아니한 경우\n5. 삭제<2014.1.28>\n6. 제25조제3항의 규정을 위반하여 중개대상물확인ㆍ설명서를 교부하지 아니하거나 보존하지 아니한 경우\n7. 제25조제4항의 규정을 위반하여 중개대상물확인ㆍ설명서에 서명 및 날인을 하지 아니한 경우\n8. 제26조제1항의 규정을 위반하여 적정하게 거래계약서를 작성ㆍ교부하지 아니하거나 보존하지 아니한 경우\n9. 제26조제2항의 규정을 위반하여 거래계약서에 서명 및 날인을 하지 아니한 경우\n10. 제37조제1항에 따른 보고, 자료의 제출, 조사 또는 검사를 거부ㆍ방해 또는 기피하거나 그 밖의 명령을 이행하지 아니하거나 거짓으로 보고 또는 자료제출을 한 경우\n11. 제38조제2항 각 호의 어느 하나에 해당하는 경우\n12. 최근 1년 이내에 이 법에 의하여 2회 이상 업무정지 또는 과태료의 처분을 받고 다시 과태료의 처분에 해당하는 행위를 한 경우\n13. 개업공인중개사가 조직한 사업자단체 또는 그 구성원인 개업공인중개사가 「독점규제 및 공정거래에 관한 법률」 제51조를 위반하여 같은 법 제52조 또는 제53조에 따른 처분을 받은 경우\n14. 그 밖에 이 법 또는 이 법에 의한 명령이나 처분을 위반한 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"등록하지 아니한 인장의 사용은 제36조제1항제2호 사유이고, 기준은 자격정지 3개월이다(시행규칙 별표 3)."},{"번호":2,"판정":"옳음","설명":"직접 거래는 제33조제1항제6호 금지행위이고, 금지행위는 제36조제1항제7호에 따라 자격정지 6개월이다."},{"번호":3,"판정":"옳음","설명":"거래계약서에 서명 및 날인을 하지 않으면 제36조제1항제5호에 해당하고, 자격정지 3개월이다(법 제26조제2항)."},{"번호":4,"판정":"틀림","설명":"확인·설명서의 교부·보존 위반은 개업공인중개사의 업무정지 사유다(법 제39조제1항제6호). 소속공인중개사가 서명·날인을 하지 않은 경우만 자격정지 사유가 된다(제36조제1항제4호)."},{"번호":5,"판정":"옳음","설명":"거짓된 언행은 제33조제1항제4호 금지행위이므로 제36조제1항제7호에 해당한다."}],"개념":[{"종류":"표","제목":"소속공인중개사 자격정지 사유와 기준 (법 제36조제1항, 시행규칙 별표 3)","머리":["위반행위","근거","기준"],"행":[["둘 이상의 중개사무소에 소속","법 제12조제2항","6개월"],["인장 미등록·미등록 인장 사용","법 제16조","3개월"],["확인·설명 불성실, 근거자료 미제시","법 제25조제1항","3개월"],["확인·설명서 서명 및 날인 누락","법 제25조제4항","3개월"],["거래계약서 서명 및 날인 누락","법 제26조제2항","3개월"],["거래계약서 거짓 기재, 서로 다른 둘 이상의 계약서 작성","법 제26조제3항","6개월"],["금지행위","법 제33조제1항 각 호","6개월"]]},{"종류":"비교","제목":"같은 서류, 다른 책임 주체","왼쪽":{"이름":"소속공인중개사 (자격정지)","항목":["확인·설명서에 서명·날인하지 않은 경우","거래계약서에 서명·날인하지 않은 경우","인장 미등록·미등록 인장 사용","처분권자는 시·도지사, 6개월 범위"]},"오른쪽":{"이름":"개업공인중개사 (업무정지)","항목":["확인·설명서를 교부·보존하지 않은 경우 (제39조제1항제6호)","거래계약서를 작성·교부·보존하지 않은 경우 (제8호)","전속중개계약서를 쓰지 않거나 보존하지 않은 경우 (제3호)","처분권자는 등록관청, 6개월 범위"]}}],"함정":"서명·날인 누락은 소속공인중개사의 자격정지와 개업공인중개사의 업무정지에 모두 걸리지만, 교부·보존 위반은 개업공인중개사에게만 걸린다."}},{"i":"S3-2-1-중개사법-24","r":"S3","g":2,"c":2,"n":24,"s":"중개사법","q":"공인중개사법령상 행정제재처분효과의 승계 등에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["폐업신고 전의 개업공인중개사가 받은 업무정지처분의 효과는 그 처분일부터 6개월간 재등록 개업공인중개사에게 승계된다.","폐업신고 전의 업무정지 사유에 해당하는 위반행위는 폐업기간이 2년이어도 재등록 개업공인중개사에게 업무정지처분을 할 수 있다.","폐업신고 전의 개업공인중개사가 과태료처분을 받은 경우 그 처분의 효과는 그 처분일부터 1년간 재등록 개업공인중개사에게 승계된다.","폐업기간이 4년인 경우에도 폐업신고 전의 등록취소 사유에 해당하는 위반행위를 이유로 재등록 개업공인중개사의 등록을 취소할 수 있다.","개업공인중개사인 법인의 대표자에 대해서는 행정제재처분효과의 승계 규정을 적용하지 않는다."],"a":[3],"L":"중1-13","o":"변형","x":{"한줄":"폐업신고 전 업무정지·과태료 처분의 효과는 처분일부터 1년간 재등록 개업공인중개사에게 승계된다(법 제40조제2항).","근거":[{"법령":"공인중개사법","조문":"제40조 제1항 제2항 제3항 제5항","원문":"①개업공인중개사가 제21조에 따른 폐업신고후 제9조에 따라 다시 중개사무소의 개설등록을 한 때에는 폐업신고 전의 개업공인중개사의 지위를 승계한다.\n②제1항의 경우 폐업신고 전의 개업공인중개사에 대하여 제39조제1항 각 호, 제51조제1항 각 호, 같은 조 제2항 각 호 및 같은 조 제3항 각 호의 위반행위를 사유로 행한 행정처분의 효과는 그 처분일부터 1년간 다시 중개사무소의 개설등록을 한 자(이하 이 조에서 \"재등록 개업공인중개사\"라 한다)에게 승계된다.\n③제1항의 경우 재등록 개업공인중개사에 대하여 폐업신고 전의 제38조제1항 각 호, 같은 조 제2항 각 호 및 제39조제1항 각 호의 위반행위에 대한 행정처분을 할 수 있다. 다만, 다음 각 호의 어느 하나에 해당하는 경우는 제외한다.\n1. 폐업신고를 한 날부터 다시 중개사무소의 개설등록을 한 날까지의 기간(이하 제2호에서 \"폐업기간\"이라 한다)이 3년을 초과한 경우\n2. 폐업신고 전의 위반행위에 대한 행정처분이 업무정지에 해당하는 경우로서 폐업기간이 1년을 초과한 경우\n⑤ 개업공인중개사인 법인의 대표자에 관하여는 제1항부터 제4항까지를 준용한다. 이 경우 \"개업공인중개사\"는 \"법인의 대표자\"로 본다."},{"법령":"공인중개사법","조문":"제39조 제3항","원문":"③제1항의 규정에 따른 업무정지처분은 같은 항 각 호의 어느 하나에 해당하는 사유가 발생한 날부터 3년이 지난 때에는 이를 할 수 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"승계 기간은 6개월이 아니라 처분일부터 1년간이다(법 제40조제2항)."},{"번호":2,"판정":"틀림","설명":"업무정지에 해당하는 위반행위는 폐업기간이 1년을 초과하면 처분할 수 없다. 폐업기간이 2년이면 업무정지처분을 하지 못한다(법 제40조제3항제2호)."},{"번호":3,"판정":"옳음","설명":"제39조제1항 각 호, 제51조 각 항 각 호의 위반행위를 사유로 한 행정처분의 효과는 처분일부터 1년간 재등록 개업공인중개사에게 승계된다. 과태료처분도 여기에 든다(법 제40조제2항)."},{"번호":4,"판정":"틀림","설명":"폐업기간이 3년을 초과하면 폐업신고 전 위반행위에 대한 행정처분을 할 수 없다. 등록취소도 마찬가지다(법 제40조제3항제1호)."},{"번호":5,"판정":"틀림","설명":"개업공인중개사인 법인의 대표자에 관하여도 제1항부터 제4항까지를 준용한다(법 제40조제5항)."}],"개념":[{"종류":"표","제목":"폐업 후 재등록 때의 승계와 처분 (법 제40조)","머리":["구분","내용","항"],"행":[["지위 승계","폐업신고 후 다시 개설등록하면 폐업신고 전 개업공인중개사의 지위를 승계","제1항"],["처분효과 승계","제39조제1항 각 호·제51조 각 항 위반을 사유로 한 처분의 효과가 처분일부터 1년간 승계","제2항"],["종전 위반행위 처분","폐업 전 등록취소·업무정지 사유 위반행위를 재등록자에게 처분할 수 있다","제3항 본문"],["처분 불가 ①","폐업신고일부터 재등록일까지 폐업기간이 3년 초과","제3항제1호"],["처분 불가 ②","업무정지에 해당하는 행위이고 폐업기간이 1년 초과","제3항제2호"],["고려사항","처분 때 폐업기간과 폐업 사유를 고려","제4항"],["법인 대표자","개업공인중개사인 법인의 대표자에게 준용","제5항"]]},{"종류":"비교","제목":"폐업기간에 따른 처분 가능 범위","왼쪽":{"이름":"등록취소 사유 위반행위","항목":["폐업기간 3년 이내: 등록취소 가능","폐업기간 3년 초과: 처분 불가","청문을 거쳐야 한다 (법 제38조제3항)"]},"오른쪽":{"이름":"업무정지 사유 위반행위","항목":["폐업기간 1년 이내: 업무정지 가능","폐업기간 1년 초과: 처분 불가","사유 발생일부터 3년이 지나면 처분 불가 (법 제39조제3항)"]}}],"함정":"승계 기간은 1년이다. 업무정지 사유 위반행위는 폐업기간이 1년을 넘으면, 등록취소 사유를 포함한 모든 위반행위는 폐업기간이 3년을 넘으면 처분하지 못한다. 법인 대표자에게도 준용한다(제5항)."}},{"i":"S3-2-1-중개사법-25","r":"S3","g":2,"c":2,"n":25,"s":"중개사법","q":"공인중개사법령상 공인중개사의 자격정지와 자격취소에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["소속공인중개사의 자격정지는 등록관청이 6개월의 범위 안에서 기간을 정하여 한다.","시·도지사는 소속공인중개사에게 자격정지처분을 하려는 경우 청문을 실시하여야 한다.","이 법을 위반하여 300만원의 벌금형을 선고받아 확정된 공인중개사는 그 자격이 취소된다.","자격이 취소된 자는 취소처분을 받은 날부터 10일 이내에 공인중개사자격증을 반납하여야 한다.","시·도지사는 위반행위의 동기·결과 및 횟수 등을 참작하여 자격정지기간의 2분의 1 범위에서 가중할 수 있으나, 가중하여도 자격정지기간은 6개월을 초과할 수 없다."],"a":[5],"L":"중1-13","o":"변형","x":{"한줄":"자격정지 기간은 위반행위의 동기·결과·횟수를 참작하여 2분의 1 범위에서 가중·감경할 수 있고, 가중해도 6개월을 넘지 못한다(시행규칙 제22조제2항).","근거":[{"법령":"공인중개사법","조문":"제36조 제1항","원문":"①시ㆍ도지사는 공인중개사가 소속공인중개사로서 업무를 수행하는 기간 중에 다음 각 호의 어느 하나에 해당하는 경우에는 6개월의 범위 안에서 기간을 정하여 그 자격을 정지할 수 있다.\n1. 제12조제2항의 규정을 위반하여 둘 이상의 중개사무소에 소속된 경우\n2. 제16조의 규정을 위반하여 인장등록을 하지 아니하거나 등록하지 아니한 인장을 사용한 경우\n3. 제25조제1항의 규정을 위반하여 성실ㆍ정확하게 중개대상물의 확인ㆍ설명을 하지 아니하거나 설명의 근거자료를 제시하지 아니한 경우\n4. 제25조제4항의 규정을 위반하여 중개대상물확인ㆍ설명서에 서명 및 날인을 하지 아니한 경우\n5. 제26조제2항의 규정을 위반하여 거래계약서에 서명 및 날인을 하지 아니한 경우\n6. 제26조제3항의 규정을 위반하여 거래계약서에 거래금액 등 거래내용을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서를 작성한 경우\n7. 제33조제1항 각 호에 규정된 금지행위를 한 경우"},{"법령":"공인중개사법","조문":"제35조 제1항 제2항 제3항","원문":"①시ㆍ도지사는 공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 그 자격을 취소하여야 한다.\n1. 부정한 방법으로 공인중개사의 자격을 취득한 경우\n2. 제7조제1항의 규정을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도 또는 대여한 경우\n3. 제36조에 따른 자격정지처분을 받고 그 자격정지기간 중에 중개업무를 행한 경우(다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 법인인 개업공인중개사의 사원ㆍ임원이 되는 경우를 포함한다)\n4. 이 법 또는 공인중개사의 직무와 관련하여 「형법」 제114조, 제231조, 제234조, 제347조, 제355조 또는 제356조를 위반하여 금고 이상의 형(집행유예를 포함한다)을 선고받은 경우\n②시ㆍ도지사는 제1항에 따라 공인중개사의 자격을 취소하고자 하는 경우에는 청문을 실시하여야 한다.\n③제1항에 따라 공인중개사의 자격이 취소된 자는 국토교통부령으로 정하는 바에 따라 공인중개사자격증을 시ㆍ도지사에게 반납하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제21조","원문":"제21조(공인중개사자격증의 반납) 법 제35조제3항의 규정에 따라 공인중개사자격증을 반납하고자 하는 자는 자격취소처분을 받은 날부터 7일 이내에 그 공인중개사자격증을 교부한 시ㆍ도지사에게 공인중개사자격증을 반납하여야 한다."},{"법령":"공인중개사법 시행규칙","조문":"제22조 제2항","원문":"②시ㆍ도지사는 위반행위의 동기ㆍ결과 및 횟수 등을 참작하여 제1항의 규정에 따른 자격정지기간의 2분의 1의 범위 안에서 가중 또는 감경할 수 있다. 이 경우 가중하여 처분하는 때에도 자격정지기간은 6월을 초과할 수 없다."}],"선지":[{"번호":1,"판정":"틀림","설명":"자격정지는 시·도지사가 한다. 등록관청은 자격정지 사유를 알게 되면 지체 없이 시·도지사에게 통보한다(법 제36조제1항·제2항)."},{"번호":2,"판정":"틀림","설명":"청문을 거치는 처분은 자격취소다(법 제35조제2항). 자격정지에는 청문 규정이 없다."},{"번호":3,"판정":"틀림","설명":"자격취소 사유는 금고 이상의 형(집행유예 포함)을 선고받은 경우다(법 제35조제1항제4호). 벌금형은 액수와 관계없이 자격취소 사유가 아니다."},{"번호":4,"판정":"틀림","설명":"자격증은 자격취소처분을 받은 날부터 7일 이내에 교부한 시·도지사에게 반납한다(시행규칙 제21조)."},{"번호":5,"판정":"옳음","설명":"시행규칙 제22조제2항이 2분의 1 범위의 가중·감경을 허용하고, 가중해도 6개월을 초과할 수 없다고 정한다."}],"개념":[{"종류":"비교","제목":"자격취소와 자격정지","왼쪽":{"이름":"자격취소","항목":["시·도지사가 한다 (기속: ‘취소하여야 한다’)","청문을 실시한다 (법 제35조제2항)","사유 4가지: 부정 취득, 성명 사용·자격증 양도·대여, 정지 기간 중 중개업무, 금고 이상 형 선고","처분일부터 7일 이내 자격증 반납, 분실 등은 사유서 제출"]},"오른쪽":{"이름":"자격정지","항목":["시·도지사가 한다 (재량: ‘정지할 수 있다’)","청문 규정 없음","사유 7가지: 소속공인중개사로 일하는 동안의 위반행위","6개월 범위, 2분의 1 가중·감경, 가중해도 6개월 초과 불가"]}},{"종류":"표","제목":"자격취소 사유 (법 제35조제1항)","머리":["호","사유","비고"],"행":[["1","부정한 방법으로 자격 취득",""],["2","다른 사람에게 자기 성명을 사용하여 중개업무를 하게 하거나 자격증을 양도·대여","법 제7조제1항 위반"],["3","자격정지처분을 받고 정지 기간 중 중개업무","다른 개업공인중개사의 소속공인중개사·중개보조원, 법인의 사원·임원이 되는 경우 포함"],["4","이 법 또는 직무 관련 형법 위반(제114조·제231조·제234조·제347조·제355조·제356조)으로 금고 이상 형 선고","집행유예 포함, 벌금형은 제외"]]}],"함정":"300만원 이상의 벌금형은 개설등록의 결격사유(법 제10조제1항제11호)일 뿐 자격취소 사유가 아니다. 청문은 자격취소와 등록취소에만 있고, 자격정지·업무정지에는 없다."}},{"i":"S3-2-1-중개사법-26","r":"S3","g":2,"c":2,"n":26,"s":"중개사법","q":"공인중개사법령상 등록관청이 인지하였다면 공인중개사인 개업공인중개사 甲의 중개사무소 개설등록을 반드시 취소하여야 하는 경우에 해당하지 않는 것은?","b":null,"bs":"없음","img":[],"ch":["甲이 사망한 경우","甲이 업무정지기간 중에 중개업무를 한 경우","甲이 하나의 거래에 대하여 서로 다른 2 이상의 거래계약서를 작성한 경우","甲이 개업공인중개사와 소속공인중개사를 합한 수의 5배를 초과하여 중개보조원을 고용한 경우","甲이 다른 개업공인중개사의 중개보조원이 된 경우"],"a":[3],"L":"중1-13","o":"변형","x":{"한줄":"거래계약서 거짓 기재와 이중 계약서 작성은 임의적 등록취소 사유다(법 제38조제2항제7호). 반드시 취소해야 하는 사유는 제1항에 열거된 것뿐이다.","근거":[{"법령":"공인중개사법","조문":"제38조 제1항","원문":"①등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 중개사무소의 개설등록을 취소하여야 한다.\n1. 개인인 개업공인중개사가 사망하거나 개업공인중개사인 법인이 해산한 경우\n2. 거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 경우\n3. 제10조제1항제2호부터 제6호까지 또는 같은 항 제11호ㆍ제12호에 따른 결격사유에 해당하게 된 경우. 다만, 같은 항 제12호에 따른 결격사유에 해당하는 경우로서 그 사유가 발생한 날부터 2개월 이내에 그 사유를 해소한 경우에는 그러하지 아니하다.\n4. 제12조제1항의 규정을 위반하여 이중으로 중개사무소의 개설등록을 한 경우\n5. 제12조제2항의 규정을 위반하여 다른 개업공인중개사의 소속공인중개사ㆍ중개보조원 또는 개업공인중개사인 법인의 사원ㆍ임원이 된 경우\n5의2. 제15조제3항을 위반하여 중개보조원을 고용한 경우\n6. 제19조제1항의 규정을 위반하여 다른 사람에게 자기의 성명 또는 상호를 사용하여 중개업무를 하게 하거나 중개사무소등록증을 양도 또는 대여한 경우\n7. 업무정지기간 중에 중개업무를 하거나 자격정지처분을 받은 소속공인중개사로 하여금 자격정지기간 중에 중개업무를 하게 한 경우\n8. 최근 1년 이내에 이 법에 의하여 2회 이상 업무정지처분을 받고 다시 업무정지처분에 해당하는 행위를 한 경우"},{"법령":"공인중개사법","조문":"제38조 제2항","원문":"②등록관청은 개업공인중개사가 다음 각 호의 어느 하나에 해당하는 경우에는 중개사무소의 개설등록을 취소할 수 있다.\n1. 제9조제3항에 따른 등록기준에 미달하게 된 경우\n2. 제13조제1항의 규정을 위반하여 둘 이상의 중개사무소를 둔 경우\n3. 제13조제2항의 규정을 위반하여 임시 중개시설물을 설치한 경우\n4. 제14조제1항의 규정을 위반하여 겸업을 한 경우\n5. 제21조제2항의 규정을 위반하여 계속하여 6개월을 초과하여 휴업한 경우\n6. 제23조제3항의 규정을 위반하여 중개대상물에 관한 정보를 공개하지 아니하거나 중개의뢰인의 비공개요청에도 불구하고 정보를 공개한 경우\n7. 제26조제3항의 규정을 위반하여 거래계약서에 거래금액 등 거래내용을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서를 작성한 경우\n8. 제30조제3항에 따른 손해배상책임을 보장하기 위한 조치를 이행하지 아니하고 업무를 개시한 경우\n9. 제33조제1항 각 호에 규정된 금지행위를 한 경우\n10. 최근 1년 이내에 이 법에 의하여 3회 이상 업무정지 또는 과태료의 처분을 받고 다시 업무정지 또는 과태료의 처분에 해당하는 행위를 한 경우(제1항제8호에 해당하는 경우는 제외한다)\n11. 개업공인중개사가 조직한 사업자단체(「독점규제 및 공정거래에 관한 법률」 제2조제2호의 사업자단체를 말한다. 이하 같다) 또는 그 구성원인 개업공인중개사가 「독점규제 및 공정거래에 관한 법률」 제51조를 위반하여 같은 법 제52조 또는 제53조에 따른 처분을 최근 2년 이내에 2회 이상 받은 경우"},{"법령":"공인중개사법","조문":"제15조 제3항","원문":"③ 개업공인중개사가 고용할 수 있는 중개보조원의 수는 개업공인중개사와 소속공인중개사를 합한 수의 5배를 초과하여서는 아니 된다."}],"선지":[{"번호":1,"판정":"옳음","설명":"개인인 개업공인중개사의 사망은 제38조제1항제1호의 필수 취소 사유다. 이 경우 청문은 하지 않는다."},{"번호":2,"판정":"옳음","설명":"업무정지기간 중 중개업무는 제38조제1항제7호의 필수 취소 사유다."},{"번호":3,"판정":"틀림","설명":"서로 다른 둘 이상의 거래계약서 작성은 제38조제2항제7호에 따라 등록을 취소할 수 있는 사유다. 반드시 취소하는 사유가 아니며, 업무정지 사유(제39조제1항제11호)도 된다."},{"번호":4,"판정":"옳음","설명":"중개보조원 수 초과 고용은 제38조제1항제5호의2의 필수 취소 사유다(법 제15조제3항)."},{"번호":5,"판정":"옳음","설명":"다른 개업공인중개사의 소속공인중개사·중개보조원이 된 것은 제12조제2항 위반이고, 제38조제1항제5호의 필수 취소 사유다."}],"개념":[{"종류":"표","제목":"필수적 등록취소 사유 (법 제38조제1항)","머리":["호","사유"],"행":[["1","개인인 개업공인중개사 사망, 법인 해산"],["2","거짓이나 그 밖의 부정한 방법으로 개설등록"],["3","결격사유에 해당하게 된 경우 (제10조제1항제2호~제6호, 제11호·제12호). 제12호(법인의 사원·임원)는 2개월 내 해소하면 제외"],["4","이중 개설등록"],["5","다른 개업공인중개사의 소속공인중개사·중개보조원 또는 법인의 사원·임원이 된 경우"],["5의2","중개보조원 수 초과 고용 (개업공인중개사 + 소속공인중개사 합산 수의 5배 초과)"],["6","다른 사람에게 성명·상호를 사용하여 중개업무를 하게 하거나 등록증을 양도·대여"],["7","업무정지기간 중 중개업무, 자격정지 중인 소속공인중개사에게 중개업무를 하게 한 경우"],["8","최근 1년 이내 업무정지 2회 이상을 받고 다시 업무정지 사유에 해당하는 행위"]]},{"종류":"표","제목":"임의적 등록취소 사유 (법 제38조제2항)","머리":["호","사유"],"행":[["1","등록기준(제9조제3항)에 미달하게 된 경우"],["2","둘 이상의 중개사무소를 둔 경우"],["3","임시 중개시설물을 설치한 경우"],["4","겸업 제한 위반"],["5","계속하여 6개월을 초과하여 휴업"],["6","중개대상물 정보를 공개하지 않거나 비공개 요청에도 공개한 경우"],["7","거래계약서에 거래금액 등을 거짓으로 기재하거나 서로 다른 둘 이상의 거래계약서를 작성"],["8","손해배상책임 보장 조치를 하지 않고 업무를 개시"],["9","제33조제1항의 금지행위"],["10","최근 1년 이내 업무정지 또는 과태료 3회 이상을 받고 다시 업무정지 또는 과태료 사유에 해당하는 행위 (제1항제8호에 해당하는 경우 제외)"],["11","사업자단체가 독점규제법에 따른 처분을 최근 2년 이내 2회 이상 받은 경우"]]}],"함정":"거래계약서 거짓 기재는 소속공인중개사의 자격정지, 개업공인중개사의 업무정지, 임의적 등록취소 사유에 모두 걸리지만 필수 취소 사유는 아니다. 업무정지 2회 이상은 필수 취소(제1항제8호), 업무정지 또는 과태료 3회 이상은 임의적 취소(제2항제10호)다."}},{"i":"S3-2-1-중개사법-27","r":"S3","g":2,"c":2,"n":27,"s":"중개사법","q":"다음 중 공인중개사법령상 과태료를 부과할 경우 과태료의 부과기준에서 정하는 과태료 금액이 가장 큰 경우는?","b":null,"bs":"없음","img":[],"ch":["중개사무소등록증을 게시하지 않은 경우","휴업한 중개업의 재개 신고를 하지 않은 경우","중개사무소의 이전신고를 하지 않은 경우","공제사업 운용실적을 공시하지 않은 경우","중개사무소의 명칭에 ‘공인중개사사무소’라는 문자를 사용하지 않은 경우"],"a":[4],"L":"중1-14","o":"변형","x":{"한줄":"공제사업 운용실적 미공시는 300만원이다. 나머지 네 가지는 20만~50만원이다(시행령 별표 2).","근거":[{"법령":"공인중개사법","조문":"제51조 제2항 제7호","원문":"7. 제42조제5항을 위반하여 공제사업 운용실적을 공시하지 아니한 자"},{"법령":"공인중개사법","조문":"제51조 제3항","원문":"③ 다음 각 호의 어느 하나에 해당하는 자에게는 100만원 이하의 과태료를 부과한다.\n1. 제17조를 위반하여 중개사무소등록증 등을 게시하지 아니한 자\n2. 제18조제1항 또는 제3항을 위반하여 사무소의 명칭에 \"공인중개사사무소\", \"부동산중개\"라는 문자를 사용하지 아니한 자 또는 옥외 광고물에 성명을 표기하지 아니하거나 거짓으로 표기한 자\n3. 제20조제1항을 위반하여 중개사무소의 이전신고를 하지 아니한 자\n4. 제21조제1항을 위반하여 휴업, 폐업, 휴업한 중개업의 재개 또는 휴업기간의 변경 신고를 하지 아니한 자"},{"법령":"공인중개사법 시행령","조문":"별표 2 제2호 자목","원문":"자. 법 제42조제5항을 위반하여 공제사업 운용실적을 공시하지 않은 경우 / 법 제51조제2항제7호 / 300만원"}],"선지":[{"번호":1,"판정":"-","설명":"30만원이다. 법 제51조제3항제1호, 시행령 별표 2 제2호 파목."},{"번호":2,"판정":"-","설명":"20만원이다. 휴업, 폐업, 재개, 휴업기간 변경 신고 누락은 모두 20만원이다(별표 2 제2호 더목)."},{"번호":3,"판정":"-","설명":"30만원이다(별표 2 제2호 너목)."},{"번호":4,"판정":"-","설명":"300만원이다. 이 선지가 가장 크다(별표 2 제2호 자목)."},{"번호":5,"판정":"-","설명":"50만원이다(별표 2 제2호 하목)."}],"개념":[{"종류":"표","제목":"과태료 부과기준 금액 (시행령 별표 2)","머리":["위반행위","금액","상한 구분"],"행":[["존재하지 않는 중개대상물의 표시·광고","500만원","500만원 이하"],["중개보조원이라는 사실을 알리지 않은 경우, 확인·설명 불성실과 근거자료 미제시를 모두 한 경우","500만원","500만원 이하"],["공제업무 개선명령 불이행, 임원 징계·해임 요구 불이행","400만원","500만원 이하"],["공제사업 운용실적 미공시","300만원","500만원 이하"],["장관의 보고·검사 거부 (거래정보사업자·협회)","200만원","500만원 이하"],["연수교육 미이수","위반 1개월 이내 20만원 · 3개월 이내 30만원 · 6개월 이내 50만원 · 6개월 초과 100만원","500만원 이하"],["등록증 미반납, 명칭 문자 미사용, 표시·광고 명시사항 누락","50만원","100만원 이하"],["등록증 미게시, 이전신고 누락, 손해배상 미설명, 자격증 미반납","30만원","100만원 이하"],["휴업·폐업·재개·휴업기간 변경 신고 누락","20만원","100만원 이하"]]},{"종류":"표","제목":"과태료 부과권자 (법 제51조제5항)","머리":["부과권자","대상"],"행":[["국토교통부장관","제2항제1호의2·제1호의3·제1호의5, 제6호부터 제8호까지, 제8호의2, 제9호 (정보통신서비스 제공자·거래정보사업자·협회)"],["시·도지사","연수교육 미이수 (제2항제5호의2), 자격증 미반납 (제3항제6호)"],["등록관청","제2항제1호·제1호의4·제1호의6, 제3항제1호·제2호·제2호의2·제3호~제5호·제7호"]]}],"함정":"공제사업 관련 과태료(개선명령 400만원, 미공시 300만원)는 신고 누락류(20만~30만원)보다 훨씬 크다. 연수교육 미이수는 위반 기간이 길수록 금액이 커지며 최고 100만원이다."}},{"i":"S3-2-1-중개사법-28","r":"S3","g":2,"c":2,"n":28,"s":"중개사법","q":"공인중개사법령상 3년 이하의 징역 또는 3천만원 이하의 벌금에 처해지는 개업공인중개사등의 행위가 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["관계 법령에서 양도가 금지된 부동산의 분양과 관련 있는 증서의 매매를 중개하는 행위","법정 중개보수를 초과하여 수수하는 행위","중개의뢰인과 직접 거래를 하는 행위","거래당사자 쌍방을 대리하는 행위","단체를 구성하여 특정 중개대상물에 대하여 중개를 제한하는 행위"],"a":[2],"L":"중1-14","o":"기출","x":{"한줄":"법정 중개보수 초과 수수는 제33조제1항제3호 금지행위로, 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제49조제1항제10호).","근거":[{"법령":"공인중개사법","조문":"제48조","원문":"제48조(벌칙) 다음 각 호의 어느 하나에 해당하는 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.\n1. 제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 한 자\n2. 거짓이나 그 밖의 부정한 방법으로 중개사무소의 개설등록을 한 자\n3. 제33조제1항제5호부터 제9호까지의 규정을 위반한 자\n4. 제33조제2항 각 호의 규정을 위반한 자"},{"법령":"공인중개사법","조문":"제49조 제1항","원문":"①다음 각 호의 어느 하나에 해당하는 자는 1년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.\n1. 제7조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명을 사용하여 중개업무를 하게 하거나 공인중개사자격증을 양도ㆍ대여한 자 또는 다른 사람의 공인중개사자격증을 양수ㆍ대여받은 자\n1의2. 제7조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자\n2. 제8조의 규정을 위반하여 공인중개사가 아닌 자로서 공인중개사 또는 이와 유사한 명칭을 사용한 자\n3. 제12조의 규정을 위반하여 이중으로 중개사무소의 개설등록을 하거나 둘 이상의 중개사무소에 소속된 자\n4. 제13조제1항의 규정을 위반하여 둘 이상의 중개사무소를 둔 자\n5. 제13조제2항의 규정을 위반하여 임시 중개시설물을 설치한 자\n5의2. 제15조제3항을 위반하여 중개보조원을 고용한 자\n6. 제18조제2항의 규정을 위반하여 개업공인중개사가 아닌 자로서 \"공인중개사사무소\", \"부동산중개\" 또는 이와 유사한 명칭을 사용한 자\n6의2. 제18조의2제3항을 위반하여 개업공인중개사가 아닌 자로서 중개업을  하기 위하여 중개대상물에 대한 표시ㆍ광고를 한 자\n7. 제19조제1항 또는 제2항을 위반하여 다른 사람에게 자기의 성명 또는 상호를 사용하여 중개업무를 하게 하거나 중개사무소등록증을 다른 사람에게 양도ㆍ대여한 자 또는 다른 사람의 성명ㆍ상호를 사용하여 중개업무를 하거나 중개사무소등록증을 양수ㆍ대여받은 자\n7의2. 제19조제3항을 위반하여 같은 조 제1항 및 제2항에서 금지한 행위를 알선한 자\n8. 제24조제4항의 규정을 위반하여 정보를 공개한 자\n9. 제29조제2항의 규정을 위반하여 업무상 비밀을 누설한 자\n10. 제33조제1항제1호부터 제4호까지의 규정을 위반한 자"},{"법령":"공인중개사법","조문":"제33조 제1항","원문":"① 개업공인중개사등은 다음 각 호의 행위를 하여서는 아니된다.\n1. 제3조에 따른 중개대상물의 매매를 업으로 하는 행위\n2. 제9조에 따른 중개사무소의 개설등록을 하지 아니하고 중개업을 영위하는 자인 사실을 알면서 그를 통하여 중개를 의뢰받거나 그에게 자기의 명의를 이용하게 하는 행위\n3. 사례ㆍ증여 그 밖의 어떠한 명목으로도 제32조에 따른 보수 또는 실비를 초과하여 금품을 받는 행위\n4. 해당 중개대상물의 거래상의 중요사항에 관하여 거짓된 언행 그 밖의 방법으로 중개의뢰인의 판단을 그르치게 하는 행위\n5. 관계 법령에서 양도ㆍ알선 등이 금지된 부동산의 분양ㆍ임대 등과 관련 있는 증서 등의 매매ㆍ교환 등을 중개하거나 그 매매를 업으로 하는 행위\n6. 중개의뢰인과 직접 거래를 하거나 거래당사자 쌍방을 대리하는 행위\n7. 탈세 등 관계 법령을 위반할 목적으로 소유권보존등기 또는 이전등기를 하지 아니한 부동산이나 관계 법령의 규정에 의하여 전매 등 권리의 변동이 제한된 부동산의 매매를 중개하는 등 부동산투기를 조장하는 행위\n8. 부당한 이익을 얻거나 제3자에게 부당한 이익을 얻게 할 목적으로 거짓으로 거래가 완료된 것처럼 꾸미는 등 중개대상물의 시세에 부당한 영향을 주거나 줄 우려가 있는 행위\n9. 단체를 구성하여 특정 중개대상물에 대하여 중개를 제한하거나 단체 구성원 이외의 자와 공동중개를 제한하는 행위"}],"선지":[{"번호":1,"판정":"옳음","설명":"양도·알선이 금지된 분양·임대 관련 증서의 매매·교환 중개는 제33조제1항제5호이고, 3년 이하의 징역 또는 3천만원 이하의 벌금이다(법 제48조제3호)."},{"번호":2,"판정":"틀림","설명":"제33조제1항제3호 위반이므로 1년 이하의 징역 또는 1천만원 이하의 벌금이다(법 제49조제1항제10호)."},{"번호":3,"판정":"옳음","설명":"직접 거래는 제33조제1항제6호이고 3년 이하의 징역 또는 3천만원 이하의 벌금이다(법 제48조제3호)."},{"번호":4,"판정":"옳음","설명":"거래당사자 쌍방 대리도 제33조제1항제6호다. 같은 벌칙을 받는다."},{"번호":5,"판정":"옳음","설명":"단체를 구성하여 특정 중개대상물의 중개를 제한하는 행위는 제33조제1항제9호이고 3년 이하의 징역 또는 3천만원 이하의 벌금이다."}],"개념":[{"종류":"비교","제목":"금지행위의 형량 경계 (법 제33조제1항)","왼쪽":{"이름":"1년 이하 징역·1천만원 이하 벌금 (제49조제1항제10호)","항목":["제1호: 중개대상물 매매업","제2호: 무등록 중개업자와 거래하거나 명의를 이용하게 하는 행위","제3호: 보수·실비를 초과하는 금품 수수","제4호: 거래상 중요사항에 관한 거짓된 언행"]},"오른쪽":{"이름":"3년 이하 징역·3천만원 이하 벌금 (제48조제3호)","항목":["제5호: 양도·알선이 금지된 증서 등의 매매·중개, 그 매매업","제6호: 직접 거래, 쌍방 대리","제7호: 미등기 전매 등 투기 조장","제8호: 거짓 거래완료 등 시세 부당 영향","제9호: 단체 구성으로 중개·공동중개 제한"]}},{"종류":"표","제목":"징역·벌금 대상 비교","머리":["벌칙","대상 행위"],"행":[["3년 이하 · 3천만원 이하 (제48조)","무등록 중개업, 거짓·부정 개설등록, 제33조제1항제5호~제9호, 제33조제2항(업무방해)"],["1년 이하 · 1천만원 이하 (제49조제1항)","자격증·등록증 양도·대여와 알선, 유사명칭, 이중등록·이중소속, 둘 이상의 중개사무소, 임시 중개시설물, 중개보조원 수 초과, 개업공인중개사 아닌 자의 명칭·표시·광고, 정보 부당 공개, 비밀 누설, 제33조제1항제1호~제4호"],["양벌규정 (제50조)","소속공인중개사·중개보조원·법인 사원·임원이 중개업무에 관해 위반하면 행위자를 벌하는 외에 개업공인중개사에게도 벌금형. 상당한 주의·감독을 다했으면 제외"]]}],"함정":"금지행위 9가지 중 앞의 4가지(제1호~제4호)는 1년·1천만원, 뒤의 5가지(제5호~제9호)는 3년·3천만원으로 갈린다. 초과 수수는 앞쪽에 속한다."}},{"i":"S3-2-1-중개사법-29","r":"S3","g":2,"c":2,"n":29,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 부동산 거래신고에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["거래당사자 중 일방이 지방공사인 경우에는 상대방이 개인이어도 지방공사가 신고하여야 한다.","공동으로 중개한 개업공인중개사 중 일방이 신고를 거부한 경우 다른 개업공인중개사는 단독으로 신고할 수 있다.","신고관청은 신고를 받은 경우 부동산거래가격 검증체계를 활용하여 신고가격의 적정성을 검증하고, 그 결과를 관할 세무관서의 장에게 통보하여야 한다.","신고관청은 신고 내용의 사실 여부를 확인하기 위하여 거래당사자 또는 개업공인중개사에게 거래계약서와 거래대금 지급을 증명할 수 있는 자료의 제출을 요구할 수 있다.","개업공인중개사가 거래계약서를 작성·교부한 경우에도 거래당사자는 직접 신고할지 개업공인중개사에게 신고를 맡길지 선택할 수 있다."],"a":[5],"L":"중2-1","o":"변형","x":{"한줄":"개업공인중개사가 거래계약서를 작성·교부했다면 거래당사자의 선택과 관계없이 그 개업공인중개사가 신고하여야 한다(법 제3조제3항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제3조 제1항 제3항 제4항","원문":"① 거래당사자는 다음 각 호의 어느 하나에 해당하는 계약을 체결한 경우 그 실제 거래가격 등 대통령령으로 정하는 사항을 거래계약의 체결일부터 30일 이내에 그 권리의 대상인 부동산등(권리에 관한 계약의 경우에는 그 권리의 대상인 부동산을 말한다)의 소재지를 관할하는 시장(구가 설치되지 아니한 시의 시장 및 특별자치시장과 특별자치도 행정시의 시장을 말한다)ㆍ군수 또는 구청장(이하 \"신고관청\"이라 한다)에게 공동으로 신고하여야 한다. 다만, 거래당사자 중 일방이 국가, 지방자치단체, 대통령령으로 정하는 자의 경우(이하 \"국가등\"이라 한다)에는 국가등이 신고를 하여야 한다.\n1. 부동산의 매매계약\n2. 「택지개발촉진법」, 「주택법」 등 대통령령으로 정하는 법률에 따른 부동산에 대한 공급계약\n3. 다음 각 목의 어느 하나에 해당하는 지위의 매매계약\n가. 제2호에 따른 계약을 통하여 부동산을 공급받는 자로 선정된 지위\n나. 「도시 및 주거환경정비법」 제74조에 따른 관리처분계획의 인가 및 「빈집 및 소규모주택 정비에 관한 특례법」 제29조에 따른 사업시행계획인가로 취득한 입주자로 선정된 지위\n③ 「공인중개사법」 제2조제4호에 따른 개업공인중개사(이하 \"개업공인중개사\"라 한다)가 같은 법 제26조제1항에 따라 거래계약서를 작성ㆍ교부한 경우에는 제1항에도 불구하고 해당 개업공인중개사가 같은 항에 따른 신고를 하여야 한다. 이 경우 공동으로 중개를 한 경우에는 해당 개업공인중개사가 공동으로 신고하여야 한다.\n④ 제3항에도 불구하고 개업공인중개사 중 일방이 신고를 거부한 경우에는 제2항을 준용한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제3조 제2항","원문":"② 법 제3조제1항 각 호 외의 부분 단서에서 \"대통령령으로 정하는 자\"란 다음 각 호의 기관을 말한다.\n1. 「공공기관의 운영에 관한 법률」에 따른 공공기관\n2. 「지방공기업법」에 따른 지방직영기업ㆍ지방공사 또는 지방공단"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제5조 제2항 제3항","원문":"② 신고관청은 제3조에 따른 신고를 받은 경우 제1항에 따른 부동산거래가격 검증체계를 활용하여 그 적정성을 검증하여야 한다.\n③ 신고관청은 제2항에 따른 검증 결과를 해당 부동산의 소재지를 관할하는 세무관서의 장에게 통보하여야 하며, 통보받은 세무관서의 장은 해당 신고 내용을 국세 또는 지방세 부과를 위한 과세자료로 활용할 수 있다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제6조 제1항","원문":"① 신고관청은 제3조, 제3조의2 또는 제8조에 따라 신고 받은 내용이 누락되어 있거나 정확하지 아니하다고 판단하는 경우에는 국토교통부령으로 정하는 바에 따라 신고인에게 신고 내용을 보완하게 하거나 신고한 내용의 사실 여부를 확인하기 위하여 소속 공무원으로 하여금 거래당사자 또는 개업공인중개사에게 거래계약서, 거래대금 지급을 증명할 수 있는 자료 등 관련 자료의 제출을 요구하는 등 필요한 조치를 취할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"당사자 일방이 국가·지방자치단체·공공기관·지방직영기업·지방공사·지방공단이면 그 국가등이 신고한다(법 제3조제1항 단서, 시행령 제3조제2항)."},{"번호":2,"판정":"옳음","설명":"공동중개면 개업공인중개사가 공동으로 신고하고, 일방이 거부하면 단독 신고 규정(제2항)을 준용한다(법 제3조제3항 후단·제4항)."},{"번호":3,"판정":"옳음","설명":"신고관청은 검증체계로 신고가격의 적정성을 검증하고 결과를 세무관서의 장에게 통보한다(법 제5조제2항·제3항)."},{"번호":4,"판정":"옳음","설명":"신고 내용이 누락되었거나 정확하지 않다고 판단하면 신고관청이 소속 공무원으로 하여금 거래계약서, 대금 지급 증빙 등의 제출을 요구하게 할 수 있다(법 제6조제1항)."},{"번호":5,"판정":"틀림","설명":"개업공인중개사가 거래계약서를 작성·교부했다면 제1항의 공동신고 대신 그 개업공인중개사가 신고하여야 한다. 선택 사항이 아니다(법 제3조제3항)."}],"개념":[{"종류":"표","제목":"거래신고의 주체","머리":["상황","신고 방법","근거"],"행":[["당사자 간 직거래","거래당사자 공동 신고","법 제3조제1항"],["일방이 신고 거부","다른 당사자가 단독 신고","법 제3조제2항"],["일방이 국가등","국가등이 신고","법 제3조제1항 단서"],["개업공인중개사가 거래계약서 작성·교부","해당 개업공인중개사가 신고 (의무)","법 제3조제3항"],["공동중개","개업공인중개사가 공동 신고, 일방 거부 시 다른 쪽이 단독 신고","법 제3조제3항·제4항"],["해제·무효·취소 확정","거래당사자가 확정일부터 30일 이내 공동 신고. 개업공인중개사가 거래를 신고했으면 그 개업공인중개사도 신고 가능","법 제3조의2"]]},{"종류":"흐름","제목":"신고에서 검증·조사까지","단계":[{"이름":"계약 체결","설명":"부동산 매매계약, 공급계약, 분양권·입주권 매매계약."},{"이름":"신고","설명":"계약 체결일부터 30일 이내에 소재지 관할 신고관청(시장·군수·구청장)에 신고한다."},{"이름":"신고필증 발급","설명":"신고관청이 지체 없이 발급한다. 발급 때 매수인은 검인을 받은 것으로 본다."},{"이름":"가격 검증","설명":"신고관청이 검증체계로 적정성을 검증하고 결과를 세무관서의 장에게 통보한다."},{"이름":"조사·조치","설명":"보완 요구, 거래계약서·대금 지급 증빙 제출 요구. 과태료 부과 또는 수사기관 고발."}]}],"함정":"개업공인중개사의 신고는 당사자와 나누어 고르는 방식이 아니라 의무다. 소속공인중개사·중개보조원에게는 신고의무가 없고, 개업공인중개사가 위임하면 소속공인중개사가 제출만 대행할 수 있다."}},{"i":"S3-2-1-중개사법-30","r":"S3","g":2,"c":2,"n":30,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 부동산거래신고에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["거래당사자 또는 개업공인중개사는 부동산 거래계약 신고 내용 중 거래 지분 비율이 잘못 기재된 경우 신고관청에 신고 내용의 정정을 신청할 수 있다.","자연인 甲이 단독으로 ｢주택법｣상 투기과열지구 외에 소재하는 주택을 실제 거래가격 6억원으로 매수한 경우 입주 예정 시기 등 그 주택의 이용계획은 신고사항이다.","법인이 주택의 매수자로서 거래계약을 체결한 경우 임대 등 그 주택의 이용계획은 신고사항이다.","부동산의 매수인은 신고인이 부동산거래계약 신고필증을 발급받은 때에 ｢부동산등기 특별조치법｣에 따른 검인을 받은 것으로 본다.","개업공인중개사가 신고한 후 해당 거래계약이 해제된 경우 그 계약을 해제한 거래당사자는 해제가 확정된 날부터 30일 이내에 해당 신고관청에 단독으로 신고하여야 한다."],"a":[5],"L":"중2-1","o":"기출","x":{"한줄":"해제등 신고는 거래당사자가 공동으로 하는 것이 원칙이다. 단독 신고는 일방이 신고를 거부하는 경우에만 할 수 있다(법 제3조의2제1항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제3조의2 제1항 제2항","원문":"① 거래당사자는 제3조에 따라 신고한 후 해당 거래계약이 해제, 무효 또는 취소(이하 \"해제등\"이라 한다)된 경우 해제등이 확정된 날부터 30일 이내에 해당 신고관청에 공동으로 신고하여야 한다. 다만, 거래당사자 중 일방이 신고를 거부하는 경우에는 국토교통부령으로 정하는 바에 따라 단독으로 신고할 수 있다.\n② 개업공인중개사가 제3조제3항에 따라 신고를 한 경우에는 제1항에도 불구하고 개업공인중개사가 같은 항에 따른 신고(공동으로 중개를 한 경우에는 해당 개업공인중개사가 공동으로 신고하는 것을 말한다)를 할 수 있다. 다만, 개업공인중개사 중 일방이 신고를 거부한 경우에는 제1항 단서를 준용한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행규칙","조문":"제3조 제1항","원문":"① 거래당사자 또는 개업공인중개사는 부동산 거래계약 신고 내용 중 다음 각 호의 어느 하나에 해당하는 사항이 잘못 기재된 경우에는 신고관청에 신고 내용의 정정을 신청할 수 있다.\n1. 거래당사자의 주소ㆍ전화번호 또는 휴대전화번호\n2. 거래 지분 비율\n3. 개업공인중개사의 전화번호ㆍ상호 또는 사무소 소재지\n4. 거래대상 건축물의 종류\n5. 거래대상 부동산등(부동산을 취득할 수 있는 권리에 관한 계약의 경우에는 그 권리의 대상인 부동산을 말한다. 이하 같다)의 지목, 면적, 거래 지분 및 대지권비율"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제3조 제6항","원문":"⑥ 부동산등의 매수인은 신고인이 제5항에 따른 신고필증을 발급받은 때에 「부동산등기 특별조치법」 제3조제1항에 따른 검인을 받은 것으로 본다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"별표 1 제2호 나목·제3호","원문":"2. 법인이 주택의 거래계약을 체결하는 경우 / 나. 주택 취득 목적 및 취득 자금 등에 관한 다음의 사항(법인이 주택의 매수자인 경우만 해당한다) 1) 거래대상인 주택의 취득목적 2) 거래대상 주택의 취득에 필요한 자금의 조달계획 및 지급방식 3) 임대 등 거래대상 주택의 이용계획\n3. 법인 외의 자가 실제 거래가격이 6억원 이상인 주택을 매수하거나 투기과열지구 또는 조정대상지역에 소재하는 주택을 매수하는 경우(매수인 중 국가등이 포함되어 있는 경우는 제외한다) / 가. 거래대상 주택의 취득에 필요한 자금의 조달계획 및 지급방식 나. 거래대상 주택에 매수자 본인이 입주할지 여부, 입주 예정 시기 등 거래대상 주택의 이용계획"}],"선지":[{"번호":1,"판정":"옳음","설명":"거래 지분 비율이 잘못 기재되면 거래당사자 또는 개업공인중개사가 정정을 신청할 수 있다(시행규칙 제3조제1항제2호)."},{"번호":2,"판정":"옳음","설명":"법인 외의 자가 실제 거래가격 6억원 이상 주택을 사면 투기과열지구가 아니어도 자금조달계획과 입주 여부·시기 등 이용계획을 신고한다(시행령 별표 1 제3호)."},{"번호":3,"판정":"옳음","설명":"법인이 주택의 매수자이면 취득목적, 자금조달계획·지급방식, 임대 등 이용계획을 신고한다(시행령 별표 1 제2호 나목)."},{"번호":4,"판정":"옳음","설명":"신고인이 신고필증을 발급받은 때에 매수인이 검인을 받은 것으로 본다(법 제3조제6항). 신고서를 낸 때가 아니다."},{"번호":5,"판정":"틀림","설명":"해제등 신고는 거래당사자가 해제등이 확정된 날부터 30일 이내에 공동으로 한다. 개업공인중개사가 거래를 신고했다면 그 개업공인중개사가 해제등 신고를 할 수도 있다. 단독 신고는 일방이 거부하는 경우다(법 제3조의2제1항·제2항)."}],"개념":[{"종류":"표","제목":"신고 후 정정·변경·해제 (시행규칙 제3조, 법 제3조의2)","머리":["구분","대상","방법"],"행":[["정정 신청","거래당사자 주소·전화번호, 거래 지분 비율, 개업공인중개사의 전화번호·상호·소재지, 건축물 종류, 지목·면적·지분·대지권비율","신고필증에 정정 사항을 표시하고 서명·날인. 주소·전화번호는 당사자 일방이 단독으로 가능"],["변경 신고","거래 지분 비율·지분, 면적, 계약 조건·기한, 거래가격, 중도금·잔금과 지급일, 일부 매수인·일부 부동산 제외 등","부동산등기 신청 전에 신고"],["해제등 신고","신고한 계약이 해제·무효·취소된 경우","확정일부터 30일 이내 공동 신고. 일방 거부 시 단독. 개업공인중개사가 신고했으면 개업공인중개사 신고 가능"]]},{"종류":"표","제목":"주택 거래에서 추가로 신고하는 사항 (시행령 별표 1)","머리":["거래","추가 신고사항","제외"],"행":[["법인이 주택을 거래","법인 등기 현황, 상대방과의 임원 관계","국가등이 당사자이거나 공급계약·분양권 매매"],["법인이 주택을 매수","취득목적, 자금조달계획·지급방식, 임대 등 이용계획","-"],["법인 외의 자가 6억원 이상 주택을 매수, 또는 투기과열지구·조정대상지역 주택 매수","자금조달계획·지급방식, 본인 입주 여부·입주 예정 시기","매수인 중 국가등이 포함된 경우"],["토지거래허가를 받아 허가구역 주택을 매수","자금조달계획(증빙 첨부), 입주 여부·이용계획","-"]]}],"함정":"6억원 이상이면 투기과열지구 밖의 주택도 이용계획 신고 대상이다. 검인은 신고필증을 발급받은 때에 받은 것으로 본다. 해제등 신고의 단독 신고는 일방이 거부할 때만 가능하다."}},{"i":"S3-2-1-중개사법-31","r":"S3","g":2,"c":2,"n":31,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 외국인등의 부동산 취득 등에 관한 특례에 대한 설명으로 옳은 것은? (단, 헌법과 법률에 따라 체결된 조약의 이행에 필요한 경우는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["외국인등이 상속으로 대한민국 안의 부동산등을 취득한 때에는 부동산등을 취득한 날부터 6개월 이내에 신고관청에 신고하여야 한다.","외국인등이 증여계약으로 대한민국 안의 부동산등을 취득한 때에는 계약체결일부터 6개월 이내에 신고관청에 신고하여야 한다.","외국인등이 대한민국 안의 토지를 매매계약으로 취득한 경우에는 계약체결일부터 60일 이내에 외국인등의 부동산 취득신고를 하여야 한다.","대한민국의 법령에 따라 설립된 법인이 외국인등으로 변경된 경우 그 외국인등이 부동산등을 계속보유하려면 변경된 날부터 1년 이내에 신고하여야 한다.","생태ㆍ경관보전지역 안의 토지를 취득하려는 외국인등은 토지취득계약을 체결한 후 신고관청의 허가를 받아야 한다."],"a":[1],"L":"중2-3","o":"변형","x":{"한줄":"상속·경매 등 계약 외의 원인으로 취득하면 취득한 날부터 6개월 이내에 신고관청에 신고한다(법 제8조제2항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제8조","원문":"제8조(외국인등의 부동산 취득ㆍ보유 신고)\n① 외국인등이 대한민국 안의 부동산등을 취득하는 계약(제3조제1항 각 호에 따른 계약은 제외한다)을 체결하였을 때에는 계약체결일부터 60일 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다.\n② 외국인등이 상속ㆍ경매, 그 밖에 대통령령으로 정하는 계약 외의 원인으로 대한민국 안의 부동산등을 취득한 때에는 부동산등을 취득한 날부터 6개월 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다.\n③ 대한민국 안의 부동산등을 가지고 있는 대한민국국민이나 대한민국의 법령에 따라 설립된 법인 또는 단체가 외국인등으로 변경된 경우 그 외국인등이 해당 부동산등을 계속보유하려는 경우에는 외국인등으로 변경된 날부터 6개월 이내에 대통령령으로 정하는 바에 따라 신고관청에 신고하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제9조 제1항 제3항","원문":"① 제3조 및 제8조에도 불구하고 외국인등이 취득하려는 토지가 다음 각 호의 어느 하나에 해당하는 구역ㆍ지역 등에 있으면 토지를 취득하는 계약(이하 \"토지취득계약\"이라 한다)을 체결하기 전에 대통령령으로 정하는 바에 따라 신고관청으로부터 토지취득의 허가를 받아야 한다. 다만, 제11조에 따라 토지거래계약에 관한 허가를 받은 경우에는 그러하지 아니하다.\n1. 「군사기지 및 군사시설 보호법」 제2조제6호에 따른 군사기지 및 군사시설 보호구역, 그 밖에 국방목적을 위하여 외국인등의 토지취득을 특별히 제한할 필요가 있는 지역으로서 대통령령으로 정하는 지역\n2. 「문화유산의 보존 및 활용에 관한 법률」 제2조제3항에 따른 지정문화유산과 이를 위한 보호물 또는 보호구역\n2의2. 「자연유산의 보존 및 활용에 관한 법률」에 따라 지정된 천연기념물등과 이를 위한 보호물 또는 보호구역\n3. 「자연환경보전법」 제2조제12호에 따른 생태ㆍ경관보전지역\n4. 「야생생물 보호 및 관리에 관한 법률」 제27조에 따른 야생생물 특별보호구역\n③ 제1항을 위반하여 체결한 토지취득계약은 그 효력이 발생하지 아니한다."},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제5조 제2항","원문":"② 법 제8조제2항에서 \"대통령령으로 정하는 계약 외의 원인\"이란 다음 각 호의 어느 하나에 해당하는 사유를 말한다.\n1. 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」 및 그 밖의 법률에 따른 환매권의 행사\n2. 법원의 확정판결\n3. 법인의 합병\n4. 건축물의 신축ㆍ증축ㆍ개축ㆍ재축"}],"선지":[{"번호":1,"판정":"옳음","설명":"상속은 계약 외의 원인이다. 취득한 날부터 6개월 이내에 신고관청에 신고한다(법 제8조제2항). 신고이고 허가가 아니다."},{"번호":2,"판정":"틀림","설명":"증여는 매매 외의 계약이므로 계약체결일부터 60일 이내에 신고한다(법 제8조제1항). 6개월은 계약 외의 원인으로 취득한 경우의 기한이다."},{"번호":3,"판정":"틀림","설명":"외국인등의 매매계약은 일반 부동산 거래신고 대상이라 계약체결일부터 30일 이내에 신고한다(법 제3조제1항, 제8조제1항 괄호). 취득신고를 따로 하지 않는다."},{"번호":4,"판정":"틀림","설명":"계속보유 신고는 외국인등으로 변경된 날부터 6개월 이내다(법 제8조제3항)."},{"번호":5,"판정":"틀림","설명":"생태ㆍ경관보전지역의 토지는 토지취득계약을 체결하기 전에 허가를 받아야 한다. 허가 없이 체결한 계약은 효력이 생기지 않는다(법 제9조제1항·제3항)."}],"개념":[{"종류":"표","제목":"외국인등의 취득 원인별 신고 (법 제3조·제8조)","머리":["원인","신고 종류","기한","과태료 상한"],"행":[["매매계약 (공급계약, 분양권·입주권 매매 포함)","부동산 거래신고","계약체결일부터 30일","500만원 (법 제28조제2항)"],["매매 외 계약 (증여, 교환 등)","외국인등 취득신고","계약체결일부터 60일","300만원 (법 제28조제4항)"],["계약 외 원인 (상속, 경매, 확정판결, 환매권 행사, 법인 합병, 건축물 신축·증축·개축·재축)","외국인등 취득신고","취득한 날부터 6개월","100만원 (법 제28조제5항제1호)"],["국민·국내 법인이 외국인등으로 변경된 뒤 계속 보유","계속보유 신고","변경된 날부터 6개월","100만원 (법 제28조제5항제2호)"]]},{"종류":"표","제목":"외국인등의 토지취득 허가 (법 제9조, 시행령 제6조)","머리":["구분","내용"],"행":[["허가 구역","군사기지·군사시설 보호구역 등 국방목적 지역, 지정문화유산과 보호물·보호구역, 천연기념물등과 보호물·보호구역, 생태·경관보전지역, 야생생물 특별보호구역"],["허가 시점","토지취득계약을 체결하기 전"],["허가권자","신고관청 (시장·군수·구청장)"],["처리기간","군사기지 등 국방목적 구역은 30일 (부득이하면 30일 범위에서 연장), 그 밖의 구역은 15일"],["위반 효과","허가 없이 체결한 계약은 효력 불발생, 2년 이하 징역 또는 2천만원 이하 벌금"],["예외","토지거래허가(법 제11조)를 받은 경우에는 외국인등의 허가를 따로 받지 않는다"]]}],"함정":"6개월은 계약 외 원인 취득과 계속보유 두 가지에만 붙는다. 증여·교환은 60일, 매매는 30일이다. 상수원보호구역은 허가 대상 구역 목록에 없다.","개정":"외국인등의 토지취득 허가 처리기간이 군사기지 등 국방목적 구역 30일, 그 밖의 구역 15일로 나뉘었다(시행령 제6조제3항, 2023.10.4. 개정). 이전에는 구역 구분 없이 15일이었다."}},{"i":"S3-2-1-중개사법-32","r":"S3","g":2,"c":2,"n":32,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 토지거래계약을 허가받은 자에게 부과되는 토지의 이용 의무에 관한 설명으로 옳은 것을 모두 고른 것은?","b":"ㄱ. 자기의 거주용 주택용지로 이용하려는 목적으로 토지거래계약의 허가를 받은 경우 토지 취득일부터 4년간 토지의 이용 의무가 있다.\nㄴ. 이행강제금은 이행명령이 이행될 때까지 반복하여 부과할 수 있으며, 토지의 이용 의무기간이 지난 후에도 부과할 수 있다.\nㄷ. 시장·군수 또는 구청장은 토지의 이용 의무 불이행에 따른 이행명령을 받은 자가 그 명령을 이행하는 경우에도 명령을 이행하기 전에 이미 부과된 이행강제금은 징수하여야 한다.","bs":"글자","img":[],"ch":["ㄱ","ㄷ","ㄱ, ㄴ","ㄴ, ㄷ","ㄱ, ㄴ, ㄷ"],"a":[2],"L":"중2-4","o":"기출","x":{"한줄":"자기 거주용 주택용지의 이용 의무기간은 취득일부터 2년이고, 이행강제금은 이용 의무기간이 지나면 부과할 수 없으며, 이미 부과된 이행강제금은 이행해도 징수한다. 보기 중 ㄷ만 맞다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제14조 제2항","원문":"② 법 제17조제1항에서 \"대통령령으로 정하는 기간\"이란 다음 각 호의 구분에 따른 기간을 말한다.\n1. 법 제12조제1호가목부터 다목까지의 목적으로 허가를 받은 경우: 토지 취득일부터 2년\n2. 법 제12조제1호라목부터 바목까지의 목적으로 허가를 받은 경우: 토지 취득일부터 4년. 다만, 분양을 목적으로 허가를 받은 토지로서 개발에 착수한 후 토지 취득일부터 4년 이내에 분양을 완료한 경우에는 분양을 완료한 때에 4년이 지난 것으로 본다.\n3. 제10조제2항제1호에 따라 대체토지를 취득하기 위하여 허가를 받은 경우: 토지 취득일부터 2년\n4. 제10조제2항제2호에 따라 현상보존의 목적으로 토지를 취득하기 위하여 허가를 받은 경우: 토지 취득일부터 5년\n5. 제1호부터 제4호까지의 경우 외의 경우: 토지 취득일부터 5년"},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제18조 제3항 제4항 제5항","원문":"③ 시장ㆍ군수 또는 구청장은 최초의 이행명령이 있었던 날을 기준으로 1년에 한 번씩 그 이행명령이 이행될 때까지 반복하여 제2항에 따른 이행강제금을 부과ㆍ징수할 수 있다.\n④ 시장ㆍ군수 또는 구청장은 제17조제1항에 따른 이용 의무기간이 지난 후에는 이행강제금을 부과할 수 없다.\n⑤ 시장ㆍ군수 또는 구청장은 제1항에 따른 이행명령을 받은 자가 그 명령을 이행하는 경우에는 새로운 이행강제금의 부과를 즉시 중지하되, 명령을 이행하기 전에 이미 부과된 이행강제금은 징수하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ이 틀린 설명이라 이 조합은 정답이 아니다. 맞는 ㄷ이 빠져 있다."},{"번호":2,"판정":"-","설명":"ㄷ만 맞는 설명이므로 정답 조합이다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄴ은 둘 다 틀린 설명이다."},{"번호":4,"판정":"-","설명":"ㄴ이 틀린 설명이라 ㄷ과 함께 고를 수 없다."},{"번호":5,"판정":"-","설명":"ㄱ, ㄴ이 틀린 설명이라 셋을 모두 고를 수 없다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"법 제12조제1호가목부터 다목까지(자기 거주용 주택용지 포함)의 목적으로 허가를 받은 경우 이용 의무기간은 토지 취득일부터 2년이다(시행령 제14조제2항제1호). 4년은 라목~바목 목적이다."},{"기호":"ㄴ","판정":"틀림","설명":"이행강제금은 이행명령이 이행될 때까지 1년에 한 번씩 반복 부과할 수 있으나(법 제18조제3항), 이용 의무기간이 지난 후에는 부과할 수 없다(법 제18조제4항)."},{"기호":"ㄷ","판정":"옳음","설명":"이행명령을 이행하면 새 이행강제금 부과를 즉시 중지하되, 명령을 이행하기 전에 이미 부과된 이행강제금은 징수하여야 한다(법 제18조제5항)."}],"개념":[{"종류":"표","제목":"토지 이용 의무기간 (시행령 제14조제2항)","머리":["허가 목적","이용 의무기간"],"행":[["자기의 거주용 주택용지, 주민 복지·편익시설 설치, 농업·축산업·임업·어업 경영 (법 제12조제1호 가목~다목)","토지 취득일부터 2년"],["수용 가능 사업 시행자의 사업, 지역 발전에 필요한 사업, 인접 지역 사업 시행자의 사업 (라목~바목)","토지 취득일부터 4년. 분양 목적으로 개발에 착수해 4년 안에 분양을 완료하면 완료한 때 4년이 지난 것으로 본다"],["대체토지 취득 목적 (시행령 제10조제2항제1호)","토지 취득일부터 2년"],["현상보존 목적 (시행령 제10조제2항제2호)","토지 취득일부터 5년"],["그 밖의 경우","토지 취득일부터 5년"]]},{"종류":"흐름","제목":"이용 의무 위반에서 이행강제금까지","단계":[{"이름":"이용 현황 조사","설명":"시장·군수·구청장이 허가받은 목적대로 이용하는지 조사한다 (법 제17조제2항)."},{"이름":"이행명령","설명":"문서로 하고 이행기간은 3개월 이내로 정한다 (시행령 제16조제1항)."},{"이름":"계고","설명":"이행기간 안에 이행하지 않으면 이행강제금을 부과·징수한다는 뜻을 미리 문서로 알린다 (시행령 제16조제5항)."},{"이름":"이행강제금 부과","설명":"취득가액의 100분의 10 범위의 금액을 문서로 부과한다. 최초 이행명령일을 기준으로 1년에 한 번씩 반복할 수 있다 (법 제18조제2항·제3항)."},{"이름":"부과 중단","설명":"이행명령을 이행하면 새 부과를 중지하지만 이미 부과된 금액은 징수한다. 이용 의무기간이 지나면 부과할 수 없다 (법 제18조제4항·제5항)."}]}],"함정":"이용 의무기간은 2년, 4년, 5년으로 갈리고 자기 거주용 주택용지는 가장 짧은 2년이다. 이행강제금은 반복 부과할 수 있지만 이용 의무기간이 지나면 부과하지 못한다."}},{"i":"S3-2-1-중개사법-33","r":"S3","g":2,"c":2,"n":33,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 이행강제금에 대하여 개업공인중개사가 중개의뢰인에게 설명한 내용으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["이행명령은 구두로도 할 수 있으며, 이행기간은 6개월 이내로 정하여야 한다.","토지거래계약허가를 받아 취득한 토지를 직접 이용하지 아니하고 임대한 경우에는 토지 취득가액의 100분의 10에 상당하는 금액을 이행강제금으로 부과한다.","허가관청의 승인 없이 당초의 이용목적을 변경하여 이용하는 경우에는 토지 취득가액의 100분의 7에 상당하는 금액을 이행강제금으로 부과한다.","이행강제금 산정의 기준이 되는 토지 취득가액은 실제 거래가격이 확인되더라도 취득 당시 가장 최근에 발표된 개별공시지가로 한다.","허가관청은 이행강제금을 부과하기 전에 이행기간 내에 이행명령을 이행하지 아니하면 이행강제금을 부과·징수한다는 뜻을 미리 문서로 계고하여야 한다."],"a":[5],"L":"중2-4","o":"변형","x":{"한줄":"이행강제금을 부과하기 전에 이행기간 안에 이행하지 않으면 부과·징수한다는 뜻을 문서로 미리 계고해야 한다(시행령 제16조제5항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제16조 제1항 제3항 제4항 제5항 제7항","원문":"① 법 제18조제1항 본문에 따른 이행명령은 문서로 하여야 하며, 이행기간은 3개월 이내로 정하여야 한다.\n③ 법 제18조제2항에서 \"대통령령으로 정하는 금액\"이란 다음 각 호의 구분에 따른 금액을 말한다.\n1. 토지거래계약허가를 받아 토지를 취득한 자가 당초의 목적대로 이용하지 아니하고 방치한 경우: 토지 취득가액의 100분의 10에 상당하는 금액\n2. 토지거래계약허가를 받아 토지를 취득한 자가 직접 이용하지 아니하고 임대한 경우: 토지 취득가액의 100분의 7에 상당하는 금액\n3. 토지거래계약허가를 받아 토지를 취득한 자가 제14조제1항제3호에 따른 허가관청의 승인 없이 당초의 이용목적을 변경하여 이용하는 경우: 토지 취득가액의 100분의 5에 상당하는 금액\n4. 제1호부터 제3호까지에 해당하지 아니하는 경우: 토지 취득가액의 100분의 7에 상당하는 금액\n④ 제3항 각 호에 따른 토지 취득가액은 실제 거래가격으로 한다. 다만, 실제 거래가격이 확인되지 아니하는 경우에는 취득 당시를 기준으로 가장 최근에 발표된 개별공시지가(「부동산 가격공시에 관한 법률」에 따른 개별공시지가를 말한다)를 기준으로 산정한다.\n⑤ 허가관청은 법 제18조제2항에 따른 이행강제금을 부과하기 전에 이행기간 내에 이행명령을 이행하지 아니하면 이행강제금을 부과ㆍ징수한다는 뜻을 미리 문서로 계고(戒告)하여야 한다.\n⑦ 제6항에 따른 이행강제금 부과처분을 받은 자는 법 제18조제6항에 따라 이의를 제기하려는 경우에는 부과처분을 고지받은 날부터 30일 이내에 하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제18조 제2항","원문":"② 시장ㆍ군수 또는 구청장은 제1항에 따른 이행명령이 정하여진 기간에 이행되지 아니한 경우에는 토지 취득가액의 100분의 10의 범위에서 대통령령으로 정하는 금액의 이행강제금을 부과한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"이행명령은 문서로 하고, 이행기간은 3개월 이내로 정한다(시행령 제16조제1항)."},{"번호":2,"판정":"틀림","설명":"직접 이용하지 않고 임대한 경우는 취득가액의 100분의 7이다. 100분의 10은 방치한 경우다(시행령 제16조제3항제2호·제1호)."},{"번호":3,"판정":"틀림","설명":"허가관청의 승인 없이 이용목적을 변경한 경우는 취득가액의 100분의 5다(시행령 제16조제3항제3호)."},{"번호":4,"판정":"틀림","설명":"취득가액은 실제 거래가격이다. 실제 거래가격이 확인되지 않을 때에만 개별공시지가를 기준으로 한다(시행령 제16조제4항)."},{"번호":5,"판정":"옳음","설명":"시행령 제16조제5항이 부과 전 문서 계고를 의무로 정한다."}],"개념":[{"종류":"표","제목":"이행강제금 금액 (시행령 제16조제3항, 법 제18조제2항)","머리":["이용 의무 위반 유형","금액"],"행":[["허가받은 목적대로 이용하지 않고 방치","토지 취득가액의 100분의 10"],["직접 이용하지 않고 임대","토지 취득가액의 100분의 7"],["허가관청 승인 없이 이용목적 변경","토지 취득가액의 100분의 5"],["위 세 가지에 해당하지 않는 경우","토지 취득가액의 100분의 7"],["상한","취득가액의 100분의 10 범위 (법 제18조제2항)"]]},{"종류":"계산","제목":"이행강제금 산정 예: 취득가액 5억원 토지를 직접 이용하지 않고 임대한 경우","단계":[{"설명":"취득가액을 정한다 (실제 거래가격)","식":"취득가액","값":"5억원"},{"설명":"임대 유형의 비율을 찾는다","식":"시행령 제16조제3항제2호","값":"100분의 7"},{"설명":"취득가액에 비율을 곱한다","식":"5억원 × 7/100","값":"3,500만원"}]}],"함정":"방치 10%, 임대 7%, 승인 없는 목적 변경 5%다. 이의 제기는 부과처분을 고지받은 날부터 30일 이내에 허가관청에 한다."}},{"i":"S3-2-1-중개사법-34","r":"S3","g":2,"c":2,"n":34,"s":"중개사법","q":"부동산 거래신고 등에 관한 법령상 벌금 또는 과태료의 부과기준이 '계약 체결 당시의 개별공시지가에 따른 해당 토지가격' 또는 '해당 부동산등의 취득가액'의 비율 형식으로 규정된 경우가 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["토지거래허가구역 안에서 허가 없이 토지거래계약을 체결한 경우","외국인이 부정한 방법으로 허가를 받아 토지취득계약을 체결한 경우","토지거래허가구역 안에서 속임수나 그 밖의 부정한 방법으로 토지거래계약 허가를 받은 경우","부동산매매계약을 체결한 거래당사자가 그 실제거래가격을 거짓으로 신고한 경우","부동산매매계약을 체결한 후 신고 의무자가 아닌 자가 거짓으로 부동산거래신고를 한 경우"],"a":[2],"L":"중2-5","o":"기출","x":{"한줄":"외국인등이 허가 없이 또는 부정한 방법으로 허가를 받아 토지취득계약을 체결하면 2년 이하 징역 또는 2천만원 이하 벌금이다. 정액이라 비율 형식이 아니다(법 제26조제2항).","근거":[{"법령":"부동산 거래신고 등에 관한 법률","조문":"제26조 제2항 제3항","원문":"② 제9조제1항에 따른 허가를 받지 아니하고 토지취득계약을 체결하거나 부정한 방법으로 허가를 받아 토지취득계약을 체결한 외국인등은 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.\n③ 제11조제1항에 따른 허가 또는 변경허가를 받지 아니하고 토지거래계약을 체결하거나, 속임수나 그 밖의 부정한 방법으로 토지거래계약 허가를 받은 자는 2년 이하의 징역 또는 계약 체결 당시의 개별공시지가에 따른 해당 토지가격의 100분의 30에 해당하는 금액 이하의 벌금에 처한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제28조 제3항","원문":"③ 제3조제1항부터 제4항까지 또는 제4조제2호를 위반하여 그 신고를 거짓으로 한 자에게는 해당 부동산등의 취득가액의 100분의 10 이하에 상당하는 금액의 과태료를 부과한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"허가 없이 체결한 토지거래계약은 2년 이하 징역 또는 계약 체결 당시 개별공시지가에 따른 토지가격의 100분의 30 이하 벌금이다(법 제26조제3항). 비율 형식이다."},{"번호":2,"판정":"틀림","설명":"외국인등의 허가 위반 벌금은 2천만원 이하의 정액이다(법 제26조제2항)."},{"번호":3,"판정":"옳음","설명":"속임수 등 부정한 방법으로 토지거래계약 허가를 받은 경우도 제26조제3항이라 토지가격의 100분의 30 이하 벌금이다."},{"번호":4,"판정":"옳음","설명":"실제 거래가격을 거짓으로 신고하면 해당 부동산등의 취득가액의 100분의 10 이하 과태료다(법 제28조제3항)."},{"번호":5,"판정":"옳음","설명":"신고의무가 없는 자가 거짓으로 신고한 경우(법 제4조제2호 위반)도 제28조제3항이라 취득가액의 100분의 10 이하 과태료다."}],"개념":[{"종류":"표","제목":"거래신고법상 벌칙·과태료 금액","머리":["위반행위","제재","근거"],"행":[["허가 없이, 또는 부정한 방법으로 허가받아 토지거래계약","2년 이하 징역 또는 개별공시지가 토지가격의 100분의 30 이하 벌금","법 제26조제3항"],["외국인등이 허가 없이, 또는 부정한 방법으로 허가받아 토지취득계약","2년 이하 징역 또는 2천만원 이하 벌금","법 제26조제2항"],["부당 이득 목적의 가장 거래신고·거짓 해제등 신고","3년 이하 징역 또는 3천만원 이하 벌금","법 제26조제1항"],["허가 취소·처분·조치명령 위반","1년 이하 징역 또는 1천만원 이하 벌금","법 제26조제4항"],["실제 거래가격 거짓 신고 (신고의무자 아닌 자의 거짓 신고 포함)","취득가액의 100분의 10 이하 과태료","법 제28조제3항"],["거래대금 지급 증빙 미제출·거짓 제출","3천만원 이하 과태료","법 제28조제1항제3호"],["거래신고·해제등 신고 미이행","500만원 이하 과태료","법 제28조제2항"],["외국인등 매매 외 계약 취득 미신고","300만원 이하 과태료","법 제28조제4항"],["외국인등 계약 외 원인 취득·계속보유 미신고","100만원 이하 과태료","법 제28조제5항"]]},{"종류":"비교","제목":"비율로 정하는 제재와 정액 제재","왼쪽":{"이름":"비율 형식 (2가지 유형)","항목":["벌금: 계약 체결 당시 개별공시지가에 따른 토지가격의 100분의 30 이하 (토지거래허가 위반)","과태료: 해당 부동산등의 취득가액의 100분의 10 이하 (실제 거래가격 거짓 신고)"]},"오른쪽":{"이름":"정액 형식","항목":["외국인등의 허가 위반: 2천만원 이하 벌금","가장 신고: 3천만원 이하 벌금","대금 증빙 미제출: 3천만원 이하 과태료","신고 미이행: 500만원 이하 과태료"]}}],"함정":"토지거래허가 위반(내국인 포함 일반 허가구역)은 비율 벌금이고, 외국인등의 토지취득 허가 위반은 정액 벌금이다. 둘 다 징역 상한은 2년이다."}},{"i":"S3-2-1-중개사법-35","r":"S3","g":2,"c":2,"n":35,"s":"중개사법","q":"개업공인중개사가 묘소가 설치되어 있는 임야를 중개하면서 중개의뢰인에게 설명한 내용으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["분묘기지권을 시효취득한 자는 시효취득이 완성된 때로 소급하여 지료를 지급할 의무가 있다.","2001. 1. 13. 이후 토지소유자의 승낙 없이 설치한 분묘는 20년간 평온·공연하게 점유하더라도 분묘기지권을 시효취득할 수 없다.","평장되어 외부에서 분묘임을 알아볼 수 있는 외형을 갖추지 못한 묘소에는 분묘기지권이 인정되지 않는다.","분묘기지권자가 그 권리를 포기하는 의사표시를 하면 점유까지 내놓지 않아도 분묘기지권은 소멸한다.","분묘기지권은 등기 없이도 그 토지를 양수한 제3자에게 주장할 수 있다."],"a":[1],"L":"중3-1","o":"변형","x":{"한줄":"시효취득한 분묘기지권자는 토지소유자가 지료를 청구한 날부터의 지료를 지급할 의무가 있다. 시효취득이 완성된 때로 소급하지 않는다.","근거":[{"판례":"대법원 2021. 4. 29. 선고 2017다228007 전원합의체 판결","요지":"승낙 없이 분묘를 설치하고 20년간 평온·공연하게 점유해 분묘기지권을 시효취득한 사람은 토지소유자가 지료를 청구한 날부터의 지료를 지급할 의무가 있다."},{"법령":"장사 등에 관한 법률","조문":"제27조 제1항 제1호, 제3항","원문":"1. 토지 소유자의 승낙 없이 해당 토지에 설치한 분묘\n③ 제1항 각 호의 어느 하나에 해당하는 분묘의 연고자는 해당 토지 소유자, 묘지 설치자 또는 연고자에게 토지 사용권이나 그 밖에 분묘의 보존을 위한 권리를 주장할 수 없다."},{"이론":"분묘기지권의 성립·소멸·대항력 (판례)","내용":"시신이나 유골이 있고 봉분 등 외부에서 분묘임을 알아볼 형태를 갖춘 분묘에 성립한다. 평장·암장된 묘와 장래를 위한 가묘에는 성립하지 않는다. 권리자가 포기의 의사표시를 하면 점유 포기 없이도 소멸한다. 관습상 물권이라 등기 없이도 토지 양수인 등 제3자에게 주장할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"시효취득자의 지료 지급의무는 토지소유자가 지료를 청구한 날부터 생긴다. 소급하지 않는다(대법원 2017다228007 전원합의체)."},{"번호":2,"판정":"옳음","설명":"2001. 1. 13. 장사 등에 관한 법률이 시행된 뒤 승낙 없이 설치한 분묘의 연고자는 토지사용권 등을 주장할 수 없다(법 제27조제3항). 20년 점유로도 시효취득을 주장하지 못한다."},{"번호":3,"판정":"옳음","설명":"평장·암장처럼 객관적으로 분묘임을 인식할 수 있는 외형을 갖추지 못한 묘소에는 분묘기지권이 성립하지 않는다."},{"번호":4,"판정":"옳음","설명":"분묘기지권은 권리자가 포기의 의사표시를 하면 소멸하고, 점유의 포기까지는 필요하지 않다."},{"번호":5,"판정":"옳음","설명":"분묘기지권은 관습상 물권이어서 등기 없이도 토지 양수인 등 제3자에게 주장할 수 있다."}],"개념":[{"종류":"표","제목":"분묘기지권 성립 유형별 지료","머리":["유형","성립 원인","지료"],"행":[["승낙형","토지소유자의 승낙을 받아 분묘를 설치","약정에 따른다. 지료 약정은 토지 승계인에게도 효력이 있다"],["양도형","자기 토지에 분묘를 설치한 사람이 이장 특약 없이 토지만 처분","분묘기지권이 성립한 때부터"],["시효취득형","승낙 없이 설치한 분묘를 20년간 평온·공연하게 점유 (2001. 1. 13. 전 설치분)","토지소유자가 지료를 청구한 날부터"]]},{"종류":"표","제목":"분묘기지권의 요점","머리":["항목","내용"],"행":[["성립 요건","시신·유골이 있고, 봉분 등 분묘임을 알아볼 외형. 평장·암장·가묘는 불성립"],["효력 범위","분묘의 기지와 분묘를 지키고 제사를 지내는 데 필요한 주변 빈터. 범위 안에서도 새 분묘를 설치할 권능은 없다"],["존속기간","약정이 없으면 권리자가 분묘를 수호·봉사하는 동안 분묘가 존속하는 기간. 지상권 존속기간을 끌어쓰지 않는다"],["멸실","유골이 남아 있어 분묘를 다시 만들 수 있는 일시적 멸실이면 소멸하지 않는다"],["소멸","포기의 의사표시만으로 소멸. 점유 포기는 불필요"],["대항력","등기 없이도 제3자에게 주장 가능. 등기사항증명서에는 나타나지 않으므로 현장 확인"]]}],"함정":"양도형은 성립한 때부터, 시효취득형은 청구한 날부터 지료를 낸다. 장사법 시행일 2001. 1. 13.을 기준으로 시효취득 가능 여부가 갈린다.","개정":"대법원 2021. 4. 29. 선고 2017다228007 전원합의체 판결로 시효취득한 분묘기지권자도 토지소유자가 지료를 청구한 날부터의 지료를 지급하는 것으로 판례가 바뀌었다. 종전에는 시효취득자는 지료를 지급할 필요가 없다고 보았다."}},{"i":"S3-2-1-중개사법-36","r":"S3","g":2,"c":2,"n":36,"s":"중개사법","q":"개업공인중개사가 농지법에 대하여 중개의뢰인에게 설명한 내용으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["농지 소유자가 소유 농지를 정당한 사유 없이 자기의 농업경영에 이용하지 아니한다고 시장·군수 또는 구청장이 인정한 경우에는 그 사유가 발생한 날부터 1년 이내에 해당 농지를 처분하여야 한다.","농지의 임대차계약은 임차인이 농지 소재지를 관할하는 시·구·읍·면의 장의 확인을 받고 해당 농지를 인도받으면 그 날부터 제삼자에 대하여 효력이 생긴다.","일반 농지의 임대차 기간을 정하지 아니한 경우에는 3년으로 약정된 것으로 본다.","임대인이 임대차 기간이 끝나기 3개월 전까지 임차인에게 갱신하지 아니한다는 뜻이나 조건을 변경한다는 뜻을 통지하지 아니하면, 기간이 끝난 때에 이전의 임대차계약과 같은 조건으로 다시 임대차계약을 한 것으로 본다.","농지취득자격증명을 발급받아 농지를 취득한 자가 소유권에 관한 등기를 신청할 때에는 농지취득자격증명을 첨부하여야 한다."],"a":[2],"L":"중3-1","o":"변형","x":{"한줄":"농지 임대차는 임차인이 시·구·읍·면의 장의 확인을 받고 농지를 인도받은 날의 다음 날부터 제삼자에게 효력이 생긴다(농지법 제24조제2항).","근거":[{"법령":"농지법","조문":"제24조 제2항","원문":"② 제1항에 따른 임대차계약은 그 등기가 없는 경우에도 임차인이 농지소재지를 관할하는 시ㆍ구ㆍ읍ㆍ면의 장의 확인을 받고, 해당 농지를 인도(引渡)받은 경우에는 그 다음 날부터 제삼자에 대하여 효력이 생긴다."},{"법령":"농지법","조문":"제10조 제1항","원문":"①농지 소유자는 다음 각 호의 어느 하나에 해당하게 되면 그 사유가 발생한 날부터 1년 이내에 해당 농지(제6호의 경우에는 농지 소유 상한을 초과하는 면적에 해당하는 농지를 말한다)를 처분하여야 한다. 다만, 「부동산 거래신고 등에 관한 법률」 제10조제1항에 따라 지정된 허가구역에 소재한 농지(제8조제1항에 따른 농지취득자격증명을 발급받거나 「부동산 거래신고 등에 관한 법률」 제11조에 따라 토지거래계약 허가를 받아 소유한 농지로 한정한다. 이하 \"토지거래허가구역내농지\"라 한다)의 경우는 제외한다.\n1. 소유 농지를 자연재해ㆍ농지개량ㆍ질병 등 대통령령으로 정하는 정당한 사유 없이 자기의 농업경영에 이용하지 아니하거나 이용하지 아니하게 되었다고 시장(구를 두지 아니한 시의 시장을 말한다. 이하 이 조에서 같다)ㆍ군수 또는 구청장이 인정한 경우\n2. 농지를 소유하고 있는 농업회사법인이 제2조제3호의 요건에 맞지 아니하게 된 후 3개월이 지난 경우\n3. 제6조제2항제2호에 따라 농지를 취득한 자가 그 농지를 해당 목적사업에 이용하지 아니하게 되었다고 시장ㆍ군수 또는 구청장이 인정한 경우\n4. 제6조제2항제3호에 따라 농지를 취득한 자가 자연재해ㆍ농지개량ㆍ질병 등 대통령령으로 정하는 정당한 사유 없이 그 농지를 주말ㆍ체험영농에 이용하지 아니하게 되었다고 시장ㆍ군수 또는 구청장이 인정한 경우\n4의2. 제6조제2항제4호에 따라 농지를 취득하여 소유한 자가 농지를 제23조제1항제1호에 따라 임대하거나 제23조제1항제6호에 따라 한국농어촌공사에 위탁하여 임대하는 등 대통령령으로 정하는 정당한 사유 없이 자기의 농업경영에 이용하지 아니하거나 이용하지 아니하게 되었다고 시장ㆍ군수 또는 구청장이 인정한 경우\n4의3. 제6조제2항제5호에 따라 농지를 소유한 자가 농지를 제23조제1항제1호에 따라 임대하거나 제23조제1항제6호에 따라 한국농어촌공사에 위탁하여 임대하는 등 대통령령으로 정하는 정당한 사유 없이 자기의 농업경영에 이용하지 아니하거나, 이용하지 아니하게 되었다고 시장ㆍ군수 또는 구청장이 인정한 경우\n5. 제6조제2항제7호에 따라 농지를 취득한 자가 취득한 날부터 2년 이내에 그 목적사업에 착수하지 아니한 경우\n5의2. 제6조제2항제10호마목에 따른 농림축산식품부장관과의 협의를 마치지 아니하고 농지를 소유한 경우\n5의3. 제6조제2항제10호바목에 따라 소유한 농지를 한국농어촌공사에 지체 없이 위탁하지 아니한 경우\n6. 제7조에 따른 농지 소유 상한을 초과하여 농지를 소유한 것이 판명된 경우\n7. 자연재해ㆍ농지개량ㆍ질병 등 대통령령으로 정하는 정당한 사유 없이 제8조제2항에 따른 농업경영계획서 또는 주말ㆍ체험영농계획서 내용을 이행하지 아니하였다고 시장ㆍ군수 또는 구청장이 인정한 경우"},{"법령":"농지법","조문":"제24조의2 제1항 제2항","원문":"① 제23조제1항 각 호(제8호는 제외한다)의 임대차 기간은 3년 이상으로 하여야 한다. 다만, 다년생식물 재배지 등 대통령령으로 정하는 농지의 경우에는 5년 이상으로 하여야 한다.\n② 임대차 기간을 정하지 아니하거나 제1항에 따른 기간 미만으로 정한 경우에는 제1항에 따른 기간으로 약정된 것으로 본다. 다만, 임차인은 제1항에 따른 기간 미만으로 정한 임대차 기간이 유효함을 주장할 수 있다."},{"법령":"농지법","조문":"제25조","원문":"제25조(묵시의 갱신) 임대인이 임대차 기간이 끝나기 3개월 전까지 임차인에게 임대차계약을 갱신하지 아니한다는 뜻이나 임대차계약 조건을 변경한다는 뜻을 통지하지 아니하면 그 임대차 기간이 끝난 때에 이전의 임대차계약과 같은 조건으로 다시 임대차계약을 한 것으로 본다."},{"법령":"농지법","조문":"제8조 제6항","원문":"⑥제1항 본문과 제2항에 따라 농지취득자격증명을 발급받아 농지를 취득하는 자가 그 소유권에 관한 등기를 신청할 때에는 농지취득자격증명을 첨부하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"정당한 사유 없이 자기의 농업경영에 이용하지 않는다고 시장·군수·구청장이 인정한 경우 그 사유가 발생한 날부터 1년 이내에 처분하여야 한다(농지법 제10조제1항제1호). 토지거래허가구역 안의 농지는 제외된다."},{"번호":2,"판정":"틀림","설명":"확인을 받고 농지를 인도받은 날이 아니라 그 다음 날부터 제삼자에 대하여 효력이 생긴다(농지법 제24조제2항)."},{"번호":3,"판정":"옳음","설명":"임대차 기간은 3년 이상이어야 하고, 기간을 정하지 않거나 3년 미만으로 정하면 3년으로 약정된 것으로 본다. 다년생식물 재배지 등 대통령령이 정하는 농지는 5년이다(농지법 제24조의2제1항·제2항)."},{"번호":4,"판정":"옳음","설명":"임대인이 기간 만료 3개월 전까지 갱신 거절이나 조건 변경의 통지를 하지 않으면 묵시적으로 갱신된다(농지법 제25조)."},{"번호":5,"판정":"옳음","설명":"농지취득자격증명을 발급받아 취득한 자는 소유권 등기 신청 때 증명서를 첨부해야 한다(농지법 제8조제6항)."}],"개념":[{"종류":"표","제목":"농지 소유 제한과 상한 (농지법 제6조·제7조)","머리":["구분","내용"],"행":[["원칙","자기의 농업경영에 이용하거나 이용할 자만 농지를 소유 (제6조제1항)"],["상속 취득","농업경영을 하지 않는 상속인은 상속 농지 중 총 1만제곱미터까지 소유 (제7조제1항)"],["이농","대통령령이 정하는 기간 이상 농업경영 후 이농한 사람은 이농 당시 소유 농지 중 총 1만제곱미터까지 (제7조제2항)"],["주말·체험영농","총 1천제곱미터 미만, 면적은 세대원 전부가 소유하는 총 면적으로 계산. 농업진흥지역 밖의 농지만 가능 (제6조제2항제3호, 제7조제3항)"],["농지 전용허가·신고·협의","전용허가를 받거나 전용신고를 한 자, 전용협의를 마친 농지는 소유 가능 (제6조제2항제7호·제8호)"],["처분의무","자기 농업경영에 이용하지 않는 등의 사유가 발생한 날부터 1년 이내 처분 (제10조제1항)"]]},{"종류":"표","제목":"농지취득자격증명 (농지법 제8조)","머리":["항목","내용"],"행":[["발급기관","농지 소재지 관할 시장·구청장·읍장·면장"],["발급 면제","국가·지방자치단체의 취득, 상속, 담보농지 취득, 농지전용협의를 마친 농지, 한국농어촌공사 등 일부 공익 취득, 농업법인 합병, 공유 농지의 분할 등"],["발급 기간","신청받은 날부터 7일 이내. 농업경영계획서를 쓰지 않는 경우 4일, 농지위원회 심의 대상은 14일"],["등기 신청 때","소유권에 관한 등기 신청서에 첨부"]]}],"함정":"임대차의 제삼자 효력은 확인과 인도를 갖춘 다음 날부터 생긴다. 주택·상가 임대차의 대항력이 인도와 주민등록·사업자등록의 다음 날부터 생기는 것과 같은 틀이다. 주말·체험영농용 농지의 1천제곱미터는 미만이고, 세대원 전부의 합산이다."}},{"i":"S3-2-1-중개사법-37","r":"S3","g":2,"c":2,"n":37,"s":"중개사법","q":"甲이 乙로부터 乙소유의 X주택을 2020. 1. 매수하면서 그 소유권이전등기는 자신의 친구인 丙에게로 해 줄 것을 요구하였다(이에 대한 丙의 동의가 있었음). 乙로부터 X주택의 소유권이전등기를 받은 丙은 甲의 허락을 얻지 않고 X주택을 丁에게 임대하였고, 丁은 X주택을 인도받은 후 주민등록을 이전하였다. 그런데 丁은 임대차계약 체결 당시에 甲의 허락이 없었음을 알고 있었다. 이에 대하여 개업공인중개사가 丁에게 설명한 내용으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["丙은 X주택의 소유권을 취득할 수 없다.","乙은 丙을 상대로 진정명의 회복을 위한 소유권이전등기를 청구할 수 있다.","甲은 乙과의 매매계약을 기초로 乙에게 X주택의 소유권이전등기를 청구할 수 있다.","丁은 甲또는 乙에 대하여 임차권을 주장할 수 있다.","丙은 丁을 상대로 임대차계약의 무효를 주장할 수 없지만, 甲은 그 계약의 무효를 주장할 수 있다."],"a":[5],"L":"중3-2","o":"기출","x":{"한줄":"명의신탁약정과 그에 따른 등기는 무효이지만 그 무효는 제3자에게 대항하지 못한다. 丁은 선의·악의를 가리지 않고 보호되는 제3자이므로 甲도 임대차의 무효를 주장할 수 없다(부동산 실권리자명의 등기에 관한 법률 제4조제3항).","근거":[{"법령":"부동산 실권리자명의 등기에 관한 법률","조문":"제4조 제1항 제2항 제3항","원문":"① 명의신탁약정은 무효로 한다.\n② 명의신탁약정에 따른 등기로 이루어진 부동산에 관한 물권변동은 무효로 한다. 다만, 부동산에 관한 물권을 취득하기 위한 계약에서 명의수탁자가 어느 한쪽 당사자가 되고 상대방 당사자는 명의신탁약정이 있다는 사실을 알지 못한 경우에는 그러하지 아니하다.\n③ 제1항 및 제2항의 무효는 제3자에게 대항하지 못한다."},{"이론":"3자간 등기명의신탁의 법률관계 (판례)","내용":"신탁자 甲이 매도인 乙과 매매계약을 맺고 등기만 수탁자 丙 명의로 한 경우 명의신탁약정과 丙 명의 등기는 무효다. 소유권은 매도인 乙에게 남고, 매매계약은 유효하므로 甲은 乙에게 이전등기를 청구할 수 있고 乙은 丙에게 말소 또는 진정명의회복을 위한 이전등기를 청구할 수 있다. 수탁자 丙으로부터 임차한 丁은 제4조제3항의 제3자로서 명의신탁 사실을 알았더라도 보호된다."}],"선지":[{"번호":1,"판정":"옳음","설명":"명의신탁약정에 따른 등기로 이루어진 물권변동은 무효다(제4조제2항). 매도인이 명의신탁 사실을 알았는지와 관계없이 3자간 등기명의신탁에서 丙은 소유권을 취득하지 못한다."},{"번호":2,"판정":"옳음","설명":"소유권은 乙에게 남아 있으므로 乙은 丙을 상대로 진정명의 회복을 위한 소유권이전등기를 청구할 수 있다."},{"번호":3,"판정":"옳음","설명":"甲과 乙 사이의 매매계약은 유효하다. 甲은 매매계약에 기한 이전등기청구권을 乙에게 행사할 수 있다."},{"번호":4,"판정":"옳음","설명":"丁은 제4조제3항의 제3자에 해당한다. 명의신탁을 알고 있었더라도 임차권으로 甲 또는 乙에게 대항할 수 있다."},{"번호":5,"판정":"틀림","설명":"丙이 임대차의 무효를 주장할 수 없는 것은 맞다. 그러나 명의신탁의 무효는 제3자인 丁에게 대항하지 못하므로 甲도 임대차계약의 무효를 주장할 수 없다."}],"개념":[{"종류":"표","제목":"명의신탁 유형별 효력 (부동산 실권리자명의 등기에 관한 법률 제4조)","머리":["유형","명의신탁약정","수탁자 명의 등기·물권변동","소유권·청구권"],"행":[["양자간 등기명의신탁 (신탁자 소유 부동산을 수탁자 명의로 등기)","무효","무효","신탁자가 소유권 유지, 수탁자 명의 등기는 말소 또는 진정명의회복 청구 대상"],["3자간 등기명의신탁 (신탁자가 매수하고 등기만 수탁자 명의)","무효","무효","매도인이 소유권 유지. 신탁자는 매도인에게 이전등기 청구, 매도인은 수탁자에게 말소 청구"],["계약명의신탁 (수탁자가 매매 당사자), 매도인이 약정을 모른 경우","무효","유효 (제4조제2항 단서)","수탁자가 소유권 취득"],["계약명의신탁, 매도인이 약정을 안 경우","무효","무효","매도인이 소유권 유지"],["공통","-","-","무효는 제3자에게 대항하지 못한다 (제4조제3항)"]]},{"종류":"흐름","제목":"사례의 법률관계 순서","단계":[{"이름":"명의신탁약정","설명":"甲이 매수하면서 丙 명의로 등기하기로 하고 丙이 동의. 약정은 무효 (제4조제1항)."},{"이름":"丙 명의 등기","설명":"물권변동이 무효이므로 소유권은 乙에게 남는다 (제4조제2항)."},{"이름":"甲·乙 관계","설명":"매매계약은 유효. 甲은 乙에게 이전등기를 청구할 수 있다."},{"이름":"乙·丙 관계","설명":"乙은 丙에게 진정명의 회복을 위한 이전등기(또는 말소)를 청구할 수 있다."},{"이름":"丙·丁 관계","설명":"丙이 맺은 임대차에서 丁은 제3자. 악의여도 보호되어 甲·乙에게 임차권을 주장할 수 있다 (제4조제3항)."}]}],"함정":"丙 명의 등기가 무효여도 丁의 임차권은 무효가 되지 않는다. 제4조제3항의 제3자는 선의·악의를 가리지 않는다. 명의신탁자는 5년 이하 징역 또는 2억원 이하 벌금(제7조제1항), 명의수탁자는 3년 이하 징역 또는 1억원 이하 벌금(제7조제2항)이고, 신탁자에게는 부동산 가액 100분의 30 범위의 과징금이 붙는다(제5조)."}},{"i":"S3-2-1-중개사법-38","r":"S3","g":2,"c":2,"n":38,"s":"중개사법","q":"개업공인중개사 甲의 중개로 乙은 丙 소유의 서울특별시 소재 X상가건물에 대하여 보증금 6억원, 월 차임 300만원에 1년 기간으로 임대차계약을 체결하였다. 乙은 X건물을 인도받아 2026. 3. 10. 사업자등록을 신청하였으며 2026. 3. 13. 임대차계약서상의 확정일자를 받았다. 이 사례에서 상가건물 임대차보호법령의 적용에 관한 甲의 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["乙은 2026. 3. 11. 대항력을 취득한다.","乙이 임대차기간 만료 6개월 전부터 1개월 전까지 사이에 계약갱신을 요구하더라도 3기의 차임액에 해당하는 금액에 이르도록 차임을 연체한 사실이 있으면 丙은 이를 거절할 수 있다.","환산보증금이 9억원을 초과하므로 乙은 보증금에 대한 우선변제권을 취득하지 못한다.","丙이 임대차기간 만료 6개월 전부터 1개월 전까지 사이에 乙에게 갱신 거절의 통지를 하지 아니한 경우에는 그 기간이 만료된 때에 전 임대차와 동일한 조건으로 다시 임대차한 것으로 보며, 이 경우 임대차의 존속기간은 1년으로 본다.","乙이 2026. 3. 13. 확정일자를 받았으므로 임대차가 경매나 공매로 매각되면 후순위권리자보다 우선하여 보증금을 변제받을 수 있다."],"a":[3],"L":"중3-2","o":"변형","x":{"한줄":"환산보증금은 6억원 + 300만원 × 100 = 9억원으로 서울특별시의 한도 9억원과 같다. 한도를 초과하는 임대차가 아니므로 우선변제권이 적용된다.","근거":[{"법령":"상가건물 임대차보호법","조문":"제2조 제1항 제2항","원문":"① 이 법은 상가건물(제3조제1항에 따른 사업자등록의 대상이 되는 건물을 말한다)의 임대차(임대차 목적물의 주된 부분을 영업용으로 사용하는 경우를 포함한다)에 대하여 적용한다. 다만, 제14조의2에 따른 상가건물임대차위원회의 심의를 거쳐 대통령령으로 정하는 보증금액을 초과하는 임대차에 대하여는 그러하지 아니하다.\n② 제1항 단서에 따른 보증금액을 정할 때에는 해당 지역의 경제 여건 및 임대차 목적물의 규모 등을 고려하여 지역별로 구분하여 규정하되, 보증금 외에 차임이 있는 경우에는 그 차임액에 「은행법」에 따른 은행의 대출금리 등을 고려하여 대통령령으로 정하는 비율을 곱하여 환산한 금액을 포함하여야 한다."},{"법령":"상가건물 임대차보호법 시행령","조문":"제2조 제1항 제3항","원문":"①「상가건물 임대차보호법」(이하 \"법\"이라 한다) 제2조제1항 단서에서 \"대통령령으로 정하는 보증금액\"이란 다음 각 호의 구분에 의한 금액을 말한다.\n1. 서울특별시 : 9억원\n2. 「수도권정비계획법」에 따른 과밀억제권역(서울특별시는 제외한다) 및 부산광역시: 6억9천만원\n3. 광역시(「수도권정비계획법」에 따른 과밀억제권역에 포함된 지역과 군지역, 부산광역시는 제외한다), 세종특별자치시, 파주시, 화성시, 안산시, 용인시, 김포시 및 광주시: 5억4천만원\n4. 그 밖의 지역 : 3억7천만원\n③법 제2조제2항에서 \"대통령령으로 정하는 비율\"이라 함은 1분의 100을 말한다."},{"법령":"상가건물 임대차보호법","조문":"제3조 제1항","원문":"① 임대차는 그 등기가 없는 경우에도 임차인이 건물의 인도와 「부가가치세법」 제8조, 「소득세법」 제168조 또는 「법인세법」 제111조에 따른 사업자등록을 신청하면 그 다음 날부터 제3자에 대하여 효력이 생긴다."},{"법령":"상가건물 임대차보호법","조문":"제5조 제2항","원문":"② 제3조제1항의 대항요건을 갖추고 관할 세무서장으로부터 임대차계약서상의 확정일자를 받은 임차인은 「민사집행법」에 따른 경매 또는 「국세징수법」에 따른 공매 시 임차건물(임대인 소유의 대지를 포함한다)의 환가대금에서 후순위권리자나 그 밖의 채권자보다 우선하여 보증금을 변제받을 권리가 있다."},{"법령":"상가건물 임대차보호법","조문":"제10조 제1항 제4항","원문":"① 임대인은 임차인이 임대차기간이 만료되기 6개월 전부터 1개월 전까지 사이에 계약갱신을 요구할 경우 정당한 사유 없이 거절하지 못한다. 다만, 다음 각 호의 어느 하나의 경우에는 그러하지 아니하다.\n1. 임차인이 3기의 차임액에 해당하는 금액에 이르도록 차임을 연체한 사실이 있는 경우\n2. 임차인이 거짓이나 그 밖의 부정한 방법으로 임차한 경우\n3. 서로 합의하여 임대인이 임차인에게 상당한 보상을 제공한 경우\n4. 임차인이 임대인의 동의 없이 목적 건물의 전부 또는 일부를 전대(轉貸)한 경우\n5. 임차인이 임차한 건물의 전부 또는 일부를 고의나 중대한 과실로 파손한 경우\n6. 임차한 건물의 전부 또는 일부가 멸실되어 임대차의 목적을 달성하지 못할 경우\n7. 임대인이 다음 각 목의 어느 하나에 해당하는 사유로 목적 건물의 전부 또는 대부분을 철거하거나 재건축하기 위하여 목적 건물의 점유를 회복할 필요가 있는 경우\n가. 임대차계약 체결 당시 공사시기 및 소요기간 등을 포함한 철거 또는 재건축 계획을 임차인에게 구체적으로 고지하고 그 계획에 따르는 경우\n나. 건물이 노후ㆍ훼손 또는 일부 멸실되는 등 안전사고의 우려가 있는 경우\n다. 다른 법령에 따라 철거 또는 재건축이 이루어지는 경우\n8. 그 밖에 임차인이 임차인으로서의 의무를 현저히 위반하거나 임대차를 계속하기 어려운 중대한 사유가 있는 경우\n④ 임대인이 제1항의 기간 이내에 임차인에게 갱신 거절의 통지 또는 조건 변경의 통지를 하지 아니한 경우에는 그 기간이 만료된 때에 전 임대차와 동일한 조건으로 다시 임대차한 것으로 본다. 이 경우에 임대차의 존속기간은 1년으로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"건물 인도와 사업자등록 신청을 마치면 그 다음 날부터 제3자에 대한 효력이 생긴다. 인도와 신청이 3월 10일이므로 대항력은 3월 11일에 생긴다(법 제3조제1항)."},{"번호":2,"판정":"옳음","설명":"3기의 차임액에 이르도록 연체한 사실이 있으면 임대인은 갱신요구를 거절할 수 있다(법 제10조제1항제1호). 월 차임 300만원이면 연체액이 900만원에 이른 경우다."},{"번호":3,"판정":"틀림","설명":"환산보증금은 9억원이고 서울특별시의 한도도 9억원이다. 한도를 초과해야 법 적용이 배제되는데 9억원은 초과가 아니다. 우선변제권이 적용된다(법 제2조제1항 단서, 시행령 제2조제1항제1호)."},{"번호":4,"판정":"옳음","설명":"임대인이 갱신 거절이나 조건 변경의 통지를 하지 않으면 기간 만료 때 전 임대차와 동일한 조건으로 다시 임대차한 것으로 보고, 존속기간은 1년이다(법 제10조제4항)."},{"번호":5,"판정":"옳음","설명":"대항요건을 갖추고 확정일자를 받은 임차인은 경매 또는 공매 때 후순위권리자와 그 밖의 채권자보다 우선하여 보증금을 변제받는다(법 제5조제2항). 우선변제권은 3월 13일에 생긴다."}],"개념":[{"종류":"계산","제목":"환산보증금과 법 적용 범위 (상가건물 임대차보호법 제2조, 시행령 제2조)","단계":[{"설명":"환산 공식: 월 차임에 100을 곱해 보증금에 더한다 (시행령 제2조제3항: 1분의 100)","식":"환산보증금 = 보증금 + 월 차임 × 100","값":"공식 확정"},{"설명":"월 차임을 환산한다","식":"300만원 × 100","값":"3억원"},{"설명":"보증금과 합산한다","식":"6억원 + 3억원","값":"9억원"},{"설명":"서울특별시 한도와 비교한다","식":"9억원 ≤ 9억원","값":"한도를 초과하지 않음 (법 전부 적용)"}]},{"종류":"표","제목":"지역별 보증금 한도와 한도 초과 시에도 적용되는 규정","머리":["구분","내용"],"행":[["서울특별시","9억원"],["과밀억제권역(서울 제외)·부산광역시","6억9천만원"],["광역시(과밀억제권역·군지역·부산 제외), 세종특별자치시, 파주시, 화성시, 안산시, 용인시, 김포시, 광주시","5억4천만원"],["그 밖의 지역","3억7천만원"],["한도를 초과해도 적용되는 규정 (법 제2조제3항)","대항력(제3조), 계약갱신요구(제10조제1항·제2항·제3항 본문), 권리금 보호(제10조의2~제10조의9), 폐업 시 해지(제11조의2), 표준계약서(제19조)"],["한도를 초과하면 적용되지 않는 대표 규정","우선변제권(제5조), 확정일자, 임차권등기명령(제6조), 소액보증금 최우선변제(제14조), 차임 증액 상한(제11조)"]]}],"함정":"한도는 ‘초과’일 때 배제된다. 환산보증금이 정확히 한도와 같으면 우선변제권이 적용된다. 한도를 넘더라도 대항력과 계약갱신요구권은 보호된다. 환산할 때는 월 차임에 100을 곱한다."}},{"i":"S3-2-1-중개사법-39","r":"S3","g":2,"c":2,"n":39,"s":"중개사법","q":"개업공인중개사가 집합건물의 매매를 중개하면서 설명한 내용으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["아파트 지하실은 특별한 사정이 없는 한 구분소유자 전원의 공용부분으로, 따로 구분소유의 목적이 될 수 없다.","전유부분이 주거 용도로 분양된 경우, 구분소유자는 정당한 사유 없이 그 부분을 주거 외의 용도로 사용해서는 안 된다.","구분소유자는 구조상 구분소유자 전원의 공용에 제공된 건물 부분에 대한 공유지분을 그가 가지는 전유부분과 분리하여 처분할 수 없다.","규약으로써 달리 정한 경우에도 구분소유자는 그가 가지는 전유부분과 분리하여 대지사용권을 처분할 수 없다.","일부의 구분소유자만이 공용하도록 제공되는 것임이 명백한 공용부분은 그들 구분소유자의 공유에 속한다."],"a":[4],"L":"중3-2","o":"기출","x":{"한줄":"대지사용권은 전유부분과 분리하여 처분할 수 없다. 다만 규약으로 달리 정하면 분리 처분이 가능하다(집합건물법 제20조제2항 단서).","근거":[{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제3조 제1항","원문":"① 여러 개의 전유부분으로 통하는 복도, 계단, 그 밖에 구조상 구분소유자 전원 또는 일부의 공용(共用)에 제공되는 건물부분은 구분소유권의 목적으로 할 수 없다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제5조 제2항","원문":"② 전유부분이 주거의 용도로 분양된 것인 경우에는 구분소유자는 정당한 사유 없이 그 부분을 주거 외의 용도로 사용하거나 그 내부 벽을 철거하거나 파손하여 증축ㆍ개축하는 행위를 하여서는 아니 된다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제13조 제2항","원문":"② 공유자는 그가 가지는 전유부분과 분리하여 공용부분에 대한 지분을 처분할 수 없다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제20조 제2항 제3항","원문":"② 구분소유자는 그가 가지는 전유부분과 분리하여 대지사용권을 처분할 수 없다. 다만, 규약으로써 달리 정한 경우에는 그러하지 아니하다.\n③ 제2항 본문의 분리처분금지는 그 취지를 등기하지 아니하면 선의(善意)로 물권을 취득한 제3자에게 대항하지 못한다."},{"법령":"집합건물의 소유 및 관리에 관한 법률","조문":"제10조 제1항","원문":"① 공용부분은 구분소유자 전원의 공유에 속한다. 다만, 일부의 구분소유자만이 공용하도록 제공되는 것임이 명백한 공용부분(이하 \"일부공용부분\"이라 한다)은 그들 구분소유자의 공유에 속한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"여러 전유부분으로 통하는 복도·계단처럼 구조상 공용에 제공되는 부분은 구분소유권의 목적이 될 수 없고, 아파트 지하실은 특별한 사정이 없으면 공용부분이다(제3조제1항)."},{"번호":2,"판정":"옳음","설명":"전유부분이 주거 용도로 분양된 것이면 정당한 사유 없이 주거 외 용도로 사용하지 못한다(제5조제2항)."},{"번호":3,"판정":"옳음","설명":"공용부분에 대한 공유지분은 전유부분과 분리하여 처분할 수 없다(제13조제2항)."},{"번호":4,"판정":"틀림","설명":"대지사용권의 분리 처분 금지에는 ‘규약으로 달리 정한 경우에는 그러하지 아니하다’는 단서가 있다(제20조제2항). 규약으로 정하면 분리 처분할 수 있다."},{"번호":5,"판정":"옳음","설명":"일부공용부분은 그들 구분소유자의 공유에 속한다(제10조제1항 단서)."}],"개념":[{"종류":"표","제목":"전유부분과의 일체성 (집합건물법 제12조·제13조·제20조)","머리":["대상","원칙","예외·보호"],"행":[["공용부분 공유지분","전유부분의 처분에 따르고, 분리하여 처분할 수 없음 (제13조)","공용부분에 관한 물권의 득실변경은 등기 불요 (제13조제3항)"],["공유지분 비율","각 공유자가 가지는 전유부분의 면적 비율 (제12조제1항)","규약으로 달리 정할 수 있는 사항은 제12조·제17조 (제10조제2항)"],["대지사용권","전유부분의 처분에 따르고, 분리 처분 금지 (제20조제1항·제2항 본문)","규약으로 달리 정하면 분리 처분 가능 (제20조제2항 단서)"],["분리처분금지의 대항력","취지를 등기하지 않으면 선의로 물권을 취득한 제3자에게 대항하지 못함 (제20조제3항)","-"]]},{"종류":"비교","제목":"법정 공용부분과 규약상 공용부분","왼쪽":{"이름":"법정 공용부분","항목":["구조상 독립성이 없는 복도·계단 등 (제3조제1항)","구분소유권의 목적이 될 수 없음","공용부분이라는 취지의 등기 불필요","일부의 구분소유자만 공용하는 것이 명백하면 그들의 공유 (제10조제1항 단서)"]},"오른쪽":{"이름":"규약상 공용부분","항목":["독립성이 있는 건물부분과 부속건물을 규약이나 공정증서로 공용부분으로 정함 (제3조제2항·제3항)","공용부분이라는 취지를 등기해야 함 (제3조제4항)"]}}],"함정":"분리 처분 금지는 공용부분 지분과 대지사용권에 모두 붙지만, 규약으로 풀 수 있는 것은 대지사용권뿐이다. 공용부분 지분은 규약으로도 분리 처분할 수 없다."}},{"i":"S3-2-1-중개사법-40","r":"S3","g":2,"c":2,"n":40,"s":"중개사법","q":"법원은 X부동산에 대하여 담보권 실행을 위한 경매절차를 개시하는 결정을 내렸고, 최저매각가격을 2억원으로 정하였다. 기일입찰로 진행되는 이 경매에서 매수신청을 하고자 하는 중개의뢰인 甲에게 개업공인중개사가 설명한 내용으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["甲이 2억 4천만원에 매수신청을 하려는 경우, 법원에서 달리 정함이 없으면 2천 4백만원을 보증금액으로 제공하여야 한다.","최고가매수신고를 한 사람이 2명인 때에는 집행관이 즉시 추첨으로 최고가매수신고인을 정한다.","최고가매수신고를 한 사람들이 다시 입찰하는 경우 전의 입찰가격에 못 미치는 가격으로도 입찰할 수 있다.","3억원의 최고가매수신고인이 있는 경우, 법원에서 보증금액을 달리 정하지 않았다면 甲이 차순위매수신고를 하기 위해서는 신고액이 2억 8천만원을 넘어야 한다.","최고가매수신고인과 차순위매수신고인이 아닌 매수신고인은 매각허가결정이 확정된 후에야 매수신청의 보증을 돌려 달라고 신청할 수 있다."],"a":[4],"L":"중3-3","o":"변형","x":{"한줄":"보증금액은 최저매각가격의 10분의 1인 2천만원이다. 차순위매수신고는 신고액이 최고가매수신고액에서 보증액을 뺀 금액(3억원 - 2천만원 = 2억 8천만원)을 넘을 때만 할 수 있다.","근거":[{"법령":"민사집행규칙","조문":"제63조 제1항 제2항","원문":"①기일입찰에서 매수신청의 보증금액은 최저매각가격의 10분의 1로 한다.\n②법원은 상당하다고 인정하는 때에는 보증금액을 제1항과 달리 정할 수 있다."},{"법령":"민사집행규칙","조문":"제66조 제1항 제2항","원문":"①최고가매수신고를 한 사람이 둘 이상인 때에는 집행관은 그 사람들에게 다시 입찰하게 하여 최고가매수신고인을 정한다. 이 경우 입찰자는 전의 입찰가격에 못미치는 가격으로는 입찰할 수 없다.\n②제1항의 규정에 따라 다시 입찰하는 경우에 입찰자 모두가 입찰에 응하지 아니하거나(전의 입찰가격에 못미치는 가격으로 입찰한 경우에는 입찰에 응하지 아니한 것으로 본다) 두 사람 이상이 다시 최고의 가격으로 입찰한 때에는 추첨으로 최고가매수신고인을 정한다."},{"법령":"민사집행법","조문":"제114조 제2항","원문":"②차순위매수신고는 그 신고액이 최고가매수신고액에서 그 보증액을 뺀 금액을 넘는 때에만 할 수 있다."},{"법령":"민사집행법","조문":"제115조 제3항","원문":"③최고가매수신고인과 차순위매수신고인을 제외한 다른 매수신고인은 제1항의 고지에 따라 매수의 책임을 벗게 되고, 즉시 매수신청의 보증을 돌려 줄 것을 신청할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"기일입찰의 보증금액은 입찰가격이 아니라 최저매각가격(2억원)의 10분의 1인 2천만원이다(민사집행규칙 제63조제1항)."},{"번호":2,"판정":"틀림","설명":"최고가매수신고를 한 사람이 둘 이상이면 먼저 그 사람들에게 다시 입찰하게 한다. 추첨은 재입찰에서도 최고가가 같을 때 하는 절차다(민사집행규칙 제66조제1항·제2항)."},{"번호":3,"판정":"틀림","설명":"다시 입찰하는 경우 전의 입찰가격에 못 미치는 가격으로는 입찰할 수 없다(민사집행규칙 제66조제1항 후문)."},{"번호":4,"판정":"옳음","설명":"차순위매수신고는 신고액이 최고가매수신고액에서 그 보증액을 뺀 금액을 넘어야 한다(민사집행법 제114조제2항). 3억원 - 2천만원 = 2억 8천만원이다."},{"번호":5,"판정":"틀림","설명":"최고가매수신고인과 차순위매수신고인을 제외한 다른 매수신고인은 매각기일 종결 고지에 따라 매수 책임을 벗고 즉시 보증을 돌려 달라고 신청할 수 있다(민사집행법 제115조제3항)."}],"개념":[{"종류":"계산","제목":"보증금액과 차순위매수신고 하한 계산","단계":[{"설명":"보증금액 = 최저매각가격 × 1/10","식":"2억원 × 1/10","값":"2,000만원"},{"설명":"최고가매수신고액에서 보증액을 뺀다","식":"3억원 - 2,000만원","값":"2억 8,000만원"},{"설명":"차순위매수신고는 이 금액을 넘는 신고액만 가능하다","식":"신고액 > 2억 8,000만원","값":"2억 8,000만원 이하는 신고 불가"},{"설명":"흔한 오답: 입찰가격의 10분의 1을 보증금액으로 계산","식":"2억 4천만원 × 1/10","값":"2,400만원 (틀림)"}]},{"종류":"흐름","제목":"기일입찰의 진행","단계":[{"이름":"입찰표 제출","설명":"매각기일에 입찰표와 보증을 집행관에게 낸다. 입찰은 취소·변경·교환할 수 없다 (민사집행규칙 제62조·제64조)."},{"이름":"입찰 마감·개찰","설명":"입찰표 제출을 최고한 후 1시간이 지나야 마감할 수 있고, 개찰 때 입찰자를 참여시킨다 (제65조)."},{"이름":"최고가매수신고인 결정","설명":"최고가가 같은 사람이 둘 이상이면 그들끼리 재입찰. 재입찰에서도 같으면 추첨 (제66조)."},{"이름":"차순위매수신고","설명":"매각기일 종결 전에 신고. 신고액이 최고가매수신고액에서 보증액을 뺀 금액을 넘어야 한다 (민사집행법 제114조)."},{"이름":"매각기일 종결","설명":"최고가·차순위 외의 매수신고인은 즉시 보증을 돌려받을 수 있다 (민사집행법 제115조제3항)."},{"이름":"매각결정기일","설명":"법원이 이해관계인의 의견을 듣고 매각허가 여부를 정한다 (민사집행법 제120조·제128조)."}]}],"함정":"보증금액은 최저매각가격 기준이고, 법원이 달리 정할 수 있다. 차순위매수신고 하한은 최고가에서 보증액을 뺀 금액 ‘초과’이므로 같은 금액은 신고할 수 없다."}},{"i":"S3-2-1-공법-01","r":"S3","g":2,"c":2,"n":41,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 광역도시계획에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["국토교통부장관이 광역계획권을 지정하려면 관계 시·도지사, 시장 또는 군수의 의견을 들은 후 지방도시계획위원회의 심의를 거쳐야 한다.","광역계획권이 같은 도의 관할 구역에 속하는 경우, 광역계획권을 지정한 날부터 3년이 지날 때까지 관할 시장 또는 군수로부터 광역도시계획의 승인 신청이 없으면 관할 도지사가 광역도시계획을 수립한다.","도지사가 직접 수립하거나 관할 시장 또는 군수와 공동으로 수립하는 광역도시계획은 국토교통부장관의 승인을 받아야 한다.","광역도시계획안에 대하여 의견을 요청받은 시·도, 시 또는 군의 의회와 관계 시장 또는 군수는 특별한 사유가 없으면 60일 이내에 의견을 제시하여야 한다.","광역계획권은 인접한 둘 이상의 특별시·광역시·시 또는 군의 관할 구역 전부를 포함하도록 지정하여야 하며, 그 일부만을 광역계획권에 포함시킬 수는 없다."],"a":[2],"L":"공1-1","o":"변형","x":{"한줄":"광역계획권을 지정한 날부터 3년이 지나도록 시장·군수의 승인 신청이 없으면 관할 도지사가 광역도시계획을 수립한다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제11조제1항","원문":"① 국토교통부장관, 시ㆍ도지사, 시장 또는 군수는 다음 각 호의 구분에 따라 광역도시계획을 수립하여야 한다.\n  1. 광역계획권이 같은 도의 관할 구역에 속하여 있는 경우: 관할 시장 또는 군수가 공동으로 수립\n  2. 광역계획권이 둘 이상의 시ㆍ도의 관할 구역에 걸쳐 있는 경우: 관할 시ㆍ도지사가 공동으로 수립\n  3. 광역계획권을 지정한 날부터 3년이 지날 때까지 관할 시장 또는 군수로부터 제16조제1항에 따른 광역도시계획의 승인 신청이 없는 경우: 관할 도지사가 수립"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제10조제3항","원문":"③ 국토교통부장관은 광역계획권을 지정하거나 변경하려면 관계 시ㆍ도지사, 시장 또는 군수의 의견을 들은 후 중앙도시계획위원회의 심의를 거쳐야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제16조제1항","원문":"① 시ㆍ도지사는 광역도시계획을 수립하거나 변경하려면 국토교통부장관의 승인을 받아야 한다. 다만, 제11조제3항에 따라 도지사가 수립하는 광역도시계획은 그러하지 아니하다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제15조제3항","원문":"③ 제1항과 제2항에 따른 시ㆍ도, 시 또는 군의 의회와 관계 시장 또는 군수는 특별한 사유가 없으면 30일 이내에 시ㆍ도지사, 시장 또는 군수에게 의견을 제시하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제10조제1항","원문":"① 국토교통부장관 또는 도지사는 … 인접한 둘 이상의 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 관할 구역 전부 또는 일부를 대통령령으로 정하는 바에 따라 광역계획권으로 지정할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"국토교통부장관이 광역계획권을 지정하거나 변경할 때 거치는 위원회는 중앙도시계획위원회다. 지방도시계획위원회는 도지사가 지정할 때의 위원회다(법 제10조제3항·제4항)."},{"번호":2,"판정":"옳음","설명":"같은 도 안의 광역계획권은 원래 시장·군수가 공동 수립한다. 지정일부터 3년이 지나도록 승인 신청이 없으면 도지사가 넘겨받아 수립한다(법 제11조제1항제3호)."},{"번호":3,"판정":"틀림","설명":"제11조제3항에 따라 도지사가 수립하는 광역도시계획은 국토교통부장관의 승인을 받지 않는다(법 제16조제1항 단서). 승인 대상은 시·도지사가 수립하는 경우다."},{"번호":4,"판정":"틀림","설명":"의견 제시 기한은 30일이다(법 제15조제3항)."},{"번호":5,"판정":"틀림","설명":"광역계획권은 관할 구역의 전부 또는 일부를 대상으로 지정한다(법 제10조제1항). 일부만 포함시킬 수도 있다."}],"개념":[{"종류":"표","제목":"광역도시계획의 수립권자·승인권자","머리":["광역계획권의 범위","수립권자","승인","위원회 심의"],"행":[["같은 도의 관할 구역 안","관할 시장·군수 공동","도지사 승인(법 제16조제5항)","지방도시계획위원회(법 제16조제6항)"],["같은 도 안, 지정일부터 3년 내 승인 신청 없음","관할 도지사","승인 없음(법 제16조제1항 단서)","지방도시계획위원회"],["도지사가 시장·군수 요청으로 공동 수립","도지사와 시장·군수","승인 없음(법 제16조제1항 단서)","지방도시계획위원회"],["둘 이상의 시·도에 걸침","관할 시·도지사 공동","국토교통부장관 승인(법 제16조제1항)","중앙도시계획위원회(법 제16조제2항)"],["국가계획 관련, 또는 지정일부터 3년 내 시·도지사의 승인 신청 없음","국토교통부장관","직접 수립","중앙도시계획위원회"],["광역계획권의 지정·변경","국토교통부장관(둘 이상의 시·도) 또는 도지사","-","국토교통부장관은 중앙도시계획위원회, 도지사는 지방도시계획위원회(법 제10조제3항·제4항)"]]},{"종류":"흐름","제목":"광역도시계획의 수립 절차","단계":[{"이름":"기초조사","설명":"인구·경제·토지이용 등을 조사하고, 정보체계를 구축한 뒤 5년마다 현황을 확인한다(법 제13조)."},{"이름":"공청회","설명":"수립·변경 전에 주민과 전문가의 의견을 듣고, 타당하면 반영한다(법 제14조)."},{"이름":"의견 청취","설명":"관계 의회와 시장·군수의 의견을 듣는다. 기한은 30일이다(법 제15조)."},{"이름":"협의·심의·승인","설명":"관계 중앙행정기관 협의(30일 이내 의견)와 도시계획위원회 심의를 거쳐 승인한다(법 제16조제2항·제3항)."},{"이름":"공고·열람","설명":"관계 서류를 송부받은 시·도지사가 내용을 공고하고 일반이 열람하게 한다(법 제16조제4항)."}]}],"함정":"승인 면제를 도지사 직접 수립이 아니라 시·도지사 전반으로 넓혀 읽거나, 국토교통부장관 지정에 지방도시계획위원회를 붙이는 선지를 고르기 쉽다. 위원회는 지정·승인권자의 급(국토교통부장관은 중앙, 도지사는 지방)에 맞춘다."}},{"i":"S3-2-1-공법-02","r":"S3","g":2,"c":2,"n":42,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 도시ㆍ군관리계획의 결정에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["도시ㆍ군관리계획 결정의 효력은 지형도면을 고시한 날의 다음 날부터 발생한다.","시가화조정구역의 지정에 관한 도시ㆍ군관리계획 결정 당시 이미 사업에 착수한 자는 그 결정에도 불구하고 신고 없이 그 사업을 계속할 수 있다.","국토교통부장관이 도시ㆍ군관리계획을 직접 입안한 경우에는 시ㆍ도지사가 지형도면을 작성하여야 한다.","시장ㆍ군수가 입안한 지구단위계획의 수립에 관한 도시ㆍ군관리계획은 시장ㆍ군수의 신청에 따라 도지사가 결정한다.","시ㆍ도지사는 국가계획과 관련되어 국토교통부장관이 입안하여 결정한 도시ㆍ군관리계획을 변경하려면 미리 국토교통부장관과 협의하여야 한다."],"a":[5],"L":"공1-2","o":"기출","x":{"한줄":"국토교통부장관이 입안·결정한 도시·군관리계획을 시·도지사가 변경하려면 미리 국토교통부장관과 협의한다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제30조제2항","원문":"② 시ㆍ도지사는 제24조제5항에 따라 국토교통부장관이 입안하여 결정한 도시ㆍ군관리계획을 변경하거나 그 밖에 대통령령으로 정하는 중요한 사항에 관한 도시ㆍ군관리계획을 결정하려면 미리 국토교통부장관과 협의하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제31조제1항","원문":"① 도시ㆍ군관리계획 결정의 효력은 제32조제4항에 따라 지형도면을 고시한 날부터 발생한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제31조제2항","원문":"② … 다만, 시가화조정구역이나 수산자원보호구역의 지정에 관한 도시ㆍ군관리계획 결정이 있는 경우에는 대통령령으로 정하는 바에 따라 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수에게 신고하고 그 사업이나 공사를 계속할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제32조제3항","원문":"③ 국토교통부장관(제40조에 따른 수산자원보호구역의 경우 해양수산부장관을 말한다. 이하 이 조에서 같다)이나 도지사는 도시ㆍ군관리계획을 직접 입안한 경우에는 제1항과 제2항에도 불구하고 관계 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수의 의견을 들어 직접 지형도면을 작성할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제29조제1항","원문":"① … 다음 각 호의 도시ㆍ군관리계획은 시장 또는 군수가 직접 결정한다.\n  1. 시장 또는 군수가 입안한 지구단위계획구역의 지정ㆍ변경과 지구단위계획의 수립ㆍ변경에 관한 도시ㆍ군관리계획"}],"선지":[{"번호":1,"판정":"틀림","설명":"효력은 지형도면을 고시한 날부터 생긴다. 다음 날이 아니다(법 제31조제1항)."},{"번호":2,"판정":"틀림","설명":"시가화조정구역·수산자원보호구역 지정 결정 당시 이미 착수한 사업은 시장·군수 등에게 신고하고 계속한다. 이 두 구역에만 신고 의무가 붙는다(법 제31조제2항 단서)."},{"번호":3,"판정":"틀림","설명":"국토교통부장관이나 도지사가 직접 입안한 계획은 그 입안자가 관계 시장·군수의 의견을 들어 직접 지형도면을 작성할 수 있다(법 제32조제3항)."},{"번호":4,"판정":"틀림","설명":"시장·군수가 입안한 지구단위계획 관련 도시·군관리계획은 시장·군수가 직접 결정한다(법 제29조제1항제1호)."},{"번호":5,"판정":"옳음","설명":"국토교통부장관이 국가계획과 관련해 입안·결정한 계획을 시·도지사가 변경할 때는 사전 협의를 거친다(법 제30조제2항)."}],"개념":[{"종류":"표","제목":"도시·군관리계획의 결정권자","머리":["구분","결정권자","근거"],"행":[["일반 도시·군관리계획","시·도지사(직접 또는 시장·군수의 신청)","법 제29조제1항"],["인구 50만 이상 대도시","해당 대도시 시장","법 제29조제1항"],["시장·군수가 입안한 지구단위계획구역 지정·변경, 지구단위계획 수립·변경","시장 또는 군수","법 제29조제1항제1호"],["국토교통부장관이 입안한 계획","국토교통부장관","법 제29조제2항제1호"],["개발제한구역의 지정·변경","국토교통부장관","법 제29조제2항제2호"],["시가화조정구역(국가계획과 연계해 필요한 경우)","국토교통부장관","법 제29조제2항제3호, 제39조제1항 단서"],["수산자원보호구역","1제곱킬로미터 이상 공유수면은 해양수산부장관, 인접 토지·1제곱킬로미터 미만 공유수면은 시·도지사","법 제29조제2항제4호"]]},{"종류":"흐름","제목":"도시·군관리계획의 입안에서 효력 발생까지","단계":[{"이름":"입안","설명":"입안권자가 기초조사와 환경성 검토를 거쳐 계획도서·계획설명서를 만든다(법 제24조, 제25조, 제27조)."},{"이름":"의견 청취","설명":"주민과 지방의회의 의견을 듣는다(법 제28조)."},{"이름":"협의·심의","설명":"관계 행정기관과 협의한다. 협의 기관은 30일 이내에 의견을 낸다. 이어 도시계획위원회 심의를 거친다(법 제30조제1항·제3항)."},{"이름":"결정·고시","설명":"결정권자가 결정 내용을 고시하고 관계 서류를 열람하게 한다(법 제30조제6항)."},{"이름":"지형도면 고시","설명":"시장·군수가 만든 지형도면은 도지사가 승인한다. 이후 지형도면을 고시한다(법 제32조제2항·제4항)."},{"이름":"효력 발생","설명":"지형도면을 고시한 날부터 효력이 생긴다(법 제31조제1항)."}]}],"함정":"효력 발생을 결정 고시일이나 지형도면 고시 다음 날로 잡는 오답이 많다. 지형도면 고시일 당일부터다. 국토교통부장관 입안분의 지형도면을 시·도지사가 작성한다고 단정하는 선지도 흔하다."}},{"i":"S3-2-1-공법-03","r":"S3","g":2,"c":2,"n":43,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 용도지구 안에서의 건축제한 등에 관한 설명으로 옳은 것은? (단, 건축물은 도시ㆍ군계획시설이 아님)","b":null,"bs":"없음","img":[],"ch":["경관지구 안에서의 건축물의 건폐율·용적률·높이·최대너비·색채는 도시·군계획조례로 정할 수 없고, 도시·군관리계획으로만 정하여야 한다.","고도지구 안에서는 시장·군수가 도시계획위원회의 심의를 거친 경우 도시·군관리계획으로 정하는 높이를 초과하는 건축물도 건축할 수 있다.","지구단위계획 또는 관계 법률에 따른 개발계획을 수립하는 개발진흥지구에서는 그 계획이 수립되기 전에도 해당 용도지역에서 허용되는 건축물을 모두 건축할 수 있다.","일반공업지역에 지정된 복합용도지구 안에서는 준공업지역에서 허용되는 건축물 중 도시·군계획조례가 정하는 건축물을 건축할 수 있으나, 아파트는 건축할 수 없다.","보호지구 안에서는 도시·군계획조례가 정하는 건축물에 한하여 건축할 수 있고, 어떠한 경우에도 그 밖의 건축물은 건축할 수 없다."],"a":[4],"L":"공1-3","o":"변형","x":{"한줄":"일반공업지역의 복합용도지구에서는 준공업지역 허용 건축물 중 조례가 정한 것을 건축할 수 있지만 아파트는 제외된다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제81조","원문":"법 제76조제5항제1호의3에 따라 복합용도지구에서는 해당 용도지역에서 허용되는 건축물 외에 다음 각 호에 따른 건축물 중 도시ㆍ군계획조례가 정하는 건축물을 건축할 수 있다.\n  2. 일반공업지역: 준공업지역에서 허용되는 건축물. 다만 다음 각 목의 건축물은 제외한다.\n    가. 「건축법 시행령」 별표 1 제2호가목의 아파트\n    나. 「건축법 시행령」 별표 1 제4호의 제2종 근린생활시설 중 단란주점 및 안마시술소\n    다. 「건축법 시행령」 별표 1 제11호의 노유자시설"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제72조제2항","원문":"② 경관지구안에서의 건축물의 건폐율ㆍ용적률ㆍ높이ㆍ최대너비ㆍ색채 및 대지안의 조경 등에 관하여는 그 지구의 경관의 보전ㆍ관리ㆍ형성에 필요한 범위안에서 도시ㆍ군계획조례로 정한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제74조","원문":"고도지구안에서는 도시ㆍ군관리계획으로 정하는 높이를 초과하는 건축물을 건축할 수 없다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제79조제1항","원문":"① 법 제76조제5항제1호의2에 따라 지구단위계획 또는 관계 법률에 따른 개발계획을 수립하는 개발진흥지구에서는 지구단위계획 또는 관계 법률에 따른 개발계획에 위반하여 건축물을 건축할 수 없으며, 지구단위계획 또는 개발계획이 수립되기 전에는 개발진흥지구의 계획적 개발에 위배되지 아니하는 범위에서 도시ㆍ군계획조례로 정하는 건축물을 건축할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제76조","원문":"보호지구 안에서는 다음 각호의 구분에 따른 건축물에 한하여 건축할 수 있다. 다만, 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수가 지구의 지정목적에 위배되지 아니하는 범위안에서 도시ㆍ군계획조례가 정하는 기준에 적합하다고 인정하여 관계 행정기관의 장과의 협의 및 당해 지방자치단체에 설치된 도시계획위원회의 심의를 거친 경우에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"경관지구 안의 건폐율·용적률·높이·색채 등은 원칙적으로 도시·군계획조례가 정한다. 조례 기준을 그대로 적용하기 불합리하거나 목적 달성이 어려운 경우에 한해 지구 지정 도시·군관리계획으로 따로 정한다(영 제72조제2항·제3항)."},{"번호":2,"판정":"틀림","설명":"고도지구 안에서는 도시·군관리계획으로 정한 높이를 넘는 건축물을 짓지 못한다. 위원회 심의로 예외를 두는 규정은 없다(영 제74조)."},{"번호":3,"판정":"틀림","설명":"계획 수립 전에 건축할 수 있는 건축물은 개발진흥지구의 계획적 개발에 위배되지 않는 범위에서 조례가 정한 것이다(영 제79조제1항). 해당 용도지역 허용 건축물을 모두 지을 수 있는 경우는 계획을 수립하지 않는 개발진흥지구다(영 제79조제2항)."},{"번호":4,"판정":"옳음","설명":"일반공업지역의 복합용도지구는 준공업지역 허용 건축물을 기준으로 하되 아파트, 단란주점·안마시술소, 노유자시설을 뺀다(영 제81조제2호)."},{"번호":5,"판정":"틀림","설명":"보호지구도 지정목적에 위배되지 않고 조례 기준에 적합하면 관계 행정기관 협의와 도시계획위원회 심의를 거쳐 열거된 건축물 외의 건축물을 지을 수 있다(영 제76조 단서)."}],"개념":[{"종류":"표","제목":"용도지구의 세분과 건축제한 규정","머리":["용도지구","세분(영 제31조제2항)","건축제한 규정"],"행":[["경관지구","자연경관지구, 시가지경관지구, 특화경관지구","영 제72조(조례가 원칙, 관리계획으로 예외)"],["고도지구","-","영 제74조(관리계획이 정한 높이 초과 금지)"],["방재지구","시가지방재지구, 자연방재지구","영 제75조, 제83조제6항(1층 전부 필로티는 층수 제외)"],["보호지구","역사문화환경보호지구, 중요시설물보호지구, 생태계보호지구","영 제76조(조례가 정한 건축물만)"],["취락지구","자연취락지구, 보호취락지구, 집단취락지구","영 제78조(자연: 별표 23, 보호: 별표 23의2, 집단: 개발제한구역법령)"],["개발진흥지구","주거·산업유통·관광휴양·복합·특정 개발진흥지구","영 제79조"],["특정용도제한지구","-","영 제80조(조례가 정한 건축물 금지)"],["복합용도지구","-","영 제81조(지정 가능: 일반주거·일반공업·계획관리)"]]},{"종류":"표","제목":"복합용도지구의 지정 용도지역과 건축 가능 범위","머리":["지정 용도지역","추가로 건축할 수 있는 건축물(조례가 정하는 것)","제외되는 건축물"],"행":[["일반주거지역","준주거지역에서 허용되는 건축물","안마시술소, 관람장, 공장, 위험물 저장·처리시설, 동물·식물 관련 시설, 장례시설"],["일반공업지역","준공업지역에서 허용되는 건축물","아파트, 단란주점·안마시술소, 노유자시설"],["계획관리지역","일반음식점·휴게음식점·제과점, 판매시설, 숙박시설, 테마파크업 시설 등","별표 20의 제한에 걸리는 음식점·숙박시설"],["지정 기준","해당 용도지역 전체 면적의 3분의 1 이하","영 제31조제7항제3호"]]}],"함정":"복합용도지구를 완화 지구로만 외우면 일반주거지역의 장례시설처럼 제외 목록을 놓친다. 제외되는 건축물은 용도지역마다 다르다. 보호지구와 고도지구는 둘 다 건축제한이 엄해 보이지만 예외 단서는 보호지구에만 있다.","개정":"시행령 제78조제2항이 2025.7.1 신설되어 취락지구에 보호취락지구가 추가되었다(영 제31조제2항제7호나목, 제78조제2항, 별표 23의2). 이 문항의 정답 판단에는 영향이 없다."}},{"i":"S3-2-1-공법-04","r":"S3","g":2,"c":2,"n":44,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 용도구역에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["개발제한구역의 지정 및 변경에 관한 도시·군관리계획은 시·도지사가 결정한다.","시가화조정구역의 시가화 유보기간은 5년 이상 20년 이내의 범위에서 도시·군관리계획으로 정한다.","시가화조정구역의 지정에 관한 도시·군관리계획 결정은 시가화 유보기간이 끝난 날부터 그 효력을 잃는다.","도시자연공원구역의 지정 또는 변경은 국토교통부장관이 도시·군관리계획으로 결정한다.","도시혁신구역의 지정 및 변경은 도시·군관리계획으로 결정한다."],"a":[2],"L":"공1-3","o":"변형","x":{"한줄":"시가화조정구역의 유보기간은 5년 이상 20년 이내이고, 이 기간은 도시·군관리계획에 담아 정한다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제32조제1항·제2항","원문":"① 법 제39조제1항 본문에서 \"대통령령으로 정하는 기간\"이란 5년 이상 20년 이내의 기간을 말한다.\n② 국토교통부장관 또는 시ㆍ도지사는 법 제39조제1항에 따라 시가화조정구역을 지정 또는 변경하고자 하는 때에는 … 도시ㆍ군관리계획으로 시가화유보기간을 정하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제39조제2항","원문":"② 시가화조정구역의 지정에 관한 도시ㆍ군관리계획의 결정은 제1항에 따른 시가화 유보기간이 끝난 날의 다음날부터 그 효력을 잃는다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제29조제2항제2호","원문":"② 제1항에도 불구하고 다음 각 호의 도시ㆍ군관리계획은 국토교통부장관이 결정한다. …\n  2. 제38조에 따른 개발제한구역의 지정 및 변경에 관한 도시ㆍ군관리계획"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제38조의2제1항","원문":"① 시ㆍ도지사 또는 대도시 시장은 도시의 자연환경 및 경관을 보호하고 도시민에게 건전한 여가ㆍ휴식공간을 제공하기 위하여 도시지역 안에서 식생(植生)이 양호한 산지(山地)의 개발을 제한할 필요가 있다고 인정하면 도시자연공원구역의 지정 또는 변경을 도시ㆍ군관리계획으로 결정할 수 있다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제40조의3제3항","원문":"③ 제1항에 따른 도시혁신구역의 지정 및 변경과 제2항에 따른 도시혁신계획은 다음 각 호의 사항을 종합적으로 고려하여 공간재구조화계획으로 결정한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"개발제한구역은 국토교통부장관이 결정한다(법 제29조제2항제2호, 제38조제1항)."},{"번호":2,"판정":"옳음","설명":"시가화 유보기간은 5년 이상 20년 이내이며 도시·군관리계획으로 정한다(영 제32조제1항·제2항)."},{"번호":3,"판정":"틀림","설명":"유보기간이 끝난 날의 다음 날부터 효력을 잃는다(법 제39조제2항)."},{"번호":4,"판정":"틀림","설명":"도시자연공원구역은 시·도지사 또는 대도시 시장이 결정한다(법 제38조의2제1항)."},{"번호":5,"판정":"틀림","설명":"도시혁신구역은 도시·군관리계획이 아니라 공간재구조화계획으로 결정한다(법 제40조의3제3항)."}],"개념":[{"종류":"표","제목":"용도구역의 종류와 결정 주체","머리":["용도구역","결정권자","결정 수단","핵심 내용"],"행":[["개발제한구역","국토교통부장관","도시·군관리계획","도시의 무질서한 확산 방지, 보안상 개발 제한(법 제38조)"],["도시자연공원구역","시·도지사 또는 대도시 시장","도시·군관리계획","도시지역 안 식생이 양호한 산지의 개발 제한(법 제38조의2)"],["시가화조정구역","시·도지사(국가계획과 연계 시 국토교통부장관)","도시·군관리계획","유보기간 5년 이상 20년 이내(법 제39조, 영 제32조)"],["수산자원보호구역","해양수산부장관 또는 시·도지사","도시·군관리계획","수산자원의 보호·육성(법 제40조)"],["도시혁신구역","공간재구조화계획 결정권자","공간재구조화계획","도심·부도심, 생활권 중심지역 등(법 제40조의3)"],["복합용도구역","공간재구조화계획 결정권자","공간재구조화계획","복합적 토지이용이 필요한 지역(법 제40조의4)"],["도시·군계획시설입체복합구역","도시·군관리계획 결정권자","도시·군관리계획","건폐율·용적률은 용도지역별 최대한도의 200퍼센트 이하(법 제40조의5제3항)"]]},{"종류":"흐름","제목":"시가화조정구역의 지정부터 실효까지","단계":[{"이름":"지정","설명":"시·도지사가 도시·군관리계획으로 결정한다. 국가계획과 연계가 필요하면 국토교통부장관이 직접 결정한다(법 제39조제1항)."},{"이름":"유보기간 설정","설명":"인구 동태·토지이용·산업발전상황을 고려해 5년 이상 20년 이내로 정한다(영 제32조)."},{"이름":"기존 사업","설명":"결정 당시 이미 착수한 사업·공사는 시장·군수 등에게 신고하고 계속한다(법 제31조제2항 단서)."},{"이름":"실효","설명":"유보기간이 끝난 날의 다음 날 효력을 잃는다(법 제39조제2항)."},{"이름":"실효 고시","설명":"국토교통부장관은 관보·홈페이지에, 시·도지사는 공보·홈페이지에 실효일자·사유·내용을 게재한다(영 제32조제3항)."}]}],"함정":"결정 주체를 한 덩어리로 외우면 개발제한구역과 도시자연공원구역을 서로 바꾼다. 개발제한구역만 국토교통부장관이고 도시자연공원구역은 시·도지사다. 2024.2.6 이후 도시혁신구역·복합용도구역은 관리계획이 아니라 공간재구조화계획으로 정한다.","개정":"2024.2.6 개정으로 입지규제최소구역(제40조의2)이 삭제되고 도시혁신구역(제40조의3), 복합용도구역(제40조의4), 도시·군계획시설입체복합구역(제40조의5)이 생겼다."}},{"i":"S3-2-1-공법-05","r":"S3","g":2,"c":2,"n":45,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 용도지역 안에서의 건폐율의 범위로 틀린 것은? (단, 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["자연녹지지역에 지정된 개발진흥지구: 30퍼센트 이하","수산자원보호구역: 40퍼센트 이하","「자연공원법」에 따른 자연공원: 60퍼센트 이하","계획관리지역에 지정된 산업ㆍ유통개발진흥지구: 40퍼센트 이하","공업지역에 있는 「산업입지 및 개발에 관한 법률」에 따른 준산업단지: 80퍼센트 이하"],"a":[4],"L":"공1-4","o":"기출","x":{"한줄":"계획관리지역에 지정된 산업·유통개발진흥지구의 건폐율은 40퍼센트가 아니라 60퍼센트 이하다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제84조제4항제2호","원문":"2. 개발진흥지구: 다음 각 목에서 정하는 비율 이하\n    가. 도시지역 외의 지역에 지정된 경우: 40퍼센트. 다만, 계획관리지역에 제31조제2항제8호나목에 따른 산업ㆍ유통개발진흥지구가 지정된 경우에는 60퍼센트로 한다.\n    나. 자연녹지지역에 지정된 경우: 30퍼센트"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제84조제4항제3호·제4호","원문":"3. 수산자원보호구역 : 40퍼센트 이하\n  4. 「자연공원법」에 따른 자연공원 : 60퍼센트 이하"},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제84조제4항제6호","원문":"6. 공업지역에 있는 「산업입지 및 개발에 관한 법률」 제2조제8호가목부터 다목까지의 규정에 따른 국가산업단지ㆍ일반산업단지ㆍ도시첨단산업단지 및 같은 조 제12호에 따른 준산업단지: 80퍼센트 이하"}],"선지":[{"번호":1,"판정":"옳음","설명":"자연녹지지역에 지정된 개발진흥지구는 30퍼센트 이하다(영 제84조제4항제2호나목)."},{"번호":2,"판정":"옳음","설명":"수산자원보호구역은 40퍼센트 이하다(영 제84조제4항제3호)."},{"번호":3,"판정":"옳음","설명":"자연공원은 60퍼센트 이하다(영 제84조제4항제4호)."},{"번호":4,"판정":"틀림","설명":"계획관리지역의 산업·유통개발진흥지구는 60퍼센트 이하다. 40퍼센트는 도시지역 외 개발진흥지구의 일반 비율이고, 이 경우만 60퍼센트로 올라간다(영 제84조제4항제2호가목 단서)."},{"번호":5,"판정":"옳음","설명":"공업지역의 국가·일반·도시첨단산업단지와 준산업단지는 80퍼센트 이하다(영 제84조제4항제6호)."}],"개념":[{"종류":"표","제목":"용도지역별 건폐율과 용적률의 범위(영 제84조제1항, 제85조제1항)","머리":["용도지역","건폐율(이하)","용적률"],"행":[["제1종전용주거지역","50퍼센트","50퍼센트 이상 100퍼센트 이하"],["제2종전용주거지역","50퍼센트","50퍼센트 이상 150퍼센트 이하"],["제1종일반주거지역","60퍼센트","100퍼센트 이상 200퍼센트 이하"],["제2종일반주거지역","60퍼센트","100퍼센트 이상 250퍼센트 이하"],["제3종일반주거지역","50퍼센트","100퍼센트 이상 300퍼센트 이하"],["준주거지역","70퍼센트","200퍼센트 이상 500퍼센트 이하"],["중심상업지역","90퍼센트","200퍼센트 이상 1천500퍼센트 이하"],["일반상업지역","80퍼센트","200퍼센트 이상 1천300퍼센트 이하"],["근린상업지역","70퍼센트","200퍼센트 이상 900퍼센트 이하"],["유통상업지역","80퍼센트","200퍼센트 이상 1천100퍼센트 이하"],["전용공업지역","70퍼센트","150퍼센트 이상 300퍼센트 이하"],["일반공업지역","70퍼센트","150퍼센트 이상 350퍼센트 이하"],["준공업지역","70퍼센트","150퍼센트 이상 400퍼센트 이하"],["보전녹지지역","20퍼센트","50퍼센트 이상 80퍼센트 이하"],["생산녹지지역","20퍼센트","50퍼센트 이상 100퍼센트 이하"],["자연녹지지역","20퍼센트","50퍼센트 이상 100퍼센트 이하"],["보전관리지역","20퍼센트","50퍼센트 이상 80퍼센트 이하"],["생산관리지역","20퍼센트","50퍼센트 이상 80퍼센트 이하"],["계획관리지역","40퍼센트","50퍼센트 이상 100퍼센트 이하"],["농림지역","20퍼센트","50퍼센트 이상 80퍼센트 이하"],["자연환경보전지역","20퍼센트","50퍼센트 이상 80퍼센트 이하"]]},{"종류":"표","제목":"용도지역과 별도로 정한 건폐율(영 제84조제4항)","머리":["대상","건폐율(이하)"],"행":[["취락지구","60퍼센트(집단취락지구는 개발제한구역법령에 따름)"],["개발진흥지구 - 도시지역 외","40퍼센트(계획관리지역의 산업·유통개발진흥지구는 60퍼센트)"],["개발진흥지구 - 자연녹지지역","30퍼센트"],["수산자원보호구역","40퍼센트"],["자연공원","60퍼센트"],["농공단지","70퍼센트(기반시설이 충분하면 80퍼센트)"],["공업지역의 국가·일반·도시첨단산업단지, 준산업단지","80퍼센트"]]}],"함정":"40퍼센트라는 숫자가 계획관리지역의 일반 건폐율과 같아서 맞는 것처럼 보인다. 산업·유통개발진흥지구에 한해 계획관리지역이 60퍼센트로 올라간다."}},{"i":"S3-2-1-공법-06","r":"S3","g":2,"c":2,"n":46,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 기반시설의 종류와 그 해당 시설의 연결이 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["교통시설 - 차량 검사 및 면허시설","공간시설 - 녹지","유통ㆍ공급시설 - 방송ㆍ통신시설","공공ㆍ문화체육시설 - 학교","보건위생시설 - 폐기물처리 및 재활용시설"],"a":[5],"L":"공1-5","o":"기출","x":{"한줄":"폐기물처리 및 재활용시설은 보건위생시설이 아니라 환경기초시설이다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제2조제1항","원문":"1. 교통시설 : 도로ㆍ철도ㆍ항만ㆍ공항ㆍ주차장ㆍ자동차정류장ㆍ궤도ㆍ차량 검사 및 면허시설\n  2. 공간시설 : 광장ㆍ공원ㆍ녹지ㆍ유원지ㆍ공공공지\n  3. 유통ㆍ공급시설 : 유통업무설비, 수도ㆍ전기ㆍ가스ㆍ열공급설비, 방송ㆍ통신시설, 공동구ㆍ시장, 유류저장 및 송유설비\n  4. 공공ㆍ문화체육시설 : 학교ㆍ공공청사ㆍ문화시설ㆍ공공필요성이 인정되는 체육시설ㆍ연구시설ㆍ사회복지시설ㆍ공공직업훈련시설ㆍ청소년수련시설\n  6. 보건위생시설 : 장사시설ㆍ도축장ㆍ종합의료시설\n  7. 환경기초시설 : 하수도ㆍ폐기물처리 및 재활용시설ㆍ빗물저장 및 이용시설ㆍ수질오염방지시설ㆍ폐차장"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제2조제6호","원문":"6. \"기반시설\"이란 다음 각 목의 시설로서 대통령령으로 정하는 시설을 말한다. … 바. 장사시설 등 보건위생시설 사. 하수도, 폐기물처리 및 재활용시설, 빗물저장 및 이용시설 등 환경기초시설"}],"선지":[{"번호":1,"판정":"옳음","설명":"차량 검사 및 면허시설은 교통시설이다(영 제2조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"녹지는 광장·공원·유원지·공공공지와 함께 공간시설이다(영 제2조제1항제2호)."},{"번호":3,"판정":"옳음","설명":"방송·통신시설은 유통·공급시설에 속한다(영 제2조제1항제3호)."},{"번호":4,"판정":"옳음","설명":"학교는 공공·문화체육시설이다(영 제2조제1항제4호)."},{"번호":5,"판정":"틀림","설명":"보건위생시설은 장사시설·도축장·종합의료시설이다. 폐기물처리 및 재활용시설은 하수도와 함께 환경기초시설이다(영 제2조제1항제6호·제7호)."}],"개념":[{"종류":"표","제목":"기반시설 7종류(법 제2조제6호, 영 제2조제1항)","머리":["종류","해당 시설"],"행":[["교통시설","도로, 철도, 항만, 공항, 주차장, 자동차정류장, 궤도, 차량 검사 및 면허시설"],["공간시설","광장, 공원, 녹지, 유원지, 공공공지"],["유통·공급시설","유통업무설비, 수도·전기·가스·열공급설비, 방송·통신시설, 공동구, 시장, 유류저장 및 송유설비"],["공공·문화체육시설","학교, 공공청사, 문화시설, 공공필요성이 인정되는 체육시설, 연구시설, 사회복지시설, 공공직업훈련시설, 청소년수련시설"],["방재시설","하천, 유수지, 저수지, 방화설비, 방풍설비, 방수설비, 사방설비, 방조설비"],["보건위생시설","장사시설, 도축장, 종합의료시설"],["환경기초시설","하수도, 폐기물처리 및 재활용시설, 빗물저장 및 이용시설, 수질오염방지시설, 폐차장"]]},{"종류":"표","제목":"도시·군관리계획 결정 없이 설치할 수 있는 기반시설(영 제35조제1항)","머리":["지역","시설"],"행":[["도시지역 또는 지구단위계획구역","주차장, 차량 검사 및 면허시설, 공공공지, 열공급설비, 방송·통신시설, 시장·공공청사·문화시설·체육시설·연구시설·사회복지시설·공공직업훈련시설·청소년수련시설, 저수지, 방화·방풍·방수·사방·방조설비, 장사시설, 종합의료시설, 빗물저장 및 이용시설, 폐차장"],["도시지역 및 지구단위계획구역 외의 지역","위 시설에 더해 궤도, 전기공급설비"],["공통","「도시공원 및 녹지 등에 관한 법률」에 따라 점용허가 대상이 되는 공원 안의 기반시설과 국토교통부령으로 정하는 시설"]]}],"함정":"폐기물처리시설을 위생 계열로 묶어 보건위생시설에 넣기 쉽다. 장사시설·도축장·종합의료시설만 보건위생시설이고 나머지 오염 처리 시설은 환경기초시설이다."}},{"i":"S3-2-1-공법-07","r":"S3","g":2,"c":2,"n":47,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 도시ㆍ군계획시설에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["공동구관리자는 5년마다 해당 공동구의 안전 및 유지관리계획을 수립·시행하여야 한다.","공동구관리자는 1년에 2회 이상 공동구의 안전점검을 실시하여야 한다.","도시·군계획시설 부지의 매수 청구를 받은 매수의무자는 그 청구를 받은 날부터 3개월 이내에 매수 여부를 결정하여 토지 소유자에게 알려야 한다.","도시·군계획시설 부지의 매수 청구에서 매수하기로 결정한 토지는 매수 결정을 알린 날부터 3년 이내에 매수하여야 한다.","도시·군계획시설결정이 고시된 날부터 20년이 되는 날까지 도시·군계획시설사업이 시행되지 아니하면 그 20년이 되는 날에 도시·군계획시설결정의 효력을 잃는다."],"a":[1],"L":"공1-5","o":"변형","x":{"한줄":"공동구관리자는 5년마다 공동구의 안전 및 유지관리계획을 세워 시행한다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제44조의2제2항·제3항","원문":"② 공동구관리자는 5년마다 해당 공동구의 안전 및 유지관리계획을 대통령령으로 정하는 바에 따라 수립ㆍ시행하여야 한다.\n③ 공동구관리자는 대통령령으로 정하는 바에 따라 1년에 1회 이상 공동구의 안전점검을 실시하여야 하며, 안전점검결과 이상이 있다고 인정되는 때에는 지체 없이 정밀안전진단ㆍ보수ㆍ보강 등 필요한 조치를 하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제47조제6항","원문":"⑥ 매수의무자는 제1항에 따른 매수 청구를 받은 날부터 6개월 이내에 매수 여부를 결정하여 토지 소유자와 … 알려야 하며, 매수하기로 결정한 토지는 매수 결정을 알린 날부터 2년 이내에 매수하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제48조제1항","원문":"① 도시ㆍ군계획시설결정이 고시된 도시ㆍ군계획시설에 대하여 그 고시일부터 20년이 지날 때까지 그 시설의 설치에 관한 도시ㆍ군계획시설사업이 시행되지 아니하는 경우 그 도시ㆍ군계획시설결정은 그 고시일부터 20년이 되는 날의 다음날에 그 효력을 잃는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"안전 및 유지관리계획의 주기는 5년이다(법 제44조의2제2항)."},{"번호":2,"판정":"틀림","설명":"안전점검은 1년에 1회 이상이다(법 제44조의2제3항)."},{"번호":3,"판정":"틀림","설명":"매수 여부는 청구를 받은 날부터 6개월 이내에 결정해 알린다(법 제47조제6항)."},{"번호":4,"판정":"틀림","설명":"매수하기로 결정한 토지는 결정을 알린 날부터 2년 이내에 매수한다(법 제47조제6항)."},{"번호":5,"판정":"틀림","설명":"효력은 고시일부터 20년이 되는 날의 다음 날에 잃는다(법 제48조제1항)."}],"개념":[{"종류":"표","제목":"도시·군계획시설 관련 기간·숫자","머리":["항목","내용","근거"],"행":[["매수 청구 요건","결정 고시일부터 10년 이내에 시설사업 미시행(실시계획 인가 등이 진행되면 제외), 지목이 대(垈)인 토지","법 제47조제1항"],["매수 여부 결정","청구를 받은 날부터 6개월 이내","법 제47조제6항"],["매수 기한","매수 결정을 알린 날부터 2년 이내","법 제47조제6항"],["지급 방법","현금이 원칙. 지방자치단체가 매수의무자이면 채권 발행 가능, 채권 상환기간 10년 이내","법 제47조제2항·제3항"],["지방의회 보고","결정 고시일부터 10년이 지나도록 미시행","법 제48조제3항"],["해제를 위한 입안 신청","10년 미시행이고 단계별 집행계획상 실효 시까지 집행계획이 없을 때. 입안권자는 3개월 이내 입안 여부 통지","법 제48조의2제1항·제2항"],["결정권자에게 해제 신청","결정권자는 신청을 받은 날부터 2개월 이내 결정 여부 통지","법 제48조의2제3항·제4항"],["실효","고시일부터 20년이 되는 날의 다음 날","법 제48조제1항"],["공동구 설치 규모","도시개발구역 등이 200만 제곱미터 초과","영 제35조의2제1항"]]},{"종류":"흐름","제목":"매수 청구에서 건축 허용까지","단계":[{"이름":"청구","설명":"고시일부터 10년이 지나도록 시설사업이 시행되지 않으면 지목이 대인 토지의 소유자가 매수의무자에게 매수를 청구한다(법 제47조제1항)."},{"이름":"매수 여부 결정","설명":"청구를 받은 날부터 6개월 이내에 매수 여부를 정해 토지 소유자에게 알린다(법 제47조제6항)."},{"이름":"매수","설명":"매수하기로 했다면 결정을 알린 날부터 2년 이내에 매수한다. 대금은 현금이 원칙이다(법 제47조제2항·제6항)."},{"이름":"불매수·미이행","설명":"매수하지 않기로 결정했거나 2년이 지나도록 매수하지 않으면 소유자는 허가를 받아 일정한 건축물·공작물을 설치할 수 있다(법 제47조제7항)."},{"이름":"설치 가능 건축물","설명":"3층 이하의 단독주택, 3층 이하의 제1종 근린생활시설 등과 공작물이다(영 제41조제5항)."}]}],"함정":"10년·20년·6개월·2년 같은 숫자를 서로 바꿔 쓴 선지가 반복해서 나온다. 매수 청구는 10년, 결정 실효는 20년이며, 20년은 그날이 아니라 다음 날 효력이 사라진다."}},{"i":"S3-2-1-공법-08","r":"S3","g":2,"c":2,"n":48,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 개발행위허가(이하 '허가'라 함)에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["도시ㆍ군계획사업에 의하여 10층 이상의 건축물을 건축하려는 경우에는 허가를 받아야 한다.","건축물의 건축에 대한 허가를 받은 자가 그 건축을 완료하고 ｢건축법｣에 따른 건축물의 사용승인을 받은 경우 허가권자의 준공검사를 받지 않아도 된다.","허가를 받은 건축물의 연면적을 5퍼센트 범위에서 축소하려는 경우에는 허가권자에게 미리 신고하여야 한다.","허가의 신청이 있는 경우 특별한 사유가 없으면 도시계획위원회의 심의 또는 기타 협의 기간을 포함하여 15일 이내에 허가 또는 불허가의 처분을 하여야 한다.","국토교통부장관이 지구단위계획구역으로 지정된 지역에 대하여 허가의 제한을 연장하려면 중앙도시계획위원회의 심의를 거쳐야 한다."],"a":[2],"L":"공1-7","o":"기출","x":{"한줄":"개발행위허가를 받아 건축한 뒤 건축법상 사용승인을 받았다면 개발행위 준공검사는 받지 않는다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제62조제1항","원문":"① 제56조제1항제1호부터 제3호까지의 행위에 대한 개발행위허가를 받은 자는 그 개발행위를 마치면 국토교통부령으로 정하는 바에 따라 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수의 준공검사를 받아야 한다. 다만, 같은 항 제1호의 행위에 대하여 「건축법」 제22조에 따른 건축물의 사용승인을 받은 경우에는 그러하지 아니하다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제56조제1항","원문":"① … 다만, 도시ㆍ군계획사업(다른 법률에 따라 도시ㆍ군계획사업을 의제한 사업을 포함한다)에 의한 행위는 그러하지 아니하다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제52조제1항·제2항","원문":"① 법 제56조제2항 단서에서 \"대통령령으로 정하는 경미한 사항을 변경하는 경우\"란 … 다음 각 호의 어느 하나에 해당하는 경우 …\n  2. 다음 각 목의 어느 하나에 해당하는 경우\n    가. 부지면적 또는 건축물 연면적을 5퍼센트 범위에서 축소[…]하는 경우\n② 개발행위허가를 받은 자는 제1항 각호의 1에 해당하는 경미한 사항을 변경한 때에는 지체없이 그 사실을 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장 또는 군수에게 통지하여야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제54조제1항","원문":"① 법 제57조제2항에서 \"대통령령으로 정하는 기간\"이란 15일(도시계획위원회의 심의를 거쳐야 하거나 관계 행정기관의 장과 협의를 하여야 하는 경우에는 심의 또는 협의기간을 제외한다)을 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제63조제1항","원문":"① … 다만, 제3호부터 제5호까지에 해당하는 지역에 대해서는 중앙도시계획위원회나 지방도시계획위원회의 심의를 거치지 아니하고 한 차례만 2년 이내의 기간 동안 개발행위허가의 제한을 연장할 수 있다.\n  4. 지구단위계획구역으로 지정된 지역"}],"선지":[{"번호":1,"판정":"틀림","설명":"도시·군계획사업에 의한 행위는 개발행위허가를 받지 않는다. 도시·군계획사업의 인가 단계에서 이미 걸러지기 때문이다(법 제56조제1항 단서)."},{"번호":2,"판정":"옳음","설명":"제56조제1항제1호의 건축에 대해 건축법 제22조의 사용승인을 받으면 준공검사를 따로 받지 않는다(법 제62조제1항 단서)."},{"번호":3,"판정":"틀림","설명":"건축물 연면적을 5퍼센트 범위에서 줄이는 것은 경미한 변경이다. 변경허가도 신고도 필요 없고, 변경한 뒤 지체 없이 통지만 한다(영 제52조제1항제2호가목, 제2항)."},{"번호":4,"판정":"틀림","설명":"처분 기간은 15일이다. 위원회 심의나 관계기관 협의에 걸린 기간은 이 15일에 넣지 않는다(영 제54조제1항)."},{"번호":5,"판정":"틀림","설명":"지구단위계획구역에 대한 허가 제한은 위원회 심의 없이 2년 이내에 한 번 연장할 수 있다(법 제63조제1항 단서)."}],"개념":[{"종류":"표","제목":"개발행위허가의 규모(토지 형질변경 면적, 영 제55조제1항)","머리":["용도지역","규모"],"행":[["주거지역·상업지역·자연녹지지역·생산녹지지역","1만 제곱미터 미만"],["공업지역","3만 제곱미터 미만"],["보전녹지지역","5천 제곱미터 미만"],["관리지역","3만 제곱미터 미만(조례로 달리 정할 수 있음)"],["농림지역","3만 제곱미터 미만(조례로 달리 정할 수 있음)"],["자연환경보전지역","5천 제곱미터 미만"]]},{"종류":"흐름","제목":"개발행위허가의 절차","단계":[{"이름":"신청","설명":"기반시설 설치, 위해 방지, 환경오염 방지, 경관·조경 계획서를 붙여 신청한다. 개발밀도관리구역에서는 기반시설 계획서가 빠진다(법 제57조제1항)."},{"이름":"심의·협의","설명":"대통령령이 정한 개발행위는 중앙·지방도시계획위원회 심의를 거친다(법 제59조)."},{"이름":"처분","설명":"15일 이내에 허가 또는 불허가한다. 위원회 심의와 관계기관 협의 기간은 제외한다(영 제54조제1항)."},{"이름":"조건·이행보증","설명":"허가에 조건을 붙이려면 신청인의 의견을 듣는다. 필요하면 이행보증금을 예치하게 한다(영 제54조제2항, 법 제60조제1항)."},{"이름":"준공검사","설명":"건축물 사용승인을 받은 건축은 준공검사를 받지 않는다(법 제62조제1항)."}]}],"함정":"경미한 변경을 신고 대상으로 외우기 쉽다. 5퍼센트 범위 축소는 허가·신고 모두 불필요하고 통지만 한다. 허가 제한 연장에서 중앙도시계획위원회 심의 여부는 제한 사유별로 다르다."}},{"i":"S3-2-1-공법-09","r":"S3","g":2,"c":2,"n":49,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 개발행위허가에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["농림지역에 물건을 1개월 이상 쌓아놓는 행위는 개발행위허가의 대상이 아니다.","「사방사업법」에 따른 사방사업을 위한 개발행위에 대하여 허가를 하는 경우 중앙도시계획위원회와 지방도시계획위원회의 심의를 거치지 아니한다.","일정 기간 동안 개발행위허가를 제한할 수 있는 대상지역에 지구단위계획구역은 포함되지 않는다.","기반시설부담구역으로 지정된 지역에 대해서는 중앙도시계획위원회나 지방도시계획위원회의 심의를 거치지 아니하고 개발행위허가의 제한을 연장할 수 있다.","개발행위허가의 제한을 연장하는 경우 그 연장 기간은 2년을 넘을 수 없다."],"a":[3],"L":"공1-7","o":"기출","x":{"한줄":"지구단위계획구역으로 지정된 지역도 개발행위허가 제한 대상 지역에 포함된다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제63조제1항","원문":"① … 다음 각 호의 어느 하나에 해당되는 지역으로서 도시ㆍ군관리계획상 특히 필요하다고 인정되는 지역에 대해서는 … 한 차례만 3년 이내의 기간 동안 개발행위허가를 제한할 수 있다. 다만, 제3호부터 제5호까지에 해당하는 지역에 대해서는 중앙도시계획위원회나 지방도시계획위원회의 심의를 거치지 아니하고 한 차례만 2년 이내의 기간 동안 개발행위허가의 제한을 연장할 수 있다.\n  4. 지구단위계획구역으로 지정된 지역\n  5. 기반시설부담구역으로 지정된 지역"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제56조제1항제5호","원문":"5. 녹지지역ㆍ관리지역 또는 자연환경보전지역에 물건을 1개월 이상 쌓아놓는 행위"},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제59조제2항제7호","원문":"② 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 개발행위는 중앙도시계획위원회와 지방도시계획위원회의 심의를 거치지 아니한다.\n  7. 「산림자원의 조성 및 관리에 관한 법률」에 따른 산림사업 및 「사방사업법」에 따른 사방사업을 위한 개발행위"}],"선지":[{"번호":1,"판정":"옳음","설명":"물건을 쌓아놓는 행위가 허가 대상인 곳은 녹지지역·관리지역·자연환경보전지역이다. 농림지역은 빠진다(법 제56조제1항제5호)."},{"번호":2,"판정":"옳음","설명":"사방사업을 위한 개발행위는 도시계획위원회 심의 면제 대상이다(법 제59조제2항제7호)."},{"번호":3,"판정":"틀림","설명":"지구단위계획구역으로 지정된 지역은 허가 제한 대상 지역의 하나다(법 제63조제1항제4호)."},{"번호":4,"판정":"옳음","설명":"기반시설부담구역은 제3호부터 제5호에 해당하여 위원회 심의 없이 연장할 수 있다(법 제63조제1항 단서)."},{"번호":5,"판정":"옳음","설명":"연장은 한 차례, 2년 이내다(법 제63조제1항 단서)."}],"개념":[{"종류":"표","제목":"개발행위허가 제한 대상 지역(법 제63조제1항)","머리":["호","지역","제한(위원회 심의 필요)","연장"],"행":[["제1호","녹지지역·계획관리지역으로서 수목이 집단적으로 자라거나 조수류가 집단 서식하는 지역, 우량 농지 등 보전 필요 지역","한 차례 3년 이내","법에 연장 규정 없음"],["제2호","개발행위로 주변 환경·경관·미관·국가유산이 크게 오염·손상될 우려가 있는 지역","한 차례 3년 이내","법에 연장 규정 없음"],["제3호","도시·군기본계획 또는 도시·군관리계획 수립 중이고 결정되면 용도지역 등이 변경되어 허가 기준이 크게 달라질 지역","한 차례 3년 이내","심의 없이 한 차례 2년 이내"],["제4호","지구단위계획구역으로 지정된 지역","한 차례 3년 이내","심의 없이 한 차례 2년 이내"],["제5호","기반시설부담구역으로 지정된 지역","한 차례 3년 이내","심의 없이 한 차례 2년 이내"]]},{"종류":"표","제목":"도시계획위원회 심의를 거치지 않는 개발행위(법 제59조제2항)","머리":["호","개발행위"],"행":[["1","제8조·제9조 또는 다른 법률에 따라 도시계획위원회의 심의를 받는 구역에서 하는 개발행위"],["2","지구단위계획 또는 성장관리계획을 수립한 지역에서 하는 개발행위"],["3","주거·상업·공업지역에서 하는 개발행위 중 조례가 정한 규모·위치에 해당하지 않는 것"],["4","환경영향평가를 받은 개발행위"],["5","교통영향평가에 대한 검토를 받은 개발행위"],["6","농어촌정비사업 중 대통령령으로 정하는 사업을 위한 개발행위"],["7","산림사업 및 사방사업을 위한 개발행위"]]}],"함정":"허가 제한 대상 5개 지역 가운데 지구단위계획구역을 빠뜨리기 쉽다. 연장 규정과 심의 면제는 제3호부터 제5호에만 있다."}},{"i":"S3-2-1-공법-10","r":"S3","g":2,"c":2,"n":50,"s":"공법","q":"국토의 계획 및 이용에 관한 법령상 개발행위에 따른 기반시설의 설치에 관한 설명으로 옳은 것은? (단, 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["시장 또는 군수가 개발밀도관리구역을 변경하는 경우 관할 지방도시계획위원회의 심의를 거치지 않아도 된다.","기반시설부담구역의 지정고시일부터 2년이 되는 날까지 기반시설설치계획을 수립하지 아니하면 그 2년이 되는 날에 기반시설부담구역의 지정은 해제된 것으로 본다.","시장 또는 군수는 기반시설설치비용 납부의무자가 지방자치단체로부터 건축허가를 받은 날부터 3개월 이내에 기반시설설치비용을 부과하여야 한다.","시장 또는 군수는 개발밀도관리구역에서는 해당 용도지역에 적용되는 용적률의 최대한도의 50퍼센트 범위에서 용적률을 강화하여 적용한다.","기반시설설치비용 납부의무자는 사용승인 신청 후 7일까지 그 비용을 내야 한다."],"a":[4],"L":"공1-8","o":"기출","x":{"한줄":"개발밀도관리구역에서는 해당 용도지역 용적률 최대한도의 50퍼센트 범위에서 용적률을 강화한다.","근거":[{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제62조제1항","원문":"① 법 제66조제2항에서 \"대통령령으로 정하는 범위\"란 해당 용도지역에 적용되는 용적률의 최대한도의 50퍼센트를 말한다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제66조제3항","원문":"③ … 개발밀도관리구역을 지정하거나 변경하려면 다음 각 호의 사항을 포함하여 해당 지방자치단체에 설치된 지방도시계획위원회의 심의를 거쳐야 한다."},{"법령":"국토의 계획 및 이용에 관한 법률 시행령","조문":"제65조제4항","원문":"④ 기반시설부담구역의 지정고시일부터 1년이 되는 날까지 기반시설설치계획을 수립하지 아니하면 그 1년이 되는 날의 다음날에 기반시설부담구역의 지정은 해제된 것으로 본다."},{"법령":"국토의 계획 및 이용에 관한 법률","조문":"제69조제2항","원문":"② … 납부의무자가 국가 또는 지방자치단체로부터 건축허가(…)를 받은 날부터 2개월 이내에 기반시설설치비용을 부과하여야 하고, 납부의무자는 사용승인(…) 신청 시까지 이를 내야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"개발밀도관리구역은 지정할 때도 변경할 때도 지방도시계획위원회 심의를 거친다(법 제66조제3항)."},{"번호":2,"판정":"틀림","설명":"기반시설설치계획 수립 기한은 지정고시일부터 1년이다. 그 1년이 되는 날의 다음 날 지정이 해제된 것으로 본다(영 제65조제4항)."},{"번호":3,"판정":"틀림","설명":"부과 기한은 건축허가를 받은 날부터 2개월 이내다(법 제69조제2항)."},{"번호":4,"판정":"옳음","설명":"강화 범위는 용적률 최대한도의 50퍼센트다(법 제66조제2항, 영 제62조제1항)."},{"번호":5,"판정":"틀림","설명":"납부 시기는 사용승인 신청 시까지다(법 제69조제2항)."}],"개념":[{"종류":"비교","제목":"개발밀도관리구역과 기반시설부담구역","왼쪽":{"이름":"개발밀도관리구역(법 제66조)","항목":["지정권자: 특별시장·광역시장·특별자치시장·특별자치도지사·시장·군수","대상: 주거·상업·공업지역에서 기반시설 설치가 곤란한 지역","효과: 건폐율·용적률 강화(용적률은 최대한도의 50퍼센트 범위)","절차: 지방도시계획위원회 심의, 지방자치단체 공보에 고시"]},"오른쪽":{"이름":"기반시설부담구역(법 제67조)","항목":["지정권자: 같음","대상: 법령 제정·개정이나 용도지역 변경으로 행위제한이 완화되는 지역, 전년도 개발행위허가 건수 20퍼센트 이상 증가 지역 등(영 제64조제1항)","효과: 기반시설설치비용 부과","절차: 주민 의견, 지방도시계획위원회 심의, 고시. 지정고시일부터 1년 내 기반시설설치계획 미수립 시 다음 날 해제로 간주","지정 규모: 최소 10만 제곱미터 이상(영 제66조)"]}},{"종류":"표","제목":"기반시설설치비용(법 제68조·제69조)","머리":["항목","내용"],"행":[["부과 대상","200제곱미터(기존 건축물 연면적 포함)를 초과하는 건축물의 신축·증축"],["기존 건축물 철거 후 신축","기존 연면적을 초과하는 건축행위만 부과 대상"],["민간 개발사업자 부담률","100분의 20(100분의 25의 범위에서 가감 가능)"],["용지환산계수","0.4 범위에서 조례로 정함"],["부과 시기","건축허가를 받은 날부터 2개월 이내"],["납부 시기","사용승인 신청 시까지"],["환급","사용승인 신청 후 기반시설 추가 설치 등 사유가 생기면 해당 비용 환급"]]}],"함정":"개발밀도관리구역과 기반시설부담구역은 이름이 비슷하다. 기반시설설치비용은 기반시설부담구역에서만 부과한다. 숫자는 1년(계획 수립), 2개월(부과), 신청 시까지(납부), 50퍼센트(용적률 강화)를 짝지어 둔다."}},{"i":"S3-2-1-공법-11","r":"S3","g":2,"c":2,"n":51,"s":"공법","q":"부동산 거래신고 등에 관한 법령상 토지거래계약에 관한 허가구역에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["국토교통부장관 또는 시·도지사는 10년 이내의 기간을 정하여 허가구역을 지정할 수 있다.","허가구역 안의 녹지지역에서 200제곱미터 이하의 토지에 관한 토지거래계약은, 지정권자가 면적을 따로 정하여 공고하지 않았다면 허가를 받지 않아도 된다.","시장·군수·구청장은 토지거래계약 허가신청서를 받은 날부터 30일 이내에 허가 또는 불허가의 처분을 하여야 한다.","허가신청에 대하여 불허가처분을 받은 자는 그 통지를 받은 날부터 3개월 이내에 시장·군수·구청장에게 해당 토지에 관한 권리의 매수를 청구할 수 있다.","허가구역이 둘 이상의 시·도의 관할 구역에 걸쳐 있는 경우에는 관계 시·도지사가 협의하여 허가구역을 지정한다."],"a":[2],"L":"공1-8","o":"변형","x":{"한줄":"허가구역 안의 녹지지역에서 200제곱미터 이하 토지는 면적을 따로 공고하지 않는 한 허가 대상이 아니다.","근거":[{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제9조제1항","원문":"① 법 제11조제2항제1호에서 \"대통령령으로 정하는 용도별 면적\"이란 다음 각 호의 구분에 따른 면적을 말한다. 다만, 국토교통부장관 또는 시ㆍ도지사가 허가구역을 지정할 당시 … 해당 기준면적의 10퍼센트 이상 300퍼센트 이하의 범위에서 따로 정하여 공고한 경우에는 그에 따른다.\n  1. 「국토의 계획 및 이용에 관한 법률」 제36조제1항제1호에 따른 도시지역(이하 \"도시지역\"이라 한다): 다음 각 목의 세부 용도지역별 구분에 따른 면적\n    가. 주거지역: 60제곱미터\n    나. 상업지역: 150제곱미터\n    다. 공업지역: 150제곱미터\n    라. 녹지지역: 200제곱미터\n    마. 가목부터 라목까지의 구분에 따른 용도지역의 지정이 없는 구역: 60제곱미터\n  2. 도시지역 외의 지역: 250제곱미터. 다만, 농지(…)의 경우에는 500제곱미터로 하고, 임야의 경우에는 1천제곱미터로 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제10조제1항","원문":"① 국토교통부장관 또는 시ㆍ도지사는 … 다음 각 호의 구분에 따라 5년 이내의 기간을 정하여 제11조제1항에 따른 토지거래계약에 관한 허가구역(…)으로 지정할 수 있다. …\n  1. 허가구역이 둘 이상의 시ㆍ도의 관할 구역에 걸쳐 있는 경우: 국토교통부장관이 지정\n  2. 허가구역이 동일한 시ㆍ도 안의 일부지역인 경우: 시ㆍ도지사가 지정. …"},{"법령":"부동산 거래신고 등에 관한 법률 시행령","조문":"제8조제3항","원문":"③ … 허가관청은 지체 없이 필요한 조사를 하고 신청서를 받은 날부터 15일 이내에 허가ㆍ변경허가 또는 불허가 처분을 하여야 한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제16조제1항","원문":"① 제11조제1항에 따른 허가신청에 대하여 불허가처분을 받은 자는 그 통지를 받은 날부터 1개월 이내에 시장ㆍ군수 또는 구청장에게 해당 토지에 관한 권리의 매수를 청구할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"지정 기간은 5년 이내다(법 제10조제1항)."},{"번호":2,"판정":"옳음","설명":"허가 면제 면적은 녹지지역 200제곱미터다. 지정권자가 지정 당시 기준면적의 10퍼센트 이상 300퍼센트 이하로 따로 정하여 공고하면 그 면적이 우선한다(영 제9조제1항)."},{"번호":3,"판정":"틀림","설명":"처분 기한은 신청서를 받은 날부터 15일이다(영 제8조제3항)."},{"번호":4,"판정":"틀림","설명":"매수 청구는 불허가 통지를 받은 날부터 1개월 이내에 한다(법 제16조제1항)."},{"번호":5,"판정":"틀림","설명":"둘 이상의 시·도에 걸치면 국토교통부장관이 지정한다(법 제10조제1항제1호)."}],"개념":[{"종류":"표","제목":"허가를 받지 않아도 되는 토지 면적(영 제9조제1항)","머리":["구분","면적"],"행":[["도시지역 - 주거지역","60제곱미터 이하"],["도시지역 - 상업지역","150제곱미터 이하"],["도시지역 - 공업지역","150제곱미터 이하"],["도시지역 - 녹지지역","200제곱미터 이하"],["도시지역 - 용도지역 지정이 없는 구역","60제곱미터 이하"],["도시지역 외","250제곱미터 이하(농지 500, 임야 1천 제곱미터 이하)"]]},{"종류":"표","제목":"허가구역과 허가절차의 기간","머리":["항목","기간·요건","근거"],"행":[["지정 기간","5년 이내","법 제10조제1항"],["지정 기관","둘 이상 시·도: 국토교통부장관. 동일 시·도 일부: 시·도지사","법 제10조제1항"],["지정 시 심의","중앙도시계획위원회 또는 시·도도시계획위원회","법 제10조제2항"],["효력 발생","공고한 날부터 5일 후","법 제10조제5항"],["공고·열람","시장·군수·구청장이 7일 이상 공고, 15일간 열람","법 제10조제4항"],["처분 기간","허가신청서를 받은 날부터 15일","영 제8조제3항"],["선매자 지정","신청이 있는 날부터 1개월 이내. 선매협의는 지정 통지를 받은 날부터 1개월 이내","법 제15조제2항"],["이의신청","처분을 받은 날부터 1개월 이내","법 제13조제1항"],["매수 청구","불허가 통지를 받은 날부터 1개월 이내","법 제16조제1항"]]}],"함정":"허가구역 지정권자를 시장·군수·구청장으로 착각하는 선지가 많다. 시장·군수·구청장은 허가권자이고 지정권자는 국토교통부장관 또는 시·도지사다. 면적 기준은 용도지역마다 다르다.","개정":"토지거래허가는 국토계획법에서 부동산 거래신고 등에 관한 법률로 옮겨졌다(제10조 이하). 허가 면제 면적의 용도지역별 구분은 같은 법 시행령 제9조제1항에 있다."}},{"i":"S3-2-1-공법-12","r":"S3","g":2,"c":2,"n":52,"s":"공법","q":"도시개발법령상 도시개발구역 지정권자가 속한 기관에 종사하는 자로부터 제공받은 미공개정보를 지정목적 외로 사용하여 1억 5천만원 상당의 재산상 이익을 얻은 자에게 벌금을 부과하는 경우 그 상한액은?","b":null,"bs":"없음","img":[],"ch":["1억 5천만원","4억 5천만원","5억원","7억 5천만원","10억원"],"a":[5],"L":"공2-1","o":"기출","x":{"한줄":"이익의 5배인 7억 5천만원이 10억원 이하이므로 벌금 상한은 10억원이 된다.","근거":[{"법령":"도시개발법","조문":"제79조의2제1항","원문":"① 제10조의2제2항 또는 제3항을 위반하여 미공개정보를 목적 외로 사용하거나 타인에게 제공 또는 누설한 자는 5년 이하의 징역 또는 그 위반행위로 얻은 재산상 이익 또는 회피한 손실액의 3배 이상 5배 이하에 상당하는 벌금에 처한다. 다만, 얻은 이익 또는 회피한 손실액이 없거나 산정하기 곤란한 경우 또는 그 위반행위로 얻은 재산상 이익의 5배에 해당하는 금액이 10억원 이하인 경우에는 벌금의 상한액을 10억원으로 한다."},{"법령":"도시개발법","조문":"제10조의2제3항","원문":"③ 제2항 각 호의 어느 하나에 해당하는 기관 또는 업체에 종사하였거나 종사하는 자 … 로부터 미공개정보를 제공받은 자 또는 미공개정보를 부정한 방법으로 취득한 자는 그 미공개정보를 도시개발구역의 지정 또는 지정 요청ㆍ제안 목적 외로 사용하거나 타인에게 제공 또는 누설해서는 아니 된다."}],"선지":[{"번호":1,"판정":"-","설명":"이익액 자체는 벌금의 한도 계산 기준일 뿐 상한액이 아니다. 벌금은 이익의 3배 이상 5배 이하 범위에서 정해진다."},{"번호":2,"판정":"-","설명":"이익 1억 5천만원의 3배가 4억 5천만원이다. 3배는 벌금 하한이다."},{"번호":3,"판정":"-","설명":"5억원은 벌금 계산에 쓰이는 값이 아니다. 이익이 5억원 이상일 때 징역을 3년 이상 유기징역으로 가중하는 기준액이다(법 제79조의2제2항제2호)."},{"번호":4,"판정":"-","설명":"이익 1억 5천만원의 5배가 7억 5천만원이다. 그러나 5배 금액이 10억원 이하이면 상한액은 10억원으로 올라간다(법 제79조의2제1항 단서)."},{"번호":5,"판정":"-","설명":"5배 금액 7억 5천만원이 10억원 이하이므로 단서가 적용되어 상한은 10억원이다."}],"개념":[{"종류":"표","제목":"도시개발구역의 지정대상 지역과 규모(영 제2조제1항)","머리":["지역","규모"],"행":[["도시지역 - 주거지역·상업지역","1만 제곱미터 이상"],["도시지역 - 공업지역","3만 제곱미터 이상"],["도시지역 - 자연녹지지역","1만 제곱미터 이상"],["도시지역 - 생산녹지지역(구역 면적의 100분의 30 이하인 경우만)","1만 제곱미터 이상"],["도시지역 외의 지역","30만 제곱미터 이상(아파트·연립주택 건설계획이 있고 초등학교용지 확보·도로 연결 요건을 갖추면 10만 제곱미터 이상)"]]},{"종류":"표","제목":"지정권자와 지정 해제","머리":["항목","내용","근거"],"행":[["지정권자","시·도지사, 인구 50만 이상 대도시 시장. 국가가 사업을 하는 경우 등에는 국토교통부장관","법 제3조제1항·제3항"],["구역 지정 후 개발계획 수립 시 해제","지정·고시일부터 2년이 되는 날까지 개발계획을 수립·고시하지 않으면 그날 다음 날 해제(면적 330만 제곱미터 이상은 5년)","법 제10조제2항제1호, 영 제17조제2항"],["실시계획 인가 신청 기한","지정·고시일(개발계획 수립·고시일)부터 3년이 되는 날까지 신청하지 않으면 해제(330만 제곱미터 이상은 5년)","법 제10조제1항제1호, 제2항제2호"],["공사 완료 시 해제","공사 완료(환지 방식은 환지처분) 공고일의 다음 날","법 제10조제1항제2호"],["공람 기간","관계 서류의 공람 14일 이상","영 제15조제4항"],["국토교통부장관 협의","구역 면적 50만 제곱미터 이상이거나 국가계획 관련","영 제14조의2제1항"]]}],"함정":"이익의 5배를 곧바로 상한으로 읽으면 7억 5천만원을 고른다. 5배 금액이 10억원 이하이면 상한을 10억원으로 끌어올리는 단서를 먼저 확인한다."}},{"i":"S3-2-1-공법-13","r":"S3","g":2,"c":2,"n":53,"s":"공법","q":"도시개발법령상 수용 또는 사용 방식으로 시행하는 도시개발사업의 시행자로 지정될 수 없는 자는?","b":null,"bs":"없음","img":[],"ch":["｢한국철도공사법｣에 따른 한국철도공사","지방자치단체","｢지방공기업법｣에 따라 설립된 지방공사","도시개발구역의 국공유지를 제외한 토지면적의 3분의 2이상을 소유한 자","도시개발구역의 토지 소유자가 도시개발을 위하여 설립한 조합"],"a":[5],"L":"공2-2","o":"기출","x":{"한줄":"조합은 사업 전부를 환지 방식으로 시행하는 경우에만 시행자가 되므로 수용·사용 방식의 시행자가 될 수 없다.","근거":[{"법령":"도시개발법","조문":"제11조제1항","원문":"① 도시개발사업의 시행자(…)는 다음 각 호의 자 중에서 지정권자가 지정한다. 다만, 도시개발구역의 전부를 환지 방식으로 시행하는 경우에는 제5호의 토지 소유자나 제6호의 조합을 시행자로 지정한다.\n  1. 국가나 지방자치단체\n  2. 대통령령으로 정하는 공공기관\n  4. 「지방공기업법」에 따라 설립된 지방공사\n  5. 도시개발구역의 토지 소유자(… 제21조에 따른 수용 또는 사용 방식의 경우에는 도시개발구역의 국공유지를 제외한 토지면적의 3분의 2 이상을 소유한 자를 말한다)\n  6. 도시개발구역의 토지 소유자(…)가 도시개발을 위하여 설립한 조합(도시개발사업의 전부를 환지 방식으로 시행하는 경우에만 해당하며, 이하 \"조합\"이라 한다)"},{"법령":"도시개발법 시행령","조문":"제18조제1항","원문":"① 법 제11조제1항제2호에서 \"대통령령으로 정하는 공공기관\"이란 다음 각 호의 공공기관을 말한다.\n  1. 「한국토지주택공사법」에 따른 한국토지주택공사 …\n  6. 「한국철도공사법」에 따른 한국철도공사"}],"선지":[{"번호":1,"판정":"옳음","설명":"한국철도공사는 시행령이 정한 공공기관이므로 시행자가 될 수 있다(영 제18조제1항제6호, 법 제11조제1항제2호)."},{"번호":2,"판정":"옳음","설명":"지방자치단체는 시행자다(법 제11조제1항제1호)."},{"번호":3,"판정":"옳음","설명":"지방공사는 시행자다(법 제11조제1항제4호)."},{"번호":4,"판정":"옳음","설명":"수용·사용 방식에서는 국공유지를 제외한 토지면적의 3분의 2 이상을 소유한 토지 소유자가 시행자가 될 수 있다(법 제11조제1항제5호)."},{"번호":5,"판정":"틀림","설명":"조합은 사업 전부를 환지 방식으로 시행하는 경우에만 해당한다(법 제11조제1항제6호)."}],"개념":[{"종류":"표","제목":"시행방식별 시행자","머리":["시행방식","시행자가 될 수 있는 자","근거"],"행":[["수용·사용 방식","국가·지방자치단체, 공공기관(한국토지주택공사, 한국수자원공사, 한국농어촌공사, 한국관광공사, 한국철도공사, 한국공항공사 등), 정부출연기관, 지방공사, 국공유지 제외 토지면적의 3분의 2 이상을 소유한 토지 소유자, 과밀억제권역 이전 법인, 주택 등록업자, 건설업자, 부동산개발업자, 부동산투자회사, 이들이 출자한 법인","법 제11조제1항제1호~제5호·제7호~제11호, 영 제18조"],["전부 환지 방식","토지 소유자 또는 조합을 시행자로 지정한다","법 제11조제1항 단서"],["조합","도시개발사업의 전부를 환지 방식으로 시행하는 경우에만","법 제11조제1항제6호"],["지방자치단체등 지정","토지 소유자·조합이 지정을 신청하지 않거나 신청이 부당한 경우, 공공시설 사업과 병행할 필요가 있는 경우, 국공유지 제외 토지면적의 2분의 1 이상 소유자와 소유자 총수의 2분의 1 이상이 동의한 경우","법 제11조제2항"]]},{"종류":"표","제목":"시행자 관련 동의·기간 요건","머리":["항목","요건","근거"],"행":[["조합 설립 인가 신청","토지면적의 3분의 2 이상 소유자와 토지 소유자 총수의 2분의 1 이상 동의","법 제13조제3항"],["환지 방식 개발계획 수립","환지 방식 지역 토지면적의 3분의 2 이상 소유자와 소유자 총수의 2분의 1 이상 동의","법 제4조제4항"],["수용·사용 방식의 민간 시행자","사업대상 토지면적의 3분의 2 이상 소유하고 토지 소유자 총수의 2분의 1 이상 동의","법 제22조제1항"],["구역 지정 제안 시 동의","대상 구역 토지면적의 3분의 2 이상 소유자(지상권자 포함) 동의","법 제11조제6항"],["시행자 변경 사유","실시계획 인가 후 2년 내 사업 미착수 등","법 제11조제8항제1호"]]}],"함정":"조합을 토지 소유자 단체이니 모든 방식의 시행자로 읽기 쉽다. 조합과 토지 소유자의 지위는 방식에 따라 달라진다. 수용·사용 방식에서 토지 소유자는 3분의 2 이상 소유 요건이 붙는다."}},{"i":"S3-2-1-공법-14","r":"S3","g":2,"c":2,"n":54,"s":"공법","q":"도시개발법령상 도시개발사업 조합에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["조합은 도시개발사업의 전부 또는 일부를 환지 방식으로 시행하는 경우 시행자가 될 수 있다.","조합설립의 인가를 받은 조합의 대표자는 설립인가를 받은 날부터 60일 이내에 주된 사무소의 소재지에서 설립등기를 하여야 한다.","의결권을 가진 조합원의 수가 30인 이상인 조합은 총회의 권한을 대행하게 하기 위하여 대의원회를 둘 수 있다.","조합원의 의결권은 보유 토지의 면적과 관계없이 평등하되, 다른 조합원으로부터 해당 도시개발구역에 가진 토지 소유권 전부를 이전받은 조합원은 정관으로 정하는 바에 따라 이전한 조합원의 의결권을 승계할 수 있다.","조합장 또는 이사의 자기를 위한 조합과의 계약이나 소송에 관하여는 조합장이 조합을 대표한다."],"a":[4],"L":"공2-2","o":"변형","x":{"한줄":"조합원의 의결권은 토지 면적과 무관하게 평등하고, 토지 소유권 전부를 이전받은 조합원은 정관에 따라 의결권을 승계할 수 있다.","근거":[{"법령":"도시개발법 시행령","조문":"제32조제2항","원문":"② 조합원의 권리 및 의무는 다음 각 호와 같다.\n  1. 보유토지의 면적과 관계없는 평등한 의결권. 다만, 다른 조합원으로부터 해당 도시개발구역에 그가 가지고 있는 토지 소유권 전부를 이전 받은 조합원은 정관으로 정하는 바에 따라 본래의 의결권과는 별도로 그 토지 소유권을 이전한 조합원의 의결권을 승계할 수 있다."},{"법령":"도시개발법","조문":"제11조제1항제6호","원문":"6. 도시개발구역의 토지 소유자 … 가 도시개발을 위하여 설립한 조합(도시개발사업의 전부를 환지 방식으로 시행하는 경우에만 해당하며, 이하 \"조합\"이라 한다)"},{"법령":"도시개발법 시행령","조문":"제32조제1항","원문":"① 법 제13조에 따라 조합의 설립인가를 받은 조합의 대표자는 설립인가를 받은 날부터 30일 이내에 주된 사무소의 소재지에서 설립등기를 하여야 한다."},{"법령":"도시개발법 시행령","조문":"제36조제1항","원문":"① 의결권을 가진 조합원의 수가 50인 이상인 조합은 총회의 권한을 대행하게 하기 위하여 대의원회를 둘 수 있다."},{"법령":"도시개발법 시행령","조문":"제34조제4항","원문":"④ 조합장 또는 이사의 자기를 위한 조합과의 계약이나 소송에 관하여는 감사가 조합을 대표한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"조합은 사업의 전부를 환지 방식으로 시행하는 경우에만 시행자가 된다(법 제11조제1항제6호)."},{"번호":2,"판정":"틀림","설명":"설립등기는 설립인가를 받은 날부터 30일 이내에 한다(영 제32조제1항)."},{"번호":3,"판정":"틀림","설명":"대의원회는 의결권을 가진 조합원이 50인 이상일 때 둘 수 있다(영 제36조제1항)."},{"번호":4,"판정":"옳음","설명":"평등한 의결권이 원칙이고, 토지 소유권 전부를 이전받은 조합원에게는 승계 예외가 있다(영 제32조제2항제1호)."},{"번호":5,"판정":"틀림","설명":"조합장 또는 이사가 자기를 위해 조합과 계약하거나 소송하는 경우에는 감사가 조합을 대표한다(영 제34조제4항)."}],"개념":[{"종류":"표","제목":"조합의 설립과 운영 수치","머리":["항목","내용","근거"],"행":[["설립 인가","토지 소유자 7명 이상이 정관을 작성해 지정권자의 인가를 받는다","법 제13조제1항"],["인가 신청 동의","토지면적의 3분의 2 이상 소유자와 소유자 총수의 2분의 1 이상","법 제13조제3항"],["설립등기","인가를 받은 날부터 30일 이내","영 제32조제1항"],["조합원","도시개발구역의 토지 소유자","법 제14조제1항"],["임원","조합장 1명, 이사, 감사. 의결권을 가진 조합원 중 총회에서 선임","영 제33조"],["임원 겸직","조합의 다른 임원이나 직원을 겸할 수 없고, 같은 목적의 사업을 하는 다른 조합의 임원·직원도 겸할 수 없다","법 제14조제2항, 영 제34조제5항"],["대의원회","의결권을 가진 조합원 50인 이상일 때 설치 가능, 대의원은 조합원 총수의 100분의 10 이상","영 제36조제1항·제2항"],["공유 토지","공유자의 동의를 받은 대표공유자 1명만 의결권","영 제32조제3항"]]},{"종류":"표","제목":"총회 의결사항과 대의원회 대행(영 제35조, 제36조제3항)","머리":["총회 의결사항","대의원회가 대행할 수 있는지"],"행":[["정관의 변경","대행 불가"],["개발계획 및 실시계획의 수립·변경","대행 불가(개발계획의 경미한 변경과 실시계획의 수립·변경은 대행 가능)"],["환지계획의 작성","대행 불가(환지계획의 경미한 변경은 대행 가능)"],["조합임원의 선임","대행 불가"],["조합의 합병 또는 해산","대행 불가(청산금 징수·교부 완료 후 해산은 총회 의결 대상이 아님)"],["자금의 차입, 수지예산, 부과금, 환지예정지의 지정, 체비지 처분방법","대행 가능"]]}],"함정":"조합 관련 기간과 인원 수가 서로 닮았다. 설립등기 30일, 대의원회 50인, 설립 발기 7명을 한 묶음으로 외운다. 계약·소송에서 조합을 대표하는 자는 감사다."}},{"i":"S3-2-1-공법-15","r":"S3","g":2,"c":2,"n":55,"s":"공법","q":"도시개발법령상 한국토지주택공사가 발행하려는 토지상환채권의 발행계획에 포함되어야 하는 사항이 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["보증기관 및 보증의 내용","토지가격의 추산방법","상환대상지역 또는 상환대상토지의 용도","토지상환채권의 발행가액 및 발행시기","토지상환채권의 발행총액"],"a":[1],"L":"공2-3","o":"기출","x":{"한줄":"보증기관 및 보증의 내용은 법 제11조제1항제5호부터 제11호까지에 해당하는 자가 발행하는 경우에만 발행계획에 들어간다.","근거":[{"법령":"도시개발법 시행령","조문":"제47조","원문":"법 제23조제2항에 따른 토지상환채권의 발행계획에는 다음 각 호의 사항이 포함되어야 한다.\n  1. 시행자의 명칭\n  2. 토지상환채권의 발행총액\n  3. 토지상환채권의 이율\n  4. 토지상환채권의 발행가액 및 발행시기\n  5. 상환대상지역 또는 상환대상토지의 용도\n  6. 토지가격의 추산방법\n  7. 보증기관 및 보증의 내용(법 제11조제1항제5호부터 제11호까지의 규정에 해당하는 자가 발행하는 경우에만 해당한다)"},{"법령":"도시개발법","조문":"제23조제1항","원문":"① 시행자는 토지 소유자가 원하면 토지등의 매수 대금의 일부를 지급하기 위하여 대통령령으로 정하는 바에 따라 사업 시행으로 조성된 토지ㆍ건축물로 상환하는 채권(…)을 발행할 수 있다. 다만, 제11조제1항제5호부터 제11호까지의 규정에 해당하는 자는 대통령령으로 정하는 금융기관 등으로부터 지급보증을 받은 경우에만 이를 발행할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"한국토지주택공사는 법 제11조제1항제2호의 공공기관이다. 보증기관 기재는 제5호~제11호에 해당하는 시행자에게만 요구된다(영 제47조제7호)."},{"번호":2,"판정":"옳음","설명":"토지가격의 추산방법은 발행계획 포함사항이다(영 제47조제6호)."},{"번호":3,"판정":"옳음","설명":"상환대상지역 또는 상환대상토지의 용도는 포함사항이다(영 제47조제5호)."},{"번호":4,"판정":"옳음","설명":"발행가액과 발행시기는 포함사항이다(영 제47조제4호)."},{"번호":5,"판정":"옳음","설명":"발행총액은 포함사항이다(영 제47조제2호)."}],"개념":[{"종류":"표","제목":"토지상환채권(법 제23조, 영 제45조~제54조)","머리":["항목","내용"],"행":[["발행 시기·목적","토지 소유자가 원하면 토지등의 매수 대금 일부를 사업으로 조성된 토지·건축물로 상환하는 채권을 발행"],["발행 규모","상환할 토지·건축물이 분양토지 또는 분양건축물 면적의 2분의 1을 초과하지 않도록 한다(영 제45조)"],["지급보증","법 제11조제1항제5호~제11호 시행자는 금융기관 등의 지급보증이 있어야 발행 가능. 보증기관은 은행, 보험회사, 공제조합(영 제46조)"],["발행계획 승인","지정권자가 시행자인 경우를 제외하고 미리 지정권자의 승인을 받는다(법 제23조제2항)"],["이율","발행 당시 은행 예금금리와 부동산 수급상황을 고려해 발행자가 정함(영 제49조제1항)"],["증권 형식","기명식 증권(영 제49조제2항)"]]},{"종류":"표","제목":"선수금·원형지·조성토지 공급","머리":["항목","내용","근거"],"행":[["선수금","조성토지등과 원형지를 공급받으려는 자로부터 대금 전부 또는 일부를 미리 받을 수 있다. 지정권자가 시행자인 경우를 제외하고 지정권자의 승인이 필요","법 제25조"],["공공 시행자의 선수금 요건","개발계획 수립·고시 후 사업시행 토지면적의 100분의 10 이상 소유권 확보(사용동의 포함)","영 제55조제1항제1호"],["원형지 공급 면적","도시개발구역 전체 토지 면적의 3분의 1 이내","법 제25조의2제1항"],["원형지개발자","국가·지방자치단체, 공공기관, 지방공사, 공모에서 선정된 자, 학교·공장 등 부지로 직접 사용하는 자","법 제25조의2제1항"],["원형지 매각 제한","공사완료 공고일부터 5년 또는 공급계약일부터 10년 중 먼저 끝나는 기간","영 제55조의2제3항"],["원형지 계약 해제","시행자가 2회 이상 시정을 요구하고도 시정하지 않은 경우","영 제55조의2제5항"],["조성토지등의 공급계획","지정권자가 아닌 시행자는 공급계획에 대해 지정권자의 승인을 받는다","법 제26조제1항"]]}],"함정":"발행계획 포함사항 7개 가운데 보증기관은 시행자 유형에 따라 붙는다. 공공 시행자에게는 지급보증 의무가 없으므로 보증 항목도 계획에서 빠진다."}},{"i":"S3-2-1-공법-16","r":"S3","g":2,"c":2,"n":56,"s":"공법","q":"도시개발법령상 환지 방식으로 도시개발사업을 시행하는 경우, 환지처분에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["환지 계획에서 환지를 정하지 아니한 종전의 토지에 있던 권리는 환지처분이 공고된 날의 다음 날에 소멸한다.","환지 예정지가 지정되면 종전의 토지의 소유자는 환지처분이 공고되는 날까지 종전의 토지를 계속 사용하거나 수익할 수 있다.","청산금은 환지처분이 공고된 날의 다음 날에 확정된다.","시행자는 환지처분이 공고되면 공고 후 30일 이내에 관할 등기소에 이를 알리고 토지와 건축물에 관한 등기를 촉탁하거나 신청하여야 한다.","환지처분 전에 이미 처분된 체비지는 환지처분이 공고된 날의 다음 날에 그 체비지를 매입한 자가 소유권을 취득한다."],"a":[3],"L":"공2-4","o":"변형","x":{"한줄":"청산금은 환지처분이 공고된 날의 다음 날에 확정된다.","근거":[{"법령":"도시개발법","조문":"제42조제6항","원문":"⑥ 제41조에 따른 청산금은 환지처분이 공고된 날의 다음 날에 확정된다."},{"법령":"도시개발법","조문":"제42조제1항","원문":"① 환지 계획에서 정하여진 환지는 그 환지처분이 공고된 날의 다음 날부터 종전의 토지로 보며, 환지 계획에서 환지를 정하지 아니한 종전의 토지에 있던 권리는 그 환지처분이 공고된 날이 끝나는 때에 소멸한다."},{"법령":"도시개발법","조문":"제36조제1항","원문":"① 환지 예정지가 지정되면 종전의 토지의 소유자와 임차권자등은 환지 예정지 지정의 효력발생일부터 환지처분이 공고되는 날까지 환지 예정지나 해당 부분에 대하여 종전과 같은 내용의 권리를 행사할 수 있으며 종전의 토지는 사용하거나 수익할 수 없다."},{"법령":"도시개발법","조문":"제43조제1항","원문":"① 시행자는 제40조제5항에 따라 환지처분이 공고되면 공고 후 14일 이내에 관할 등기소에 이를 알리고 토지와 건축물에 관한 등기를 촉탁하거나 신청하여야 한다."},{"법령":"도시개발법","조문":"제42조제5항","원문":"⑤ 제34조에 따른 체비지는 시행자가, 보류지는 환지 계획에서 정한 자가 각각 환지처분이 공고된 날의 다음 날에 해당 소유권을 취득한다. 다만, 제36조제4항에 따라 이미 처분된 체비지는 그 체비지를 매입한 자가 소유권 이전 등기를 마친 때에 소유권을 취득한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"환지를 정하지 않은 종전 토지의 권리는 공고된 날의 다음 날이 아니라 공고된 날이 끝나는 때 소멸한다(법 제42조제1항)."},{"번호":2,"판정":"틀림","설명":"환지 예정지가 지정되면 종전 토지는 사용·수익할 수 없고, 환지 예정지에서 종전과 같은 내용의 권리를 행사한다(법 제36조제1항)."},{"번호":3,"판정":"옳음","설명":"청산금은 환지처분 공고일의 다음 날에 확정된다(법 제42조제6항)."},{"번호":4,"판정":"틀림","설명":"등기 촉탁·신청은 공고 후 14일 이내에 한다(법 제43조제1항)."},{"번호":5,"판정":"틀림","설명":"이미 처분된 체비지는 매입한 자가 소유권 이전 등기를 마친 때 소유권을 취득한다(법 제42조제5항 단서)."}],"개념":[{"종류":"흐름","제목":"환지 방식 사업의 진행","단계":[{"이름":"환지 계획 작성","설명":"환지 설계, 환지 명세, 청산 대상 토지 명세, 체비지·보류지 명세를 정한다. 토지평가협의회 심의 전에 공인평가기관이 평가한다(법 제28조)."},{"이름":"공람·의견","설명":"토지 소유자와 임차권자등에게 알리고 14일 이상 공람한다. 의견서를 낸 자에게는 공람 종료일부터 60일 이내에 반영 여부를 통보한다(법 제29조제3항~제6항, 영 제61조제2항)."},{"이름":"인가","설명":"행정청이 아닌 시행자는 특별자치도지사·시장·군수·구청장의 인가를 받는다(법 제29조제1항)."},{"이름":"환지 예정지 지정","설명":"지정 효력발생일부터 환지처분 공고일까지 종전 토지는 사용·수익하지 못한다(법 제35조, 제36조)."},{"이름":"공사 완료 공고·공람","설명":"공사를 끝내면 관보·공보에 공고하고 서류를 14일 이상 공람하게 한다(법 제40조제1항, 영 제64조)."},{"이름":"준공검사·환지처분","설명":"준공검사를 받은 날부터 60일 이내에 환지처분을 하고 공고한다(법 제40조제4항·제5항, 영 제65조)."},{"이름":"등기","설명":"공고 후 14일 이내 등기소에 알리고 등기를 촉탁·신청한다(법 제43조제1항)."}]},{"종류":"표","제목":"환지처분 공고를 기준으로 한 효과 발생 시점","머리":["대상","시점","근거"],"행":[["환지 계획에서 정한 환지","공고된 날의 다음 날부터 종전의 토지로 본다","법 제42조제1항"],["환지를 정하지 않은 종전 토지의 권리","공고된 날이 끝나는 때 소멸","법 제42조제1항"],["행사할 이익이 없어진 지역권","공고된 날이 끝나는 때 소멸(그 밖의 지역권은 종전 토지에 존속)","법 제42조제3항"],["입체환지 건축물 일부와 대지 공유지분","공고된 날의 다음 날 취득","법 제42조제4항"],["체비지·보류지","공고된 날의 다음 날 시행자(체비지), 환지 계획에서 정한 자(보류지)가 취득. 이미 처분된 체비지는 매입자가 이전 등기를 마친 때","법 제42조제5항"],["청산금","공고된 날의 다음 날 확정. 받을 권리와 징수할 권리는 5년간 행사하지 않으면 시효 소멸","법 제42조제6항, 제47조"],["등기","공고 후 14일 이내 촉탁·신청. 공고일부터 등기까지 다른 등기 불가(공고일 전 등기원인을 확정일자 있는 서류로 증명하면 가능)","법 제43조"]]}],"함정":"환지는 공고일 다음 날부터 종전 토지로 보지만, 환지를 정하지 않은 토지의 권리는 공고일이 끝나는 때 사라진다. 이미 팔린 체비지는 이전 등기를 마쳐야 소유권을 얻는다."}},{"i":"S3-2-1-공법-17","r":"S3","g":2,"c":2,"n":57,"s":"공법","q":"도시개발법령상 도시개발채권에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["도시개발채권의 매입의무자가 매입하여야 할 금액을 초과하여 도시개발채권을 매입한 경우에는 도시개발채권을 중도에 상환할 수 있다.","도시개발채권의 이율은 국토교통부장관이 고시하는 이율로 한다.","도시개발채권의 상환은 1년부터 10년까지의 범위에서 지방자치단체의 조례로 정한다.","도시개발채권의 소멸시효는 상환일부터 기산하여 원금은 5년, 이자는 3년으로 한다.","도시개발채권 매입필증은 멸실 또는 도난 등의 사유로 분실한 경우에도 반드시 재발행하여야 한다."],"a":[1],"L":"공2-4","o":"변형","x":{"한줄":"매입의무 금액을 초과해 매입한 경우는 도시개발채권을 중도에 상환받을 수 있는 사유에 해당한다.","근거":[{"법령":"도시개발법 시행규칙","조문":"제38조제1항","원문":"① 도시개발채권은 다음 각 호의 어느 하나에 해당하는 경우를 제외하고는 중도에 상환할 수 없다.\n  1. 도시개발채권의 매입사유가 된 허가 또는 인가가 매입자의 귀책사유 없이 취소된 경우\n  2. 법 제63조제1항제1호에 해당하는 자의 귀책사유 없이 해당 도급계약이 취소된 경우\n  3. 도시개발채권의 매입의무자가 아닌 자가 착오로 도시개발채권을 매입한 경우\n  4. 도시개발채권의 매입의무자가 매입하여야 할 금액을 초과하여 도시개발채권을 매입한 경우"},{"법령":"도시개발법 시행령","조문":"제83조제2항·제3항","원문":"② 도시개발채권의 이율은 채권의 발행 당시의 국채ㆍ공채 등의 금리와 특별회계의 상황 등을 고려하여 해당 시ㆍ도의 조례로 정한다.\n③ 법 제62조에 따른 도시개발채권의 상환은 5년부터 10년까지의 범위에서 지방자치단체의 조례로 정한다."},{"법령":"도시개발법","조문":"제62조제3항","원문":"③ 도시개발채권의 소멸시효는 상환일부터 기산(起算)하여 원금은 5년, 이자는 2년으로 한다."},{"법령":"도시개발법 시행규칙","조문":"제40조제1항","원문":"① 도시개발채권 매입필증은 멸실 또는 도난 등의 사유로 분실한 경우라도 재발행하지 아니한다. 다만, 매입필증이 도시개발채권의 매입목적에 사용되지 아니하였음을 해당 도시개발채권을 발행한 자가 확인한 경우에는 이를 재발행할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"초과 매입분은 중도상환 사유다(규칙 제38조제1항제4호)."},{"번호":2,"판정":"틀림","설명":"이율은 발행 당시 국채·공채 등의 금리와 특별회계 상황을 고려해 시·도 조례로 정한다(영 제83조제2항)."},{"번호":3,"판정":"틀림","설명":"상환 기간은 5년부터 10년까지다(영 제83조제3항)."},{"번호":4,"판정":"틀림","설명":"소멸시효는 상환일부터 원금 5년, 이자 2년이다(법 제62조제3항)."},{"번호":5,"판정":"틀림","설명":"분실한 매입필증은 재발행하지 않는 것이 원칙이다. 매입목적에 사용되지 않았음을 발행자가 확인하면 재발행할 수 있다(규칙 제40조제1항)."}],"개념":[{"종류":"표","제목":"도시개발채권의 발행·상환·시효","머리":["항목","내용","근거"],"행":[["발행 주체","시·도지사가 시·도 조례에 따라 발행","영 제82조제1항"],["발행 승인","채권의 발행총액, 발행방법, 발행조건, 상환방법·절차 등에 대해 행정안전부장관의 승인","영 제82조제2항"],["발행 방법","전자등록 또는 무기명","영 제83조제1항"],["이율","시·도 조례","영 제83조제2항"],["상환","5년부터 10년까지의 범위에서 조례로 정함","영 제83조제3항"],["소멸시효","상환일부터 원금 5년, 이자 2년","법 제62조제3항"],["매입필증 보관","매입필증을 제출받는 자가 5년간 따로 보관","규칙 제41조제3항"],["최저 매입금액","1만원","영 별표 1"]]},{"종류":"표","제목":"채권 매입대상·금액과 중도상환(영 별표 1, 규칙 제38조)","머리":["구분","내용"],"행":[["매입대상 가","법 제11조제1항제1호~제4호 시행자와 공사 도급계약을 체결한 자: 공사도급계약 금액의 100분의 3"],["매입대상 나","법 제11조제1항제5호~제9호, 제9호의2, 제10호, 제11호 시행자: 시행면적 3.3제곱미터당 20,000원"],["매입대상 다","국토계획법 제56조에 따라 토지 형질변경허가를 받는 자: 허가면적 3.3제곱미터당 20,000원"],["조례 조정","나목·다목 금액은 시·도 조례로 위 금액의 범위에서 달리 정할 수 있다"],["중도상환 사유","매입사유가 된 허가·인가의 귀책사유 없는 취소, 귀책사유 없는 도급계약 취소, 매입의무자가 아닌 자의 착오 매입, 매입의무 금액 초과 매입"]]}],"함정":"시효와 상환 기간의 숫자가 서로 닮아 있다. 시효는 원금 5년·이자 2년, 상환은 5년~10년이다. 중도상환은 원칙적 금지이고 규칙이 정한 4가지 사유만 인정한다."}},{"i":"S3-2-1-공법-18","r":"S3","g":2,"c":2,"n":58,"s":"공법","q":"도시개발법령상 환지처분에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["도시개발구역의 토지 소유자나 이해관계인은 환지 방식에 의한 도시개발사업 공사 관계 서류의 공람 기간에 시행자에게 의견서를 제출할 수 있다.","환지를 정하거나 그 대상에서 제외한 경우 그 과부족분(過不足分)은 금전으로 청산하여야 한다.","시행자는 지정권자에 의한 준공검사를 받은 경우에는 90일 이내에 환지처분을 하여야 한다.","시행자가 환지처분을 하려는 경우에는 환지 계획에서 정한 사항을 토지 소유자에게 알리고 관보 또는 공보에 의해 이를 공고하여야 한다.","환지 계획에서 정하여진 환지는 그 환지처분이 공고된 날의 다음 날부터 종전의 토지로 본다."],"a":[3],"L":"공2-4","o":"기출","x":{"한줄":"준공검사를 받은 시행자는 60일 이내에 환지처분을 하여야 한다.","근거":[{"법령":"도시개발법 시행령","조문":"제65조","원문":"법 제40조제4항에서 \"대통령령으로 정하는 기간\"이란 60일 이내를 말한다."},{"법령":"도시개발법","조문":"제40조제4항","원문":"④ 시행자는 지정권자에 의한 준공검사를 받은 경우(지정권자가 시행자인 경우에는 제51조에 따른 공사 완료 공고가 있는 때)에는 대통령령으로 정하는 기간에 환지처분을 하여야 한다."},{"법령":"도시개발법","조문":"제40조제2항","원문":"② 도시개발구역의 토지 소유자나 이해관계인은 제1항의 공람 기간에 시행자에게 의견서를 제출할 수 있으며, 의견서를 받은 시행자는 공사 결과와 실시계획 내용에 맞는지를 확인하여 필요한 조치를 하여야 한다."},{"법령":"도시개발법","조문":"제41조제1항","원문":"① 환지를 정하거나 그 대상에서 제외한 경우 그 과부족분(過不足分)은 종전의 토지 … 및 환지의 위치ㆍ지목ㆍ면적ㆍ토질ㆍ수리ㆍ이용 상황ㆍ환경, 그 밖의 사항을 종합적으로 고려하여 금전으로 청산하여야 한다."},{"법령":"도시개발법","조문":"제40조제5항","원문":"⑤ 시행자는 환지처분을 하려는 경우에는 환지 계획에서 정한 사항을 토지 소유자에게 알리고 대통령령으로 정하는 바에 따라 이를 공고하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"공사 관계 서류의 공람 기간에 토지 소유자와 이해관계인이 의견서를 낼 수 있다(법 제40조제2항)."},{"번호":2,"판정":"옳음","설명":"환지의 과부족분은 금전으로 청산한다(법 제41조제1항)."},{"번호":3,"판정":"틀림","설명":"환지처분 기한은 준공검사를 받은 날부터 60일 이내다(법 제40조제4항, 영 제65조)."},{"번호":4,"판정":"옳음","설명":"환지 계획에서 정한 사항을 토지 소유자에게 알리고 관보 또는 공보에 공고한다(법 제40조제5항, 영 제66조제1항)."},{"번호":5,"판정":"옳음","설명":"환지는 공고된 날의 다음 날부터 종전의 토지로 본다(법 제42조제1항)."}],"개념":[{"종류":"표","제목":"환지 관련 기간","머리":["단계","기간","근거"],"행":[["환지 계획 공람","14일 이상(토요일·공휴일 제외)","영 제61조제2항"],["의견 반영 여부 통보","공람 기일이 종료된 날부터 60일 이내","법 제29조제6항"],["공사완료 공고 후 서류 공람","14일 이상","영 제64조제3항"],["환지처분","준공검사를 받은 날부터 60일 이내(지정권자가 시행자이면 공사 완료 공고가 있는 때부터)","법 제40조제4항, 영 제65조"],["등기 촉탁·신청","환지처분 공고 후 14일 이내","법 제43조제1항"],["사용·수익 정지 예고","30일 이상의 기간을 두고 미리 알림","법 제37조제2항"],["입체환지 신청 기간","통지한 날부터 30일 이상 60일 이하(20일 범위에서 연장 가능)","법 제32조제4항"],["청산금 시효","5년","법 제47조"]]},{"종류":"비교","제목":"환지 예정지 지정과 환지처분","왼쪽":{"이름":"환지 예정지 지정(법 제35조·제36조)","항목":["시행자가 필요하면 지정하고, 소유자·임차권자등에게 위치·면적·효력발생 시기를 알린다","효력발생일부터 환지처분 공고일까지 종전 토지는 사용·수익할 수 없고, 환지 예정지에서 종전과 같은 권리를 행사한다","체비지 용도로 지정된 환지 예정지는 시행자가 사용·수익하게 하거나 처분할 수 있다"]},"오른쪽":{"이름":"환지처분(법 제40조~제43조)","항목":["공사 완료 후 준공검사를 받은 날부터 60일 이내에 하고 공고한다","공고된 날의 다음 날부터 환지가 종전 토지로 간주된다","청산금은 공고된 날의 다음 날 확정되고, 공고 후 14일 이내에 등기를 촉탁·신청한다"]}}],"함정":"환지처분 기한은 준공검사를 받은 날부터 60일이다. 90일이라는 기간은 이 절차에 나오지 않는다. 의견 검토 결과 통지(60일), 환지처분(60일), 등기(14일)의 기간이 서로 섞이기 쉽다."}},{"i":"S3-2-1-공법-19","r":"S3","g":2,"c":2,"n":59,"s":"공법","q":"도시 및 주거환경정비법령상 도시·주거환경정비기본계획을 변경할 때 지방의회의 의견청취를 생략할 수 있는 경우가 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["건폐율 및 용적률을 각각 25퍼센트씩 변경하는 경우","정비기반시설의 규모를 확대하는 경우","단계별 정비사업 추진계획을 변경하는 경우","도시ㆍ군기본계획의 변경에 따라 기본계획을 변경하는 경우","정비기반시설의 면적을 10퍼센트 미만의 범위에서 축소하는 경우"],"a":[1],"L":"공3-1","o":"변형","x":{"한줄":"건폐율·용적률은 각 20퍼센트 미만의 범위에서 변경할 때만 경미한 변경이므로 각 25퍼센트 변경은 의견청취를 생략할 수 없다.","근거":[{"법령":"도시 및 주거환경정비법 시행령","조문":"제6조제4항","원문":"④ 법 제6조제3항 및 제7조제1항 단서에서 \"대통령령으로 정하는 경미한 사항을 변경하는 경우\"란 각각 다음 각 호의 경우를 말한다.\n  1. 정비기반시설(…)의 규모를 확대하거나 그 면적을 10퍼센트 미만의 범위에서 축소하는 경우\n  6. 법 제5조제1항제10호에 따른 단계별 정비사업 추진계획(…)을 변경하는 경우\n  7. 건폐율(…) 및 용적률(…)을 각 20퍼센트 미만의 범위에서 변경하는 경우\n  9. 「국토의 계획 및 이용에 관한 법률」 제2조제3호에 따른 도시ㆍ군기본계획의 변경에 따라 기본계획을 변경하는 경우"},{"법령":"도시 및 주거환경정비법","조문":"제6조제3항","원문":"③ 제1항 및 제2항에도 불구하고 대통령령으로 정하는 경미한 사항을 변경하는 경우에는 주민공람과 지방의회의 의견청취 절차를 거치지 아니할 수 있다."},{"법령":"도시 및 주거환경정비법","조문":"제6조제2항","원문":"② 기본계획의 수립권자는 제1항에 따른 공람과 함께 지방의회의 의견을 들어야 한다. 이 경우 지방의회는 기본계획의 수립권자가 기본계획을 통지한 날부터 60일 이내에 의견을 제시하여야 하며, 의견제시 없이 60일이 지난 경우 이의가 없는 것으로 본다."}],"선지":[{"번호":1,"판정":"틀림","설명":"건폐율·용적률은 각각 20퍼센트 미만의 범위에서 변경할 때만 경미한 사항이다. 25퍼센트 변경은 의견청취를 거쳐야 한다(영 제6조제4항제7호)."},{"번호":2,"판정":"옳음","설명":"정비기반시설의 규모 확대는 경미한 사항이다(영 제6조제4항제1호)."},{"번호":3,"판정":"옳음","설명":"단계별 정비사업 추진계획 변경은 경미한 사항이다(영 제6조제4항제6호)."},{"번호":4,"판정":"옳음","설명":"도시·군기본계획의 변경에 따른 기본계획 변경은 경미한 사항이다(영 제6조제4항제9호)."},{"번호":5,"판정":"옳음","설명":"정비기반시설 면적을 10퍼센트 미만 축소하는 경우는 경미한 사항이다(영 제6조제4항제1호)."}],"개념":[{"종류":"표","제목":"기본계획 변경 시 경미한 사항(영 제6조제4항)","머리":["호","경미한 사항","비고"],"행":[["1","정비기반시설의 규모 확대, 면적 10퍼센트 미만 축소","확대는 크기 제한 없음"],["2","정비사업의 계획기간 단축","연장은 해당 없음"],["3","공동이용시설 설치계획 변경",""],["4","사회복지시설 및 주민문화시설 등 설치계획 변경",""],["5","면적이 명시된 정비예정구역의 면적을 20퍼센트 미만 변경","20퍼센트 이상은 경미 아님"],["6","단계별 정비사업 추진계획 변경",""],["7","건폐율·용적률을 각 20퍼센트 미만 변경","20퍼센트 이상은 경미 아님"],["8","정비사업 시행에 필요한 재원조달에 관한 사항 변경",""],["9","도시·군기본계획의 변경에 따른 기본계획 변경",""]]},{"종류":"흐름","제목":"기본계획의 수립 절차","단계":[{"이름":"수립","설명":"특별시장·광역시장·특별자치시장·특별자치도지사·시장이 10년 단위로 수립하고 5년마다 타당성을 검토한다(법 제4조)."},{"이름":"주민공람·의견청취","설명":"14일 이상 공람하고, 지방의회 의견은 통지일부터 60일 이내에 듣는다. 60일이 지나면 이의가 없는 것으로 본다(법 제6조제1항·제2항)."},{"이름":"협의·심의","설명":"수립권자(대도시가 아닌 시의 시장은 제외)는 관계 행정기관 협의 후 지방도시계획위원회 심의를 거친다. 대도시가 아닌 시의 시장은 도지사의 승인을 받는다(법 제7조제1항·제2항)."},{"이름":"고시·열람","설명":"지체 없이 공보에 고시하고 일반이 열람하게 한다(법 제7조제3항)."},{"이름":"보고","설명":"고시한 때에는 국토교통부장관에게 보고한다(법 제7조제4항)."}]}],"함정":"건폐율·용적률 변경과 정비예정구역 면적 변경은 20퍼센트 미만일 때만 경미한 사항이다. 정비기반시설은 규모 확대에 크기 제한이 없고 축소에만 10퍼센트 선이 있다."}},{"i":"S3-2-1-공법-20","r":"S3","g":2,"c":2,"n":60,"s":"공법","q":"도시 및 주거환경정비법령상 정비계획의 입안권자가 정비계획을 입안하려는 경우 별표 1의 요건에 적합한지 확인하기 위하여 조사하여야 하는 사항으로 명시되어 있는 것은? (단, 조례로 정하는 사항은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["정비구역 내 건축물의 내진설계 적용 현황","도시ㆍ군계획시설 및 정비기반시설의 설치현황","관계 중앙행정기관의 장의 의견","정비구역 내 세입자의 소득수준","지방의회의 의견"],"a":[2],"L":"공3-1","o":"변형","x":{"한줄":"조사 항목에는 도시·군계획시설 및 정비기반시설의 설치현황이 들어 있다.","근거":[{"법령":"도시 및 주거환경정비법 시행령","조문":"제7조제2항","원문":"② 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ특별자치도지사ㆍ시장ㆍ군수 또는 자치구의 구청장은 제1항에 따라 정비계획을 입안하는 경우에는 다음 각 호의 사항을 조사하여 별표 1의 요건에 적합한지 여부를 확인하여야 하며, …\n  1. 주민 또는 산업의 현황\n  2. 토지 및 건축물의 이용과 소유현황\n  3. 도시ㆍ군계획시설 및 정비기반시설의 설치현황\n  4. 정비구역 및 주변지역의 교통상황\n  5. 토지 및 건축물의 가격과 임대차 현황\n  6. 정비사업의 시행계획 및 시행방법 등에 대한 주민의 의견\n  7. 그 밖에 시ㆍ도조례로 정하는 사항"},{"법령":"도시 및 주거환경정비법","조문":"제15조제2항","원문":"② 정비계획의 입안권자는 제1항에 따른 주민공람과 함께 지방의회의 의견을 들어야 한다. …"}],"선지":[{"번호":1,"판정":"틀림","설명":"내진설계 적용 현황은 조사 항목으로 열거되어 있지 않다(영 제7조제2항)."},{"번호":2,"판정":"옳음","설명":"도시·군계획시설 및 정비기반시설의 설치현황은 제3호에 명시되어 있다(영 제7조제2항제3호)."},{"번호":3,"판정":"틀림","설명":"관계 중앙행정기관의 장의 의견은 조사 항목이 아니다(영 제7조제2항)."},{"번호":4,"판정":"틀림","설명":"세입자의 소득수준은 열거되어 있지 않다. 토지 및 건축물의 가격과 임대차 현황이 명시되어 있다(영 제7조제2항제5호)."},{"번호":5,"판정":"틀림","설명":"지방의회의 의견은 조사 항목이 아니라 정비계획 입안 때 주민공람과 함께 듣는 절차다(법 제15조제2항)."}],"개념":[{"종류":"흐름","제목":"정비계획 입안에서 정비구역 지정까지","단계":[{"이름":"조사·확인","설명":"입안권자가 영 제7조제2항의 7가지 사항을 조사해 별표 1의 요건에 적합한지 확인한다. 사업시행자에게 조사를 하게 할 수 있다(영 제7조제2항·제3항)."},{"이름":"주민 의견","설명":"주민에게 서면으로 통보하고 주민설명회를 연 뒤 30일 이상 공람한다(법 제15조제1항)."},{"이름":"지방의회 의견","설명":"공람과 함께 듣는다. 통지일부터 60일 이내에 의견을 내고, 60일이 지나면 이의가 없는 것으로 본다(법 제15조제2항)."},{"이름":"지정 신청","설명":"자치구의 구청장 또는 광역시의 군수는 정비계획을 입안해 특별시장·광역시장에게 정비구역 지정을 신청하고 지방의회 의견을 첨부한다(법 제8조제5항)."},{"이름":"심의·고시","설명":"정비구역의 지정권자가 지방도시계획위원회 심의를 거쳐 정비계획을 결정하고 정비구역을 지정·고시한다. 국토교통부장관에게 보고하고 서류를 열람하게 한다(법 제16조)."}]},{"종류":"표","제목":"정비계획 입안 제안과 정비구역 해제의 기간","머리":["항목","내용","근거"],"행":[["입안 제안 동의","토지등소유자 3분의 2 이하 및 토지면적 3분의 2 이하의 범위에서 시·도조례로 정하는 비율 이상","영 제12조제1항"],["제안 반영 여부 통지","제안일부터 60일 이내(부득이하면 한 차례 30일 연장)","영 제12조제2항"],["정비계획 변경 요청","토지등소유자 3분의 2 이상 동의","법 제14조제1항제6호"],["정비예정구역 해제","기본계획의 정비구역 지정 예정일부터 3년이 되는 날까지 지정하지 않거나 지정 신청을 하지 않으면 해제","법 제20조제1항제1호"],["추진위원회 승인 신청","정비구역 지정·고시일부터 2년 이내(추진위원회를 구성하는 경우)","법 제20조제1항제2호가목"],["조합설립인가 신청","추진위원회 미구성: 지정·고시일부터 3년, 추진위원회 승인일부터 2년","법 제20조제1항제2호나목·다목"],["사업시행계획인가 신청","조합설립인가일부터 3년. 토지등소유자 시행 재개발은 지정·고시일부터 5년","법 제20조제1항제2호라목·제3호"],["해제 연장","2년의 범위에서 연장 가능. 토지등소유자 100분의 30 이상 동의로 요청하는 경우 등","법 제20조제6항"]]}],"함정":"지방의회 의견 청취나 관계기관 의견은 입안 절차에 속하고, 영 제7조제2항의 조사 항목은 현황·소유·시설·교통·가격 등과 주민 의견이다. 둘을 같은 목록으로 섞은 선지가 오답으로 나온다."}},{"i":"S3-2-1-공법-21","r":"S3","g":2,"c":2,"n":61,"s":"공법","q":"도시 및 주거환경정비법령상 조합설립 등에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["재개발조합이 조합설립인가를 받은 날부터 3년 이내에 사업시행계획인가를 신청하지 아니한 때에는 시장ㆍ군수등은 직접 정비사업을 시행할 수 있다.","재개발사업의 추진위원회가 조합을 설립하려면 토지등소유자의 3분의 2 이상 및 토지면적의 2분의 1 이상의 토지소유자의 동의를 받아야 한다.","토지등소유자가 30인 미만인 경우 토지등소유자는 조합을 설립하지 아니하고 재개발사업을 시행할 수 있다.","조합은 재개발조합설립인가를 받은 때에도 토지등소유자에게 그 내용을 통지하지 아니한다.","추진위원회는 조합설립인가 후 지체 없이 추정분담금에관한 정보를 토지등소유자에게 제공하여야 한다."],"a":[1],"L":"공3-2","o":"기출","x":{"한줄":"조합설립인가일부터 3년 안에 사업시행계획인가를 신청하지 않으면 시장·군수등이 직접 시행하거나 토지주택공사등을 시행자로 지정할 수 있다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제26조제1항제3호","원문":"3. 추진위원회가 시장ㆍ군수등의 구성승인을 받은 날부터 3년 이내에 조합설립인가를 신청하지 아니하거나 조합이 조합설립인가를 받은 날부터 3년 이내에 사업시행계획인가를 신청하지 아니한 때"},{"법령":"도시 및 주거환경정비법","조문":"제35조제2항","원문":"② 재개발사업의 추진위원회(제31조제7항에 따라 추진위원회를 구성하지 아니하는 경우에는 토지등소유자를 말한다)가 조합을 설립하려면 토지등소유자의 4분의 3 이상 및 토지면적의 2분의 1 이상의 토지소유자의 동의를 받아 다음 각 호의 사항을 첨부하여 제16조에 따른 정비구역 지정ㆍ고시 후 시장ㆍ군수등의 인가를 받아야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제25조제1항제2호","원문":"2. 토지등소유자가 20인 미만인 경우에는 토지등소유자가 시행하거나 토지등소유자가 토지등소유자의 과반수의 동의를 받아 시장ㆍ군수등, 토지주택공사등, 건설업자, 등록사업자 또는 대통령령으로 정하는 요건을 갖춘 자와 공동으로 시행하는 방법"},{"법령":"도시 및 주거환경정비법 시행령","조문":"제30조제4항","원문":"④ 조합은 조합설립인가를 받은 때에는 정관으로 정하는 바에 따라 토지등소유자에게 그 내용을 통지하고, 이해관계인이 열람할 수 있도록 하여야 한다."},{"법령":"도시 및 주거환경정비법","조문":"제35조제10항","원문":"⑩ 추진위원회는 조합설립에 필요한 동의를 받기 전에 추정분담금 등 대통령령으로 정하는 정보를 토지등소유자에게 제공하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"재개발·재건축 모두 해당한다. 추진위원회 승인 후 3년 이내 조합설립인가를 신청하지 않은 경우도 같은 호에 있다(법 제26조제1항제3호)."},{"번호":2,"판정":"틀림","설명":"재개발조합 설립동의는 토지등소유자 4분의 3 이상, 토지면적 2분의 1 이상 토지소유자다(법 제35조제2항). 3분의 2는 주택단지가 아닌 지역이 포함된 재건축의 토지면적 기준이다(법 제35조제4항)."},{"번호":3,"판정":"틀림","설명":"조합 없이 토지등소유자가 직접 시행하는 재개발은 토지등소유자가 20인 미만일 때다(법 제25조제1항제2호, 제35조제1항 단서)."},{"번호":4,"판정":"틀림","설명":"조합은 설립인가를 받으면 정관으로 정하는 바에 따라 토지등소유자에게 그 내용을 통지하고 이해관계인이 열람하게 한다(영 제30조제4항)."},{"번호":5,"판정":"틀림","설명":"추정분담금 등 정보는 조합설립에 필요한 동의를 받기 전에 제공한다(법 제35조제10항, 영 제32조). 인가 후가 아니다."}],"개념":[{"종류":"표","제목":"조합설립 동의요건(법 제35조, 제31조)","머리":["구분","사람 기준","토지면적 기준"],"행":[["추진위원회 구성","토지등소유자 과반수(위원장 포함 추진위원 5명 이상)","-"],["재개발 조합설립","토지등소유자 4분의 3 이상","토지면적 2분의 1 이상 토지소유자"],["재건축 조합설립(주택단지)","동별 구분소유자 과반수(동별 구분소유자 5 이하는 제외) + 전체 구분소유자 100분의 70 이상","토지면적 100분의 70 이상 토지소유자"],["재건축 조합설립(주택단지가 아닌 지역 포함)","그 지역의 토지 또는 건축물 소유자 4분의 3 이상","그 지역 토지면적 3분의 2 이상 토지소유자"],["인가받은 사항 변경","총회에서 조합원 3분의 2 이상 찬성 후 인가(경미한 사항은 신고)","-"]]},{"종류":"표","제목":"시장·군수등의 직접 시행·공공시행자 지정 사유(법 제26조제1항)","머리":["사유","내용"],"행":[["긴급한 필요","천재지변, 사용제한·사용금지 등 불가피한 사유로 긴급하게 시행할 필요가 있는 때"],["사업시행계획인가 미신청","정비계획 고시의 정비사업시행 예정일부터 2년 이내 미신청(재건축은 제외)"],["조합설립·사업시행 단계 지연","추진위원회 구성승인일부터 3년 이내 조합설립인가 미신청, 조합설립인가일부터 3년 이내 사업시행계획인가 미신청"],["국·공유지 비율","국·공유지(또는 토지주택공사등 소유 합산)가 전체 토지면적의 2분의 1 이상이고 토지등소유자 과반수가 동의"],["주민 요청","토지면적 2분의 1 이상 토지소유자와 토지등소유자 3분의 2 이상이 지정을 요청"]]}],"함정":"2번은 재건축의 주택단지가 아닌 지역에서 쓰는 3분의 2를 재개발에 끌어온 문장이다. 3번은 20인을 30인으로, 5번은 동의 전을 인가 후로 바꿔 놓았다. 3년과 2년, 20인과 30인처럼 숫자 한 칸만 틀리게 하는 유형이다."}},{"i":"S3-2-1-공법-22","r":"S3","g":2,"c":2,"n":62,"s":"공법","q":"도시 및 주거환경정비법령상 정비사업의 시행에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["세입자의 세대수가 토지등소유자의 3분의 1에 해당하는 경우 시장ㆍ군수등은 토지주택공사등을 주거환경개선사업 시행자로 지정하기 위해서는 세입자의 동의를 받아야 한다.","재개발사업은 토지등소유자가 30인인 경우에는 토지등 소유자가 직접 시행할 수 있다.","재건축사업 조합설립추진위원회가 구성승인을 받은 날부터 2년이 되었음에도 조합설립인가를 신청하지 아니한 경우 시장ㆍ군수등이 직접 시행할 수 있다.","조합설립추진위원회는 토지등소유자의 수가 200인인 경우 5명 이상의 이사를 두어야 한다.","주민대표회의는 토지등소유자의 과반수의 동의를 받아 구성하며, 위원장과 부위원장 각 1명과 1명 이상 3명 이하의 감사를 둔다."],"a":[5],"L":"공3-2","o":"기출","x":{"한줄":"주민대표회의는 토지등소유자 과반수의 동의로 구성해 시장·군수등의 승인을 받고, 위원장과 부위원장 각 1명, 감사 1명 이상 3명 이하를 둔다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제47조제3항","원문":"③ 주민대표회의는 토지등소유자의 과반수의 동의를 받아 구성하며, 국토교통부령으로 정하는 방법 및 절차에 따라 시장ㆍ군수등의 승인을 받아야 한다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제45조제1항","원문":"① 법 제47조제1항에 따른 주민대표회의(이하 \"주민대표회의\"라 한다)에는 위원장과 부위원장 각 1명과 1명 이상 3명 이하의 감사를 둔다"},{"법령":"도시 및 주거환경정비법","조문":"제24조제3항","원문":"③ 제2항에 따라 시행하려는 경우에는 제15조제1항에 따른 공람공고일 현재 해당 정비예정구역의 토지 또는 건축물의 소유자 또는 지상권자의 3분의 2 이상의 동의와 세입자(제15조제1항에 따른 공람공고일 3개월 전부터 해당 정비예정구역에 3개월 이상 거주하고 있는 자를 말한다) 세대수의 과반수의 동의를 각각 받아야 한다. 다만, 세입자의 세대수가 토지등소유자의 2분의 1 이하인 경우 등 대통령령으로 정하는 사유가 있는 경우에는 세입자의 동의절차를 거치지 아니할 수 있다."},{"법령":"도시 및 주거환경정비법","조문":"제33조제1항","원문":"① 추진위원회는 추진위원회를 대표하는 추진위원장 1명과 감사를 두어야 한다."},{"법령":"도시 및 주거환경정비법 시행령","조문":"제40조","원문":"제40조(조합임원의 수) 법 제41조제1항에 따라 조합에 두는 이사의 수는 3명 이상으로 하고, 감사의 수는 1명 이상 3명 이하로 한다. 다만, 토지등소유자의 수가 100인을 초과하는 경우에는 이사의 수를 5명 이상으로 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"세입자 세대수가 토지등소유자의 2분의 1 이하이면 세입자 동의 절차를 거치지 않는다(법 제24조제3항 단서). 3분의 1은 여기에 든다."},{"번호":2,"판정":"틀림","설명":"토지등소유자가 직접 시행할 수 있는 재개발은 20인 미만일 때다(법 제25조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"추진위원회 구성승인일부터 3년 이내 조합설립인가를 신청하지 않으면 시행할 수 있다(법 제26조제1항제3호). 2년이 아니다."},{"번호":4,"판정":"틀림","설명":"추진위원회에는 추진위원장 1명과 감사를 둔다(법 제33조제1항). 이사는 조합임원이며 수는 3명 이상, 토지등소유자 100인 초과 시 5명 이상이다(영 제40조)."},{"번호":5,"판정":"옳음","설명":"법 제47조제3항, 영 제45조제1항에 그대로 있다. 주민대표회의는 위원장을 포함해 5명 이상 25명 이하로 구성한다(법 제47조제2항)."}],"개념":[{"종류":"표","제목":"정비사업별 사업시행자","머리":["사업","시행자","동의 요건"],"행":[["주거환경개선(스스로 개량 방식)","시장·군수등 직접. 토지주택공사등을 지정하려면","공람공고일 현재 토지등소유자 과반수"],["주거환경개선(수용·환지·관리처분 방식)","시장·군수등 직접 또는 토지주택공사등 등 지정","토지·건축물 소유자 또는 지상권자 3분의 2 이상 + 세입자 세대수 과반수"],["재개발","조합(또는 조합이 시장·군수등 등과 공동), 토지등소유자 20인 미만이면 토지등소유자","공동시행은 조합원 또는 토지등소유자 과반수"],["재건축","조합(또는 조합이 시장·군수등, 건설업자 등과 공동)","공동시행은 조합원 과반수"]]},{"종류":"표","제목":"추진위원회·주민대표회의·조합의 구성","머리":["기구","구성","구성 절차"],"행":[["추진위원회","추진위원장 포함 5명 이상, 위원장 1명과 감사","토지등소유자 과반수 동의 + 시장·군수등 승인"],["주민대표회의","위원장 포함 5명 이상 25명 이하, 위원장·부위원장 각 1명, 감사 1명 이상 3명 이하","토지등소유자 과반수 동의 + 시장·군수등 승인"],["조합","조합장 1명, 이사 3명 이상(토지등소유자 100인 초과 시 5명 이상), 감사 1명 이상 3명 이하","조합설립인가 후 법인 등기로 성립"]]}],"함정":"4번은 이사를 추진위원회에 두는 것처럼 써 놓았다. 추진위원회는 위원장과 감사이고 이사는 조합임원이다. 1번은 세입자 동의를 면제하는 2분의 1 이하 기준을 모르면 걸린다. 2번과 3번은 20인, 3년이 나오는 자리에 30인, 2년을 넣었다."}},{"i":"S3-2-1-공법-23","r":"S3","g":2,"c":2,"n":63,"s":"공법","q":"도시 및 주거환경정비법령상 한국토지주택공사가 단독으로 정비사업을 시행하는 경우에 작성하는 시행규정에 포함하여야 하는 사항이 아닌 것은? (단, 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["토지등소유자 전체회의","토지등소유자의 권리ㆍ의무","토지 및 건축물에 관한 권리의 평가방법","정비사업의 시행연도 및 시행방법","공고ㆍ공람 및 통지의 방법"],"a":[1],"L":"공3-2","o":"기출","x":{"한줄":"토지등소유자 전체회의는 신탁업자가 사업시행자인 경우에만 시행규정에 넣는다. 한국토지주택공사 단독시행의 시행규정에는 들어가지 않는다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제53조","원문":"제53조(시행규정의 작성) 시장ㆍ군수등, 토지주택공사등 또는 신탁업자가 단독으로 정비사업을 시행하는 경우 다음 각 호의 사항을 포함하는 시행규정을 작성하여야 한다.\n1. 정비사업의 종류 및 명칭\n2. 정비사업의 시행연도 및 시행방법\n3. 비용부담 및 회계\n4. 토지등소유자의 권리ㆍ의무\n5. 정비기반시설 및 공동이용시설의 부담\n6. 공고ㆍ공람 및 통지의 방법\n7. 토지 및 건축물에 관한 권리의 평가방법\n8. 관리처분계획 및 청산(분할징수 또는 납입에 관한 사항을 포함한다). 다만, 수용의 방법으로 시행하는 경우는 제외한다.\n9. 시행규정의 변경\n10. 사업시행계획서의 변경\n11. 토지등소유자 전체회의(신탁업자가 사업시행자인 경우로 한정한다)\n12. 그 밖에 시ㆍ도조례로 정하는 사항"}],"선지":[{"번호":1,"판정":"틀림","설명":"제11호 전체회의는 '신탁업자가 사업시행자인 경우로 한정'한다. 토지주택공사등 단독시행에는 해당하지 않는다."},{"번호":2,"판정":"옳음","설명":"제4호. 시행규정 포함사항이다."},{"번호":3,"판정":"옳음","설명":"제7호. 시행규정 포함사항이다."},{"번호":4,"판정":"옳음","설명":"제2호. 시행규정 포함사항이다."},{"번호":5,"판정":"옳음","설명":"제6호. 시행규정 포함사항이다."}],"개념":[{"종류":"표","제목":"시행규정 포함사항(법 제53조)","머리":["호","사항","비고"],"행":[["1","정비사업의 종류 및 명칭",""],["2","정비사업의 시행연도 및 시행방법",""],["3","비용부담 및 회계",""],["4","토지등소유자의 권리ㆍ의무",""],["5","정비기반시설 및 공동이용시설의 부담",""],["6","공고ㆍ공람 및 통지의 방법",""],["7","토지 및 건축물에 관한 권리의 평가방법",""],["8","관리처분계획 및 청산","수용 방법으로 시행하면 제외"],["9","시행규정의 변경",""],["10","사업시행계획서의 변경",""],["11","토지등소유자 전체회의","신탁업자가 사업시행자인 경우만"],["12","그 밖에 시ㆍ도조례로 정하는 사항",""]]},{"종류":"표","제목":"주민대표회의·세입자가 시행규정에 의견을 낼 수 있는 사항(법 제47조제5항)","머리":["호","사항"],"행":[["1","건축물의 철거"],["2","주민의 이주(세입자의 퇴거 포함)"],["3","토지 및 건축물의 보상(세입자 주거이전비 등 포함)"],["4","정비사업비의 부담"],["5","세입자에 대한 임대주택의 공급 및 입주자격"]]}],"함정":"시행규정을 쓰는 주체는 시장·군수등, 토지주택공사등, 신탁업자다. 12개 호 가운데 전체회의 하나만 신탁업자 전용이다. 나머지 사항이 눈에 익어 어디가 예외인지 놓치기 쉽다."}},{"i":"S3-2-1-공법-24","r":"S3","g":2,"c":2,"n":64,"s":"공법","q":"도시 및 주거환경정비법령상 사업시행자가 인가받은 관리처분계획을 변경하려는 경우 시장ㆍ군수등의 인가를 받아야 하는 것은?","b":null,"bs":"없음","img":[],"ch":["계산착오ㆍ오기ㆍ누락 등에 따른 조서의 단순정정인 경우로서 불이익을 받는 자가 없는 경우","재건축사업에서 매도청구에 대한 판결에 따라 관리처분계획을 변경하는 경우","임대사업자의 주소(법인인 경우 법인의 소재지와 대표자의 성명 및 주소)를 변경하는 경우","정비사업비의 추산액이 늘어나 조합원의 분담규모를 변경하는 경우","정관 및 사업시행계획인가의 변경에 따라 관리처분계획을 변경하는 경우"],"a":[4],"L":"공3-3","o":"변형","x":{"한줄":"영 제61조에 열거된 경미한 변경만 신고한다. 정비사업비 추산액과 조합원 분담규모는 관리처분계획의 내용이므로 변경하려면 인가를 받아야 한다.","근거":[{"법령":"도시 및 주거환경정비법","조문":"제74조제1항(본문 및 단서)","원문":"① 사업시행자는 제72조에 따른 분양신청기간이 종료된 때에는 분양신청의 현황을 기초로 다음 각 호의 사항이 포함된 관리처분계획을 수립하여 시장ㆍ군수등의 인가를 받아야 하며, 관리처분계획을 변경ㆍ중지 또는 폐지하려는 경우에도 또한 같다. 다만, 대통령령으로 정하는 경미한 사항을 변경하려는 경우에는 시장ㆍ군수등에게 신고하여야 한다.\n6. 정비사업비의 추산액(재건축사업의 경우에는 「재건축초과이익 환수에 관한 법률」에 따른 재건축부담금에 관한 사항을 포함한다) 및 그에 따른 조합원 분담규모 및 분담시기"},{"법령":"도시 및 주거환경정비법 시행령","조문":"제61조","원문":"제61조(관리처분계획의 경미한 변경) 법 제74조제1항 각 호 외의 부분 단서에서 \"대통령령으로 정하는 경미한 사항을 변경하려는 경우\"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다.\n1. 계산착오ㆍ오기ㆍ누락 등에 따른 조서의 단순정정인 경우(불이익을 받는 자가 없는 경우에만 해당한다)\n2. 법 제40조제3항에 따른 정관 및 법 제50조에 따른 사업시행계획인가의 변경에 따라 관리처분계획을 변경하는 경우\n3. 법 제64조에 따른 매도청구에 대한 판결에 따라 관리처분계획을 변경하는 경우\n4. 법 제129조에 따른 권리ㆍ의무의 변동이 있는 경우로서 분양설계의 변경을 수반하지 아니하는 경우\n5. 주택분양에 관한 권리를 포기하는 토지등소유자에 대한 임대주택의 공급에 따라 관리처분계획을 변경하는 경우\n6. 「민간임대주택에 관한 특별법」 제2조제7호에 따른 임대사업자의 주소(법인인 경우에는 법인의 소재지와 대표자의 성명 및 주소)를 변경하는 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"불이익을 받는 자가 없는 단순정정은 인가가 아니라 신고 대상이다(영 제61조제1호). 불이익을 받는 자가 있는 단순정정은 신고 대상이 아니므로 인가를 받는다."},{"번호":2,"판정":"틀림","설명":"매도청구 판결에 따른 변경은 신고 대상이다(영 제61조제3호)."},{"번호":3,"판정":"틀림","설명":"임대사업자 주소 변경은 신고 대상이다(영 제61조제6호)."},{"번호":4,"판정":"옳음","설명":"영 제61조 각 호에 없다. 정비사업비와 분담규모는 법 제74조제1항제6호의 관리처분계획 내용이라 변경하면 인가를 받는다."},{"번호":5,"판정":"틀림","설명":"정관(법 제40조제3항) 및 사업시행계획인가(법 제50조) 변경에 따른 변경은 신고 대상이다(영 제61조제2호)."}],"개념":[{"종류":"표","제목":"관리처분계획 변경: 신고와 인가(법 제74조제1항, 영 제61조)","머리":["구분","경우","처리"],"행":[["신고","계산착오·오기·누락 등 조서의 단순정정(불이익을 받는 자가 없는 경우만)","시장·군수등에게 신고"],["신고","정관 변경 또는 사업시행계획인가 변경에 따른 변경","시장·군수등에게 신고"],["신고","매도청구에 대한 판결에 따른 변경","시장·군수등에게 신고"],["신고","분양설계 변경을 수반하지 않는 권리·의무 변동(법 제129조)","시장·군수등에게 신고"],["신고","주택분양 권리를 포기한 토지등소유자에게 임대주택을 공급하는 변경","시장·군수등에게 신고"],["신고","임대사업자의 주소(법인은 소재지와 대표자 성명·주소) 변경","시장·군수등에게 신고"],["인가","위 6가지 외의 변경, 불이익을 받는 자가 있는 단순정정, 중지·폐지","시장·군수등의 인가"]]},{"종류":"흐름","제목":"분양신청에서 관리처분계획 인가까지","단계":[{"이름":"분양공고·통지","설명":"사업시행계획인가 고시일(인가 후 시공자를 선정하면 계약일)부터 90일 이내 통지·공고(법 제72조제1항)"},{"이름":"분양신청","설명":"통지한 날부터 30일 이상 60일 이내. 20일 범위에서 한 차례만 연장(법 제72조제2항)"},{"이름":"관리처분계획 수립","설명":"분양신청 현황을 기초로 수립(법 제74조제1항)"},{"이름":"공람·의견청취","설명":"인가 신청 전 30일 이상 토지등소유자에게 공람(법 제78조제1항)"},{"이름":"인가","설명":"신청일부터 30일 이내 결정·통보. 타당성 검증을 요청하면 60일 이내(법 제78조제2항)"},{"이름":"고시·통지","설명":"인가 내용을 공보에 고시하고 분양신청자에게 통지(법 제78조제4항, 제5항)"}]}],"함정":"신고 대상 목록을 외우다가 반대 질문이 나오면 흔들린다. 1번은 '불이익을 받는 자가 없는 경우'라서 신고 대상이다. 같은 단순정정이라도 불이익 받는 자가 있으면 인가 대상이 된다. 목록에 없는 변경은 모두 인가 쪽이다."}},{"i":"S3-2-1-공법-25","r":"S3","g":2,"c":2,"n":65,"s":"공법","q":"건축법령상 건축법의 적용 제외 건축물이 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["고속도로 통행료 징수시설","철도의 선로 부지에 있는 플랫폼","이동이 쉬운 컨테이너를 이용한 임시숙소","「하천법」에 따른 하천구역 내의 수문조작실","「문화유산의 보존 및 활용에 관한 법률」에 따른 임시지정문화유산"],"a":[3],"L":"공4-1","o":"기출","x":{"한줄":"컨테이너를 이용한 간이창고는 공장 대지에 설치하는 이동이 쉬운 것만 적용 제외다. 컨테이너 임시숙소는 건축법 적용 대상이다.","근거":[{"법령":"건축법","조문":"제3조제1항","원문":"① 다음 각 호의 어느 하나에 해당하는 건축물에는 이 법을 적용하지 아니한다.\n1. 「문화유산의 보존 및 활용에 관한 법률」에 따른 지정문화유산이나 임시지정문화유산 또는 「자연유산의 보존 및 활용에 관한 법률」에 따라 지정된 천연기념물등이나 임시지정천연기념물, 임시지정명승, 임시지정시ㆍ도자연유산, 임시자연유산자료\n2. 철도나 궤도의 선로 부지(敷地)에 있는 다음 각 목의 시설\n가. 운전보안시설\n나. 철도 선로의 위나 아래를 가로지르는 보행시설\n다. 플랫폼\n라. 해당 철도 또는 궤도사업용 급수(給水)ㆍ급탄(給炭) 및 급유(給油) 시설\n3. 고속도로 통행료 징수시설\n4. 컨테이너를 이용한 간이창고(「산업집적활성화 및 공장설립에 관한 법률」 제2조제1호에 따른 공장의 용도로만 사용되는 건축물의 대지에 설치하는 것으로서 이동이 쉬운 것만 해당된다)\n5. 「하천법」에 따른 하천구역 내의 수문조작실"}],"선지":[{"번호":1,"판정":"옳음","설명":"제3호. 고속도로 통행료 징수시설은 적용 제외다."},{"번호":2,"판정":"옳음","설명":"제2호다목. 철도·궤도의 선로 부지에 있는 플랫폼은 적용 제외다."},{"번호":3,"판정":"틀림","설명":"제4호의 컨테이너 건축물은 공장 용도 건축물의 대지에 설치하는 이동이 쉬운 간이창고만 적용 제외다. 임시숙소는 해당하지 않는다."},{"번호":4,"판정":"옳음","설명":"제5호. 하천구역 내 수문조작실은 적용 제외다."},{"번호":5,"판정":"옳음","설명":"제1호. 임시지정문화유산은 지정문화유산과 함께 적용 제외다."}],"개념":[{"종류":"표","제목":"건축법 적용 제외 건축물(법 제3조제1항)","머리":["호","적용 제외 건축물","주의"],"행":[["1","지정문화유산·임시지정문화유산, 천연기념물등·임시지정천연기념물·임시지정명승·임시지정시ㆍ도자연유산·임시자연유산자료","임시지정까지 포함"],["2","철도·궤도 선로 부지의 운전보안시설, 선로 위·아래를 가로지르는 보행시설, 플랫폼, 철도·궤도사업용 급수·급탄·급유 시설","선로 부지 안의 시설만"],["3","고속도로 통행료 징수시설",""],["4","컨테이너를 이용한 간이창고","공장 용도 건축물의 대지에 설치, 이동이 쉬운 것만"],["5","「하천법」에 따른 하천구역 내의 수문조작실",""]]},{"종류":"표","제목":"일부 규정만 적용하지 않는 지역(법 제3조제2항)","머리":["지역","적용하지 않는 규정"],"행":[["도시지역 및 지구단위계획구역 외의 지역으로서 동이나 읍이 아닌 지역","제44조~제47조(대지와 도로), 제51조(방화지구), 제57조(대지 분할 제한)"],["동·읍에 속하는 섬","인구 500명 이상인 경우만 동·읍으로 본다"]]}],"함정":"이름이 비슷한 '컨테이너 간이창고'와 '컨테이너 임시숙소'를 섞은 선지다. 제외되는 것은 공장 대지의 이동이 쉬운 간이창고뿐이다. 임시지정문화유산은 낯설어 보여도 제외 목록에 있다."}},{"i":"S3-2-1-공법-26","r":"S3","g":2,"c":2,"n":66,"s":"공법","q":"甲은 A도 B시에 소재하는 자동차영업소로만 쓰는 건축물(사용승인을 받은 건축물로서 같은 건축물에 해당 용도로 쓰는 바닥면적의 합계가 500 m²임)의 용도를 전부 노래연습장으로 용도변경하려고 한다. 건축법령상 이에 관한 설명으로 옳은 것은? (단, 제시된 조건 이외의 다른 조건이나 제한, 건축법령상 특례 및 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["甲은 건축물 용도변경에 관하여 B시장의 허가를 받아야 한다.","甲은 B시장에게 건축물 용도변경에 관하여 신고를 하여야 한다.","甲은 용도변경한 건축물을 사용하려면 B시장의 사용승인을 받아야 한다.","甲은 B시장에게 건축물대장 기재내용의 변경을 신청하여야 한다.","甲의 건축물에 대한 용도변경을 위한 설계는 건축사가 아니면 할 수 없다."],"a":[4],"L":"공4-2","o":"기출","x":{"한줄":"자동차영업소와 노래연습장은 모두 제2종 근린생활시설로 근린생활시설군(7군)이다. 같은 시설군 안의 변경이므로 허가·신고가 아니라 건축물대장 기재내용 변경을 신청한다. 노래연습장은 영 제14조제4항 단서의 예외라 신청 면제도 없다.","근거":[{"법령":"건축법","조문":"제19조제2항·제3항","원문":"② 제22조에 따라 사용승인을 받은 건축물의 용도를 변경하려는 자는 다음 각 호의 구분에 따라 국토교통부령으로 정하는 바에 따라 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장의 허가를 받거나 신고를 하여야 한다.\n1. 허가 대상: 제4항 각 호의 어느 하나에 해당하는 시설군(施設群)에 속하는 건축물의 용도를 상위군(제4항 각 호의 번호가 용도변경하려는 건축물이 속하는 시설군보다 작은 시설군을 말한다)에 해당하는 용도로 변경하는 경우\n2. 신고 대상: 제4항 각 호의 어느 하나에 해당하는 시설군에 속하는 건축물의 용도를 하위군(제4항 각 호의 번호가 용도변경하려는 건축물이 속하는 시설군보다 큰 시설군을 말한다)에 해당하는 용도로 변경하는 경우\n③ 제4항에 따른 시설군 중 같은 시설군 안에서 용도를 변경하려는 자는 국토교통부령으로 정하는 바에 따라 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장에게 건축물대장 기재내용의 변경을 신청하여야 한다. 다만, 대통령령으로 정하는 변경의 경우에는 그러하지 아니하다."},{"법령":"건축법 시행령","조문":"제14조제4항","원문":"④ 법 제19조제3항 단서에서 \"대통령령으로 정하는 변경\"이란 다음 각 호의 어느 하나에 해당하는 건축물 상호 간의 용도변경을 말한다. 다만, 별표 1 제3호다목(목욕장만 해당한다)ㆍ라목, 같은 표 제4호가목ㆍ사목ㆍ카목ㆍ파목(골프연습장, 놀이형시설만 해당한다)ㆍ더목ㆍ러목ㆍ머목, 같은 표 제7호다목2), 같은 표 제15호가목(생활숙박시설만 해당한다) 및 같은 표 제16호가목ㆍ나목에 해당하는 용도로 변경하는 경우는 제외한다.\n1. 별표 1의 같은 호에 속하는 건축물 상호 간의 용도변경\n2. 「국토의 계획 및 이용에 관한 법률」이나 그 밖의 관계 법령에서 정하는 용도제한에 적합한 범위에서 제1종 근린생활시설과 제2종 근린생활시설 상호 간의 용도변경"},{"법령":"건축법 시행령","조문":"별표 1 제4호 다목·러목","원문":"다. 자동차영업소로서 같은 건축물에 해당 용도로 쓰는 바닥면적의 합계가 1천제곱미터 미만인 것\n러. 안마시술소, 노래연습장"},{"법령":"건축법","조문":"제19조제5항·제6항","원문":"⑤ 제2항에 따른 허가나 신고 대상인 경우로서 용도변경하려는 부분의 바닥면적의 합계가 100제곱미터 이상인 경우의 사용승인에 관하여는 제22조를 준용한다. 다만, 용도변경하려는 부분의 바닥면적의 합계가 500제곱미터 미만으로서 대수선에 해당되는 공사를 수반하지 아니하는 경우에는 그러하지 아니하다.\n⑥ 제2항에 따른 허가 대상인 경우로서 용도변경하려는 부분의 바닥면적의 합계가 500제곱미터 이상인 용도변경(대통령령으로 정하는 경우는 제외한다)의 설계에 관하여는 제23조를 준용한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"허가 대상은 상위군으로 올리는 경우다(법 제19조제2항제1호). 같은 7군 안의 변경이라 허가 대상이 아니다."},{"번호":2,"판정":"틀림","설명":"신고 대상은 하위군으로 내리는 경우다(법 제19조제2항제2호). 같은 시설군이라 신고 대상도 아니다."},{"번호":3,"판정":"틀림","설명":"사용승인 준용은 허가·신고 대상 용도변경에서 바닥면적 합계 100㎡ 이상일 때다(법 제19조제5항). 허가·신고 대상이 아니다."},{"번호":4,"판정":"옳음","설명":"같은 시설군 안에서 변경하면 건축물대장 기재내용의 변경을 신청한다(법 제19조제3항). 노래연습장으로 바꾸는 경우는 영 제14조제4항 단서의 예외라 신청해야 한다."},{"번호":5,"판정":"틀림","설명":"용도변경 설계에 건축사 설계를 준용하는 경우는 허가 대상이면서 바닥면적 합계 500㎡ 이상일 때다(법 제19조제6항). 허가 대상이 아니다."}],"개념":[{"종류":"표","제목":"용도변경 시설군 9개(법 제19조제4항, 영 제14조제5항)","머리":["번호","시설군","속하는 용도"],"행":[["1","자동차 관련 시설군","자동차 관련 시설"],["2","산업 등 시설군","운수·창고·공장·위험물저장 및 처리·자원순환 관련·묘지 관련·장례시설"],["3","전기통신시설군","방송통신시설, 발전시설"],["4","문화집회시설군","문화 및 집회, 종교, 위락, 관광휴게시설"],["5","영업시설군","판매, 운동, 숙박시설, 제2종 근린생활시설 중 다중생활시설"],["6","교육 및 복지시설군","의료, 교육연구, 노유자, 수련시설, 야영장 시설"],["7","근린생활시설군","제1종 근린생활시설, 제2종 근린생활시설(다중생활시설 제외)"],["8","주거업무시설군","단독주택, 공동주택, 업무시설, 교정시설, 국방·군사시설"],["9","그 밖의 시설군","동물 및 식물 관련 시설"]]},{"종류":"흐름","제목":"용도변경 처리 판단","단계":[{"이름":"시설군 확인","설명":"변경 전과 변경 후 용도가 속한 시설군 번호를 비교한다(영 제14조제5항)"},{"이름":"상위군(번호가 작아짐)","설명":"허가. 시장·군수·구청장의 허가(법 제19조제2항제1호)"},{"이름":"하위군(번호가 커짐)","설명":"신고(법 제19조제2항제2호)"},{"이름":"같은 시설군","설명":"건축물대장 기재내용 변경 신청. 같은 호 안의 변경, 제1종·제2종 근린생활시설 상호 변경은 신청도 면제이나 노래연습장·안마시술소·학원 등 열거된 용도로 바꾸면 신청(영 제14조제4항)"},{"이름":"부수 절차","설명":"허가·신고 대상이고 변경 부분 100㎡ 이상이면 사용승인 준용(500㎡ 미만이고 대수선 없으면 제외). 허가 대상이고 500㎡ 이상이면 건축사 설계 준용(법 제19조제5항, 제6항)"}]}],"함정":"허가냐 신고냐만 보다가 시설군이 같다는 점을 놓친다. 자동차영업소와 노래연습장은 둘 다 제2종 근린생활시설이다. 노래연습장은 면제 예외에 열거돼 있어서 대장 변경 신청이 필요하다. 정답률이 18%로 낮았다."}},{"i":"S3-2-1-공법-27","r":"S3","g":2,"c":2,"n":67,"s":"공법","q":"건축법령상 건축 관련 입지와 규모의 사전결정에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["건축신고 대상 건축물을 건축하려는 자도 신고 전에 허가권자에게 사전결정을 신청할 수 있다.","사전결정신청자는 사전결정을 통지받은 날부터 3년 이내에 건축허가를 신청하지 아니하면 사전결정의 효력이 상실된다.","사전결정의 통지로써 농지전용허가가 의제되는 내용이 포함된 경우 허가권자는 미리 관계 행정기관의 장과 협의하여야 하며, 협의를 요청받은 관계 행정기관의 장은 요청받은 날부터 15일 이내에 의견을 제출하여야 한다.","협의를 요청받은 관계 행정기관의 장이 정해진 기간 내에 의견을 제출하지 아니하면 협의가 이루어지지 아니한 것으로 본다.","사전결정의 통지를 받으면 보전산지에서의 산지전용허가는 도시지역인지 여부와 관계없이 받은 것으로 본다."],"a":[3],"L":"공4-2","o":"변형","x":{"한줄":"사전결정으로 농지전용허가 등이 의제되는 내용이 있으면 허가권자가 미리 관계 행정기관의 장과 협의하고, 그 장은 요청받은 날부터 15일 이내에 의견을 낸다.","근거":[{"법령":"건축법","조문":"제10조제1항·제2항","원문":"① 제11조에 따른 건축허가 대상 건축물을 건축하려는 자는 건축허가를 신청하기 전에 허가권자에게 그 건축물의 건축에 관한 다음 각 호의 사항에 대한 사전결정을 신청할 수 있다.\n1. 해당 대지에 건축하는 것이 이 법이나 관계 법령에서 허용되는지 여부\n2. 이 법 또는 관계 법령에 따른 건축기준 및 건축제한, 그 완화에 관한 사항 등을 고려하여 해당 대지에 건축 가능한 건축물의 규모\n3. 건축허가를 받기 위하여 신청자가 고려하여야 할 사항\n② 제1항에 따른 사전결정을 신청하는 자(이하 \"사전결정신청자\"라 한다)는 건축위원회 심의와 「도시교통정비 촉진법」에 따른 교통영향평가서의 검토를 동시에 신청할 수 있다."},{"법령":"건축법","조문":"제10조제6항~제8항","원문":"⑥ 제4항에 따른 사전결정 통지를 받은 경우에는 다음 각 호의 허가를 받거나 신고 또는 협의를 한 것으로 본다.\n2. 「산지관리법」 제14조와 제15조에 따른 산지전용허가와 산지전용신고, 같은 법 제15조의2에 따른 산지일시사용허가ㆍ신고. 다만, 보전산지인 경우에는 도시지역만 해당된다.\n3. 「농지법」 제34조, 제35조 및 제43조에 따른 농지전용허가ㆍ신고 및 협의\n⑦ 허가권자는 제6항 각 호의 어느 하나에 해당되는 내용이 포함된 사전결정을 하려면 미리 관계 행정기관의 장과 협의하여야 하며, 협의를 요청받은 관계 행정기관의 장은 요청받은 날부터 15일 이내에 의견을 제출하여야 한다.\n⑧ 관계 행정기관의 장이 제7항에서 정한 기간(「민원 처리에 관한 법률」 제20조제2항에 따라 회신기간을 연장한 경우에는 그 연장된 기간을 말한다) 내에 의견을 제출하지 아니하면 협의가 이루어진 것으로 본다."},{"법령":"건축법","조문":"제10조제9항","원문":"⑨ 사전결정신청자는 제4항에 따른 사전결정을 통지받은 날부터 2년 이내에 제11조에 따른 건축허가를 신청하여야 하며, 이 기간에 건축허가를 신청하지 아니하면 사전결정의 효력이 상실된다."}],"선지":[{"번호":1,"판정":"틀림","설명":"사전결정은 제11조에 따른 건축허가 대상 건축물을 건축하려는 자가 신청한다(법 제10조제1항). 신고 대상은 해당하지 않는다."},{"번호":2,"판정":"틀림","설명":"사전결정 통지일부터 2년 이내에 건축허가를 신청해야 한다(법 제10조제9항). 3년이 아니다."},{"번호":3,"판정":"옳음","설명":"의제되는 허가를 포함하는 사전결정은 미리 협의하고 15일 이내 의견을 제출한다(법 제10조제6항제3호, 제7항)."},{"번호":4,"판정":"틀림","설명":"기간 내에 의견을 제출하지 않으면 협의가 이루어진 것으로 본다(법 제10조제8항)."},{"번호":5,"판정":"틀림","설명":"보전산지의 산지전용허가·신고는 도시지역인 경우에만 의제된다(법 제10조제6항제2호 단서)."}],"개념":[{"종류":"표","제목":"사전결정의 내용과 효력(법 제10조)","머리":["항목","내용"],"행":[["신청권자","제11조 건축허가 대상 건축물을 건축하려는 자(허가 신청 전)"],["사전결정 사항","관계 법령상 건축 허용 여부, 건축 가능한 규모, 허가를 위해 고려할 사항"],["동시 신청","건축위원회 심의, 「도시교통정비 촉진법」 교통영향평가서 검토"],["소규모 환경영향평가","대상이면 허가권자가 기후에너지환경부장관 또는 지방환경관서의 장과 협의"],["의제되는 허가","개발행위허가, 산지전용허가·신고와 산지일시사용허가·신고(보전산지는 도시지역만), 농지전용허가·신고·협의, 하천점용허가"],["관계 행정기관 협의","미리 협의, 요청받은 날부터 15일 이내 의견 제출, 기간 내 미제출 시 협의된 것으로 봄"],["효력 상실","통지받은 날부터 2년 이내 건축허가 미신청 시"]]},{"종류":"흐름","제목":"사전결정 절차","단계":[{"이름":"신청","설명":"건축허가 대상 건축물을 지으려는 자가 허가권자에게 사전결정 신청(필요하면 건축위원회 심의·교통영향평가서 검토 동시 신청)"},{"이름":"협의","설명":"의제되는 허가가 있으면 관계 행정기관의 장과 미리 협의. 15일 이내 의견 제출"},{"이름":"통지","설명":"허가권자가 입지·규모·용도를 사전결정하고 신청인에게 통지. 통지 시 의제 효과 발생"},{"이름":"건축허가 신청","설명":"통지받은 날부터 2년 이내. 넘기면 사전결정 효력 상실"}]}],"함정":"2년 기산점이 착공신고가 아니라 건축허가 신청이라는 점이 핵심이다. 의견 미제출은 '협의된 것으로 본다'가 규칙이라, 반대로 쓴 4번에 속기 쉽다. 5번은 보전산지의 도시지역 한정을 빼 놓은 문장이다."}},{"i":"S3-2-1-공법-28","r":"S3","g":2,"c":2,"n":68,"s":"공법","q":"건축주 甲은 사용승인을 받은 2층 건축물(바닥면적의 합계 600 m²)을 숙박시설로 사용하다가 이를 종교시설로 용도변경하고자 한다. 건축법령상 이에 관한 설명으로 옳은 것은? (단, 다른 조건은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["甲은 건축물의 용도를 종교시설로 변경하려면 용도변경을 신고하여야 한다.","甲은 건축물대장 기재내용의 변경을 신청하는 것으로 용도변경을 마칠 수 있다.","甲이 용도변경 후 건축물을 사용하려면 용도변경 부분의 바닥면적 합계가 600 m²이므로 대수선이 수반되지 않더라도 사용승인을 받아야 하는 것은 아니다.","甲의 건축물에 대한 용도변경을 위한 설계는 건축사가 아니면 할 수 없다.","甲은 종교시설에 다른 용도를 추가하여 복수 용도로 용도변경 허가를 신청할 수 없다."],"a":[4],"L":"공4-2","o":"변형","x":{"한줄":"숙박시설(5군)에서 종교시설(4군)로 번호가 작은 상위군으로 바꾸므로 허가 대상이다. 허가 대상이고 바닥면적 합계가 500㎡ 이상이면 건축사 설계 규정을 준용한다.","근거":[{"법령":"건축법","조문":"제19조제2항","원문":"② 제22조에 따라 사용승인을 받은 건축물의 용도를 변경하려는 자는 다음 각 호의 구분에 따라 국토교통부령으로 정하는 바에 따라 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장의 허가를 받거나 신고를 하여야 한다.\n1. 허가 대상: 제4항 각 호의 어느 하나에 해당하는 시설군(施設群)에 속하는 건축물의 용도를 상위군(제4항 각 호의 번호가 용도변경하려는 건축물이 속하는 시설군보다 작은 시설군을 말한다)에 해당하는 용도로 변경하는 경우\n2. 신고 대상: 제4항 각 호의 어느 하나에 해당하는 시설군에 속하는 건축물의 용도를 하위군(제4항 각 호의 번호가 용도변경하려는 건축물이 속하는 시설군보다 큰 시설군을 말한다)에 해당하는 용도로 변경하는 경우"},{"법령":"건축법 시행령","조문":"제14조제5항(제4호·제5호)","원문":"⑤ 법 제19조제4항 각 호의 시설군에 속하는 건축물의 용도는 다음 각 호와 같다.\n4. 문화집회시설군\n가. 문화 및 집회시설\n나. 종교시설\n다. 위락시설\n라. 관광휴게시설\n5. 영업시설군\n가. 판매시설\n나. 운동시설\n다. 숙박시설\n라. 제2종 근린생활시설 중 다중생활시설"},{"법령":"건축법","조문":"제19조제5항·제6항","원문":"⑤ 제2항에 따른 허가나 신고 대상인 경우로서 용도변경하려는 부분의 바닥면적의 합계가 100제곱미터 이상인 경우의 사용승인에 관하여는 제22조를 준용한다. 다만, 용도변경하려는 부분의 바닥면적의 합계가 500제곱미터 미만으로서 대수선에 해당되는 공사를 수반하지 아니하는 경우에는 그러하지 아니하다.\n⑥ 제2항에 따른 허가 대상인 경우로서 용도변경하려는 부분의 바닥면적의 합계가 500제곱미터 이상인 용도변경(대통령령으로 정하는 경우는 제외한다)의 설계에 관하여는 제23조를 준용한다."},{"법령":"건축법","조문":"제19조의2","원문":"제19조의2(복수 용도의 인정)\n① 건축주는 건축물의 용도를 복수로 하여 제11조에 따른 건축허가, 제14조에 따른 건축신고 및 제19조에 따른 용도변경 허가ㆍ신고 또는 건축물대장 기재내용의 변경 신청을 할 수 있다.\n② 허가권자는 제1항에 따라 신청한 복수의 용도가 이 법 및 관계 법령에서 정한 건축기준과 입지기준 등에 모두 적합한 경우에 한정하여 국토교통부령으로 정하는 바에 따라 복수 용도를 허용할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"신고 대상은 하위군으로 바꿀 때다. 4군으로의 변경은 상위군으로의 변경이라 허가 대상이다(법 제19조제2항제1호)."},{"번호":2,"판정":"틀림","설명":"대장 기재내용 변경 신청은 같은 시설군 안의 변경이다(법 제19조제3항). 5군에서 4군으로 바꾸는 경우는 해당하지 않는다."},{"번호":3,"판정":"틀림","설명":"허가·신고 대상 용도변경은 변경 부분이 100㎡ 이상이면 사용승인을 준용하고, 500㎡ 미만이면서 대수선이 없는 경우만 제외한다(법 제19조제5항). 600㎡는 제외 사유가 아니다."},{"번호":4,"판정":"옳음","설명":"허가 대상이고 변경 부분이 500㎡ 이상이므로 건축사 설계 규정을 준용한다(법 제19조제6항, 제23조제1항)."},{"번호":5,"판정":"틀림","설명":"건축주는 복수 용도로 용도변경 허가·신고 또는 대장 변경 신청을 할 수 있다. 허가권자는 건축기준과 입지기준에 모두 적합할 때 허용한다(법 제19조의2)."}],"개념":[{"종류":"표","제목":"용도변경 사례별 처리","머리":["사례","시설군 이동","처리","근거"],"행":[["숙박시설(5군) → 종교시설(4군)","상위군","허가","법 제19조제2항제1호"],["의료시설(6군) → 서점(제2종 근린생활시설, 7군)","하위군","신고","법 제19조제2항제2호"],["자동차영업소(7군) → 노래연습장(7군)","같은 시설군","건축물대장 기재내용 변경 신청","법 제19조제3항, 영 제14조제4항"],["제1종 근린생활시설 → 제2종 근린생활시설(열거 용도 제외)","같은 시설군","신청도 면제","영 제14조제4항제2호"],["허가·신고 대상, 변경 부분 100㎡ 이상","-","사용승인 준용(500㎡ 미만이고 대수선 없으면 제외)","법 제19조제5항"],["허가 대상, 변경 부분 500㎡ 이상","-","건축사 설계 준용","법 제19조제6항"]]},{"종류":"비교","제목":"용도변경 허가와 신고","왼쪽":{"이름":"허가 대상","항목":["변경하려는 용도가 상위군(시설군 번호가 작은 쪽)","허가권자는 특별자치시장·특별자치도지사 또는 시장·군수·구청장","변경 부분 500㎡ 이상이면 건축사 설계 규정 준용","변경 부분 100㎡ 이상이면 사용승인 준용(500㎡ 미만이고 대수선 없으면 제외)"]},"오른쪽":{"이름":"신고 대상","항목":["변경하려는 용도가 하위군(시설군 번호가 큰 쪽)","같은 허가권자에게 신고","설계 규정은 준용되지 않는다","변경 부분 100㎡ 이상이면 사용승인 준용(500㎡ 미만·대수선 없음 제외)"]}}],"함정":"신고 사례를 먼저 외워 두면 상위군으로 올라가는 이 사례도 신고로 읽게 된다. 번호가 작아지면 허가다. 복수 용도 신청은 법 제19조의2에서 허용하므로 5번의 '할 수 없다'는 틀린 말이다."}},{"i":"S3-2-1-공법-29","r":"S3","g":2,"c":2,"n":69,"s":"공법","q":"건축법령상 건축물 바닥면적의 산정방법에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["벽ㆍ기둥의 구획이 없는 건축물은 그 지붕 끝부분으로부터 수평거리 1미터를 후퇴한 선으로 둘러싸인 수평투영면적으로 한다.","층고가 1.8미터 이하인 다락은 지붕의 형태와 관계없이 바닥면적에 산입하지 아니한다.","공동주택으로서 지상층에 설치한 기계실, 전기실, 어린이놀이터는 바닥면적에 산입하지 아니한다.","필로티 부분이 공중의 통행이나 차량의 통행 또는 주차에 전용되는 경우에는 바닥면적에 산입하지 아니한다.","승강기탑(옥상 출입용 승강장을 포함한다), 계단탑, 장식탑은 바닥면적에 산입하지 아니한다."],"a":[2],"L":"공4-3","o":"변형","x":{"한줄":"다락이 바닥면적에서 빠지려면 층고가 1.5미터 이하여야 한다. 경사진 지붕일 때만 1.8미터 이하를 적용한다.","근거":[{"법령":"건축법 시행령","조문":"제119조제1항제3호","원문":"3. 바닥면적: 건축물의 각 층 또는 그 일부로서 벽, 기둥, 그 밖에 이와 비슷한 구획의 중심선으로 둘러싸인 부분의 수평투영면적으로 한다. 다만, 다음 각 목의 어느 하나에 해당하는 경우에는 각 목에서 정하는 바에 따른다.\n가. 벽ㆍ기둥의 구획이 없는 건축물은 그 지붕 끝부분으로부터 수평거리 1미터를 후퇴한 선으로 둘러싸인 수평투영면적으로 한다.\n나. 건축물의 노대등의 바닥은 난간 등의 설치 여부에 관계없이 노대등의 면적(외벽의 중심선으로부터 노대등의 끝부분까지의 면적을 말한다)에서 노대등이 접한 가장 긴 외벽에 접한 길이에 1.5미터를 곱한 값을 뺀 면적을 바닥면적에 산입한다.\n다. 필로티나 그 밖에 이와 비슷한 구조(벽면적의 2분의 1 이상이 그 층의 바닥면에서 위층 바닥 아래면까지 공간으로 된 것만 해당한다)의 부분은 그 부분이 공중의 통행이나 차량의 통행 또는 주차에 전용되는 경우와 공동주택의 경우에는 바닥면적에 산입하지 아니한다.\n라. 승강기탑(옥상 출입용 승강장을 포함한다. 이하 같다), 계단탑, 장식탑, 다락[층고(層高)가 1.5미터(경사진 형태의 지붕인 경우에는 1.8미터) 이하인 것만 해당한다], 건축물의 내부에 설치하는 냉방설비 배기장치 전용 설치공간(각 세대나 실별로 외부 공기에 직접 닿는 곳에 설치하는 경우로서 1제곱미터 이하로 한정한다), 건축물의 외부 또는 내부에 설치하는 굴뚝, 더스트슈트, 설비덕트, 그 밖에 이와 비슷한 것과 옥상ㆍ옥외 또는 지하에 설치하는 물탱크, 기름탱크, 냉각탑, 정화조, 도시가스 정압기, 그 밖에 이와 비슷한 것을 설치하기 위한 구조물과 건축물 간에 화물의 이동에 이용되는 컨베이어벨트만을 설치하기 위한 구조물은 바닥면적에 산입하지 않는다.\n마. 공동주택으로서 지상층에 설치한 기계실, 전기실, 어린이놀이터, 조경시설 및 생활폐기물 보관시설의 면적은 바닥면적에 산입하지 않는다."}],"선지":[{"번호":1,"판정":"옳음","설명":"영 제119조제1항제3호가목."},{"번호":2,"판정":"틀림","설명":"다락은 층고 1.5미터(경사진 형태의 지붕이면 1.8미터) 이하인 것만 불산입이다(영 제119조제1항제3호라목). 1.8미터를 일반 지붕에 적용하지 않는다."},{"번호":3,"판정":"옳음","설명":"공동주택의 지상층 기계실·전기실·어린이놀이터·조경시설·생활폐기물 보관시설은 불산입이다(같은 호 마목)."},{"번호":4,"판정":"옳음","설명":"필로티는 공중통행·차량통행·주차에 전용되거나 공동주택이면 불산입이다(같은 호 다목)."},{"번호":5,"판정":"옳음","설명":"승강기탑, 계단탑, 장식탑은 불산입이다(같은 호 라목)."}],"개념":[{"종류":"표","제목":"면적 산정방법 요약(영 제119조제1항)","머리":["구분","기준"],"행":[["대지면적","대지의 수평투영면적. 건축선과 도로 사이의 대지, 도시·군계획시설(도로·공원 등)에 포함되는 대지는 제외"],["건축면적","외벽(없으면 외곽 기둥) 중심선으로 둘러싸인 부분의 수평투영면적. 처마·차양 등이 1미터 이상 돌출되면 돌출 끝에서 1미터 후퇴한 선(한옥 2미터 이하, 전통사찰 4미터 이하 범위)"],["바닥면적","각 층 또는 그 일부로서 벽·기둥 등 구획의 중심선으로 둘러싸인 부분의 수평투영면적"],["연면적","각 층 바닥면적의 합계. 용적률 산정 때는 지하층 면적과 부속용도 지상층 주차용 면적 등을 제외"]]},{"종류":"비교","제목":"바닥면적 산입과 불산입(영 제119조제1항제3호)","왼쪽":{"이름":"산입·특수 산정","항목":["벽·기둥 구획이 없는 건축물: 지붕 끝에서 1미터 후퇴한 선 안","노대등: 노대 면적에서 가장 긴 외벽 접한 길이 × 1.5미터를 뺀 면적(난간 유무 무관)","층고 1.5미터(경사지붕은 1.8미터)를 넘는 다락","공동주택이 아닌 건축물의 필로티 중 공중통행·차량통행·주차 전용이 아닌 부분"]},"오른쪽":{"이름":"불산입","항목":["승강기탑(옥상 출입용 승강장 포함), 계단탑, 장식탑","층고 1.5미터(경사지붕은 1.8미터) 이하 다락","공중통행·차량통행·주차 전용 필로티, 공동주택 필로티","공동주택 지상층의 기계실·전기실·어린이놀이터·조경시설·생활폐기물 보관시설"]}}],"함정":"1.5미터와 1.8미터를 바꿔 쓴 선지다. 평지붕에서 1.8미터 다락을 불산입으로 읽으면 안 된다. 노대 공식의 1.5미터도 같은 숫자라 서로 섞이기 쉽다."}},{"i":"S3-2-1-공법-30","r":"S3","g":2,"c":2,"n":70,"s":"공법","q":"건축법령상 대지에 공개 공지 또는 공개 공간을 설치하여야 하는 건축물은? (단, 건축물의 용도로 쓰는 바닥면적의 합계는 5천 제곱미터 이상이며, 건축법령상 특례 및 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["일반주거지역에 있는 초등학교","준주거지역에 있는 「농수산물 유통 및 가격안정에 관한 법률」에 따른 농수산물유통시설","일반상업지역에 있는 관망탑","자연녹지지역에 있는 「청소년활동진흥법」에 따른 유스호스텔","준공업지역에 있는 여객용 운수시설"],"a":[5],"L":"공4-3","o":"기출","x":{"한줄":"준공업지역은 설치 대상 지역이고, 여객용 운수시설은 바닥면적 합계 5천㎡ 이상이면 설치 대상 용도다.","근거":[{"법령":"건축법","조문":"제43조제1항","원문":"① 다음 각 호의 어느 하나에 해당하는 지역의 환경을 쾌적하게 조성하기 위하여 대통령령으로 정하는 용도와 규모의 건축물은 일반이 사용할 수 있도록 대통령령으로 정하는 기준에 따라 소규모 휴식시설 등의 공개 공지(空地: 공터) 또는 공개 공간(이하 \"공개공지등\"이라 한다)을 설치하여야 한다.\n1. 일반주거지역, 준주거지역\n2. 상업지역\n3. 준공업지역\n4. 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장이 도시화의 가능성이 크거나 노후 산업단지의 정비가 필요하다고 인정하여 지정ㆍ공고하는 지역"},{"법령":"건축법 시행령","조문":"제27조의2제1항","원문":"① 법 제43조제1항에 따라 다음 각 호의 어느 하나에 해당하는 건축물의 대지에는 공개 공지 또는 공개 공간(이하 이 조에서 \"공개공지등\"이라 한다)을 설치해야 한다. 이 경우 공개 공지는 필로티의 구조로 설치할 수 있다.\n1. 문화 및 집회시설, 종교시설, 판매시설(「농수산물 유통 및 가격안정에 관한 법률」에 따른 농수산물유통시설은 제외한다), 운수시설(여객용 시설만 해당한다), 업무시설 및 숙박시설로서 해당 용도로 쓰는 바닥면적의 합계가 5천 제곱미터 이상인 건축물\n2. 그 밖에 다중이 이용하는 시설로서 건축조례로 정하는 건축물"}],"선지":[{"번호":1,"판정":"틀림","설명":"일반주거지역은 설치 지역이지만 초등학교(교육연구시설)는 대상 용도가 아니다(영 제27조의2제1항제1호)."},{"번호":2,"판정":"틀림","설명":"준주거지역은 설치 지역이지만 판매시설 중 농수산물유통시설은 제외된다(영 제27조의2제1항제1호)."},{"번호":3,"판정":"틀림","설명":"일반상업지역은 설치 지역이지만 관망탑(관광휴게시설)은 대상 용도가 아니다."},{"번호":4,"판정":"틀림","설명":"자연녹지지역은 설치 지역이 아니다(법 제43조제1항). 유스호스텔(수련시설)도 대상 용도가 아니다."},{"번호":5,"판정":"옳음","설명":"준공업지역(법 제43조제1항제3호)의 운수시설 중 여객용 시설은 대상 용도다(영 제27조의2제1항제1호)."}],"개념":[{"종류":"표","제목":"공개공지등 설치 대상(법 제43조, 영 제27조의2)","머리":["구분","내용"],"행":[["대상 지역","일반주거지역, 준주거지역, 상업지역, 준공업지역, 시장·군수·구청장이 도시화 가능성이 크거나 노후 산업단지 정비가 필요하다고 보아 지정·공고한 지역"],["대상 용도","문화 및 집회시설, 종교시설, 판매시설(농수산물유통시설 제외), 운수시설(여객용 시설만), 업무시설, 숙박시설"],["규모","해당 용도로 쓰는 바닥면적 합계 5천㎡ 이상"],["그 밖에","다중이 이용하는 시설로서 건축조례로 정하는 건축물"],["설치 면적","대지면적의 100분의 10 이하 범위에서 건축조례로 정함"],["완화","용적률은 해당 지역 용적률의 1.2배 이하, 높이 제한은 1.2배 이하(조례 기준이 더 크면 조례)"],["활용","연간 60일 이내 문화행사·판촉활동 가능. 울타리 설치 등 이용을 막는 행위는 금지"]]}],"함정":"지역과 용도를 둘 다 맞춰야 한다. 1번과 2번과 3번은 지역은 맞고 용도가 어긋나며, 4번은 지역 자체가 어긋난다. 판매시설과 운수시설에 붙은 괄호 조건이 고르는 기준이다."}},{"i":"S3-2-1-공법-31","r":"S3","g":2,"c":2,"n":71,"s":"공법","q":"건축법령상 결합건축을 하려는 건축주가 건축허가를 신청할 때 첨부하는 결합건축협정서에 명시하여야 하는 사항은?","b":null,"bs":"없음","img":[],"ch":["결합건축 대상 대지의 소유권 외의 권리 현황","결합건축협정서를 체결하는 자가 법인인 경우 지방세 납세증명서","결합건축 대상 대지별 건축계획서","결합건축 대상 대지별 개별공시지가","결합건축으로 이전되는 용적률의 매매대금"],"a":[3],"L":"공4-4","o":"변형","x":{"한줄":"결합건축협정서에는 대지의 위치와 용도지역, 협정체결자 인적사항, 대지별 용적률, 대지별 건축계획서를 명시한다.","근거":[{"법령":"건축법","조문":"제77조의16제1항","원문":"① 결합건축을 하고자 하는 건축주는 제11조에 따라 건축허가를 신청하는 때에는 다음 각 호의 사항을 명시한 결합건축협정서를 첨부하여야 하며 국토교통부령으로 정하는 도서를 제출하여야 한다.\n1. 결합건축 대상 대지의 위치 및 용도지역\n2. 결합건축협정서를 체결하는 자(이하 \"결합건축협정체결자\"라 한다)의 성명, 주소 및 생년월일(법인, 법인 아닌 사단이나 재단 및 외국인의 경우에는 「부동산등기법」 제49조에 따라 부여된 등록번호를 말한다)\n3. 「국토의 계획 및 이용에 관한 법률」 제78조에 따라 조례로 정한 용적률과 결합건축으로 조정되어 적용되는 대지별 용적률\n4. 결합건축 대상 대지별 건축계획서"}],"선지":[{"번호":1,"판정":"틀림","설명":"협정서 명시사항 4가지에 없다(법 제77조의16제1항 각 호)."},{"번호":2,"판정":"틀림","설명":"협정체결자가 법인이면 성명·주소·생년월일 대신 「부동산등기법」 제49조에 따라 부여된 등록번호를 적는다(같은 항 제2호). 납세증명서는 명시사항이 아니다."},{"번호":3,"판정":"옳음","설명":"제4호. 결합건축 대상 대지별 건축계획서를 명시한다."},{"번호":4,"판정":"틀림","설명":"명시사항에 없다. 대지별 용적률은 조례로 정한 용적률과 결합건축으로 조정되어 적용되는 용적률이다(제3호)."},{"번호":5,"판정":"틀림","설명":"명시사항에 없다."}],"개념":[{"종류":"표","제목":"결합건축 요건과 절차(법 제77조의15~제77조의17, 영 제111조)","머리":["항목","내용"],"행":[["대상지역","상업지역, 역세권개발구역, 주거환경개선사업 정비구역, 건축협정구역·특별건축구역·리모델링 활성화 구역·도시재생활성화지역·건축자산 진흥구역"],["2개 대지","최단거리 100미터 이내, 같은 지역에 속하고 너비 12미터 이상 도로로 둘러싸인 하나의 구역 안(그 안에 더 작은 구역이 없을 것)"],["3개 이상 대지","공공기관 소유·관리 건축물과 결합, 빈집·빈 건축물 철거 후 공원·광장 설치 등의 경우에 모든 대지 간 최단거리 500미터 이내"],["협정서 명시사항","대지의 위치·용도지역, 협정체결자 인적사항, 대지별 용적률, 대지별 건축계획서"],["심의","건축위원회 심의. 조정된 용적률이 조례 용적률의 100분의 20을 초과하면 건축위원회와 도시계획위원회 공동 심의"],["협정 유지기간","최소 30년(용적률을 종전대로 환원하여 신축·개축·재축하는 경우 제외)"],["폐지","결합건축협정체결자 전원이 동의해 허가권자에게 신고. 용적률을 이전받은 건축물이 멸실된 것을 확인한 후 수리"]]},{"종류":"흐름","제목":"결합건축 절차","단계":[{"이름":"합의","설명":"대상지 요건에 맞는 2개(예외적으로 3개 이상) 대지의 건축주가 합의"},{"이름":"건축허가 신청","설명":"결합건축협정서와 국토교통부령이 정한 도서를 첨부(법 제77조의16제1항)"},{"이름":"심의","설명":"건축위원회 심의. 20% 초과 시 도시계획위원회와 공동 심의(같은 조 제3항)"},{"이름":"허가·공고·관리","설명":"허가권자가 공고하고 결합건축 관리대장 작성, 건축물대장에 명시(법 제77조의17제1항, 제3항)"},{"이름":"사용승인","설명":"다른 대지의 착공신고 또는 영 제111조의3의 조치가 이행되었는지 확인한 뒤 사용승인(같은 조 제2항)"}]}],"함정":"명시사항은 네 가지뿐이다. 2번은 법인 체결자라는 단서가 붙어 그럴듯해 보이지만 적는 것은 납세증명서가 아니라 등록번호다. 협정 유지기간 30년은 별도 규정이므로 명시사항 목록과 구분한다."}},{"i":"S3-2-1-공법-32","r":"S3","g":2,"c":2,"n":72,"s":"공법","q":"건축법령상 건축협정에 관한 설명으로 옳은 것은? (단, 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["건축협정 체결 대상 토지가 둘 이상의 시ㆍ군ㆍ구에 걸치는 경우에는 대상 토지면적의 과반이 속하는 건축협정인가권자에게 인가를 신청할 수 있으며, 이 경우 인가 전에 다른 시장ㆍ군수ㆍ구청장과 협의하여야 한다.","협정체결자는 인가받은 건축협정을 변경하려면 경미한 사항을 변경하는 경우에도 변경인가를 받아야 한다.","건축협정인가권자는 건축협정을 인가하기 전에 지방도시계획위원회의 심의를 거쳐야 한다.","협정체결자는 건축협정운영회를 설립하려면 협정체결자 전원의 동의를 받아야 한다.","건축협정이 공고된 후 건축협정구역의 토지에 관한 권리를 협정체결자로부터 이전받은 자는 건축협정에서 달리 정한 경우에도 협정체결자의 지위를 승계한다."],"a":[1],"L":"공4-4","o":"변형","x":{"한줄":"건축협정 대상 토지가 둘 이상의 시·군·구에 걸치면 토지면적 과반이 속하는 인가권자에게 신청하고, 인가권자는 다른 시장등과 협의한다.","근거":[{"법령":"건축법","조문":"제77조의6제1항·제2항","원문":"① 협정체결자 또는 건축협정운영회의 대표자는 건축협정서를 작성하여 국토교통부령으로 정하는 바에 따라 해당 건축협정인가권자의 인가를 받아야 한다. 이 경우 인가신청을 받은 건축협정인가권자는 인가를 하기 전에 건축협정인가권자가 두는 건축위원회의 심의를 거쳐야 한다.\n② 제1항에 따른 건축협정 체결 대상 토지가 둘 이상의 특별자치시 또는 시ㆍ군ㆍ구에 걸치는 경우 건축협정 체결 대상 토지면적의 과반(過半)이 속하는 건축협정인가권자에게 인가를 신청할 수 있다. 이 경우 인가 신청을 받은 건축협정인가권자는 건축협정을 인가하기 전에 다른 특별자치시장 또는 시장ㆍ군수ㆍ구청장과 협의하여야 한다."},{"법령":"건축법","조문":"제77조의7제1항","원문":"① 협정체결자 또는 건축협정운영회의 대표자는 제77조의6제1항에 따라 인가받은 사항을 변경하려면 국토교통부령으로 정하는 바에 따라 변경인가를 받아야 한다. 다만, 대통령령으로 정하는 경미한 사항을 변경하는 경우에는 그러하지 아니하다."},{"법령":"건축법","조문":"제77조의5제2항","원문":"② 제1항에 따라 건축협정운영회를 설립하려면 협정체결자 과반수의 동의를 받아 건축협정운영회의 대표자를 선임하고, 국토교통부령으로 정하는 바에 따라 건축협정인가권자에게 신고하여야 한다. 다만, 제77조의6에 따른 건축협정 인가 신청 시 건축협정운영회에 관한 사항을 포함한 경우에는 그러하지 아니하다."},{"법령":"건축법","조문":"제77조의10제2항","원문":"② 제77조의6제3항에 따라 건축협정이 공고된 후 건축협정구역에 있는 토지나 건축물 등에 관한 권리를 협정체결자인 소유자등으로부터 이전받거나 설정받은 자는 협정체결자로서의 지위를 승계한다. 다만, 건축협정에서 달리 정한 경우에는 그에 따른다."}],"선지":[{"번호":1,"판정":"옳음","설명":"법 제77조의6제2항."},{"번호":2,"판정":"틀림","설명":"대통령령으로 정하는 경미한 사항의 변경은 변경인가가 필요 없다(법 제77조의7제1항 단서)."},{"번호":3,"판정":"틀림","설명":"인가 전에 건축협정인가권자가 두는 건축위원회의 심의를 거친다(법 제77조의6제1항). 도시계획위원회가 아니다."},{"번호":4,"판정":"틀림","설명":"건축협정운영회는 협정체결자 과반수의 동의로 설립하고 대표자를 선임해 신고한다(법 제77조의5제2항)."},{"번호":5,"판정":"틀림","설명":"공고 후 권리를 이전받은 자는 협정체결자의 지위를 승계하되, 건축협정에서 달리 정한 경우에는 그에 따른다(법 제77조의10제2항 단서)."}],"개념":[{"종류":"표","제목":"건축협정 단계별 기준(법 제77조의4~제77조의10)","머리":["단계","기준","조문"],"행":[["체결","토지·건축물 소유자, 지상권자 등(소유자등) 전원의 합의. 지구단위계획구역, 주거환경개선사업 정비구역, 존치지역, 도시재생활성화지역 등","제77조의4제1항"],["건축협정서","명칭, 대상 지역의 위치·범위, 목적, 내용, 협정체결자 인적사항, 운영회 정보, 유효기간, 위반 시 제재 등","제77조의4제5항"],["운영회","협정체결자 과반수 동의로 대표자 선임 후 인가권자에게 신고","제77조의5제2항"],["인가","협정서를 작성해 인가권자의 인가. 인가 전 건축위원회 심의. 면적 과반이 속하는 인가권자에게 신청 가능","제77조의6"],["변경","변경인가(경미한 사항은 제외)","제77조의7"],["폐지","협정체결자 과반수 동의를 받아 인가권자의 인가","제77조의9제1항"],["효력·승계","건축협정구역에서 건축 등을 하려는 소유자등은 인가된 협정에 따름. 공고 후 권리를 이전받은 자는 지위 승계(협정에서 달리 정하면 그에 따름)","제77조의10"]]},{"종류":"흐름","제목":"건축협정 체결에서 효력까지","단계":[{"이름":"체결","설명":"소유자등 전원이 합의해 건축협정서 작성(협정서 명시사항 충족)"},{"이름":"인가 신청","설명":"협정체결자 또는 운영회 대표자가 인가권자에게 신청"},{"이름":"심의·인가","설명":"인가권자의 건축위원회 심의를 거쳐 인가"},{"이름":"공고","설명":"인가권자가 그 내용을 공고(법 제77조의6제3항)"},{"이름":"효력","설명":"공고 이후 권리를 이전받은 자도 승계. 변경은 변경인가, 폐지는 과반수 동의 + 인가"}]}],"함정":"변경과 폐지의 동의율, 설립과 체결의 동의율이 서로 다르다. 체결은 소유자등 전원, 운영회 설립과 폐지 동의는 협정체결자 과반수다. 5번은 승계 규정의 단서를 지워 놓았다."}},{"i":"S3-2-1-공법-33","r":"S3","g":2,"c":2,"n":73,"s":"공법","q":"주택법령상 용어에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["폭 10m인 일반도로로 분리된 토지는 각각 별개의 주택단지이다.","공구란 하나의 주택단지에서 둘 이상으로 구분되는 일단의 구역으로서, 공구 간 경계는 너비 4미터 이상으로 설정한다.","국민주택규모란 주거전용면적이 1세대당 85제곱미터 이하인 주택을 말하며, 수도권의 도시지역이 아닌 읍 또는 면 지역은 1세대당 100제곱미터 이하이다.","도시형 생활주택은 도시지역이 아닌 지역에서도 건설할 수 있다.","「혁신도시 조성 및 발전에 관한 특별법」에 따른 혁신도시개발사업에 의하여 개발ㆍ조성되는 공동주택이 건설되는 용지는 공공택지에 해당한다."],"a":[5],"L":"공5-1","o":"변형","x":{"한줄":"혁신도시개발사업으로 개발·조성되는 공동주택용지는 공공택지다.","근거":[{"법령":"주택법","조문":"제2조제24호아목","원문":"24. \"공공택지\"란 다음 각 목의 어느 하나에 해당하는 공공사업에 의하여 개발ㆍ조성되는 공동주택이 건설되는 용지를 말한다.\n아. 「혁신도시 조성 및 발전에 관한 특별법」에 따른 혁신도시개발사업"},{"법령":"주택법","조문":"제2조제12호","원문":"12. \"주택단지\"란 제15조에 따른 주택건설사업계획 또는 대지조성사업계획의 승인을 받아 주택과 그 부대시설 및 복리시설을 건설하거나 대지를 조성하는 데 사용되는 일단(一團)의 토지를 말한다. 다만, 다음 각 목의 시설로 분리된 토지는 각각 별개의 주택단지로 본다.\n가. 철도ㆍ고속도로ㆍ자동차전용도로\n나. 폭 20미터 이상인 일반도로\n다. 폭 8미터 이상인 도시계획예정도로\n라. 가목부터 다목까지의 시설에 준하는 것으로서 대통령령으로 정하는 시설"},{"법령":"주택법 시행령","조문":"제8조","원문":"제8조(공구의 구분기준) 법 제2조제18호에서 \"대통령령으로 정하는 기준\"이란 다음 각 호의 요건을 모두 충족하는 것을 말한다.\n1. 다음 각 목의 어느 하나에 해당하는 시설을 설치하거나 공간을 조성하여 6미터 이상의 너비로 공구 간 경계를 설정할 것\n가. 「주택건설기준 등에 관한 규정」 제26조에 따른 주택단지 안의 도로\n나. 주택단지 안의 지상에 설치되는 부설주차장\n다. 주택단지 안의 옹벽 또는 축대\n라. 식재ㆍ조경이 된 녹지\n마. 그 밖에 어린이놀이터 등 부대시설이나 복리시설로서 사업계획 승인권자가 적합하다고 인정하는 시설\n2. 공구별 세대수는 300세대 이상으로 할 것"},{"법령":"주택법","조문":"제2조제6호","원문":"6. \"국민주택규모\"란 주거의 용도로만 쓰이는 면적(이하 \"주거전용면적\"이라 한다)이 1호(戶) 또는 1세대당 85제곱미터 이하인 주택(「수도권정비계획법」 제2조제1호에 따른 수도권을 제외한 도시지역이 아닌 읍 또는 면 지역은 1호 또는 1세대당 주거전용면적이 100제곱미터 이하인 주택을 말한다)을 말한다. 이 경우 주거전용면적의 산정방법은 국토교통부령으로 정한다."},{"법령":"주택법 시행령","조문":"제10조제1항(본문)","원문":"① 법 제2조제20호에서 \"대통령령으로 정하는 주택\"이란 「국토의 계획 및 이용에 관한 법률」 제36조제1항제1호에 따른 도시지역에 건설하는 다음 각 호의 주택을 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"일반도로는 폭 20미터 이상이어야 주택단지를 나눈다(법 제2조제12호나목)."},{"번호":2,"판정":"틀림","설명":"공구 간 경계는 6미터 이상의 너비로 설정하고, 공구별 세대수는 300세대 이상이다(영 제8조제1호, 제2호)."},{"번호":3,"판정":"틀림","설명":"100제곱미터 이하는 수도권을 '제외한' 도시지역이 아닌 읍·면 지역에 적용한다(법 제2조제6호). 수도권의 읍·면은 85제곱미터 이하다."},{"번호":4,"판정":"틀림","설명":"도시형 생활주택은 도시지역에 건설하는 주택이다(영 제10조제1항)."},{"번호":5,"판정":"옳음","설명":"법 제2조제24호아목."}],"개념":[{"종류":"표","제목":"주택법 용어 기준(법 제2조, 영 제8조·제10조)","머리":["용어","기준"],"행":[["국민주택규모","주거전용면적 1호(세대)당 85㎡ 이하. 수도권을 제외한 도시지역이 아닌 읍·면 지역은 100㎡ 이하(제6호)"],["주택단지 분리 시설","철도·고속도로·자동차전용도로, 폭 20m 이상 일반도로, 폭 8m 이상 도시계획예정도로, 이에 준하는 시설(제12호)"],["공구","하나의 주택단지에서 구분되는 일단의 구역으로 착공신고·사용검사를 별도로 할 수 있는 구역. 6m 이상 너비의 경계, 공구별 300세대 이상(제18호, 영 제8조)"],["세대구분형 공동주택","주택 내부 공간 일부를 세대별로 구분해 생활이 가능한 구조로 하되 구분된 공간의 일부를 구분소유할 수 없는 주택(제19호)"],["도시형 생활주택","300세대 미만의 국민주택규모 주택으로 대통령령이 정하는 주택. 도시지역에 건설(제20호, 영 제10조)"],["공공택지","국민주택건설사업·대지조성사업, 택지개발사업, 산업단지개발사업, 공공주택지구조성사업, 혁신도시개발사업, 행정중심복합도시건설사업 등으로 조성되는 공동주택 용지(제24호)"]]},{"종류":"표","제목":"도시형 생활주택의 유형(영 제10조)","머리":["유형","요건","층수"],"행":[["아파트형 주택","아파트로서 세대별 욕실·부엌 설치, 지하층에 세대 설치 금지","-"],["단지형 연립주택","연립주택","건축위원회 심의를 받으면 제1종 전용·일반주거지역 5개층, 그 밖의 지역 6개층까지"],["단지형 다세대주택","다세대주택","같은 기준"],["혼합 건축","하나의 건축물에 도시형 생활주택과 그 밖의 주택은 원칙적으로 함께 건축 불가. 단지형 연립·다세대와 아파트형 주택도 함께 건축 불가","-"]]}],"함정":"숫자를 하나씩 바꾼 선지가 줄지어 있다. 10m와 20m, 4m와 6m, 수도권 포함과 제외를 구분해야 한다. 공공택지는 사업 이름 목록을 알아야 풀리며 혁신도시개발사업과 산업단지개발사업이 그 안에 있다.","개정":"도시형 생활주택의 유형은 영 제10조제1항에서 아파트형 주택·단지형 연립주택·단지형 다세대주택으로 규정한다. 예전 기출의 '원룸형(소형) 주택' 표현은 현행 '아파트형 주택'으로 읽는다(영 제10조제1항제1호, 개정 2025.1.21 포함)."}},{"i":"S3-2-1-공법-34","r":"S3","g":2,"c":2,"n":74,"s":"공법","q":"주택법령상 주택단지가 일정한 시설로 분리된 토지는 각각 별개의 주택단지로 본다. 그 시설에 해당하지 않는 것은?","b":null,"bs":"없음","img":[],"ch":["자동차전용도로","폭 6미터인 도시ㆍ군계획시설 국지도로","폭 25미터의 일반도로","「도로법」에 따른 지방도로서 보행자 및 자동차의 통행이 가능한 도로","폭 8미터인 도시계획예정도로"],"a":[2],"L":"공5-1","o":"변형","x":{"한줄":"도시·군계획시설 도로는 주간선도로, 보조간선도로, 집산도로, 폭 8미터 이상인 국지도로만 주택단지를 나눈다. 폭 6미터 국지도로는 해당하지 않는다.","근거":[{"법령":"주택법","조문":"제2조제12호","원문":"12. \"주택단지\"란 제15조에 따른 주택건설사업계획 또는 대지조성사업계획의 승인을 받아 주택과 그 부대시설 및 복리시설을 건설하거나 대지를 조성하는 데 사용되는 일단(一團)의 토지를 말한다. 다만, 다음 각 목의 시설로 분리된 토지는 각각 별개의 주택단지로 본다.\n가. 철도ㆍ고속도로ㆍ자동차전용도로\n나. 폭 20미터 이상인 일반도로\n다. 폭 8미터 이상인 도시계획예정도로\n라. 가목부터 다목까지의 시설에 준하는 것으로서 대통령령으로 정하는 시설"},{"법령":"주택법 시행령","조문":"제5조제1항","원문":"① 법 제2조제12호라목에서 \"대통령령으로 정하는 시설\"이란 보행자 및 자동차의 통행이 가능한 도로로서 다음 각 호의 어느 하나에 해당하는 도로를 말한다.\n1. 「국토의 계획 및 이용에 관한 법률」 제2조제7호에 따른 도시ㆍ군계획시설(이하 \"도시ㆍ군계획시설\"이라 한다)인 도로로서 국토교통부령으로 정하는 도로\n2. 「도로법」 제10조에 따른 일반국도ㆍ특별시도ㆍ광역시도 또는 지방도\n3. 그 밖에 관계 법령에 따라 설치된 도로로서 제1호 및 제2호에 준하는 도로"},{"법령":"주택법 시행규칙","조문":"제3조제1항","원문":"① 「주택법 시행령」(이하 \"영\"이라 한다) 제5조제1항제1호에서 \"국토교통부령으로 정하는 도로\"란 「도시ㆍ군계획시설의 결정ㆍ구조 및 설치기준에 관한 규칙」 제9조제3호에 따른 주간선도로, 보조간선도로, 집산도로(集散道路) 및 폭 8미터 이상인 국지도로를 말한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"자동차전용도로는 법 제2조제12호가목에 있다."},{"번호":2,"판정":"틀림","설명":"규칙 제3조제1항이 정한 도시·군계획시설 도로는 주간선·보조간선·집산도로와 폭 8미터 이상인 국지도로다. 6미터 국지도로는 빠진다."},{"번호":3,"판정":"옳음","설명":"폭 20미터 이상인 일반도로다(법 제2조제12호나목)."},{"번호":4,"판정":"옳음","설명":"지방도는 보행자 및 자동차 통행이 가능한 도로로서 영 제5조제1항제2호에 있다."},{"번호":5,"판정":"옳음","설명":"폭 8미터 이상인 도시계획예정도로다(법 제2조제12호다목). 8미터는 경계값으로 포함된다."}],"개념":[{"종류":"표","제목":"주택단지를 나누는 시설","머리":["근거","시설"],"행":[["법 제2조제12호가목","철도, 고속도로, 자동차전용도로"],["법 제2조제12호나목","폭 20미터 이상인 일반도로"],["법 제2조제12호다목","폭 8미터 이상인 도시계획예정도로"],["영 제5조제1항제1호, 규칙 제3조제1항","도시·군계획시설인 도로 중 주간선도로, 보조간선도로, 집산도로, 폭 8미터 이상인 국지도로"],["영 제5조제1항제2호","「도로법」상 일반국도, 특별시도, 광역시도, 지방도(보행자 및 자동차 통행이 가능한 도로)"],["영 제5조제1항제3호","그 밖에 관계 법령에 따라 설치된 도로로서 제1호·제2호에 준하는 도로"]]},{"종류":"표","제목":"구분기준에서 제외되는 도로(영 제5조제2항, 규칙 제3조제2항)","머리":["요건","내용"],"행":[["승인","사업계획승인권자가 인정하여 사업계획을 승인한 도로"],["도로 종류·폭","집산도로 또는 국지도로, 폭 15미터 미만"],["속도","설계속도 30km/h 이하이거나 통행속도를 30km/h 이내로 제한(보행자우선도로는 예외)"],["유지·변경","인근 주민 통행권 확보 등을 위해 기존 도로를 국토교통부령 기준에 맞게 유지·변경"],["보행 안전","지하도·육교·횡단보도 등 설치(보행자우선도로는 예외 가능)"]]}],"함정":"일반도로의 20미터와 도시계획예정도로의 8미터를 맞바꿔 외우면 틀린다. 도시·군계획시설 국지도로는 폭이 8미터 이상일 때만 포함된다는 규칙 조건이 새로 걸리는 자리다."}},{"i":"S3-2-1-공법-35","r":"S3","g":2,"c":2,"n":75,"s":"공법","q":"주택법령상 사전방문 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["사전방문한 입주예정자가 보수공사 등 적절한 조치를 요청한 사항이 하자가 아니라고 판단하는 사업주체는 사용검사권자에게 하자 여부를 확인해줄 것을 요청할 수 있다.","사업주체는 사전방문을 주택공급계약에 따라 정한 입주지정기간 시작일 60일 전까지 1일 이상 실시해야 한다.","사업주체가 사전방문을 실시하려는 경우, 사용검사권자에 대한 사전방문계획의 제출은 사전방문기간 시작일 1개월 전까지 해야 한다.","사용검사권자는 사업주체로부터 하자 여부의 확인 요청을 받은 날부터 7일 이내에 하자 여부를 확인하여 해당사업주체에게 통보해야 한다.","보수공사 등의 조치계획을 수립한 사업주체는 사전방문기간의 종료일부터 7일 이내에 사용검사권자에게 해당조치계획을 제출해야 한다."],"a":[2],"L":"공5-2","o":"기출","x":{"한줄":"사전방문은 입주지정기간 시작일 45일 전까지 2일 이상 실시한다.","근거":[{"법령":"주택법 시행규칙","조문":"제20조의2제1항·제2항","원문":"① 사업주체는 법 제48조의2제1항에 따른 사전방문(이하 \"사전방문\"이라 한다)을 주택공급계약에 따라 정한 입주지정기간 시작일 45일 전까지 2일 이상 실시해야 한다.\n② 사업주체가 사전방문을 실시하려는 경우에는 사전방문기간 및 방법 등 사전방문에 필요한 사항을 포함한  사전방문계획을 수립하여 사용검사권자에게 제출하고, 입주예정자에게 그 내용을 서면(전자문서를 포함한다)으로 알려야 한다. 이 경우 사전방문계획의 제출 및 통보는 사전방문기간 시작일 1개월 전까지 해야 한다."},{"법령":"주택법","조문":"제48조의2제4항","원문":"④ 제3항에도 불구하고 입주예정자가 요청한 사항이 하자가 아니라고 판단하는 사업주체는 대통령령으로 정하는 바에 따라 제49조제1항에 따른 사용검사를 하는 시장ㆍ군수ㆍ구청장(이하 \"사용검사권자\"라 한다)에게 하자 여부를 확인해줄 것을 요청할 수 있다. 이 경우 사용검사권자는 제48조의3에 따른 공동주택 품질점검단의 자문을 받는 등 대통령령으로 정하는 바에 따라 하자 여부를 확인할 수 있다."},{"법령":"주택법 시행령","조문":"제53조의3제3항","원문":"③ 사용검사권자는 제1항에 따라 확인 요청을 받은 날부터 7일 이내에 하자 여부를 확인하여 해당 사업주체에게 통보해야 한다."},{"법령":"주택법 시행령","조문":"제53조의2제3항","원문":"③ 조치계획을 수립한 사업주체는 법 제48조의2에 따른 사전방문 기간의 종료일부터 7일 이내에 사용검사권자(법 제49조제1항에 따라 사용검사를 하는 자를 말한다. 이하 같다)에게 해당 조치계획을 제출하고, 입주예정자에게 그 조치계획을 문서(전자문서를 포함한다)로 알려야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"법 제48조의2제4항 전단."},{"번호":2,"판정":"틀림","설명":"입주지정기간 시작일 45일 전까지 2일 이상 실시한다(규칙 제20조의2제1항)."},{"번호":3,"판정":"옳음","설명":"사전방문계획의 제출·통보는 사전방문기간 시작일 1개월 전까지다(규칙 제20조의2제2항)."},{"번호":4,"판정":"옳음","설명":"영 제53조의3제3항."},{"번호":5,"판정":"옳음","설명":"영 제53조의2제3항."}],"개념":[{"종류":"흐름","제목":"사전방문 절차","단계":[{"이름":"감리자 확인","설명":"전유부분과 공용부분(계단·복도·승강기·현관)이 설계도서대로 시공됐는지 감리자에게 확인받은 뒤 실시(규칙 제20조의2제3항)"},{"이름":"사전방문계획","설명":"사용검사권자에게 제출하고 입주예정자에게 서면 통보. 사전방문기간 시작일 1개월 전까지(규칙 제20조의2제2항)"},{"이름":"사전방문 실시","설명":"입주지정기간 시작일 45일 전까지 2일 이상(규칙 제20조의2제1항)"},{"이름":"하자 조치 요청","설명":"입주예정자가 사업주체에게 보수공사 등 조치 요청(법 제48조의2제2항)"},{"이름":"조치계획 제출","설명":"사전방문기간 종료일부터 7일 이내 사용검사권자에게 제출하고 입주예정자에게 통지(영 제53조의2제3항)"},{"이름":"하자 여부 확인","설명":"사업주체가 하자가 아니라고 판단하면 조치계획 제출 때 자료를 붙여 확인 요청. 사용검사권자는 7일 이내 통보(영 제53조의3)"},{"이름":"조치 완료","설명":"중대한 하자는 특별한 사유가 없으면 사용검사를 받기 전까지 완료(법 제48조의2제3항)"}]},{"종류":"표","제목":"사전방문 숫자 모음","머리":["항목","기준","근거"],"행":[["사전방문 시기·일수","입주지정기간 시작일 45일 전까지 2일 이상","규칙 제20조의2제1항"],["계획 제출","사전방문기간 시작일 1개월 전까지","규칙 제20조의2제2항"],["조치계획 제출","사전방문기간 종료일부터 7일 이내","영 제53조의2제3항"],["하자 여부 통보","확인 요청을 받은 날부터 7일 이내","영 제53조의3제3항"],["그 밖의 하자 조치(전유부분)","입주예정자에게 인도하기 전","영 제53조의2제2항제2호"]]}],"함정":"45일과 2일을 60일과 1일로 바꾼 선지 하나가 정답이다. 나머지 네 선지는 1개월, 7일, 7일, 하자 확인 요청처럼 외워 둔 기한이 맞게 나와서 오히려 안심하고 넘기게 된다. 정답률은 21%였다."}},{"i":"S3-2-1-공법-36","r":"S3","g":2,"c":2,"n":76,"s":"공법","q":"주택법령상 지역주택조합이 설립인가를 받은 후 결원이 발생한 범위에서 조합원을 충원할 수 있는 사유에 해당하지 않는 것은?","b":null,"bs":"없음","img":[],"ch":["조합원이 사망한 경우","사업계획승인 후 입주자로 선정된 지위가 증여로 변경된 경우(전매가 금지되는 경우는 제외)","조합원의 탈퇴로 조합원 수가 주택건설 예정 세대수의 40퍼센트가 된 경우","사업계획승인의 과정에서 주택건설 예정 세대수가 변경되어 조합원 수가 변경된 세대수의 45퍼센트가 된 경우","조합원의 탈퇴로 조합원 수가 주택건설 예정 세대수의 50퍼센트가 된 경우"],"a":[5],"L":"공5-2","o":"변형","x":{"한줄":"탈퇴로 충원할 수 있는 경우는 조합원 수가 주택건설 예정 세대수의 50퍼센트 '미만'이 될 때다. 50퍼센트 정확히는 해당하지 않는다.","근거":[{"법령":"주택법 시행령","조문":"제22조제1항","원문":"① 지역주택조합 또는 직장주택조합은 설립인가를 받은 후에는 해당 조합원을 교체하거나 신규로 가입하게 할 수 없다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 예외로 한다.\n1. 조합원 수가 주택건설 예정 세대수를 초과하지 아니하는 범위에서 시장ㆍ군수ㆍ구청장으로부터 국토교통부령으로 정하는 바에 따라 조합원 추가모집의 승인을 받은 경우\n2. 다음 각 목의 어느 하나에 해당하는 사유로 결원이 발생한 범위에서 충원하는 경우\n가. 조합원의 사망\n나. 법 제15조에 따른 사업계획승인 이후[지역주택조합 또는 직장주택조합이 제16조제2항제2호 단서에 따라 해당 주택건설대지 전부의 소유권을 확보하지 아니하고 법 제15조에 따른 사업계획승인을 받은 경우에는 해당 주택건설대지 전부의 소유권(해당 주택건설대지가 저당권등의 목적으로 되어 있는 경우에는 그 저당권등의 말소를 포함한다)을 확보한 이후를 말한다]에 입주자로 선정된 지위(해당 주택에 입주할 수 있는 권리ㆍ자격 또는 지위 등을 말한다)가 양도ㆍ증여 또는 판결 등으로 변경된 경우. 다만, 법 제64조제1항제1호에 따라 전매가 금지되는 경우는 제외한다.\n다. 조합원의 탈퇴 등으로 조합원 수가 주택건설 예정 세대수의 50퍼센트 미만이 되는 경우\n라. 조합원이 무자격자로 판명되어 자격을 상실하는 경우\n마. 법 제15조에 따른 사업계획승인 등의 과정에서 주택건설 예정 세대수가 변경되어 조합원 수가 변경된 세대수의 50퍼센트 미만이 되는 경우"}],"선지":[{"번호":1,"판정":"옳음","설명":"영 제22조제1항제2호가목."},{"번호":2,"판정":"옳음","설명":"사업계획승인 후 입주자로 선정된 지위가 양도·증여·판결로 변경된 경우는 충원 사유다. 법 제64조제1항제1호에 따라 전매가 금지되는 경우는 제외한다(같은 호 나목)."},{"번호":3,"판정":"옳음","설명":"50퍼센트 미만이므로 충원 사유다(같은 호 다목)."},{"번호":4,"판정":"옳음","설명":"변경된 세대수의 50퍼센트 미만이 된 경우다(같은 호 마목)."},{"번호":5,"판정":"틀림","설명":"50퍼센트는 '미만'에 들지 않는다(같은 호 다목)."}],"개념":[{"종류":"표","제목":"설립인가 후 조합원 교체·신규가입(영 제22조)","머리":["구분","내용"],"행":[["원칙","설립인가를 받은 후에는 조합원을 교체하거나 신규로 가입하게 할 수 없다"],["예외 1","조합원 수가 주택건설 예정 세대수를 초과하지 않는 범위에서 시장·군수·구청장의 추가모집 승인"],["예외 2(결원 충원)","조합원 사망 / 사업계획승인 후 입주자 지위의 양도·증여·판결 변경(전매금지 제외) / 탈퇴 등으로 조합원 수가 세대수의 50% 미만 / 무자격자로 판명 / 세대수 변경으로 조합원 수가 변경 세대수의 50% 미만"],["자격 판단 기준일","추가모집은 조합설립인가 신청일, 충원은 조합 가입 신청일"],["신청 시한","추가모집 승인과 변경인가 신청은 사업계획승인신청일까지"]]},{"종류":"표","제목":"조합원 모집(법 제11조의3)","머리":["항목","내용"],"행":[["모집 신고","주택건설대지의 50퍼센트 이상 사용권원을 확보해 시장·군수·구청장에게 신고 후 공개모집"],["결원 충원·재모집","공개모집 이후 사망·자격상실·탈퇴로 생긴 결원 충원이나 미달 재모집은 신고 없이 선착순으로 가능"],["신고 수리 불가","사업대지 중복, 건축 불가 대지, 업무대행자 요건 위반, 사실과 다른 신고"]]}],"함정":"50퍼센트 '미만'이라는 경계 표현을 놓치면 풀리지 않는다. 40%와 45%는 미만이라 충원 사유이고, 50%는 정확히 경계라서 사유가 아니다. 사업계획승인 후 지위 변경에는 전매금지 제외 괄호가 붙는다."}},{"i":"S3-2-1-공법-37","r":"S3","g":2,"c":2,"n":77,"s":"공법","q":"주택법령상 공동주택의 리모델링에 관한 설명으로 틀린 것은? (단, 조례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["세대수가 증가되는 리모델링을 하는 경우에는 기존 주택의 권리변동, 비용분담 등에 관한 권리변동계획을 수립하여 사업계획승인 또는 행위허가를 받아야 한다.","시장ㆍ군수ㆍ구청장이 세대수가 50세대 이상 증가하는 세대수 증가형 리모델링을 허가하려는 경우에는 시ㆍ군ㆍ구도시계획위원회의 심의를 거쳐야 한다.","시장ㆍ군수ㆍ구청장은 수직증축형 리모델링을 허가한 후 해당 건축물의 구조안전성 등에 대한 상세 확인을 위하여 안전진단을 실시하여야 한다.","증축형 리모델링의 안전진단 결과 건축물 구조의 안전에 위험이 있어 재건축사업의 시행이 필요하다고 결정된 건축물도 증축형 리모델링을 할 수 있다.","수직증축형 리모델링의 대상이 되는 기존 건축물의 층수가 15층인 경우에는 3개층까지 증축할 수 있다."],"a":[4],"L":"공5-3","o":"변형","x":{"한줄":"안전진단으로 재건축사업 시행이 필요하다고 결정된 건축물은 증축형 리모델링을 하여서는 아니 된다.","근거":[{"법령":"주택법","조문":"제68조제3항","원문":"③ 시장ㆍ군수ㆍ구청장이 제1항에 따른 안전진단으로 건축물 구조의 안전에 위험이 있다고 평가하여 「도시 및 주거환경정비법」 제2조제2호다목에 따른 재건축사업 및 「빈집 및 소규모주택 정비에 관한 특례법」 제2조제1항제3호다목에 따른 소규모재건축사업의 시행이 필요하다고 결정한 건축물은 증축형 리모델링을 하여서는 아니 된다."},{"법령":"주택법","조문":"제67조","원문":"제67조(권리변동계획의 수립) 세대수가 증가되는 리모델링을 하는 경우에는 기존 주택의 권리변동, 비용분담 등 대통령령으로 정하는 사항에 대한 계획(이하 \"권리변동계획\"이라 한다)을 수립하여 사업계획승인 또는 행위허가를 받아야 한다."},{"법령":"주택법","조문":"제66조제6항","원문":"⑥ 제1항에 따라 시장ㆍ군수ㆍ구청장이 세대수 증가형 리모델링(대통령령으로 정하는 세대수 이상으로 세대수가 증가하는 경우로 한정한다. 이하 이 조에서 같다)을 허가하려는 경우에는 기반시설에의 영향이나 도시ㆍ군관리계획과의 부합 여부 등에 대하여 「국토의 계획 및 이용에 관한 법률」 제113조제2항에 따라 설치된 시ㆍ군ㆍ구도시계획위원회(이하 \"시ㆍ군ㆍ구도시계획위원회\"라 한다)의 심의를 거쳐야 한다."},{"법령":"주택법 시행령","조문":"제76조제2항","원문":"② 법 제66조제6항에서 \"대통령령으로 정하는 세대수\"란 50세대를 말한다."},{"법령":"주택법","조문":"제68조제4항","원문":"④ 시장ㆍ군수ㆍ구청장은 제66조제1항에 따라 수직증축형 리모델링을 허가한 후에 해당 건축물의 구조안전성 등에 대한 상세 확인을 위하여 안전진단을 실시하여야 한다. 이 경우 안전진단을 의뢰받은 기관은 제2항에 따른 건축구조기술사와 함께 안전진단을 실시하여야 하며, 리모델링을 하려는 자는 안전진단 후 구조설계의 변경 등이 필요한 경우에는 건축구조기술사로 하여금 이를 보완하도록 하여야 한다."},{"법령":"주택법 시행령","조문":"제13조제1항제1호","원문":"① 법 제2조제25호다목1)에서 \"대통령령으로 정하는 범위\"란 다음 각 호의 구분에 따른 범위를 말한다.\n1. 수직으로 증축하는 행위(이하 \"수직증축형 리모델링\"이라 한다)의 대상이 되는 기존 건축물의 층수가 15층 이상인 경우: 3개층"}],"선지":[{"번호":1,"판정":"옳음","설명":"법 제67조."},{"번호":2,"판정":"옳음","설명":"법 제66조제6항, 영 제76조제2항(50세대)."},{"번호":3,"판정":"옳음","설명":"법 제68조제4항 전단."},{"번호":4,"판정":"틀림","설명":"재건축사업 시행이 필요하다고 결정된 건축물은 증축형 리모델링을 하여서는 아니 된다(법 제68조제3항)."},{"번호":5,"판정":"옳음","설명":"15층 이상은 3개층, 14층 이하는 2개층까지다(영 제13조제1항)."}],"개념":[{"종류":"표","제목":"리모델링 핵심 기준(법 제2조제25호, 제66조~제68조, 영 제13조)","머리":["항목","기준"],"행":[["허가","입주자·사용자·관리주체가 시장·군수·구청장의 허가. 리모델링 결의를 한 조합이나 소유자 전원 동의를 받은 입주자대표회의도 허가를 받아 시행"],["증축 요건","사용검사일 또는 사용승인일부터 15년(조례로 15~20년)이 지난 공동주택"],["증축 범위","각 세대 주거전용면적의 30퍼센트 이내(85㎡ 미만은 40퍼센트 이내)"],["세대수 증가","증축 가능 면적 합산 범위에서 기존 세대수의 15퍼센트 이내"],["수직증축 층수","기존 15층 이상 3개층, 14층 이하 2개층(법은 최대 3개층 이하)"],["수직증축 요건","신축 당시 구조도 보유"],["도시계획위원회 심의","세대수 증가형 중 50세대 이상 증가하는 경우"],["권리변동계획","세대수가 증가되는 리모델링에서 수립"]]},{"종류":"흐름","제목":"증축형 리모델링의 안전진단","단계":[{"이름":"안전진단 요청","설명":"증축형 리모델링을 하려는 자가 시장·군수·구청장에게 요청(법 제68조제1항)"},{"이름":"안전진단 실시","설명":"시장·군수·구청장이 증축 가능 여부 확인을 위해 실시. 대통령령이 정한 기관에 의뢰하고 리모델링하려는 자가 추천한 건축구조기술사와 함께 실시(제2항)"},{"이름":"재건축 필요 결정","설명":"구조 안전에 위험이 있어 재건축이 필요하다고 결정되면 증축형 리모델링 불가(제3항)"},{"이름":"허가 후 상세 확인","설명":"수직증축형 리모델링은 허가 후 구조안전성 상세 확인용 안전진단을 다시 실시(제4항)"},{"이름":"비용","설명":"시장·군수·구청장은 안전진단 비용의 전부 또는 일부를 리모델링하려는 자에게 부담시킬 수 있다(제6항)"}]}],"함정":"안전진단은 두 번 나온다. 허가 전에는 증축 가능 여부를 확인하고, 수직증축형은 허가 후 구조안전성을 다시 확인한다. 4번은 재건축 판정을 받은 건축물에 증축형 리모델링을 허용하는 문장이어서 법 제68조제3항과 반대다.","개정":"수직증축형 리모델링은 법에서 최대 3개층 이하로 하고, 영에서 기존 15층 이상이면 3개층, 14층 이하이면 2개층으로 정한다(법 제2조제25호다목1), 영 제13조제1항)."}},{"i":"S3-2-1-공법-38","r":"S3","g":2,"c":2,"n":78,"s":"공법","q":"주택법령상 주택의 공급에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["「관광진흥법」에 따라 지정된 관광특구에서 건설ㆍ공급하는 층수가 49층이고 높이가 160m인 아파트는 분양가상한제의 적용대상이다.","도시형 생활주택은 공공택지에서 공급하는 경우에도 분양가상한제 적용주택이다.","국토교통부장관은 주택가격이 급등하거나 급등할 우려가 있는 지역으로서 대통령령으로 정하는 기준을 충족하는 지역을 주거정책심의위원회 심의를 거쳐 분양가상한제 적용 지역으로 지정할 수 있으며, 지정하는 경우 미리 시ㆍ도지사의 의견을 들어야 한다.","주택의 사용검사 후 토지의 소유권을 회복한 실소유자에게 매도청구 소송을 제기하기 위해 주택소유자들이 대표자를 선정하려면 주택소유자 전체의 과반수 동의를 받아야 한다.","주택의 소유자들이 사용검사 후 매도청구를 하는 경우 매도청구의 의사표시는 실소유자가 해당 토지 소유권을 회복한 날부터 3년 이내에 실소유자에게 송달되어야 한다."],"a":[3],"L":"공5-3","o":"변형","x":{"한줄":"분양가상한제 적용 지역은 국토교통부장관이 주거정책심의위원회 심의를 거쳐 지정하고, 지정 전에 시·도지사의 의견을 듣는다.","근거":[{"법령":"주택법","조문":"제58조제1항·제2항","원문":"① 국토교통부장관은 제57조제1항제2호에 따라 주택가격상승률이 물가상승률보다 현저히 높은 지역으로서 그 지역의 주택가격ㆍ주택거래 등과 지역 주택시장 여건 등을 고려하였을 때 주택가격이 급등하거나 급등할 우려가 있는 지역 중 대통령령으로 정하는 기준을 충족하는 지역은 주거정책심의위원회 심의를 거쳐 분양가상한제 적용 지역으로 지정할 수 있다.\n② 국토교통부장관이 제1항에 따라 분양가상한제 적용 지역을 지정하는 경우에는 미리 시ㆍ도지사의 의견을 들어야 한다."},{"법령":"주택법","조문":"제57조제2항(제1호·제3호)","원문":"② 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 제1항을 적용하지 아니한다.\n1. 도시형 생활주택\n3. 「관광진흥법」 제70조제1항 또는 제2항에 따라 지정된 관광특구에서 건설ㆍ공급하는 공동주택으로서 해당 건축물의 층수가 50층 이상이거나 높이가 150미터 이상인 경우"},{"법령":"주택법","조문":"제62조제2항·제5항","원문":"② 주택의 소유자들은 대표자를 선정하여 제1항에 따른 매도청구에 관한 소송을 제기할 수 있다. 이 경우 대표자는 주택의 소유자 전체의 4분의 3 이상의 동의를 받아 선정한다.\n⑤ 제1항에 따른 매도청구의 의사표시는 실소유자가 해당 토지 소유권을 회복한 날부터 2년 이내에 해당 실소유자에게 송달되어야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"관광특구의 공동주택은 층수 50층 이상이거나 높이 150미터 이상이면 분양가상한제 적용 제외다(법 제57조제2항제3호). 49층이어도 높이가 160미터이면 제외된다."},{"번호":2,"판정":"틀림","설명":"도시형 생활주택은 분양가상한제를 적용하지 않는다(법 제57조제2항제1호). 택지 종류와 무관하다."},{"번호":3,"판정":"옳음","설명":"법 제58조제1항·제2항."},{"번호":4,"판정":"틀림","설명":"대표자는 주택소유자 전체의 4분의 3 이상 동의로 선정한다(법 제62조제2항)."},{"번호":5,"판정":"틀림","설명":"의사표시는 소유권 회복일부터 2년 이내에 송달되어야 한다(법 제62조제5항)."}],"개념":[{"종류":"표","제목":"분양가상한제 적용 범위(법 제57조)","머리":["구분","내용"],"행":[["적용","공공택지, 공공택지 외 택지로서 국토교통부장관이 주거정책심의위원회 심의를 거쳐 지정한 지역"],["제외","도시형 생활주택"],["제외","경제자유구역에서 외자유치와 관련해 경제자유구역위원회가 적용하지 않기로 의결한 공동주택"],["제외","관광특구의 공동주택으로 50층 이상이거나 높이 150미터 이상"],["제외","한국토지주택공사·지방공사가 시행자로 참여하는 일정 정비사업·소규모주택정비사업 등 공공성 요건 충족 주택"],["제외","주거환경개선사업, 공공재개발사업, 혁신지구재생사업(주거재생혁신지구), 도심 공공주택 복합사업, 쪽방 밀집지역 공공주택사업의 주택"]]},{"종류":"표","제목":"사용검사 후 매도청구(법 제62조)와 지정권자","머리":["항목","기준"],"행":[["청구 주체·상대","주택(복리시설 포함) 소유자들이 사용검사 후 토지 소유권을 회복한 실소유자에게 시가로 매도 청구"],["소송 대표자","주택소유자 전체의 4분의 3 이상 동의로 선정. 판결은 소유자 전체에 효력"],["면적 요건","해당 토지가 주택단지 전체 대지면적의 5퍼센트 미만"],["의사표시 기한","소유권 회복일부터 2년 이내 송달"],["비용","주택소유자들은 사업주체에게 구상 가능"],["투기과열지구","국토교통부장관 또는 시·도지사가 주거정책심의위원회 심의를 거쳐 지정(법 제63조제1항)"],["분양가상한제 적용 지역·조정대상지역","국토교통부장관이 지정(법 제58조, 제63조의2)"]]}],"함정":"지정권자가 지역마다 다르다. 투기과열지구는 국토교통부장관 또는 시·도지사, 분양가상한제 지역과 조정대상지역은 국토교통부장관이다. 관광특구 기준은 '그리고'가 아니라 '또는'이라서 49층이어도 160미터이면 제외된다."}},{"i":"S3-2-1-공법-39","r":"S3","g":2,"c":2,"n":79,"s":"공법","q":"농지법령상 농지 소유자가 소유농지를 위탁경영할 수 있는 경우로서 옳은 것을 모두 고른 것은?","b":"ㄱ. 농업법인이 청산 중인 경우\nㄴ. 「병역법」에 따라 징집된 경우\nㄷ. 3월 이상의 치료가 필요한 부상으로 자경할 수 없는 경우\nㄹ. 6개월간 국내 여행 중인 경우","bs":"글자","img":[],"ch":["ㄱ, ㄴ","ㄷ, ㄹ","ㄱ, ㄴ, ㄷ","ㄴ, ㄷ, ㄹ","ㄱ, ㄴ, ㄷ, ㄹ"],"a":[3],"L":"공6-1","o":"기출","x":{"한줄":"위탁경영이 허용되는 것은 ㄱ(농업법인 청산 중), ㄴ(징집), ㄷ(부상으로 3월 이상 치료)이다. 국외 여행은 3개월 이상이어야 하므로 국내 여행은 해당하지 않는다.","근거":[{"법령":"농지법","조문":"제9조","원문":"제9조(농지의 위탁경영) 농지 소유자는 다음 각 호의 어느 하나에 해당하는 경우 외에는 소유 농지를 위탁경영할 수 없다.\n1. 「병역법」에 따라 징집 또는 소집된 경우\n2. 3개월 이상 국외 여행 중인 경우\n3. 농업법인이 청산 중인 경우\n4. 질병, 취학, 선거에 따른 공직 취임, 그 밖에 대통령령으로 정하는 사유로 자경할 수 없는 경우\n5. 제17조에 따른 농지이용증진사업 시행계획에 따라 위탁경영하는 경우\n6. 농업인이 자기 노동력이 부족하여 농작업의 일부를 위탁하는 경우"},{"법령":"농지법 시행령","조문":"제8조제1항","원문":"①법 제9조제4호에서 \"그 밖에 대통령령으로 정하는 사유\"란 다음 각 호의 어느 하나에 해당하는 사유를 말한다.\n1. 부상으로 3월 이상의 치료가 필요한 경우\n2. 교도소ㆍ구치소 또는 보호감호시설에 수용 중인 경우\n3. 임신 중이거나 분만 후 6개월 미만인 경우"}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ, ㄴ은 맞지만 ㄷ이 빠졌다."},{"번호":2,"판정":"-","설명":"ㄷ은 맞지만 ㄹ이 틀리고 ㄱ, ㄴ이 빠졌다."},{"번호":3,"판정":"-","설명":"ㄱ, ㄴ, ㄷ이 모두 맞고 ㄹ이 틀리다."},{"번호":4,"판정":"-","설명":"ㄹ이 틀리고 ㄱ이 빠졌다."},{"번호":5,"판정":"-","설명":"ㄹ이 틀려서 전부 맞는 조합이 아니다."}],"보기판정":[{"기호":"ㄱ","판정":"옳음","설명":"농업법인이 청산 중이면 위탁경영할 수 있다(법 제9조제3호)."},{"기호":"ㄴ","판정":"옳음","설명":"「병역법」에 따라 징집 또는 소집된 경우다(법 제9조제1호)."},{"기호":"ㄷ","판정":"옳음","설명":"부상으로 3월 이상의 치료가 필요한 경우다(영 제8조제1항제1호, 법 제9조제4호)."},{"기호":"ㄹ","판정":"틀림","설명":"위탁경영 사유는 3개월 이상 '국외' 여행 중인 경우다(법 제9조제2호). 국내 여행은 해당하지 않는다."}],"개념":[{"종류":"표","제목":"위탁경영이 가능한 경우(농지법 제9조, 영 제8조)","머리":["근거","사유"],"행":[["법 제9조제1호","「병역법」에 따라 징집 또는 소집된 경우"],["법 제9조제2호","3개월 이상 국외 여행 중인 경우"],["법 제9조제3호","농업법인이 청산 중인 경우"],["법 제9조제4호","질병, 취학, 선거에 따른 공직 취임, 그 밖에 대통령령으로 정하는 사유로 자경할 수 없는 경우"],["영 제8조제1항","부상으로 3월 이상 치료가 필요한 경우 / 교도소·구치소·보호감호시설 수용 중 / 임신 중이거나 분만 후 6개월 미만"],["법 제9조제5호","농지이용증진사업 시행계획에 따라 위탁경영하는 경우"],["법 제9조제6호","농업인이 자기 노동력이 부족하여 농작업의 일부를 위탁하는 경우"]]},{"종류":"표","제목":"자기 노동력이 부족한 경우(영 제8조제2항)","머리":["구분","기준"],"행":[["원칙","통상적인 농업경영관행에 따라 자기 또는 세대원의 노동력으로 해당 농지의 농작업 전부를 행할 수 없는 경우"],["요건 1","벼·과수·그 밖의 농작물의 재배작물별 주요 농작업의 3분의 1 이상을 자기 또는 세대원의 노동력으로 하는 경우"],["요건 2","자기의 농업경영에 관련된 해당 농작업에 1년 중 30일 이상 직접 종사하는 경우"]]}],"함정":"ㄹ은 국외 여행이 아니라 국내 여행이고 기간도 6개월이라 여행이라는 말에 끌린다. 법에 있는 것은 3개월 이상 '국외' 여행이다. ㄷ의 3월 이상 부상 치료는 법이 아니라 시행령 제8조제1항에 있어서 놓치기 쉽다."}},{"i":"S3-2-1-공법-40","r":"S3","g":2,"c":2,"n":80,"s":"공법","q":"농지법령상 농업진흥지역에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["광역시의 녹지지역은 농업진흥지역 지정 대상이 될 수 있다.","농업진흥지역은 시장ㆍ군수 또는 자치구구청장이 지정한다.","시ㆍ도지사는 시ㆍ도 농업ㆍ농촌및식품산업정책심의회의 심의를 거치지 아니하고 농림축산식품부장관의 승인만으로 농업진흥지역을 지정한다.","농업보호구역은 농지가 집단화되어 농업 목적으로 이용할 필요가 있는 지역으로서 농림축산식품부장관이 정하는 규모의 지역이다.","농림축산식품부장관은 녹지지역이나 계획관리지역이 농업진흥지역에 포함되면 승인하기 전에 환경부장관과 협의하여야 한다."],"a":[1],"L":"공6-1","o":"변형","x":{"한줄":"농업진흥지역 지정 대상은 녹지지역·관리지역·농림지역·자연환경보전지역이고 특별시의 녹지지역만 제외된다. 광역시의 녹지지역은 대상이다.","근거":[{"법령":"농지법","조문":"제29조","원문":"제29조(농업진흥지역의 지정 대상) 제28조에 따른 농업진흥지역 지정은 「국토의 계획 및 이용에 관한 법률」에 따른 녹지지역ㆍ관리지역ㆍ농림지역 및 자연환경보전지역을 대상으로 한다. 다만, 특별시의 녹지지역은 제외한다."},{"법령":"농지법","조문":"제28조제1항·제2항","원문":"①시ㆍ도지사는 농지를 효율적으로 이용하고 보전하기 위하여 농업진흥지역을 지정한다.\n②제1항에 따른 농업진흥지역은 다음 각 호의 용도구역으로 구분하여 지정할 수 있다.\n1. 농업진흥구역: 농업의 진흥을 도모하여야 하는 다음 각 목의 어느 하나에 해당하는 지역으로서 농림축산식품부장관이 정하는 규모로 농지가 집단화되어 농업 목적으로 이용할 필요가 있는 지역\n가. 농지조성사업 또는 농업기반정비사업이 시행되었거나 시행 중인 지역으로서 농업용으로 이용하고 있거나 이용할 토지가 집단화되어 있는 지역\n나. 가목에 해당하는 지역 외의 지역으로서 농업용으로 이용하고 있는 토지가 집단화되어 있는 지역\n2. 농업보호구역: 농업진흥구역의 용수원 확보, 수질 보전 등 농업 환경을 보호하기 위하여 필요한 지역"},{"법령":"농지법","조문":"제30조제1항·제3항","원문":"①시ㆍ도지사는 시ㆍ도 농업ㆍ농촌및식품산업정책심의회의 심의를 거쳐 농림축산식품부장관의 승인을 받아 농업진흥지역을 지정한다.\n③농림축산식품부장관은 「국토의 계획 및 이용에 관한 법률」에 따른 녹지지역이나 계획관리지역이 농업진흥지역에 포함되면 제1항에 따른 농업진흥지역 지정을 승인하기 전에 국토교통부장관과 협의하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"제외되는 것은 특별시의 녹지지역뿐이다(법 제29조 단서)."},{"번호":2,"판정":"틀림","설명":"지정권자는 시·도지사다(법 제28조제1항)."},{"번호":3,"판정":"틀림","설명":"시·도 농업·농촌및식품산업정책심의회의 심의를 거쳐 농림축산식품부장관의 승인을 받는다(법 제30조제1항)."},{"번호":4,"판정":"틀림","설명":"그 설명은 농업진흥구역이다. 농업보호구역은 농업진흥구역의 용수원 확보, 수질 보전 등 농업 환경을 보호하기 위해 필요한 지역이다(법 제28조제2항)."},{"번호":5,"판정":"틀림","설명":"협의 상대는 국토교통부장관이다(법 제30조제3항)."}],"개념":[{"종류":"표","제목":"농업진흥지역(농지법 제28조~제31조)","머리":["항목","내용"],"행":[["지정권자","시·도지사"],["지정 대상","녹지지역·관리지역·농림지역·자연환경보전지역. 특별시의 녹지지역은 제외(제29조)"],["용도구역","농업진흥구역(농지가 집단화되어 농업 목적으로 이용할 필요가 있는 지역), 농업보호구역(농업진흥구역의 용수원 확보, 수질 보전 등 농업 환경 보호에 필요한 지역)"],["지정 절차","시·도 농업·농촌및식품산업정책심의회 심의 → 농림축산식품부장관 승인(제30조제1항)"],["협의","녹지지역이나 계획관리지역이 포함되면 승인 전에 국토교통부장관과 협의(제30조제3항)"],["변경·해제","시·도지사가 대통령령이 정한 사유가 있으면 변경·해제, 사유가 없어지면 환원(제31조)"]]},{"종류":"흐름","제목":"농업진흥지역 지정 절차","단계":[{"이름":"계획안 작성","설명":"시장·군수·자치구구청장이 관할구역 농지를 조사해 지정계획안과 계획도를 작성(영 제25조제1항)"},{"이름":"계획안 송부","설명":"시장·군수·자치구구청장이 시·도지사에게 송부(영 제25조제3항)"},{"이름":"심의","설명":"시·도지사가 시·도 농업·농촌및식품산업정책심의회의 심의를 받는다(법 제30조제1항)"},{"이름":"협의·승인","설명":"녹지지역·계획관리지역이 포함되면 국토교통부장관과 협의 후 농림축산식품부장관이 승인(법 제30조제1항, 제3항)"},{"이름":"고시·열람","설명":"시·도지사가 지체 없이 고시·통보하고 시장·군수·자치구구청장이 일반인에게 열람하게 한다(법 제30조제2항)"}]}],"함정":"지정 대상 지역의 예외는 특별시의 녹지지역 하나뿐이다. 특별시와 광역시를 한데 묶어 광역시 녹지지역도 빠진다고 외우면 틀린다. 4번은 농업진흥구역의 정의를 농업보호구역에 붙였다."}},{"i":"S3-2-2-공시법-01","r":"S3","g":3,"c":2,"n":1,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지목의 구분 및 설정방법 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["필지마다 하나의 지목을 설정하여야 한다.","1필지가 둘 이상의 용도로 활용되는 경우에는 주된 용도에 따라 지목을 설정하여야 한다.","토지가 일시적 또는 임시적인 용도로 사용될 때에는 그 용도에 따라 지목을 변경하여야 한다.","물을 상시적으로 이용하지 않고 닥나무ㆍ묘목ㆍ관상수 등의 식물을 주로 재배하는 토지의 지목은 “전”으로 한다.","물을 상시적으로 직접 이용하여 벼ㆍ연(蓮)ㆍ미나리ㆍ왕골 등의 식물을 주로 재배하는 토지의 지목은 “답”으로 한다."],"a":[3],"L":"시1-1","o":"기출","x":{"한줄":"일시적·임시적 용도로 쓰이는 토지는 그 용도에 따라 지목을 변경하지 않는다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제59조","원문":"제59조(지목의 설정방법 등)\n① 법 제67조제1항에 따른 지목의 설정은 다음 각 호의 방법에 따른다.\n  1. 필지마다 하나의 지목을 설정할 것\n  2. 1필지가 둘 이상의 용도로 활용되는 경우에는 주된 용도에 따라 지목을 설정할 것\n② 토지가 일시적 또는 임시적인 용도로 사용될 때에는 지목을 변경하지 아니한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제1호·제2호","원문":"제58조(지목의 구분) 법 제67조제1항에 따른 지목의 구분은 다음 각 호의 기준에 따른다.\n  1. 전\n　물을 상시적으로 이용하지 않고 곡물ㆍ원예작물(과수류는 제외한다)ㆍ약초ㆍ뽕나무ㆍ닥나무ㆍ묘목ㆍ관상수 등의 식물을 주로 재배하는 토지와 식용(食用)으로 죽순을 재배하는 토지\n  2. 답\n　물을 상시적으로 직접 이용하여 벼ㆍ연(蓮)ㆍ미나리ㆍ왕골 등의 식물을 주로 재배하는 토지"}],"선지":[{"번호":1,"판정":"옳음","설명":"1필 1지목이 원칙이다(영 제59조제1항제1호)."},{"번호":2,"판정":"옳음","설명":"1필지가 둘 이상의 용도로 쓰이면 주된 용도를 따른다(영 제59조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"일시적·임시적 용도로 쓰일 때에는 지목을 변경하지 않는다(영 제59조제2항)."},{"번호":4,"판정":"옳음","설명":"물을 상시 이용하지 않고 닥나무·묘목·관상수 등을 재배하는 토지가 전이다(영 제58조제1호)."},{"번호":5,"판정":"옳음","설명":"물을 상시 직접 이용해 벼·연·미나리·왕골 등을 재배하는 토지가 답이다(영 제58조제2호)."}],"개념":[{"종류":"표","제목":"지목 설정 규정 모음","머리":["구분","내용","근거"],"행":[["지목 종류","전·답·과수원·목장용지·임야·광천지·염전·대·공장용지·학교용지·주차장·주유소용지·창고용지·도로·철도용지·제방·하천·구거·유지·양어장·수도용지·공원·체육용지·유원지·종교용지·사적지·묘지·잡종지, 28종","법 제67조제1항"],["필지와 지목","필지마다 하나의 지목","영 제59조제1항제1호"],["용도가 둘 이상","주된 용도에 따라 설정","영 제59조제1항제2호"],["일시적·임시적 용도","지목을 변경하지 않음","영 제59조제2항"],["지적도면 부호","대부분 첫 글자, 공장용지 장·하천 천·유원지 원·주차장 차","규칙 제64조"]]},{"종류":"비교","제목":"전과 답","왼쪽":{"이름":"전","항목":["물을 상시 이용하지 않음","곡물·원예작물(과수류 제외)·약초·뽕나무·닥나무·묘목·관상수 재배","식용 죽순 재배지 포함"]},"오른쪽":{"이름":"답","항목":["물을 상시 직접 이용","벼·연·미나리·왕골 등 재배"]}}],"함정":"③은 「변경하여야 한다」로 바뀐 문장이다. 일시적·임시적 용도에서는 지목 변경이 일어나지 않는다. ④의 닥나무·묘목·관상수는 낯선 작물 이름이지만 전의 정의 그대로다."}},{"i":"S3-2-2-공시법-02","r":"S3","g":3,"c":2,"n":2,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지목의 구분에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["물이 고이거나 상시적으로 물을 저장하고 있는 저수지ㆍ소류지(沼溜地)ㆍ호수ㆍ연못 등의 토지와 연(蓮)ㆍ왕골 등이 자생하는 배수가 잘 되지 아니하는 토지는 “유지”로 한다.","과수류를 집단적으로 재배하는 토지에 접속된 저장고 부지와 그 안에 있는 주거용 건축물의 부지는 모두 “과수원”으로 한다.","묘지의 관리를 위한 건축물의 부지는 “묘지”로 한다.","자동차 등의 판매 목적으로 설치된 야외전시장의 부지는 “주차장”으로 한다.","조수ㆍ자연유수ㆍ모래ㆍ바람 등을 막기 위하여 설치된 방조제ㆍ방수제ㆍ방파제 등의 부지는 “구거”로 한다."],"a":[1],"L":"시1-1","o":"변형","x":{"한줄":"저수지·호수·연못 등과 연·왕골 등이 자생하는 배수 불량 토지는 지목이 유지다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제19호","원문":"제58조(지목의 구분) 법 제67조제1항에 따른 지목의 구분은 다음 각 호의 기준에 따른다.\n  19. 유지(溜池)\n　물이 고이거나 상시적으로 물을 저장하고 있는 댐ㆍ저수지ㆍ소류지(沼溜地)ㆍ호수ㆍ연못 등의 토지와 연ㆍ왕골 등이 자생하는 배수가 잘 되지 아니하는 토지"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제3호·제27호","원문":"제58조(지목의 구분) 법 제67조제1항에 따른 지목의 구분은 다음 각 호의 기준에 따른다.\n  3. 과수원\n　사과ㆍ배ㆍ밤ㆍ호두ㆍ귤나무 등 과수류를 집단적으로 재배하는 토지와 이에 접속된 저장고 등 부속시설물의 부지. 다만, 주거용 건축물의 부지는 \"대\"로 한다.\n  27. 묘지\n　사람의 시체나 유골이 매장된 토지, 「도시공원 및 녹지 등에 관한 법률」에 따른 묘지공원으로 결정ㆍ고시된 토지 및 「장사 등에 관한 법률」 제2조제9호에 따른 봉안시설과 이에 접속된 부속시설물의 부지. 다만, 묘지의 관리를 위한 건축물의 부지는 \"대\"로 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제58조제11호·제16호","원문":"제58조(지목의 구분) 법 제67조제1항에 따른 지목의 구분은 다음 각 호의 기준에 따른다.\n  11. 주차장\n　자동차 등의 주차에 필요한 독립적인 시설을 갖춘 부지와 주차전용 건축물 및 이에 접속된 부속시설물의 부지. 다만, 다음 각 목의 어느 하나에 해당하는 시설의 부지는 제외한다.\n    가. 「주차장법」 제2조제1호가목 및 다목에 따른 노상주차장 및 부설주차장(「주차장법」 제19조제4항에 따라 시설물의 부지 인근에 설치된 부설주차장은 제외한다)\n    나. 자동차 등의 판매 목적으로 설치된 물류장 및 야외전시장\n  16. 제방\n　조수ㆍ자연유수(自然流水)ㆍ모래ㆍ바람 등을 막기 위하여 설치된 방조제ㆍ방수제ㆍ방사제ㆍ방파제 등의 부지"}],"선지":[{"번호":1,"판정":"옳음","설명":"영 제58조제19호의 유지 정의 그대로다."},{"번호":2,"판정":"틀림","설명":"과수원 안의 주거용 건축물 부지는 「대」다(영 제58조제3호 단서). 저장고 등 부속시설물 부지만 과수원이다."},{"번호":3,"판정":"틀림","설명":"묘지의 관리를 위한 건축물의 부지는 「대」다(영 제58조제27호 단서)."},{"번호":4,"판정":"틀림","설명":"자동차 등의 판매 목적으로 설치된 물류장·야외전시장은 주차장에서 제외된다(영 제58조제11호 나목)."},{"번호":5,"판정":"틀림","설명":"방조제·방수제·방파제 등의 부지는 「제방」이다(영 제58조제16호). 구거는 용수·배수를 위한 인공 수로·둑과 그 부속시설물의 부지, 자연의 유수가 있거나 있을 것으로 예상되는 소규모 수로부지다(영 제58조제18호)."}],"개념":[{"종류":"표","제목":"주거용·관리용 건축물 부지가 「대」로 바뀌는 지목","머리":["지목","원래 범위","「대」로 하는 부지"],"행":[["과수원","과수류 집단 재배지와 저장고 등 부속시설물 부지","주거용 건축물의 부지"],["목장용지","초지·축사 등 부지와 접속된 부속시설물 부지","주거용 건축물의 부지"],["묘지","매장지·묘지공원·봉안시설과 접속 부속시설물 부지","묘지의 관리를 위한 건축물의 부지"],["도로(제외 사유)","보행·차량운행 설비를 갖춘 토지, 고속도로 휴게소 부지 등","아파트·공장 등 단일 용도 단지 안의 통로는 도로에서 제외"]]},{"종류":"비교","제목":"유지와 답·구거","왼쪽":{"이름":"유지","항목":["물이 고이거나 상시 물을 저장하는 댐·저수지·소류지·호수·연못","연·왕골 등이 자생하는 배수 불량 토지"]},"오른쪽":{"이름":"답·구거","항목":["답: 물을 상시 직접 이용해 벼·연·미나리·왕골 등을 재배","구거: 용수·배수를 위한 인공 수로, 소규모 자연 수로부지"]}}],"함정":"연·왕골은 답의 정의에도 유지의 정의에도 나온다. 답은 물을 직접 이용해 재배하는 땅이고, 유지는 자생하는 배수 불량 토지다. ②③은 주거용·관리용 건축물 부지가 「대」라는 점이 빠져 있고, ⑤는 제방과 구거를 바꿔 놓았다."}},{"i":"S3-2-2-공시법-03","r":"S3","g":3,"c":2,"n":3,"s":"공시법","q":"경계점좌표등록부에 등록하는 지역에서 1필지의 면적측정을 위해 계산한 값이 468.35m² 인 경우 토지대장에 등록할 면적으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["468.4m²","468.3m²","468.35m²","468m²","469m²"],"a":[1],"L":"시1-2","o":"변형","x":{"한줄":"경계점좌표등록부 지역은 제곱미터 이하 한 자리까지 등록하고, 끝수가 정확히 0.05이면 구하려는 끝자리 숫자가 홀수일 때 올린다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제60조제1항","원문":"제60조(면적의 결정 및 측량계산의 끝수처리)\n① 면적의 결정은 다음 각 호의 방법에 따른다.\n  1. 토지의 면적에 1제곱미터 미만의 끝수가 있는 경우 0.5제곱미터 미만일 때에는 버리고 0.5제곱미터를 초과하는 때에는 올리며, 0.5제곱미터일 때에는 구하려는 끝자리의 숫자가 0 또는 짝수이면 버리고 홀수이면 올린다. 다만, 1필지의 면적이 1제곱미터 미만일 때에는 1제곱미터로 한다.\n  2. 지적도의 축척이 600분의 1인 지역과 경계점좌표등록부에 등록하는 지역의 토지 면적은 제1호에도 불구하고 제곱미터 이하 한 자리 단위로 하되, 0.1제곱미터 미만의 끝수가 있는 경우 0.05제곱미터 미만일 때에는 버리고 0.05제곱미터를 초과할 때에는 올리며, 0.05제곱미터일 때에는 구하려는 끝자리의 숫자가 0 또는 짝수이면 버리고 홀수이면 올린다. 다만, 1필지의 면적이 0.1제곱미터 미만일 때에는 0.1제곱미터로 한다."}],"선지":[{"번호":1,"판정":"-","설명":"끝수 0.05, 끝자리 3은 홀수여서 올려 468.4m2다."},{"번호":2,"판정":"-","설명":"끝수 0.05를 무조건 버린 값이다. 끝자리가 홀수(3)이면 올린다."},{"번호":3,"판정":"-","설명":"끝수 처리를 하지 않은 계산값이다. 한 자리 단위로 등록한다."},{"번호":4,"판정":"-","설명":"1m2 미만 끝수를 처리하는 일반 지역의 방식이다(영 제60조제1항제1호). 이 지역은 0.1m2 단위로 정한다."},{"번호":5,"판정":"-","설명":"0.35를 올려 정수로 만든 값이다. 일반 지역 방식으로도 0.5 미만이면 버리므로 맞지 않는다."}],"개념":[{"종류":"표","제목":"면적 결정 끝수처리","머리":["구분","적용 지역","등록 단위","끝수 처리"],"행":[["일반 지역","그 밖의 지역","1m2","0.5 미만 버림, 0.5 초과 올림, 0.5이면 끝자리 0·짝수 버림·홀수 올림"],["좌표 지역","지적도 축척 600분의 1 지역, 경계점좌표등록부 등록 지역","0.1m2","0.05 미만 버림, 0.05 초과 올림, 0.05이면 끝자리 0·짝수 버림·홀수 올림"],["1필지가 최소 단위보다 작을 때(일반)","1필지 면적 1m2 미만","1m2","1m2로 한다"],["1필지가 최소 단위보다 작을 때(좌표)","1필지 면적 0.1m2 미만","0.1m2","0.1m2로 한다"]]},{"종류":"계산","제목":"468.35m2 처리","단계":[{"설명":"적용 규정 판단: 경계점좌표등록부 지역","식":"영 제60조제1항제2호","값":"0.1m2 단위"},{"설명":"끝수 확인","식":"468.35 = 468.3 + 0.05","값":"끝수 0.05"},{"설명":"끝수가 0.05이면 끝자리 숫자로 판단","식":"끝자리 3 = 홀수","값":"올림"},{"설명":"결과","식":"468.3 + 0.1","값":"468.4m2"}]}],"함정":"0.05를 보면 0.5 처리처럼 버리거나 반올림만 떠올린다. 0.05는 반올림이 아니라 끝자리 홀짝으로 정한다. 끝자리 3이 홀수여서 올림이다. 정수로 처리한 ④⑤는 일반 지역 방식을 쓴 오답이다."}},{"i":"S3-2-2-공시법-04","r":"S3","g":3,"c":2,"n":4,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적공부와 등록사항의 연결이 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["토지대장 - 지목, 면적, 경계","경계점좌표등록부 - 지번, 토지의 고유번호, 지적도면의 번호","공유지연명부 - 지번, 지목, 소유권 지분","대지권등록부 - 좌표, 건물의 명칭, 대지권 비율","지적도 - 삼각점 및 지적기준점의 위치, 도곽선(圖廓線)과 그 수치, 부호 및 부호도"],"a":[2],"L":"시1-3","o":"기출","x":{"한줄":"경계점좌표등록부에는 토지의 소재, 지번, 좌표와 함께 토지의 고유번호, 지적도면의 번호, 장번호, 부호 및 부호도를 등록한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제73조","원문":"제73조(경계점좌표등록부의 등록사항) 지적소관청은 제86조에 따른 도시개발사업 등에 따라 새로이 지적공부에 등록하는 토지에 대하여는 다음 각 호의 사항을 등록한 경계점좌표등록부를 작성하고 갖춰 두어야 한다.\n  1. 토지의 소재\n  2. 지번\n  3. 좌표\n  4. 그 밖에 국토교통부령으로 정하는 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제71조제3항","원문":"제71조(경계점좌표등록부의 등록사항 등)\n③ 법 제73조제4호에서 \"그 밖에 국토교통부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다.\n  1. 토지의 고유번호\n  2. 지적도면의 번호\n  3. 필지별 경계점좌표등록부의 장번호\n  4. 부호 및 부호도"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제71조제1항","원문":"제71조(토지대장 등의 등록사항)\n① 토지대장과 임야대장에는 다음 각 호의 사항을 등록하여야 한다.\n  1. 토지의 소재\n  2. 지번\n  3. 지목\n  4. 면적\n  5. 소유자의 성명 또는 명칭, 주소 및 주민등록번호(국가, 지방자치단체, 법인, 법인 아닌 사단이나 재단 및 외국인의 경우에는 「부동산등기법」 제49조에 따라 부여된 등록번호를 말한다. 이하 같다)\n  1. 토지의 소재\n  2. 지번\n  3. 소유권 지분\n  4. 소유자의 성명 또는 명칭, 주소 및 주민등록번호\n  5. 그 밖에 국토교통부령으로 정하는 사항\n  1. 토지의 소재\n  2. 지번\n  3. 대지권 비율\n  4. 소유자의 성명 또는 명칭, 주소 및 주민등록번호\n  5. 그 밖에 국토교통부령으로 정하는 사항"}],"선지":[{"번호":1,"판정":"틀림","설명":"토지대장에는 토지의 소재·지번·지목·면적·소유자 등을 등록하고 경계는 등록하지 않는다(법 제71조제1항). 경계는 지적도·임야도에 등록한다(법 제72조)."},{"번호":2,"판정":"옳음","설명":"지번은 법 제73조제2호, 고유번호와 지적도면의 번호는 규칙 제71조제3항제1호·제2호다."},{"번호":3,"판정":"틀림","설명":"공유지연명부에는 지목이 없다. 토지의 소재·지번·소유권 지분·소유자 정보·고유번호 등을 등록한다(법 제71조제2항, 규칙 제68조제3항)."},{"번호":4,"판정":"틀림","설명":"대지권등록부에 좌표는 없다. 토지의 소재·지번·대지권 비율·소유자 정보·건물의 명칭 등을 등록한다(법 제71조제3항, 규칙 제68조제4항)."},{"번호":5,"판정":"틀림","설명":"부호 및 부호도는 경계점좌표등록부 등록사항이다(규칙 제71조제3항제4호). 지적도에는 삼각점 및 지적기준점의 위치, 도곽선과 그 수치 등을 등록한다(규칙 제69조제2항)."}],"개념":[{"종류":"표","제목":"지적공부별 등록사항","머리":["지적공부","법정 등록사항","규칙상 추가 등록사항"],"행":[["토지대장·임야대장","토지의 소재, 지번, 지목, 면적, 소유자 성명·주소·주민등록번호","고유번호, 도면 번호·장번호·축척, 토지의 이동사유, 소유자 변경일과 원인, 토지등급, 개별공시지가와 기준일"],["공유지연명부","토지의 소재, 지번, 소유권 지분, 소유자 성명·주소·주민등록번호","고유번호, 장번호, 소유자 변경일과 원인"],["대지권등록부","토지의 소재, 지번, 대지권 비율, 소유자 성명·주소·주민등록번호","고유번호, 전유부분 건물표시, 건물의 명칭, 장번호, 소유자 변경일과 원인, 소유권 지분"],["지적도·임야도","토지의 소재, 지번, 지목, 경계","색인도, 제명과 축척, 도곽선과 수치, 삼각점·지적기준점 위치, 건축물·구조물 위치, 좌표 지역의 경계점 간 거리"],["경계점좌표등록부","토지의 소재, 지번, 좌표","고유번호, 지적도면의 번호, 장번호, 부호 및 부호도"]]}],"함정":"경계는 지적도·임야도에만 있고 토지대장에는 없다. 지목은 공유지연명부에 없다. 좌표는 경계점좌표등록부에만 있다. 부호도를 지적도 등록사항으로 옮겨 적은 ⑤가 가장 많이 걸린다."}},{"i":"S3-2-2-공시법-05","r":"S3","g":3,"c":2,"n":5,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 경계점좌표등록부를 갖춰 두는 지역에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["경계점좌표등록부를 갖춰 두는 지역의 지적도에는 도면의 제명 끝에 “(좌표)”라고 표시하고, 도곽선의 오른쪽 아래 끝에 “이 도면에 의하여 측량을 할 수 없음”이라고 적어야 한다.","경계점좌표등록부를 갖춰 두는 토지는 지적공부의 복구 또는 등록사항 정정으로 경계점을 좌표로 등록한 지역의 토지로 한다.","경계점좌표등록부에는 토지의 소재, 지번, 좌표와 함께 토지의 지목과 면적을 등록한다.","경계점좌표등록부를 갖춰 두는 지역의 지적도에는 좌표에 의하여 계산된 경계점 간의 거리를 등록할 수 없다.","경계점좌표등록부를 갖춰 두는 지역의 토지 면적은 1제곱미터 미만의 끝수를 처리하여 정수 단위로 등록한다."],"a":[1],"L":"시1-3","o":"변형","x":{"한줄":"경계점좌표등록부 지역의 지적도에는 제명 끝에 「(좌표)」를 표시하고 도곽선 오른쪽 아래 끝에 「이 도면에 의하여 측량을 할 수 없음」을 적는다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제69조제3항","원문":"제69조(지적도면 등의 등록사항 등)\n③ 경계점좌표등록부를 갖춰 두는 지역의 지적도에는 해당 도면의 제명 끝에 \"(좌표)\"라고 표시하고, 도곽선의 오른쪽 아래 끝에 \"이 도면에 의하여 측량을 할 수 없음\"이라고 적어야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제71조제2항","원문":"제71조(경계점좌표등록부의 등록사항 등)\n② 법 제73조에 따라 경계점좌표등록부를 갖춰 두는 토지는 지적확정측량 또는 축척변경을 위한 측량을 실시하여 경계점을 좌표로 등록한 지역의 토지로 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"규칙 제69조제3항 그대로다."},{"번호":2,"판정":"틀림","설명":"지적확정측량 또는 축척변경을 위한 측량을 실시해 경계점을 좌표로 등록한 지역의 토지다(규칙 제71조제2항)."},{"번호":3,"판정":"틀림","설명":"지목과 면적은 경계점좌표등록부 등록사항이 아니다. 토지의 소재·지번·좌표, 고유번호, 지적도면의 번호, 장번호, 부호 및 부호도를 등록한다(법 제73조, 규칙 제71조제3항)."},{"번호":4,"판정":"틀림","설명":"이 지역의 지적도에는 좌표에 의하여 계산된 경계점 간의 거리를 등록한다(규칙 제69조제2항제4호)."},{"번호":5,"판정":"틀림","설명":"경계점좌표등록부 등록 지역의 면적은 제곱미터 이하 한 자리 단위로 정한다(영 제60조제1항제2호)."}],"개념":[{"종류":"표","제목":"경계점좌표등록부 지역 정리","머리":["항목","내용","근거"],"행":[["갖춰 두는 토지","지적확정측량 또는 축척변경을 위한 측량으로 경계점을 좌표로 등록한 지역","규칙 제71조제2항"],["등록사항","토지의 소재, 지번, 좌표, 고유번호, 지적도면의 번호, 장번호, 부호 및 부호도","법 제73조, 규칙 제71조제3항"],["지적도 표시","제명 끝 「(좌표)」, 도곽선 오른쪽 아래 끝 「이 도면에 의하여 측량을 할 수 없음」","규칙 제69조제3항"],["지적도 등록사항","좌표로 계산된 경계점 간의 거리를 등록","규칙 제69조제2항제4호"],["면적 단위","제곱미터 이하 한 자리(0.1m2)","영 제60조제1항제2호"]]}],"함정":"경계점좌표등록부 지역은 도면으로 측량할 수 없다는 문구를 도면에 넣는다. ④는 경계점 간 거리를 등록하지 않는다고 뒤집은 문장이다. ⑤는 일반 지역의 면적 단위를 끌어온 오답이다."}},{"i":"S3-2-2-공시법-06","r":"S3","g":3,"c":2,"n":6,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적도와 임야도의 축척 중에서 공통된 것으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["1/1200, 1/2400","1/1200, 1/3000","1/2400, 1/3000","1/2400, 1/6000","1/3000, 1/6000"],"a":[5],"L":"시1-3","o":"기출","x":{"한줄":"지적도와 임야도에 모두 있는 축척은 1/3000과 1/6000이다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제69조제6항","원문":"제69조(지적도면 등의 등록사항 등)\n  1. 지적도면의 색인도(인접도면의 연결 순서를 표시하기 위하여 기재한 도표와 번호를 말한다)\n  2. 지적도면의 제명 및 축척\n⑥ 지적도면의 축척은 다음 각 호의 구분에 따른다.\n  1. 지적도: 1/500,  1/600, 1/1000, 1/1200, 1/2400, 1/3000, 1/6000\n  2. 임야도: 1/3000, 1/6000"}],"선지":[{"번호":1,"판정":"-","설명":"1/1200, 1/2400은 지적도에만 있다."},{"번호":2,"판정":"-","설명":"1/1200은 지적도에만 있다."},{"번호":3,"판정":"-","설명":"1/2400은 지적도에만 있다."},{"번호":4,"판정":"-","설명":"1/2400은 지적도에만 있다."},{"번호":5,"판정":"-","설명":"두 도면에 모두 있는 축척이다."}],"개념":[{"종류":"표","제목":"지적도면 축척","머리":["도면","축척","개수"],"행":[["지적도","1/500, 1/600, 1/1000, 1/1200, 1/2400, 1/3000, 1/6000","7종"],["임야도","1/3000, 1/6000","2종"],["공통","1/3000, 1/6000","2종"],["지적도에만","1/500, 1/600, 1/1000, 1/1200, 1/2400","5종"]]}],"함정":"임야도의 축척은 1/3000, 1/6000 두 개뿐이다. 1/1200, 1/2400을 임야도에도 있는 축척으로 알면 ①②③④에 걸린다. 1/600은 지적도 축척이고 이 지역은 면적을 0.1m2 단위로 정한다."}},{"i":"S3-2-2-공시법-07","r":"S3","g":3,"c":2,"n":7,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적소관청은 토지의 이동 등으로 토지의 표시 변경에 관한 등기를 할 필요가 있는 경우에는 지체 없이 관할 등기관서에 그 등기를 촉탁하여야 한다. 이 경우 등기촉탁의 대상이 아닌 것은?","b":null,"bs":"없음","img":[],"ch":["지목변경","지번변경","신규등록","축척변경","합병"],"a":[3],"L":"시1-4","o":"기출","x":{"한줄":"신규등록은 지적소관청의 등기촉탁 대상에서 제외된다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제89조제1항","원문":"제89조(등기촉탁)\n① 지적소관청은 제64조제2항(신규등록은 제외한다), 제66조제2항, 제82조, 제83조제2항, 제84조제2항 또는 제85조제2항에 따른 사유로 토지의 표시 변경에 관한 등기를 할 필요가 있는 경우에는 지체 없이 관할 등기관서에 그 등기를 촉탁하여야 한다. 이 경우 등기촉탁은 국가가 국가를 위하여 하는 등기로 본다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지목변경은 토지의 이동(법 제64조제2항)이어서 촉탁 대상이다."},{"번호":2,"판정":"옳음","설명":"지번변경(법 제66조제2항)은 촉탁 대상이다."},{"번호":3,"판정":"틀림","설명":"신규등록은 법 제89조제1항 괄호에서 제외된다. 신규등록 토지는 미등기 상태여서 토지소유자가 소유권보존등기를 신청한다."},{"번호":4,"판정":"옳음","설명":"축척변경(법 제83조제2항)은 촉탁 대상이다."},{"번호":5,"판정":"옳음","설명":"합병은 토지의 이동(법 제64조제2항)이어서 촉탁 대상이다."}],"개념":[{"종류":"표","제목":"지적소관청의 등기촉탁 사유","머리":["사유","근거 조문","촉탁 여부"],"행":[["토지의 이동(분할·합병·지목변경 등)","법 제64조제2항","촉탁"],["신규등록","법 제64조제2항","촉탁 제외"],["지번변경","법 제66조제2항","촉탁"],["바다로 된 토지의 등록말소","법 제82조","촉탁"],["축척변경","법 제83조제2항","촉탁"],["등록사항 정정(직권)","법 제84조제2항","촉탁"],["행정구역 개편으로 새 지번 부여","법 제85조제2항","촉탁"]]},{"종류":"흐름","제목":"신규등록 토지의 등기","단계":[{"이름":"토지소유자의 신규등록 신청","설명":"공유수면 매립 등으로 새로 생긴 토지를 지적공부에 등록한다."},{"이름":"지적소관청의 지적공부 등록","설명":"토지대장 등에 최초 소유자로 등록한다."},{"이름":"촉탁 없음","설명":"신규등록은 법 제89조제1항 촉탁 대상에서 제외된다."},{"이름":"소유권보존등기 신청","설명":"토지대장에 최초의 소유자로 등록된 자나 그 상속인 등이 신청한다(부동산등기법 제65조제1호)."}]}],"함정":"분할·합병·지목변경 같은 일반 토지이동은 모두 촉탁 대상이다. 같은 토지이동 중에서도 신규등록만 빠진다는 점이 쟁점이다. 미등기 토지에는 바꿀 표시등기가 없다."}},{"i":"S3-2-2-공시법-08","r":"S3","g":3,"c":2,"n":8,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 합병 신청을 할 수 없는 경우에 관한 내용으로 틀린 것은? (단, 다른 조건은 고려하지 아니함)","b":null,"bs":"없음","img":[],"ch":["합병하려는 토지의 지목이 서로 다른 경우","합병하려는 토지의 소유자별 공유지분이 다른 경우","합병하려는 토지의 지번부여지역이 서로 다른 경우","합병하려는 토지의 소유자에 대한 소유권이전등기 연월일이 서로 다른 경우","합병하려는 토지의 지적도 축척이 서로 다른 경우"],"a":[4],"L":"시1-4","o":"기출","x":{"한줄":"소유권이전등기 연월일이 서로 달라도 합병 신청은 막히지 않는다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제80조제3항","원문":"제80조(합병 신청)\n③ 다음 각 호의 어느 하나에 해당하는 경우에는 합병 신청을 할 수 없다.\n  1. 합병하려는 토지의 지번부여지역, 지목 또는 소유자가 서로 다른 경우\n  2. 합병하려는 토지에 다음 각 목의 등기 외의 등기가 있는 경우\n    가. 소유권ㆍ지상권ㆍ전세권 또는 임차권의 등기\n    나. 승역지(承役地)에 대한 지역권의 등기\n    다. 합병하려는 토지 전부에 대한 등기원인(登記原因) 및 그 연월일과 접수번호가 같은 저당권의 등기\n    라. 합병하려는 토지 전부에 대한 「부동산등기법」 제81조제1항 각 호의 등기사항이 동일한 신탁등기\n  3. 그 밖에 합병하려는 토지의 지적도 및 임야도의 축척이 서로 다른 경우 등 대통령령으로 정하는 경우"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제66조제3항","원문":"제66조(합병 신청)\n③ 법 제80조제3항제3호에서 \"합병하려는 토지의 지적도 및 임야도의 축척이 서로 다른 경우 등 대통령령으로 정하는 경우\"란 다음 각 호의 경우를 말한다.\n  1. 합병하려는 토지의 지적도 및 임야도의 축척이 서로 다른 경우\n  2. 합병하려는 각 필지가 서로 연접하지 않은 경우\n  3. 합병하려는 토지가 등기된 토지와 등기되지 아니한 토지인 경우\n  4. 합병하려는 각 필지의 지목은 같으나 일부 토지의 용도가 다르게 되어 법 제79조제2항에 따른 분할대상 토지인 경우. 다만, 합병 신청과 동시에 토지의 용도에 따라 분할 신청을 하는 경우는 제외한다.\n  5. 합병하려는 토지의 소유자별 공유지분이 다른 경우\n  6. 합병하려는 토지가 구획정리, 경지정리 또는 축척변경을 시행하고 있는 지역의 토지와 그 지역 밖의 토지인 경우\n  7. 합병하려는 토지 소유자의 주소가 서로 다른 경우. 다만, 제1항에 따른 신청을 접수받은 지적소관청이 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 다음 각 목의 사항을 확인(신청인이 주민등록표 초본 확인에 동의하지 않는 경우에는 해당 자료를 첨부하도록 하여 확인)한 결과 토지 소유자가 동일인임을 확인할 수 있는 경우는 제외한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"지번부여지역·지목·소유자가 서로 다르면 합병할 수 없다(법 제80조제3항제1호)."},{"번호":2,"판정":"옳음","설명":"소유자별 공유지분이 다르면 합병할 수 없다(영 제66조제3항제5호)."},{"번호":3,"판정":"옳음","설명":"지번부여지역이 다르면 합병할 수 없다(법 제80조제3항제1호)."},{"번호":4,"판정":"틀림","설명":"소유권이전등기 연월일의 차이는 합병 제한 사유로 규정되어 있지 않다. 소유권 등기가 있으면 합병은 가능하다(법 제80조제3항제2호 가목). 등기원인·연월일·접수번호가 같아야 하는 것은 저당권 등기다(다목)."},{"번호":5,"판정":"옳음","설명":"지적도 및 임야도의 축척이 서로 다르면 합병할 수 없다(영 제66조제3항제1호)."}],"개념":[{"종류":"표","제목":"합병 신청을 할 수 없는 경우","머리":["구분","내용","근거"],"행":[["법 제80조제3항제1호","지번부여지역, 지목 또는 소유자가 서로 다른 경우","법"],["법 제80조제3항제2호","소유권·지상권·전세권·임차권 등기, 승역지 지역권 등기, 전부에 원인·연월일·접수번호가 같은 저당권 등기, 신탁등기사항이 동일한 신탁등기 외의 등기가 있는 경우","법"],["영 제66조제3항","축척이 다른 경우, 연접하지 않은 경우, 등기·미등기 혼합, 분할대상 토지, 공유지분이 다른 경우, 구획정리·경지정리·축척변경 시행지역과 지역 밖 토지, 소유자 주소가 다른 경우","영"]]},{"종류":"비교","제목":"합병 의무와 합병 신청","왼쪽":{"이름":"합병 신청 의무","항목":["공동주택 부지, 도로, 제방, 하천, 구거, 유지 등 합병하여야 할 토지","사유가 발생한 날부터 60일 이내에 신청(법 제80조제2항)"]},"오른쪽":{"이름":"일반 합병","항목":["토지소유자가 임의로 신청(법 제80조제1항)","합병 제한 사유가 있으면 신청 불가(법 제80조제3항)"]}}],"함정":"소유자가 서로 다르면 합병할 수 없지만, 소유권이전등기를 한 날이 다른 것은 별개 문제다. 이전등기 연월일은 저당권 등기에서만 같아야 한다. ②는 소유자가 같아도 지분이 다르면 안 된다는 규정이다."}},{"i":"S3-2-2-공시법-09","r":"S3","g":3,"c":2,"n":9,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 토지소유자의 정리 등에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["등기부에 적혀 있는 토지의 표시가 지적공부와 일치하지 아니하면 토지소유자를 정리할 수 없으며, 이 경우 그 사실을 관할 등기관서에 통지하여야 한다.","지적공부에 등록된 토지소유자의 변경사항은 등기필증, 등기완료통지서, 등기사항증명서 또는 등기관서에서 제공한 등기전산정보자료에 따라 정리한다.","신규등록하는 토지의 소유자는 지적소관청이 직접 조사하여 등록한다.","지적소관청은 지적공부와 부동산등기부가 일치하지 아니하는 사항을 발견하면 반드시 토지소유자나 이해관계인에게 신청을 하도록 요구하여야 하며, 직권으로 지적공부를 정리할 수 없다.","지적소관청 소속 공무원이 지적공부와 부동산등기부의 부합 여부를 확인하기 위하여 등기사항증명서의 발급을 신청하는 경우 그 수수료는 무료로 한다."],"a":[4],"L":"시1-4","o":"변형","x":{"한줄":"지적소관청은 불일치 사항을 발견하면 등기사항증명서 등에 따라 지적공부를 직권으로 정리하거나 신청을 요구할 수 있다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제88조","원문":"제88조(토지소유자의 정리)\n① 지적공부에 등록된 토지소유자의 변경사항은 등기관서에서 등기한 것을 증명하는 등기필증, 등기완료통지서, 등기사항증명서 또는 등기관서에서 제공한 등기전산정보자료에 따라 정리한다. 다만, 신규등록하는 토지의 소유자는 지적소관청이 직접 조사하여 등록한다.\n③ 등기부에 적혀 있는 토지의 표시가 지적공부와 일치하지 아니하면 제1항에 따라 토지소유자를 정리할 수 없다. 이 경우 토지의 표시와 지적공부가 일치하지 아니하다는 사실을 관할 등기관서에 통지하여야 한다.\n④ 지적소관청은 필요하다고 인정하는 경우에는 관할 등기관서의 등기부를 열람하여 지적공부와 부동산등기부가 일치하는지 여부를 조사ㆍ확인하여야 하며, 일치하지 아니하는 사항을 발견하면 등기사항증명서 또는 등기관서에서 제공한 등기전산정보자료에 따라 지적공부를 직권으로 정리하거나, 토지소유자나 그 밖의 이해관계인에게 그 지적공부와 부동산등기부가 일치하게 하는 데에 필요한 신청 등을 하도록 요구할 수 있다.\n⑤ 지적소관청 소속 공무원이 지적공부와 부동산등기부의 부합 여부를 확인하기 위하여 등기부를 열람하거나, 등기사항증명서의 발급을 신청하거나, 등기전산정보자료의 제공을 요청하는 경우 그 수수료는 무료로 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"법 제88조제3항 그대로다."},{"번호":2,"판정":"옳음","설명":"변경사항은 등기서류와 등기전산정보자료로 정리한다(법 제88조제1항 본문)."},{"번호":3,"판정":"옳음","설명":"신규등록하는 토지의 소유자는 지적소관청이 직접 조사해 등록한다(법 제88조제1항 단서)."},{"번호":4,"판정":"틀림","설명":"직권으로 정리하거나 신청 등을 요구하는 것 중 선택할 수 있다(법 제88조제4항). 직권 정리가 막혀 있지 않다."},{"번호":5,"판정":"옳음","설명":"확인을 위한 열람·발급 신청·자료 요청의 수수료는 무료다(법 제88조제5항)."}],"개념":[{"종류":"표","제목":"토지소유자 정리 규정","머리":["항목","내용","근거"],"행":[["변경사항","등기필증·등기완료통지서·등기사항증명서·등기전산정보자료에 따라 정리","법 제88조제1항 본문"],["신규등록","지적소관청이 직접 조사해 등록","법 제88조제1항 단서"],["소유자 없는 부동산","총괄청·중앙관서의 장이 등록 신청하면 지적공부에 소유자가 없는 경우에만 등록","법 제88조제2항"],["표시 불일치","토지소유자를 정리할 수 없고 관할 등기관서에 통지","법 제88조제3항"],["일치 여부 조사","필요하면 등기부를 열람해 조사·확인","법 제88조제4항"],["수수료","공무원의 열람·발급 신청·자료 요청은 무료","법 제88조제5항"]]},{"종류":"흐름","제목":"지적공부와 등기부가 일치하지 않을 때","단계":[{"이름":"등기부 열람","설명":"지적소관청이 필요하다고 인정하면 관할 등기관서의 등기부를 열람해 일치 여부를 조사·확인한다."},{"이름":"불일치 사항 발견","설명":"등기사항증명서 또는 등기전산정보자료로 확인한다."},{"이름":"처리 방법 선택","설명":"지적공부를 직권으로 정리하거나, 토지소유자·이해관계인에게 일치시키는 데 필요한 신청 등을 하도록 요구한다."}]}],"함정":"「반드시 요구하여야 하며 직권 정리할 수 없다」처럼 한 방향만 인정하는 표현은 틀린 선지의 전형이다. 법은 직권 정리와 신청 요구 두 가지를 모두 인정한다. ①은 토지의 표시가 불일치하면 정리 자체가 막힌다는 별개 규정이다."}},{"i":"S3-2-2-공시법-10","r":"S3","g":3,"c":2,"n":10,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 축척변경에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["도시개발사업 등의 시행지역에 있는 토지로서 그 사업시행에서 제외된 토지의 축척변경을 하는 경우 축척변경위원회의 심의 및 시ㆍ도지사 또는 대도시 시장의 승인을 받아야 한다.","지적소관청은 시ㆍ도지사 또는 대도시 시장으로부터 축척변경 승인을 받았을 때에는 지체 없이 축척변경의 목적, 시행지역 및 시행기간, 축척변경의 시행에 관한 세부계획, 축척변경의 시행에 따른 청산금액의 내용, 축척변경의 시행에 따른 토지소유자 등의 협조에 관한 사항을 15일 이상 공고하여야 한다.","지적소관청은 축척변경에 관한 측량을 한 결과 측량 전에 비하여 면적의 증감이 있는 경우에는 그 증감면적에 대하여 청산을 하여야 한다. 다만, 토지소유자 3분의 2이상이 청산하지 아니하기로 합의하여 서면으로 제출한 경우에는 그러하지 아니하다.","지적소관청은 청산금을 내야 하는 자가 납부고지를 받은 날부터 1개월 이내에 청산금에 관한 이의신청을 하지 아니하고, 고지를 받은 날부터 3개월 이내에 지적소관청에 청산금을 내지 아니하면 ｢지방행정제재ㆍ부과금의 징수 등에 관한 법률｣에 따라 징수할 수 있다.","청산금의 납부 및 지급이 완료되었을 때에는 지적소관청은 지체 없이 축척변경의 확정공고를 하여야 하며, 확정공고 사항에는 토지의 소재 및 지역명, 축척변경 지번별조서, 청산금 조서, 지적도의 축척이 포함되어야 한다."],"a":[5],"L":"시1-4","o":"기출","x":{"한줄":"청산금의 납부·지급이 끝나면 확정공고를 하고, 확정공고에는 토지의 소재 및 지역명, 축척변경 지번별 조서, 청산금 조서, 지적도의 축척이 들어간다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제78조제1항","원문":"제78조(축척변경의 확정공고)\n① 청산금의 납부 및 지급이 완료되었을 때에는 지적소관청은 지체 없이 축척변경의 확정공고를 하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제92조제1항","원문":"제92조(축척변경의 확정공고)\n① 영 제78조제1항에 따른 축척변경의 확정공고에는 다음 각 호의 사항이 포함되어야 한다.\n  1. 토지의 소재 및 지역명\n  2. 영 제73조에 따른 축척변경 지번별 조서\n  3. 영 제75조제4항에 따른 청산금 조서\n  4. 지적도의 축척\n  1. 토지대장은 제1항제2호에 따라 확정공고된 축척변경 지번별 조서에 따를 것\n  2. 지적도는 확정측량 결과도 또는 경계점좌표에 따를 것"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제83조제3항","원문":"제83조(축척변경)\n  1. 잦은 토지의 이동으로 1필지의 규모가 작아서 소축척으로는 지적측량성과의 결정이나 토지의 이동에 따른 정리를 하기가 곤란한 경우\n  2. 하나의 지번부여지역에 서로 다른 축척의 지적도가 있는 경우\n③ 지적소관청은 제2항에 따라 축척변경을 하려면 축척변경 시행지역의 토지소유자 3분의 2 이상의 동의를 받아 제1항에 따른 축척변경위원회의 의결을 거친 후 시ㆍ도지사 또는 대도시 시장의 승인을 받아야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 축척변경위원회의 의결 및 시ㆍ도지사 또는 대도시 시장의 승인 없이 축척변경을 할 수 있다.\n  1. 합병하려는 토지가 축척이 다른 지적도에 각각 등록되어 있어 축척변경을 하는 경우\n  2. 제86조에 따른 도시개발사업 등의 시행지역에 있는 토지로서 그 사업 시행에서 제외된 토지의 축척변경을 하는 경우"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제71조제1항","원문":"제71조(축척변경 시행공고 등)\n① 지적소관청은 법 제83조제3항에 따라 시ㆍ도지사 또는 대도시 시장으로부터 축척변경 승인을 받았을 때에는 지체 없이 다음 각 호의 사항을 20일 이상 공고하여야 한다.\n  1. 축척변경의 목적, 시행지역 및 시행기간\n  2. 축척변경의 시행에 관한 세부계획\n  3. 축척변경의 시행에 따른 청산방법\n  4. 축척변경의 시행에 따른 토지소유자 등의 협조에 관한 사항"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제75조제1항","원문":"제75조(청산금의 산정)\n① 지적소관청은 축척변경에 관한 측량을 한 결과 측량 전에 비하여 면적의 증감이 있는 경우에는 그 증감면적에 대하여 청산을 하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그러하지 아니하다.\n  1. 필지별 증감면적이 제19조제1항제2호가목에 따른 허용범위 이내인 경우. 다만, 축척변경위원회의 의결이 있는 경우는 제외한다.\n  2. 토지소유자 전원이 청산하지 아니하기로 합의하여 서면으로 제출한 경우"},{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행령","조문":"제76조제2항·제5항","원문":"제76조(청산금의 납부고지 등)\n② 제1항에 따른 납부고지를 받은 자는 그 고지를 받은 날부터 6개월 이내에 청산금을 지적소관청에 내야 한다.\n⑤ 지적소관청은 청산금을 내야 하는 자가 제77조제1항에 따른 기간 내에 청산금에 관한 이의신청을 하지 아니하고 제2항에 따른 기간 내에 청산금을 내지 아니하면 「지방행정제재ㆍ부과금의 징수 등에 관한 법률」에 따라 징수할 수 있다."}],"선지":[{"번호":1,"판정":"틀림","설명":"사업시행에서 제외된 토지의 축척변경은 위원회 의결과 시·도지사 또는 대도시 시장의 승인 없이 할 수 있다(법 제83조제3항 단서 제2호)."},{"번호":2,"판정":"틀림","설명":"시행공고 기간은 20일 이상이고, 공고사항은 「청산금액」이 아니라 「청산방법」이다(영 제71조제1항)."},{"번호":3,"판정":"틀림","설명":"청산하지 않을 수 있는 경우는 토지소유자 전원이 합의해 서면으로 제출한 때다(영 제75조제1항제2호). 3분의 2가 아니다."},{"번호":4,"판정":"틀림","설명":"청산금 납부기간은 납부고지를 받은 날부터 6개월이다(영 제76조제2항). 이의신청 기간 1개월은 맞다(영 제77조제1항)."},{"번호":5,"판정":"옳음","설명":"영 제78조제1항, 규칙 제92조제1항 그대로다."}],"개념":[{"종류":"흐름","제목":"축척변경 절차","단계":[{"이름":"신청 또는 직권","설명":"토지소유자의 신청 또는 지적소관청의 직권으로 일정한 지역을 정한다."},{"이름":"동의·의결·승인","설명":"시행지역 토지소유자 3분의 2 이상 동의 → 축척변경위원회 의결 → 시·도지사 또는 대도시 시장 승인."},{"이름":"시행공고","설명":"승인 후 지체 없이 20일 이상 공고한다."},{"이름":"경계점표지 설치","설명":"토지소유자 또는 점유자가 시행공고일부터 30일 이내에 설치한다."},{"이름":"측량과 지번별 조서","설명":"새 축척으로 측량하고 축척변경 지번별 조서를 작성한다."},{"이름":"청산금 산정·공고","설명":"청산금 조서를 작성하고 15일 이상 공고한다."},{"이름":"납부고지·수령통지","설명":"결정 공고일부터 20일 이내에 한다."},{"이름":"납부·지급","설명":"납부는 고지받은 날부터 6개월, 지급은 통지한 날부터 6개월 이내. 이의신청은 1개월 이내."},{"이름":"확정공고","설명":"납부·지급 완료 후 지체 없이. 확정공고일에 토지의 이동이 있는 것으로 본다."}]},{"종류":"표","제목":"축척변경의 기간·비율","머리":["항목","수치","근거"],"행":[["토지소유자 동의","3분의 2 이상","법 제83조제3항"],["시행공고","20일 이상","영 제71조제1항"],["경계점표지 설치","시행공고일부터 30일 이내","영 제71조제3항"],["청산금 결정 공고","15일 이상","영 제75조제4항"],["납부고지","청산금 결정 공고일부터 20일 이내","영 제76조제1항"],["청산금 납부","고지받은 날부터 6개월 이내","영 제76조제2항"],["이의신청","고지·통지받은 날부터 1개월 이내","영 제77조제1항"],["청산 생략 합의","토지소유자 전원","영 제75조제1항제2호"]]}],"함정":"공고 기간(20일)·청산금 공고(15일)를 서로 바꿔 놓은 ②와, 청산 생략 합의를 3분의 2로 바꾼 ③이 대표 함정이다. 청산금 납부는 6개월인데 ④는 3개월로 줄였다. ①은 도시개발사업 제외 토지의 특례를 반대로 적었다."}},{"i":"S3-2-2-공시법-11","r":"S3","g":3,"c":2,"n":11,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적측량의 적부심사 등에 관한 설명이다. ( )에 들어갈 내용으로 옳은 것은?","b":"○ ( ㄱ )(으)로부터 지적측량 적부심사청구를 회부받은 지방지적위원회는 그 심사청구를 회부받은 날부터 ( ㄴ ) 이내에 심의·의결하여야 한다. 다만, 부득이한 경우에는 그 심의기간을 해당 지적위원회의 의결을 거쳐 30일 이내에서 한 번만 연장할 수 있다.\n○ ( ㄷ )은(는) 지방지적위원회의 의결서를 받은 날부터 ( ㄹ ) 이내에 지적측량 적부심사 청구인 및 이해관계인에게 그 의결서를 통지하여야 한다.","bs":"글자","img":[],"ch":["ㄱ: 시ㆍ도지사, ㄴ: 60일, ㄷ: 시ㆍ도지사, ㄹ: 15일","ㄱ: 시ㆍ도지사, ㄴ: 90일, ㄷ: 지적소관청, ㄹ: 15일","ㄱ: 시ㆍ도지사, ㄴ: 60일, ㄷ: 시ㆍ도지사, ㄹ: 7일","ㄱ: 지적소관청, ㄴ: 60일, ㄷ: 지적소관청, ㄹ: 7일","ㄱ: 지적소관청, ㄴ: 90일, ㄷ: 시ㆍ도지사, ㄹ: 15일"],"a":[3],"L":"시1-5","o":"기출","x":{"한줄":"적부심사청구는 시·도지사가 지방지적위원회에 회부하고, 위원회는 60일 이내에 의결하며, 시·도지사가 의결서를 받은 날부터 7일 이내에 통지한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제29조제1항~제6항","원문":"제29조(지적측량의 적부심사 등)\n① 토지소유자, 이해관계인 또는 지적측량수행자는 지적측량성과에 대하여 다툼이 있는 경우에는 대통령령으로 정하는 바에 따라 관할 시ㆍ도지사를 거쳐 지방지적위원회에 지적측량 적부심사를 청구할 수 있다.\n② 제1항에 따른 지적측량 적부심사청구를 받은 시ㆍ도지사는 30일 이내에 다음 각 호의 사항을 조사하여 지방지적위원회에 회부하여야 한다.\n③ 제2항에 따라 지적측량 적부심사청구를 회부받은 지방지적위원회는 그 심사청구를 회부받은 날부터 60일 이내에 심의ㆍ의결하여야 한다. 다만, 부득이한 경우에는 그 심의기간을 해당 지적위원회의 의결을 거쳐 30일 이내에서 한 번만 연장할 수 있다.\n④ 지방지적위원회는 지적측량 적부심사를 의결하였으면 대통령령으로 정하는 바에 따라 의결서를 작성하여 시ㆍ도지사에게 송부하여야 한다.\n⑤ 시ㆍ도지사는 제4항에 따라 의결서를 받은 날부터 7일 이내에 지적측량 적부심사 청구인 및 이해관계인에게 그 의결서를 통지하여야 한다.\n⑥ 제5항에 따라 의결서를 받은 자가 지방지적위원회의 의결에 불복하는 경우에는 그 의결서를 받은 날부터 90일 이내에 국토교통부장관을 거쳐 중앙지적위원회에 재심사를 청구할 수 있다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄱ·ㄴ·ㄷ은 맞지만 통지기한 ㄹ이 15일로 틀렸다. 7일이다(법 제29조제5항)."},{"번호":2,"판정":"-","설명":"심의기간 ㄴ이 90일이 아니라 60일이고, 통지 주체 ㄷ이 지적소관청이 아니라 시·도지사다."},{"번호":3,"판정":"-","설명":"ㄱ 시·도지사(법 제29조제2항), ㄴ 60일(제3항), ㄷ 시·도지사, ㄹ 7일(제5항)이다."},{"번호":4,"판정":"-","설명":"회부하는 자는 지적소관청이 아니라 시·도지사다. 적부심사는 시·도지사를 거쳐 청구한다."},{"번호":5,"판정":"-","설명":"ㄱ·ㄴ·ㄹ이 모두 틀렸다. 90일은 재심사 청구 기간이다(법 제29조제6항)."}],"개념":[{"종류":"흐름","제목":"지적측량 적부심사","단계":[{"이름":"청구","설명":"토지소유자·이해관계인·지적측량수행자가 관할 시·도지사를 거쳐 지방지적위원회에 청구한다."},{"이름":"조사·회부","설명":"시·도지사가 30일 이내에 지적측량 경위와 성과, 토지이동·소유권 변동 연혁, 주변 현황 실측도를 조사해 회부한다."},{"이름":"심의·의결","설명":"지방지적위원회가 회부받은 날부터 60일 이내에 의결한다. 부득이하면 위원회 의결을 거쳐 30일 이내에서 한 번만 연장한다."},{"이름":"의결서 송부·통지","설명":"위원회가 의결서를 시·도지사에게 송부하고, 시·도지사가 받은 날부터 7일 이내에 청구인과 이해관계인에게 통지한다."},{"이름":"재심사","설명":"불복하면 의결서를 받은 날부터 90일 이내에 국토교통부장관을 거쳐 중앙지적위원회에 청구한다."},{"이름":"정정","설명":"재심사를 청구하지 않으면 의결서 사본을 지적소관청에 보내고, 지적소관청이 등록사항을 정정하거나 측량성과를 수정한다."}]},{"종류":"표","제목":"적부심사 기간 모음","머리":["단계","기간","주체"],"행":[["조사·회부","청구를 받은 날부터 30일 이내","시·도지사"],["심의·의결","회부받은 날부터 60일 이내, 30일 이내 한 번 연장","지방지적위원회"],["의결서 통지","의결서를 받은 날부터 7일 이내","시·도지사"],["재심사 청구","의결서를 받은 날부터 90일 이내","청구인·이해관계인"]]}],"함정":"회부·통지 주체는 지적소관청이 아니라 시·도지사다. 7일, 30일, 60일, 90일이 한 조문에 몰려 있어 숫자를 서로 바꿔 쓴 선지가 나온다. 90일은 재심사 청구 기간에만 쓴다."}},{"i":"S3-2-2-공시법-12","r":"S3","g":3,"c":2,"n":12,"s":"공시법","q":"공간정보의 구축 및 관리 등에 관한 법령상 지적삼각보조점성과의 등본을 발급받으려는 경우 그 신청기관으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["시ㆍ도지사","시ㆍ도지사 또는 지적소관청","지적소관청","지적소관청 또는 한국국토정보공사","한국국토정보공사"],"a":[3],"L":"시1-5","o":"기출","x":{"한줄":"지적삼각보조점성과와 지적도근점성과의 열람·등본 발급은 지적소관청에 신청한다.","근거":[{"법령":"공간정보의 구축 및 관리 등에 관한 법률 시행규칙","조문":"제26조제1항","원문":"제26조(지적기준점성과의 열람 및 등본발급)\n① 법 제27조에 따라 지적측량기준점성과 또는 그 측량부를 열람하거나 등본을 발급받으려는 자는 지적삼각점성과에 대해서는 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사ㆍ특별자치도지사(이하 \"시ㆍ도지사\"라 한다) 또는 지적소관청에 신청하고, 지적삼각보조점성과 및 지적도근점성과에 대해서는 지적소관청에 신청하여야 한다."},{"법령":"공간정보의 구축 및 관리 등에 관한 법률","조문":"제27조","원문":"제27조(지적기준점성과의 보관 및 열람 등)\n① 시ㆍ도지사나 지적소관청은 지적기준점성과(지적기준점에 의한 측량성과를 말한다. 이하 같다)와 그 측량기록을 보관하고 일반인이 열람할 수 있도록 하여야 한다.\n② 지적기준점성과의 등본이나 그 측량기록의 사본을 발급받으려는 자는 국토교통부령으로 정하는 바에 따라 시ㆍ도지사나 지적소관청에 그 발급을 신청하여야 한다."}],"선지":[{"번호":1,"판정":"-","설명":"지적삼각점성과의 신청기관 일부다. 보조점성과는 지적소관청이다."},{"번호":2,"판정":"-","설명":"지적삼각점성과의 신청기관이다. 보조점성과는 시·도지사에게 신청하지 않는다."},{"번호":3,"판정":"-","설명":"규칙 제26조제1항 그대로다."},{"번호":4,"판정":"-","설명":"한국국토정보공사는 지적측량수행자이지 성과 등본 발급기관이 아니다."},{"번호":5,"판정":"-","설명":"한국국토정보공사는 신청기관이 아니다."}],"개념":[{"종류":"비교","제목":"지적기준점성과 신청기관","왼쪽":{"이름":"지적삼각점성과","항목":["시·도지사 또는 지적소관청에 신청"]},"오른쪽":{"이름":"지적삼각보조점성과·지적도근점성과","항목":["지적소관청에 신청"]}},{"종류":"표","제목":"지적측량 기간(규칙 제25조)","머리":["구분","기간"],"행":[["측량기간","5일"],["측량검사기간","4일"],["지적기준점 15점 이하","4일(측량·검사 각각)"],["15점 초과","4일에 15점을 초과하는 4점마다 1일 가산"],["의뢰인과 수행자 합의","합의 기간. 전체의 4분의 3은 측량기간, 4분의 1은 검사기간"]]}],"함정":"삼각점은 시·도지사 또는 지적소관청, 보조점·도근점은 지적소관청이다. 보조점을 삼각점과 같이 보면 ①②를 고르게 된다."}},{"i":"S3-2-2-공시법-13","r":"S3","g":3,"c":2,"n":13,"s":"공시법","q":"등기권리자와 등기의무자에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["절차법상 등기권리자와 실체법상 등기권리자는 항상 일치한다.","甲이 乙에게 매도하여 소유권이전등기를 마쳤으나 乙의 대금 미지급으로 매매계약이 해제된 경우, 해제에 따른 소유권이전등기의 말소등기를 신청할 때 甲은 절차법상 등기권리자이고 乙은 절차법상 등기의무자이다.","절차법상 등기의무자에 해당하는지 여부는 실체법상 권리관계에 따라 판단하여야 하고, 등기기록의 기록은 고려하지 않는다.","등기원인이 발생한 후 등기의무자가 사망한 경우, 그 상속인이 상속등기를 먼저 마치지 않으면 등기의무자로서 등기를 신청할 수 없다.","부동산이 甲→乙→丙으로 순차 매도되었으나 등기명의가 甲에게 남아 있어 丙이 乙을 대위하여 甲에서 乙로의 소유권이전등기를 신청하는 경우, 丙은 절차법상 등기권리자에 해당한다."],"a":[2],"L":"시2-1","o":"변형","x":{"한줄":"말소등기에서는 말소로 등기기록상 권리를 회복하는 직전 명의인이 절차법상 등기권리자이고, 말소 대상 등기의 명의인이 등기의무자다.","근거":[{"이론":"절차법상(형식적) 등기권리자·등기의무자","내용":"등기기록상 권리를 취득하거나 이익을 받는 자가 등기권리자, 등기기록상 권리를 상실하거나 불이익을 받는 자가 등기의무자다. 실체법상 권리의무와 일치하지 않을 수 있다."},{"법령":"부동산등기법","조문":"제27조","원문":"제27조(포괄승계인에 의한 등기신청) 등기원인이 발생한 후에 등기권리자 또는 등기의무자에 대하여 상속이나 그 밖의 포괄승계가 있는 경우에는 상속인이나 그 밖의 포괄승계인이 그 등기를 신청할 수 있다."},{"법령":"민법","조문":"제404조제1항","원문":"제404조(채권자대위권)\n①채권자는 자기의 채권을 보전하기 위하여 채무자의 권리를 행사할 수 있다. 그러나 일신에 전속한 권리는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"틀림","설명":"대위신청, 말소등기, 실체관계와 등기기록이 어긋난 경우에는 둘이 달라진다."},{"번호":2,"판정":"옳음","설명":"해제로 乙 명의 이전등기를 말소하면 등기기록상 甲이 권리를 회복하므로 甲이 등기권리자, 乙이 등기의무자다."},{"번호":3,"판정":"틀림","설명":"등기의무자 여부는 등기기록상 형식으로 판단한다. 등기관은 실체관계를 심사하지 않는다."},{"번호":4,"판정":"틀림","설명":"등기원인 발생 후 포괄승계가 있으면 상속인이 바로 그 등기를 신청할 수 있다(법 제27조)."},{"번호":5,"판정":"틀림","설명":"丙은 대위신청인이다. 절차법상 등기권리자는 권리를 취득하는 乙이다(민법 제404조제1항)."}],"개념":[{"종류":"비교","제목":"실체법상과 절차법상","왼쪽":{"이름":"실체법상 등기권리자·의무자","항목":["등기청구권이라는 실체법상 권리의무를 기준으로 한다","등기에 협력을 요구할 수 있는 자와 협력할 의무가 있는 자"]},"오른쪽":{"이름":"절차법상 등기권리자·의무자","항목":["등기기록상 권리 취득·이익 여부를 기준으로 한다","등기관은 형식으로 판단하고 실체관계는 심사하지 않는다"]}},{"종류":"표","제목":"사례별 절차법상 당사자","머리":["사례","등기권리자","등기의무자"],"행":[["매매에 따른 소유권이전","매수인","매도인(등기기록상 소유자)"],["소유권이전등기 말소(해제·무효)","직전 소유권 명의인","말소 대상 등기의 명의인"],["저당권설정등기 말소","저당권 설정자(소유자)","저당권자"],["채권자대위 이전등기(甲→乙→丙, 丙이 대위)","乙","甲"],["상속","상속인 단독신청","-"]]}],"함정":"⑤는 대위신청인을 등기권리자로 착각하게 만든 선지다. 대위한 丙은 신청인일 뿐이고 등기권리자는 乙이다. 말소등기의 등기권리자는 말소 대상 등기의 직전 명의인이다. ③은 형식 심사 원칙을 반대로 적었다."}},{"i":"S3-2-2-공시법-14","r":"S3","g":3,"c":2,"n":14,"s":"공시법","q":"등기당사자능력에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["민법상 조합은 조합 자체를 등기권리자로 하여 조합 명의로 등기를 신청한다.","종중 소유 부동산은 법인 아닌 사단의 재산이므로 종중원 전원의 공유로 등기하여야 한다.","외국인은 주민등록번호가 없어 부동산등기용등록번호를 부여받을 수 없으므로 등기권리자가 될 수 없다.","국가와 지방자치단체도 등기권리자가 될 수 있으며, 국가가 등기권리자인 경우에는 등기의무자의 승낙을 받아 해당 등기를 등기소에 촉탁한다.","법인 아닌 사단이 등기를 신청하는 경우 대표자나 관리인의 성명과 주소만 신청정보로 제공하면 되고 주민등록번호는 제공하지 않는다."],"a":[4],"L":"시2-1","o":"변형","x":{"한줄":"국가와 지방자치단체도 등기권리자가 될 수 있고, 이 경우 등기의무자의 승낙을 받아 등기를 촉탁한다.","근거":[{"법령":"부동산등기법","조문":"제98조","원문":"제98조(관공서의 촉탁에 따른 등기)\n① 국가 또는 지방자치단체가 등기권리자인 경우에는 국가 또는 지방자치단체는 등기의무자의 승낙을 받아 해당 등기를 지체 없이 등기소에 촉탁하여야 한다.\n② 국가 또는 지방자치단체가 등기의무자인 경우에는 국가 또는 지방자치단체는 등기권리자의 청구에 따라 지체 없이 해당 등기를 등기소에 촉탁하여야 한다."},{"법령":"부동산등기법","조문":"제49조제1항제4호","원문":"제49조(등록번호의 부여절차)\n① 제48조제2항에 따른 부동산등기용등록번호(이하 \"등록번호\"라 한다)는 다음 각 호의 방법에 따라 부여한다.\n  4. 외국인의 등록번호는 체류지(국내에 체류지가 없는 경우에는 대법원 소재지에 체류지가 있는 것으로 본다)를 관할하는 지방출입국ㆍ외국인관서의 장이 부여한다."},{"법령":"부동산등기법","조문":"제26조","원문":"제26조(법인 아닌 사단 등의 등기신청)\n① 종중(宗中), 문중(門中), 그 밖에 대표자나 관리인이 있는 법인 아닌 사단(社團)이나 재단(財團)에 속하는 부동산의 등기에 관하여는 그 사단이나 재단을 등기권리자 또는 등기의무자로 한다.\n② 제1항의 등기는 그 사단이나 재단의 명의로 그 대표자나 관리인이 신청한다."},{"법령":"민법","조문":"제271조제1항","원문":"제271조(물건의 합유)\n①법률의 규정 또는 계약에 의하여 수인이 조합체로서 물건을 소유하는 때에는 합유로 한다. 합유자의 권리는 합유물 전부에 미친다."},{"법령":"부동산등기규칙","조문":"제43조제2항","원문":"제43조(신청정보의 내용)\n② 법 제26조의 법인 아닌 사단이나 재단이 신청인인 경우에는 그 대표자나 관리인의 성명, 주소 및 주민등록번호를 신청정보의 내용으로 등기소에 제공하여야 한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"법 제26조는 법인 아닌 사단·재단만 등기 명의인으로 인정한다. 조합재산은 조합원 전원의 합유로 등기한다(민법 제271조제1항)."},{"번호":2,"판정":"틀림","설명":"종중은 그 사단 자체를 등기권리자·의무자로 하고 대표자나 관리인이 신청한다(법 제26조)."},{"번호":3,"판정":"틀림","설명":"외국인의 등록번호는 체류지 관할 지방출입국·외국인관서의 장이 부여한다(법 제49조제1항제4호). 외국인도 등기권리자가 될 수 있다."},{"번호":4,"판정":"옳음","설명":"국가 또는 지방자치단체가 등기권리자이면 등기의무자의 승낙을 받아 지체 없이 촉탁한다(법 제98조제1항)."},{"번호":5,"판정":"틀림","설명":"법인 아닌 사단·재단이 신청인이면 대표자나 관리인의 성명, 주소 및 주민등록번호를 제공한다(규칙 제43조제2항)."}],"개념":[{"종류":"표","제목":"등기당사자능력과 등기 명의","머리":["주체","등기 명의","근거"],"행":[["자연인(내국인·외국인)","본인 명의. 외국인은 체류지 관할 관서가 부여한 등록번호","법 제49조제1항제4호"],["법인","법인 명의","-"],["법인 아닌 사단·재단","그 사단·재단 명의로 대표자나 관리인이 신청","법 제26조"],["국가·지방자치단체","국가·지방자치단체 명의. 등기권리자이면 의무자의 승낙을 받아 촉탁","법 제98조"],["민법상 조합","조합 명의 불가. 조합원 전원의 합유","민법 제271조"]]},{"종류":"표","제목":"법인 아닌 사단·재단의 신청(규칙 제43조·제48조)","머리":["구분","제공할 정보"],"행":[["신청정보","대표자나 관리인의 성명, 주소, 주민등록번호"],["첨부정보","정관이나 그 밖의 규약"],["첨부정보","대표자나 관리인임을 증명하는 정보(등기된 대표자가 신청하면 생략)"],["첨부정보","민법 제276조제1항의 결의가 있음을 증명하는 정보(등기의무자일 때)"],["첨부정보","대표자나 관리인의 주소 및 주민등록번호를 증명하는 정보"]]}],"함정":"부동산등기법이 등기 명의를 인정하는 단체는 법인 아닌 사단·재단뿐이다. 조합은 조합원 전원의 합유로 등기한다. ⑤는 법인의 대표자(성명·주소)와 법인 아닌 사단의 대표자(주민등록번호까지)를 섞은 함정이다."}},{"i":"S3-2-2-공시법-15","r":"S3","g":3,"c":2,"n":15,"s":"공시법","q":"부동산등기를 신청하는 경우에 등기소에 제공하여야 할 신청정보 및 첨부정보에 관한 설명으로 옳은 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["「민법」상 사단법인이 부동산취득에 따른 소유권이전등기를 신청하는 경우에는 주무관청의 허가증명서면을 첨부해야 한다.","학교법인의 기본재산인 부동산에 관한 처분에 따른 등기신청에는 관할청의 허가를 증명하는 서면을 첨부할 필요가 없다.","공동신청 또는 승소한 등기권리자의 단독신청에 의하여 권리에 관한 등기를 신청하는 경우에는 등기필정보를 제공해야 한다.","농지를 매수한 자가 농지에 관하여 소유권이전등기를 마쳤더라도 농지취득자격증명을 발급받지 못하였다면 그 소유권을 취득하지 못한다.","토지에 관한 매매계약 체결 후 토지거래허가구역으로 지정된 경우에도 관할청의 토지거래허가서를 첨부하지 않으면 소유권이전등기를 마칠 수 없다."],"a":[4],"L":"시2-2","o":"기출","x":{"한줄":"농지취득자격증명은 농지 소유권 취득의 요건이어서, 이를 발급받지 못한 채 등기를 마쳐도 소유권을 취득하지 못한다.","근거":[{"법령":"농지법","조문":"제8조제1항·제6항","원문":"제8조(농지취득자격증명의 발급)\n①농지를 취득하려는 자는 농지 소재지를 관할하는 시장(구를 두지 아니한 시의 시장을 말하며, 도농 복합 형태의 시는 농지 소재지가 동지역인 경우만을 말한다), 구청장(도농 복합 형태의 시의 구에서는 농지 소재지가 동지역인 경우만을 말한다), 읍장 또는 면장(이하 \"시ㆍ구ㆍ읍ㆍ면의 장\"이라 한다)에게서 농지취득자격증명을 발급받아야 한다. 다만, 다음 각 호의 어느 하나에 해당하면 농지취득자격증명을 발급받지 아니하고 농지를 취득할 수 있다.\n⑥제1항 본문과 제2항에 따라 농지취득자격증명을 발급받아 농지를 취득하는 자가 그 소유권에 관한 등기를 신청할 때에는 농지취득자격증명을 첨부하여야 한다."},{"법령":"부동산등기규칙","조문":"제43조제1항제7호","원문":"제43조(신청정보의 내용)\n① 등기를 신청하는 경우에는 다음 각 호의 사항을 신청정보의 내용으로 등기소에 제공하여야 한다.\n  7. 등기필정보. 다만, 공동신청 또는 승소한 등기의무자의 단독신청에 의하여 권리에 관한 등기를 신청하는 경우로 한정한다."},{"법령":"부동산 거래신고 등에 관한 법률","조문":"제11조제1항","원문":"제11조(허가구역 내 토지거래에 대한 허가)\n① 허가구역에 있는 토지에 관한 소유권ㆍ지상권(소유권ㆍ지상권의 취득을 목적으로 하는 권리를 포함한다)을 이전하거나 설정(대가를 받고 이전하거나 설정하는 경우만 해당한다)하는 계약(예약을 포함한다. 이하 \"토지거래계약\"이라 한다)을 체결하려는 당사자는 공동으로 대통령령으로 정하는 바에 따라 시장ㆍ군수 또는 구청장의 허가를 받아야 한다. 허가받은 사항을 변경하려는 경우에도 또한 같다."}],"선지":[{"번호":1,"판정":"틀림","설명":"비영리법인의 설립허가는 법인 자체의 요건이다. 법인이 부동산을 취득하는 이전등기에 주무관청 허가서를 첨부하라는 규정은 없다."},{"번호":2,"판정":"틀림","설명":"학교법인이 기본재산을 처분하려면 관할청의 허가가 필요하고(사립학교법 제28조제1항), 처분에 따른 등기신청에는 그 허가를 증명하는 정보를 첨부한다(규칙 제46조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"등기필정보는 공동신청 또는 승소한 등기의무자의 단독신청일 때 제공한다(규칙 제43조제1항제7호). 승소한 등기권리자의 단독신청에는 제공하지 않는다."},{"번호":4,"판정":"옳음","설명":"농지를 취득하려면 농지취득자격증명을 발급받아야 하고(농지법 제8조제1항), 이를 발급받아 취득한 자가 등기를 신청할 때 첨부한다(같은 조 제6항). 증명 없이 마친 이전등기로는 소유권을 취득하지 못한다."},{"번호":5,"판정":"틀림","설명":"허가는 허가구역 안의 토지에 대한 계약을 체결하려는 당사자가 받는 것이다(거래신고법 제11조제1항). 허가구역 지정 전에 체결한 계약의 이전등기에는 허가서 첨부를 요구하지 않는다."}],"개념":[{"종류":"표","제목":"등기신청 시 주요 제공정보","머리":["정보","제공 여부"],"행":[["등기필정보","공동신청, 승소한 등기의무자의 단독신청에 제공. 승소한 등기권리자의 단독신청에는 불요"],["농지취득자격증명","농지 소유권이전등기 신청 시 첨부(농지법 제8조제6항). 법령상 면제 사유는 예외"],["토지거래허가서","허가구역 안 토지 계약 후 이전등기 시 첨부. 지정 전 체결 계약은 불요"],["학교법인 기본재산 처분 허가","관할청의 허가를 증명하는 정보 첨부"],["법인 대표자 자격","법인 신청 시 대표자 자격을 증명하는 정보 첨부(규칙 제46조제1항제4호)"],["등기원인에 대한 제3자 허가·동의","허가·동의·승낙을 증명하는 정보 첨부(규칙 제46조제1항제2호)"]]}],"함정":"농지취득자격증명은 이전등기를 마쳤다고 해서 나중에 보충되는 서류가 아니다. 증명 없이 한 등기로는 소유권을 취득하지 못한다. 토지거래허가는 계약 체결 시점이 기준이다. 승소한 등기권리자와 승소한 등기의무자에서 등기필정보 제공 여부가 갈린다."}},{"i":"S3-2-2-공시법-16","r":"S3","g":3,"c":2,"n":16,"s":"공시법","q":"매매를 원인으로 한 토지소유권이전등기를 신청하는 경우에 부동산등기규칙상 신청정보의 내용으로 등기소에 제공해야 하는 사항으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["등기권리자의 등기필정보","토지의 표시에 관한 사항 중 면적","토지의 표시에 관한 사항 중 표시번호","신청인이 법인인 경우에 그 대표자의 주민등록번호","대리인에 의하여 등기를 신청하는 경우에 그 대리인의 주민등록번호"],"a":[2],"L":"시2-2","o":"기출","x":{"한줄":"토지의 표시는 소재와 지번, 지목, 면적을 신청정보로 제공한다.","근거":[{"법령":"부동산등기규칙","조문":"제43조제1항","원문":"제43조(신청정보의 내용)\n① 등기를 신청하는 경우에는 다음 각 호의 사항을 신청정보의 내용으로 등기소에 제공하여야 한다.\n  1. 다음 각 목의 구분에 따른 부동산의 표시에 관한 사항\n    가. 토지 : 법 제34조제3호부터 제5호까지의 규정에서 정하고 있는 사항\n  3. 신청인이 법인인 경우에는 그 대표자의 성명과 주소\n  4. 대리인에 의하여 등기를 신청하는 경우에는 그 성명과 주소\n  7. 등기필정보. 다만, 공동신청 또는 승소한 등기의무자의 단독신청에 의하여 권리에 관한 등기를 신청하는 경우로 한정한다."},{"법령":"부동산등기법","조문":"제34조","원문":"제34조(등기사항) 등기관은 토지 등기기록의 표제부에 다음 각 호의 사항을 기록하여야 한다.\n  1. 표시번호\n  3. 소재와 지번(地番)\n  4. 지목(地目)\n  5. 면적"}],"선지":[{"번호":1,"판정":"틀림","설명":"제공하는 등기필정보는 등기의무자의 것이다. 공동신청 또는 승소한 등기의무자의 단독신청일 때만 제공한다(규칙 제43조제1항제7호)."},{"번호":2,"판정":"옳음","설명":"토지의 표시는 법 제34조제3호부터 제5호까지의 소재와 지번, 지목, 면적이다(규칙 제43조제1항제1호 가목)."},{"번호":3,"판정":"틀림","설명":"표시번호는 법 제34조제1호 사항으로, 규칙 제43조제1항제1호 가목이 정한 제3호~제5호에 들어가지 않는다."},{"번호":4,"판정":"틀림","설명":"신청인이 법인이면 대표자의 성명과 주소를 제공한다(규칙 제43조제1항제3호). 주민등록번호는 포함되지 않는다."},{"번호":5,"판정":"틀림","설명":"대리인에 의한 신청이면 대리인의 성명과 주소를 제공한다(규칙 제43조제1항제4호). 주민등록번호는 포함되지 않는다."}],"개념":[{"종류":"표","제목":"신청정보의 내용(규칙 제43조제1항)","머리":["호","제공 사항"],"행":[["1호","부동산의 표시(토지: 소재와 지번·지목·면적)"],["2호","신청인의 성명(명칭), 주소(사무소 소재지), 주민등록번호(등록번호)"],["3호","신청인이 법인이면 대표자의 성명과 주소"],["4호","대리인에 의한 신청이면 대리인의 성명과 주소"],["5호","등기원인과 그 연월일"],["6호","등기의 목적"],["7호","등기필정보(공동신청·승소한 등기의무자의 단독신청)"],["8호","등기소의 표시"],["9호","신청연월일"]]}],"함정":"법인의 대표자와 대리인은 성명과 주소만 제공하고, 주민등록번호는 신청인 본인에게만 요구한다(법인 아닌 사단의 대표자는 예외로 주민등록번호까지). 등기필정보는 등기권리자가 아니라 등기의무자의 것이다."}},{"i":"S3-2-2-공시법-17","r":"S3","g":3,"c":2,"n":17,"s":"공시법","q":"등기권리자와 등기의무자가 등기를 공동으로 신청해야 하는 경우는?","b":null,"bs":"없음","img":[],"ch":["특정유증에 따른 등기","이행판결에 의한 등기","부동산표시의 변경등기","소유권보존등기의 말소등기","신탁재산에 속하는 부동산의 신탁등기"],"a":[1],"L":"시2-2","o":"기출","x":{"한줄":"특정유증에 따른 소유권이전등기는 법에 단독신청 규정이 없어 원칙대로 공동신청한다.","근거":[{"법령":"부동산등기법","조문":"제23조","원문":"제23조(등기신청인)\n① 등기는 법률에 다른 규정이 없는 경우에는 등기권리자(登記權利者)와 등기의무자(登記義務者)가 공동으로 신청한다.\n② 소유권보존등기(所有權保存登記) 또는 소유권보존등기의 말소등기(抹消登記)는 등기명의인으로 될 자 또는 등기명의인이 단독으로 신청한다.\n③ 상속, 법인의 합병, 그 밖에 대법원규칙으로 정하는 포괄승계에 따른 등기는 등기권리자가 단독으로 신청한다.\n④ 등기절차의 이행 또는 인수를 명하는 판결에 의한 등기는 승소한 등기권리자 또는 등기의무자가 단독으로 신청하고, 공유물을 분할하는 판결에 의한 등기는 등기권리자 또는 등기의무자가 단독으로 신청한다.\n⑤ 부동산표시의 변경이나 경정(更正)의 등기는 소유권의 등기명의인이 단독으로 신청한다.\n⑥ 등기명의인표시의 변경이나 경정의 등기는 해당 권리의 등기명의인이 단독으로 신청한다.\n⑦ 신탁재산에 속하는 부동산의 신탁등기는 수탁자(受託者)가 단독으로 신청한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"포괄승계에 해당하지 않는 특정유증은 수증자(등기권리자)와 유증자의 상속인 등(등기의무자)이 공동으로 신청한다(법 제23조제1항)."},{"번호":2,"판정":"틀림","설명":"이행판결에 의한 등기는 승소한 등기권리자 또는 등기의무자가 단독으로 신청한다(법 제23조제4항)."},{"번호":3,"판정":"틀림","설명":"부동산표시의 변경이나 경정의 등기는 소유권의 등기명의인이 단독으로 신청한다(법 제23조제5항)."},{"번호":4,"판정":"틀림","설명":"소유권보존등기의 말소등기는 등기명의인이 단독으로 신청한다(법 제23조제2항)."},{"번호":5,"판정":"틀림","설명":"신탁재산에 속하는 부동산의 신탁등기는 수탁자가 단독으로 신청한다(법 제23조제7항)."}],"개념":[{"종류":"표","제목":"단독신청과 공동신청","머리":["구분","신청 방법","근거"],"행":[["원칙","등기권리자와 등기의무자 공동","법 제23조제1항"],["소유권보존등기·그 말소등기","등기명의인(될 자)이 단독","법 제23조제2항"],["상속·법인합병 등 포괄승계","등기권리자 단독","법 제23조제3항"],["이행·인수 판결, 공유물분할 판결","승소한 권리자·의무자 단독","법 제23조제4항"],["부동산표시의 변경·경정","소유권 등기명의인 단독","법 제23조제5항"],["등기명의인표시의 변경·경정","해당 권리의 등기명의인 단독","법 제23조제6항"],["신탁재산 신탁등기","수탁자 단독","법 제23조제7항"],["특정유증","공동신청","법 제23조제1항"]]},{"종류":"비교","제목":"포괄유증과 특정유증","왼쪽":{"이름":"포괄유증","항목":["수증자는 상속인과 같은 권리의무","등기신청은 공동신청"]},"오른쪽":{"이름":"특정유증","항목":["특정 재산을 지정하여 증여","등기원인은 유증, 공동신청"]}}],"함정":"이행판결, 표시변경, 보존말소, 신탁등기는 모두 법에 단독신청 규정이 있다. 유증은 상속과 달리 포괄승계 단독신청 규정(제23조제3항)에 들어가지 않는다. 포괄유증의 등기도 공동신청으로 처리한다."}},{"i":"S3-2-2-공시법-18","r":"S3","g":3,"c":2,"n":18,"s":"공시법","q":"부동산등기에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["유증으로 인한 소유권이전등기는 상속등기를 거치지 않으면 유증자로부터 직접 수증자 명의로 신청할 수 없다.","유증으로 인한 소유권이전등기 신청이 상속인의 유류분을 침해하는 내용인 경우에는 등기관은 이를 수리할 수 없다.","상속재산분할심판에 따른 상속인의 소유권이전등기는 법정상속분에 따른 상속등기를 거치지 않으면 할 수 없다.","상속등기 경료 전의 상속재산분할협의에 따라 상속등기를 신청하는 경우, 등기원인일자는 '협의분할일'로 한다.","권리의 변경등기는 그 등기로 등기상 이해관계 있는 제3자의 권리가 침해되는 경우, 그 제3자의 승낙 또는 이에 대항할 수 있는 재판이 있음을 증명하는 정보의 제공이 없으면 부기등기로 할 수 없다."],"a":[5],"L":"시2-3","o":"기출","x":{"한줄":"권리의 변경·경정등기는 원칙적으로 부기등기로 하되, 등기상 이해관계 있는 제3자의 승낙이 없으면 주등기로 한다.","근거":[{"법령":"부동산등기법","조문":"제52조제5호","원문":"제52조(부기로 하는 등기) 등기관이 다음 각 호의 등기를 할 때에는 부기로 하여야 한다. 다만, 제5호의 등기는 등기상 이해관계 있는 제3자의 승낙이 없는 경우에는 그러하지 아니하다.\n  5. 권리의 변경이나 경정의 등기"},{"법령":"부동산등기규칙","조문":"제46조제1항제3호","원문":"제46조(첨부정보)\n① 등기를 신청하는 경우에는 다음 각 호의 정보를 그 신청정보와 함께 첨부정보로서 등기소에 제공하여야 한다.\n  3. 등기상 이해관계 있는 제3자의 승낙이 필요한 경우에는 이를 증명하는 정보 또는 이에 대항할 수 있는 재판이 있음을 증명하는 정보\n  3. 건물의 소유자가 그 건물이 속하는 1동의 건물이 있는 「집합건물의 소유 및 관리에 관한 법률」 제2조제5호에 따른 건물의 대지에 대하여 가지는 대지사용권이 대지권이 아닌 경우"},{"이론":"상속·유증 등기 실무","내용":"유증은 유증자 명의에서 수증자 명의로 직접 이전하고, 상속재산분할심판·협의분할에 따른 상속등기의 등기원인일자는 상속개시일이다. 등기관은 형식적 심사만 하므로 유류분 침해 여부를 이유로 각하하지 않는다."}],"선지":[{"번호":1,"판정":"틀림","설명":"유증은 상속등기를 거치지 않고 유증자로부터 직접 수증자 명의로 신청한다."},{"번호":2,"판정":"틀림","설명":"등기관은 형식적 심사권만 가지므로 유류분 침해 여부를 이유로 신청을 각하하지 못한다(법 제29조 각 호에 해당 사유가 없다)."},{"번호":3,"판정":"틀림","설명":"상속재산분할심판에 따른 이전등기는 법정상속분에 따른 상속등기를 거치지 않고 해당 상속인 명의로 직접 신청할 수 있다."},{"번호":4,"판정":"틀림","설명":"협의분할에 따른 상속등기의 등기원인일자는 협의분할일이 아니라 상속개시일(피상속인의 사망일)이다."},{"번호":5,"판정":"옳음","설명":"법 제52조 제5호 단서 그대로다. 제3자의 승낙이 없으면 부기가 아니라 주등기로 한다."}],"개념":[{"종류":"표","제목":"부기등기로 하는 등기(법 제52조)","머리":["호","대상","비고"],"행":[["1호","등기명의인표시의 변경·경정",""],["2호","소유권 외의 권리의 이전등기","저당권이전 등"],["3호","소유권 외의 권리를 목적으로 하는 권리에 관한 등기","전세권저당권 등"],["4호","소유권 외의 권리에 대한 처분제한 등기",""],["5호","권리의 변경·경정등기","이해관계 있는 제3자의 승낙이 없으면 주등기"],["6~8호","환매특약, 권리소멸약정, 공유물 분할금지 약정등기",""]]},{"종류":"비교","제목":"상속과 유증의 등기","왼쪽":{"이름":"상속","항목":["법정상속분대로 상속인 단독신청(법 제23조제3항)","협의분할이면 등기원인일자는 상속개시일"]},"오른쪽":{"이름":"유증","항목":["유증자 → 수증자 직접 신청","공동신청(법 제23조제1항)"]}}],"함정":"변경등기를 부기로 하는 것은 맞지만, 제3자의 승낙이 없으면 주등기다. 상속의 등기원인일자는 협의분할일이 아니라 상속개시일이다. 유증등기에 상속등기를 먼저 하라는 설명도 틀렸다."}},{"i":"S3-2-2-공시법-19","r":"S3","g":3,"c":2,"n":19,"s":"공시법","q":"구분건물의 등기에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["대지권의 표시에 관한 사항은 전유부분의 등기기록 표제부에 기록하여야 한다.","토지전세권이 대지권인 경우에 대지권이라는 뜻의 등기가 되어 있는 토지의 등기기록에는 특별한 사정이 없는 한 그 전세권을 목적으로 하는 저당권설정등기를 할 수 없다.","대지권의 변경이 있는 경우, 구분건물의 소유권의 등기명의인은 1동의 건물에 속하는 다른 구분건물의 소유권의 등기명의인을 대위하여 대지권변경등기를 신청할 수 있다.","1동의 건물에 속하는 구분건물 중 일부만에 관하여 소유권보존등기를 신청하는 경우에는 나머지 구분건물의 표시에 관한 등기를 동시에 신청하여야 한다.","집합건물의 규약상 공용부분이라는 뜻을 정한 규약을 폐지한 경우, 그 공용부분의 취득자는 소유권이전등기를 신청하여야 한다."],"a":[5],"L":"시2-3","o":"기출","x":{"한줄":"공용부분이라는 뜻을 정한 규약을 폐지하면 공용부분의 취득자는 지체 없이 소유권보존등기를 신청한다.","근거":[{"법령":"부동산등기법","조문":"제47조제2항","원문":"제47조(규약상 공용부분의 등기와 규약폐지에 따른 등기)\n② 공용부분이라는 뜻을 정한 규약을 폐지한 경우에 공용부분의 취득자는 지체 없이 소유권보존등기를 신청하여야 한다."},{"법령":"부동산등기법","조문":"제40조제3항·제4항","원문":"제40조(등기사항)\n③ 구분건물에 「집합건물의 소유 및 관리에 관한 법률」 제2조제6호의 대지사용권(垈地使用權)으로서 건물과 분리하여 처분할 수 없는 것[이하 \"대지권\"(垈地權)이라 한다]이 있는 경우에는 등기관은 제2항에 따라 기록하여야 할 사항 외에 1동 건물의 등기기록의 표제부에 대지권의 목적인 토지의 표시에 관한 사항을 기록하고 전유부분의 등기기록의 표제부에는 대지권의 표시에 관한 사항을 기록하여야 한다.\n④ 등기관이 제3항에 따라 대지권등기를 하였을 때에는 직권으로 대지권의 목적인 토지의 등기기록에 소유권, 지상권, 전세권 또는 임차권이 대지권이라는 뜻을 기록하여야 한다."},{"법령":"부동산등기법","조문":"제61조제4항·제5항","원문":"제61조(구분건물의 등기기록에 대지권등기가 되어 있는 경우)\n④ 토지의 소유권이 대지권인 경우에 대지권이라는 뜻의 등기가 되어 있는 토지의 등기기록에는 소유권이전등기, 저당권설정등기, 그 밖에 이와 관련이 있는 등기를 할 수 없다.\n⑤ 지상권, 전세권 또는 임차권이 대지권인 경우에는 제4항을 준용한다."},{"법령":"부동산등기법","조문":"제41조제3항","원문":"제41조(변경등기의 신청)\n③ 구분건물로서 그 대지권의 변경이나 소멸이 있는 경우에는 구분건물의 소유권의 등기명의인은 1동의 건물에 속하는 다른 구분건물의 소유권의 등기명의인을 대위하여 그 등기를 신청할 수 있다."},{"법령":"부동산등기법","조문":"제46조제1항","원문":"제46조(구분건물의 표시에 관한 등기)\n① 1동의 건물에 속하는 구분건물 중 일부만에 관하여 소유권보존등기를 신청하는 경우에는 나머지 구분건물의 표시에 관한 등기를 동시에 신청하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"전유부분의 표제부에 대지권의 표시에 관한 사항을 기록한다(법 제40조제3항)."},{"번호":2,"판정":"옳음","설명":"지상권·전세권·임차권이 대지권인 경우 토지 등기기록에는 대지권이라는 뜻의 등기 후 해당 권리와 관련된 등기를 할 수 없다(법 제61조제4항·제5항)."},{"번호":3,"판정":"옳음","설명":"대지권의 변경·소멸 시 구분소유자는 다른 구분건물의 소유권 등기명의인을 대위하여 신청할 수 있다(법 제41조제3항)."},{"번호":4,"판정":"옳음","설명":"일부 구분건물만 보존등기를 신청하면 나머지 구분건물의 표시등기를 동시에 신청해야 한다(법 제46조제1항)."},{"번호":5,"판정":"틀림","설명":"규약을 폐지하면 공용부분의 취득자는 소유권이전등기가 아니라 소유권보존등기를 신청한다(법 제47조제2항)."}],"개념":[{"종류":"표","제목":"구분건물 등기 요점","머리":["항목","내용","근거"],"행":[["1동 건물 표제부","소재와 지번, 건물명칭, 번호 기록. 대지권의 목적인 토지 표시 기록","법 제40조제2항·제3항"],["전유부분 표제부","건물번호, 대지권의 표시 기록","법 제40조제2항·제3항"],["대지권 토지 등기기록","대지권이라는 뜻을 직권 기록","법 제40조제4항"],["대지권 등기 후 건물 등기","대지권에도 같은 효력. 건물만 처분하는 등기는 불가","법 제61조제1항·제3항"],["일부만 보존등기","나머지 구분건물의 표시등기 동시 신청","법 제46조제1항"],["대지권 변경·소멸","다른 구분건물 소유자를 대위하여 신청 가능","법 제41조제3항"]]},{"종류":"비교","제목":"규약상 공용부분 등기","왼쪽":{"이름":"공용부분이라는 뜻의 등기","항목":["소유권의 등기명의인이 신청","소유권 외의 권리가 있으면 그 권리자의 승낙 필요"]},"오른쪽":{"이름":"규약 폐지","항목":["공용부분의 취득자가 신청","지체 없이 소유권보존등기를 신청"]}}],"함정":"규약을 폐지하면 공용부분이 일반 건물이 되므로 새로 소유권의 등기를 해야 한다. 등기명의인이 없으니 이전이 아니라 보존이다. ②는 저당권의 대상이 대지권인 전세권으로 한정된 문장이다.","개정":"선지 ②는 원 기출에서 「저당권설정등기」였던 부분을 「그 전세권을 목적으로 하는 저당권설정등기」로 한정했다. 법 제61조제5항이 제4항을 준용하는 문언이 토지소유권에 대한 저당권과 구분되지 않아 공식 복수정답(②,⑤)이던 문항을 ⑤ 단일정답으로 정리한 것이며, 법령 개정에 따른 변경은 아니다."}},{"i":"S3-2-2-공시법-20","r":"S3","g":3,"c":2,"n":20,"s":"공시법","q":"근저당권등기에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["근저당권설정등기를 할 때 채무자의 성명 또는 명칭과 주소는 기록하지 않고 채권자의 표시만 기록한다.","근저당권의 존속기간은 등기원인에 그 약정이 있는 경우에만 등기사항이 된다.","근저당권설정등기를 신청할 때에는 확정된 채권액을 신청정보의 내용으로 제공한다.","근저당권설정등기에는 이자 및 그 발생기·지급시기의 약정이 있으면 이를 기록한다.","근저당권을 피담보채권과 분리하여 양도하는 근저당권이전등기도 신청할 수 있다."],"a":[2],"L":"시2-4","o":"변형","x":{"한줄":"근저당권의 존속기간은 등기원인에 약정이 있는 경우에만 기록한다.","근거":[{"법령":"부동산등기법","조문":"제75조제2항","원문":"제75조(저당권의 등기사항)\n  1. 채권액\n  2. 채무자의 성명 또는 명칭과 주소 또는 사무소 소재지\n  3. 변제기(辨濟期)\n  4. 이자 및 그 발생기ㆍ지급시기\n② 등기관은 제1항의 저당권의 내용이 근저당권(根抵當權)인 경우에는 제48조에서 규정한 사항 외에 다음 각 호의 사항을 기록하여야 한다. 다만, 제3호 및 제4호는 등기원인에 그 약정이 있는 경우에만 기록한다.\n  1. 채권의 최고액\n  2. 채무자의 성명 또는 명칭과 주소 또는 사무소 소재지\n  3. 「민법」 제358조 단서의 약정\n  4. 존속기간"},{"법령":"부동산등기규칙","조문":"제52조제5호","원문":"제52조(사건이 등기할 것이 아닌 경우) 법 제29조제2호에서 \"사건이 등기할 것이 아닌 경우\"란 다음 각 호의 어느 하나에 해당하는 경우를 말한다.\n  5. 저당권을 피담보채권과 분리하여 양도하거나, 피담보채권과 분리하여 다른 채권의 담보로 하는 등기를 신청한 경우"}],"선지":[{"번호":1,"판정":"틀림","설명":"채무자의 성명 또는 명칭과 주소는 근저당권설정등기의 필수 기록사항이다(법 제75조제2항제2호)."},{"번호":2,"판정":"옳음","설명":"존속기간은 법 제75조제2항 제4호이고, 단서에 따라 등기원인에 그 약정이 있는 경우에만 기록한다."},{"번호":3,"판정":"틀림","설명":"근저당권은 확정된 채권액이 아니라 채권의 최고액을 기록한다(법 제75조제2항제1호)."},{"번호":4,"판정":"틀림","설명":"이자 및 그 발생기·지급시기는 저당권(법 제75조제1항제4호)의 등기사항이다. 근저당권의 등기사항에는 들어 있지 않다."},{"번호":5,"판정":"틀림","설명":"저당권을 피담보채권과 분리하여 양도하는 등기를 신청하면 각하된다(규칙 제52조제5호)."}],"개념":[{"종류":"표","제목":"저당권과 근저당권의 등기사항(법 제75조)","머리":["구분","필수 기록","약정이 있을 때만 기록"],"행":[["저당권(제1항)","채권액, 채무자의 성명(명칭)·주소","변제기, 이자와 그 발생기·지급시기, 원본·이자 지급장소, 채무불이행 손해배상 약정, 민법 제358조 단서의 약정, 채권의 조건"],["근저당권(제2항)","채권의 최고액, 채무자의 성명(명칭)·주소","민법 제358조 단서의 약정, 존속기간"]]},{"종류":"비교","제목":"저당권과 근저당권의 차이","왼쪽":{"이름":"저당권","항목":["확정된 채권액을 기록","변제기·이자 등을 약정이 있으면 기록","피담보채권과 분리하여 양도·담보 제공 불가"]},"오른쪽":{"이름":"근저당권","항목":["채권의 최고액을 기록","변제기·이자는 등기사항이 아님. 존속기간은 약정이 있으면 기록","피담보채권과 분리하여 양도하는 등기는 각하"]}}],"함정":"저당권의 등기사항인 변제기·이자는 근저당권의 등기사항이 아니다. 근저당권은 최고액과 채무자가 필수이고 존속기간은 약정이 있을 때만 기록한다. 피담보채권과 분리한 양도는 근저당권에서도 허용되지 않는다."}},{"i":"S3-2-2-공시법-21","r":"S3","g":3,"c":2,"n":21,"s":"공시법","q":"전세권 등기에 관한 설명으로 틀린 것은? (다툼이 있으면 판례에 따름)","b":null,"bs":"없음","img":[],"ch":["전세권 설정등기를 하는 경우, 등기관은 전세금을 기록해야 한다.","전세권의 사용ㆍ수익 권능을 배제하고 채권담보만을 위해 전세권을 설정한 경우, 그 전세권설정등기는 무효이다.","집합건물에 있어서 특정 전유부분의 대지권에 대하여는 전세권설정등기를 할 수가 없다.","전세권의 목적인 범위가 건물의 일부로서 특정 층 전부인 경우에는 전세권설정등기 신청서에 그 층의 도면을 첨부해야 한다.","乙명의의 전세권등기와 그 전세권에 대한 丙명의의 가압류가 순차로 마쳐진 甲소유 부동산에 대하여 乙명의의 전세권등기를 말소하라는 판결을 받았다고 하더라도 그 판결에 의하여 전세권말소등기를 신청할 때에는 丙의 승낙서 또는 丙에게 대항할 수 있는 재판의 등본을 첨부해야 한다."],"a":[4],"L":"시2-4","o":"기출","x":{"한줄":"특정 층 전부는 층 표시만으로 범위가 정해지므로 도면을 첨부하지 않는다. 도면은 층의 일부처럼 범위를 그림으로 특정해야 할 때 낸다.","근거":[{"법령":"부동산등기규칙","조문":"제128조제2항","원문":"전세권설정 또는 전전세의 범위가 부동산의 일부인 경우에는 그 부분을 표시한 지적도나 건물도면을 첨부정보로서 등기소에 제공하여야 한다."},{"법령":"부동산등기법","조문":"제72조제1항제1호·제6호","원문":"1. 전세금 또는 전전세금\n6. 전세권설정이나 전전세의 범위가 부동산의 일부인 경우에는 그 부분을 표시한 도면의 번호"},{"법령":"부동산등기법","조문":"제57조제1항","원문":"등기의 말소를 신청하는 경우에 그 말소에 대하여 등기상 이해관계 있는 제3자가 있을 때에는 제3자의 승낙이 있어야 한다."},{"판례":"대법원 판례","요지":"전세권설정계약의 당사자가 전세권자의 사용·수익 권능을 배제하고 채권담보만을 위해 전세권을 설정했다면 그 전세권설정등기는 무효다. 민법 제303조 제1항이 전세권을 사용·수익하는 물권으로 정하기 때문이다."}],"선지":[{"번호":1,"판정":"옳음","설명":"전세금은 전세권설정등기에서 반드시 적는 사항이다(법 제72조제1항제1호). 존속기간·위약금·민법 제306조 단서 약정은 원인에 약정이 있을 때만 적는다."},{"번호":2,"판정":"옳음","설명":"사용·수익을 배제한 채 채권담보만 목적으로 한 전세권설정등기는 무효다(민법 제303조제1항, 대법원 판례)."},{"번호":3,"판정":"옳음","설명":"전유부분과 대지사용권은 분리해 처분할 수 없다(집합건물법 제20조제2항). 대지권 등기를 한 뒤에는 전유부분이나 대지권만을 따로 목적으로 하는 권리등기를 할 수 없다(법 제61조제3항·제4항)."},{"번호":4,"판정":"틀림","설명":"도면은 범위가 부동산의 일부일 때 낸다(규칙 제128조제2항). 특정 층 전부는 층으로 범위가 특정되어 도면 첨부 대상이 아니다."},{"번호":5,"판정":"옳음","설명":"전세권 위에 가압류를 한 丙은 전세권 말소로 불이익을 받는 이해관계인이다. 말소판결이 있어도 丙의 승낙서나 대항 재판의 등본을 첨부한다(법 제57조제1항)."}],"개념":[{"종류":"표","제목":"용익권 설정등기의 기록사항","머리":["권리","반드시 적는 것","약정이 있을 때만","일부 설정 시"],"행":[["지상권(법 제69조)","목적, 범위","존속기간, 지료·지급시기, 민법 제289조의2제1항 후단의 약정","도면 번호"],["지역권(법 제70조)","목적, 범위, 요역지","민법 제292조제1항 단서·제297조제1항 단서·제298조의 약정","승역지 일부면 도면 번호"],["전세권(법 제72조)","전세금, 범위","존속기간, 위약금·배상금, 민법 제306조 단서의 약정","도면 번호"],["임차권(법 제74조)","차임, 범위","차임지급시기, 존속기간, 임차보증금, 양도·전대 동의","도면 번호"]]},{"종류":"표","제목":"전세권 등기 쟁점 모음","머리":["쟁점","결론","근거"],"행":[["일부 설정","도면이나 지적도 첨부, 등기기록에 도면 번호 기록","규칙 제128조제2항, 법 제72조제1항제6호"],["층 전부 설정","층으로 범위가 특정되어 도면 불요","선지 4의 판단"],["전세금반환채권 일부양도","존속기간 만료 전에는 일부이전 신청 불가, 소멸 증명 시 가능","법 제73조제2항"],["일부이전 기록사항","양도액 기록","법 제73조제1항"],["전세권 말소 시 그 위의 가압류권자","승낙서 또는 대항 재판 필요","법 제57조제1항"],["사용·수익 배제 전세권","무효","민법 제303조제1항"]]}],"함정":"선지 5를 틀렸다고 보기 쉽다. 말소판결이 있으면 승낙이 필요 없다고 생각하는 경우다. 판결로 단독신청을 해도 이해관계인의 승낙 요건은 그대로여서 가압류권자 丙의 승낙서나 대항 재판의 등본이 필요하다. 선지 3은 대지권 등기를 한 구분건물이라는 전제를 놓치면 틀려 보인다."}},{"i":"S3-2-2-공시법-22","r":"S3","g":3,"c":2,"n":22,"s":"공시법","q":"다음 중 부기등기가 아니라 주등기로 해야 하는 것은? (단, 등기상 이해관계 있는 제3자의 승낙서는 제공되지 않았다)","b":null,"bs":"없음","img":[],"ch":["후순위 저당권이 설정되어 있는 1번 근저당권의 채권최고액을 증액하는 변경등기","지상권에 대한 가압류등기","전세권의 이전등기","근저당권자의 주소가 바뀐 경우의 등기명의인표시변경등기","소유권에 대한 환매특약등기"],"a":[1],"L":"시2-5","o":"변형","x":{"한줄":"권리의 변경등기는 이해관계 있는 제3자의 승낙이 없으면 주등기로 한다. 최고액 증액은 후순위 저당권자의 배당 몫을 줄이므로 후순위 저당권자가 승낙해야 부기로 한다.","근거":[{"법령":"부동산등기법","조문":"제52조","원문":"등기관이 다음 각 호의 등기를 할 때에는 부기로 하여야 한다. 다만, 제5호의 등기는 등기상 이해관계 있는 제3자의 승낙이 없는 경우에는 그러하지 아니하다.\n1. 등기명의인표시의 변경이나 경정의 등기\n2. 소유권 외의 권리의 이전등기\n3. 소유권 외의 권리를 목적으로 하는 권리에 관한 등기\n4. 소유권 외의 권리에 대한 처분제한 등기\n5. 권리의 변경이나 경정의 등기\n6. 제53조의 환매특약등기"},{"법령":"부동산등기규칙","조문":"제112조제1항","원문":"등기관이 권리의 변경이나 경정의 등기를 할 때에는 변경이나 경정 전의 등기사항을 말소하는 표시를 하여야 한다. 다만, 등기상 이해관계 있는 제3자의 승낙이 없어 변경이나 경정을 주등기로 할 때에는 그러하지 아니하다."}],"선지":[{"번호":1,"판정":"옳음","설명":"권리의 변경등기(법 제52조제5호)다. 후순위 저당권자가 이해관계인이고 승낙서가 없으므로 주등기로 한다(같은 조 단서, 규칙 제112조제1항 단서). 주등기라서 변경 전 사항을 말소하는 표시도 하지 않는다."},{"번호":2,"판정":"옳음","설명":"소유권 외의 권리(지상권)에 대한 처분제한등기이므로 승낙과 관계없이 부기로 한다(법 제52조제4호)."},{"번호":3,"판정":"옳음","설명":"소유권 외의 권리의 이전등기는 부기로 한다(법 제52조제2호)."},{"번호":4,"판정":"옳음","설명":"등기명의인표시의 변경등기는 제3자의 승낙 요건이 없고 언제나 부기로 한다(법 제52조제1호)."},{"번호":5,"판정":"옳음","설명":"환매특약등기는 부기로 한다(법 제52조제6호, 제53조)."}],"개념":[{"종류":"표","제목":"부기로 하는 등기(법 제52조)","머리":["호","대상","예시","승낙 필요 여부"],"행":[["제1호","등기명의인표시의 변경·경정","주소·성명 변경","불요"],["제2호","소유권 외의 권리의 이전","지상권·전세권·저당권의 이전","불요"],["제3호","소유권 외의 권리를 목적으로 하는 권리","전세권 위의 저당권설정, 전전세","불요"],["제4호","소유권 외의 권리에 대한 처분제한","지상권 위의 가압류","불요"],["제5호","권리의 변경·경정","최고액 증액, 전세금 증액","이해관계인이 있으면 승낙 필요, 없으면 주등기"],["제6호~제8호","환매특약, 권리소멸약정, 공유물 분할금지 약정","환매기간 기록","불요"]]},{"종류":"비교","제목":"부기등기와 주등기","왼쪽":{"이름":"부기등기","항목":["소유권 외 권리의 이전·처분제한","승낙을 받은 권리 변경등기","환매특약·권리소멸약정·분할금지 약정","일부 사항만 말소된 등기의 회복(규칙 제118조)","순위는 주등기를 따른다(법 제5조)"]},"오른쪽":{"이름":"주등기","항목":["표제부 등기(표시변경·분필·멸실)","소유권이전등기와 소유권에 대한 처분제한","승낙 없는 권리 변경등기","신탁재산이 고유재산이 된 뜻의 등기(규칙 제143조)","독립한 순위번호를 받는다"]}}],"함정":"선지 2·3·5는 눈에 띄는 변경·이전 형태라 주등기로 착각하기 쉽다. 이 선지들은 승낙과 상관없이 법 제52조 각 호에 따라 부기로 한다. 승낙 요건이 붙는 것은 제5호의 권리 변경·경정뿐이며, 선지 4의 명의인표시 변경은 제1호라서 승낙이 필요 없다."}},{"i":"S3-2-2-공시법-23","r":"S3","g":3,"c":2,"n":23,"s":"공시법","q":"1필의 토지 전부에 대한 지상권설정등기청구권보전 가등기에 의해 지상권설정의 본등기가 행해진 경우 가등기 후 본등기 전에 마쳐진 등기로서 직권말소의 대상이 되는 것은?","b":null,"bs":"없음","img":[],"ch":["저당권설정등기","토지임차권설정등기","체납처분으로 인한 압류등기","가압류 및 가처분 등 처분제한의 등기","소유권이전등기 및 소유권이전등기청구권보전 가등기"],"a":[2],"L":"시2-5","o":"기출","x":{"한줄":"지상권 설정청구권 가등기로 본등기를 하면 같은 부분의 지상권·지역권·전세권·임차권 설정등기만 직권말소한다. 토지임차권설정등기가 여기에 든다.","근거":[{"법령":"부동산등기규칙","조문":"제148조제1항","원문":"등기관이 지상권, 전세권 또는 임차권의 설정등기청구권보전 가등기에 의하여 지상권, 전세권 또는 임차권의 설정의 본등기를 한 경우 가등기 후 본등기 전에 마쳐진 다음 각 호의 등기(동일한 부분에 마쳐진 등기로 한정한다)는 법 제92조제1항에 따라 직권으로 말소한다.\n1. 지상권설정등기\n2. 지역권설정등기\n3. 전세권설정등기\n4. 임차권설정등기"},{"법령":"부동산등기규칙","조문":"제148조제2항","원문":"지상권, 전세권 또는 임차권의 설정등기청구권보전 가등기에 의하여 지상권, 전세권 또는 임차권의 설정의 본등기를 한 경우 가등기 후 본등기 전에 마쳐진 다음 각 호의 등기는 직권말소의 대상이 되지 아니한다.\n1. 소유권이전등기 및 소유권이전등기청구권보전 가등기\n2. 가압류 및 가처분 등 처분제한의 등기\n3. 체납처분으로 인한 압류등기\n4. 저당권설정등기"}],"선지":[{"번호":1,"판정":"틀림","설명":"저당권설정등기는 용익권 본등기와 양립하므로 직권말소 대상이 아니다(규칙 제148조제2항제4호)."},{"번호":2,"판정":"옳음","설명":"임차권설정등기는 같은 토지 전부에 마쳐진 지상권과 양립할 수 없는 용익권이라 직권말소한다(규칙 제148조제1항제4호)."},{"번호":3,"판정":"틀림","설명":"체납처분으로 인한 압류등기는 직권말소 대상이 아니다(규칙 제148조제2항제3호)."},{"번호":4,"판정":"틀림","설명":"가압류·가처분 등 처분제한의 등기는 남는다(규칙 제148조제2항제2호)."},{"번호":5,"판정":"틀림","설명":"소유권이전등기와 소유권이전등기청구권보전 가등기는 남는다(규칙 제148조제2항제1호)."}],"개념":[{"종류":"표","제목":"가등기 종류별 본등기 뒤 직권말소 범위","머리":["가등기의 종류","직권말소하는 것","직권말소하지 않는 것","근거"],"행":[["소유권이전청구권 가등기","가등기 뒤 본등기 전에 마쳐진 등기 중 예외를 뺀 전부","가등기상 권리 목적의 가압류·가처분, 가등기 전 가압류의 강제경매개시결정, 가등기 전 담보가등기·전세권·저당권의 임의경매개시결정, 대항력 있는 주택임차권등기등","규칙 제147조제1항"],["소유권이전청구권 가등기 중 체납처분 압류","직권말소대상통지 후 이의신청이 있으면 예규에 따라 결정","이의신청이 없는 경우의 처리는 예규에 따름","규칙 제147조제2항"],["지상권·전세권·임차권 설정청구권 가등기","동일한 부분의 지상권·지역권·전세권·임차권 설정등기, 대항력 없는 주택임차권등기등","소유권이전과 그 가등기, 가압류·가처분, 체납처분 압류, 저당권설정, 가등기 안 된 부분의 용익권","규칙 제148조제1·2항"],["저당권설정청구권 가등기","없음","가등기 후 본등기 전의 등기 전부","규칙 제148조제3항"]]},{"종류":"비교","제목":"소유권 가등기와 용익권 가등기의 본등기","왼쪽":{"이름":"소유권이전청구권 가등기","항목":["중간 등기를 거의 전부 직권말소","가압류·가처분은 가등기상 권리를 목적으로 한 것만 남는다","저당권설정등기는 말소 대상","규칙 제147조"]},"오른쪽":{"이름":"지상권·전세권·임차권 설정청구권 가등기","항목":["같은 부분의 용익권 설정등기만 말소","가압류·가처분 등 처분제한은 남는다","저당권설정등기는 남는다","규칙 제148조"]}}],"함정":"선지 1을 고르기 쉽다. 소유권이전청구권 가등기의 본등기에서는 중간의 저당권이 말소되지만, 용익권 가등기에서는 저당권이 남는다. 직권말소는 가등기로 보전하는 권리와 양립하지 못하는 같은 부분의 용익권에 한정된다."}},{"i":"S3-2-2-공시법-24","r":"S3","g":3,"c":2,"n":24,"s":"공시법","q":"가등기에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["가등기권리자는 가등기를 명하는 법원의 가처분명령이 있는 경우에는 단독으로 가등기를 신청할 수 있다.","근저당권 채권최고액의 변경등기청구권을 보전하기 위해 가등기를 할 수 있다.","가등기를 한 후 본등기의 신청이 있을 때에는 가등기의 순위번호를 사용하여 본등기를 하여야 한다.","임차권설정등기청구권보전 가등기에 의한 본등기를 한 경우 가등기 후 본등기 전에 마쳐진 저당권설정등기는 직권말소의 대상이 아니다.","등기관이 소유권이전등기청구권보전 가등기에 의한 본등기를 한 경우, 가등기 후 본등기 전에 마쳐진 해당 가등기상 권리를 목적으로 하는 가처분등기는 직권으로 말소한다."],"a":[5],"L":"시2-5","o":"기출","x":{"한줄":"소유권이전청구권 가등기로 본등기를 해도 그 가등기상 권리를 목적으로 하는 가처분등기는 직권말소 대상에서 빠진다.","근거":[{"법령":"부동산등기규칙","조문":"제147조제1항제1호","원문":"등기관이 소유권이전등기청구권보전 가등기에 의하여 소유권이전의 본등기를 한 경우에는 법 제92조제1항에 따라 가등기 후 본등기 전에 마쳐진 등기 중 다음 각 호의 등기를 제외하고는 모두 직권으로 말소한다.\n1. 해당 가등기상 권리를 목적으로 하는 가압류등기나 가처분등기"},{"법령":"부동산등기법","조문":"제89조","원문":"가등기권리자는 제23조제1항에도 불구하고 가등기의무자의 승낙이 있거나 가등기를 명하는 법원의 가처분명령(假處分命令)이 있을 때에는 단독으로 가등기를 신청할 수 있다."},{"법령":"부동산등기법","조문":"제88조","원문":"가등기는 제3조 각 호의 어느 하나에 해당하는 권리의 설정, 이전, 변경 또는 소멸의 청구권(請求權)을 보전(保全)하려는 때에 한다."},{"법령":"부동산등기규칙","조문":"제146조","원문":"가등기를 한 후 본등기의 신청이 있을 때에는 가등기의 순위번호를 사용하여 본등기를 하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"가등기를 명하는 가처분명령이 있으면 가등기권리자 단독으로 신청한다(법 제89조, 규칙 제145조제2항)."},{"번호":2,"판정":"옳음","설명":"저당권은 법 제3조의 권리이고, 그 변경 청구권도 가등기 대상이다(법 제88조)."},{"번호":3,"판정":"옳음","설명":"본등기는 가등기의 순위번호를 쓴다(규칙 제146조). 본등기의 순위는 가등기 순위에 따른다(법 제91조)."},{"번호":4,"판정":"옳음","설명":"저당권설정등기는 용익권 가등기의 본등기에서 직권말소 대상이 아니다(규칙 제148조제2항제4호)."},{"번호":5,"판정":"틀림","설명":"해당 가등기상 권리를 목적으로 하는 가압류·가처분등기는 직권말소하지 않는다(규칙 제147조제1항제1호)."}],"개념":[{"종류":"표","제목":"가등기의 대상·신청·본등기·말소","머리":["항목","내용","근거"],"행":[["대상","법 제3조 권리의 설정·이전·변경·소멸 청구권. 시기부·정지조건부·장래 확정될 청구권 포함","법 제88조"],["신청","공동신청이 원칙. 의무자의 승낙이나 가처분명령이 있으면 권리자 단독","법 제89조, 규칙 제145조제2항"],["가처분명령","부동산 소재지 관할 지방법원이 권리자 신청과 소명으로 한다. 각하결정에는 즉시항고","법 제90조"],["본등기 방식","가등기의 순위번호를 사용, 순위는 가등기 순위","규칙 제146조, 법 제91조"],["가등기 말소","명의인은 단독. 의무자·이해관계인은 명의인의 승낙을 받아 단독","법 제93조"]]},{"종류":"흐름","제목":"가등기에 의한 본등기와 직권말소","단계":[{"이름":"본등기 신청","설명":"가등기 명의인이 본등기를 신청한다."},{"이름":"본등기","설명":"가등기의 순위번호를 사용해 한다(규칙 제146조, 법 제91조)."},{"이름":"직권말소 대상 판단","설명":"가등기 종류별로 규칙 제147조·제148조에 따라 가등기 후 본등기 전에 마쳐진 등기를 가린다(법 제92조제1항)."},{"이름":"직권말소와 기록","설명":"본등기로 인하여 말소한다는 뜻을 기록한다(규칙 제149조)."},{"이름":"통지","설명":"말소된 권리의 등기명의인에게 지체 없이 통지한다(법 제92조제2항)."}]}],"함정":"선지 5가 소유권이전청구권 가등기의 본등기에서는 중간 등기를 거의 다 지운다는 원칙과 맞아 보인다. 그러나 예외 4가지 가운데 첫째가 가등기상 권리를 목적으로 하는 가압류·가처분등기다. 선지 4는 용익권 가등기에서는 저당권이 남는다는 점을 기억하면 풀린다."}},{"i":"S3-2-2-세법-01","r":"S3","g":3,"c":2,"n":25,"s":"세법","q":"국세 및 지방세의 연대납세의무에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["공동주택의 공유물에 관계되는 지방자치단체의 징수금은 공유자가 연대하여 납부할 의무를 진다.","공동으로 소유한 자산에 대한 양도소득금액을 계산하는 경우에는 해당 자산을 공동으로 소유하는 공유자가 그 양도소득세를 연대하여 납부할 의무를 진다.","공동사업에 관한 소득금액을 계산하는 경우(주된 공동사업자에게 합산과세되는 경우 제외)에는 해당 공동사업자가 그 종합소득세를 연대하여 납부할 의무를 진다.","상속으로 인하여 단독주택을 상속인이 공동으로 취득하는 경우에는 상속인 각자가 상속받는 취득물건을 취득한 것으로 보고, 공동상속인이 그 취득세를 연대하여 납부할 의무를 진다.","어느 연대납세의무자에 대하여 소멸시효가 완성된 때에도 다른 연대납세의무자의 납세의무에는 영향을 미치지 아니한다."],"a":[4],"L":"세1-1","o":"기출","x":{"한줄":"상속으로 취득세 과세물건을 공동상속인이 취득하면 상속인 각자가 자기 지분을 취득한 것으로 보되, 그 취득세는 공동상속인이 연대하여 납부한다.","근거":[{"법령":"지방세법","조문":"제7조제7항","원문":"⑦ 상속(피상속인이 상속인에게 한 유증 및 포괄유증과 신탁재산의 상속을 포함한다. 이하 이 장과 제3장에서 같다)으로 인하여 취득하는 경우에는 상속인 각자가 상속받는 취득물건(지분을 취득하는 경우에는 그 지분에 해당하는 취득물건을 말한다)을 취득한 것으로 본다. 이 경우 상속인의 납부의무에 관하여는 「지방세기본법」 제44조제1항 및 제5항을 준용한다."},{"법령":"지방세기본법","조문":"제44조제1항","원문":"① 공유물(공동주택의 공유물은 제외한다), 공동사업 또는 그 공동사업에 속하는 재산에 관계되는 지방자치단체의 징수금은 공유자 또는 공동사업자가 연대하여 납부할 의무를 진다."},{"법령":"소득세법","조문":"제2조의2제1항","원문":"① 제43조에 따라 공동사업에 관한 소득금액을 계산하는 경우에는 해당 공동사업자별로 납세의무를 진다. 다만, 제43조제3항에 따른 주된 공동사업자(이하 이 항에서 \"주된 공동사업자\"라 한다)에게 합산과세되는 경우 그 합산과세되는 소득금액에 대해서는 주된 공동사업자의 특수관계인은 같은 조 제2항에 따른 손익분배비율에 해당하는 그의 소득금액을 한도로 주된 공동사업자와 연대하여 납세의무를 진다."},{"법령":"소득세법","조문":"제2조의2제5항","원문":"⑤ 공동으로 소유한 자산에 대한 양도소득금액을 계산하는 경우에는 해당 자산을 공동으로 소유하는 각 거주자가 납세의무를 진다."},{"법령":"민법","조문":"제421조","원문":"제421조(소멸시효의 절대적 효력) 어느 연대채무자에 대하여 소멸시효가 완성한 때에는 그 부담부분에 한하여 다른 연대채무자도 의무를 면한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"공유물에 관계되는 지방자치단체의 징수금은 공유자가 연대하여 납부한다. 다만 공동주택의 공유물은 연대납세 대상에서 뺀다(지방세기본법 제44조제1항)."},{"번호":2,"판정":"틀림","설명":"공동으로 소유한 자산의 양도소득세는 공유자 각자가 자기 몫의 납세의무를 진다. 연대하지 않는다(소득세법 제2조의2제5항)."},{"번호":3,"판정":"틀림","설명":"공동사업의 소득금액은 공동사업자별로 납세의무를 진다. 연대는 주된 공동사업자에게 합산과세되는 경우에 특수관계인이 손익분배비율에 해당하는 소득금액을 한도로 지는 것뿐이다(소득세법 제2조의2제1항)."},{"번호":4,"판정":"옳음","설명":"상속 취득은 상속인 각자가 지분만큼 취득한 것으로 보고, 납부의무는 지방세기본법 제44조제1항·제5항을 준용해 공동상속인이 연대한다(지방세법 제7조제7항)."},{"번호":5,"판정":"틀림","설명":"어느 연대납세의무자에 대해 소멸시효가 완성되면 그 부담부분에 한하여 다른 연대납세의무자도 의무를 면한다(민법 제421조, 국세기본법 제25조의2, 지방세기본법 제44조제5항 준용)."}],"개념":[{"종류":"표","제목":"연대납세의무가 생기는 경우와 각자 납세의무를 지는 경우","머리":["구분","납세의무","근거"],"행":[["공유물·공동사업·공동사업 재산에 관계되는 지방세 징수금","공유자·공동사업자 연대","지방세기본법 제44조제1항"],["공동주택의 공유물","연대 아님(제외)","지방세기본법 제44조제1항 괄호"],["공유물·공동사업 관계 국세 및 강제징수비","공유자·공동사업자 연대","국세기본법 제25조제1항"],["공동상속인의 취득세","공동상속인 연대","지방세법 제7조제7항"],["과점주주의 간주취득 취득세","과점주주 연대(지방세기본법 제44조 준용)","지방세법 제7조제5항"],["공동 소유 자산의 양도소득세","공유자 각자(연대 아님)","소득세법 제2조의2제5항"],["공동사업의 종합소득세","공동사업자별 각자","소득세법 제2조의2제1항"],["주된 공동사업자에게 합산과세되는 소득","특수관계인은 손익분배비율 소득금액 한도로 연대","소득세법 제2조의2제1항 단서"],["증여자가 직접 양도한 것으로 보는 양도소득","증여자와 수증자 연대","소득세법 제2조의2제3항"]]},{"종류":"표","제목":"연대납세의무에 준용하는 민법 규정(국세기본법 제25조의2, 지방세기본법 제44조제5항)","머리":["민법 조문","내용","효력"],"행":[["제413조·제414조","연대채무의 내용, 각 연대채무자에 대한 이행청구","채권자는 어느 연대채무자에게든 전부·일부 청구"],["제415조","한 사람에게 생긴 무효·취소","다른 연대채무자에 영향 없음"],["제416조","이행청구","다른 연대채무자에게도 효력"],["제419조","면제","그 채무자의 부담부분에 한하여 다른 연대채무자 이익"],["제421조","소멸시효 완성","그 부담부분에 한하여 다른 연대채무자도 의무를 면함"],["제423조","효력의 상대성","위 사항 외에는 다른 연대채무자에게 효력 없음"],["제425조~제427조","구상권","출재채무자의 구상, 통지, 무자력자의 부담부분 분담"]]}],"함정":"1번은 공유물이면 모두 연대한다고 외우면 속는다. 지방세기본법 제44조제1항 괄호에서 공동주택의 공유물이 빠진다. 2번과 3번은 소득세가 공유·공동사업을 각자 납세의무로 규정한다는 점을 놓친 선지다. 소득세에서 연대가 나오는 대표적인 경우는 주된 공동사업자 합산과세와 증여자 직접 양도 간주(제101조제2항)다. 5번은 소멸시효 완성이 부담부분 범위에서 다른 연대납세의무자에게도 미치는데 전혀 영향이 없다고 쓴 선지다."}},{"i":"S3-2-2-세법-02","r":"S3","g":3,"c":2,"n":26,"s":"세법","q":"지방세법령상 취득세에 관한 설명으로 옳은 것을 모두 고른 것은?","b":"ㄱ. 취득이란 매매, 교환 등 유상의 취득을 말하며 기부는 제외한다.\nㄴ. 건축물 중 조작 설비, 그 밖의 부대설비에 속하는 부분으로서 그 주체구조부와 하나가 되어 건축물로서의 효용가치를 이루고 있는 것에 대하여는 주체구조부 취득자 외의 자가 가설한 경우에도 주체구조부의 취득자가 함께 취득한 것으로 본다.\nㄷ. 토지의 지목을 사실상 변경함으로써 그 가액이 증가하거나 감소한 경우에는 취득으로 본다.\nㄹ. 피상속인이 상속인에게 한 유증은 상속으로 인하여 취득하는 경우에 포함되지 않으므로 상속인 각자가 상속받는 취득물건을 취득한 것으로 보지 않는다.\nㅁ. 「주택법」 제11조에 따른 주택조합이 해당 조합원용으로 취득하는 조합주택용 부동산 중에서 공동주택 부대시설·복리시설은 조합원에게 귀속되는 부동산이라 하더라도 그 조합원이 취득한 것으로 보지 않는다.","bs":"글자","img":[],"ch":["ㄴ","ㄱ, ㅁ","ㄴ, ㅁ","ㄷ, ㄹ","ㄷ, ㄹ, ㅁ"],"a":[1],"L":"세2-1","o":"기출","x":{"한줄":"옳은 것은 ㄴ뿐이다. 조작 설비·부대설비는 주체구조부와 한 몸이 되면 주체구조부 취득자가 함께 취득한 것으로 본다.","근거":[{"법령":"지방세법","조문":"제6조제1호","원문":"1. \"취득\"이란 매매, 교환, 상속, 증여, 기부, 법인에 대한 현물출자, 건축, 개수(改修), 공유수면의 매립, 간척에 의한 토지의 조성 등과 그 밖에 이와 유사한 취득으로서 원시취득(수용재결로 취득한 경우 등 과세대상이 이미 존재하는 상태에서 취득하는 경우는 제외한다), 승계취득 또는 유상ㆍ무상의 모든 취득을 말한다."},{"법령":"지방세법","조문":"제7조제3항","원문":"③ 건축물 중 조작(造作) 설비, 그 밖의 부대설비에 속하는 부분으로서 그 주체구조부(主體構造部)와 하나가 되어 건축물로서의 효용가치를 이루고 있는 것에 대하여는 주체구조부 취득자 외의 자가 가설(加設)한 경우에도 주체구조부의 취득자가 함께 취득한 것으로 본다."},{"법령":"지방세법","조문":"제7조제4항","원문":"④ 선박, 차량과 기계장비의 종류를 변경하거나 토지의 지목을 사실상 변경함으로써 그 가액이 증가한 경우에는 취득으로 본다. 이 경우 「도시개발법」에 따른 도시개발사업(환지방식만 해당한다)의 시행으로 토지의 지목이 사실상 변경된 때에는 그 환지계획에 따라 공급되는 환지는 조합원이, 체비지 또는 보류지는 사업시행자가 각각 취득한 것으로 본다."},{"법령":"지방세법","조문":"제7조제7항","원문":"⑦ 상속(피상속인이 상속인에게 한 유증 및 포괄유증과 신탁재산의 상속을 포함한다. 이하 이 장과 제3장에서 같다)으로 인하여 취득하는 경우에는 상속인 각자가 상속받는 취득물건(지분을 취득하는 경우에는 그 지분에 해당하는 취득물건을 말한다)을 취득한 것으로 본다. 이 경우 상속인의 납부의무에 관하여는 「지방세기본법」 제44조제1항 및 제5항을 준용한다."},{"법령":"지방세법","조문":"제7조제8항","원문":"⑧ 「주택법」 제11조에 따른 주택조합과 「도시 및 주거환경정비법」 제35조제3항 및 「빈집 및 소규모주택 정비에 관한 특례법」 제23조에 따른 재건축조합 및 소규모재건축조합(이하 이 장에서 \"주택조합등\"이라 한다)이 해당 조합원용으로 취득하는 조합주택용 부동산(공동주택과 부대시설ㆍ복리시설 및 그 부속토지를 말한다)은 그 조합원이 취득한 것으로 본다. 다만, 조합원에게 귀속되지 아니하는 부동산(이하 이 장에서 \"비조합원용 부동산\"이라 한다)은 제외한다."}],"선지":[{"번호":1,"판정":"-","설명":"ㄴ만 옳다. 보기 판정 참조."},{"번호":2,"판정":"-","설명":"ㄱ·ㅁ은 모두 틀린 보기다."},{"번호":3,"판정":"-","설명":"ㅁ이 틀려서 ㄴ, ㅁ 조합은 맞지 않는다."},{"번호":4,"판정":"-","설명":"ㄷ·ㄹ은 모두 틀린 보기다."},{"번호":5,"판정":"-","설명":"ㄷ·ㄹ·ㅁ은 모두 틀린 보기다."}],"보기판정":[{"기호":"ㄱ","판정":"틀림","설명":"취득에는 매매·교환·상속·증여·기부·현물출자·건축·개수 등이 모두 들어간다. 기부도 취득이다(지방세법 제6조제1호)."},{"기호":"ㄴ","판정":"옳음","설명":"조작 설비 등이 주체구조부와 하나가 되어 건축물의 효용가치를 이루면 가설한 자가 따로 있어도 주체구조부 취득자가 함께 취득한 것으로 본다(지방세법 제7조제3항)."},{"기호":"ㄷ","판정":"틀림","설명":"지목을 사실상 변경해 가액이 증가한 경우만 취득으로 본다. 감소한 경우는 해당하지 않는다(지방세법 제7조제4항)."},{"기호":"ㄹ","판정":"틀림","설명":"상속에는 피상속인이 상속인에게 한 유증과 포괄유증, 신탁재산의 상속이 포함된다. 상속인 각자가 지분만큼 취득한 것으로 본다(지방세법 제7조제7항)."},{"기호":"ㅁ","판정":"틀림","설명":"조합주택용 부동산은 공동주택과 부대시설·복리시설 및 부속토지를 말하고 조합원이 취득한 것으로 본다. 조합원에게 귀속되지 않는 비조합원용 부동산만 제외한다(지방세법 제7조제8항)."}],"개념":[{"종류":"표","제목":"취득세 취득 간주 규정(지방세법 제7조)","머리":["대상","취득자·효과","근거"],"행":[["등기·등록을 하지 않은 승계취득","사실상 취득하면 취득한 것, 양수인이 취득자","제7조제2항"],["건축물의 조작 설비·부대설비","주체구조부 취득자가 함께 취득","제7조제3항"],["토지 지목의 사실상 변경(가액 증가)","취득으로 봄. 가액 감소는 해당 없음","제7조제4항"],["과점주주가 된 경우","법인의 부동산등을 취득한 것으로 봄. 설립 시 주식 취득은 제외","제7조제5항"],["상속(유증·포괄유증·신탁재산의 상속 포함)","상속인 각자가 지분만큼 취득, 연대 납부","제7조제7항"],["주택조합등의 조합원용 부동산","조합원이 취득. 비조합원용은 제외","제7조제8항"],["배우자·직계존비속의 부동산등 취득","증여로 취득한 것으로 봄(경매·교환 등 예외)","제7조제11항"],["증여자의 채무를 인수하는 부담부증여","채무액 상당 부분은 유상취득","제7조제12항"]]},{"종류":"비교","제목":"주택조합등 취득 부동산의 취득자","왼쪽":{"이름":"조합원용 부동산","항목":["대상: 조합주택용 부동산(공동주택, 부대시설·복리시설, 그 부속토지)","취득자: 해당 조합원","주택조합등이 취득해도 조합원 취득으로 봄"]},"오른쪽":{"이름":"비조합원용 부동산","항목":["대상: 조합원에게 귀속되지 않는 부동산","취득자: 주택조합등","조합원 취득 간주 규정이 적용되지 않음"]}}],"함정":"ㄱ은 취득을 유상취득으로 좁혀 읽게 만든 보기다. 취득의 정의에는 기부와 증여 같은 무상취득이 들어간다. ㄷ은 가액이 증가한 경우만 취득으로 보는데 감소까지 넣었다. ㄹ은 유증이 상속에 들어가는 규정을 반대로 썼다. ㅁ은 조합원용 부동산의 범위에 부대시설·복리시설이 들어간다는 점을 뒤집은 보기다. ㄴ이 옳다는 것만 잡고 ㅁ까지 옳다고 읽으면 3번으로 간다."}},{"i":"S3-2-2-세법-03","r":"S3","g":3,"c":2,"n":27,"s":"세법","q":"지방세법상 부동산 취득세의 표준세율이 가장 높은 것은? (단, 중과세율·세율 특례·감면과 주택 유상거래 특례는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["농지를 상속으로 취득한 경우","합유물의 분할로 취득한 경우","개인이 농지 외의 토지를 증여로 취득한 경우","건축물을 신축하여 취득한 경우","농지를 매매로 취득한 경우"],"a":[3],"L":"세2-1","o":"변형","x":{"한줄":"상속을 제외한 무상취득의 표준세율은 1천분의 35로, 보기 가운데 가장 높다.","근거":[{"법령":"지방세법","조문":"제11조제1항제1호~제3호","원문":"1. 상속으로 인한 취득 가. 농지: 1천분의 23 나. 농지 외의 것: 1천분의 28 2. 제1호 외의 무상취득: 1천분의 35. 다만, 대통령령으로 정하는 비영리사업자의 취득은 1천분의 28로 한다. 3. 원시취득: 1천분의 28"},{"법령":"지방세법","조문":"제11조제1항제6호·제7호","원문":"6. 합유물 및 총유물의 분할로 인한 취득: 1천분의 23 7. 그 밖의 원인으로 인한 취득 가. 농지: 1천분의 30 나. 농지 외의 것: 1천분의 40"}],"선지":[{"번호":1,"판정":"-","설명":"농지의 상속 취득은 1천분의 23이다(제11조제1항제1호가목)."},{"번호":2,"판정":"-","설명":"합유물·총유물의 분할로 인한 취득은 1천분의 23이다(제11조제1항제6호)."},{"번호":3,"판정":"-","설명":"상속 외의 무상취득은 1천분의 35이다. 비영리사업자의 취득은 1천분의 28로 낮아지지만 개인에게는 해당하지 않는다(제11조제1항제2호)."},{"번호":4,"판정":"-","설명":"신축은 원시취득이므로 1천분의 28이다(제11조제1항제3호)."},{"번호":5,"판정":"-","설명":"매매는 그 밖의 원인에 해당하고 농지는 1천분의 30이다(제11조제1항제7호가목)."}],"개념":[{"종류":"표","제목":"부동산 취득세 표준세율(지방세법 제11조제1항)","머리":["취득 원인","표준세율"],"행":[["상속 - 농지","1천분의 23"],["상속 - 농지 외","1천분의 28"],["상속 외의 무상취득(증여 등)","1천분의 35(대통령령이 정하는 비영리사업자는 1천분의 28)"],["원시취득(신축·재축 등)","1천분의 28"],["공유물의 분할, 부동산 실권리자명의 등기법상 공유권 해소를 위한 지분이전(본인 지분 초과분 제외)","1천분의 23"],["합유물·총유물의 분할","1천분의 23"],["그 밖의 원인(매매·교환 등) - 농지","1천분의 30"],["그 밖의 원인(매매·교환 등) - 농지 외","1천분의 40"],["주택 유상거래 - 취득당시가액 6억원 이하 / 9억원 초과","1천분의 10 / 1천분의 30(6억원 초과 9억원 이하는 계산식 세율)"]]},{"종류":"계산","제목":"과세표준 2억원일 때 원인별 취득세 본세(교육세·농어촌특별세 제외, 가정)","단계":[{"설명":"농지 외 토지를 증여로 취득(개인)","식":"2억원 × 3.5%","값":"700만원"},{"설명":"농지를 매매로 취득","식":"2억원 × 3.0%","값":"600만원"},{"설명":"농지 외 토지를 매매로 취득","식":"2억원 × 4.0%","값":"800만원"},{"설명":"공유물 분할로 본인 지분을 취득(과세표준은 취득 지분의 가액 2억원)","식":"2억원 × 2.3%","값":"460만원"}]}],"함정":"1번과 2번은 1천분의 23이어서 낮은 쪽이다. 5번은 농지 매매 30이고 농지 외 매매 40이라는 숫자를 섞어 3번보다 높다고 읽기 쉽다. 이 문항은 매매가 아니라 증여다. 4번 신축의 1천분의 28은 상속 농지 외와 같은 숫자여서 상속 세율과 헷갈린다. 증여는 상속보다 높은 1천분의 35로 외워 두면 된다."}},{"i":"S3-2-2-세법-04","r":"S3","g":3,"c":2,"n":28,"s":"세법","q":"지방세법령상 취득세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["건축물 중 조작 설비에 속하는 부분으로서 그 주체구조부와 하나가 되어 건축물로서의 효용가치를 이루고 있는 것에 대하여는 주체구조부 취득자 외의 자가 가설한 경우에도 주체구조부의 취득자가 함께 취득한 것으로 본다.","「도시개발법」에 따른 환지방식에 의한 도시개발사업의 시행으로 토지의 지목이 사실상 변경됨으로써 그 가액이 증가한 경우에는 그 환지계획에 따라 공급되는 환지는 사업시행자가, 체비지 또는 보류지는 조합원이 각각 취득한 것으로 본다.","경매를 통하여 배우자의 부동산을 취득하는 경우에는 유상으로 취득한 것으로 본다.","형제자매인 증여자의 채무를 인수하는 부담부증여의 경우에는 그 채무액에 상당하는 부분은 부동산을 유상으로 취득하는 것으로 본다.","부동산의 승계취득은 「민법」 등 관계 법령에 따른 등기를 하지 아니한 경우라도 사실상 취득하면 취득한 것으로 보고 그 부동산의 양수인을 취득자로 한다."],"a":[2],"L":"세2-1","o":"기출","x":{"한줄":"도시개발법상 환지방식 도시개발사업으로 지목이 변경되면 환지는 조합원이, 체비지·보류지는 사업시행자가 취득한 것으로 본다.","근거":[{"법령":"지방세법","조문":"제7조제2항","원문":"② 부동산등의 취득은 「민법」, 「자동차관리법」, 「건설기계관리법」, 「항공안전법」, 「선박법」, 「입목에 관한 법률」, 「광업법」, 「수산업법」 또는 「양식산업발전법」 등 관계 법령에 따른 등기ㆍ등록 등을 하지 아니한 경우라도 사실상 취득하면 각각 취득한 것으로 보고 해당 취득물건의 소유자 또는 양수인을 각각 취득자로 한다. 다만, 차량, 기계장비, 항공기 및 주문을 받아 건조하는 선박은 승계취득인 경우에만 해당한다."},{"법령":"지방세법","조문":"제7조제3항","원문":"③ 건축물 중 조작(造作) 설비, 그 밖의 부대설비에 속하는 부분으로서 그 주체구조부(主體構造部)와 하나가 되어 건축물로서의 효용가치를 이루고 있는 것에 대하여는 주체구조부 취득자 외의 자가 가설(加設)한 경우에도 주체구조부의 취득자가 함께 취득한 것으로 본다."},{"법령":"지방세법","조문":"제7조제4항","원문":"④ 선박, 차량과 기계장비의 종류를 변경하거나 토지의 지목을 사실상 변경함으로써 그 가액이 증가한 경우에는 취득으로 본다. 이 경우 「도시개발법」에 따른 도시개발사업(환지방식만 해당한다)의 시행으로 토지의 지목이 사실상 변경된 때에는 그 환지계획에 따라 공급되는 환지는 조합원이, 체비지 또는 보류지는 사업시행자가 각각 취득한 것으로 본다."},{"법령":"지방세법","조문":"제7조제11항","원문":"⑪ 배우자 또는 직계존비속의 부동산등을 취득하는 경우에는 증여로 취득한 것으로 본다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 그 취득한 부동산등 전체를 유상으로 취득한 것으로 본다. 1. 공매(경매를 포함한다. 이하 같다)를 통하여 부동산등을 취득한 경우"},{"법령":"지방세법","조문":"제7조제12항","원문":"⑫ 증여자의 채무를 인수하는 부담부(負擔附) 증여의 경우에는 그 채무액에 상당하는 부분은 부동산등을 유상으로 취득하는 것으로 본다. 다만, 배우자 또는 직계존비속으로부터의 부동산등의 부담부 증여의 경우에는 제11항을 적용한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"조작 설비·부대설비는 주체구조부와 하나가 되어 효용가치를 이루면 가설한 자와 관계없이 주체구조부 취득자가 함께 취득한다(지방세법 제7조제3항)."},{"번호":2,"판정":"틀림","설명":"환지계획에 따라 공급되는 환지는 조합원이, 체비지 또는 보류지는 사업시행자가 취득한 것으로 본다. 선지는 주체가 서로 바뀌어 있다(지방세법 제7조제4항 후단)."},{"번호":3,"판정":"옳음","설명":"배우자·직계존비속의 부동산 취득은 증여로 보는 것이 원칙이다. 공매(경매 포함)로 취득하면 그 부동산 전체를 유상취득으로 본다(지방세법 제7조제11항제1호)."},{"번호":4,"판정":"옳음","설명":"증여자의 채무를 인수하는 부담부증여는 채무액 상당 부분을 유상취득으로 본다. 배우자·직계존비속 사이의 부담부증여만 제11항으로 넘어가는데 형제자매는 해당하지 않는다(지방세법 제7조제12항)."},{"번호":5,"판정":"옳음","설명":"승계취득은 등기를 하지 않아도 사실상 취득하면 취득이고 양수인이 취득자다(지방세법 제7조제2항)."}],"개념":[{"종류":"표","제목":"배우자·직계존비속의 부동산등 취득과 부담부증여(지방세법 제7조제11항·제12항)","머리":["상황","취득세상 성격"],"행":[["배우자·직계존비속의 부동산등을 취득(원칙)","증여로 취득한 것으로 봄"],["공매(경매 포함)를 통한 취득","그 부동산등 전체를 유상취득으로 봄"],["파산선고로 처분되는 부동산등의 취득","유상취득으로 봄"],["등기·등록이 필요한 부동산등을 서로 교환","유상취득으로 봄"],["대가 지급 사실이 소득·재산처분·기과세 재산 등으로 증명됨","유상취득으로 봄(시가인정액과의 차액이 3억원 이상이거나 시가인정액의 100분의 30 이상인 범위에서 대통령령으로 정하는 경우는 제외)"],["증여자의 채무를 인수하는 부담부증여(배우자·직계존비속 외)","채무액 상당 부분은 유상취득, 나머지는 증여"],["배우자·직계존비속으로부터 받는 부담부증여","제11항 적용(원칙적으로 증여)"]]},{"종류":"비교","제목":"지목 변경 취득과 환지·관리처분계획 공급 취득","왼쪽":{"이름":"토지 지목 사실상 변경(제7조제4항)","항목":["도시개발사업(환지방식)으로 지목이 변경되어 가액 증가","환지: 조합원이 취득","체비지·보류지: 사업시행자가 취득"]},"오른쪽":{"이름":"환지계획·관리처분계획에 따른 공급(제7조제16항)","항목":["대상: 도시개발사업·정비사업의 대상 부동산 소유자(상속인 포함)","건축물: 소유자가 원시취득","토지: 소유자가 승계취득하되 당초 면적을 초과한 부분만 취득"]}}],"함정":"2번은 환지와 체비지·보류지의 취득 주체를 거꾸로 쓴 선지다. 환지는 소유자인 조합원 몫이고 체비지·보류지는 사업비용을 충당하는 땅이라 사업시행자 몫이라고 연결하면 된다. 3번은 배우자 사이라 증여로 보는 원칙만 떠올리면 틀려 보이지만 경매는 유상취득 예외다. 4번은 증여자가 형제자매라서 제11항 적용 대상이 아니다."}},{"i":"S3-2-2-세법-05","r":"S3","g":3,"c":2,"n":29,"s":"세법","q":"지방세법상 부동산 등기에 대한 등록면허세에 관한 설명으로 옳은 것은? (단, 주어진 조건 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["상속으로 인한 소유권이전등기의 세율은 부동산 가액의 1천분의 15이다.","소유권 보존등기의 세율은 부동산 가액의 1천분의 20이다.","임차권 설정등기의 세율은 연 임대차금액의 1천분의 2이다.","「지방세법」 제11조제1항제8호에 따른 세율을 적용받는 주택이 아닌 부동산의 유상 소유권이전등기 세율은 부동산 가액의 1천분의 20이다.","등록 신고의무를 다하지 아니한 경우에는 등록을 하기 전까지 산출세액을 납부하였더라도 무신고가산세가 부과된다."],"a":[4],"L":"세2-2","o":"변형","x":{"한줄":"주택 유상거래 특례 대상이 아닌 부동산의 유상 소유권이전등기는 부동산 가액의 1천분의 20이다.","근거":[{"법령":"지방세법","조문":"제28조제1항제1호","원문":"가. 소유권의 보존 등기: 부동산 가액의 1천분의 8 1) 유상으로 인한 소유권 이전 등기: 부동산 가액의 1천분의 20. 다만, 제11조제1항제8호에 따른 세율을 적용받는 주택의 경우에는 해당 주택의 취득세율에 100분의 50을 곱한 세율을 적용하여 산출한 금액을 그 세액으로 한다. 2) 무상으로 인한 소유권 이전 등기: 부동산 가액의 1천분의 15. 다만, 상속으로 인한 소유권 이전 등기의 경우에는 부동산 가액의 1천분의 8로 한다. 5) 임차권: 월 임대차금액의 1천분의 2."},{"법령":"지방세법","조문":"제30조제4항","원문":"④ 제1항부터 제3항까지의 규정에 따른 신고의무를 다하지 아니한 경우에도 등록면허세 산출세액을 등록을 하기 전까지(제2항 또는 제3항의 경우에는 해당 항에 따른 신고기한까지) 납부하였을 때에는 제1항부터 제3항까지의 규정에 따라 신고를 하고 납부한 것으로 본다. 이 경우 제32조에도 불구하고 「지방세기본법」 제53조 및 제54조에 따른 가산세를 부과하지 아니한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"상속으로 인한 소유권이전등기는 부동산 가액의 1천분의 8이다. 1천분의 15는 상속 외 무상 이전등기의 세율이다(지방세법 제28조제1항제1호나목2))."},{"번호":2,"판정":"틀림","설명":"소유권 보존등기는 부동산 가액의 1천분의 8이다. 1천분의 20은 유상 이전등기다(지방세법 제28조제1항제1호가목)."},{"번호":3,"판정":"틀림","설명":"임차권의 세율은 월 임대차금액의 1천분의 2다. 연 단위가 아니다(지방세법 제28조제1항제1호다목5))."},{"번호":4,"판정":"옳음","설명":"유상 소유권이전등기는 부동산 가액의 1천분의 20이다. 주택 유상거래 특례 대상 주택만 취득세율의 100분의 50을 적용한다(지방세법 제28조제1항제1호나목1))."},{"번호":5,"판정":"틀림","설명":"신고의무를 다하지 않았어도 등록하기 전까지 산출세액을 납부하면 신고·납부한 것으로 보고 지방세기본법 제53조·제54조의 가산세(무신고·과소신고·초과환급신고가산세)를 부과하지 않는다(지방세법 제30조제4항)."}],"개념":[{"종류":"표","제목":"부동산 등기 등록면허세율(지방세법 제28조제1항제1호)","머리":["등기 종류","세율"],"행":[["소유권 보존","부동산 가액의 1천분의 8"],["소유권 이전 - 유상","부동산 가액의 1천분의 20(주택 유상거래 특례 대상 주택은 해당 주택 취득세율의 100분의 50)"],["소유권 이전 - 무상","부동산 가액의 1천분의 15(상속은 1천분의 8)"],["지상권","부동산 가액의 1천분의 2"],["저당권","채권금액의 1천분의 2"],["지역권","요역지 가액의 1천분의 2"],["전세권","전세금액의 1천분의 2"],["임차권","월 임대차금액의 1천분의 2"],["경매신청·가압류·가처분·가등기","채권금액(가등기는 부동산 가액 또는 채권금액)의 1천분의 2"],["그 밖의 등기, 최저세액","건당 6천원"]]},{"종류":"계산","제목":"부동산 가액 5억원일 때 등기별 세액(조례 가감 및 지방교육세 제외, 가정)","단계":[{"설명":"상가 유상 소유권이전등기","식":"5억원 × 2%","값":"1,000만원"},{"설명":"상속에 의한 소유권이전등기","식":"5억원 × 0.8%","값":"400만원"},{"설명":"소유권 보존등기","식":"5억원 × 0.8%","값":"400만원"},{"설명":"채권금액 3억원의 저당권 설정등기","식":"3억원 × 0.2%","값":"60만원"}]}],"함정":"1번의 1천분의 15는 증여 같은 무상 이전의 세율이고 상속은 1천분의 8로 낮다. 2번은 보존등기와 유상 이전등기의 세율을 바꿔 쓴 선지다. 3번은 임차권이 월 임대차금액 기준이라는 점을 연 단위로 바꿨다. 5번은 등록면허세가 등록 전 납부로 신고를 갈음한다는 규정을 놓치면 가산세를 붙이게 된다."}},{"i":"S3-2-2-세법-06","r":"S3","g":3,"c":2,"n":30,"s":"세법","q":"지방세법상 지역자원시설세에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["소방분 지역자원시설세는 건축물 또는 선박의 가액 또는 시가표준액을 과세표준으로 하고, 과세표준이 600만원 이하인 경우 표준세율은 1만분의 4이다.","지방자치단체의 장은 조례로 지역자원시설세의 세율을 표준세율의 100분의 50의 범위에서 가감할 수 있으나, 원자력발전과 화력발전에 대한 세율은 가감할 수 없다.","납세지를 관할하는 지방자치단체에 소방선이 없는 경우 선박은 소방분 지역자원시설세의 과세대상에서 제외된다.","소방분 지역자원시설세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수의 방법으로 부과·징수하고, 납세고지서는 늦어도 납기개시 5일 전까지 발급하여야 한다.","지하자원이 과세대상인 경우 납세지는 지하자원을 채광하는 자의 주소지이다."],"a":[5],"L":"세2-3","o":"변형","x":{"한줄":"지하자원의 납세지는 광업권이 등록된 토지의 소재지이고, 채광하는 자의 주소지가 아니다.","근거":[{"법령":"지방세법","조문":"제142조제2항제3호","원문":"3. 소방분 지역자원시설세: 소방시설로 인하여 이익을 받는 자의 건축물(주택의 건축물 부분을 포함한다. 이하 이 장에서 같다) 및 선박(납세지를 관할하는 지방자치단체에 소방선이 없는 경우는 제외한다. 이하 이 장에서 같다)"},{"법령":"지방세법","조문":"제144조제1항제1호다목","원문":"1. 특정자원분 지역자원시설세: 다음 각 목의 납세지 다. 지하자원: 광업권이 등록된 토지의 소재지. 다만, 광업권이 등록된 토지가 둘 이상의 지방자치단체에 걸쳐 있는 경우에는 광업권이 등록된 토지의 면적에 따라 안분한다."},{"법령":"지방세법","조문":"제146조제3항제1호","원문":"③ 소방분 지역자원시설세의 과세표준과 표준세율은 다음 각 호에서 정하는 바에 따른다. 1. 건축물 또는 선박의 가액 또는 시가표준액을 과세표준으로 하여 다음 표의 표준세율을 적용하여 산출한 금액을 세액으로 한다."},{"법령":"지방세법","조문":"제146조제5항","원문":"⑤ 지방자치단체의 장은 조례로 정하는 바에 따라 지역자원시설세의 세율을 제1항부터 제3항까지의 규정에 따른 표준세율의 100분의 50의 범위에서 가감할 수 있다. 다만, 제2항제2호 및 제3호는 세율을 가감할 수 없다."},{"법령":"지방세법","조문":"제147조제3항·제4항","원문":"③ 소방분 지역자원시설세는 관할 지방자치단체의 장이 세액을 산정하여 보통징수의 방법으로 부과ㆍ징수한다. ④ 소방분 지역자원시설세를 징수하려면 건축물 또는 선박으로 구분한 납세고지서에 과세표준과 세액을 적어 늦어도 납기개시 5일 전까지 발급하여야 한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"소방분의 표준세율은 과세표준 600만원 이하 구간이 1만분의 4다(지방세법 제146조제3항제1호)."},{"번호":2,"판정":"옳음","설명":"조례로 표준세율의 100분의 50 범위에서 가감할 수 있다. 특정시설분 중 원자력발전(제2항제2호)과 화력발전(제2항제3호)은 가감할 수 없다(지방세법 제146조제5항)."},{"번호":3,"판정":"옳음","설명":"소방분의 과세대상 선박에서 납세지를 관할하는 지방자치단체에 소방선이 없는 경우는 제외한다(지방세법 제142조제2항제3호)."},{"번호":4,"판정":"옳음","설명":"소방분은 지방자치단체의 장이 세액을 산정해 보통징수하고, 건축물·선박으로 구분한 납세고지서를 늦어도 납기개시 5일 전까지 발급한다(지방세법 제147조제3항·제4항)."},{"번호":5,"판정":"틀림","설명":"지하자원의 납세지는 광업권이 등록된 토지의 소재지다. 토지가 둘 이상의 지방자치단체에 걸치면 면적에 따라 안분한다(지방세법 제144조제1항제1호다목)."}],"개념":[{"종류":"표","제목":"지역자원시설세의 구분별 납세의무자·납세지·표준세율","머리":["구분","납세의무자","납세지","표준세율"],"행":[["발전용수(특정자원분)","흐르는 물로 직접 수력발전(양수발전 제외)을 하는 자","발전소 소재지","발전에 이용된 물 10세제곱미터당 2원"],["지하수(특정자원분)","지하수를 이용하려고 채수하는 자","채수공 소재지","먹는 물 세제곱미터당 200원, 온천 목욕용수 100원, 그 밖 20원"],["지하자원(특정자원분)","지하자원을 채광하는 자","광업권이 등록된 토지 소재지(둘 이상이면 면적 안분)","채광된 광물가액의 1천분의 5"],["컨테이너(특정시설분)","컨테이너 부두를 이용해 입항·출항시키는 자","부두 소재지","컨테이너 티이유당 1만5천원"],["원자력발전(특정시설분)","원자력을 이용해 발전하는 자","발전소 소재지","발전량 킬로와트시당 1원"],["화력발전(특정시설분)","연료를 연소하여 발전하는 자","발전소 소재지","킬로와트시당 0.7원(액화천연가스는 0.6원)"],["폐기물(특정시설분)","폐기물매립시설에 매립하려고 배출하는 자","폐기물매립시설 소재지","매립량 톤당 6천원"],["소방분","건축물 또는 선박에 대한 재산세 납세의무자","건축물은 소재지, 선박은 선적항 소재지","과세표준 600만원 이하 1만분의 4 등 6단계 누진"]]},{"종류":"계산","제목":"소방분 지역자원시설세 산출 예(가정: 과세표준 2,000만원)","단계":[{"설명":"과세표준 1,300만원 초과 2,600만원 이하 구간은 5,900원에 1,300만원 초과금액의 1만분의 6을 더한다","식":"5,900원 + (2,000만원 − 1,300만원) × 6/10,000","값":"5,900원 + 4,200원 = 10,100원"},{"설명":"4층 이상 10층 이하 건축물 등 화재위험 건축물은 산출금액의 100분의 200","식":"10,100원 × 200%","값":"20,200원"},{"설명":"대형마트·백화점·11층 이상 건축물 등 대형 화재위험 건축물은 산출금액의 100분의 300","식":"10,100원 × 300%","값":"30,300원"}]}],"함정":"5번은 특정자원분의 납세의무자(채광하는 자)와 납세지를 같은 곳으로 묶어 주소지라고 쓴 선지다. 납세지는 광업권 등록 토지, 발전용수는 발전소, 지하수는 채수공 소재지로 대상 물건이 있는 곳이다. 2번은 가감 범위 100분의 50만 알고 원자력·화력 제외 단서를 모르면 틀린 선지로 보인다. 3번도 소방선 유무가 선박에만 걸린다는 점을 놓치기 쉽다.","개정":"옛 기출이 묻던 오물처리시설·수리시설 충당분 규정은 지방세법 제146조제1항 제4호~제6호가 삭제(2019.12.31)되어 현행 문항에서 빠졌다. 현행 제142조~제144조는 특정자원분·특정시설분·소방분으로 나뉘며 해당 조문에 <개정 2025.12.31> 표시가 있다. 소방분 과세대상은 건축물과 선박이다(제142조제2항제3호)."}},{"i":"S3-2-2-세법-07","r":"S3","g":3,"c":2,"n":31,"s":"세법","q":"지방세법령상 재산세 징수에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["지방자치단체의 장은 재산세 납부세액이 1천만원을 초과하는 경우 납세의무자의 신청을 받아 해당 지방자치단체의 관할구역에 있는 부동산에 대하여만 대통령령으로 정하는 바에 따라 물납을 허가할 수 있다.","지방자치단체의 장은 재산세 납부세액이 250만원을 초과하는 경우 대통령령으로 정하는 바에 따라 납부할 세액의 일부를 납부기한이 지난 날부터 3개월 이내에 분할납부하게 할 수 있다.","「지방세법」 제118조의2에 따른 주택 재산세의 납부유예를 신청한 납세의무자는 그 유예할 주택 재산세에 상당하는 담보를 제공하여야 한다.","고지서 1장당 재산세로 징수할 세액이 2천원 미만인 경우 해당 재산세를 징수하지 아니한다.","신탁재산의 수탁자는 신탁 설정일 전에 법정기일이 도래한 위탁자의 재산세에 대하여 그 신탁재산으로써 납부할 의무가 있다."],"a":[5],"L":"세2-3","o":"기출","x":{"한줄":"수탁자의 물적납세의무는 신탁 설정일 이후에 법정기일이 도래하는 재산세에 대한 것이고, 설정일 전에 도래한 재산세는 대상이 아니다.","근거":[{"법령":"지방세법","조문":"제117조","원문":"제117조(물납) 지방자치단체의 장은 재산세의 납부세액이 1천만원을 초과하는 경우에는 납세의무자의 신청을 받아 해당 지방자치단체의 관할구역에 있는 부동산에 대하여만 대통령령으로 정하는 바에 따라 물납을 허가할 수 있다."},{"법령":"지방세법","조문":"제118조","원문":"제118조(분할납부) 지방자치단체의 장은 재산세의 납부세액이 250만원을 초과하는 경우에는 대통령령으로 정하는 바에 따라 납부할 세액의 일부를 납부기한이 지난 날부터 3개월 이내에 분할납부하게 할 수 있다."},{"법령":"지방세법","조문":"제118조의2제1항","원문":"① 지방자치단체의 장은 다음 각 호의 요건을 모두 충족하는 납세의무자가 제111조의2에 따른 1세대 1주택(제4조제1항에 따른 시가표준액이 9억원을 초과하는 주택을 포함한다)의 재산세액(해당 재산세를 징수하기 위하여 함께 부과하는 지방세를 포함하며, 이하 이 조에서 \"주택 재산세\"라 한다)의 납부유예를 그 납부기한 만료 3일 전까지 신청하는 경우 이를 허가할 수 있다. 이 경우 납부유예를 신청한 납세의무자는 그 유예할 주택 재산세에 상당하는 담보를 제공하여야 한다."},{"법령":"지방세법","조문":"제119조","원문":"제119조(소액 징수면제) 고지서 1장당 재산세로 징수할 세액이 2천원 미만인 경우에는 해당 재산세를 징수하지 아니한다."},{"법령":"지방세법","조문":"제119조의2제1항","원문":"① 신탁재산의 위탁자가 다음 각 호의 어느 하나에 해당하는 재산세ㆍ납부지연가산세 또는 체납처분비(이하 이 조에서 \"재산세등\"이라 한다)를 체납한 경우로서 그 위탁자의 다른 재산에 대하여 체납처분을 하여도 징수할 금액에 미치지 못할 때에는 해당 신탁재산의 수탁자는 그 신탁재산(해당 신탁재산의 관리, 처분, 운용 또는 개발 등을 통하여 수탁자가 얻은 재산으로서 「신탁법」 제27조에 따라 신탁재산에 속하는 재산을 포함한다. 이하 제5항 및 제6항에서 같다)으로써 위탁자의 재산세등을 납부할 의무가 있다. 1. 신탁 설정일 이후에 「지방세기본법」 제71조제1항에 따른 법정기일이 도래하는 재산세 또는 납부지연가산세(재산세에 대한 납부지연가산세으로 한정한다)으로서 해당 신탁재산과 관련하여 발생한 것. 다만, 제113조제1항제1호 및 제2호에 따라 신탁재산과 다른 토지를 합산하여 과세하는 경우에는 신탁재산과 관련하여 발생한 재산세 등을 제4조에 따른 신탁재산과 다른 토지의 시가표준액 비율로 안분계산한 부분 중 신탁재산 부분에 한정한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"납부세액이 1천만원을 초과하면 신청에 따라 물납을 허가할 수 있고, 해당 지방자치단체 관할구역의 부동산에 한한다(지방세법 제117조)."},{"번호":2,"판정":"옳음","설명":"납부세액이 250만원을 초과하면 납부기한이 지난 날부터 3개월 이내에 나누어 내게 할 수 있다(지방세법 제118조)."},{"번호":3,"판정":"옳음","설명":"납부유예를 신청한 납세의무자는 유예할 주택 재산세에 상당하는 담보를 제공해야 한다(지방세법 제118조의2제1항)."},{"번호":4,"판정":"옳음","설명":"고지서 1장당 재산세액이 2천원 미만이면 징수하지 않는다(지방세법 제119조)."},{"번호":5,"판정":"틀림","설명":"수탁자가 신탁재산으로 납부할 의무는 위탁자가 체납하고 위탁자의 다른 재산에 체납처분을 해도 부족한 경우, 신탁 설정일 이후에 법정기일이 도래하는 해당 신탁재산 관련 재산세에 한한다(지방세법 제119조의2제1항제1호)."}],"개념":[{"종류":"표","제목":"재산세 납부·징수 관련 수치(지방세법 제117조~제122조)","머리":["제도","요건·한도","근거"],"행":[["물납","납부세액 1천만원 초과, 납세의무자 신청, 관할구역 안 부동산에 한함","제117조"],["분할납부","납부세액 250만원 초과, 납부기한이 지난 날부터 3개월 이내","제118조"],["납부유예","1세대 1주택자 등 요건 충족, 납부기한 만료 3일 전까지 신청, 담보 제공","제118조의2"],["소액 징수면제","고지서 1장당 재산세 2천원 미만","제119조"],["세부담 상한","직전 연도 상당액의 100분의 150(주택은 적용 제외)","제122조"],["수탁자 물적납세의무","위탁자 체납 + 위탁자 다른 재산으로 부족 + 신탁 설정일 이후 법정기일 도래분","제119조의2"]]},{"종류":"흐름","제목":"주택 재산세 납부유예 절차(지방세법 제118조의2)","단계":[{"이름":"신청","설명":"납부기한 만료 3일 전까지 신청하고 유예할 재산세에 상당하는 담보를 제공한다. 과세기준일 현재 1세대 1주택 소유자, 만 60세 이상 또는 5년 이상 보유, 직전 과세기간 총급여액 7천만원 이하 또는 종합소득금액 6천만원 이하, 납부세액 100만원 초과, 지방세·국세 체납 없음."},{"이름":"허가 여부 통지","설명":"지방자치단체의 장이 납부기한 만료일까지 납세의무자에게 허가 여부를 통지한다."},{"이름":"유예 기간","설명":"허가한 날부터 징수할 세액의 고지일까지 납부지연가산세를 부과하지 않는다."},{"이름":"허가 취소","설명":"주택 양도·증여, 사망으로 상속 개시, 1세대 1주택 요건 상실, 담보 보전 명령 불응, 징수 곤란, 유예세액을 납부하려는 경우에는 취소해야 하고 납세의무자에게 즉시 통지한다."},{"이름":"징수","설명":"유예받은 세액과 이자상당가산액을 징수한다. 상속인은 상속으로 받은 재산의 한도에서 납부한다."}]}],"함정":"5번은 신탁 설정일 전과 후를 바꾼 선지다. 신탁 설정 전에 이미 법정기일이 지난 위탁자의 재산세까지 신탁재산이 떠안지는 않는다. 위탁자 체납과 다른 재산 부족이라는 요건도 같이 따라붙는다. 1번 물납과 2번 분할납부는 1천만원과 250만원을 바꿔 쓰는 숫자 함정으로 자주 나온다."}},{"i":"S3-2-2-세법-08","r":"S3","g":3,"c":2,"n":32,"s":"세법","q":"지방세법상 재산세에 관한 설명으로 틀린 것은? (단, 주어진 조건 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["재산세 과세기준일 현재 공부상에 개인 등의 명의로 등재되어 있는 사실상의 종중재산으로서 종중소유임을 신고하지 아니하였을 때에는 공부상 소유자는 재산세를 납부할 의무가 있다.","지방자치단체가 1년 이상 공용으로 사용하는 재산에 대하여는 소유권의 유상이전을 약정한 경우로서 그 재산을 취득하기 전에 미리 사용하는 경우 재산세를 부과하지 아니한다.","재산세 과세기준일 현재 소유권의 귀속이 분명하지 아니하여 사실상의 소유자를 확인할 수 없는 경우에는 그 사용자가 재산세를 납부할 의무가 있다.","재산세의 납기는 토지의 경우 매년 9월 16일부터 9월 30일까지이며, 건축물의 경우 매년 7월 16일부터 7월 31일까지이다.","재산세의 납기에도 불구하고 지방자치단체의 장은 과세대상 누락, 위법 또는 착오 등으로 인하여 이미 부과한 세액을 변경하거나 수시부과하여야 할 사유가 발생하면 수시로 부과ㆍ징수할 수 있다."],"a":[2],"L":"세2-3","o":"기출","x":{"한줄":"1년 이상 공용으로 쓰는 재산이라도 소유권 유상이전을 약정하고 취득 전에 미리 사용하는 경우에는 재산세를 부과한다.","근거":[{"법령":"지방세법","조문":"제107조제2항제3호","원문":"② 제1항에도 불구하고 재산세 과세기준일 현재 다음 각 호의 어느 하나에 해당하는 자는 재산세를 납부할 의무가 있다. 3. 공부상에 개인 등의 명의로 등재되어 있는 사실상의 종중재산으로서 종중소유임을 신고하지 아니하였을 때에는 공부상 소유자"},{"법령":"지방세법","조문":"제107조제3항","원문":"③ 재산세 과세기준일 현재 소유권의 귀속이 분명하지 아니하여 사실상의 소유자를 확인할 수 없는 경우에는 그 사용자가 재산세를 납부할 의무가 있다."},{"법령":"지방세법","조문":"제109조제2항","원문":"② 국가, 지방자치단체 또는 지방자치단체조합이 1년 이상 공용 또는 공공용으로 사용(1년 이상 사용할 것이 계약서 등에 의하여 입증되는 경우를 포함한다)하는 재산에 대하여는 재산세를 부과하지 아니한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 재산세를 부과한다. 1. 유료로 사용하는 경우 2. 소유권의 유상이전을 약정한 경우로서 그 재산을 취득하기 전에 미리 사용하는 경우"},{"법령":"지방세법","조문":"제115조제1항","원문":"① 재산세의 납기는 다음 각 호와 같다. 1. 토지: 매년 9월 16일부터 9월 30일까지 2. 건축물: 매년 7월 16일부터 7월 31일까지"},{"법령":"지방세법","조문":"제115조제2항","원문":"② 제1항에도 불구하고 지방자치단체의 장은 과세대상 누락, 위법 또는 착오 등으로 인하여 이미 부과한 세액을 변경하거나 수시부과하여야 할 사유가 발생하면 수시로 부과ㆍ징수할 수 있다."}],"선지":[{"번호":1,"판정":"옳음","설명":"종중소유임을 신고하지 않은 사실상 종중재산은 공부상 소유자가 납세의무자다(지방세법 제107조제2항제3호)."},{"번호":2,"판정":"틀림","설명":"국가·지방자치단체가 1년 이상 공용 또는 공공용으로 사용하는 재산은 재산세를 부과하지 않는다. 유료 사용과 소유권 유상이전 약정 후 취득 전 사용은 예외로 과세한다(지방세법 제109조제2항제2호)."},{"번호":3,"판정":"옳음","설명":"소유권 귀속이 분명하지 않아 사실상 소유자를 확인할 수 없으면 사용자가 납세의무자다(지방세법 제107조제3항)."},{"번호":4,"판정":"옳음","설명":"토지는 9월 16일~9월 30일, 건축물은 7월 16일~7월 31일이다(지방세법 제115조제1항제1호·제2호)."},{"번호":5,"판정":"옳음","설명":"과세대상 누락, 위법 또는 착오 등으로 부과세액을 변경하거나 수시부과할 사유가 생기면 납기와 관계없이 수시로 부과·징수할 수 있다(지방세법 제115조제2항)."}],"개념":[{"종류":"표","제목":"재산세 납세의무자 특례(과세기준일 6월 1일 현재, 지방세법 제107조)","머리":["상황","납세의무자"],"행":[["원칙","재산을 사실상 소유하고 있는 자"],["공유재산","지분권자(지분 표시가 없으면 균등한 것으로 봄)"],["주택의 건물과 부속토지 소유자가 다른 경우","산출세액을 시가표준액 비율로 안분해 각 소유자"],["소유권 변동 미신고로 사실상 소유자를 알 수 없음","공부상 소유자"],["상속등기 미이행 + 사실상 소유자 미신고","행정안전부령으로 정하는 주된 상속자"],["공부상 개인 명의의 종중재산 + 종중소유 미신고","공부상 소유자"],["국가·지방자치단체와 연부 매매계약 + 무상 사용권","매수계약자"],["수탁자 명의로 등기·등록된 신탁재산","위탁자(위탁자가 소유한 것으로 봄)"],["환지방식 도시개발·재개발사업의 체비지·보류지","사업시행자"],["소유권 귀속 불분명으로 소유자 확인 불가","사용자"]]},{"종류":"표","제목":"재산세 납기(지방세법 제115조)","머리":["과세대상","납기"],"행":[["토지","9월 16일부터 9월 30일까지"],["건축물","7월 16일부터 7월 31일까지"],["주택","세액의 2분의 1은 7월 16일~7월 31일, 나머지는 9월 16일~9월 30일(부과세액 20만원 이하는 조례로 7월에 한꺼번에 부과 가능)"],["선박","7월 16일부터 7월 31일까지"],["항공기","7월 16일부터 7월 31일까지"],["과세대상 누락·착오 등","수시로 부과·징수"]]}],"함정":"2번은 1년 이상 공용 사용이면 무조건 비과세라는 암기를 노린 선지다. 비과세의 예외가 유료 사용과 유상이전 약정 후 취득 전 사용 두 가지다. 3번의 사용자 납세의무는 소유자를 확인할 수 없을 때만 적용되고, 공부상 소유자를 알 수 없는 경우(제107조제2항제1호)와 구별해야 한다. 4번은 토지와 건축물의 납기월을 서로 바꾸는 숫자 함정이 자주 나온다."}},{"i":"S3-2-2-세법-09","r":"S3","g":3,"c":2,"n":33,"s":"세법","q":"종합부동산세법령상 주택에 대한 과세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["｢신탁법｣제2조에 따른 수탁자의 명의로 등기된 신탁주택의 경우에는 수탁자가 종합부동산세를 납부할 의무가 있으며, 이 경우 수탁자가 신탁주택을 소유한 것으로 본다.","법인이 2주택을 소유한 경우 종합부동산세의 세율은 1천분의 50을 적용한다.","거주자 甲이 2023년부터 보유한 3주택(주택 수 계산에서 제외되는 주택은 없음) 중 2주택을 2024.6.17.에 양도하고 동시에 소유권이전등기를 한 경우, 甲의 2024년도주택분 종합부동산세액은 3주택 이상을 소유한 경우의세율을 적용하여 계산한다.","신탁주택의 수탁자가 종합부동산세를 체납한 경우 그 수탁자의 다른 재산에 대하여 강제징수하여도 징수할 금액에 미치지 못할 때에는 해당 주택의 위탁자가 종합부동산세를 납부할 의무가 있다.","공동명의 1주택자인 경우 주택에 대한 종합부동산세의 과세표준은 주택의 시가를 합산한 금액에서 11억원을 공제한 금액에 100분의 50을 한도로 공정시장가액비율을 곱한 금액으로 한다."],"a":[3],"L":"세3-1","o":"기출","x":{"한줄":"주택 수는 과세기준일(6월 1일) 현재로 따지므로, 6월 17일에 2주택을 양도해도 그해 종합부동산세는 3주택 이상 세율로 계산한다.","근거":[{"법령":"종합부동산세법","조문":"제3조","원문":"제3조(과세기준일) 종합부동산세의 과세기준일은 「지방세법」 제114조에 따른 재산세의 과세기준일로 한다."},{"법령":"지방세법","조문":"제114조","원문":"제114조(과세기준일) 재산세의 과세기준일은 매년 6월 1일로 한다."},{"법령":"종합부동산세법","조문":"제9조제1항제2호","원문":"① 주택에 대한 종합부동산세는 다음 각 호와 같이 납세의무자가 소유한 주택 수에 따라 과세표준에 해당 세율을 적용하여 계산한 금액을 그 세액(이하 \"주택분 종합부동산세액\"이라 한다)으로 한다. 2. 납세의무자가 3주택 이상을 소유한 경우"},{"법령":"종합부동산세법","조문":"제9조제2항제3호","원문":"② 납세의무자가 법인 또는 법인으로 보는 단체인 경우 제1항에도 불구하고 과세표준에 다음 각 호에 따른 세율을 적용하여 계산한 금액을 주택분 종합부동산세액으로 한다. 3. 제1호 및 제2호 외의 경우: 다음 각 목에 따른 세율 가. 2주택 이하를 소유한 경우: 1천분의 27 나. 3주택 이상을 소유한 경우: 1천분의 50"},{"법령":"종합부동산세법","조문":"제7조제2항","원문":"② 「신탁법」 제2조에 따른 수탁자(이하 \"수탁자\"라 한다)의 명의로 등기 또는 등록된 신탁재산으로서 주택(이하 \"신탁주택\"이라 한다)의 경우에는 제1항에도 불구하고 같은 조에 따른 위탁자[「주택법」 제2조제11호가목에 따른 지역주택조합, 같은 호 나목에 따른 직장주택조합 등 위탁자별로 구분 과세가 곤란한 조합으로서 대통령령으로 정하는 조합(이하 \"지역주택조합등\"이라 한다)이 조합원이 납부한 금전으로 매수하여 소유하고 있는 신탁주택의 경우에는 해당 지역주택조합등을 말한다. 이하 \"위탁자\"라 한다]가 종합부동산세를 납부할 의무가 있다. 이 경우 위탁자가 신탁주택을 소유한 것으로 본다."},{"법령":"종합부동산세법","조문":"제7조의2","원문":"제7조의2(신탁주택 관련 수탁자의 물적납세의무) 신탁주택의 위탁자가 다음 각 호의 어느 하나에 해당하는 종합부동산세 또는 강제징수비(이하 \"종합부동산세등\"이라 한다)를 체납한 경우로서 그 위탁자의 다른 재산에 대하여 강제징수를 하여도 징수할 금액에 미치지 못할 때에는 해당 신탁주택의 수탁자는 그 신탁주택(해당 신탁주택의 관리, 처분, 운용 또는 개발 등을 통하여 수탁자가 얻은 재산으로서 「신탁법」 제27조에 따라 신탁재산에 속하는 재산을 포함한다)으로써 위탁자의 종합부동산세등을 납부할 의무가 있다."},{"법령":"종합부동산세법","조문":"제8조제1항","원문":"① 주택에 대한 종합부동산세의 과세표준은 납세의무자별로 주택의 공시가격을 합산한 금액에서 다음 각 호의 금액을 공제한 금액에 부동산 시장의 동향과 재정 여건 등을 고려하여 100분의 60부터 100분의 100까지의 범위에서 대통령령으로 정하는 공정시장가액비율을 곱한 금액으로 한다. 다만, 그 금액이 영보다 작은 경우에는 영으로 본다. 1. 대통령령으로 정하는 1세대 1주택자(이하 \"1세대 1주택자\"라 한다): 12억원 2. 제9조제2항제3호 각 목의 세율이 적용되는 법인 또는 법인으로 보는 단체: 0원 3. 제1호 및 제2호에 해당하지 아니하는 자: 9억원"},{"법령":"종합부동산세법 시행령","조문":"제2조의4제1항","원문":"① 법 제8조제1항 각 호 외의 부분 본문에서 \"대통령령으로 정하는 공정시장가액비율\"이란 100분의 60을 말하되, 2019년부터 2021년까지 납세의무가 성립하는 종합부동산세에 대해서는 다음 각 호의 연도별 비율을 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"수탁자 명의 신탁주택은 위탁자가 종합부동산세를 납부할 의무가 있고 위탁자가 소유한 것으로 본다(종합부동산세법 제7조제2항)."},{"번호":2,"판정":"틀림","설명":"법인의 세율은 2주택 이하가 1천분의 27, 3주택 이상이 1천분의 50이다. 2주택이면 1천분의 27이다(종합부동산세법 제9조제2항제3호)."},{"번호":3,"판정":"옳음","설명":"종합부동산세의 과세기준일은 재산세 과세기준일(6월 1일)이다. 6월 17일 양도분도 그해 주택 수에 포함되어 3주택 이상 세율(제9조제1항제2호)을 적용한다(종합부동산세법 제3조, 지방세법 제114조)."},{"번호":4,"판정":"틀림","설명":"납세의무자가 위탁자이고, 위탁자가 체납한 경우에 위탁자의 다른 재산으로 부족하면 수탁자가 신탁주택으로써 납부한다. 선지는 수탁자와 위탁자가 거꾸로 되어 있다(종합부동산세법 제7조의2)."},{"번호":5,"판정":"틀림","설명":"과세표준은 시가가 아니라 공시가격을 합산한 금액에서 공제금액(1세대 1주택자 12억원, 일반 9억원)을 빼고 공정시장가액비율을 곱한다. 비율은 100분의 60부터 100까지 범위에서 대통령령으로 정하며 현재 100분의 60이다. 공동명의 1주택자는 신청하면 1세대 1주택자로 본다(종합부동산세법 제8조제1항, 제10조의2제3항, 같은 법 시행령 제2조의4제1항)."}],"개념":[{"종류":"표","제목":"주택분 종합부동산세 공제금액과 세율 구분","머리":["납세의무자","공제금액","세율·기준"],"행":[["개인 - 2주택 이하","9억원","1천분의 5 ~ 1천분의 27(7단계)"],["개인 - 3주택 이상","9억원","1천분의 5 ~ 1천분의 50(7단계)"],["1세대 1주택자","12억원","2주택 이하 세율 적용 후 연령·보유기간 공제(합계 100분의 80 한도)"],["공동명의 1주택자(9월 16일~9월 30일 신청)","12억원","1세대 1주택자로 보아 계산(제10조의2)"],["법인(공익법인등 제외)","0원","2주택 이하 1천분의 27, 3주택 이상 1천분의 50"],["신탁주택","위탁자 기준","위탁자가 납세의무자, 위탁자 체납 시 수탁자 물적납세의무"],["주택 수·세율 구간 판단 시점","해당 없음","과세기준일(6월 1일) 현재 소유 주택 수. 6월 17일 양도분도 그해 주택 수에 포함"]]},{"종류":"계산","제목":"개인 납세의무자 공시가격 합계 34억원, 주택분 종합부동산세 산출(재산세 공제 전, 가정)","단계":[{"설명":"과세표준 = (공시가격 합계 − 공제금액) × 공정시장가액비율","식":"(34억원 − 9억원) × 60%","값":"15억원"},{"설명":"3주택 이상: 12억원 초과 25억원 이하 구간 960만원 + 12억원 초과금액의 1천분의 20","식":"960만원 + (15억원 − 12억원) × 2%","값":"1,560만원"},{"설명":"2주택 이하: 12억원 초과 25억원 이하 구간 960만원 + 12억원 초과금액의 1천분의 13","식":"960만원 + (15억원 − 12억원) × 1.3%","값":"1,350만원"}]}],"함정":"3번의 6월 17일 양도는 과세기준일 6월 1일 이후다. 양도로 2주택이 줄어든 것처럼 보이지만 그해 세율을 정하는 주택 수는 6월 1일 현재로 센다. 1번과 4번은 위탁자와 수탁자의 역할을 바꾼 쌍이다. 납세의무자는 위탁자이고 수탁자는 보충적으로 신탁주택으로 책임진다. 5번은 11억원이라는 공제금액 자체가 현행 규정에 없고 시가가 아니라 공시가격을 합산한다."}},{"i":"S3-2-2-세법-10","r":"S3","g":3,"c":2,"n":34,"s":"세법","q":"종합부동산세법령상 토지에 대한 과세에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["토지분 재산세의 납세의무자로서 종합합산과세대상 토지의 공시가격을 합한 금액이 5억원인 자는 종합부동산세를 납부할 의무가 있다.","토지분 재산세의 납세의무자로서 별도합산과세대상 토지의 공시가격을 합한 금액이 80억원인 자는 종합부동산세를 납부할 의무가 있다.","토지에 대한 종합부동산세는 종합합산과세대상, 별도합산과세대상 그리고 분리과세대상으로 구분하여 과세한다.","종합합산과세대상인 토지에 대한 종합부동산세의 과세표준은 해당 토지의 공시가격을 합산한 금액에서 5억원을 공제한 금액에 100분의 50을 한도로 공정시장가액비율을 곱한 금액으로 한다.","별도합산과세대상인 토지의 과세표준 금액에 대하여 해당 과세대상 토지의 토지분 재산세로 부과된 세액(｢지방세법｣에 따라 가감조정된 세율이 적용된 경우에는 그 세율이 적용된 세액, 같은 법에 따라 세부담 상한을 적용받은 경우에는 그 상한을 적용받은 세액을 말한다)은 토지분 별도합산세액에서 이를 공제한다."],"a":[5],"L":"세3-1","o":"기출","x":{"한줄":"별도합산과세대상 토지의 재산세로 부과된 세액은 가감조정세율·세부담 상한을 반영한 금액 그대로 토지분 별도합산세액에서 공제한다.","근거":[{"법령":"종합부동산세법","조문":"제11조","원문":"제11조(과세방법) 토지에 대한 종합부동산세는 국내에 소재하는 토지에 대하여 「지방세법」 제106조제1항제1호에 따른 종합합산과세대상(이하 \"종합합산과세대상\"이라 한다)과 같은 법 제106조제1항제2호에 따른 별도합산과세대상(이하 \"별도합산과세대상\"이라 한다)으로 구분하여 과세한다."},{"법령":"종합부동산세법","조문":"제12조제1항","원문":"①과세기준일 현재 토지분 재산세의 납세의무자로서 다음 각호의 어느 하나에 해당하는 자는 해당 토지에 대한 종합부동산세를 납부할 의무가 있다. 1. 종합합산과세대상인 경우에는 국내에 소재하는 해당 과세대상토지의 공시가격을 합한 금액이 5억원을 초과하는 자 2. 별도합산과세대상인 경우에는 국내에 소재하는 해당 과세대상토지의 공시가격을 합한 금액이 80억원을 초과하는 자"},{"법령":"종합부동산세법","조문":"제13조제1항","원문":"① 종합합산과세대상인 토지에 대한 종합부동산세의 과세표준은 납세의무자별로 해당 과세대상토지의 공시가격을 합산한 금액에서 5억원을 공제한 금액에 부동산 시장의 동향과 재정 여건 등을 고려하여 100분의 60부터 100분의 100까지의 범위에서 대통령령으로 정하는 공정시장가액비율을 곱한 금액으로 한다."},{"법령":"종합부동산세법","조문":"제14조제6항","원문":"⑥별도합산과세대상인 토지의 과세표준 금액에 대하여 해당 과세대상 토지의 토지분 재산세로 부과된 세액(「지방세법」 제111조제3항에 따라 가감조정된 세율이 적용된 경우에는 그 세율이 적용된 세액, 같은 법 제122조에 따라 세부담 상한을 적용받은 경우에는 그 상한을 적용받은 세액을 말한다)은 토지분 별도합산세액에서 이를 공제한다."},{"법령":"종합부동산세법 시행령","조문":"제2조의4제2항","원문":"② 법 제13조제1항 및 제2항에서 \"대통령령으로 정하는 공정시장가액비율\"이란 100분의 100을 말하되, 2019년부터 2021년까지 납세의무가 성립하는 종합부동산세에 대해서는 다음 각 호의 연도별 비율을 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"종합합산과세대상 토지는 공시가격 합계가 5억원을 초과하는 자만 납세의무가 있다. 5억원이면 해당하지 않는다(종합부동산세법 제12조제1항제1호)."},{"번호":2,"판정":"틀림","설명":"별도합산과세대상 토지는 공시가격 합계가 80억원을 초과하는 자만 납세의무가 있다. 80억원이면 해당하지 않는다(종합부동산세법 제12조제1항제2호)."},{"번호":3,"판정":"틀림","설명":"토지분은 종합합산과세대상과 별도합산과세대상으로 구분해 과세한다. 분리과세대상은 종합부동산세를 과세하지 않는다(종합부동산세법 제11조)."},{"번호":4,"판정":"틀림","설명":"공제금액 5억원은 맞지만 공정시장가액비율은 100분의 60부터 100까지의 범위에서 대통령령으로 정하며 현재 100분의 100이다. 100분의 50 한도라는 규정은 없다(종합부동산세법 제13조제1항, 같은 법 시행령 제2조의4제2항)."},{"번호":5,"판정":"옳음","설명":"가감조정된 세율이나 세부담 상한이 적용된 재산세액을 그대로 토지분 별도합산세액에서 공제한다(종합부동산세법 제14조제6항)."}],"개념":[{"종류":"표","제목":"토지분 종합부동산세 비교","머리":["구분","종합합산과세대상","별도합산과세대상"],"행":[["납세의무자","공시가격 합계 5억원 초과","공시가격 합계 80억원 초과"],["공제금액","5억원","80억원"],["공정시장가액비율","100분의 60~100 범위, 현재 100분의 100","100분의 60~100 범위, 현재 100분의 100"],["세율","15억원 이하 1천분의 10, 15억원 초과 45억원 이하 1천500만원+15억원 초과분의 1천분의 20, 45억원 초과 7천500만원+45억원 초과분의 1천분의 30","200억원 이하 1천분의 5, 200억원 초과 400억원 이하 1억원+200억원 초과분의 1천분의 6, 400억원 초과 2억2천만원+400억원 초과분의 1천분의 7"],["재산세 공제","토지분 재산세로 부과된 세액을 토지분 종합합산세액에서 공제","토지분 재산세로 부과된 세액을 토지분 별도합산세액에서 공제"],["분리과세대상","종합부동산세 과세대상 아님","종합부동산세 과세대상 아님"],["신탁토지","위탁자가 납세의무자","위탁자가 납세의무자"]]},{"종류":"계산","제목":"토지분 종합부동산세 산출 예(재산세 공제 전, 가정)","단계":[{"설명":"종합합산: 공시가격 합계 25억원의 과세표준","식":"(25억원 − 5억원) × 100%","값":"20억원"},{"설명":"종합합산: 15억원 초과 45억원 이하 구간","식":"1,500만원 + (20억원 − 15억원) × 2%","값":"2,500만원"},{"설명":"별도합산: 공시가격 합계 100억원의 과세표준","식":"(100억원 − 80억원) × 100%","값":"20억원"},{"설명":"별도합산: 200억원 이하 구간","식":"20억원 × 0.5%","값":"1,000만원"}]}],"함정":"1번과 2번은 5억원과 80억원이 하한이라 '이상'으로 읽는 숫자 함정이다. 법은 초과를 요건으로 한다. 3번은 종합부동산세가 토지를 세 갈래로 나눠 과세한다고 착각하게 만든 선지다. 분리과세대상은 재산세만 낸다. 4번은 공정시장가액비율 범위를 100분의 50 한도로 바꿔 놓았다."}},{"i":"S3-2-2-세법-11","r":"S3","g":3,"c":2,"n":35,"s":"세법","q":"거주자 甲은 2015년 3월 1일 8천만원에 취득한 국내 소재 X토지를 2026년 6월 10일 동생 乙에게 부담부증여하였다. X토지는 양도소득세 과세대상이고, 증여 당시 시가는 3억원이다. X토지에는 甲의 금융기관 차입금 1억2천만원에 대한 근저당권이 설정되어 있고 乙이 이를 인수한 사실은 채무부담계약서로 확인되었다. 다음 설명 중 옳은 것은? (단, 취득가액 외의 필요경비는 없고 주어진 조건 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["乙이 인수한 채무 1억2천만원에 해당하는 부분은 증여에 해당하므로 양도소득세 과세대상이 아니다.","양도로 보는 부분의 양도가액은 3억원이다.","양도로 보는 부분의 취득가액은 3천2백만원이다.","甲의 양도소득세 예정신고기한은 2026년 8월 31일이다.","甲이 X토지와 함께 양도소득세 과세대상이 아닌 Y자산(증여가액 1억원)도 乙에게 부담부증여하고 乙이 총채무 1억2천만원을 인수하였다면, X토지에 대한 양도로 보는 채무액은 1억2천만원이다."],"a":[3],"L":"세3-2","o":"변형","x":{"한줄":"양도로 보는 부분의 취득가액은 취득가액에 채무액÷증여가액을 곱한 금액이므로 8천만원 × 1억2천만원 ÷ 3억원 = 3천2백만원이다.","근거":[{"법령":"소득세법","조문":"제88조제1호","원문":"1. \"양도\"란 자산에 대한 등기 또는 등록과 관계없이 매도, 교환, 법인에 대한 현물출자 등을 통하여 그 자산을 유상으로 사실상 이전하는 것을 말한다. 이 경우 대통령령으로 정하는 부담부증여 시 수증자가 부담하는 채무액에 해당하는 부분은 양도로 보며, 다음 각 목의 어느 하나에 해당하는 경우에는 양도로 보지 아니한다."},{"법령":"소득세법 시행령","조문":"제151조제3항","원문":"③ 법 제88조제1호 각 목 외의 부분 후단에서 \"대통령령으로 정하는 부담부증여 시 수증자가 부담하는 채무액에 해당하는 부분\"이란 부담부증여 시 증여자의 채무를 수증자(受贈者)가 인수하는 경우 증여가액 중 그 채무액에 해당하는 부분을 말한다. 다만, 배우자 간 또는 직계존비속 간의 부담부증여(「상속세 및 증여세법」 제44조에 따라 증여로 추정되는 경우를 포함한다)로서 같은 법 제47조제3항 본문에 따라 수증자에게 인수되지 아니한 것으로 추정되는 채무액은 제외한다."},{"법령":"소득세법 시행령","조문":"제159조제1항","원문":"① 법 제88조제1호 각 목 외의 부분 후단에 따른 부담부증여의 경우 양도로 보는 부분에 대한 양도차익을 계산할 때 그 취득가액 및 양도가액은 다음 각 호에 따른다. 1. 취득가액: 다음 계산식에 따른 금액 2. 양도가액: 다음 계산식에 따른 금액"},{"법령":"소득세법 시행령","조문":"제159조제2항","원문":"②제1항을 적용할 때 양도소득세 과세대상에 해당하는 자산과 해당하지 아니하는 자산을 함께 부담부증여하는 경우로서 증여자의 채무를 수증자가 인수하는 경우 채무액은 다음 계산식에 따라 계산한다."},{"법령":"소득세법","조문":"제105조제1항제3호","원문":"① 제94조제1항 각 호(같은 항 제3호다목 및 같은 항 제5호는 제외한다)에서 규정하는 자산을 양도한 거주자는 제92조제2항에 따라 계산한 양도소득과세표준을 다음 각 호의 구분에 따른 기간에 대통령령으로 정하는 바에 따라 납세지 관할 세무서장에게 신고하여야 한다. 3. 제1호 및 제2호에도 불구하고 제88조제1호 각 목 외의 부분 후단에 따른 부담부증여의 채무액에 해당하는 부분으로서 양도로 보는 경우에는 그 양도일이 속하는 달의 말일부터 3개월"}],"선지":[{"번호":1,"판정":"틀림","설명":"부담부증여에서 수증자가 인수하는 채무액에 해당하는 부분은 양도로 본다. 동생은 배우자·직계존비속이 아니어서 인수하지 않은 것으로 추정하는 예외도 없다(소득세법 제88조제1호 후단, 같은 법 시행령 제151조제3항)."},{"번호":2,"판정":"틀림","설명":"양도가액은 증여가액에 채무액÷증여가액을 곱한 금액이다. 3억원 × 1억2천만원 ÷ 3억원 = 1억2천만원이다(같은 법 시행령 제159조제1항제2호)."},{"번호":3,"판정":"옳음","설명":"취득가액 8천만원 × 채무액 1억2천만원 ÷ 증여가액 3억원 = 3천2백만원이다(같은 법 시행령 제159조제1항제1호)."},{"번호":4,"판정":"틀림","설명":"양도로 보는 부담부증여의 예정신고기한은 양도일이 속하는 달의 말일부터 3개월이다. 6월 말일부터 3개월은 2026년 9월 30일이다. 8월 31일은 일반 양도의 2개월 기준으로 센 날이다(소득세법 제105조제1항제3호)."},{"번호":5,"판정":"틀림","설명":"과세대상 자산과 과세대상이 아닌 자산을 함께 부담부증여하면 채무액을 자산가액 비율로 나눈다. 1억2천만원 × 3억원 ÷ 4억원 = 9천만원이다(같은 법 시행령 제159조제2항)."}],"개념":[{"종류":"계산","제목":"부담부증여로 양도로 보는 부분의 양도차익(시행령 제159조)","단계":[{"설명":"양도가액 = 증여가액 × 채무액 ÷ 증여가액","식":"3억원 × (1억2천만원 ÷ 3억원)","값":"1억2천만원"},{"설명":"취득가액 = 취득가액 × 채무액 ÷ 증여가액","식":"8천만원 × (1억2천만원 ÷ 3억원)","값":"3천2백만원"},{"설명":"양도차익 = 양도가액 − 취득가액(다른 필요경비 없음)","식":"1억2천만원 − 3천2백만원","값":"8천8백만원"},{"설명":"증여로 보는 부분(양도소득세 대상이 아님)","식":"3억원 − 1억2천만원","값":"1억8천만원"},{"설명":"예정신고기한: 양도일 2026.6.10.이 속하는 달의 말일(6.30.)부터 3개월","식":"6월 30일 + 3개월","값":"2026년 9월 30일"},{"설명":"과세·비과세 자산 병행 시 채무액 안분(선지 5): X 3억원, Y 1억원, 총채무 1억2천만원","식":"1억2천만원 × 3억원 ÷ (3억원 + 1억원)","값":"X토지 채무액 9천만원"}]},{"종류":"표","제목":"부담부증여 양도 판정과 신고","머리":["항목","내용","근거"],"행":[["양도로 보는 범위","증여자의 채무를 수증자가 인수한 경우 그 채무액에 해당하는 부분","소득세법 제88조제1호 후단, 시행령 제151조제3항"],["양도에서 제외","배우자 간·직계존비속 간 부담부증여에서 수증자에게 인수되지 않은 것으로 추정되는 채무액","시행령 제151조제3항 단서"],["양도가액","증여가액(상속세 및 증여세법 평가액) × 채무액 ÷ 증여가액","시행령 제159조제1항제2호"],["취득가액","취득가액 × 채무액 ÷ 증여가액","시행령 제159조제1항제1호"],["과세·비과세 자산 병행","총채무액 × 양도소득세 과세대상 자산가액 ÷ 총 증여 자산가액","시행령 제159조제2항"],["예정신고","양도일이 속하는 달의 말일부터 3개월","소득세법 제105조제1항제3호"],["확정신고","다음 연도 5월 1일~5월 31일","소득세법 제110조제1항"]]}],"함정":"1번은 부담부증여 전체를 증여로 읽은 선지다. 채무를 넘기는 만큼은 유상 이전이라 양도로 본다. 2번은 양도가액에 증여가액 전체를 넣은 것이다. 3번에서 취득가액도 같은 비율로 줄여야 한다는 점을 놓치면 8천만원을 그대로 쓰게 된다. 4번의 2개월은 부담부증여가 아닌 일반 양도의 예정신고기한이다. 5번은 비과세 또는 과세대상이 아닌 자산이 섞이면 채무를 안분한다는 규정을 빼고 계산한 것이다."}},{"i":"S3-2-2-세법-12","r":"S3","g":3,"c":2,"n":36,"s":"세법","q":"거주자 甲은 2016. 10. 20. 취득한 토지(취득가액 1억원, 등기함)를 동생인 거주자 乙(특수관계인임)에게 2019. 10. 1. 증여(시가 3억원, 등기함)하였다. 乙은 해당 토지를 2022. 6. 30. 특수관계가 없는 丙에게 양도(양도가액 10억원)하였다. 양도소득은 乙에게 실질적으로 귀속되지 아니하고, 乙의 증여세와 양도소득세를 합한 세액이 甲이 직접 양도하는 경우로 보아 계산한 양도소득세보다 적은 경우에 해당한다. 소득세법상 양도소득세 납세의무에 관한 설명으로 틀린 것은?","b":null,"bs":"없음","img":[],"ch":["乙이 납부한 증여세는 양도차익 계산 시 필요경비에 산입한다.","양도차익 계산 시 취득가액은 甲의 취득 당시를 기준으로 한다.","양도소득세에 대해서는 甲과 乙이 연대하여 납세의무를 진다.","甲은 양도소득세 납세의무자이다.","양도소득세 계산 시 보유기간은 甲의 취득일부터 乙의 양도일까지의 기간으로 한다."],"a":[1],"L":"세3-2","o":"기출","x":{"한줄":"증여자가 직접 양도한 것으로 보면 당초 증여받은 자산에는 증여세를 부과하지 않으므로, 乙의 증여세를 필요경비에 산입하는 일은 없다.","근거":[{"법령":"소득세법","조문":"제101조제2항","원문":"② 거주자가 제1항에서 규정하는 특수관계인(제97조의2제1항을 적용받는 배우자 및 직계존비속의 경우는 제외한다)에게 자산을 증여한 후 그 자산을 증여받은 자가 그 증여일부터 10년 이내에 다시 타인에게 양도한 경우로서 제1호에 따른 세액이 제2호에 따른 세액보다 적은 경우에는 증여자가 그 자산을 직접 양도한 것으로 본다. 다만, 양도소득이 해당 수증자에게 실질적으로 귀속된 경우에는 그러하지 아니하다. 1. 증여받은 자의 증여세(「상속세 및 증여세법」에 따른 산출세액에서 공제ㆍ감면세액을 뺀 세액을 말한다)와 양도소득세(이 법에 따른 산출세액에서 공제ㆍ감면세액을 뺀 결정세액을 말한다. 이하 제2호에서 같다)를 합한 세액 2. 증여자가 직접 양도하는 경우로 보아 계산한 양도소득세"},{"법령":"소득세법","조문":"제101조제3항","원문":"③ 제2항에 따라 증여자에게 양도소득세가 과세되는 경우에는 당초 증여받은 자산에 대해서는 「상속세 및 증여세법」의 규정에도 불구하고 증여세를 부과하지 아니한다."},{"법령":"소득세법","조문":"제2조의2제3항","원문":"③ 제101조제2항에 따라 증여자가 자산을 직접 양도한 것으로 보는 경우 그 양도소득에 대해서는 증여자와 증여받은 자가 연대하여 납세의무를 진다."},{"법령":"소득세법","조문":"제95조제4항","원문":"④ 제2항에서 규정하는 자산의 보유기간은 그 자산의 취득일부터 양도일까지로 한다. 다만, 제97조의2제1항의 경우에는 증여한 배우자 또는 직계존비속이 해당 자산을 취득한 날부터 기산(起算)하고, 같은 조 제4항제1호에 따른 가업상속공제가 적용된 비율에 해당하는 자산의 경우에는 피상속인이 해당 자산을 취득한 날부터 기산한다."},{"법령":"소득세법","조문":"제97조의2제1항제3호","원문":"① 거주자가 양도일부터 소급하여 10년(제94조제1항제3호에 따른 자산의 경우에는 1년) 이내에 그 배우자(양도 당시 혼인관계가 소멸된 경우를 포함하되, 사망으로 혼인관계가 소멸된 경우는 제외한다. 이하 이 항에서 같다) 또는 직계존비속(양도 당시 사망한 경우는 제외한다. 이하 이 항에서 같다)으로부터 증여받은 제94조제1항제1호 및 제3호에 따른 자산이나 그 밖에 대통령령으로 정하는 자산의 양도차익을 계산할 때 양도가액에서 공제할 필요경비는 제97조제2항에 따르되, 다음 각 호의 기준을 적용한다. 3. 거주자가 해당 자산에 대하여 납부하였거나 납부할 증여세 상당액이 있는 경우 필요경비에 산입한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"증여자에게 양도소득세를 과세하면 당초 증여받은 자산에 증여세를 부과하지 않는다(소득세법 제101조제3항). 증여세 상당액을 필요경비에 넣는 것은 배우자·직계존비속으로부터 증여받은 자산의 이월과세 규정이다(제97조의2제1항제3호)."},{"번호":2,"판정":"옳음","설명":"甲이 그 자산을 직접 양도한 것으로 보므로 취득가액은 甲의 취득 당시 금액 1억원이다(소득세법 제101조제2항)."},{"번호":3,"판정":"옳음","설명":"제101조제2항에 따라 증여자가 직접 양도한 것으로 보는 경우 그 양도소득에 대해 증여자와 수증자가 연대하여 납세의무를 진다(소득세법 제2조의2제3항)."},{"번호":4,"판정":"옳음","설명":"甲이 직접 양도한 것으로 보므로 甲이 양도소득세 납세의무자다(소득세법 제101조제2항)."},{"번호":5,"판정":"옳음","설명":"甲이 직접 양도한 것으로 보므로 보유기간은 甲의 취득일(2016.10.20.)부터 乙의 양도일(2022.6.30.)까지다(소득세법 제95조제4항, 제101조제2항)."}],"개념":[{"종류":"비교","제목":"이월과세와 양도소득의 부당행위계산 부인","왼쪽":{"이름":"이월과세(소득세법 제97조의2)","항목":["증여자: 배우자 또는 직계존비속(양도 당시 사망한 직계존비속은 제외)","기간: 양도일부터 소급해 10년 이내 증여받은 토지·건물 등(주식등 제94조제1항제3호는 1년)","납세의무자: 증여받아 양도한 거주자","취득가액: 증여자가 취득할 당시 금액","증여세 상당액: 필요경비에 산입","보유기간: 증여자가 취득한 날부터 기산"]},"오른쪽":{"이름":"부당행위계산 부인(제101조제2항)","항목":["증여자: 특수관계인(제97조의2제1항 적용 대상 배우자·직계존비속은 제외)","기간: 증여일부터 10년 이내 수증자가 타인에게 양도","요건: 증여세+양도소득세 합계가 증여자 직접 양도 시 양도소득세보다 적고, 양도소득이 수증자에게 실질 귀속되지 않음","효과: 증여자가 직접 양도한 것으로 보아 증여자·수증자가 연대납세","증여세: 부과하지 않음(제101조제3항)"]}},{"종류":"계산","제목":"乙의 양도로 보지 않고 甲이 직접 양도한 것으로 본 양도차익(다른 필요경비 없음, 가정)","단계":[{"설명":"乙 기준 양도차익이라면(취득가액 증여 시가 3억원)","식":"10억원 − 3억원","값":"7억원"},{"설명":"甲이 직접 양도한 것으로 보면 취득가액은 甲의 취득 당시 1억원","식":"10억원 − 1억원","값":"9억원"},{"설명":"보유기간은 甲 취득일 2016.10.20.부터 양도일 2022.6.30.까지 5년 8개월이므로 5년 이상 6년 미만 구간의 장기보유특별공제율 100분의 10(표 1)","식":"9억원 × 10%","값":"9천만원"},{"설명":"양도소득금액","식":"9억원 − 9천만원","값":"8억1천만원"}]}],"함정":"1번은 이월과세에서 증여세 상당액을 필요경비에 넣는 규정과 섞은 선지다. 부당행위 부인은 증여세를 부과하지 않는 구조라서 필요경비 산입 대상 자체가 없다. 3번의 연대납세는 제2조의2제3항에서 나오고, 4번 납세의무자는 증여자 甲이다. 乙이 형제여서 이월과세(배우자·직계존비속)가 아닌 제101조제2항이 적용된다는 점이 출발점이다.","개정":"현행 제101조제2항은 증여일부터 10년 이내 재양도를 기준으로 하며 2022.12.31. 개정 표시가 붙어 있다. 이 문항은 증여(2019.10.1.)와 양도(2022.6.30.)의 간격이 3년이 안 되어 기간 기준이 5년이든 10년이든 결론이 같다."}},{"i":"S3-2-2-세법-13","r":"S3","g":3,"c":2,"n":37,"s":"세법","q":"소득세법상 거주자의 양도소득과세표준 계산에 관한 설명으로 옳은 것은? (단, 주어진 조건 외에는 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["양도차익을 실지거래가액에 따라 계산하는 경우, 보유기간에 그 자산의 감가상각비로서 사업소득금액 계산상 필요경비에 산입한 금액이 있으면 이를 공제하지 않은 금액을 취득가액으로 한다.","토지의 양도로 발생한 양도차손은 같은 과세기간에 발생한 주식등의 양도소득금액에서 공제할 수 있다.","양도소득 기본공제는 토지·건물의 양도소득금액과 주식등의 양도소득금액을 합산한 금액에서 연 250만원을 공제한다.","양도소득금액에 감면소득금액이 있으면 양도소득 기본공제는 감면소득금액 외의 양도소득금액에서 먼저 공제하고, 감면소득금액 외의 양도소득금액 중에서는 해당 과세기간에 먼저 양도한 자산의 양도소득금액부터 순서대로 공제한다.","미등기양도자산도 보유기간이 3년 이상이면 장기보유 특별공제를 적용받는다."],"a":[4],"L":"세3-2","o":"변형","x":{"한줄":"기본공제는 감면소득금액 외의 양도소득금액에서 먼저 공제하고, 그 안에서도 먼저 양도한 자산의 양도소득금액부터 순서대로 공제한다.","근거":[{"법령":"소득세법","조문":"제103조제1항·제2항","원문":"① 양도소득이 있는 거주자에 대해서는 다음 각 호의 소득별로 해당 과세기간의 양도소득금액에서 각각 연 250만원을 공제한다. 1. 제94조제1항제1호ㆍ제2호 및 제4호에 따른 소득. 다만, 제104조제3항에 따른 미등기양도자산의 양도소득금액에 대해서는 그러하지 아니하다. 2. 제94조제1항제3호에 따른 소득 ② 제1항을 적용할 때 제95조에 따른 양도소득금액에 이 법 또는 「조세특례제한법」이나 그 밖의 법률에 따른 감면소득금액이 있는 경우에는 그 감면소득금액 외의 양도소득금액에서 먼저 공제하고, 감면소득금액 외의 양도소득금액 중에서는 해당 과세기간에 먼저 양도한 자산의 양도소득금액에서부터 순서대로 공제한다."},{"법령":"소득세법","조문":"제97조제3항","원문":"③ 제2항에 따라 필요경비를 계산할 때 양도자산 보유기간에 그 자산에 대한 감가상각비로서 각 과세기간의 사업소득금액을 계산하는 경우 필요경비에 산입하였거나 산입할 금액이 있을 때에는 이를 제1항의 금액에서 공제한 금액을 그 취득가액으로 한다."},{"법령":"소득세법","조문":"제102조제1항·제2항","원문":"① 양도소득금액은 다음 각 호의 소득별로 구분하여 계산한다. 이 경우 소득금액을 계산할 때 발생하는 결손금은 다른 호의 소득금액과 합산하지 아니한다. 1. 제94조제1항제1호ㆍ제2호 및 제4호에 따른 소득 2. 제94조제1항제3호에 따른 소득 ② 제1항에 따라 양도소득금액을 계산할 때 양도차손이 발생한 자산이 있는 경우에는 제1항 각 호별로 해당 자산 외의 다른 자산에서 발생한 양도소득금액에서 그 양도차손을 공제한다. 이 경우 공제방법은 양도소득금액의 세율 등을 고려하여 대통령령으로 정한다."},{"법령":"소득세법","조문":"제95조제2항","원문":"②제1항에서 \"장기보유 특별공제액\"이란 제94조제1항제1호에 따른 자산(제104조제3항에 따른 미등기양도자산과 같은 조 제7항 각 호에 따른 자산은 제외한다)으로서 보유기간이 3년 이상인 것 및 제94조제1항제2호가목에 따른 자산 중 조합원입주권(조합원으로부터 취득한 것은 제외한다)에 대하여 그 자산의 양도차익(조합원입주권을 양도하는 경우에는 「도시 및 주거환경정비법」 제74조에 따른 관리처분계획 인가 및 「빈집 및 소규모주택 정비에 관한 특례법」 제29조에 따른 사업시행계획인가 전 토지분 또는 건물분의 양도차익으로 한정한다)에 다음 표 1에 따른 보유기간별 공제율을 곱하여 계산한 금액을 말한다. 다만, 대통령령으로 정하는 1세대 1주택(이에 딸린 토지를 포함한다)에 해당하는 자산의 경우에는 그 자산의 양도차익에 다음 표 2에 따른 보유기간별 공제율을 곱하여 계산한 금액과 같은 표에 따른 거주기간별 공제율을 곱하여 계산한 금액을 합산한 것을 말한다."}],"선지":[{"번호":1,"판정":"틀림","설명":"감가상각비로 필요경비에 산입한 금액이 있으면 이를 공제한 금액이 취득가액이다. 공제하지 않은 금액이 아니다(소득세법 제97조제3항)."},{"번호":2,"판정":"틀림","설명":"양도소득금액은 토지·건물·부동산에 관한 권리·기타자산(제1호 소득)과 주식등(제2호 소득)으로 구분해 계산하고 결손금은 다른 호의 소득금액과 합산하지 않는다. 양도차손은 같은 호 안의 다른 자산 양도소득금액에서 공제한다(소득세법 제102조제1항·제2항)."},{"번호":3,"판정":"틀림","설명":"기본공제는 소득별로 해당 과세기간의 양도소득금액에서 각각 연 250만원을 공제한다. 토지·건물 소득과 주식등 소득은 따로 공제받는다(소득세법 제103조제1항)."},{"번호":4,"판정":"옳음","설명":"감면소득금액 외의 양도소득금액에서 먼저 공제하고, 그 안에서는 먼저 양도한 자산의 양도소득금액부터 순서대로 공제한다(소득세법 제103조제2항)."},{"번호":5,"판정":"틀림","설명":"미등기양도자산은 장기보유 특별공제 대상에서 제외한다(소득세법 제95조제2항 괄호)."}],"개념":[{"종류":"계산","제목":"양도소득세 산출 순서(등기된 사업용 상가, 단독 양도, 보유 10년 5개월, 가정)","단계":[{"설명":"양도차익 = 양도가액 − 취득가액 − 기타 필요경비(양도가액 8억원, 취득가액 3억원, 자본적지출·양도비 5천만원)","식":"8억원 − 3억원 − 5천만원","값":"4억5천만원"},{"설명":"장기보유 특별공제 = 양도차익 × 보유기간별 공제율(10년 이상 11년 미만 100분의 20, 표 1)","식":"4억5천만원 × 20%","값":"9천만원"},{"설명":"양도소득금액 = 양도차익 − 장기보유 특별공제","식":"4억5천만원 − 9천만원","값":"3억6천만원"},{"설명":"양도소득과세표준 = 양도소득금액 − 양도소득 기본공제","식":"3억6천만원 − 250만원","값":"3억5천750만원"},{"설명":"산출세액: 3억원 초과 5억원 이하 구간(보유 2년 이상 기본세율) 9,406만원 + 3억원 초과금액의 100분의 40","식":"9,406만원 + (3억5천750만원 − 3억원) × 40%","값":"1억1천706만원"}]},{"종류":"표","제목":"양도소득금액 구분 계산과 기본공제 단위(소득세법 제102조·제103조)","머리":["구분","자산","기본공제"],"행":[["제1호 소득","토지·건물(제94조제1항제1호), 부동산에 관한 권리(제2호), 기타자산(제4호)","연 250만원(미등기양도자산의 양도소득금액은 제외)"],["제2호 소득","주식등(제94조제1항제3호)","연 250만원"],["제3호 소득","파생상품등(제94조제1항제5호)","연 250만원"],["제4호 소득","신탁 수익권(제94조제1항제6호)","연 250만원"],["양도차손","각 호 안에서 해당 자산 외의 다른 자산 양도소득금액에서 공제","다른 호의 소득금액과 합산하지 않음"]]}],"함정":"1번은 감가상각비 이중공제를 막는 규정을 거꾸로 쓴 선지다. 필요경비로 이미 뺀 감가상각비는 취득가액에서 빼야 한다. 2번과 3번은 양도소득 전체를 한 덩어리로 보는 착각을 노린다. 토지·건물과 주식등은 별개의 소득 구분이라 차손 통산도 기본공제도 따로 한다. 5번은 보유기간 3년 이상 요건만 보고 미등기 제외 규정을 놓친 선지다."}},{"i":"S3-2-2-세법-14","r":"S3","g":3,"c":2,"n":38,"s":"세법","q":"소득세법령상 거주자의 양도소득과세표준에 적용되는 세율에 관한 내용으로 옳은 것은? (단, 국내소재 자산을 2023년에 양도한 경우로서 주어진 자산 외에 다른 자산은 없으며, 비과세와 감면은 고려하지 않음)","b":null,"bs":"없음","img":[],"ch":["보유기간이 6개월인 등기된 상가건물: 100분의 40","보유기간이 10개월인 「소득세법」에 따른 분양권: 100분의 70","보유기간이 1년 6개월인 등기된 상가건물: 100분의 30","보유기간이 1년 10개월인 「소득세법」에 따른 조합원입주권: 100분의 70","보유기간이 2년 6개월인 「소득세법」에 따른 분양권: 100분의 50"],"a":[2],"L":"세3-2","o":"기출","x":{"한줄":"분양권은 보유기간 1년 미만이면 양도소득과세표준의 100분의 70이다.","근거":[{"법령":"소득세법","조문":"제104조제1항제1호","원문":"1. 제94조제1항제1호ㆍ제2호 및 제4호에 따른 자산 제55조제1항에 따른 세율(분양권의 경우에는 양도소득 과세표준의 100분의 60)"},{"법령":"소득세법","조문":"제104조제1항제2호","원문":"2. 제94조제1항제1호 및 제2호에서 규정하는 자산으로서 그 보유기간이 1년 이상 2년 미만인 것 양도소득 과세표준의 100분의 40[주택(이에 딸린 토지로서 대통령령으로 정하는 토지를 포함한다. 이하 이 항에서 같다), 조합원입주권 및 분양권의 경우에는 100분의 60]"},{"법령":"소득세법","조문":"제104조제1항제3호","원문":"3. 제94조제1항제1호 및 제2호에 따른 자산으로서 그 보유기간이 1년 미만인 것 양도소득 과세표준의 100분의 50(주택, 조합원입주권 및 분양권의 경우에는 100분의 70)"}],"선지":[{"번호":1,"판정":"틀림","설명":"등기된 상가건물을 1년 미만 보유하고 양도하면 100분의 50이다. 100분의 40은 1년 이상 2년 미만 구간이다(소득세법 제104조제1항제3호·제2호)."},{"번호":2,"판정":"옳음","설명":"분양권은 보유기간 1년 미만이면 100분의 70이다(소득세법 제104조제1항제3호)."},{"번호":3,"판정":"틀림","설명":"상가건물을 1년 이상 2년 미만 보유하면 100분의 40이다(소득세법 제104조제1항제2호)."},{"번호":4,"판정":"틀림","설명":"조합원입주권을 1년 이상 2년 미만 보유하고 양도하면 100분의 60이다. 100분의 70은 1년 미만이다(소득세법 제104조제1항제2호)."},{"번호":5,"판정":"틀림","설명":"분양권은 2년 이상 보유해도 100분의 60이다(소득세법 제104조제1항제1호 괄호)."}],"개념":[{"종류":"표","제목":"양도소득세율(소득세법 제104조제1항, 등기된 자산·2023년 양도 기준)","머리":["자산","1년 미만","1년 이상 2년 미만","2년 이상"],"행":[["토지·건물(주택 제외), 부동산에 관한 권리(조합원입주권·분양권 제외)","100분의 50","100분의 40","기본세율(제55조)"],["주택, 조합원입주권","100분의 70","100분의 60","기본세율(제55조)"],["분양권","100분의 70","100분의 60","100분의 60"],["미등기양도자산","100분의 70","100분의 70","100분의 70"],["비사업용 토지","기본세율+100분의 10 세율 적용 세액과 100분의 50 적용 세액 중 큰 세액","기본세율+100분의 10 세율 적용 세액과 100분의 40 적용 세액 중 큰 세액","기본세율+100분의 10(제104조제1항제8호 표)"]]},{"종류":"계산","제목":"양도소득과세표준 2억원일 때 산출세액(가정)","단계":[{"설명":"등기된 상가, 보유 2년 6개월: 1억5천만원 초과 3억원 이하 구간","식":"3,706만원 + (2억원 − 1억5천만원) × 38%","값":"5,606만원"},{"설명":"미등기양도자산","식":"2억원 × 70%","값":"1억4천만원"},{"설명":"분양권, 보유 10개월","식":"2억원 × 70%","값":"1억4천만원"},{"설명":"분양권, 보유 2년 6개월","식":"2억원 × 60%","값":"1억2천만원"},{"설명":"등기된 상가, 보유 6개월","식":"2억원 × 50%","값":"1억원"}]}],"함정":"분양권만 따로 외워야 한다. 상가·토지는 50, 40, 기본세율로 내려가지만 분양권은 70, 60, 60이어서 2년을 넘겨도 기본세율로 내려가지 않는다. 4번은 조합원입주권을 주택과 같은 구간표로 읽어야 하는데 70과 60을 섞은 선지다. 1번과 3번은 상가의 50, 40을 40, 30으로 한 단계씩 낮춰 쓴 숫자 함정이다."}},{"i":"S3-2-2-세법-15","r":"S3","g":3,"c":2,"n":39,"s":"세법","q":"소득세법상 거주자의 양도소득세 징수와 환급에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["과세기간별로 이미 납부한 확정신고세액이 관할세무서장이 결정한 양도소득 총결정세액을 초과한 경우 다른 국세에 충당할 수 없다.","양도소득과세표준과 세액을 결정 또는 경정한 경우 관할세무서장이 결정한 양도소득 총결정세액이 이미 납부한 확정신고세액을 초과할 때에는 그 초과하는 세액을 해당 거주자에게 알린 날부터 30일 이내에 징수한다.","양도소득세 과세대상 건물을 양도한 거주자는 부담부증여의 채무액을 양도로 보는 경우 예정신고 없이 확정신고를 하여야 한다.","양도소득세 납세의무의 확정은 납세의무자의 신고에 의하지 않고 관할세무서장의 결정에 의한다.","이미 납부한 확정신고세액이 관할세무서장이 결정한 양도소득 총결정세액을 초과할 때에는 해당 결정일부터 90일 이내에 환급해야 한다."],"a":[2],"L":"세3-2","o":"기출","x":{"한줄":"결정·경정으로 총결정세액이 기납부세액을 넘으면 그 초과액(추가납부세액)을 거주자에게 알린 날부터 30일 이내에 징수한다.","근거":[{"법령":"소득세법","조문":"제116조제2항","원문":"② 납세지 관할 세무서장은 제114조에 따라 양도소득과세표준과 세액을 결정 또는 경정한 경우 제92조제3항제3호에 따른 양도소득 총결정세액이 다음 각 호의 금액의 합계액을 초과할 때에는 그 초과하는 세액(이하 \"추가납부세액\"이라 한다)을 해당 거주자에게 알린 날부터 30일 이내에 징수한다. 1. 제106조에 따른 예정신고납부세액과 제111조에 따른 확정신고납부세액 2. 제1항에 따라 징수하는 세액 3. 제82조 및 제118조에 따른 수시부과세액 4. 제156조제1항제5호에 따라 원천징수한 세액"},{"법령":"소득세법","조문":"제117조","원문":"제117조(양도소득세의 환급) 납세지 관할 세무서장은 과세기간별로 제116조제2항 각 호의 금액의 합계액이 제92조제3항제3호에 따른 양도소득 총결정세액을 초과할 때에는 그 초과하는 세액을 환급하거나 다른 국세 및 강제징수비에 충당하여야 한다."},{"법령":"소득세법","조문":"제105조제1항제3호","원문":"① 제94조제1항 각 호(같은 항 제3호다목 및 같은 항 제5호는 제외한다)에서 규정하는 자산을 양도한 거주자는 제92조제2항에 따라 계산한 양도소득과세표준을 다음 각 호의 구분에 따른 기간에 대통령령으로 정하는 바에 따라 납세지 관할 세무서장에게 신고하여야 한다. 3. 제1호 및 제2호에도 불구하고 제88조제1호 각 목 외의 부분 후단에 따른 부담부증여의 채무액에 해당하는 부분으로서 양도로 보는 경우에는 그 양도일이 속하는 달의 말일부터 3개월"},{"법령":"국세기본법","조문":"제22조제2항","원문":"② 다음 각 호의 국세는 납세의무자가 과세표준과 세액을 정부에 신고했을 때에 확정된다. 다만, 납세의무자가 과세표준과 세액의 신고를 하지 아니하거나 신고한 과세표준과 세액이 세법에서 정하는 바와 맞지 아니한 경우에는 정부가 과세표준과 세액을 결정하거나 경정하는 때에 그 결정 또는 경정에 따라 확정된다. 1. 소득세"}],"선지":[{"번호":1,"판정":"틀림","설명":"기납부 확정신고세액이 총결정세액을 초과하면 그 초과액을 환급하거나 다른 국세 및 강제징수비에 충당하여야 한다(소득세법 제117조)."},{"번호":2,"판정":"옳음","설명":"총결정세액이 예정·확정신고납부세액 등의 합계를 초과하면 초과분을 해당 거주자에게 알린 날부터 30일 이내에 징수한다(소득세법 제116조제2항)."},{"번호":3,"판정":"틀림","설명":"부담부증여의 채무액 해당 부분은 양도일이 속하는 달의 말일부터 3개월 이내에 예정신고를 해야 한다(소득세법 제105조제1항제3호)."},{"번호":4,"판정":"틀림","설명":"소득세는 납세의무자가 과세표준과 세액을 신고한 때 확정된다. 신고를 하지 않았거나 신고 내용이 세법과 맞지 않을 때 정부의 결정·경정으로 확정된다(국세기본법 제22조제2항)."},{"번호":5,"판정":"틀림","설명":"소득세법 제117조는 초과세액의 환급 또는 충당만 정하고 결정일부터 90일 이내라는 기한은 두지 않는다(소득세법 제117조)."}],"개념":[{"종류":"흐름","제목":"양도소득세 신고·결정·징수·환급 절차","단계":[{"이름":"예정신고·납부","설명":"양도일이 속하는 달의 말일부터 2개월 이내(부담부증여의 채무액 해당 부분은 3개월). 양도차익이 없거나 양도차손이어도 신고한다."},{"이름":"확정신고·납부","설명":"다음 연도 5월 1일부터 5월 31일까지. 예정신고를 한 자는 확정신고를 생략할 수 있다. 다만 누진세율 자산에 대한 예정신고를 2회 이상 한 경우 등은 확정신고를 해야 한다."},{"이름":"결정·경정","설명":"신고를 하지 않으면 결정, 신고 내용에 탈루·오류가 있으면 경정한다. 결과는 거주자에게 서면으로 알린다."},{"이름":"추가 징수","설명":"총결정세액이 기납부세액(예정·확정신고납부, 수시부과, 징수된 세액 등)의 합계를 초과하면 초과분을 알린 날부터 30일 이내에 징수한다."},{"이름":"환급·충당","설명":"기납부세액 합계가 총결정세액을 초과하면 그 초과분을 환급하거나 다른 국세 및 강제징수비에 충당한다."}]},{"종류":"표","제목":"국세 납세의무의 확정 방식(국세기본법 제22조)","머리":["확정 방식","해당 국세","확정 시기"],"행":[["신고로 확정","소득세(양도소득세 포함), 법인세, 부가가치세, 개별소비세, 주세, 증권거래세, 교육세, 교통ㆍ에너지ㆍ환경세","납세의무자가 신고한 때. 미신고·신고 오류는 정부의 결정·경정 때"],["신고로 확정(선택)","종합부동산세","제16조제3항에 따라 신고한 때에 한함"],["정부 결정으로 확정","상속세, 증여세 등 위 목록 외의 국세","정부가 과세표준과 세액을 결정하는 때"],["성립과 동시에 확정","인지세, 원천징수 소득세·법인세, 납세조합 징수 소득세 등","납세의무 성립 때"]]}],"함정":"4번의 확정 방식은 신고납세와 부과과세의 구별 문제다. 소득세는 신고로 확정되고 상속세·증여세는 정부 결정으로 확정된다. 3번은 부담부증여도 예정신고 대상이라는 점을 놓친 선지로, 기한이 일반 양도보다 1개월 긴 3개월이라는 차이만 따로 붙는다. 1번은 환급과 충당이 둘 다 가능하다는 점, 5번은 90일 같은 숫자가 법에 없다는 점이 포인트다."}},{"i":"S3-2-2-세법-16","r":"S3","g":3,"c":2,"n":40,"s":"세법","q":"소득세법령상 거주자의 부동산과 관련된 사업소득에 관한 설명으로 옳은 것은?","b":null,"bs":"없음","img":[],"ch":["해당 과세기간의 종합소득금액이 있는 거주자(종합소득과세표준이 없거나 결손금이 있는 거주자를 포함한다)는 그 종합소득 과세표준을 그 과세기간의 다음 연도 5월 1일부터 5월 31일까지 대통령령으로 정하는 바에 따라 납세지 관할 세무서장에게 신고하여야 하며, 해당 과세기간에 분리과세 주택임대소득이 있는 경우에도 이를 적용한다.","공장재단을 대여하는 사업은 부동산임대업에 해당되지 않는다.","해당 과세기간의 주거용 건물 임대업을 제외한 부동산임대업에서 발생한 결손금은 그 과세기간의 종합소득과세표준을 계산할 때 공제한다.","｢공익사업을 위한 토지 등의 취득 및 보상에 관한 법률｣제4조에 따른 공익사업과 관련하여 지역권을 설정함으로써 발생하는 소득은 부동산업에서 발생하는 소득에 해당한다.","사업소득에 부동산임대업에서 발생한 소득이 포함되어 있는 사업자는 그 소득별로 구분하지 않고 회계처리하여야 한다."],"a":[1],"L":"세3-3","o":"기출","x":{"한줄":"분리과세 주택임대소득만 있어도 종합소득 과세표준을 다음 연도 5월 1일부터 5월 31일까지 신고해야 한다.","근거":[{"법령":"소득세법","조문":"제70조제1항·제2항","원문":"① 해당 과세기간의 종합소득금액이 있는 거주자(종합소득과세표준이 없거나 결손금이 있는 거주자를 포함한다)는 그 종합소득 과세표준을 그 과세기간의 다음 연도 5월 1일부터 5월 31일까지 대통령령으로 정하는 바에 따라 납세지 관할 세무서장에게 신고하여야 한다. ② 해당 과세기간에 분리과세 주택임대소득 및 제127조제1항제6호나목의 소득이 있는 경우에도 제1항을 적용한다."},{"법령":"소득세법","조문":"제45조제2항","원문":"② 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 사업(이하 \"부동산임대업\"이라 한다)에서 발생한 결손금은 종합소득 과세표준을 계산할 때 공제하지 아니한다. 다만, 주거용 건물 임대업의 경우에는 그러하지 아니하다. 1. 부동산 또는 부동산상의 권리를 대여하는 사업 2. 공장재단 또는 광업재단을 대여하는 사업 3. 채굴에 관한 권리를 대여하는 사업으로서 대통령령으로 정하는 사업"},{"법령":"소득세법","조문":"제19조제1항제12호","원문":"12. 부동산업에서 발생하는 소득. 다만, 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」 제4조에 따른 공익사업과 관련하여 지역권ㆍ지상권(지하 또는 공중에 설정된 권리를 포함한다)을 설정하거나 대여함으로써 발생하는 소득은 제외한다."},{"법령":"소득세법","조문":"제21조제1항제9호","원문":"9. 「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률」 제4조에 따른 공익사업과 관련하여 지역권ㆍ지상권(지하 또는 공중에 설정된 권리를 포함한다)을 설정하거나 대여함으로써 발생하는 소득"},{"법령":"소득세법","조문":"제160조제4항","원문":"④ 제1항이나 제2항의 경우에 사업소득에 부동산임대업에서 발생한 소득이 포함되어 있는 사업자는 그 소득별로 구분하여 회계처리하여야 한다. 이 경우에 소득별로 구분할 수 없는 공통수입금액과 그 공통수입금액에 대응하는 공통경비는 각 총수입금액에 비례하여 그 금액을 나누어 장부에 기록한다."}],"선지":[{"번호":1,"판정":"옳음","설명":"종합소득금액이 있는 거주자는 다음 연도 5월 1일~5월 31일에 신고한다. 분리과세 주택임대소득이 있는 경우에도 같다(소득세법 제70조제1항·제2항)."},{"번호":2,"판정":"틀림","설명":"공장재단 또는 광업재단을 대여하는 사업도 부동산임대업에 해당한다(소득세법 제45조제2항제2호)."},{"번호":3,"판정":"틀림","설명":"주거용 건물 임대업을 제외한 부동산임대업의 결손금은 종합소득 과세표준을 계산할 때 공제하지 않는다. 주거용 건물 임대업만 공제한다(소득세법 제45조제2항)."},{"번호":4,"판정":"틀림","설명":"공익사업과 관련해 지역권·지상권을 설정하거나 대여해 얻는 소득은 부동산업 사업소득에서 제외한다. 기타소득으로 본다(소득세법 제19조제1항제12호 단서, 제21조제1항제9호)."},{"번호":5,"판정":"틀림","설명":"부동산임대업 소득이 포함된 사업자는 그 소득별로 구분하여 회계처리해야 한다. 공통수입금액과 공통경비는 총수입금액에 비례해 나눈다(소득세법 제160조제4항)."}],"개념":[{"종류":"표","제목":"주택임대소득 과세(소득세법)","머리":["항목","내용","근거"],"행":[["비과세","1개의 주택을 소유하는 자의 주택임대소득. 기준시가 12억원 초과 주택과 국외 주택은 제외","제12조제2호나목"],["분리과세 대상","해당 과세기간 주택임대 총수입금액 합계가 2천만원 이하인 자의 주택임대소득","제14조제3항제7호"],["분리과세 세액","사업소득금액 × 100분의 14. 종합과세한 세액과 비교해 선택","제64조의2제1항"],["필요경비","총수입금액의 100분의 50(대통령령으로 정하는 임대주택은 100분의 60)","제64조의2제2항"],["추가 차감","분리과세 주택임대소득을 뺀 종합소득금액이 2천만원 이하이면 200만원(대통령령으로 정하는 임대주택은 400만원)","제64조의2제2항"],["신고","분리과세 주택임대소득만 있어도 다음 연도 5월 1일~5월 31일 신고","제70조제2항"],["보증금등 간주임대료","3주택 이상 소유 + 보증금등 합계 3억원 초과이면 총수입금액에 산입","제25조제1항제1호"]]},{"종류":"계산","제목":"분리과세 주택임대소득의 세액(가정: 연 총수입금액 1,800만원, 일반 임대주택)","단계":[{"설명":"분리과세 주택임대소득을 뺀 종합소득금액이 2천만원 초과: 필요경비 50%만 차감","식":"1,800만원 − 1,800만원 × 50%","값":"사업소득금액 900만원"},{"설명":"세액 = 사업소득금액 × 100분의 14","식":"900만원 × 14%","값":"126만원"},{"설명":"종합소득금액이 2천만원 이하이면 추가로 200만원 차감","식":"1,800만원 − 900만원 − 200만원","값":"사업소득금액 700만원"},{"설명":"세액 = 사업소득금액 × 100분의 14","식":"700만원 × 14%","값":"98만원"}]}],"함정":"3번은 주거용 건물 임대업과 그 밖의 부동산임대업의 결손금 처리를 뒤바꾼 선지다. 상가·토지 임대업의 결손금은 종합소득에서 공제하지 않고 이월해 부동산임대업 소득금액에서만 뺀다. 2번은 공장재단·광업재단 대여가 부동산임대업에 포함된다는 규정을 놓친 선지다. 4번은 공익사업 지역권 소득이 사업소득이 아니라 기타소득이라는 점이 관건이다. 1번은 분리과세라서 신고를 생략한다고 오해하기 쉬운데, 분리과세 주택임대소득도 확정신고 대상이다."}}];